/*
 * MLX91219 Hall-Effect Current Sensor Reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADS1115 SDA -> GPIO2 (BCM)
 *   ADS1115 SCL -> GPIO3 (BCM)
 *   ADS1115 ADDR -> GND (physical pin 1)
 *   ADS1115 VDD -> 3.3 V
 *   ADS1115 GND -> GND
 *   MLX91219 VDD -> 3.3 V
 *   MLX91219 GND -> GND
 *   MLX91219 VOUT -> ADS1115 AIN0
 *   MLX91219 GND -> ADS1115 GND
 *
 * Build: gcc -O2 -Wall -o mlx91219_reader mlx91219_reader.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <errno.h>
#include <string.h>
#include <math.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG    0x01

#define ADS1115_MUX_SINGLE_ENDED 0x8000
#define ADS1115_PGA_4_096V       0x4000
#define ADS1115_MODE_SINGLE_SHOT  0x0001
#define ADS1115_DR_128SPS        0x0080

#define SAMPLE_INTERVAL_US 500000
#define MAX_RETRIES 3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a single byte to an ADS1115 register */
static int ads1115_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit big-endian value from an ADS1115 register */
static int ads1115_read_reg(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* Read a single 16-bit conversion from the ADS1115 */
static int ads1115_read_conversion(int fd, int16_t *out)
{
    uint16_t raw;
    if (ads1115_read_reg(fd, ADS1115_REG_CONVERSION, &raw) < 0)
        return -1;
    *out = (int16_t)raw;
    return 0;
}

/* Convert raw ADC value to current in amperes */
static double convert_to_current(int16_t raw)
{
    double voltage = (double)raw / 32768.0;
    return (voltage / 4.096) * 1000.0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                ADS1115_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Configure ADS1115: single-shot, AIN0 single-ended, +/-4.096V, 128 SPS */
    uint8_t config[3];
    config[0] = ADS1115_MUX_SINGLE_ENDED | ADS1115_PGA_4_096V;
    config[1] = ADS1115_MODE_SINGLE_SHOT | ADS1115_DR_128SPS;
    config[2] = 0x00;

    if (ads1115_write_reg(g_i2c_fd, ADS1115_REG_CONFIG, config[0]) < 0) {
        fprintf(stderr, "Failed to configure ADS1115\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Allow the conversion to complete */
    usleep(10000);

    printf("MLX91219 current sensor reader started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int16_t raw;
        if (ads1115_read_conversion(g_i2c_fd, &raw) < 0) {
            fprintf(stderr, "Failed to read current sensor data\n");
            break;
        }

        double current = convert_to_current(raw);
        printf("Current: %.2f A\n", current);

        if (current < 0.0) {
            fprintf(stderr, "Sensor read error, retrying...\n");
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

