/*
 * Flame Sensor Monitoring with MCP3008 ADC
 * Board:  Raspberry Pi 3 Model B+
 * Sensor: AZDelivery KY-026 Flame Sensor Module
 * ADC:    MCP3008 on SPI0, CH0 (single-ended), CE0 (GPIO8)
 * Log:    flame_data.csv
 *
 * Build:  gcc -O2 -Wall -o flame_monitor flame_monitor.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0
#define SPI_CS_PIN      8
#define ADC_CHANNEL     0
#define ADC_MAX_VALUE   1023.0f
#define LOG_FILE        "flame_data.csv"
#define SAMPLE_INTERVAL 1.0

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                          (start bit)
 *   tx[1] = (0x08 | channel) << 4          (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                          (clock out remaining bits)
 * Result: 10-bit value in rx[1] and rx[2].
 */
static int mcp3008_read(int fd, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)(0x08 | (channel << 4)), 0x00 };
    unsigned char rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int value = ((rx[1] & 0x03) << 8) | rx[2];
    return value;
}

static float calculate_temperature(int adc_value)
{
    if (adc_value < 0 || adc_value > ADC_MAX_VALUE) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return -1.0f;
    }
    return (float)adc_value / ADC_MAX_VALUE * 100.0f;
}

static int log_data(float temperature, int flame_detected)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%.2f,%d\n", timestamp, temperature, flame_detected) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open SPI device */
    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device '%s': %s\n",
                SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Configure SPI mode */
    unsigned char mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    /* Configure SPI bits per word */
    unsigned char bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    /* Configure SPI max speed */
    unsigned char speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    /* Open ADC device */
    int adc_fd = open(SPI_DEVICE, O_RDWR);
    if (adc_fd < 0) {
        fprintf(stderr, "Error opening ADC device '%s': %s\n",
                SPI_DEVICE, strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    /* Configure ADC channel */
    if (ioctl(adc_fd, SPI_IOC_WR_CHIP_SELECT_LINE, &SPI_CS_PIN) < 0) {
        fprintf(stderr, "Error setting ADC channel: %s\n", strerror(errno));
        close(adc_fd);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_value = mcp3008_read(adc_fd, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error, skipping entry\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        float temperature = calculate_temperature(adc_value);
        if (temperature < 0.0f) {
            fprintf(stderr, "Temperature calculation error, skipping entry\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        int flame_detected = (temperature < 100.0f) ? 1 : 0;

        if (log_data(temperature, flame_detected) != 0) {
            fprintf(stderr, "Logging failed, skipping entry\n");
        }

        printf("Flame detected: %s\n", flame_detected ? "Yes" : "No");
        sleep(SAMPLE_INTERVAL);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    close(spi_fd);
    close(adc_fd);
    printf("Resources released. Exiting.\n");
    return EXIT_SUCCESS;
}

