    fprintf(fp, "%s, Current: %.2f A\n", timestamp, current);
    fclose(fp);
}

static void control_fan(float current) {
    if (current > threshold) {
        gpiod_line_set_value(fan_line, 1);
    } else {
        gpiod_line_set_value(fan_line, 0);
    }
}

static void cleanup(void) {
    if (fan_line) {
        gpiod_line_set_value(fan_line, 0);
        gpiod_line_release(fan_line);
        fan_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

