        fprintf(stderr, "Error setting signal handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        cleanup();
        return 1;
    }

    fan_line = gpiod_chip_get_line(chip, FAN_GPIO_LINE);
    if (!fan_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", FAN_GPIO_LINE, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(fan_line, "fan_control", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = spi_read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error, retrying...\n");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        float current = adc_to_current(adc_value);
        log_current(current);
        control_fan(current);

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

