/*
 * flame_sensor.c
 *
 * Raspberry Pi 3 Model B+
 * AZDelivery KY-026 Flame Sensor Module + MCP3008 ADC
 *
 * Wiring:
 *   KY-026 VCC  -> 3.3 V (Pin 1)
 *   KY-026 GND  -> GND  (Pin 6)
 *   KY-026 DO   -> MCP3008 CH0 (Pin 9)
 *   MCP3008 SCLK -> GPIO11 (Pin 23)
 *   MCP3008 DOUT -> GPIO10 (Pin 21)
 *   MCP3008 DIN  -> GPIO9  (Pin 19)
 *   MCP3008 CS   -> GPIO8  (Pin 24)
 *   MCP3008 VDD  -> 3.3 V
 *   MCP3008 AGND -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o flame_sensor flame_sensor.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0
#define FLAME_GPIO      4
#define MCP3008_CHANNEL 0
#define LOG_FILE        "flame_data.csv"
#define SAMPLE_INTERVAL 1

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0–1023 on success, -1 on error.
 */
static int mcp3008_read(int fd, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read sequence (3 bytes):
     *   tx[0] = 0x01  (start bit)
     *   tx[1] = (0x08 | channel) << 4  (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00  (clock out remaining bits)
     *
     * Response:
     *   rx[0] = low 2 bits of result
     *   rx[1] = high 2 bits of result
     *   rx[2] = don't care
     */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
