/*
 * MICS-4514 Dual CO/NO2 Sensor Reader for Raspberry Pi 4 Model B
 *
 * Reads the four-byte response from the MICS-4514 sensor over I2C,
 * extracts the two 16-bit ADC readings (OX for CO and RED for NO2),
 * and calculates the CO concentration in parts per million (ppm).
 *
 * Build: gcc -O2 -Wall -o mics_reader mics_reader.c
 * Run:   sudo ./mics_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MICS_SENSOR_ADDR 0x5A
#define CO_THRESHOLD_PPM 25.0f
#define LOG_FILE       "co_log.txt"
#define ALERT_LOG_FILE "alert_log.txt"
#define READ_INTERVAL_S 5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read the four-byte response from the MICS-4514 sensor.
 * Returns 0 on success, -1 on I2C error.
 */
static int read_sensor_data(int i2c_fd, uint16_t *co_ppm, uint16_t *no2_ppm)
{
    uint8_t buf[4];
    ssize_t n;

    /*
     * The MICS-4514 sends a 4-byte response:
     *   [OX_MSB, OX_LSB, RED_MSB, RED_LSB]
     * Each byte is 2 bits, so the total data is 8 bits.
     */
    n = read(i2c_fd, buf, 4);
    if (n != 4) {
        fprintf(stderr, "I2C read error: expected 4 bytes, got %zd\n", n);
        return -1;
    }

    /*
     * The MICS-4514 sends the data in little-endian format.
     * The MSB of each byte is the most significant bit.
     */
    *co_ppm = ((uint16_t)buf[0] << 8) | (uint16_t)buf[1];
    *no2_ppm = ((uint16_t)buf[2] << 8) | (uint16_t)buf[3];

    return 0;
}

/*
 * Convert the CO ADC reading to a CO concentration in parts per million.
 * The MICS-4514 has a linear relationship between the ADC value and
 * the CO concentration. The conversion factor is approximately
 * 0.01 ppm per LSB.
 */
static float calculate_co_ppm(uint16_t co_adc)
{
    return (float)co_adc * 0.01f;
}

/*
 * Append the CO concentration to the log file.
 * Returns 0 on success, -1 on I/O error.
 */
static int log_co_ppm(float co_ppm)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s CO: %.2f ppm\n", ts, co_ppm);
    } else {
        fprintf(fp, "Error: localtime_r failed\n");
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Append an alert entry to the alert log file.
 * Returns 0 on success, -1 on I/O error.
 */
static int log_alert(float co_ppm)
{
    FILE *fp = fopen(ALERT_LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening alert log file '%s': %s\n",
                ALERT_LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s CO: %.2f ppm (ALERT)\n", ts, co_ppm);
    } else {
        fprintf(fp, "Error: localtime_r failed\n");
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing alert log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    int i2c_fd = -1;
    uint16_t co_ppm = 0;
    uint16_t no2_ppm = 0;
    int ret = EXIT_FAILURE;

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not register SIGINT handler: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not register SIGTERM handler: %s\n",
                strerror(errno));
    }

    /* Open the I2C bus */
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus '%s': %s\n",
                I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the MICS-4514 sensor address */
    if (ioctl(i2c_fd, I2C_SLAVE, MICS_SENSOR_ADDR) < 0) {
        fprintf(stderr, "Error acquiring I2C bus access to address 0x%02X: %s\n",
                MICS_SENSOR_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Main loop */
    while (g_running) {
        if (read_sensor_data(i2c_fd, &co_ppm, &no2_ppm) == 0) {
            float co_ppm_ppm = calculate_co_ppm(co_ppm);
            if (log_co_ppm(co_ppm_ppm) == 0) {
                if (co_ppm_ppm > CO_THRESHOLD_PPM) {
                    if (log_alert(co_ppm_ppm) == 0) {
                        printf("CO: %.2f ppm (ALERT)\n", co_ppm_ppm);
                    }
                }
            } else {
                fprintf(stderr, "Error logging CO ppm\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < READ_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return ret;
}

