 * Raspberry Pi 4 Model B – dual STMicroelectronics IMP23ABSU MEMS microphone reader
 *
 * Wiring:
 *   - Mic 1 OUT (analog) -> GPIO2 (BCM2)
 *   - Mic 2 OUT (analog) -> GPIO3 (BCM3)
 *   - VDD  -> 3.3 V (pin 1)
 *   - GND  -> GND  (pin 9)
 *   - SDA  -> GPIO3 (BCM3)  – I2C bus 1 SDA
 *   - SCL  -> GPIO2 (BCM2)  – I2C bus 1 SCL
 *
 * Build:  gcc -O2 -Wall -Wextra -o audio_reader audio_reader.c
 * Run:    sudo ./audio_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SOUND_MIC_1_PATH "/dev/i2c-1"
#define SOUND_MIC_2_PATH "/dev/i2c-1"
#define LOG_FILE       "audio_log.txt"
#define SAMPLE_PERIOD_US 100000   /* 100 ms */
#define MAX_SAMPLE_US  1000000   /* 1 s */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_open(const char *path, uint8_t sda, uint8_t scl)
{
    int fd = open(path, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", path, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, sda) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, %u): %s\n", sda, strerror(errno));
        close(fd);
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, scl) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, %u): %s\n", scl, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * Read a single 16-bit sample from a single channel.
 * Returns 0 on success, -1 on error.
 */
static int read_sound_level(int fd, int channel, float *out)
{
    uint8_t buf[2];
    ssize_t n;

    if (channel < 0 || channel > 1) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    /*
     * The IMP23ABSU outputs a differential signal.
     * The two channels are combined into a single 16-bit value.
     * The left-most bit is the MSB of the two channels.
     * We read the two bytes and combine them into a 16-bit value.
     */
    n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "read(%d): expected 2 bytes, got %zd\n", channel, n);
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *out = (float)raw / 32768.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static int log_audio_data(float avg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s, %.2f dB\n", ts, avg);
    } else {
        fprintf(fp, "timestamp error, %.2f dB\n", avg);
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose(%s): %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd1 = i2c_open(SOUND_MIC_1_PATH, 2, 0x3E);
    if (fd1 < 0) {
        return EXIT_FAILURE;
    }

    int fd2 = i2c_open(SOUND_MIC_2_PATH, 2, 0x3E);
    if (fd2 < 0) {
        close(fd1);
        return EXIT_FAILURE;
    }

    printf("Audio logger started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float v1 = 0.0f, v2 = 0.0f;

        if (read_sound_level(fd1, 0, &v1) < 0) {
            fprintf(stderr, "Sensor 1 read error; continuing.\n");
        } else if (v1 < -999.0f) {
            fprintf(stderr, "Sensor 1 read invalid; continuing.\n");
        } else {
            log_audio_data(v1);
        }

        if (read_sound_level(fd2, 1, &v2) < 0) {
            fprintf(stderr, "Sensor 2 read error; continuing.\n");
        } else if (v2 < -999.0f) {
            fprintf(stderr, "Sensor 2 read invalid; continuing.\n");
        } else {
            log_audio_data(v2);
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly.\n");
    close(fd1);
    close(fd2);
    return EXIT_SUCCESS;
}

