/*
 * ADMP401 MEMS Microphone Audio Sampler for Raspberry Pi 4 Model B
 *
 * Hardware:
 *   - MCP3008 ADC on SPI0:
 *     - CH0:  BCM GPIO8 (MISO)
 *     - CH1:  BCM GPIO9 (MISO)
 *     - CH2:  BCM GPIO10 (MISO)
 *     - VDD:  3.3 V
 *     - GND:  GND
 *   - LED on GPIO27 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -o audio_sampler audio_sampler.c -lm
 *
 * Run:
 *   ./audio_sampler
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define SPI_DEVICE        "/dev/spidev0.0"
#define SPI_SPEED_HZ      1000000U   /* 1 MHz */
#define SPI_BITS          8
#define SPI_MODE          0

#define ADC_CHANNELS      2
#define ADC_CHANNEL_0     0
#define ADC_CHANNEL_1     1

#define LED_PIN           27
#define LED_ON_MS         500
#define SAMPLE_PERIOD_US  1000000U   /* 1 ms */
#define WINDOW_MS         100
#define WINDOW_SAMPLES    (WINDOW_MS * 1000)

#define LOG_FILE          "audio_events.csv"

/* ----------------------------- Globals ----------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static int g_led_on = 0;

/* ----------------------------- Prototypes -------------------------------- */

static void signal_handler(int sig);
static int  init_spi(void);
static int  read_adc(int channel);
static float calculate_rms(int16_t *samples, int num_samples);
static int  log_event(float mic1_rms, float mic2_rms);
static void control_led(int on_ms);
static void cleanup(void);

/* ----------------------------- Signal handler ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- SPI initialization ----------------------------- */

static int init_spi(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

/* ----------------------------- ADC read -------------------------------- */

static int read_adc(int channel)
{
    if (channel < 0 || channel > ADC_CHANNELS - 1) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {
        (uint8_t)((channel & 0x07) << 4),
        0x00,
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/* ----------------------------- RMS calculation -------------------------------- */

static float calculate_rms(int16_t *samples, int num_samples)
{
    float sum_sq = 0.0f;
    for (int i = 0; i < num_samples; i++) {
        sum_sq += (float)samples[i] * (float)samples[i];
    }
    return sqrtf(sum_sq / num_samples);
}

/* ----------------------------- Logging ----------------------------------- */

static int log_event(float mic1_rms, float mic2_rms)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s,%.2f,%.2f\n", ts, mic1_rms, mic2_rms);
    } else {
        fprintf(fp, "ERROR: localtime_r failed\n");
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose(%s): %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

/* ----------------------------- LED control -------------------------------- */

static void control_led(int on_ms)
{
    if (g_led_on) {
        gpioWrite(LED_PIN, 0);
        g_led_on = 0;
        return;
    }
    if (on_ms > 0) {
        gpioWrite(LED_PIN, 1);
        g_led_on = 1;
        gpioDelay(on_ms * 1000);
        gpioWrite(LED_PIN, 0);
    }
}

/* ----------------------------- Cleanup ----------------------------------- */

static void cleanup(void)
{
    if (g_led_on) {
        gpioWrite(LED_PIN, 0);
        g_led_on = 0;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    gpioTerminate();
}

/* ----------------------------- Main --------------------------------------- */

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    if (gpioSetMode(SPI_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", SPI_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioSetMode(SPI_PIN, PI_OUTPUT);

    if (init_spi() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Audio sampler started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_0 = read_adc(ADC_CHANNEL_0);
        int adc_1 = read_adc(ADC_CHANNEL_1);

        if (adc_0 < 0 || adc_1 < 0) {
            fprintf(stderr, "ADC read error; skipping sample\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float mic1_rms = calculate_rms(adc_0, ADC_CHANNEL_0);
        float mic2_rms = calculate_rms(adc_1, ADC_CHANNEL_1);

        if (log_event(mic1_rms, mic2_rms) < 0) {
            fprintf(stderr, "Logging failed; continuing\n");
        }

        control_led(LED_ON_MS);

        gpioDelay(WINDOW_SAMPLES * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

