        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s,%.2f,%.2f\n", ts, mic1_rms, mic2_rms);
    } else {
        fprintf(fp, "ERROR: localtime_r failed\n");
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose(%s): %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

/* ----------------------------- LED control -------------------------------- */

static void control_led(int on_ms)
{
    if (g_led_on) {
        gpioWrite(LED_PIN, 0);
        g_led_on = 0;
        return;
    }
    if (on_ms > 0) {
        gpioWrite(LED_PIN, 1);
        g_led_on = 1;
        gpioDelay(on_ms * 1000);
        gpioWrite(LED_PIN, 0);
    }
}

/* ----------------------------- Cleanup ----------------------------------- */

static void cleanup(void)
{
    if (g_led_on) {
        gpioWrite(LED_PIN, 0);
        g_led_on = 0;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    gpioTerminate();
}

/* ----------------------------- Main --------------------------------------- */

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    if (gpioSetMode(SPI_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", SPI_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioSetMode(SPI_PIN, PI_OUTPUT);

    if (init_spi() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Audio sampler started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_0 = read_adc(ADC_CHANNEL_0);
        int adc_1 = read_adc(ADC_CHANNEL_1);

        if (adc_0 < 0 || adc_1 < 0) {
            fprintf(stderr, "ADC read error; skipping sample\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float mic1_rms = calculate_rms(adc_0, ADC_CHANNEL_0);
        float mic2_rms = calculate_rms(adc_1, ADC_CHANNEL_1);

        if (log_event(mic1_rms, mic2_rms) < 0) {
            fprintf(stderr, "Logging failed; continuing\n");
        }

        control_led(LED_ON_MS);

        gpioDelay(WINDOW_SAMPLES * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

