/*
 * TCS34725 color sensor reader for Raspberry Pi 4 Model B
 * Uses the Adafruit TCS34725 I2C driver on I2C bus 1.
 *
 * Build:  gcc -O2 -Wall -Wextra -o tcs34725_log tcs34725_log.c -lm
 * Run:    ./tcs34725_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define TCS34725_ADDR  0x39
#define TCS34725_REG_ID   0x00
#define TCS34725_REG_CONFIG 0x01
#define TCS34725_REG_DATA  0x03

#define TCS34725_ID_EXPECTED 0x68
#define TCS34725_CONFIG_BASE 0x01

#define LOG_FILENAME "color_log.csv"
#define SAMPLE_INTERVAL_SEC 1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, out, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
/* TCS34725 driver                                                      */
/* ------------------------------------------------------------------ */
static int tcs34725_init(int fd)
{
    uint8_t id = 0;

    if (i2c_read_byte(fd, TCS34725_REG_ID, &id) < 0) {
        fprintf(stderr, "Failed to read TCS34725 ID register.\n");
        return -1;
    }

    if (id != TCS34725_ID_EXPECTED) {
        fprintf(stderr, "TCS34725 ID mismatch: got 0x%02X, expected 0x%02X.\n",
                id, TCS34725_ID_EXPECTED);
        return -1;
    }

    /* Clear register */
    if (i2c_write_byte(fd, TCS34725_REG_CONFIG, TCS34725_CONFIG_BASE) < 0)
        return -1;

    /* Start conversion */
    if (i2c_write_byte(fd, TCS34725_REG_CONFIG, TCS34725_CONFIG_BASE | 0x80) < 0)
        return -1;

    /* Wait for conversion to complete (~3 ms) */
    usleep(3000);

    return 0;
}

static int tcs34725_read_data(int fd, uint16_t *clear, uint16_t *red,
                              uint16_t *green, uint16_t *blue)
{
    uint8_t buf[6];

    if (i2c_read_word(fd, TCS34725_REG_DATA, buf) < 0)
        return -1;

    *clear = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    *red   = (uint16_t)buf[2] | ((uint16_t)buf[3] << 8);
    *green = (uint16_t)buf[4] | ((uint16_t)buf[5] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                         */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, uint16_t clear, uint16_t red,
                    uint16_t green, uint16_t blue)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f,%.2f,%.2f,%.2f\n", ts,
                (double)clear / 65536.0,
                (double)red / 65536.0,
                (double)green / 65536.0,
                (double)blue / 65536.0) < 0) {
        fprintf(stderr, "fprintf to CSV failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                TCS34725_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (tcs34725_init(g_i2c_fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILENAME, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILENAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(stderr, "TCS34725 initialized. Logging to %s every %d s.\n",
            LOG_FILENAME, SAMPLE_INTERVAL_SEC);

    while (g_running) {
        uint16_t clear, red, green, blue;

        if (tcs34725_read_data(g_i2c_fd, &clear, &red, &green, &blue) < 0) {
            fprintf(stderr, "Read failed; continuing.\n");
        } else {
            if (log_data(g_log_fp, clear, red, green, blue) < 0) {
                fprintf(stderr, "Logging failed.\n");
            }
        }

        /* Sleep in 1-second increments so SIGINT is caught promptly. */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    fprintf(stderr, "\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

