/*
 * MLX90817 absolute pressure sensor reader for Raspberry Pi Zero W.
 *
 * Wiring:
 *   MLX90817 SDA -> GPIO2 (I2C bus 1 SDA)
 *   MLX90817 SCL -> GPIO3 (I2C bus 1 SCL)
 *   MLX90817 VDD -> 3.3 V
 *   MLX90817 GND -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o mlx90817_reader mlx90817_reader.c
 *   -lrt -lm
 *
 * Run:
 *   ./mlx90817_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX90817_ADDR  0x50
#define LOG_FILE       "pressure_log.csv"
#define SAMPLE_PERIOD  1
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a 16-bit big-endian register from the MLX90817.
 * Returns 0 on success, -1 on error.
 */
static int read_register(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    ssize_t n;

    /* Write the register address */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    /* Read 2 bytes */
    n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    /* MLX90817 returns big-endian */
    *out = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/*
 * Read the absolute pressure in kPa.
