/*
 * Honeywell MICROceL MCO-S4 CO sensor reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND  (Pin 6)
 *   MCP3008 DGND -> GND  (Pin 6)
 *   MCP3008 CLK  -> GPIO11 (BCM)
 *   MCP3008 DOUT -> GPIO9  (BCM)
 *   MCP3008 DIN  -> GPIO10 (BCM)
 *   MCP3008 CS   -> GPIO8  (BCM)
 *   MCP3008 CH0  -> Sensor analog out (Vin)
 *   MCP3008 AGND -> GND
 *   MCP3008 VREF -> 3.3 V
 *   MCP3008 DGND -> GND
 *   Alarm GPIO4  -> GND (active-low alarm)
 *
 * Build:  gcc -O2 -Wall -Wextra -o co_reader co_reader.c -lpigpio -lrt
 * Run:    sudo ./co_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL        0
#define SPI_BAUD          1000000   /* 1 MHz – well within MCP3008 spec */
#define SPI_FLAGS         0         /* Mode 0, active-low CE */
#define ALARM_GPIO        4
#define VREF              3.3f
#define VOLTAGE_THRESHOLD 2.5f
#define SAMPLE_PERIOD_US  1000000   /* 1 second */
#define LOG_FILE          "co_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MCP3008 single-ended read                                           */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI frame (3 bytes):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  (single-ended + channel)
     *   Byte 2: 0x00  (clock out remaining bits)
     *
     * Response:
     *   rx[0] = (rx[1] & 0x03) << 8 | rx[2]
     *   rx[1] is undefined (pigpio returns 0 on success)
     *   rx[2] is undefined (pigpio returns 0 on success)
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Logging                                                            */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float voltage)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(fp, "%s,Voltage: %.2f V\n", ts, voltage) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed\n");
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                            */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioWrite(ALARM_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI init --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Alarm GPIO init --- */
    if (gpioSetMode(ALARM_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", ALARM_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(ALARM_GPIO, 0);

    /* --- Log file open --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Main loop --- */
    while (g_running) {
        int adc = read_mcp3008(0);
        if (adc < 0) {
            fprintf(stderr, "ADC read failed; retrying in 1 s\n");
            sleep(1);
            continue;
        }

        float voltage = (float)adc * VREF / 1024.0f;

        if (voltage > VOLTAGE_THRESHOLD) {
            gpioWrite(ALARM_GPIO, 1);
            log_data(g_log_fp, voltage);
            printf("Alarm: voltage %.2f V > %.2f V\n", voltage, VOLTAGE_THRESHOLD);
        } else {
            gpioWrite(ALARM_GPIO, 0);
        }

        sleep(SAMPLE_PERIOD_US / 1000);
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

