/*
 * Raspberry Pi 4 Model B – Methane Monitor
 *
 * Hardware:
 *   - Honeywell MICROpeL Model 41000-020 Combustible Gas Sensor (analog)
 *     on MCP3008 ADC channel 0 (SPI0_SCLK, SPI0_MISO, SPI0_MOSI)
 *   - MCP3008 ADC on SPI0, channel 0 (CE0, SCLK, MISO, MOSI)
 *   - Raspberry Pi 3.3 V pin 1 (VREF), Pi ground (DGND/AGND)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o methane_monitor methane_monitor.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0
#define SPI_CS_PIN      8
#define SPI_CS_VALUE    0
#define LOG_FILE        "methane_log.txt"
#define CONCENTRATION_THRESHOLD 1000U
#define SAMPLE_INTERVAL_S 1

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0–1023 on success, -1 on error.
 */
static int read_mcp3008(int fd, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: 3 bytes, MSB-first, clocked out in
     *   {0x01, (0x08 | channel) << 4, 0x00}
     *   => {0x80, (0x08 | channel) << 4, 0x00}
     */
    unsigned char tx[3] = { 0x80, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static void log_data(FILE *fp, int adc_value, const char *sensor_name)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(fp, "%s, %d\n", timestamp, adc_value);
    fflush(fp);
    printf("%s, %d\n", timestamp, adc_value);
}

static void check_leak(int adc_value, const char *sensor_name)
{
    if (adc_value > CONCENTRATION_THRESHOLD) {
        fprintf(stderr, "ALARM: Methane leak detected! Concentration: %d ppm\n",
                adc_value);
        fflush(stderr);
    }
}

int main(void)
{
    int spi_fd = -1;
    int ret = EXIT_FAILURE;

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open SPI device ---- */
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Configure SPI ---- */
    unsigned char mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        goto cleanup;
    }

    unsigned char bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        goto cleanup;
    }

    unsigned char speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* ---- Open log file ---- */
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    /* ---- Main loop ---- */
    while (g_running) {
        int adc_value = read_mcp3008(spi_fd, 0);
        if (adc_value < 0) {
            fprintf(stderr, "SPI read error; continuing\n");
            usleep(SAMPLE_INTERVAL_S * 1000000);
            continue;
        }

        log_data(log_file, adc_value, "MethaneSensor");

        check_leak(adc_value, "MethaneSensor");

        usleep(SAMPLE_INTERVAL_S * 1000000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    return ret;
}

