/*
 * ADXL335 Impact Monitor for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADXL335 VCC  -> 3.3 V (Pin 1)
 *   ADXL335 GND  -> GND  (Pin 6)
 *   ADXL335 CLK  -> GPIO11 (SPI0 SCLK)
 *   ADXL335 DOUT -> GPIO9  (SPI0 MISO)
 *   ADXL335 DIN  -> GPIO10 (SPI0 MOSI)
 *   ADXL335 CS   -> GPIO8  (SPI0 CE0)
 *   ADXL335 XDA  -> MCP3008 CH0
 *   ADXL335 YDA  -> MCP3008 CH1
 *   ADXL335 ZDA  -> MCP3008 CH2
 *
 * Build: gcc -O2 -Wall -o impact_monitor impact_monitor.c -lpigpio -lrt
 * Run:   sudo ./impact_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL        0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED          1000000    /* 1 MHz */
#define SPI_FLAGS          0          /* Mode 0, active-low CE */
#define ADC_CHANNEL_X      0          /* MCP3008 CH0 */
#define ADC_CHANNEL_Y      1          /* MCP3008 CH1 */
#define ADC_CHANNEL_Z      2          /* MCP3008 CH2 */
#define SAMPLE_PERIOD_US   100000     /* 100 Hz */
#define IMPACT_THRESHOLD   1000       /* raw ADC value */
#define LOG_FILE           "impact_log.txt"
#define NUM_SAMPLES        100
#define SAMPLE_DELAY_US    (SAMPLE_PERIOD_US / 1000)

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static FILE *g_log_fp = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static int  init_spi(void);
static int  read_adc(int channel);
static int  log_data(int x, int y, int z);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- SPI initialization ----------------------------- */
static int init_spi(void)
{
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (handle=%d)\n", g_spi_handle);
        return -1;
    }
    return 0;
}

/* ----------------------------- ADC read ----------------------------------- */
static int read_adc(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read: 3-byte transfer
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  (single-ended + channel)
     *   Byte 2: 0x00  (clock out remaining bits)
     * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2]
     */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(g_spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "Error: spiXfer failed\n");
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/* ----------------------------- Logging ----------------------------------- */
static int log_data(int x, int y, int z)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s,%d,%d,%d\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Error: fprintf to log failed\n");
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "Error: fflush failed\n");
        return -1;
    }

    return 0;
}

/* ----------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

/* ----------------------------- Main ------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure SPI0 CE0 (GPIO8) as output, initial low */
    if (gpioSetMode(SPI_CHANNEL, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for SPI channel %d\n", SPI_CHANNEL);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(SPI_CHANNEL, 0);

    /* Initialize SPI */
    if (init_spi() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed\n");
    }

    printf("Impact monitor started. Logging to '%s'. Press Ctrl+C to exit.\n", LOG_FILE);

    /* Main sampling loop */
    while (g_running) {
        int x = read_adc(ADC_CHANNEL_X);
        int y = read_adc(ADC_CHANNEL_Y);
        int z = read_adc(ADC_CHANNEL_Z);

        if (x >= 0 && y >= 0 && z >= 0) {
            if (log_data(x, y, z) != 0) {
                fprintf(stderr, "Warning: log_data failed\n");
            }
        } else {
            fprintf(stderr, "Warning: ADC read failed\n");
        }

        /*
         * Impact detection: if any raw value exceeds the threshold,
         * log a message and set IMPACT_DETECTED.
         */
        if (x > IMPACT_THRESHOLD || y > IMPACT_THRESHOLD || z > IMPACT_THRESHOLD) {
            fprintf(g_log_fp, "IMPACT DETECTED\n");
            fflush(g_log_fp);
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < NUM_SAMPLES && g_running; i++) {
            gpioDelay(SAMPLE_DELAY_US);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

