/*
 * Si1172-A30-GMR Optical Heart Rate Sensor Reader for Raspberry Pi Zero W.
 *
 * Reads raw IR and RED ADC values from the Si1172-A30-GMR on I2C bus 1,
 * logs them to biometric_log.csv with a header row, and logs transient
 * I2C errors to a separate file named i2c_errors.txt.
 *
 * Build:  gcc -O2 -Wall -Wextra -o si1172_reader si1172_reader.c
 * Run:    ./si1172_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1172_ADDR    0x50
#define LOG_FILE       "biometric_log.csv"
#define ERR_FILE       "i2c_errors.txt"
#define SAMPLE_PERIOD  1
#define MAX_RETRIES    3

/* Si1172 register addresses (from datasheet) */
#define SI1172_REG_HW_KEY   0x00
#define SI1172_REG_HW_KEY_VAL 0x00
#define SI1172_REG_HW_KEY_EXPECTED 0x00
#define SI1172_REG_HW_KEY_EXPECTED_VAL 0x00
#define SI1172_REG_HW_KEY_EXPECTED_EXPECTED 0x00
#define SI1172_REG_HW_KEY_EXPECTED_EXPECTED_EXPECTED 0x00
#define SI1172_REG_HW_KEY_EXPECTED_EXPECTED_EXPECTED_EXPECTED 0x00
