/*
 * Raspberry Pi 4 Model B – Honeywell SpiroQuant A+ ES1-005 Mass Flow Sensor
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3008 CH0  -> SpiroQuant A+ analog output
 *
 * Build:  gcc -O2 -Wall -Wextra -o spiroquant spiroquant.c -lpigpio -lrt
 * Run:    sudo ./spiroquant
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL        0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED          1000000    /* 1 MHz – well within MCP3008 spec */
#define SPI_FLAGS          0          /* Mode 0, active-low CE */
#define ADC_CHANNEL        0          /* MCP3008 CH0 */
#define FLOW_MIN           0.0f       /* L/min */
#define FLOW_MAX           5.0f       /* L/min */
#define LOG_FILE           "flow_log.csv"
#define SAMPLE_PERIOD_US   1000000    /* 1 s */
#define ADC_MAX_VALUE      1023       /* 10-bit ADC */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MCP3008 single-ended read                                           */
/* ------------------------------------------------------------------ */
static int mcp3008_read(int spi_handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (clock out remaining bits)
     *
     * Response:
     *   rx[0] bits 1:0 are the 10-bit result (upper 2 bits)
     *   rx[1] bits 7:4 are the null bit (lower 2 bits)
     *   rx[2] is all 8 bits of the result
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Flow rate conversion                                                 */
/* ------------------------------------------------------------------ */
static float adc_to_flow_rate(int adc_value)
{
    if (adc_value < 0)   return FLOW_MIN;
    if (adc_value > ADC_MAX_VALUE) {
        fprintf(stderr, "ADC value %d out of range (sensor absent)\n", adc_value);
        return FLOW_MIN;
    }
