    if (adc_value > ADC_MAX_VALUE) {
        fprintf(stderr, "ADC value %d out of range (sensor absent)\n", adc_value);
        return FLOW_MIN;
    }
    float flow_rate = (float)adc_value / (float)ADC_MAX_VALUE * (FLOW_MAX - FLOW_MIN) + FLOW_MIN;
    return flow_rate;
}

