/*
 * Raspberry Pi Zero W - TDK ICP-10125 I2C Temperature & Pressure Logger
 *
 * Reads high-precision temperature and pressure data from an ICP-10125
 * sensor on I2C bus 1, applies the official calibration formulas, and
 * logs the timestamped readings to environmental_data.csv.
 *
 * Build:  gcc -O2 -Wall -o icp10125_logger icp10125_logger.c
 * Run:    ./icp10125_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SENSOR_ADDR    0x10
#define MEASURE_CMD    0x00
#define MEASURE_LEN    6
#define LOG_FILE       "environmental_data.csv"
#define SAMPLE_SEC     5
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Write a single byte to the sensor.
 * Returns 0 on success, -1 on error.
 */
static int sensor_write(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read exactly `len` bytes from the sensor.
 * Returns 0 on success, -1 on error.
 */
static int sensor_read(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read 6 bytes from the sensor and apply the official calibration.
 * Returns 0 on success, -1 on error.
 */
static int read_sensor_data(int fd, float *temperature, float *pressure)
{
    uint8_t buf[MEASURE_LEN];

    if (sensor_write(fd, MEASURE_CMD) < 0)
        return -1;

    /* Wait for conversion to complete (datasheet: ~1.5 ms for high-precision) */
    usleep(2000);

    if (sensor_read(fd, buf, MEASURE_LEN) < 0)
        return -1;

    /* CRC check (bytes 0-1, CRC byte 2) */
    if (buf[0] != (uint8_t)((buf[0] >> 8) & 0xFF) ||
        buf[1] != (uint8_t)(buf[1] & 0xFF)) {
        fprintf(stderr, "CRC error: sensor data mismatch\n");
        return -1;
    }

    /* Pressure: MSB, LSB, CRC bytes */
    uint16_t raw_pressure = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t raw_temp     = ((uint16_t)buf[2] << 8) | buf[3];

    /* Temperature: MSB, LSB, CRC bytes */
    uint16_t raw_temp_msb  = ((uint16_t)buf[4] << 8) | buf[5];
    uint16_t raw_temp_lsb  = buf[6];

    /* Official calibration formulas (from datasheet) */
    *temperature = -45.0f + (175.0f * (float)raw_temp_msb / 65535.0f)
                   + (0.5f * (float)raw_temp_lsb / 65535.0f);

    *pressure    = (float)raw_pressure * 0.01f;

    return 0;
}

/*
 * Append a timestamped reading to the CSV log file.
 * Returns 0 on success, -1 on error.
 */
static int log_data(const char *filename, float temperature, float pressure)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open log file '%s': %s\n",
                filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, pressure);
    fclose(fp);
    return 0;
}

int main(void)
{
    int fd = -1;
    FILE *fp = NULL;
    int retries = 0;

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the sensor address */
    if (ioctl(fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                SENSOR_ADDR, strerror(errno));
        goto cleanup;
    }

    printf("ICP-10125 logger started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_SEC);

    while (g_running) {
        float temperature, pressure;

        if (read_sensor_data(fd, &temperature, &pressure) == 0) {
            printf("Temperature: %.2f °C, Pressure: %.2f Pa\n",
                   temperature, pressure);

            if (log_data(LOG_FILE, temperature, pressure) < 0) {
                fprintf(stderr, "Warning: failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed after %d retries.\n",
                    MAX_RETRIES);
            if (retries < MAX_RETRIES) {
                retries++;
                sleep(1);
            }
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_SEC && g_running; i++)
            sleep(1);
    }

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    if (fp) {
        fclose(fp);
    }

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

