/*
 * Raspberry Pi 3 Model B+ - Dual MP23ABS1 Analog MEMS Microphone Sampler
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3V (Pin 1)
 *   MCP3008 VREF -> 3.3V (Pin 1)
 *   MCP3008 AGND -> GND  (Pin 6)
 *   MCP3008 DGND -> GND  (Pin 6)
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3008 CH0  -> Mic1
 *   MCP3008 CH1  -> Mic2
 *
 * Build: gcc -O2 -Wall -o mic_sampler mic_sampler.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define NUM_SAMPLES          1024
#define SAMPLE_RATE_HZ      44100
#define SPI_DEVICE          "/dev/spidev0.0"
#define SPI_SPEED_HZ        1000000
#define SPI_BITS_PER_WORD   8
#define ADC_CHANNELS         2
#define NUM_CONSECUTIVE_ERRORS 5

#define SAMPLE_PERIOD_US    (1000000 / SAMPLE_RATE_HZ)
#define SAMPLE_PERIOD_MS    (SAMPLE_PERIOD_US / 1000)

#define NUM_ERRORS          10
#define SAMPLE_PERIOD_SEC   (SAMPLE_PERIOD_MS / 1000)

#define LOG_FILE            "mic_sampler.log"

typedef struct {
    int16_t left;
    int16_t right;
} audio_sample_t;

