#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define ADC_CHANNEL 0
#define BUZZER_GPIO 18
#define LOG_FILE "flame_log.txt"
#define SAMPLE_INTERVAL_MS 500
#define MAX_RETRIES 3
#define DEFAULT_TEMP_FILE "ambient_temp.txt"
#define DEFAULT_FLAME_FILE "flame_detected.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static FILE *temp_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *buzzer_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {
        0x01,
        (unsigned char)((0x08 | channel) << 4),
        0x00
    };
    unsigned char rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    int ret = gpiod_line_set_value(buzzer_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to set buzzer GPIO %d to LOW: %s\n", BUZZER_GPIO, strerror(errno));
        return -1;
    }

    int retries = 0;
    while (retries < MAX_RETRIES) {
        int ret = spi_transfer(&tr);
        if (ret == 3) {
            break;
        }
        retries++;
        if (retries < MAX_RETRIES) {
            usleep(10000);
        }
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Error: SPI transfer failed after %d retries\n", MAX_RETRIES);
        gpiod_line_set_value(buzzer_line, 0);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    gpiod_line_set_value(buzzer_line, 1);
    return adc_value;
}

static float read_temperature(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (temp_file == NULL) {
        temp_file = fopen(DEFAULT_TEMP_FILE, "r");
        if (temp_file == NULL) {
            fprintf(stderr, "Error: Cannot open %s: %s\n", DEFAULT_TEMP_FILE, strerror(errno));
            return -1.0f;
        }
    }

    if (fscanf(temp_file, "%d.%d", &(int)rawtime, &(int)rawtime) != 2) {
        fprintf(stderr, "Error: Failed to read temperature from %s\n", DEFAULT_TEMP_FILE);
        return -1.0f;
    }

    float temp = (float)rawtime / 10.0f;
    if (temp < -50.0f || temp > 150.0f) {
        fprintf(stderr, "Warning: Temperature out of range: %.2f\n", temp);
        return -1.0f;
    }
    return temp;
}

static float compensate_voltage(int adc_value) {
    float voltage = (float)adc_value * (float)3.3f / 1024.0f;
    return voltage;
}

static float compensate_temperature(float voltage) {
    float temp = (voltage - 25.0f) / 25.0f;
    return temp;
}

static int log_data(float voltage, float compensated_voltage, float temperature, int flame_detected) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error: Cannot open %s: %s\n", LOG_FILE, strerror(errno));
            return -1;
        }
    }

    if (flame_detected) {
        fprintf(log_file, "%s,%.2f,%.2f,%.2f,%d\n", timestamp, voltage, compensated_voltage, temperature, flame_detected);
    } else {
        fprintf(log_file, "%s,%.2f,%.2f,%.2f,%d\n", timestamp, voltage, compensated_voltage, temperature, flame_detected);
    }

    if (fclose(log_file) != 0) {
        fprintf(stderr, "Error: Failed to close log file: %s\n", strerror(errno));
        return -1;
    }
    log_file = NULL;
    return 0;
}

static void cleanup(void) {
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
        buzzer_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Error: Failed to open gpiochip4: %s\n", strerror(errno));
        return 1;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_GPIO);
    if (!buzzer_line) {
        fprintf(stderr, "Error: Failed to get GPIO %d: %s\n", BUZZER_GPIO, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(buzzer_line, "flame_sensor", 0) < 0) {
        fprintf(stderr, "Error: Failed to request buzzer GPIO %d as output: %s\n", BUZZER_GPIO, strerror(errno));
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value, retrying...\n");
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }

        float voltage = compensate_voltage(adc_value);
        float compensated_voltage = compensate_temperature(voltage);
        float temperature = read_temperature();
        int flame_detected = (temperature < 0.0f);

        if (temperature < 0.0f) {
            fprintf(stderr, "Error: Temperature reading failed, retrying...\n");
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }

        if (log_data(voltage, compensated_voltage, temperature, flame_detected) != 0) {
            fprintf(stderr, "Error: Failed to log data, retrying...\n");
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }

        if (flame_detected) {
            printf("Flame detected!\n");
            gpiod_line_set_value(buzzer_line, 1);
            usleep(100000);
            gpiod_line_set_value(buzzer_line, 0);
        } else {
            gpiod_line_set_value(buzzer_line, 0);
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("Flame sensor monitoring stopped.\n");
    cleanup();
    return 0;
}

