        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error: Cannot open %s: %s\n", LOG_FILE, strerror(errno));
            return -1;
        }
    }

    if (flame_detected) {
        fprintf(log_file, "%s,%.2f,%.2f,%.2f,%d\n", timestamp, voltage, compensated_voltage, temperature, flame_detected);
    } else {
        fprintf(log_file, "%s,%.2f,%.2f,%.2f,%d\n", timestamp, voltage, compensated_voltage, temperature, flame_detected);
    }

    if (fclose(log_file) != 0) {
        fprintf(stderr, "Error: Failed to close log file: %s\n", strerror(errno));
        return -1;
    }
    log_file = NULL;
    return 0;
}

static void cleanup(void) {
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
        buzzer_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Error: Failed to open gpiochip4: %s\n", strerror(errno));
        return 1;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_GPIO);
    if (!buzzer_line) {
        fprintf(stderr, "Error: Failed to get GPIO %d: %s\n", BUZZER_GPIO, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(buzzer_line, "flame_sensor", 0) < 0) {
        fprintf(stderr, "Error: Failed to request buzzer GPIO %d as output: %s\n", BUZZER_GPIO, strerror(errno));
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value, retrying...\n");
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }

        float voltage = compensate_voltage(adc_value);
        float compensated_voltage = compensate_temperature(voltage);
        float temperature = read_temperature();
        int flame_detected = (temperature < 0.0f);

        if (temperature < 0.0f) {
            fprintf(stderr, "Error: Temperature reading failed, retrying...\n");
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }

        if (log_data(voltage, compensated_voltage, temperature, flame_detected) != 0) {
            fprintf(stderr, "Error: Failed to log data, retrying...\n");
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }

        if (flame_detected) {
            printf("Flame detected!\n");
            gpiod_line_set_value(buzzer_line, 1);
            usleep(100000);
            gpiod_line_set_value(buzzer_line, 0);
        } else {
            gpiod_line_set_value(buzzer_line, 0);
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

