/*
 * Raspberry Pi 3 Model B+ – DFRobot Gravity Analog Water Level Sensor
 * ADC – MCP3008 on SPI0, channel 0, CE0 (GPIO 8), MISO (GPIO 9), MOSI (GPIO 10),
 * SCLK (GPIO 11), 1 MHz mode 0.
 *
 * Reads the 10-bit ADC value every 5 s, prints the percentage to stdout,
 * writes the JSON-formatted data to water_levels.json, and maintains a
 * valid JSON array by writing the opening '[' and closing ']' on graceful
 * shutdown.
 *
 * Build:  gcc -O2 -Wall -Wextra -o water_level water_level.c -lpigpio -lrt
 * Run:    sudo ./water_level
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL        0          /* CE0 – GPIO 8 */
#define SPI_BAUD           1000000    /* 1 MHz – mode 0 */
#define SPI_FLAGS          0          /* CPOL=0, CPHA=0 */
#define ADC_CHANNEL        0          /* MCP3008 channel 0 */
#define LED_PIN            17         /* BCM – GPIO 17 */
#define WATER_LEVEL_THRESHOLD_PERCENTAGE  75.0f
#define WATER_LEVEL_THRESHOLD_PERCENTAGE_LOW  70.0f
#define SAMPLE_INTERVAL_S   5
#define JSON_FILENAME       "water_levels.json"

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* JSON helper                                                         */
/* ------------------------------------------------------------------ */
static int json_write_open_array(FILE *fp)
{
    if (fprintf(fp, "[") < 0)
        return -1;
    fflush(fp);
    return 0;
}

static int json_write_entry(FILE *fp, const char *key, float value)
{
    if (fprintf(fp, "\"%s\": %.2f", key, value) < 0)
        return -1;
    fflush(fp);
    return 0;
}

static int json_write_close_array(FILE *fp)
{
    if (fprintf(fp, "]") < 0)
        return -1;
    fflush(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */
static int spi_init(void)
{
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (handle=%d)\n", g_spi_handle);
        return -1;
    }
    return 0;
}

static int spi_read_adc(int channel, uint16_t *out)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: spiXfer returned %d (expected 3)\n", ret);
        return -1;
    }

    *out = ((uint16_t)(uint8_t)rx[1] << 8) | (uint8_t)rx[2];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Water level calculation                                              */
/* ------------------------------------------------------------------ */
static float calculate_water_level(int adc_value)
{
    if (adc_value < 0)
        return -1.0f;
    return 100.0f * (float)adc_value / 1023.0f;
}

/* ------------------------------------------------------------------ */
/* LED control                                                         */
/* ------------------------------------------------------------------ */
static void control_led(int on)
{
    if (gpioWrite(LED_PIN, on ? 1 : 0) < 0)
        fprintf(stderr, "Warning: gpioWrite(%d) failed\n", LED_PIN);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- LED pin init --- */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    control_led(0);

    /* --- SPI init --- */
    if (spi_init() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- JSON file open --- */
    FILE *fp = fopen(JSON_FILENAME, "w");
    if (!fp) {
        fprintf(stderr, "Error: cannot open %s for writing\n", JSON_FILENAME);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Write header if file is empty --- */
    if (fseek(fp, 0, SEEK_END) != 0) {
        fprintf(stderr, "Error: fseek failed\n");
        fclose(fp);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (ftell(fp) == 0) {
        if (json_write_open_array(fp) < 0) {
            fclose(fp);
            spiClose(g_spi_handle);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        fclose(fp);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        int adc_value = 0;
        if (spi_read_adc(ADC_CHANNEL, &adc_value) < 0) {
            fprintf(stderr, "Warning: SPI read failed – skipping this sample\n");
            gpioDelay(SAMPLE_INTERVAL_S * 1000000);
            continue;
        }

        float water_level = calculate_water_level(adc_value);
        if (water_level < 0.0f) {
            fprintf(stderr, "Warning: invalid ADC value – skipping this sample\n");
            gpioDelay(SAMPLE_INTERVAL_S * 1000000);
            continue;
        }

        if (water_level > WATER_LEVEL_THRESHOLD_PERCENTAGE_HIGH) {
            control_led(1);
            printf("[%d] Water level: %.2f%% (above threshold)\n",
                   adc_value, water_level);
        } else if (water_level < WATER_LEVEL_THRESHOLD_PERCENTAGE_LOW) {
            control_led(0);
            printf("[%d] Water level: %.2f%% (below threshold)\n",
                   adc_value, water_level);
        }

        /* Write JSON entry to file */
        if (json_write_entry(fp, "water_level", water_level) < 0) {
            fprintf(stderr, "Warning: JSON write failed – skipping this sample\n");
            gpioDelay(SAMPLE_INTERVAL_S * 1000000);
            continue;
        }

        /* Flush to ensure data is written to disk */
        if (fflush(fp) != 0) {
            fprintf(stderr, "Warning: fflush failed\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++)
            gpioDelay(100000);
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    control_led(0);
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

