/*
 * Raspberry Pi Zero W - Honeywell AWM7300V Mass Airflow Sensor Reader
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3V (Pin 1)
 *   MCP3008 VREF -> 3.3V (Pin 1)
 *   MCP3008 AGND -> GND  (Pin 6)
 *   MCP3008 DGND -> GND  (Pin 6)
 *   MCP3008 CLK  -> GPIO11 (Physical Pin 23)
 *   MCP3008 DOUT -> GPIO9  (Physical Pin 21)
 *   MCP3008 DIN  -> GPIO10 (Physical Pin 19)
 *   MCP3008 CS   -> GPIO8  (Physical Pin 24)
 *   MCP3008 CH0  -> AWM7300V analog output (physical pin 1)
 *
 * Build: gcc -O2 -Wall -o airflow airflow.c -lpigpio -lrt
 * Run:   sudo ./airflow
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL      0          /* SPI0 CE0 */
#define SPI_BAUD         1000000    /* 1 MHz */
#define SPI_FLAGS        0          /* Mode 0, active-low CE */
#define ADC_CHANNEL      0          /* MCP3008 channel 0 */
#define SAMPLE_PERIOD_US 100000    /* 100 ms */
#define LOG_FILE         "airflow_log.csv"

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MCP3008 single-ended read                                           */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (single-ended + channel)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Convert ADC value to liters per minute                             */
/* ------------------------------------------------------------------ */
static double convert_to_lpm(int adc_value)
{
    /*
     * AWM7300V:
     *   Vout = Vdd * (1 - (0.5 * (1 + (Vref / Vout)^2)))
     *   Vout = 3.3V * (1 - (0.5 * (1 + (3.3 / 3.3)^2)))
     *   Vout = 3.3V * (1 - 0.5) = 1.65V
     *   LPM = (Vout - Vref) / Vref * 1000.0
     */
    double vout = 3.3;
    double vref = 3.3;
    double vout_vref = vout / vref;
    double lpm = (vout - vref) / vref * 1000.0;
    return lpm;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped reading to the log file                        */
/* ------------------------------------------------------------------ */
static int log_reading(FILE *fp, double lpm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", timestamp, lpm) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error: fflush failed on log file\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI init --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (handle=%d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Log file init --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open %s for appending\n", LOG_FILE);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "Timestamp,LPM\n");
        fflush(g_log_file);
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    printf("Airflow monitoring started. Logging to %s. Press Ctrl+C to stop.\n",
           LOG_FILE);

    /* --- Main loop --- */
    while (g_running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: ADC read failed; continuing\n");
        } else {
            double lpm = convert_to_lpm(adc_value);
            if (log_reading(g_log_file, lpm) != 0) {
                fprintf(stderr, "Warning: log write failed; continuing\n");
            }
        }

        /* Sleep in 100 ms slices so signals are caught promptly */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

