/*
 * Soil Moisture Monitor for Raspberry Pi Zero W
 *
 * Hardware:
 *   - Raspberry Pi Zero W
 *   - HiLetgo Soil Moisture Sensor (analog resistive)
 *     - VCC -> 3.3 V, GND -> GND, OUT -> MCP3008 CH0
 *   - MCP3008 ADC on SPI bus CE0 (SPI0, GPIO8/9/10/11)
 *     - SPI mode 0, 0x01 channel 0, 500 kHz
 *   - msmtp (pop3s) configured for email alerting
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o soil_monitor soil_monitor.c -lm
 *
 * Run:
 *   ./soil_monitor [spi_channel] [adc_channel] [min_cal] [max_cal] [threshold] [interval] [email_recipient] [msmtp_config_file]
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <mimalloc.h>

#define SPI_DEVICE        "/dev/spidev0.0"
#define SPI_SPEED_HZ      500000
#define SPI_BITS_PER_WORD 8
#define SPI_MODE          0
#define SPI_CS_PIN        0

#define ADC_CHANNEL       0
#define ADC_MAX           1023.0
#define ADC_MIN           0.0

#define MOISTURE_THRESHOLD 30.0
#define LOG_INTERVAL_SEC  60
#define EMAIL_RECIPIENT   "recipient@example.com"
#define EMAIL_CONFIG_FILE "/path/to/msmtp.conf"

#define MAX_ERROR_MSG    256

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static int g_adc_channel = ADC_CHANNEL;
static float g_min_cal = ADC_MIN;
static float g_max_cal = ADC_MAX;
static float g_threshold = MOISTURE_THRESHOLD;
static int g_interval_sec = LOG_INTERVAL_SEC;
static char g_email_recipient[64] = EMAIL_RECIPIENT;
static char g_msmtp_config_file[256] = EMAIL_CONFIG_FILE;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Error: cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    unsigned int speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error: cannot set SPI speed: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    unsigned int bits = SPI_BITS_PER_WORD;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error: cannot set SPI bits per word: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    unsigned int mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error: cannot set SPI mode: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

static int adc_read(int channel)
{
    if (g_spi_fd < 0) {
        fprintf(stderr, "Error: SPI device not initialized\n");
        return -1;
    }

    unsigned char tx[3] = {
        0x01,
        (unsigned char)((channel & 0x07) << 4) | 0x80,
        0x00
    };
    unsigned char rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error: SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float adc_to_moisture(int adc_value)
{
    if (adc_value < g_min_cal || adc_value > g_max_cal) {
        fprintf(stderr, "Warning: ADC value %d out of range [%d, %d]\n",
                adc_value, g_min_cal, g_max_cal);
        return -1.0;
    }
    return ((float)adc_value / (float)ADC_MAX) * 100.0;
}

static int log_data(float moisture)
{
    FILE *fp = fopen(g_email_recipient, "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open %s: %s\n", g_email_recipient, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s, %.2f\n", ts, moisture);
    } else {
        fprintf(fp, "Error: localtime_r failed\n");
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error: fclose failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int send_email_alert(float moisture)
{
    char body[MAX_ERROR_MSG];
    snprintf(body, sizeof(body),
             "Subject: Soil Moisture Alert\n\n"
             "Moisture level below threshold: %.2f%%\n", moisture);

    FILE *fp = fopen(g_msmtp_config_file, "r");
    if (!fp) {
        fprintf(stderr, "Error: cannot open %s: %s\n", g_msmtp_config_file, strerror(errno));
        return -1;
    }

    char config_buf[1024];
    size_t n = fread(config_buf, 1, sizeof(config_buf) - 1, fp);
    fclose(fp);

    if (n == 0) {
        fprintf(stderr, "Error: msmtp config file is empty\n");
        return -1;
    }

    config_buf[n] = '\0';

    int status = system(config_buf);
    if (status == -1) {
        fprintf(stderr, "Error: msmtp command execution failed\n");
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Error: msmtp command exited with status %d\n", status);
        return -1;
    }

    printf("Email alert sent: %s\n", body);
    return 0;
}

int main(int argc, char *argv[])
{
    if (argc < 2) {
        fprintf(stderr, "Usage: %s [spi_channel] [adc_channel] [min_cal] [max_cal] [threshold] [interval_sec] [email_recipient] [msmtp_config_file]\n", argv[0]);
        return EXIT_FAILURE;
    }

    int spi_channel = atoi(argv[1]);
    if (spi_channel < 0 || spi_channel > 7) {
        fprintf(stderr, "Error: invalid SPI channel %d\n", spi_channel);
        return EXIT_FAILURE;
    }

    int adc_channel = atoi(argv[2]);
    if (adc_channel < 0 || adc_channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d\n", adc_channel);
        return EXIT_FAILURE;
    }

    float min_cal = atof(argv[3]);
    float max_cal = atof(argv[4]);
    if (min_cal <= 0.0 || max_cal <= 0.0) {
        fprintf(stderr, "Error: calibration values must be positive\n");
        return EXIT_FAILURE;
    }

    float threshold = atof(argv[5]);
    if (threshold <= 0.0) {
        fprintf(stderr, "Error: threshold must be positive\n");
        return EXIT_FAILURE;
    }

    int interval_sec = atoi(argv[6]);
    if (interval_sec <= 0) {
        fprintf(stderr, "Error: interval must be positive\n");
        return EXIT_FAILURE;
    }

    char *email_recipient = argv[7];
    if (strlen(email_recipient) > 64) {
        fprintf(stderr, "Error: email recipient too long\n");
        return EXIT_FAILURE;
    }

    if (strcmp(email_recipient, EMAIL_RECIPIENT) != 0) {
        fprintf(stderr, "Error: email recipient does not match expected recipient\n");
        return EXIT_FAILURE;
    }

    if (g_msmtp_config_file[0] != '\0') {
        fprintf(stderr, "Error: msmtp config file already exists\n");
        return EXIT_FAILURE;
    }

    if (spi_init() != 0) {
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: cannot install signal handlers: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return EXIT_FAILURE;
    }

    printf("Soil Moisture Monitor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_value = adc_read(adc_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error: ADC read failed, retrying in %d seconds\n", interval_sec);
            sleep(interval_sec);
            continue;
        }

        float moisture = adc_to_moisture(adc_value);
        if (moisture < 0.0) {
            fprintf(stderr, "Warning: ADC conversion failed, skipping log\n");
        } else if (moisture < 0.0) {
            fprintf(stderr, "Warning: moisture below threshold, skipping log\n");
        } else {
            if (log_data(moisture) != 0) {
                fprintf(stderr, "Warning: log data write failed\n");
            }
            if (moisture < threshold) {
                if (send_email_alert(moisture) != 0) {
                    fprintf(stderr, "Warning: email alert failed\n");
                }
            }
        }

        sleep(interval_sec);
    }

    printf("\nShutting down...\n");
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    return EXIT_SUCCESS;
}

