/*
 * Raspberry Pi 4 Model B - MLX90823 Pressure Sensor Reader
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3V (Pin 1)
 *   MCP3008 VREF -> 3.3V (Pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SCLK)
 *   MCP3008 DOUT -> GPIO9  (MISO)
 *   MCP3008 DIN  -> GPIO10 (MOSI)
 *   MCP3008 CS   -> GPIO8  (CE0)
 *   MCP3008 CH0  -> MLX90823 VOUT
 *
 * Build: gcc -O2 -Wall -o mlx90823_reader mlx90823_reader.c -lpigpio -lrt
 * Run:   sudo ./mlx90823_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL        0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED          1000000    /* 1 MHz */
#define SPI_FLAGS          0          /* Mode 0, active-low CE */
#define ADC_CHANNEL        0          /* MCP3008 channel 0 */
#define ADC_MAX_VALUE      1023       /* 10-bit ADC */
#define SAMPLE_INTERVAL_S  1          /* Seconds between readings */
#define LOG_FILE           "mlx90823_log.txt"
#define SENSOR_ABSENT_THRESHOLD_V 3.3f   /* VCC or GND */
#define SENSOR_ABSENT_THRESHOLD_ADC 0.0f  /* ADC value */

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static FILE *g_log_file = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  read_mcp3008(int channel);
static float calculate_pressure(int adc_value);
static void log_data(float pressure);
static void cleanup(void);

/* ----------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- MCP3008 read ----------------------------- */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  (single-ended mode + channel)
     *   Byte 2: 0x00  (don't care, clocks out low 2 bits)
     *
     * Response:
     *   Byte 1: bits 1-0 + 9th bit (don't care)
     *   Byte 2: bits 7-0
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int bytes = spiXfer(g_spi_handle, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", bytes);
        return -1;
    }

    /* 10-bit result: bits 1-0 of rx[1] + 9th bit of rx[2] */
    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ----------------------------- Pressure calculation ----------------------------- */
static float calculate_pressure(int adc_value)
{
    if (adc_value < 0 || adc_value > ADC_MAX_VALUE) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return -1.0f;
    }

    /*
     * MLX90823: Vout = VDD * (1 - (ADC/1023) * VREF)
     * VDD = 3.3V, VREF = 3.3V, ADC = 0..1023
     * Pressure = Vout / (VDD * (1 - (ADC/1023) * VREF))
     */
    float voltage = (float)adc_value * (3.3f / (float)ADC_MAX_VALUE);
    float pressure = voltage / (3.3f * (1.0f - (float)adc_value / (float)ADC_MAX_VALUE));
    return pressure;
}

/* ----------------------------- Logging ---------------------------------- */
static void log_data(float pressure)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    if (fprintf(g_log_file, "%s, Pressure: %.2f V\n", timestamp, pressure) < 0) {
        fprintf(stderr, "Error writing to log file\n");
    }
    fflush(g_log_file);
}

/* ----------------------------- Cleanup ---------------------------------- */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ----------------------------- Main ------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI0 CE0 at 1 MHz, mode 0, active-low */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s'\n", LOG_FILE);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "Timestamp, Pressure (V)\n");
        fflush(g_log_file);
    }

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX90823 pressure reader started. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed; skipping sample\n");
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        float pressure = calculate_pressure(adc_value);
        if (pressure < 0.0f) {
            fprintf(stderr, "Invalid pressure reading; skipping sample\n");
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        log_data(pressure);
        printf("ADC: %4d  Pressure: %.2f V\n", adc_value, pressure);

        sleep(SAMPLE_INTERVAL_S);
    }

    /* Cleanup */
    cleanup();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

