/*
 * Soil Moisture Monitor for Raspberry Pi Zero W
 *
 * Reads the analog output of a generic soil moisture sensor on MCP3008
 * channel 0 via SPI0 (CE0, mode 0, 1 MHz), logs the moisture percentage
 * to the console, and handles SIGINT/SIGTERM for graceful shutdown.
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3008 CH0  -> Sensor analog output
 *
 * Build: gcc -O2 -Wall -o soil_monitor soil_monitor.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0
#define SPI_CS_PIN      8          /* CE0 */
#define SAMPLE_INTERVAL 5          /* seconds */
#define ADC_CHANNEL     0          /* MCP3008 channel 0 */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0–1023 on success, -1 on error.
 */
static int read_mcp3008(int fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %u\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (don't care)
     * Result: rx[1] bits 1–0 are the lower 2 bits of the 10-bit result,
     * rx[2] is the upper 8 bits.
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return -1;
    }
    return adc_value;
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    /*
     * Configure SPI: mode 0, 8 bits, 1 MHz.
     * The MCP3008 requires a 3-byte transfer per channel:
     *   tx[0] = 0x01 (start bit)
     *   tx[1] = (0x08 | channel) << 4 (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00 (don't care)
     */
    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_WR_MODE failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /*
     * Configure CS pin as output, initially low (CE0 active low).
     */
    if (ioctl(fd, SPI_IOC_WR_CS_PIN, &SPI_CS_PIN) < 0) {
        fprintf(stderr, "SPI_WR_CS_PIN failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Soil Moisture Monitor started. Press Ctrl+C to exit.\n");
    printf("Reading MCP3008 channel %d every %d seconds.\n", ADC_CHANNEL, SAMPLE_INTERVAL);

    while (g_running) {
        int adc_value = read_mcp3008(fd, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed; continuing.\n");
        } else {
            int moisture_percent = (adc_value / 1023.0f) * 100.0f;
            if (moisture_percent < 0)   moisture_percent = 0;
            if (moisture_percent > 100) moisture_percent = 100;
            printf("Moisture: %d%%\n", moisture_percent);
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (close(fd) < 0) {
        fprintf(stderr, "Warning: close failed: %s\n", strerror(errno));
    }
    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

