/*
 * Raspberry Pi 5 - MCP3008 ADC via SPI0 (CE0)
 * Four analog sensors (0-3) via MCP3008 single-ended channel.
 * Logs timestamped voltage to environmental_data.csv every second.
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3008 CH0  -> Sensor 0
 *   MCP3008 CH1  -> Sensor 1
 *   MCP3008 CH2  -> Sensor 2
 *   MCP3008 CH3  -> Sensor 3
 *
 * Build: gcc -O2 -Wall -o environmental_data environmental_data.c -lpigpio -lrt
 * Run:   sudo ./environmental_data
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_SENSORS 4
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000  /* 1 MHz */
#define SPI_FLAGS 0        /* Mode 0, active-low CE */
#define LOG_FILE "environmental_data.csv"
#define SAMPLE_INTERVAL_US 1000000 /* 1 second */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */
static int spi_init(void)
{
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (channel %d, speed %d, flags %d)\n",
                SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
        return -1;
    }
    return 0;
}

static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read: 3-byte transfer
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  (single-ended + channel)
     *   Byte 2: 0x00  (clock out remaining bits)
     *
     * Response:
     *   rx[0] = (rx[1] & 0x03) << 8 | rx[2]
     *   rx[1] is undefined (pigpio returns 0 on success)
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: spiXfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, int sensor_number, float voltage)
