/*
 * Soil Moisture Monitor with Hysteresis Pump Control
 * Board:  Raspberry Pi 3 Model B+
 * SPI:    BCM GPIO 10 (MCP3008 CH0), BCM GPIO 9 (MISO), BCM GPIO 11 (SCLK), BCM GPIO 17 (Pump)
 * VH400:  MCP3008 single-ended channel 0
 *
 * Build:  gcc -O2 -Wall -Wextra -o soil_monitor soil_monitor.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_DEVICE        "/dev/spidev0.0"
#define SPI_SPEED_HZ      1000000U   /* 1 MHz */
#define SPI_BITS          8
#define SPI_MODE          0          /* SPI mode 0 (CPOL=0, CPHA=0) */
#define PUMP_GPIO         17
#define MOISTURE_LOW      300
#define MOISTURE_HIGH     600
#define BUFFER_SIZE       20
#define SAMPLE_INTERVAL_S 5
#define SPI_TIMEOUT_US    100000U    /* 100 ms */

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd = -1;
static int  g_pump_state = 0;

/* ----------------------------- Circular Buffer ----------------------------- */
typedef struct {
    time_t  timestamp;
    int      moisture_level;
    int      pump_state;
} moisture_data_t;

static moisture_data_t g_moisture_buffer[BUFFER_SIZE];
static int      g_buffer_index = 0;
static int      g_buffer_count = 0;

/* ----------------------------- Prototypes -------------------------------- */
static void  signal_handler(int sig);
static int   spi_init(void);
static int   spi_transfer(uint8_t *tx, uint8_t *rx, size_t len);
static int   mcp3008_read(int channel);
static void  moisture_data_cb(int level, int pump_state);
static void  log_data(int moisture_level, int pump_state);
static void  cleanup(void);

/* ----------------------------- Signal Handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- SPI Initialization ----------------------------- */
static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

/* ----------------------------- MCP3008 Read ----------------------------- */
static int mcp3008_read(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: bits 9..0 of rx[1] are the 10-bit value.
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/* ----------------------------- Pump Control ----------------------------- */
static void moisture_data_cb(int level, int pump_state)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time(): %s\n", strerror(errno));
        return;
    }

    g_moisture_buffer[g_buffer_index].timestamp = now;
    g_moisture_buffer[g_buffer_index].moisture_level = level;
    g_moisture_buffer[g_buffer_index].pump_state = pump_state;

    g_buffer_index = (g_buffer_index + 1) % BUFFER_SIZE;
    if (g_buffer_count < BUFFER_SIZE)
        g_buffer_count++;

    printf("[%ld] Moisture: %d, Pump: %s\n",
           (long)now, level,
           (g_pump_state == 1) ? "ON" : "OFF");

    if (g_pump_state == 1) {
        if (gpioWrite(PUMP_GPIO, 1) < 0)
            fprintf(stderr, "gpioWrite(PUMP_GPIO, 1): %s\n", strerror(errno));
    } else {
        if (gpioWrite(PUMP_GPIO, 0) < 0)
            fprintf(stderr, "gpioWrite(PUMP_GPIO, 0): %s\n", strerror(errno));
    }

    if (g_buffer_count == BUFFER_SIZE)
        log_data(g_moisture_buffer[0].moisture_level, g_moisture_buffer[0].pump_state);
}

/* ----------------------------- Logging ---------------------------------- */
static void log_data(int moisture_level, int pump_state)
{
    FILE *fp = fopen("moisture_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "fopen(moisture_log.txt): %s\n", strerror(errno));
        return;
    }

    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time(): %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime: buffer too small\n");
        fclose(fp);
        return;
    }

    fprintf(fp, "%s, Moisture: %d, Pump: %s\n",
            ts, moisture_level,
            (pump_state == 1) ? "ON" : "OFF");

    if (fclose(fp) != 0)
        fprintf(stderr, "fclose: %s\n", strerror(errno));
}

/* ----------------------------- Cleanup ---------------------------------- */
static void cleanup(void)
{
    if (g_spi_fd >= 0) {
        (void)spi_transfer(NULL, NULL, 0);
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
}

/* ----------------------------- Main ------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Configure pump GPIO as output */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT): %s\n",
                PUMP_GPIO, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);

    /* Initialize SPI */
    if (spi_init() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Soil Moisture Monitor started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        int level = mcp3008_read(0);
        if (level < 0) {
            fprintf(stderr, "SPI read error; skipping sample.\n");
            gpioDelay(SAMPLE_INTERVAL_S * 1000000L);
            continue;
        }

        moisture_data_cb(level, g_pump_state);

        /* Hysteresis: turn pump off if below threshold */
        if (level < MOISTURE_LOW && g_pump_state == 0) {
            if (gpioWrite(PUMP_GPIO, 0) < 0)
                fprintf(stderr, "gpioWrite(PUMP_GPIO, 0): %s\n", strerror(errno));
        } else if (level > MOISTURE_HIGH && g_pump_state == 1) {
            if (gpioWrite(PUMP_GPIO, 1) < 0)
                fprintf(stderr, "gpioWrite(PUMP_GPIO, 1): %s\n", strerror(errno));
        }

        gpioDelay(SAMPLE_INTERVAL_S * 1000000L);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

