     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: bits 9..0 of rx[1] are the 10-bit value.
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/* ----------------------------- Pump Control ----------------------------- */
static void moisture_data_cb(int level, int pump_state)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time(): %s\n", strerror(errno));
        return;
    }

    g_moisture_buffer[g_buffer_index].timestamp = now;
    g_moisture_buffer[g_buffer_index].moisture_level = level;
    g_moisture_buffer[g_buffer_index].pump_state = pump_state;

    g_buffer_index = (g_buffer_index + 1) % BUFFER_SIZE;
    if (g_buffer_count < BUFFER_SIZE)
        g_buffer_count++;

    printf("[%ld] Moisture: %d, Pump: %s\n",
           (long)now, level,
           (g_pump_state == 1) ? "ON" : "OFF");

    if (g_pump_state == 1) {
        if (gpioWrite(PUMP_GPIO, 1) < 0)
            fprintf(stderr, "gpioWrite(PUMP_GPIO, 1): %s\n", strerror(errno));
    } else {
        if (gpioWrite(PUMP_GPIO, 0) < 0)
            fprintf(stderr, "gpioWrite(PUMP_GPIO, 0): %s\n", strerror(errno));
    }

    if (g_buffer_count == BUFFER_SIZE)
        log_data(g_moisture_buffer[0].moisture_level, g_moisture_buffer[0].pump_state);
}

/* ----------------------------- Logging ---------------------------------- */
static void log_data(int moisture_level, int pump_state)
{
    FILE *fp = fopen("moisture_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "fopen(moisture_log.txt): %s\n", strerror(errno));
        return;
    }

    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time(): %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime: buffer too small\n");
        fclose(fp);
        return;
    }

    fprintf(fp, "%s, Moisture: %d, Pump: %s\n",
            ts, moisture_level,
            (pump_state == 1) ? "ON" : "OFF");

    if (fclose(fp) != 0)
        fprintf(stderr, "fclose: %s\n", strerror(errno));
}

/* ----------------------------- Cleanup ---------------------------------- */
static void cleanup(void)
{
    if (g_spi_fd >= 0) {
        (void)spi_transfer(NULL, NULL, 0);
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
}

/* ----------------------------- Main ------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Configure pump GPIO as output */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT): %s\n",
                PUMP_GPIO, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);

    /* Initialize SPI */
    if (spi_init() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Soil Moisture Monitor started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        int level = mcp3008_read(0);
        if (level < 0) {
            fprintf(stderr, "SPI read error; skipping sample.\n");
            gpioDelay(SAMPLE_INTERVAL_S * 1000000L);
            continue;
        }

        moisture_data_cb(level, g_pump_state);

        /* Hysteresis: turn pump off if below threshold */
        if (level < MOISTURE_LOW && g_pump_state == 0) {
            if (gpioWrite(PUMP_GPIO, 0) < 0)
                fprintf(stderr, "gpioWrite(PUMP_GPIO, 0): %s\n", strerror(errno));
        } else if (level > MOISTURE_HIGH && g_pump_state == 1) {
            if (gpioWrite(PUMP_GPIO, 1) < 0)
                fprintf(stderr, "gpioWrite(PUMP_GPIO, 1): %s\n", strerror(errno));
        }

        gpioDelay(SAMPLE_INTERVAL_S * 1000000L);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

