/*
 * MCP3008 ADC reader for Raspberry Pi Zero W
 * Uses pigpio for SPI and logging.
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (pin 1)
 *   MCP3008 VREF -> 3.3 V (pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3008 CH0  -> ADC0  (channel 0)
 *   MCP3008 CH1  -> ADC1  (channel 1)
 *   MCP3008 CH2  -> ADC2  (channel 2)
 *
 * Build: gcc -Wall -Wextra -O2 -o mcp3008_logger mcp3008_logger.c -lpigpio -lrt
 * Run:   sudo ./mcp3008_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL      0
#define SPI_BAUD         1000000   /* 1 MHz */
#define SPI_FLAGS        0         /* Mode 0, active-low CE */
#define LOG_FILE         "analog_log.csv"
#define SAMPLE_INTERVAL  500       /* microseconds */
#define MAX_CHANNELS     3
#define MAX_READS        10

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a single-ended channel from MCP3008 via SPI                        */
/* Returns 0-1023 on success, -1 on SPI error, -2 on invalid channel.   */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -2;
    }

    /*
     * MCP3008 single-ended read: 3-byte transfer
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: rx[1] bits 1-0 are the lower 2 bits of the 10-bit result
     *         rx[2] bits 7-0 are the upper 8 bits of the 10-bit result
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Log one sample to the CSV file                                      */
/* ------------------------------------------------------------------ */
static int log_data(int channel, int voltage)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s,%d,%.2f\n", timestamp, channel, voltage) < 0) {
        fprintf(stderr, "fprintf to log file failed\n");
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 at 1 MHz, mode 0 --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (returned %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open CSV log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Cannot open %s: ", LOG_FILE);
        perror("");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "Timestamp,Channel,Voltage\n");
        fflush(g_log_file);
    }

    /* --- Register signal handler --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MCP3008 ADC logging started. Logging to %s every %d ms.\n",
           LOG_FILE, SAMPLE_INTERVAL);
    printf("Press Ctrl+C to stop.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        int channels[MAX_CHANNELS] = {0};
        int valid_channels[MAX_CHANNELS] = {0};
        int read_count = 0;

        for (int i = 0; i < MAX_CHANNELS; i++) {
            int adc = read_mcp3008(i);
            if (adc < 0) {
                fprintf(stderr, "SPI read error on channel %d\n", i);
                valid_channels[i] = -1;
            } else {
                valid_channels[i] = i;
                channels[i] = adc;
                read_count++;
            }
        }

        if (read_count == 0) {
            fprintf(stderr, "No valid channels read this cycle.\n");
            gpioDelay(SAMPLE_INTERVAL * 1000000);
            continue;
        }

        for (int i = 0; i < read_count; i++) {
            if (log_data(valid_channels[i], channels[i]) != 0) {
                fprintf(stderr, "Logging failed for channel %d\n",
                        valid_channels[i]);
            }
        }

        gpioDelay(SAMPLE_INTERVAL * 1000000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

