/*
 * Soil Moisture Logger for Raspberry Pi 5
 * Uses shared SPI0 (GPIO10, GPIO9, GPIO11) and separate CS lines.
 * Logs three MCP3008 ADC channels to a CSV file.
 *
 * Build:  gcc -O2 -Wall -o soil_logger soil_logger.c
 * Run:    ./soil_logger   (requires root or gpio group access)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8
#define NUM_SENSORS     3
#define LOG_FILE        "soil_moisture_log.csv"
#define SAMPLE_INTERVAL 5

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0–1023 on success, -1 on error.
 */
static int read_mcp3008(int fd, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: 3-byte transfer.
     * tx[0] = 0x01  (start bit)
     * tx[1] = (0x08 | channel) << 4  (SGL/DIFF=1, D2 D1 D0 = channel)
     * tx[2] = 0x00  (clock out remaining bits)
     * rx[1] bits 1..0 are the 10-bit result
     */
    unsigned char tx[3] = { 0x01, (unsigned char)(0x08 | (channel << 4)), 0x00 };
    unsigned char rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int log_data(FILE *fp, int sensor1, int sensor2, int sensor3)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d\n", ts, sensor1, sensor2, sensor3) < 0) {
        fprintf(stderr, "fprintf() failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    /* --- Signal handling for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open SPI device --- */
    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Configure SPI mode --- */
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    /* --- Manually control CS lines --- */
    if (ioctl(spi_fd, SPI_IOC_WR_CS_SETTING, &NUM_SENSORS) < 0) {
        fprintf(stderr, "SPI_IOC_WR_CS_SETTING failed: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is newly created */
    if (ftell(fp) == 0) {
        fprintf(fp, "timestamp,sensor1,sensor2,sensor3\n");
        fflush(fp);
    }

    /* --- Main sampling loop --- */
    while (g_running) {
        int sensor1 = -1, sensor2 = -1, sensor3 = -1;

        for (int i = 0; i < NUM_SENSORS; i++) {
            int val = read_mcp3008(spi_fd, i);
            if (val < 0) {
                fprintf(stderr, "Sensor %d read failed; skipping\n", i + 1);
                continue;
            }
            sensor1 = val;
            if (log_data(fp, sensor1, sensor2, sensor3) < 0) {
                fprintf(stderr, "Logging failed for sensor %d\n", i + 1);
            }
        }

        for (int i = 0; i < NUM_SENSORS && g_running; i++) {
            int val = sensor1;
            if (log_data(fp, val, sensor2, sensor3) < 0) {
                fprintf(stderr, "Logging failed for sensor %d\n", i + 1);
            }
        }

        sleep(SAMPLE_INTERVAL);
    }

    /* --- Cleanup --- */
    fprintf(stderr, "\nShutting down...\n");
    fclose(fp);
    close(spi_fd);
    return EXIT_SUCCESS;
}

