    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    /* Configure bits per word */
    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    /* Configure speed */
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    printf("Sound level monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_value = read_mcp3008(spi_fd, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error, skipping sample.\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        if (adc_value > THRESHOLD_FACTOR * 1023) {
            log_event(adc_value);
            printf("Sound level: %d\n", adc_value);
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    close(spi_fd);
    return EXIT_SUCCESS;
}

