/*
 * Raspberry Pi Zero W - Vegetronix VH400 Soil Moisture Monitor
 *
 * Reads the Vegetronix VH400 via MCP3008 ADC on SPI0 CE0 (1 MHz, mode 0,
 * channel 0), compares the 10-bit reading to a 300 threshold, and
 * activates a relay-driven water pump on GPIO18 for 10 seconds when
 * the moisture level drops below the threshold.
 *
 * Build:  gcc -O2 -Wall -o vh400_monitor vh400_monitor.c -lpigpio -lrt
 * Run:    sudo ./vh400_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL        0          /* CE0 on SPI0 */
#define SPI_SPEED          1000000    /* 1 MHz */
#define SPI_FLAGS          0          /* mode 0, active-low CE */
#define PUMP_GPIO          18         /* BCM 18, active-high relay */
#define MOISTURE_THRESHOLD 300
#define WATERING_DURATION  10         /* seconds */
#define LOG_FILE           "watering_events.txt"
#define ADC_CHANNEL        0          /* MCP3008 channel 0 */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static int g_pump_active = 0;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(const char *msg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(log)");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    } else {
        fprintf(fp, "[unknown time] %s\n", msg);
    }
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* MCP3008 read                                                        */
/* ------------------------------------------------------------------ */
static int read_adc(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read: 3-byte transfer
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: bits 9..2 in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "spiXfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Relay control                                                       */
/* ------------------------------------------------------------------ */
static void control_pump(int on)
{
    if (on) {
        if (gpioWrite(PUMP_GPIO, 1) != 0) {
            fprintf(stderr, "Failed to activate pump\n");
        }
    } else {
        if (gpioWrite(PUMP_GPIO, 0) != 0) {
            fprintf(stderr, "Failed to deactivate pump\n");
        }
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_pump_active) {
        control_pump(0);
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI init --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- GPIO init --- */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PUMP_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("VH400 soil moisture monitor started. Threshold: %d\n",
           MOISTURE_THRESHOLD);
    printf("Pump on GPIO%d, SPI CE0, 1 MHz, channel 0.\n", PUMP_GPIO);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error; retrying in 1 s\n");
            sleep(1);
            continue;
        }

        /*
         * VH400 output: 0-1023 (10-bit ADC)
         * Threshold: 300
         * Pump on: adc < MOISTURE_THRESHOLD
         */
        if (adc_value < MOISTURE_THRESHOLD) {
            printf("Moisture level: %d (ADC: %d)\n", adc_value, adc_value);
            if (control_pump(1) != 0) {
                fprintf(stderr, "Failed to activate pump\n");
            }
            log_event("Moisture level below threshold");
        } else {
            control_pump(0);
        }

        sleep(60);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

