/*
 * YL-83 Rain Sensor Logger for Raspberry Pi 4 Model B
 *
 * Reads the analog output of a YL-83 rain sensor through an MCP3008 ADC
 * on SPI0 (CE0) at 1 MHz, logs the raw ADC value and intensity level,
 * and prints a timestamped message to stdout.
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3008 CH0  -> YL-83 analog output
 *
 * Build:  gcc -O2 -Wall -o rain_logger rain_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_BITS_PER_WORD 8
#define SPI_MODE        SPI_MODE_0

#define MCP3008_CHANNEL 0
#define ADC_MAX_VALUE   1023.0f
#define SAMPLE_PERIOD_S 1.0f

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0 on success (stores the 10-bit result in *out), -1 on error.
 */
static int mcp3008_read(int fd, uint8_t channel, uint16_t *out)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %u\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: rx[1] bits 1-0 are the lower 2 bits of the 10-bit result,
     * rx[2] bits 7-0 are the upper 8 bits.
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS_PER_WORD;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    *out = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static float adc_to_intensity(uint16_t adc_value)
{
    float voltage = (float)adc_value / (float)ADC_MAX_VALUE * 3.3f;
    return voltage / ADC_MAX_VALUE * 100.0f;
}

int main(void)
{
    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* --- Open SPI device --- */
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return EXIT_FAILURE;
    }

    /* --- Configure SPI --- */
    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(fd);
        return EXIT_FAILURE;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(fd);
        return EXIT_FAILURE;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(fd);
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    FILE *log_file = fopen("rain_log.txt", "a");
    if (!log_file) {
        perror("fopen(rain_log.txt)");
        close(fd);
        return EXIT_FAILURE;
    }

    /* --- Main sampling loop --- */
    while (g_running) {
        uint16_t adc_value = 0;

        if (mcp3008_read(fd, MCP3008_CHANNEL, &adc_value) < 0) {
            fprintf(stderr, "Error reading MCP3008 channel %u\n", MCP3008_CHANNEL);
            /* Log error but continue: next sample will retry. */
        } else {
            float intensity = adc_to_intensity(adc_value);
            time_t rawtime = time(NULL);
            struct tm *timeinfo = localtime(&rawtime);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            fprintf(log_file, "%s, ADC: %u, Intensity: %.2f\n",
                    timestamp, adc_value, intensity);
            fflush(log_file);

            printf("%s, ADC: %u, Intensity: %.2f\n",
                   timestamp, adc_value, intensity);
        }

        /* Sleep in 1-second increments so SIGINT is caught promptly. */
        for (int i = 0; i < SAMPLE_PERIOD_S && g_running; i++)
            sleep(1);
    }

    /* --- Graceful shutdown --- */
    fclose(log_file);
    close(fd);
    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

