    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(fd);
        return EXIT_FAILURE;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(fd);
        return EXIT_FAILURE;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(fd);
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    FILE *log_file = fopen("rain_log.txt", "a");
    if (!log_file) {
        perror("fopen(rain_log.txt)");
        close(fd);
        return EXIT_FAILURE;
    }

    /* --- Main sampling loop --- */
    while (g_running) {
        uint16_t adc_value = 0;

        if (mcp3008_read(fd, MCP3008_CHANNEL, &adc_value) < 0) {
            fprintf(stderr, "Error reading MCP3008 channel %u\n", MCP3008_CHANNEL);
            /* Log error but continue: next sample will retry. */
        } else {
            float intensity = adc_to_intensity(adc_value);
            time_t rawtime = time(NULL);
            struct tm *timeinfo = localtime(&rawtime);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            fprintf(log_file, "%s, ADC: %u, Intensity: %.2f\n",
                    timestamp, adc_value, intensity);
            fflush(log_file);

            printf("%s, ADC: %u, Intensity: %.2f\n",
                   timestamp, adc_value, intensity);
        }

        /* Sleep in 1-second increments so SIGINT is caught promptly. */
        for (int i = 0; i < SAMPLE_PERIOD_S && g_running; i++)
            sleep(1);
    }

    /* --- Graceful shutdown --- */
    fclose(log_file);
    close(fd);
    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

