/*
 * MCP3008 ADC -> PWM motor speed controller for Raspberry Pi.
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3008 CH0  -> Potentiometer (0-1023)
 *   Motor PWM    -> GPIO18 (PWM0 on GPIO18)
 *
 * Build:  gcc -O2 -Wall -o motor_pwm motor_pwm.c -lpigpio -lrt
 * Run:    sudo ./motor_pwm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL        0          /* CE0 on GPIO8 */
#define SPI_SPEED          1000000    /* 1 MHz */
#define SPI_FLAGS          0          /* Mode 0, active-low CE */
#define PWM_FREQUENCY      1000       /* 1 kHz */
#define PWM_RANGE          1023       /* 10-bit PWM */
#define PWM_DUTY_CYCLE     0          /* 0-1023 */
#define PWM_PERIOD_US      1000       /* 1 ms */
#define SAMPLE_DELAY_US    100000     /* 100 ms */
#define ADC_MAX_VALUE      1023       /* MCP3008 10-bit ADC */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0–1023 on success, -1 on SPI error.
 */
static int read_mcp3008(int spi_handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI frame (3 bytes):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  (single-ended + channel)
     *   Byte 2: 0x00  (don't care, clocks out low 2 bits)
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/*
 * Set PWM duty cycle on GPIO18.
 * Returns 0 on success, -1 on error.
 */
static int set_pwm(int pwm_handle, int duty_cycle)
{
    if (duty_cycle < 0 || duty_cycle > PWM_RANGE) {
        fprintf(stderr, "Invalid PWM duty cycle %d\n", duty_cycle);
        return -1;
    }

    if (gpioPWM(pwm_handle, duty_cycle) < 0) {
        fprintf(stderr, "PWM write failed\n");
        return -1;
    }
    return 0;
}

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 at 1 MHz, mode 0 --- */
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- Configure PWM on GPIO18 --- */
    if (gpioSetMode(18, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO18 as output\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(18, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(18, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Start with PWM off --- */
    if (gpioPWM(18, 0) < 0) {
        fprintf(stderr, "Failed to initialize PWM\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MCP3008 ADC -> PWM motor speed controller\n");
    printf("SPI: CE0 on GPIO8, 1 MHz, mode 0, 10-bit ADC\n");
    printf("PWM: GPIO18, %d Hz, %d\n", PWM_FREQUENCY, PWM_RANGE);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        int adc_value = read_mcp3008(spi_handle, 0);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error; retrying in 100 ms\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        int duty_cycle = (adc_value / ADC_MAX_VALUE) * PWM_RANGE;
        if (set_pwm(18, duty_cycle) < 0) {
            fprintf(stderr, "PWM write failed; continuing\n");
        }

        printf("ADC: %4d  PWM: %3d\n", adc_value, duty_cycle);
        fflush(stdout);

        gpioDelay(SAMPLE_DELAY_US);
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    gpioPWM(18, 0);
    spiClose(spi_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

