/*
 * MCP3008 10-bit ADC reader for Raspberry Pi (Pi 3/4, 40-pin header).
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (pin 1)
 *   MCP3008 VREF -> 3.3 V (pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0_SCLK, BCM)
 *   MCP3008 DOUT -> GPIO9  (SPI0_MISO, BCM)
 *   MCP3008 DIN  -> GPIO10 (SPI0_MOSI, BCM)
 *   MCP3008 CS   -> GPIO8  (SPI0_CE0, BCM)
 *
 * SPI mode 0, 1 MHz, MSB-first, active-low CS.
 *
 * Build:  gcc -O2 -Wall -o mcp3008_read mcp3008_read.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0
#define SPI_CS_VALUE    0x01       /* active-low CS */

#define MCP3008_CHANNEL 0
#define VDD_V          3.3f
#define VREF_V         3.3f

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0 on success (raw 10-bit value stored in *out),
 *        -1 on error (errno set).
 */
static int mcp3008_read(int fd, uint8_t channel, uint16_t *out)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid channel %u (must be 0-7)\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI frame (3 bytes):
     *   tx[0] = 0x01  (start bit)
     *   tx[1] = (0x08 | channel) << 4  (single-ended + channel)
     *   tx[2] = 0x00  (clock out remaining bits)
     *
     * Response:
     *   rx[0] = (rx[1] & 0x03) << 8  -> lower 2 bits
     *   rx[1] = rx[2]          -> upper 8 bits
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    /* 10-bit result: lower 2 bits of rx[1] + 8 bits of rx[2] */
    *out = ((uint16_t)(rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

int main(void)
{
    int fd = -1;
    uint16_t raw;

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open SPI device */
    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Configure SPI mode, bits, speed */
    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        goto cleanup;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        goto cleanup;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Configure CS line as output, initially low */
    if (ioctl(fd, SPI_IOC_WR_CS_SET_MODE, &SPI_CS_VALUE) < 0) {
        fprintf(stderr, "SPI_IOC_WR_CS_SET_MODE failed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("MCP3008 ADC read started on channel %u. Press Ctrl+C to exit.\n", MCP3008_CHANNEL);

    while (g_running) {
        if (mcp3008_read(fd, MCP3008_CHANNEL, &raw) < 0) {
            fprintf(stderr, "Error reading MCP3008 channel %u\n", MCP3008_CHANNEL);
            break;
        }

        printf("Channel %u: raw=%u, V=%.2f V\n", MCP3008_CHANNEL, raw,
               (float)raw / VREF_V * VDD_V);

        /* Sleep 500 ms between samples */
        usleep(500000);
    }

    /* Clean shutdown */
    if (fd >= 0) {
        (void)ioctl(fd, SPI_IOC_WR_CS_SET_MODE, &SPI_CS_VALUE);
        close(fd);
    }

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        (void)close(fd);
    }
    return EXIT_FAILURE;
}

