/*
 * MCP3008 analog-to-digital converter on Raspberry Pi Zero W.
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (pin 1)
 *   MCP3008 VREF -> 3.3 V (pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3008 CH0  -> A0  (channel 0)
 *   MCP3008 CH1  -> A1  (channel 1)
 *   MCP3008 CH2  -> A2  (channel 2)
 *
 * Build:  gcc -O2 -Wall -o mcp3008_csv mcp3008_csv.c -lpigpio -lrt
 * Run:    sudo ./mcp3008_csv
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL      0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED        1000000    /* 1 MHz */
#define SPI_FLAGS        0          /* mode 0, active-low CE */
#define VREF             3.3f       /* MCP3008 reference voltage */
#define NUM_CHANNELS     3
#define SAMPLE_INTERVAL  5          /* seconds between readings */
#define CSV_FILENAME     "sensor_data.csv"

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a single-ended channel from the MCP3008.                         */
/* Returns 0–1023 on success, -1 on SPI error, -2 on invalid channel.   */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (clock out remaining bits)
     *
     * Response:
     *   rx[0] bits 1:0  -> low 2 bits
     *   rx[1] bits 7:2  -> high 2 bits
     *   rx[2]         -> 8 bits
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int bytes = spiXfer(g_spi_handle, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", bytes);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Convert a 10-bit ADC value to voltage.                              */
/* ------------------------------------------------------------------ */
static float adc_to_voltage(int adc_value)
{
    return ((float)adc_value / 1023.0f) * VREF;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped CSV line to the file.                          */
/* ------------------------------------------------------------------ */
static int append_to_csv(float voltage1, float voltage2, float voltage3)
{
    FILE *fp = fopen(CSV_FILENAME, "a");
    if (fp == NULL) {
        perror("fopen");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time");
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, voltage1, voltage2, voltage3) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 (chip enable 0) --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MCP3008 data logger started.  Sampling every %d s.  Ctrl+C to stop.\n",
           SAMPLE_INTERVAL);

    /* --- Main sampling loop --- */
    while (g_running) {
        float v1 = adc_to_voltage(read_mcp3008(0));
        float v2 = adc_to_voltage(read_mcp3008(1));
        float v3 = adc_to_voltage(read_mcp3008(2));

        if (append_to_csv(v1, v2, v3) != 0) {
            fprintf(stderr, "CSV write failed; aborting.\n");
            break;
        }

        /* Sleep in 1-second increments so signals are caught promptly. */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

