/*
 * tamper_logger.c
 *
 * Reads the MAX9814 analog output through an MCP3008 ADC on SPI0 CE0
 * channel 0, and the BH1750 ambient light sensor on I2C /dev/i2c-1.
 * Logs timestamped readings to tamper_log.csv.
 *
 * Build: gcc -O2 -Wall -o tamper_logger tamper_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define I2C_DEVICE      "/dev/i2c-1"
#define CSV_FILE        "tamper_log.csv"
#define SAMPLE_INTERVAL 5
#define MAX_I2C_RETRIES 3
#define MAX_ADC_RETRIES 3

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0-1023 on success, -1 on error.
 */
static int read_mcp3008(int fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %u\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit + SGL/DIFF=1 + D2 D1 D0 */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_i2c_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = 1000000,
        .delay_usecs   = 0,
        .bits_per_word = 8,
        .cs_change     = 0,
        .tx_nbits      = 0,
        .rx_nbits      = 0,
        .pad           = 0,
        .delay_usecs   = 0,
    };

    if (ioctl(fd, SPI_I2C, &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/*
 * Read the BH1750 ambient light sensor.
 * Returns 0-1023 on success, -1 on error.
 */
static int read_bh1750(int fd)
{
    uint8_t cmd = 0x80;
    uint8_t buf[2] = { 0 };

    struct spi_i2c_transfer tr = {
        .tx_buf        = (unsigned long)cmd,
        .rx_buf        = (unsigned long)buf,
        .len           = 2,
        .speed_hz      = 100000,
        .delay_usecs   = 0,
        .bits_per_word = 8,
        .cs_change     = 0,
        .tx_nbits      = 0,
        .rx_nbits      = 0,
        .pad           = 0,
        .delay_usecs   = 0,
    };

    if (ioctl(fd, SPI_I2C, &tr) < 0) {
        fprintf(stderr, "BH1750 SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int light_level = ((buf[0] & 0x07) << 8) | buf[1];
    return light_level;
}

/*
 * Log a CSV row with timestamp, sound_level_db, light_level_lux, and error_code.
 */
static void log_data(FILE *fp, int sound_level, int light_level, int error_code)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "localtime failed: %s\n", strerror(errno));
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (error_code != 0) {
        fprintf(fp, "%s,%d,%d,%d\n", timestamp, sound_level, light_level, error_code);
    } else {
        fprintf(fp, "%s,%d,%d\n", timestamp, sound_level, light_level);
    }
    fflush(fp);
}

int main(void)
{
    int spi_fd = -1;
    int i2c_fd = -1;
    FILE *fp = NULL;
    int adc_retries = 0;
    int i2c_retries = 0;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open CSV file in append mode */
    fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", CSV_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open SPI device */
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        goto cleanup;
    }

    uint8_t spi_mode = SPI_MODE_0;
    uint8_t spi_bits = 8;
    uint32_t spi_speed = 1000000;

    if (ioctl(spi_fd, SPI_I2C, &spi_mode) < 0) {
        fprintf(stderr, "SPI_I2C_MODE failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_I2C, &spi_bits) < 0) {
        fprintf(stderr, "SPI_I2C_BITS failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_I2C, &spi_speed) < 0) {
        fprintf(stderr, "SPI_I2C_SPEED failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Open I2C device */
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_DEVICE, strerror(errno));
        goto cleanup;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, 0x27) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x27: %s\n", strerror(errno));
        goto cleanup;
    }

    /*
     * Read MAX9814 ADC channel 0 (MCP3008 channel 0) once to initialize
     * the sensor.
     */
    int max9814_retries = MAX_ADC_RETRIES;
    while (max9814_retries > 0 && !g_running) {
        int adc_value = read_mcp3008(spi_fd, 0);
        if (adc_value >= 0) {
            adc_retries--;
            log_data(fp, adc_value, 0, 0);
        } else {
            fprintf(stderr, "ADC read failed after %d retries\n", max9814_retries);
            adc_retries--;
        }
        usleep(10000); /* 10 ms */
    }

    if (g_running) {
        fprintf(stderr, "Max ADC retries reached. Sensor may not be ready.\n");
    }

    /* Read BH1750 sensor */
    max9814_retries = MAX_ADC_RETRIES;
    while (max9814_retries > 0 && !g_running) {
        int light_level = read_bh1750(i2c_fd);
        if (light_level >= 0) {
            light_level = (int)light_level;
            log_data(fp, 0, light_level, 0);
        } else {
            fprintf(stderr, "BH1750 read failed after %d retries\n", max9814_retries);
            adc_retries--;
        }
        usleep(10000);
    }

    if (g_running) {
        fprintf(stderr, "Max ADC retries reached. Sensor may not be ready.\n");
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (fp != NULL) {
        fclose(fp);
        fp = NULL;
    }

    return ret;
}

