/*
 * Raspberry Pi 4 Model B - Vegetronix VH400 Soil Moisture Sensor
 *
 * Wiring:
 *   VH400 OUT -> MCP3008 CH0 (0-3.3V)
 *   VH400 GND -> MCP3008 GND
 *   VH400 VDD -> 3.3V (or 5V, but MCP3008 requires 3.3V)
 *   VH400 CLK  -> SPI0 SCLK (GPIO11)
 *   VH400 DOUT -> SPI0 MISO (GPIO9)
 *   VH400 DIN  -> SPI0 MOSI (GPIO10)
 *   VH400 CS   -> SPI0 CE0 (GPIO8)
 *   VH400 RELAY -> BCM GPIO17 (active-high)
 *
 * Build: gcc -O2 -Wall -o vh400_pump vh400_pump.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0
#define SPI_DELAY_US    0

#define MCP3008_CHANNEL 0
#define PUMP_GPIO_PIN   17
#define MOISTURE_THRESHOLD_PERCENTAGE 30
#define SAMPLE_INTERVAL_SEC 60
#define MAX_RETRIES      3

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0-1023 on success, -1 on failure.
 */
static int mcp3008_read(int fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %u\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read:
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (single-ended + channel)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: bits 9-2 in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = SPI_SPEED_HZ,
        .delay_usecs   = SPI_DELAY_US,
        .bits_per_word = SPI_BITS,
        .cs_change     = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int value = ((rx[1] & 0x03) << 8) | rx[2];
    return value;
}

static void log_reading(int moisture_level)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    printf("%s - Moisture Level: %d%%\n", ts, moisture_level);
    fflush(stdout);
}

static void control_pump(int moisture_level)
{
    if (moisture_level < 0 || moisture_level > 100) {
        fprintf(stderr, "Invalid moisture level: %d%%\n", moisture_level);
        return;
    }

    int level = (moisture_level < MOISTURE_THRESHOLD_PERCENTAGE) ? 1 : 0;
    if (level == 0) {
        if (gpio_write(PUMP_GPIO_PIN, 0) < 0) {
            fprintf(stderr, "Failed to turn off pump: %s\n", strerror(errno));
        }
    } else {
        if (gpio_write(PUMP_GPIO_PIN, 1) < 0) {
            fprintf(stderr, "Failed to turn on pump: %s\n", strerror(errno));
        }
    }
}

static void cleanup(void)
{
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (gpio_is_initialized()) {
        gpio_set_mode(PUMP_GPIO_PIN, GPIO_INPUT);
        gpio_set_direction(PUMP_GPIO_PIN, GPIO_OUTPUT);
        gpio_write(PUMP_GPIO_PIN, 0);
    }
    printf("Cleanup complete.\n");
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize SPI */
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize GPIO for pump control */
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpio_set_direction(PUMP_GPIO_PIN, GPIO_OUTPUT);
    gpio_write(PUMP_GPIO_PIN, 0);

    printf("VH400 soil moisture sensor monitoring started. Press Ctrl+C to exit.\n");
    printf("SPI: %s @ %u Hz, MCP3008 CH%d, Pump GPIO%d\n",
           SPI_DEVICE, SPI_SPEED_HZ, MCP3008_CHANNEL, PUMP_GPIO_PIN);

    while (g_running) {
        int moisture_level = mcp3008_read(g_spi_fd, MCP3008_CHANNEL);
        if (moisture_level < 0) {
            fprintf(stderr, "SPI read error; retrying...\n");
            usleep(SAMPLE_INTERVAL_SEC * 1000000);
            continue;
        }

        log_reading(moisture_level);
        control_pump(moisture_level);

        if (g_running) {
            sleep(SAMPLE_INTERVAL_SEC);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

