/*
 * Door-opening simulation for Raspberry Pi Zero W using MCP3008 ADC.
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND  (Pin 6)
 *   MCP3008 DGND -> GND  (Pin 6)
 *   MCP3008 CLK  -> GPIO11 (Pin 23)
 *   MCP3008 DOUT -> GPIO9  (Pin 21)
 *   MCP3008 DIN  -> GPIO10 (Pin 19)
 *   MCP3008 CS   -> GPIO8  (Pin 24)
 *   MCP3008 CH0  -> GP2Y0A21YK0F (channel 0)
 *   Relay GND   -> GPIO17 (Pin 12)
 *   Relay VCC   -> 3.3 V (Pin 1)
 *   Relay IN    -> GPIO17 (Pin 12)
 *   Relay OUT   -> GND (Pin 14)
 *
 * Build: gcc -O2 -Wall -o door_sim door_sim.c -lpigpio -lrt
 * Run:   sudo ./door_sim
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL      0
#define SPI_BAUD         1000000   /* 1 MHz */
#define RELAY_GPIO       17
#define DISTANCE_THRESHOLD_CM 20.0f
#define POLL_INTERVAL_US  100000   /* 100 ms */
#define DEBOUNCE_DELAY_US 1000000   /* 1 s */
#define LOG_FILE         "door_events.log"

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MCP3008 single-ended read                                          */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3-byte transfer):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  (single-ended + channel)
     *   Byte 2: 0x00  (don't care, clocks out low 2 bits)
     *
     * Response:
     *   rx[0] = (rx[1] & 0x03) << 8 | rx[2]
     *   rx[1] is undefined (pigpio returns 0 on error)
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(const char *message)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[unknown time] %s\n", message);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Relay control                                                      */
/* ------------------------------------------------------------------ */
static void control_relay(bool state)
{
    if (gpioWrite(RELAY_GPIO, state ? 1 : 0) != 0) {
        fprintf(stderr, "Failed to write relay GPIO %d\n", RELAY_GPIO);
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 at 1 MHz --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (channel %d, %d baud)\n",
                SPI_CHANNEL, SPI_BAUD);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure relay GPIO as output --- */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    control_relay(0);

    /* --- Install signal handler --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        control_relay(0);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Door-opening simulation started. Press Ctrl+C to exit.\n");

    /* --- Main polling loop --- */
    while (g_running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            /* SPI error: log and retry */
            fprintf(stderr, "SPI read error; retrying in %d ms\n",
                    POLL_INTERVAL_US / 1000);
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        /* Distance in cm */
        float distance = (float)adc_value / 1023.0f * 100.0f;

        if (distance < DISTANCE_THRESHOLD_CM) {
            printf("Distance below threshold: %.2f cm\n", distance);
            log_event("Door opened due to proximity sensor error");

            /*
             * Debounce: wait for 1 s before re-energizing the relay.
             * gpioDelay is microseconds; we use a multiple of the
             * poll interval so the delay is always a multiple of 100 ms.
             */
            gpioDelay(DEBOUNCE_DELAY_US);
            control_relay(1);
        } else {
            control_relay(0);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    control_relay(0);
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

