/*
 * irrigate.c — Raspberry Pi Zero W
 *
 * Reads three successive samples from a Vegetronix VH400 soil-moisture sensor
 * through an MCP3008 ADC on SPI channel 0 (CE0 on GPIO8), computes the
 * average, and sets an ASCO RedHat 8210 series proportional solenoid valve
 * on GPIO17 (BCM numbering) with PWM at 100 Hz and a duty-cycle range of
 * 0–100.  Logs a timestamped line to irrigate.log every 5 seconds.
 *
 * Build:  gcc -O2 -Wall -Wextra -o irrigate irrigate.c -lm
 * Run:    sudo ./irrigate
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define SPI_CHANNEL        0          /* CE0 on GPIO8 */
#define SPI_SPEED_HZ       1000000     /* 1 MHz */
#define SPI_FLAGS          0           /* mode 0, active-low CE */

#define VALVE_GPIO         17          /* BCM 17 */
#define PWM_FREQUENCY      100         /* Hz */
#define PWM_RANGE          100         /* duty-cycle 0–100 */

#define SAMPLE_INTERVAL_S  5
#define LOG_FILE           "irrigation.log"

/* ----------------------------- Globals ----------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int      g_spi_fd = -1;
static FILE    *g_log_fp = NULL;

/* ----------------------------- Prototypes -------------------------------- */

static void signal_handler(int sig);
static int  init_spi(void);
static int  read_mcp3008(int channel, int *out_value);
static float compute_average(int raw1, int raw2, int raw3);
static void set_valve_position(float avg);
static void log_data(int raw1, int raw2, int raw3, float avg, int val);
static void cleanup(void);

/* ----------------------------- Signal handler ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- SPI initialization ----------------------------- */

static int init_spi(void)
{
    g_spi_fd = open(SPI_CHANNEL, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "open(%d): %s\n", SPI_CHANNEL, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_FLAGS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

/* ----------------------------- MCP3008 read ----------------------------- */

static int read_mcp3008(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = 8;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    *out_value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

/* ----------------------------- Compute average --------------------------------*/

static float compute_average(int raw1, int raw2, int raw3)
{
    return (float)raw1 + (float)raw2 + (float)raw3 / 3.0f;
}

/* ----------------------------- Set valve position ----------------------------- */

static void set_valve_position(float avg)
{
    int duty = (int)((avg * PWM_RANGE) / 100.0f);
    if (duty < 0)   duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;

    if (gpioPWM(VALVE_GPIO, duty) < 0) {
        fprintf(stderr, "gpioPWM(%d, %d): %s\n", VALVE_GPIO, duty, strerror(errno));
    }
}

/* ----------------------------- Logging ------------------------------------- */

static void log_data(int raw1, int raw2, int raw3, float avg, int val)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(g_log_fp, "%s, Raw1=%d, Raw2=%d, Raw3=%d, Avg=%5.2f, Val=%d\n",
                ts, raw1, raw2, raw3, avg, val) < 0) {
        fprintf(stderr, "fprintf to log: %s\n", strerror(errno));
    }
    fflush(g_log_fp);
}

/* ----------------------------- Cleanup ------------------------------------ */

static void cleanup(void)
{
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

/* ----------------------------- Main --------------------------------------- */

int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* --- log file -------------------------------------------------- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handlers ------------------------------------------ */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- SPI init -------------------------------------------------- */
    if (init_spi() < 0) {
        cleanup();
        return EXIT_FAILURE;
