        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(VALVE_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange(%d, %d): %s\n", VALVE_GPIO, PWM_RANGE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioPWM(VALVE_GPIO, 0) < 0) {
        fprintf(stderr, "gpioPWM(%d, 0): %s\n", VALVE_GPIO, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
