#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/pwm.h>
#include <pigpio.h>

#define PWM_CHANNEL 0
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define SENSOR_TRIG_PIN 23
#define SENSOR_ECHO_PIN 24
#define CALIBRATION_FILE "theremin_config.txt"

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static int pigpio_initialized = 0;

typedef struct {
    float distance;
    float volume;
} SensorData;

static SensorData last_distance = {0.0f, 0.0f};
static SensorData last_volume = {0.0f, 0.0f};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = SPI_SPEED;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }
    return 0;
}

static int spi_read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {0x01, (uint8_t)((0x08 | channel) << 4), 0x00};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int read_sensor(void) {
    int distance = -1;
    int volume = -1;

    if (spi_fd < 0) {
        fprintf(stderr, "SPI not initialized\n");
        return -1;
    }

    uint8_t tx[2] = {0x02, 0x00};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 2,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    if (rx[1] & 0x08) {
        distance = ((rx[1] & 0x07) << 8) | rx[2];
    }

    if (spi_fd < 0) {
        fprintf(stderr, "SPI not initialized\n");
        return -1;
    }

    if (distance < 0 || distance > 100) {
        fprintf(stderr, "Invalid distance: %d\n", distance);
        return -1;
    }

    if (volume < 0) {
        volume = (int)((distance / 10.0f) * 100.0f);
    }

    return 0;
}

static void pwm_init(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return;
    }
    pigpio_initialized = 1;
    gpioSetMode(SENSOR_TRIG_PIN, PI_OUTPUT);
    gpioSetMode(SENSOR_ECHO_PIN, PI_INPUT);
    gpioSetPWMfrequency(PWM_CHANNEL, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_CHANNEL, PWM_RANGE);
    gpioPWM(PWM_CHANNEL, 0);
}

static void pwm_stop(void) {
    if (pigpio_initialized) {
        gpioPWM(PWM_CHANNEL, 0);
    }
}

static void pwm_set_frequency(int freq) {
    if (pigpio_initialized) {
        gpioSetPWMfrequency(PWM_CHANNEL, freq);
    }
}

static void pwm_set_range(int range) {
    if (pigpio_initialized) {
        gpioSetPWMrange(PWM_CHANNEL, range);
    }
}

static void pwm_set_duty(int duty) {
    if (pigpio_initialized) {
        gpioPWM(PWM_CHANNEL, duty);
    }
}

static void pwm_stop_all(void) {
    if (pigpio_initialized) {
        gpioPWM(PWM_CHANNEL, 0);
    }
}

static void pwm_set_volume(int volume) {
    if (pigpio_initialized) {
        if (volume < 0) volume = 0;
        if (volume > 100) volume = 100;
        pwm_set_range(volume);
        pwm_set_frequency(PWM_FREQUENCY);
        pwm_set_duty(volume);
    }
}

static void calibrate(void) {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Calibration file not found\n");
        return;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *eq = strchr(line, '=');
        if (!eq) continue;
        char *end = eq + 1;
        char *val = eq + 1;
        if (*end == '\n' || *end == '\r') *end = '\0';
        if (strcmp(val, "distance") == 0) {
            float d = atof(val);
            if (d < 0.0f) d = 0.0f;
            last_distance.distance = d;
        } else if (strcmp(val, "volume") == 0) {
            float v = atof(val);
            if (v < 0.0f) v = 0.0f;
            last_volume.volume = v;
        }
    }
    fclose(fp);
}

static void load_calibration(void) {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Calibration file not found, using defaults\n");
        return;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *eq = strchr(line, '=');
        if (!eq) continue;
        char *end = eq + 1;
        char *val = eq + 1;
        if (*end == '\n' || *end == '\r') *end = '\0';
        if (strcmp(val, "distance") == 0) {
            float d = atof(val);
            if (d < 0.0f) d = 0.0f;
            last_distance.distance = d;
        } else if (strcmp(val, "volume") == 0) {
            float v = atof(val);
            if (v < 0.0f) v = 0.0f;
            last_volume.volume = v;
        }
    }
    fclose(fp);
}

static void save_calibration(void) {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (!fp) {
        perror("Failed to open calibration file");
        return;
    }

    char line[256];
    snprintf(line, sizeof(line), "distance=%.2f,volume=%.2f", last_distance.distance, last_volume.volume);
    if (fprintf(fp, "%s\n", line) < 0) {
        perror("Failed to write calibration data");
    }
    fclose(fp);
}

static void cleanup(void) {
    pwm_stop_all();
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (pigpio_initialized) {
        gpioTerminate();
        pigpio_initialized = 0;
    }
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (spi_init() < 0) {
        return 1;
    }

    if (calibrate() < 0) {
        fprintf(stderr, "Calibration failed, using defaults\n");
        load_calibration();
    }

    pwm_init();

    while (running) {
        int distance = -1;
        int volume = -1;

        if (read_sensor() < 0) {
            fprintf(stderr, "Sensor read error, retrying...\n");
            gpioDelay(100000);
            continue;
        }

        if (distance < 0 || volume < 0) {
            fprintf(stderr, "Sensor read error, retrying...\n");
            gpioDelay(100000);
            continue;
        }

        pwm_set_volume(volume);
        pwm_set_frequency(PWM_FREQUENCY);
        pwm_set_range(PWM_RANGE);
        pwm_set_duty(volume);

        printf("Distance: %.2f, Volume: %.2f\n", distance, volume);

        gpioDelay(100000);
    }

    cleanup();
    return 0;
}

