/*
 * MCP3008 single-ended read: 3-byte transfer.
 * tx[0] = 0x01                         (start bit)
 * tx[1] = (0x08 | channel) << 4        (single-ended + channel)
 * tx[2] = 0x00                         (clock out remaining bits)
 * Result: ((rx[1] & 0x03) << 8) | rx[2]
 */
static int read_mcp3008(int spi_handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int log_data(FILE *fp, int moisture, int pump_state)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }

    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s, Moisture: %d, Pump: %s\n", ts, moisture, pump_state ? "ON" : "OFF") < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }

    return 0;
}

static void cleanup(void)
{
    /* Ensure pump is off before terminating pigpio */
    if (gpioInitialise() >= 0) {
        gpioWrite(PUMP_GPIO, 0);
        gpioTerminate();
    }
}

static void signal_handler(int sig)
{
    (void)sig;
    fprintf(stderr, "\nCaught signal, cleaning up...\n");
    cleanup();
    exit(0);
}

int main(void)
{
    int spi_handle = -1;
    FILE *fp = NULL;
    int pump_state = 0;
    int rc = EXIT_FAILURE;

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- SPI init ---- */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        goto cleanup_pigpio;
    }

    /* ---- Log file open ---- */
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        goto cleanup_spi;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed\n");
        goto cleanup_log;
    }

    fprintf(stderr, "Soil moisture monitoring started.  SPI0 CE0=GPIO8, MCP3008 CH0, pump GPIO%d\n", PUMP_GPIO);
    fprintf(stderr, "Threshold: %d, Log: %s\n", MOISTURE_THRESHOLD, LOG_FILE);

    /* ---- Main loop ---- */
    while (1) {
        int moisture = read_mcp3008(spi_handle, 0);
        if (moisture < 0) {
            fprintf(stderr, "Sensor read error, skipping cycle\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        if (moisture < MOISTURE_THRESHOLD) {
            pump_state = 1;
            fprintf(stderr, "Moisture below threshold: %d, Pump ON\n", moisture);
            if (gpioWrite(PUMP_GPIO, 1) != 0) {
                fprintf(stderr, "Failed to turn pump ON\n");
            }
        } else {
            pump_state = 0;
            fprintf(stderr, "Moisture above threshold: %d, Pump OFF\n", moisture);
            if (gpioWrite(PUMP_GPIO, 0) != 0) {
                fprintf(stderr, "Failed to turn pump OFF\n");
            }
        }

        if (log_data(fp, moisture, pump_state) != 0) {
            fprintf(stderr, "Logging failed, continuing\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

    rc = EXIT_SUCCESS;

cleanup_log:
    if (fp != NULL) {
        if (fclose(fp) != 0) {
            fprintf(stderr, "Warning: fclose failed\n");
        }
    }

cleanup_spi:
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }

cleanup_pigpio:
    gpioTerminate();
    return rc;
}

