/*
 * Raspberry Pi 4 Model B – Potentiometer-controlled DC Motor Controller
 *
 * Reads two MCP3008 ADC channels (0 and 1) via SPI0 (1 MHz, mode 0)
 * and drives two Adafruit Mini DC Motors (Product ID 155) via PWM.
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V
 *   MCP3008 VREF -> 3.3 V
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SCLK)
 *   MCP3008 DOUT -> GPIO9  (MISO)
 *   MCP3008 DIN  -> GPIO10 (MOSI)
 *   MCP3008 CS   -> GPIO8  (CE0)
 *   MCP3008 CH0  -> Potentiometer 0
 *   MCP3008 CH1  -> Potentiometer 1
 *
 * Motor 1:
 *   Motor 1 enable  -> GPIO18
 *   Motor 1 direction -> GPIO23
 *   Motor 1 speed    -> GPIO25
 *
 * Motor 2:
 *   Motor 2 enable  -> GPIO24
 *   Motor 2 direction -> GPIO25
 *   Motor 2 speed    -> GPIO25
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o motor_controller motor_controller.c -lpigpio -lrt
 * Run:
 *   sudo ./motor_controller
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL        0          /* SPI0 (CE0) */
#define SPI_SPEED          1000000    /* 1 MHz */
#define SPI_FLAGS          0          /* Mode 0, active-low CE */

#define POT_CHANNEL_0      0          /* MCP3008 CH0 */
#define POT_CHANNEL_1      1          /* MCP3008 CH1 */

#define MOTOR_1_ENABLE     18         /* GPIO18 */
#define MOTOR_1_DIRECTION  23         /* GPIO23 */
#define MOTOR_1_SPEED      25         /* GPIO25 */

#define MOTOR_2_ENABLE     24         /* GPIO24 */
#define MOTOR_2_DIRECTION  25         /* GPIO25 */
#define MOTOR_2_SPEED      25         /* GPIO25 */

#define PWM_FREQUENCY      1000       /* 1 kHz */
#define PWM_RANGE          255
#define PWM_DUTY_MAX       PWM_RANGE

#define POT_MAX_VALUE      1023       /* 10-bit ADC */
#define POT_MIN_VALUE      0

#define SPEED_STEP_US      500000     /* 500 ms per step */
#define SPEED_STEP_DELAY_US 500000     /* 500 ms between steps */
#define SPEED_HOLD_US      2000000   /* 2 s hold phase */
#define PARKING_DELAY_US   5000000   /* 5 s pause between cycles */
#define LOOP_DELAY_US      1000000   /* 1 ms between cycles */

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ----------------------------- Signal Handlers ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- SPI / PWM ----------------------------- */
static int spi_init(void)
{
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (handle=%d)\n", g_spi_handle);
        return -1;
    }
    return 0;
}

static int spi_read_adc(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read: 3-byte transfer
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  (SGL/DIFF=1, D2 D1 D0 = channel)
     *   Byte 2: 0x00  (clock out remaining bits)
     * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2]
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: spiXfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ----------------------------- Potentiometer ----------------------------- */
static int read_potentiometer(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid potentiometer channel %d\n", channel);
        return -1;
    }

    int value = 0;
    for (int i = 0; i < 10; i++) {
        int adc = spi_read_adc(channel);
        if (adc < 0) {
            fprintf(stderr, "Error: SPI read failed on channel %d\n", channel);
            return -1;
        }
        value += (adc << (7 - i));
        gpioDelay(10000); /* 10 ms */
    }
    return value;
}

/* ----------------------------- Motor control ----------------------------- */
static void set_motor_speed(int enable, int direction, int speed)
{
    if (speed < 0) speed = 0;
    if (speed > PWM_RANGE) speed = PWM_RANGE;

    if (enable) {
        if (direction == 1) {
            gpioPWM(MOTOR_1_ENABLE, speed);
            gpioPWM(MOTOR_2_ENABLE, speed);
        } else {
            gpioPWM(MOTOR_1_ENABLE, 0);
            gpioPWM(MOTOR_2_ENABLE, 0);
        }
    } else {
        if (direction == 1) {
            gpioPWM(MOTOR_1_ENABLE, 0);
            gpioPWM(MOTOR_2_ENABLE, 0);
        } else {
            gpioPWM(MOTOR_1_ENABLE, -speed);
            gpioPWM(MOTOR_2_ENABLE, -speed);
        }
    }
}

/* ----------------------------- Motor direction ----------------------------- */
static void set_motor_direction(int direction)
{
    if (direction == 1) {
        gpioSetMode(MOTOR_1_ENABLE, PI_OUTPUT);
        gpioSetMode(MOTOR_2_ENABLE, PI_OUTPUT);
    } else {
        gpioSetMode(MOTOR_1_ENABLE, PI_INPUT);
        gpioSetMode(MOTOR_2_ENABLE, PI_INPUT);
        gpioSetPWMrange(MOTOR_1_ENABLE, PWM_RANGE);
        gpioSetPWMrange(MOTOR_2_ENABLE, PWM_RANGE);
        gpioPWM(MOTOR_1_ENABLE, 0);
        gpioPWM(MOTOR_2_ENABLE, 0);
    }
}

/* ----------------------------- Motor speed ----------------------------- */
static void set_motor_speed(int speed)
{
    set_motor_direction(0);
    set_motor_speed(MOTOR_1_ENABLE, MOTOR_1_DIRECTION, speed);
    set_motor_speed(MOTOR_2_ENABLE, MOTOR_2_DIRECTION, speed);
}

/* ----------------------------- Motor hold phase ----------------------------- */
static void hold_phase(int seconds)
{
    set_motor_speed(0);
    gpioDelay(seconds * 1000000); /* microseconds */
}

/* ----------------------------- Motor reverse phase ----------------------------- */
static void reverse_phase(int seconds)
{
    hold_phase(seconds);
    set_motor_direction(1);
    set_motor_speed(0);
    set_motor_direction(0);
    set_motor_speed(0);
}

/* ----------------------------- Motor cycle ----------------------------- */
static void cycle(int cycles)
{
    for (int i = 0; i < cycles && g_running; i++) {
        set_motor_speed(0);
        hold_phase(SPEED_HOLD_US);

        int pot_0 = read_potentiometer(POT_CHANNEL_0);
        int pot_1 = read_potentiometer(POT_CHANNEL_1);

        if (pot_0 < 0 || pot_1 < 0) {
            fprintf(stderr, "Warning: SPI read failed during cycle\n");
        }

        int speed_0 = (pot_0 < 0) ? 0 : (int)((float)pot_0 / POT_MAX_VALUE * PWM_RANGE);
        int speed_1 = (pot_1 < 0) ? 0 : (int)((float)pot_1 / POT_MAX_VALUE * PWM_RANGE);

        set_motor_speed(speed_0);
        set_motor_speed(speed_1);

        if (i < cycles - 1) {
            reverse_phase(SPEED_HOLD_US);
        }
    }
}

/* ----------------------------- Main ----------------------------------- */
int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (spi_init() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure motor 1 */
    if (gpioSetMode(MOTOR_1_ENABLE, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", MOTOR_1_ENABLE);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_1_DIRECTION, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", MOTOR_1_DIRECTION);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(MOTOR_1_ENABLE, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range\n");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(MOTOR_1_ENABLE, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range\n");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(MOTOR_1_ENABLE, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range\n");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioPWM(MOTOR_1_ENABLE, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise motor 1\n");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure motor 2 */
    if (gpioSetMode(MOTOR_2_ENABLE, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", MOTOR_2_ENABLE);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_2_DIRECTION, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", MOTOR_2_DIRECTION);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(MOTOR_2_ENABLE, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range\n");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(MOTOR_2_ENABLE, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range\n");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioPWM(MOTOR_2_ENABLE, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise motor 2\n");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Motor controller started. Press Ctrl+C to exit.\n");

    while (g_running) {
        cycle(2);
    }

    /* Cleanup */
    set_motor_speed(0);
    set_motor_direction(0);
    set_motor_speed(0);
