/*
 * Raspberry Pi 3 Model B+ - MAX9814 Sound Level Monitor
 *
 * Hardware:
 *   - Adafruit MAX9814 Electret Microphone Amplifier on SPI0_CH0
 *   - MCP3008 10-bit ADC on SPI0_CS0 (GPIO8)
 *   - LED on GPIO17 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -o sound_monitor sound_monitor.c -lm
 *
 * Run:
 *   sudo ./sound_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/gpio.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        0
#define LED_GPIO        17
#define SAMPLE_INTERVAL 5
#define DEBOUNCE_MS     10
#define CALIBRATION_MS  5
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_INTERVAL)
#define CALIBRATION_US  (CALIBRATION_MS * 1000)

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended sample from the MCP3008.
 * Returns 0–1023 on success, -1 on error.
 */
static int read_mcp3008(int fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %u\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read:
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (single-ended + channel)
     *   tx[2] = 0x00                       (don't care)
     * Result: bits 9–2 in rx[1] (low 2 bits), bits 1–0 in rx[2] (high 2 bits).
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    int value = ((rx[1] & 0x03) << 8) | rx[2];
    return value;
}

static void calibrate_sound_level(void)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        perror("localtime failed");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("Calibration started at %s. Press Ctrl+C to exit.\n", timestamp);

    for (int i = 0; i < CALIBRATION_MS; i++) {
        int sample = read_mcp3008(g_spi_fd, 0);
        if (sample < 0) {
            fprintf(stderr, "Calibration failed (read error)\n");
            return;
        }
        printf("Calibration sample %d: %d\n", i, sample);
        usleep(100000);
    }

    printf("Calibration complete. Ambient noise level: %d\n", sample);
}

static void log_sound_level(int level)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        perror("localtime failed");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Sound level: %d\n", timestamp, level);
}

static void control_led(int level)
{
    if (level > 0) {
        if (gpio_write(LED_GPIO, 1) < 0) {
            perror("Failed to turn LED on");
        }
    } else {
        if (gpio_write(LED_GPIO, 0) < 0) {
            perror("Failed to turn LED off");
        }
    }
}

int main(void)
{
    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT) failed");
        return EXIT_FAILURE;
    }

    /* --- SPI initialization --- */
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(g_spi_fd);
        return EXIT_FAILURE;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(g_spi_fd);
        return EXIT_FAILURE;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(g_spi_fd);
        return EXIT_FAILURE;
    }

    /* --- GPIO setup --- */
    if (gpio_init() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        close(g_spi_fd);
        return EXIT_FAILURE;
    }

    if (gpio_set_mode(LED_GPIO, OUTPUT) < 0) {
        perror("Failed to set LED GPIO mode");
        gpio_exit();
        close(g_spi_fd);
        return EXIT_FAILURE;
    }

    if (gpio_write(LED_GPIO, 0) < 0) {
        perror("Failed to initialize LED GPIO state");
        gpio_exit();
        close(g_spi_fd);
        return EXIT_FAILURE;
    }

    /* --- Sound level monitoring --- */
    calibrate_sound_level();

    printf("Sound level monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int sample = read_mcp3008(g_spi_fd, 0);
        if (sample < 0) {
            fprintf(stderr, "Error reading sound level, retrying...\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        log_sound_level(sample);

        if (sample > 0) {
            control_led(sample);
        }

        usleep(SAMPLE_PERIOD_US);
    }

    /* --- Graceful cleanup --- */
    printf("\nShutting down...\n");
    gpio_write(LED_GPIO, 0);
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
    }
    gpio_exit();
    return EXIT_SUCCESS;
}

