/*
 * ADMP401 MEMS microphone sample logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V
 *   MCP3008 VREF -> 3.3 V
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SCLK)
 *   MCP3008 DOUT -> GPIO9  (MISO)
 *   MCP3008 DIN  -> GPIO10 (MOSI)
 *   MCP3008 CS   -> GPIO8  (CE0)
 *   MCP3008 CH0  -> ADMP401 VDD (analog)
 *   MCP3008 CH1  -> ADMP401 VREF (analog)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o admp401_logger admp401_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_BITS        8
#define SPI_DELAY_US    0          /* 0-byte transfer */
#define SAMPLE_PERIOD_NS 1000000000U /* 1 ms */
#define LOG_FILE        "audio_log.txt"
#define SAMPLE_COUNT    1000       /* samples per second */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended sample from the MCP3008.
 *
 * MCP3008 SPI protocol (mode 0, 8 bits):
 *   Byte 0: 0x01  (start bit)
 *   Byte 1: (0x08 | channel) << 4  (single-ended + channel)
 *   Byte 2: 0x00  (clock out remaining bits)
 *
 * Response:
 *   rx[0] = (rx[1] << 8) | rx[2]
 *   rx[3] = 0x00  (ignored)
 *
 * Returns 0 on success, -1 on error.
 */
static int mcp3008_read(int fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int log_sample(int fd, uint32_t timestamp_ns, int raw_adc)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%u|%d\n", timestamp_ns, raw_adc) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open SPI device --- */
    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = SPI_BITS;
    uint32_t speed = SPI_SPEED_HZ;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    int log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    /* --- Main sampling loop --- */
    while (g_running) {
        uint32_t timestamp_ns = 0;
        int raw_adc = 0;

        for (int i = 0; i < SAMPLE_COUNT && g_running; i++) {
            raw_adc = mcp3008_read(spi_fd, 0);
            if (raw_adc < 0) {
                fprintf(stderr, "ADC read error; skipping sample\n");
                nanosleep(&(struct timespec){0, SAMPLE_PERIOD_NS}, NULL);
                continue;
            }

            timestamp_ns = (uint32_t)clock_gettime(CLOCK_MONOTONIC_RAW);
            if (log_sample(spi_fd, timestamp_ns, raw_adc) < 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }

            nanosleep(&(struct timespec){0, SAMPLE_PERIOD_NS}, NULL);
        }
    }

    /* --- Cleanup --- */
    fprintf(stderr, "\nShutting down...\n");

    if (close(spi_fd) < 0) {
        fprintf(stderr, "Warning: error closing SPI device: %s\n", strerror(errno));
    }
    if (close(log_fd) < 0) {
        fprintf(stderr, "Warning: error closing log file: %s\n", strerror(errno));
    }

    return EXIT_SUCCESS;
}

