/*
 * DRV5055VA Hall-Effect Sensor Reader for Raspberry Pi 3 Model B+
 *
 * Reads three DRV5055VA sensors on individual GPIO pins (BCM 4, 17, 27)
 * every 100 ms and logs the magnetic field strength in millitesla to
 * magnetic_log.txt.  Uses individual API calls for broad compatibility.
 *
 * Build:  gcc -O2 -Wall -Wextra -o magnetic_reader magnetic_reader.c
 * Run:    sudo ./magnetic_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <stdint.h>
#include <stdbool.h>

#include <gpiod.h>

#define SENSOR1_PIN  4
#define SENSOR2_PIN  17
#define SENSOR3_PIN  27
#define LOG_FILE     "magnetic_log.txt"
#define SAMPLE_US    100000   /* 100 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);
}

/* ------------------------------------------------------------------ */
/*
 * Read a single DRV5055VA sensor.
 * Returns 0 on success, -1 on error.
 */
static int read_sensor(struct gpiod_line *line, int *out_value)
{
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        fprintf(stderr, "Error: gpiod_line_get_value failed: %s\n",
                strerror(errno));
        return -1;
    }
    *out_value = val;
    return 0;
}

/* ------------------------------------------------------------------ */
/*
 * Convert a HIGH (3.3 V) reading to magnetic field strength in mT.
 * Returns 0 on success, -1 on error.
 */
static int read_sensor_to_mT(int value, int *out_mT)
{
    if (value < 0) {
        fprintf(stderr, "Warning: sensor reading %d is out of range\n", value);
        return -1;
    }

    /*
     * DRV5055VA: HIGH = 3.3 V, LOW = 0 V.
     * Convert HIGH to 3.3 V, LOW to 0 V.
     */
    int raw = (value == 1) ? 3 : 0;
    if (raw < 0) {
        fprintf(stderr, "Warning: raw value %d out of range\n", raw);
        return -1;
    }

    /*
     * DRV5055VA: 3.3 V = 3.3 V, 0 V = 0 V.
     * Convert 3.3 V to 3.3 mT, 0 V to 0 mT.
     */
    int mT = (raw == 3) ? 3.3 : 0;
    if (mT < 0) {
        fprintf(stderr, "Warning: mT value %d out of range\n", mT);
        return -1;
    }
    *out_mT = mT;
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(int sensor1, int sensor2, int sensor3, int mT1,
                     int mT2, int mT3)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open %s: %s\n",
                LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s,%d,%d,%d\n", ts, sensor1, sensor2, sensor3);
    } else {
        fprintf(fp, "ERROR: time_t conversion failed\n");
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Warning: fclose failed: %s\n", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL, *line3 = NULL;
    int ret = EXIT_FAILURE;

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed: %s\n",
                strerror(errno));
    }

    /* ---- Open GPIO chip ---- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: gpiod_chip_open_by_name failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* ---- Get lines ---- */
    line1 = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!line1) {
        fprintf(stderr, "Error: gpiod_chip_get_line(%d) failed: %s\n",
                SENSOR1_PIN, strerror(errno));
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!line2) {
        fprintf(stderr, "Error: gpiod_chip_get_line(%d) failed: %s\n",
                SENSOR2_PIN, strerror(errno));
        goto cleanup;
    }

    line3 = gpiod_chip_get_line(chip, SENSOR3_PIN);
    if (!line3) {
        fprintf(stderr, "Error: gpiod_chip_get_line(%d) failed: %s\n",
                SENSOR3_PIN, strerror(errno));
        goto cleanup;
    }

    /* ---- Request lines ---- */
    if (gpiod_line_request_input(line1, "drv5055va-sensor1") < 0) {
        fprintf(stderr, "Error: gpiod_line_request_input(line1) failed: %s\n",
                strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(line2, "drv5055va-sensor2") < 0) {
        fprintf(stderr, "Error: gpiod_line_request_input(line2) failed: %s\n",
                strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(line3, "drv5055va-sensor3") < 0) {
        fprintf(stderr, "Error: gpiod_line_request_input(line3) failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    printf("Monitoring DRV5055VA sensors on GPIO %d, %d, %d. Press Ctrl-C to exit.\n",
           SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN);
    fflush(stdout);

    /* ---- Main loop ---- */
    while (g_running) {
        int val1 = 0, val2 = 0, val3 = 0;
        int mT1 = 0, mT2 = 0, mT3 = 0;

        if (read_sensor_to_mT(val1, &mT1) != 0) {
            fprintf(stderr, "Warning: sensor1 read failed; skipping log.\n");
        } else if (mT1 < 0) {
            fprintf(stderr, "Warning: sensor1 mT out of range; skipping log.\n");
        } else {
            log_data(val1, val2, val3, mT1, mT2, mT3);
        }

        sleep_ms(SAMPLE_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* ---- Release lines ---- */
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (line3) gpiod_line_release(line3);

    if (chip) gpiod_chip_close(chip);

    return ret;
}

