/*
 * Raspberry Pi 4 Model B – LED control over MQTT
 *
 * Subscribes to “home/led_control” on mqtt.eclipseprojects.io:1883
 * and drives an LED on GPIO17 (BCM) via the pigpio driver API.
 *
 * Build:  gcc -O2 -Wall -Wextra -o led_control led_control.c -lpigpio -lrt
 * Run:    sudo ./led_control
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MQTT_HOST          "mqtt.eclipseprojects.io"
#define MQTT_PORT          1883
#define MQTT_CLIENT_ID     "rpi_led_control"
#define MQTT_TOPIC         "home/led_control"
#define LED_PIN            17
#define JSON_MAX_LEN       1024
#define MAX_RECONNECT_DELAY 60

/* ------------------------------------------------------------------ */
/* Globals                                                             */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MQTT callbacks                                                       */
/* ------------------------------------------------------------------ */

static void on_connect(int client, int rc)
{
    (void)client;
    if (rc != 0) {
        fprintf(stderr, "[ERROR] on_connect() failed: %d\n", rc);
        return;
    }

    /*
     * pigpio gpioWrite() is a direct hardware register write, not a
     * callback.  We use a pigpio callback to set the LED state.
     */
    if (gpioWrite(LED_PIN, 1) != 0) {
        fprintf(stderr, "[ERROR] gpioWrite(1) failed\n");
    }
}

static void on_message(int client, int msg_len, const char *topic,
                       const char *payload, int msg_type)
{
    (void)client;
    (void)msg_len;
    (void)topic;

    /*
     * JSON payload is a null-terminated string.
     * We use a static buffer to hold the payload, but we must
     * ensure it is not overwritten by the next incoming message.
     */
    char *json_buf = malloc(JSON_MAX_LEN);
    if (!json_buf) {
        fprintf(stderr, "[ERROR] malloc(json) failed\n");
        return;
    }
    int n = snprintf(json_buf, JSON_MAX_LEN, "%s", payload);
    if (n < 0 || (size_t)n >= JSON_MAX_LEN) {
        fprintf(stderr, "[ERROR] snprintf(json) failed\n");
        free(json_buf);
        return;
    }

    /*
     * Parse the JSON payload.
     *
     * We use a simple JSON parser that expects a "led_state" key
     * with a boolean value.  If the payload does not contain this
     * key, or if the value is not a boolean, we reject the message.
     */
    bool led_state = false;
    if (json_parse(json_buf, &led_state, "led_state")) {
        fprintf(stderr, "[ERROR] JSON parse failed: %s\n", json_buf);
        free(json_buf);
        return;
    }

    /*
     * Drive the LED.
     */
    if (led_state) {
        if (gpioWrite(LED_PIN, 1) != 0) {
            fprintf(stderr, "[ERROR] gpioWrite(1) failed\n");
        }
    } else {
        if (gpioWrite(LED_PIN, 0) != 0) {
            fprintf(stderr, "[ERROR] gpioWrite(0) failed\n");
        }
    }
}

/* ------------------------------------------------------------------ */
/* JSON parsing                                                         */
/* ------------------------------------------------------------------ */

/*
 * pigpio's json_parse() is a callback-free API that returns 0 on
 * success and -1 on failure.  It is a simple, direct mapping of
 * the MQTT JSON payload to a C struct.
 */
static int json_parse(const char *buf, bool *out, const char *key)
{
    if (!buf || !key || !*key) {
        return -1;
    }

    if (strncmp(key, "led_state", 9) == 0) {
        if (strcmp(key, "led_state") == 0) {
            if (strcmp(key, "true") == 0 || strcmp(key, "false") == 0) {
                *out = true;
                return 0;
            }
        }
    }

    /*
     * If the key is not "led_state", we reject the message.
     */
    return -1;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                              */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    /*
     * pigpio is a library that runs in user space.  We do not have
     * direct control over its resources.  However, we can ensure
     * that the pigpio daemon is not running and that all GPIOs are
     * set to LOW.
     */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                 */
/* ------------------------------------------------------------------ */

int main(void)
{
    /*
     * Signal handlers for graceful shutdown.
     */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /*
     * Initialize pigpio.
     */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /*
     * Configure the LED pin as an output.
     */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "[ERROR] gpioSetMode(%d) failed\n", LED_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /*
     * Ensure the LED is off at startup.
     */
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "[ERROR] gpioWrite(0) failed at startup\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /*
     * Start the reconnection loop.
     */
    int reconnect_delay = 1;
    int reconnect_max = MAX_RECONNECT_DELAY;

    while (g_running) {
        /*
         * Reconnect to MQTT.
         */
        if (reconnect_delay > reconnect_max) {
            fprintf(stderr, "[WARN] Reconnect delay exceeds maximum.\n");
