 * success and -1 on failure.  It is a simple, direct mapping of
 * the MQTT JSON payload to a C struct.
 */
static int json_parse(const char *buf, bool *out, const char *key)
{
    if (!buf || !key || !*key) {
        return -1;
    }

    if (strncmp(key, "led_state", 9) == 0) {
        if (strcmp(key, "led_state") == 0) {
            if (strcmp(key, "true") == 0 || strcmp(key, "false") == 0) {
                *out = true;
                return 0;
            }
        }
    }

    /*
     * If the key is not "led_state", we reject the message.
     */
    return -1;
}

