/* Cleanup                                                              */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    /*
     * pigpio is a library that runs in user space.  We do not have
     * direct control over its resources.  However, we can ensure
     * that the pigpio daemon is not running and that all GPIOs are
     * set to LOW.
     */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    gpioTerminate();
}

