/*
 * KY-038 Sound Sensor Monitor for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   KY-038 DO  -> GPIO17 (BCM)
 *   Alarm LED  -> GPIO18 (BCM)
 *   VCC        -> 3.3 V (Pin 1)
 *   GND        -> GND   (Pin 9)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o sound_monitor sound_monitor.c -lrt -lpigpio -lpthread
 *
 * Run:
 *   sudo ./sound_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SOUND_SENSOR_GPIO 17
#define ALARM_LED_GPIO    18
#define SOUND_EVENT_THRESHOLD 0
#define ALARM_DURATION_MS   1000
#define SAMPLE_DELAY_US     100000   /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read the digital output of the sound sensor.
 * Returns 0 on success (sound detected), 1 on no sound, -1 on error.
 */
static int read_sound_sensor(int gpio_pin)
{
    int level = gpioRead(gpio_pin);
    if (level < 0) {
        fprintf(stderr, "Error: gpioRead failed on GPIO %d (code %d).\n",
                gpio_pin, level);
        return -1;
    }
    return level;
}

/*
 * Trigger the alarm LED.
 * Returns 0 on success, -1 on error.
 */
static int trigger_alarm(int gpio_pin)
{
    if (gpioWrite(gpio_pin, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(1) failed on GPIO %d.\n", gpio_pin);
        return -1;
    }
    gpioDelay(ALARM_DURATION_MS * 1000);
    if (gpioWrite(gpio_pin, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(0) failed on GPIO %d.\n", gpio_pin);
        return -1;
    }
    return 0;
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(SOUND_SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d.\n", SOUND_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ALARM_LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d.\n", ALARM_LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure alarm LED is off at startup */
    if (gpioWrite(ALARM_LED_GPIO, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(0) failed on GPIO %d.\n", ALARM_LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int sound_level = read_sound_sensor(SOUND_SENSOR_GPIO);

        if (sound_level == 0) {
            printf("Sound detected! Triggering alarm.\n");
            if (trigger_alarm(ALARM_LED_GPIO) != 0) {
                fprintf(stderr, "Error: Failed to trigger alarm.\n");
            }
        } else if (sound_level == 1) {
            printf("Sound threshold exceeded. Alarm triggered.\n");
            if (trigger_alarm(ALARM_LED_GPIO) != 0) {
                fprintf(stderr, "Error: Failed to trigger alarm.\n");
            }
        }

        /* Delay between samples to avoid busy-waiting */
        gpioDelay(SAMPLE_DELAY_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    gpioWrite(ALARM_LED_GPIO, 0);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

