#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define GPIO_CHIP_PATH "/dev/gpiochip0"
#define GPIO_LINE_OFFSET 17
#define LOG_FILE "/var/log/vibration_shutdown.log"
#define SHUTDOWN_CMD "sudo shutdown -h now"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[unknown time] %s\n", message);
    }
    if (fclose(fp) != 0) {
        perror("fclose log file");
        return -1;
    }
    return 0;
}

static int log_shutdown_command(void) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] Vibration detected, shutting down...\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec);
    } else {
        fprintf(fp, "[unknown time] Vibration detected, shutting down...\n");
    }
    if (fclose(fp) != 0) {
        perror("fclose log file");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction SIGINT");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction SIGTERM");
        return EXIT_FAILURE;
    }

    struct gpio_chip *chip = gpiochip_open(GPIO_CHIP_PATH);
    if (!chip) {
        perror("gpiochip_open");
        return EXIT_FAILURE;
    }

    struct gpio_line *line = gpio_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpio_chip_get_line");
        gpiochip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpio_line_request_falling_edge_events(line, "vibration-monitor") < 0) {
        perror("gpio_line_request_falling_edge_events");
        gpiochip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Monitoring vibration sensor on GPIO%d. Press Ctrl+C to exit.\n", GPIO_LINE_OFFSET);

    while (program_running) {
        int ret = gpio_line_event_wait(line, NULL);
        if (ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("gpio_line_event_wait");
            break;
        }
        if (ret == 0) {
            continue;
        }

        struct gpio_line_event event;
        if (gpio_line_event_read(line, &event) < 0) {
            perror("gpio_line_event_read");
            break;
        }

        if (event.event_type == GPIO_LINE_EVENT_FALLING_EDGE) {
            char message[128];
            snprintf(message, sizeof(message), "Vibration detected on GPIO%d", GPIO_LINE_OFFSET);
            if (log_event(message) < 0) {
                fprintf(stderr, "Failed to log event to log file.\n");
            }
            if (log_shutdown_command() < 0) {
                fprintf(stderr, "Failed to initiate shutdown command.\n");
            }
        }
    }

    if (gpio_line_release(line) < 0) {
        perror("gpio_line_release");
    }
    if (gpiochip_close(chip) < 0) {
        perror("gpiochip_close");
    }

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

