/*
 * BMP280 Barometric Sensor Logger for Raspberry Pi 4 Model B
 *
 * Reads raw data from the BMP280 on I2C bus 1 (SDA=GPIO2, SCL=GPIO3),
 * computes altitude from raw pressure and temperature, and logs the
 * computed altitude to a file named "altitude_log.txt".
 *
 * Build:  gcc -O2 -Wall -Wextra -o bmp280_logger bmp280_logger.c
 * Run:    sudo ./bmp280_logger
 */

