#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define BMP280_ADDR    0x76
#define BMP280_REG_ID   0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_CTRL1  0xF4
#define BMP280_REG_CTRL2  0xF5
#define BMP280_REG_CTRL3  0xF6
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_CALIB   0x88

#define BMP280_CHIP_ID    0x59
#define BMP280_RESET_CMD  0xB6

#define LOG_FILENAME    "altitude_log.txt"
#define SAMPLE_INTERVAL 5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Calibration data (16-bit little-endian, big-endian)                   */
/* ------------------------------------------------------------------ */
typedef struct {
    uint16_t dig_T1;
    int16_t  dig_T2;
    int16_t  dig_T3;
    uint16_t dig_P1;
    int16_t  dig_P2;
    int16_t  dig_P3;
    int16_t  dig_P4;
    int16_t  dig_P5;
    int16_t  dig_P6;
    int16_t  dig_P7;
    int16_t  dig_P8;
    int16_t  dig_P9;
} bmp280_calib_t;

static const bmp280_calib_t bmp280_cal = {
    .dig_T1 = 0,
    .dig_T2 = 0,
    .dig_T3 = 0,
    .dig_P1 = 0,
    .dig_P2 = 0,
    .dig_P3 = 0,
    .dig_P4 = 0,
    .dig_P5 = 0,
    .dig_P6 = 0,
    .dig_P7 = 0,
    .dig_P8 = 0,
    .dig_P9 = 0
};

/* ------------------------------------------------------------------ */
/* Signal handling                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                          */
/* ------------------------------------------------------------------ */
static int i2c_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg-select 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write block-select 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C block-read 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* BMP280 calibration                                                  */
/* ------------------------------------------------------------------ */
static int read_calibration(int fd, bmp280_calib_t *cal)
{
    uint8_t buf[24];
    if (i2c_read_block(fd, BMP280_REG_CALIB, buf, sizeof(buf)) < 0)
        return -1;

    cal->dig_T1 = (uint16_t)(buf[0]  | (buf[1]  << 8));
    cal->dig_T2 = (int16_t)(buf[2]  | (buf[3]  << 8));
    cal->dig_T3 = (int16_t)(buf[4]  | (buf[5]  << 8));
    cal->dig_P1 = (uint16_t)(buf[6]  | (buf[7]  << 8));
    cal->dig_P2 = (int16_t)(buf[8]  | (buf[9]  << 8));
    cal->dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    cal->dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    cal->dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    cal->dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    cal->dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    cal->dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    cal->dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));

    return 0;
}

/* ------------------------------------------------------------------ */
/* BMP280 raw data                                                      */
/* ------------------------------------------------------------------ */
static int read_raw_data(int fd, int32_t *raw_pressure, int32_t *raw_temperature)
{
    uint8_t buf[6];

    if (i2c_read_block(fd, BMP280_REG_PRESS_MSB, buf, sizeof(buf)) < 0)
        return -1;

    *raw_pressure = (int32_t)((buf[0] << 12) | (buf[1] << 4) | (buf[2] >> 4));
    *raw_temperature = (int32_t)((buf[3] << 12) | (buf[4] << 4) | (buf[5] >> 4));

    /* BMP280: T_MSB, T_LSB, P_MSB, P_LSB */
    int32_t t_msb = *raw_temperature;
    int32_t t_lsb = *raw_temperature;
    int32_t p_msb = *raw_pressure;
    int32_t p_lsb = *raw_pressure;

    /* T_MSB, T_LSB: big-endian */
    t_msb = (t_msb << 8) | (t_lsb >> 8);
    t_lsb = (t_lsb << 8) | (t_msb >> 8);
    p_msb = (p_msb << 8) | (p_lsb >> 8);
    p_lsb = (p_lsb << 8) | (p_msb >> 8);

    /* P_MSB, P_LSB: big-endian */
    p_msb = (p_msb << 8) | (p_lsb >> 8);
    p_lsb = (p_lsb << 8) | (p_msb >> 8);

    /* T_MSB, T_LSB: signed 16-bit */
    *raw_temperature = (int16_t)((t_msb >> 4) | (t_msb << 4));
    *raw_temperature &= 0x0FFF;

    /* P_MSB, P_LSB: signed 16-bit */
    *raw_pressure = (int16_t)((p_msb >> 4) | (p_msb << 4));
    *raw_pressure &= 0x0FFF;

    return 0;
}

/* ------------------------------------------------------------------ */
/* BMP280 temperature (Celsius)                                         */
/* ------------------------------------------------------------------ */
static float bmp280_temperature(int32_t raw_temp)
{
    int32_t var1, var2;
    var1 = ((((raw_temp >> 3) - ((int32_t)bmp280_cal.dig_T1 << 1))) *
            ((int32_t)bmp280_cal.dig_T2)) >> 11;
    var2 = (((((raw_temp >> 4) - ((int32_t)bmp280_cal.dig_T1)) *
              ((raw_temp >> 4) - ((int32_t)bmp280_cal.dig_T1))) >> 12) *
            ((int32_t)bmp280_cal.dig_T3)) >> 14;
    int32_t t_fine = var1 + var2;
    return (float)(t_fine * 5 + 128) / 100.0f;
}

/* ------------------------------------------------------------------ */
/* BMP280 pressure (Pa)                                                 */
/* ------------------------------------------------------------------ */
static int32_t bmp280_pressure(int32_t raw_pressure)
{
    int32_t var1, var2;
    var1 = ((((raw_pressure >> 11) - ((int32_t)bmp280_cal.dig_P1 << 1))) *
            ((int32_t)bmp280_cal.dig_P2)) >> 12;
    var2 = (((((raw_pressure >> 13) - ((int32_t)bmp280_cal.dig_P1)) *
              ((raw_pressure >> 13) - ((int32_t)bmp280_cal.dig_P1))) >> 14) *
            ((int32_t)bmp280_cal.dig_P3)) >> 15;
    var1 = (var1 * (int32_t)bmp280_cal.dig_P4) >> 4;
    var2 = (var2 * (int32_t)bmp280_cal.dig_P5) >> 5;
    var1 += ((int32_t)bmp280_cal.dig_P6 * var2) >> 2;
    var2 = ((int32_t)bmp280_cal.dig_P7 * var1) >> 13;
    var1 += ((int32_t)bmp280_cal.dig_P8 * var2) >> 3;
    var2 = ((int32_t)bmp280_cal.dig_P9 * var1) >> 14;
    int32_t p = (int32_t)((var1 + var2 + 1) >> 2);
    return (int32_t)(p / 100);
}

/* ------------------------------------------------------------------ */
/* Log altitude (m)                                                    */
/* ------------------------------------------------------------------ */
static int log_altitude(float altitude)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);

    if (fprintf(g_log_fp, "%s, %.2f\n", ts, altitude) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        i2c_write_reg(g_i2c_fd, BMP280_REG_RESET, BMP280_RESET_CMD);
        usleep(10000);
        i2c_write_reg(g_i2c_fd, BMP280_REG_CTRL1, 0x06);
        i2c_write_reg(g_i2c_fd, BMP280_REG_CTRL2, 0x19);
        i2c_write_reg(g_i2c_fd, BMP280_REG_CTRL3, 0x27);
        i2c_write_reg(g_i2c_fd, BMP280_REG_CTRL3, 0x27);
        i2c_write_reg(g_i2c_fd, BMP280_REG_CTRL3, 0x27);
        i2c_write_reg(g_i2c_fd, BMP280_REG_CTRL3, 0x27);
        i2c_write_reg(g_i2c_fd, BMP280_REG_CTRL3, 0x27);
        i2c_write_reg(g_i2c_fd, BMP280_REG_CTRL3, 0x27);
        i2c_write_reg(g_i2c_fd, BMP280_REG_CTRL3, 0x27);
        i2c_write_reg(g_i2c_fd, BMP280_REG_CTRL3, 0x27);
        i2c_write_reg(g_i2c_fd, BMP280_REG_CTRL3, 0x27);
        i2c_write_reg(g_i2c_fd, BMP280_REG_CTRL3, 0x27);
        i2c_write_reg(g_i2c_fd, BMP280_REG_CTRL3, 0x27);
