/*
 * Raspberry Pi 3 Model B+ – LM35 Temperature Logger
 *
 * Reads an MCP3008 10-bit ADC via SPI0 (CE0, GPIO 8, 9, 10, 11) and stores
 * the temperature in a circular buffer.  Prints each value to the console
 * every 5 s.  Overwrites the buffer with the oldest data when it wraps.
 *
 * Build:  gcc -O2 -Wall -Wextra -o temp_logger temp_logger.c -lm
 * Run:    sudo ./temp_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0
#define SPI_CS_PIN      8
#define BUFFER_SIZE     120
#define SAMPLE_INTERVAL 5
#define LOG_FILE        "temp_log.dat"

/* ---- Circular buffer ---- */

typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static CircularBuffer buffer;

static void buffer_init(CircularBuffer *cb)
{
    cb->head = 0;
    cb->count = 0;
}

static void buffer_push(CircularBuffer *cb, float value)
{
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

static void buffer_print(const CircularBuffer *cb)
{
    if (cb->count == 0)
        return;

    printf("Temperature: ");
    for (int i = 0; i < cb->count; i++)
        printf("%.2f ", cb->buffer[i]);
    printf("\n");
}

/* ---- SPI helpers ---- */

static int spi_init(void)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = len;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- MCP3008 read ---- */

static int mcp3008_read(int fd, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    if (spi_transfer(fd, tx, rx, 3) < 0)
        return -1;

    /* 10-bit result: bits 1..0 of rx[1] are the MSB, rx[2] is the LSB */
    int adc = ((rx[1] & 0x03) << 8) | rx[2];
    return adc;
}

/* ---- Signal handling ---- */

static void signal_handler(int sig)
{
    (void)sig;
    fprintf(stderr, "\nCaught signal, cleaning up...\n");
    close(spi_fd);
    exit(0);
}

/* ---- Main ---- */

int main(void)
{
    /* ---- Circular buffer ---- */
    buffer_init(&buffer);

    /* ---- SPI ---- */
    spi_fd = spi_init();
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    /* ---- Main loop ---- */
    while (1) {
        int adc = mcp3008_read(spi_fd, 0);
        if (adc < 0) {
            fprintf(stderr, "SPI read error, skipping sample.\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        float temperature = (float)adc / 1023.0f * 100.0f;
        buffer_push(&buffer, temperature);

        buffer_print(&buffer);

        sleep(SAMPLE_INTERVAL);
    }

    /* ---- Cleanup ---- */
    close(spi_fd);
    return EXIT_SUCCESS;
}

