#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define I2C_BUS "/dev/i2c-1"
#define SPI_DEVICE "/dev/spidev0.0"
#define LOG_FILE "environmental_log.txt"
#define SAMPLE_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_byte(int fd, unsigned char reg) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write to register 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    char val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C read from register 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return (int)val;
}

static int spi_read_adc(int fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }
    unsigned char tx[2] = {0x01, (unsigned char)(0x80 | (channel << 4)));
    unsigned char rx[2] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 2,
        .speed_hz = 1000000,
        .delay_usecs = 0,
        .bits_per_word = 8,
        .cs_change = 0,
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[0];
}

static int log_data(const char *filename, int light_lux, int sound_raw) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", filename, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Light: %d lux, Sound: %d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, light_lux, sound_raw);
    } else {
        fprintf(fp, "Error: failed to get local time\n");
    }
    fclose(fp);
    return 0;
}

int main(void) {
