    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return 1;
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, 0x1F) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus access: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &(struct spi_ioc_transaction_block){
        .tx_buf = NULL,
        .rx_buf = NULL,
        .len = 0,
        .speed_hz = 1000000,
        .delay_usecs = 0,
        .bits_per_word = 8,
        .cs_change = 0,
    }) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }

    while (running) {
        int light_lux = i2c_read_byte(i2c_fd, 0x00);
        if (light_lux < 0) {
            fprintf(stderr, "I2C read error; continuing\n");
        } else {
            int sound_raw = spi_read_adc(spi_fd, 0);
            if (sound_raw < 0) {
                fprintf(stderr, "SPI read error; continuing\n");
            } else {
                log_data(LOG_FILE, light_lux, sound_raw);
            }
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");
    close(i2c_fd);
    close(spi_fd);
    return 0;
}

