/*
 * flame_monitor.c — Raspberry Pi 5
 *
 * Reads the digital output of a Keyes KY-026 flame sensor on BCM GPIO 17
 * (physical pin 11) and logs each reading to flame_events.log.
 *
 * Build:  gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lpigpio -lrt
 * Run:    sudo ./flame_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 17
#define LOG_FILE        "flame_events.log"
#define POLL_INTERVAL_S 1

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(FILE *fp, const char *timestamp, int pin, int state)
{
    if (!fp)
        return;

    fprintf(fp, "%s,GPIO%d,%d\n", timestamp, pin, state);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers ---------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO pin as input with pull-down ---------------- */
    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d.\n", FLAME_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for GPIO %d.\n", FLAME_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file -------------------------------------------- */
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Main polling loop ---------------------------------------- */
    while (g_running) {
        int level = gpioRead(FLAME_SENSOR_PIN);
        if (level < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO %d (code %d).\n",
                    FLAME_SENSOR_PIN, level);
            fclose(fp);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        char ts[32];
        time_t now = time(NULL);
        if (now == (time_t)-1) {
            perror("time");
            fclose(fp);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S",
                     localtime(&now)) == 0) {
            fprintf(stderr, "Error: strftime failed.\n");
            fclose(fp);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        log_event(fp, ts, FLAME_SENSOR_PIN, level);

        /*
         * KY-026 is active-HIGH: a HIGH reading indicates a flame.
         * We log both the state and the alarm message.
         */
        if (level == 1) {
            printf("[%s] Flame detected on GPIO %d\n", ts, FLAME_SENSOR_PIN);
            log_event(fp, ts, FLAME_SENSOR_PIN, 1);
        }
        fflush(stdout);
        sleep(POLL_INTERVAL_S);
    }

    /* ---- Cleanup ----------------------------------------------- */
    fclose(fp);
    gpioTerminate();
    return EXIT_SUCCESS;
}

