#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define SPI_DELAY_US 10
#define LOG_FILE "soil_data.txt"
#define SLEEP_SEC 60

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    unsigned char mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    unsigned char bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    unsigned char speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int spi_read_channel(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .delay_usecs = SPI_DELAY_US,
        .bits_per_word = SPI_BITS,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int read_soil_data(int sensor_id, int *moisture) {
    int adc_value = spi_read_channel(sensor_id);
    if (adc_value < 0) {
        fprintf(stderr, "Error reading ADC value for sensor %d\n", sensor_id);
        return -1;
    }

    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Invalid ADC value for sensor %d (value: %d)\n", sensor_id, adc_value);
        return -1;
    }

    *moisture = (adc_value / 1023.0) * 100.0;
    return 0;
}

static int log_data(int sensor_id, int moisture) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        perror("localtime failed");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, %d\n", timestamp, moisture) < 0) {
        perror("Failed to write to log file");
        return -1;
    }

    if (fflush(log_file) != 0) {
        perror("Failed to flush log file");
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int moisture[3] = {0, 0, 0};

        for (int i = 0; i < 3; i++) {
            if (read_soil_data(i, &moisture[i]) < 0) {
                fprintf(stderr, "Error reading sensor %d\n", i);
                break;
            }
        }

        if (log_data(0, moisture[0]) < 0 ||
            log_data(1, moisture[1]) < 0 ||
            log_data(2, moisture[2]) < 0) {
            fprintf(stderr, "Error logging data\n");
            break;
        }

        sleep(SLEEP_SEC);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

