#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/*
 * Light sequencer for four Songle SRD-05VDC-SL relays on BCM GPIO 17, 22, 23,
 * 24.  Each relay is initially set to inactive (LOW).  The main loop
 * sequentially activates and deactivates each relay for one second,
 * then waits one second before repeating.
 */

#define NUM_RELAYS 4

static const int relay_pins[NUM_RELAYS] = {17, 22, 23, 24};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/*
 * Activate a relay for one second.
 * Returns 0 on success, -1 on failure.
 */
static int activate_relay(int pin)
{
    if (gpioWrite(pin, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(pin=%d, 1) failed\n", pin);
        return -1;
    }
    return 0;
}

/*
 * Deactivate a relay.
 * Returns 0 on success, -1 on failure.
 */
static int deactivate_relay(int pin)
{
    if (gpioWrite(pin, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(pin=%d, 0) failed\n", pin);
        return -1;
    }
    return 0;
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure relay pins as outputs */
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Error: gpioSetMode(pin=%d, OUTPUT) failed\n",
                    relay_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("Light sequencer started.  Relays %d, %d, %d, %d on BCM pins %d, %d, %d, %d.\n",
           NUM_RELAYS, relay_pins[0], relay_pins[1], relay_pins[2], relay_pins[3],
           relay_pins[0], relay_pins[1], relay_pins[2], relay_pins[3]);

    /* Main loop */
    while (running) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            if (activate_relay(relay_pins[i]) != 0) {
                fprintf(stderr, "Error: relay %d activation failed\n", i + 1);
                break;
            }
            printf("Relay %d activated for 1 s.\n", i + 1);
            sleep(1);
            if (!running) {
                break;
            }
            if (deactivate_relay(relay_pins[i]) != 0) {
                fprintf(stderr, "Error: relay %d deactivation failed\n", i + 1);
                break;
            }
            printf("Relay %d deactivated.\n", i + 1);
            sleep(1);
        }
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioWrite(relay_pins[i], 0) < 0) {
            fprintf(stderr, "Warning: gpioWrite(pin=%d, 0) failed during shutdown\n",
                    relay_pins[i]);
        }
    }
    gpioTerminate();
    printf("Light sequencer terminated.\n");
    return EXIT_SUCCESS;
}

