/*
 * sound_sensor.c — Raspberry Pi 4 Model B
 *
 * Reads the analog output of a Keyes KY-038 sound sensor on MCP3008 channel 0
 * via SPI CE0 (GPIO 8) at 1 MHz, logs events to sound_events.log, and
 * turns on an LED on GPIO 16 for 500 ms when the measured value exceeds a
 * defined threshold.
 *
 * Build:  gcc -O2 -Wall -Wextra -o sound_sensor sound_sensor.c -lm
 * Run:    ./sound_sensor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0
#define LED_GPIO        16
#define DEBOUNCE_MS     500
#define SAMPLE_MS       10
#define LOG_FILE        "sound_events.log"

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0–1023 on success, -1 on SPI error, -2 on invalid channel.
 */
static int read_mcp3008(int spi_fd, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read:
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2]
     */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int value = ((rx[1] & 0x03) << 8) | rx[2];
    return value;
}

static void log_event(const char *filename)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                filename, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return;
    }

    fprintf(fp, "%s: Sound sensor threshold exceeded\n", ts);
    fclose(fp);
}

int main(void)
{
    /* --- Install SIGINT handler for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open SPI device --- */
    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Configure SPI mode --- */
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    /* --- Configure bits per word --- */
    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    /* --- Configure speed --- */
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    /* --- Open LED GPIO as output --- */
    if (gpio_set_mode(LED_GPIO, OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output: %s\n",
                LED_GPIO, strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        int value = read_mcp3008(spi_fd, 0);
        if (value < 0) {
            fprintf(stderr, "SPI read error; retrying in %d ms\n", DEBOUNCE_MS);
            usleep(DEBOUNCE_MS * 1000);
            continue;
        }

        if (value > 0) {
            printf("Sound sensor threshold exceeded (value: %d)\n", value);
            log_event(LOG_FILE);

            /* Turn on LED for 500 ms */
            if (gpio_set_value(LED_GPIO, 1) < 0) {
                fprintf(stderr, "Failed to turn on LED: %s\n", strerror(errno));
            } else {
                printf("LED turned on for 500 ms\n");
            }

            /* Debounce delay */
            usleep(DEBOUNCE_MS * 1000);

            if (gpio_set_value(LED_GPIO, 0) < 0) {
                fprintf(stderr, "Failed to turn off LED: %s\n", strerror(errno));
            }
        }

        usleep(SAMPLE_MS * 1000);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    gpio_set_value(LED_GPIO, 0);
    close(spi_fd);
    return EXIT_SUCCESS;
}

