/*
 * rain_monitor.c
 *
 * Reads the analog output of a Grove Rain Sensor through an MCP3008
 * on SPI channel 0 at 1 MHz mode 0, logs the rain level and timestamp
 * to rain_log.txt, and controls a L298N-based motor driver to open or
 * close a window based on the rain level.
 *
 * Build: gcc -o rain rain.c -lthe -lrt -lpthread
 * Run:   sudo ./rain
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#include <pigpio.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        0
#define SPI_BITS        8
#define SPI_BITS_MASK   (1 << SPI_BITS)
#define SPI_CHIP_ID     0

#define MCP3008_CHANNEL 0
#define RAIN_THRESHOLD  5
#define MOTOR_PWM_DUTY  150
#define MOTOR_PWM_RANGE 255
#define MOTOR_OPEN_DURATION_S 3
#define MOTOR_CLOSE_DURATION_S 3
#define LOG_FILE        "rain_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */
static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Error: cannot open %s: %s\n",
                SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error: cannot set SPI mode: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error: cannot set SPI bits per word: %s\n",
                strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error: cannot set SPI speed: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

static int spi_read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: 10-bit value in rx[1] and rx[2].
     */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error: SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Motor driver                                                        */
/* ------------------------------------------------------------------ */
static void motor_forward(void)
{
    if (gpioPWM(MOTOR_PWM_PIN, MOTOR_PWM_DUTY) < 0) {
        fprintf(stderr, "Error: gpioPWM failed for motor forward\n");
        return;
    }
    gpioDelay(MOTOR_OPEN_DURATION_S * 1000000);
    if (gpioPWM(MOTOR_PWM_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioPWM failed for motor stop\n");
    }
}

static void motor_reverse(void)
{
    if (gpioPWM(MOTOR_PWM_PIN, MOTOR_PWM_DUTY) < 0) {
        fprintf(stderr, "Error: gpioPWM failed for motor reverse\n");
        return;
    }
    gpioDelay(MOTOR_CLOSE_DURATION_S * 1000000);
    if (gpioPWM(MOTOR_PWM_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioPWM failed for motor stop\n");
    }
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_rain_level(int rain_level)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s, Rain Level: %d\n", timestamp, rain_level) < 0) {
        fprintf(stderr, "Error: fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "Error: fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure motor pins as outputs */
    if (gpioSetMode(MOTOR_OPEN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for motor open\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_CLOSE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for motor close\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure window motor pins as outputs */
    if (gpioSetMode(MOTOR_OPEN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for window open\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_CLOSE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for window close\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize SPI */
    if (spi_init() < 0) {
        fprintf(stderr, "Error: SPI initialization failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction(SIGTERM) failed: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(stdout, "Rain monitor started. Logging to %s\n", LOG_FILE);
    fprintf(stdout, "Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        int rain_level = gpioRead(MOTOR_OPEN_PIN);
        if (rain_level < 0) {
            fprintf(stderr, "Error: gpioRead failed for rain level\n");
            break;
        }

        if (log_rain_level(rain_level) < 0) {
            fprintf(stderr, "Error: log_rain_level failed\n");
            break;
        }

        if (rain_level > RAIN_THRESHOLD) {
            motor_forward();
        } else {
            motor_reverse();
        }

        gpioDelay(MOTOR_OPEN_DURATION_S * 1000000);
        if (!g_running) {
            break;
        }
    }

    fprintf(stdout, "\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

