#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define GPIO_PIN 17
#define LOG_FILE "distance_log.txt"
#define DISTANCE_THRESHOLD 200
#define RETRY_DELAY_SEC 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_distance(int distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, Distance: %d mm\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpio_set_mode(GPIO_PIN, GPIO_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as input: %s\n", GPIO_PIN, strerror(errno));
        return EXIT_FAILURE;
    }

    printf("Feeder control started. GPIO%d = digital input. Logging to %s\n",
           GPIO_PIN, LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    int last_state = -1;
    int distance = -1;

    while (running) {
        int val = gpio_get_value(GPIO_PIN);
        if (val < 0) {
            fprintf(stderr, "Error reading GPIO%d: %s\n", GPIO_PIN, strerror(errno));
            sleep(RETRY_DELAY_SEC);
            continue;
        }

        if (val == 0) {
            distance = 1;
        } else {
            distance = 0;
        }

        if (distance < 0) {
            fprintf(stderr, "Error reading distance\n");
            sleep(RETRY_DELAY_SEC);
            continue;
        }

        if (log_distance(distance) != 0) {
            fprintf(stderr, "Error logging distance\n");
        }

        if (distance < DISTANCE_THRESHOLD) {
            printf("Feeder Activated\n");
        } else {
            printf("Feeder Idle\n");
        }

        last_state = val;
        sleep(RETRY_DELAY_SEC);
    }

    printf("\nExiting gracefully...\n");
    gpio_set_mode(GPIO_PIN, GPIO_INPUT);
    return EXIT_SUCCESS;
}

