        if (gpio_output(gpio, 0) < 0) {
            fprintf(stderr, "gpio_output(0) failed: %s\n", strerror(errno));
            return -1;
        }
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Cannot open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        fclose(g_log_file);
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        fclose(g_log_file);
        return EXIT_FAILURE;
    }

    /* Initialize SPI */
    int spi_fd = spi_open(SPI_DEVICE, SPI_SPEED_HZ, SPI_BITS, SPI_MODE);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        fclose(g_log_file);
        return EXIT_FAILURE;
    }

    /* Initialize pump GPIO */
    if (gpio_setup_output(PUMP_GPIO, 0) < 0) {
        fprintf(stderr, "gpio_setup_output failed for GPIO %d\n", PUMP_GPIO);
        close(spi_fd);
        fclose(g_log_file);
        return EXIT_FAILURE;
    }

    printf("Soil Moisture Monitor started. Logging to '%s'. Press Ctrl+C to exit.\n", LOG_FILE);

    while (g_running) {
        int adc_value = mcp3008_read(spi_fd, 0);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error, skipping sample\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        float moisture = (float)adc_value / ADC_MAX * ADC_VREF;
        int pump_state = (moisture < ADC_VREF / 2.0f) ? 1 : 0;

        if (control_pump(PUMP_GPIO, pump_state) < 0) {
            fprintf(stderr, "Pump control failed, exiting\n");
            break;
        }

        if (log_data(g_log_file, moisture, pump_state) < 0) {
