 * through an MCP3008 ADC on SPI0 CE0.
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3V (Pin 1)
 *   MCP3008 VREF -> 3.3V (Pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3008 CH0  -> Sensor analog output
 *   LED Anode   -> BCM GPIO21 (via 330 ohm resistor)
 *
 * Build: gcc -O2 -Wall -o magnetic_reader magnetic_reader.c -lpigpio -lrt
 * Run:   sudo ./magnetic_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL      0
#define SPI_BAUD         1000000   /* 1 MHz */
#define SPI_FLAGS        0         /* Mode 0, active-low CE */
#define ADC_CHANNEL      0         /* MCP3008 channel 0 */
#define ADC_MAX_VALUE    1023
#define LOG_FILE         "magnetic_log.txt"
#define THRESHOLD        10.0f     /* mT */
#define SAMPLE_PERIOD_US 100000   /* 100 ms */
#define LED_GPIO         21

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MCP3008 single-ended read                                           */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | (channel << 4))    (single-ended + channel)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: rx[1] bits 1-0 are the lower 2 bits of the 10-bit result,
     *         rx[2] is the 8-bit result.
     */
    char tx[3] = { 0x01, (char)((0x08 | (channel << 4)) & 0x0F), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Convert ADC value to magnetic field strength (mT)                    */
/* ------------------------------------------------------------------ */
static float adc_to_magnetic_field(int adc_value)
{
    /*
     * TI DRV5055VA:
     *   Vdd = 3.3V, Vref = 3.3V, GND = 0V
     *   Sensor output = Vout / (2^10)
     *   Sensor output = Vout / 1024
     *   Field strength = Vout / 1023 * 0.01
     */
    float voltage = (float)adc_value / ADC_MAX_VALUE * 3.3f;
    return (voltage / 1023.0f) * 0.01f;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped reading to the log file                        */
/* ------------------------------------------------------------------ */
static void log_reading(float magnetic_field)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("Error getting local time");
        fclose(fp);
        return;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Magnetic Field: %.2f mT\n", timestamp, magnetic_field);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI0 CE0 at 1 MHz, mode 0, active-low CE */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO as output, initially off */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", LED_GPIO);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    printf("Magnetic field reader started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: ADC read failed; skipping sample\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float magnetic_field = adc_to_magnetic_field(adc_value);

        log_reading(magnetic_field);

        if (magnetic_field > THRESHOLD) {
            gpioWrite(LED_GPIO, 1);
        } else {
            gpioWrite(LED_GPIO, 0);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Graceful cleanup */
    printf("\nShutting down...\n");
    gpioWrite(LED_GPIO, 0);
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

