/*
 * Raspberry Pi 3 Model B+ – MLX91209 Current Sensor Reader
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3008 CH0  -> MLX91209 VOUT (0-5 V)
 *   MCP3008 CH1  -> GND (sensor GND)
 *   MCP3008 CH2  -> GND (sensor GND)
 *   MCP3008 CH3  -> GND (sensor GND)
 *   MCP3008 CH4  -> GND (sensor GND)
 *   MCP3008 CH5  -> GND (sensor GND)
 *   MCP3008 CH6  -> GND (sensor GND)
 *   MCP3008 CH7  -> GND (sensor GND)
 *   MCP3008 CH8  -> GND (sensor GND)
 *   MCP3008 CH9  -> GND (sensor GND)
 *   MCP3008 CH10 -> GND (sensor GND)
 *   MCP3008 CH11 -> GND (sensor GND)
 *   MCP3008 CH12 -> GND (sensor GND)
 *   MCP3008 CH13 -> GND (sensor GND)
 *   MCP3008 CH14 -> GND (sensor GND)
 *   MCP3008 CH15 -> GND (sensor GND)
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 GND  -> GND
 *
 * Build: gcc -O2 -Wall -o current_reader current_reader.c -lpigpio -lrt
 * Run:   sudo ./current_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define SPI_DEVICE        "/dev/spidev0.0"
#define SPI_SPEED_HZ      1000000   /* 1 MHz */
#define SPI_MODE          0          /* CPOL=0, CPHA=0 */
#define SPI_BITS          8
#define ADC_CHANNEL       0          /* MCP3008 channel 0 */
#define ADC_MAX_VALUE     1023       /* 10-bit ADC */
#define LOG_FILE_NAME     "current_log.txt"
#define SAMPLE_INTERVAL_S 1
#define SAMPLE_COUNT      (SAMPLE_INTERVAL_S * 1000)

/* ----------------------------- Globals ---------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static FILE *g_log_file = NULL;

/* ----------------------------- Prototypes -------------------------------- */

static void signal_handler(int sig);
static int  initialize_spi(void);
static int  initialize_gpio(void);
static int  initialize_log_file(void);
static int  read_adc_channel(int channel);
static float convert_adc_to_current(int adc_value);
static int  log_data(float current_A);
static void cleanup(void);

/* ----------------------------- Signal handler ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- SPI initialization ----------------------------- */

static int initialize_spi(void)
{
    g_spi_handle = spiOpen(SPI_DEVICE, SPI_SPEED_HZ, SPI_MODE, 0);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (handle=%d)\n", g_spi_handle);
        return -1;
    }
    return 0;
}

/* ----------------------------- GPIO initialization ----------------------------- */

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: gpioInitialise failed\n");
        return -1;
    }

    /* Configure GPIO17 as output, initially low */
    if (gpioSetMode(17, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO17\n");
        return -1;
    }
    if (gpioWrite(17, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite failed for GPIO17\n");
        return -1;
    }

    /* Allow the sensor to settle after power-on */
    gpioDelay(100000); /* 100 ms */
    return 0;
}

/* ----------------------------- Logging ----------------------------------- */

static int initialize_log_file(void)
{
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        return -1;
    }
    return 0;
