 * Raspberry Pi 5 - Dual Omron B5W-DB01 Proximity Sensor Monitor
 *
 * Wiring:
 *   Sensor 1 (BCM 4)  -> GPIO4 (input)
 *   Sensor 2 (BCM 17) -> GPIO17 (input)
 *   Sensor 1 OUT  -> BCM 4 (active-low)
 *   Sensor 2 OUT  -> BCM 17 (active-low)
 *   Sensor 1 VCC  -> 3.3 V
 *   Sensor 2 VCC  -> 3.3 V
 *   Sensor 1 GND  -> GND
 *   Sensor 2 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o b5w_monitor b5w_monitor.c -lrt
 * Run:    sudo ./b5w_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <stdbool.h>
#include <pigpio.h>

#define SENSOR1_PIN  4
#define SENSOR2_PIN  17

#define DEBOUNCE_US  5000   /* 5 ms between readings */
#define POLL_US      10000 /* 10 ms between polls */
#define LOG_INTERVAL 1     /* seconds between log entries */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_state(int sensor1, int sensor2)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (t == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    printf("[%s] Sensor 1: %s  Sensor 2: %s\n",
           ts,
           sensor1 ? "Object detected" : "No object",
           sensor2 ? "Object detected" : "No object");
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Sensor reading                                                      */
/* ------------------------------------------------------------------ */
static int read_sensor(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "gpioRead(%d) failed: %s\n", pin, strerror(errno));
        return -1;
    }
    return v;
}

/* ------------------------------------------------------------------ */
/* Debounce                                                            */
/* ------------------------------------------------------------------ */
static int debounce(int pin, int *last_val, int *debounced)
{
    int v = read_sensor(pin);
    if (v < 0)
        return -1;

    if (v == 0) {
        *debounced = 1;
        return 0;
    }

    if (*last_val == 0) {
        *debounced = 1;
        return 0;
    }

    *debounced = 0;
    return 1;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install signal handlers ----------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio ----------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --------------------------------------- */
    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(SENSOR1) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(SENSOR2) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Enable internal pull-up (B5W-DB01 has no analog output) --- */
    if (gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(SENSOR1) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(SENSOR2) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Main polling loop ----------------------------------------- */
    while (g_running) {
        int v1 = debounce(SENSOR1_PIN, &last_val1, &debounced1);
        int v2 = debounce(SENSOR2_PIN, &last_val2, &debounced2);

        if (v1 < 0 || v2 < 0) {
            fprintf(stderr, "Debounce failed; continuing.\n");
            gpioDelay(POLL_US);
            continue;
        }

        if (v1 == 0 && v2 == 0) {
            log_state(v1, v2);
            if (v1 == v2)
                printf("ALERT: Both sensors detect object\n");
            else
                printf("ALERT: Sensor 1 and Sensor 2 report object\n");
            fflush(stdout);
            gpioDelay(LOG_INTERVAL * 1000);
            continue;
        }

        if (v1 == 1 && v2 == 1) {
            log_state(v1, v2);
            printf("ALERT: Both sensors detect object\n");
            fflush(stdout);
            gpioDelay(LOG_INTERVAL * 1000);
            continue;
        }

        if (v1 == 1 || v2 == 1) {
            log_state(v1, v2);
            printf("ALERT: Object detected on Sensor 1\n");
            fflush(stdout);
            gpioDelay(LOG_INTERVAL * 1000);
        }

        if (v1 == 0 || v2 == 0) {
            log_state(v1, v2);
            printf("ALERT: No object on Sensor 2\n");
            fflush(stdout);
            gpioDelay(LOG_INTERVAL * 1000);
        }

        gpioDelay(POLL_US);
    }

    /* --- Cleanup ----------------------------------------------- */
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

