/*
 * security_cam.c — Raspberry Pi 4 Model B
 *
 * Monitors an HC-SR501 PIR sensor on GPIO17 (BCM) and triggers a libcamera-
 * styled snapshot when motion is detected.  Logs to syslog and performs a
 * clean shutdown on SIGINT or SIGTERM.
 *
 * Build:  gcc -O2 -Wall -Wextra -o security_cam security_cam.c
 * Run:    ./security_cam
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>

#define PIR_PIN          17
#define DEBOUNCE_MS      200
#define POLL_INTERVAL_MS 50
#define CAPTURE_DIR      "/home/pi/security_cam"
#define LOG_FILE         "/var/log/security_cam.log"

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        snprintf(buf, len, "UNKNOWN");
        return;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        snprintf(buf, len, "UNKNOWN");
        return;
    }
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm_info);
}

/* ------------------------------------------------------------------ */
/* Capture a JPEG snapshot                                             */
/* ------------------------------------------------------------------ */
static int capture_image(const char *filename)
{
    char cmd[256];
    snprintf(cmd, sizeof(cmd),
             "libcamera-still -o %s --width 640 --height 480 --format jpeg",
             filename);

    int status = system(cmd);
    if (status == -1) {
        syslog(LOG_ERR, "system() failed for capture: %s", cmd);
        return -1;
    }
    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        syslog(LOG_ERR, "libcamera-still exited with status %d",
               WEXITSTATUS(status));
        return -1;
    }
    if (WIFSIGNALED(status)) {
        syslog(LOG_ERR, "libcamera-still killed by signal %d",
               WTERMSIG(status));
        return -1;
    }
    if (WIFEXITED(status)) {
        syslog(LOG_INFO, "Snapshot captured: %s", filename);
        return 0;
    }
    syslog(LOG_ERR, "libcamera-still exited unexpectedly");
    return -1;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    /* Open the GPIO pin as input with pull-down */
    int pir_pin = PIR_PIN;
    if (gpioSetMode(pir_pin, PI_INPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode(PIR_PIN) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(pir_pin, PI_PUD_DOWN) != 0) {
        syslog(LOG_ERR, "gpioSetPullUpDown(PIR_PIN) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Security camera monitoring started on GPIO%d", PIR_PIN);

    char filename[256];
    char timestamp[32];

    while (g_running) {
        int level = gpioRead(pir_pin);
        if (level < 0) {
            syslog(LOG_ERR, "gpioRead(PIR_PIN) failed");
            break;
        }

        if (level == 0) {
            /* Debounce: wait DEBOUNCE_MS, then re-read */
            usleep(DEBOUNCE_MS * 1000);
            if (g_running) {
                int debounced = gpioRead(pir_pin);
                if (debounced < 0) {
                    syslog(LOG_ERR, "gpioRead(PIR_PIN) debounce failed");
                    break;
                }
                if (debounced == 0) {
                    /* Motion detected — capture image */
                    if (capture_image(filename) == 0) {
                        /* Log the event */
                        char log_msg[256];
                        get_timestamp(log_msg, sizeof(log_msg));
                        snprintf(log_msg + strlen(log_msg),
                                 sizeof(log_msg) - strlen(log_msg),
                                 "Motion detected at %s", log_msg);
                        syslog(LOG_INFO, "%s", log_msg);
                    } else {
                        syslog(LOG_ERR, "Failed to capture image");
                    }
                }
            }
        }

        /* Sleep 50 ms */
        usleep(POLL_INTERVAL_MS * 1000);
    }

    /* Clean shutdown */
    syslog(LOG_INFO, "Shutting down...");
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

