#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define VIDEO_DEVICE "/dev/video0"
#define LOG_FILE "frame_log.txt"
#define BUFFER_SIZE (1024 * 1024)
#define POLL_TIMEOUT_MS 100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mjpeg_init(void) {
    int fd = open(VIDEO_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", VIDEO_DEVICE, strerror(errno));
        return -1;
    }

    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying cap: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device %s is not a video capture device\n", VIDEO_DEVICE);
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device %s does not support streaming I/O\n", VIDEO_DEVICE);
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_OUTPUT)) {
        fprintf(stderr, "Device %s does not support output I/O\n", VIDEO_DEVICE);
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_TUNER)) {
        fprintf(stderr, "Device %s does not support tuner\n", VIDEO_DEVICE);
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_CAMERA)) {
        fprintf(stderr, "Device %s does not support camera\n", VIDEO_DEVICE);
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAM_ON)) {
        fprintf(stderr, "Device %s does not support streaming on\n", VIDEO_DEVICE);
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_READWRITE)) {
        fprintf(stderr, "Device %s does not support read/write\n", VIDEO_DEVICE);
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_MPEG_CAP)) {
        fprintf(stderr, "Device %s does not support MPEG\n", VIDEO_DEVICE);
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VBI_CAP)) {
        fprintf(stderr, "Device %s does not support VBI\n", VIDEO_DEVICE);
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_SENSORS)) {
        fprintf(stderr, "Device %s does not support sensors\n", VIDEO_DEVICE);
        close(fd);
        return -1;
    }

    return fd;
}

static int mjpeg_read(void *buf, size_t len) {
    struct v4l2_buffer buf_req;
    memset(&buf_req, 0, sizeof(buf_req));
    buf_req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf_req.index = 0;
    buf_req.size = len;

    if (ioctl(mjpeg_fd, VIDIOC_QUERYBUF, &buf_req) < 0) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        return -1;
    }

    if (buf_req.bytesused < len) {
        fprintf(stderr, "Buffer size too small: %zu/%zu\n", buf_req.bytesused, len);
        return -1;
    }

    if (mmap(buf, len, PROT_READ, MAP_SHARED, buf_req.fd, buf_req.offset) == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int mjpeg_write(const void *buf, size_t len) {
    struct v4l2_buffer buf_req;
    memset(&buf_req, 0, sizeof(buf_req));
    buf_req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf_req.index = 0;
    buf_req.size = len;

    if (ioctl(mjpeg_fd, VIDIOC_QBUF, &buf_req) < 0) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        return -1;
    }

    if (munmap(buf, len) != 0) {
        fprintf(stderr, "Error unmapping buffer: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int mjpeg_close(void) {
    if (mjpeg_fd >= 0) {
        if (mjpeg_write(NULL, 0) < 0) {
            fprintf(stderr, "Error writing EOF to %s\n", VIDEO_DEVICE);
            close(mjpeg_fd);
            mjpeg_fd = -1;
        }
        close(mjpeg_fd);
        mjpeg_fd = -1;
    }
    return 0;
}

static int mjpeg_capture(void) {
    struct v4l2_buffer buf_req;
    memset(&buf_req, 0, sizeof(buf_req));
    buf_req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf_req.index = 0;
    buf_req.size = BUFFER_SIZE;

    if (ioctl(mjpeg_fd, VIDIOC_QBUF, &buf_req) < 0) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        return -1;
    }

    if (mjpeg_write(NULL, 0) < 0) {
        fprintf(stderr, "Error writing EOF to %s\n", VIDEO_DEVICE);
        return -1;
    }

    if (mjpeg_read(NULL, BUFFER_SIZE) < 0) {
        fprintf(stderr, "Error reading from %s\n", VIDEO_DEVICE);
        return -1;
    }

    return 0;
}

static void log_timestamp(const char *filename) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", filename, strerror(errno));
        return;
    }

    time_t rawtime = time(NULL);
    struct tm *timeinfo = localtime(&rawtime);
    if (!timeinfo) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    mjpeg_fd = mjpeg_init();
    if (mjpeg_fd < 0) {
        return 1;
    }

    while (running) {
        if (mjpeg_capture() < 0) {
            fprintf(stderr, "Error capturing frame\n");
            break;
        }

        log_timestamp(LOG_FILE);
    }

    if (mjpeg_close() < 0) {
        fprintf(stderr, "Error closing MJPEG stream\n");
        return 1;
    }

    return 0;
}

