#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define TILT_UP_PIN 6
#define TILT_DOWN_PIN 7
#define PAN_LEFT_PIN 8
#define PAN_RIGHT_PIN 9

#define PWM_PERIOD_US 20000
#define PWM_RANGE 1000
#define PWM_DUTY_MIN 50
#define PWM_DUTY_MAX 100
#define PAN_MIN 75
#define PAN_MAX 125
#define PAN_STEP 5
#define TILT_MIN 25
#define TILT_MAX 125
#define TILT_STEP 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_servo_duty(int pin, int duty) {
    if (duty < 0 || duty > PWM_RANGE) {
        fprintf(stderr, "Error: duty %d out of range [0, %d]\n", duty, PWM_RANGE);
        return -1;
    }
    if (gpioPWM(pin, duty) < 0) {
        fprintf(stderr, "Error: gpioPWM failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

static int set_servo_position(int pin, int position) {
    if (position < 0 || position > PWM_RANGE) {
        fprintf(stderr, "Error: position %d out of range [0, %d]\n", position, PWM_RANGE);
        return -1;
    }
    if (gpioServo(pin, position) < 0) {
        fprintf(stderr, "Error: gpioServo failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

static int read_button(int pin) {
    int val = gpioRead(pin);
    if (val < 0) {
        fprintf(stderr, "Error: gpioRead failed on pin %d\n", pin);
        return -1;
    }
    return val;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for PAN_SERVO_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for TILT_SERVO_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(TILT_UP_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for TILT_UP_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(TILT_DOWN_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for TILT_DOWN_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PAN_LEFT_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for PAN_LEFT_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PAN_RIGHT_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for PAN_RIGHT_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PAN_SERVO_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for PAN_SERVO_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(TILT_SERVO_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for TILT_SERVO_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(TILT_UP_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for TILT_UP_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(TILT_DOWN_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for TILT_DOWN_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(PAN_LEFT_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for PAN_LEFT_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(PAN_RIGHT_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for PAN_RIGHT_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (set_servo_duty(PAN_SERVO_PIN, PAN_MIN) < 0 ||
        set_servo_duty(TILT_SERVO_PIN, TILT_MIN) < 0 ||
        set_servo_duty(TILT_UP_PIN, TILT_MIN + PAN_STEP) < 0 ||
        set_servo_duty(TILT_DOWN_PIN, TILT_MIN + PAN_STEP) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int pan_val = read_button(PAN_SERVO_PIN);
        int tilt_val = read_button(TILT_SERVO_PIN);
        int pan_left_val = read_button(PAN_LEFT_PIN);
        int pan_right_val = read_button(PAN_RIGHT_PIN);

        if (pan_val < 0 || tilt_val < 0 || pan_left_val < 0 || pan_right_val < 0) {
            fprintf(stderr, "Error: failed to read button states\n");
            break;
        }

        if (pan_val == 1) {
            int new_pan = PAN_MIN + (PAN_MAX - PAN_MIN) * (pan_val + 1) / 2;
            if (new_pan < PAN_MIN) new_pan = PAN_MIN;
            if (new_pan > PAN_MAX) new_pan = PAN_MAX;
            if (set_servo_position(PAN_SERVO_PIN, new_pan) < 0) {
                fprintf(stderr, "Error: failed to set pan position\n");
                break;
            }
        }

        if (tilt_val == 1) {
            int new_tilt = TILT_MIN + (TILT_MAX - TILT_MIN) * (tilt_val + 1) / 2;
            if (new_tilt < TILT_MIN) new_tilt = TILT_MIN;
            if (new_tilt > TILT_MAX) new_tilt = TILT_MAX;
            if (set_servo_position(TILT_SERVO_PIN, new_tilt) < 0) {
                fprintf(stderr, "Error: failed to set tilt position\n");
                break;
            }
        }

        gpioDelay(50000); /* 50 ms */
    }

    gpioServo(TILT_UP_PIN, 0);
    gpioServo(TILT_DOWN_PIN, 0);
    gpioServo(PAN_LEFT_PIN, 0);
    gpioServo(PAN_RIGHT_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

