/*
 * csi_camera_info.c — Display camera device info for a CSI camera.
 *
 * Build:  gcc -O2 -Wall -Wextra -o csi_camera_info csi_camera_info.c
 * Run:    ./csi_camera_info
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define VIDEO_DEV_NAME "/dev/video0"
#define MAX_RESOLUTION_STR 256
#define MAX_INTERVAL_STR   256

/*
 * Query V4L2 capabilities.
 * Returns 0 on success, -1 on error.
 */
static int query_camera_capabilities(int fd)
{
    V4L2_CAP_FEATURES cap;
    memset(&cap, 0, sizeof(cap));
    cap.type = V4L2_CAP_FEATURES;
    cap.index = 0;

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Video capture not supported.\n");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Streaming not supported.\n");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_OUTPUT_FRAMES)) {
        fprintf(stderr, "Output frames not supported.\n");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE_FLAG_DRIVER_SPECIFIC)) {
        fprintf(stderr, "Driver-specific capabilities not supported.\n");
        return -1;
    }

    return 0;
}

/*
 * Enumerate supported frame sizes.
 * Returns 0 on success, -1 on error.
 */
static int enumerate_frame_sizes(int fd, int *num_sizes, int *sizes)
{
    struct v4l2_frmsizeenum enum_buf;
    enum_buf.index = 0;
    enum_buf.type = V4L2_FRM_SIZE_INCHES;
    enum_buf.size = sizeof(enum_buf);

    if (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &enum_buf) < 0) {
        fprintf(stderr, "VIDIOC_ENUM_FRAMESIZES failed: %s\n", strerror(errno));
        return -1;
    }

    *num_sizes = enum_buf.count;
    if (*num_sizes == 0) {
        fprintf(stderr, "No frame sizes available.\n");
        return -1;
    }

    for (int i = 0; i < *num_sizes; i++) {
        int size_index = enum_buf.list[i].index;
        if (size_index < 0 || size_index >= V4L2_FRM_SIZE_INCHES) {
            fprintf(stderr, "Invalid frame size index %d.\n", size_index);
            return -1;
        }
        sizes[i] = enum_buf.list[i].value;
    }

    return 0;
}

/*
 * Enumerate supported frame intervals.
 * Returns 0 on success, -1 on error.
 */
static int enumerate_frame_intervals(int fd, int *num_intervals, int *intervals)
{
    struct v4l2_frm_interval enum_buf;
    enum_buf.index = 0;
    enum_buf.type = V4L2_FRM_INTERVAL_INCHES;
    enum_buf.size = sizeof(enum_buf);

    if (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &enum_buf) < 0) {
        fprintf(stderr, "VIDIOC_ENUM_FRAMEINTERVALS failed: %s\n", strerror(errno));
        return -1;
    }

    *num_intervals = enum_buf.count;
    if (*num_intervals == 0) {
        fprintf(stderr, "No frame intervals available.\n");
        return -1;
    }

    for (int i = 0; i < *num_intervals; i++) {
        int interval_index = enum_buf.list[i].index;
        if (interval_index < 0 || interval_index >= V4L2_FRM_INTERVAL_INCHES) {
            fprintf(stderr, "Invalid frame interval index %d.\n", interval_index);
            return -1;
        }
        intervals[i] = enum_buf.list[i].value;
    }

    return 0;
}

/*
 * Query autofocus capability.
 * Returns 0 on success, -1 on error.
 */
static int query_autofocus_capability(int fd)
{
    V4L2_CID_FOCUS_AUTO focus_cap;
    memset(&focus_cap, 0, sizeof(focus_cap));
    focus_cap.id = V4L2_CID_FOCUS_AUTO;

    if (ioctl(fd, VIDIOC_QUERYCTRL, &focus_cap) < 0) {
        fprintf(stderr, "VIDIOC_QUERYCTRL(FOCUS_AUTO) failed: %s\n", strerror(errno));
        return -1;
    }

    if (focus_cap.value == 0) {
        fprintf(stderr, "Autofocus not supported (value 0).\n");
        return -1;
    }

    return 0;
}

int main(void)
{
    int fd = -1;
    int num_sizes = 0;
    int num_intervals = 0;
    int autofocus_capability = -1;

    /* Open the video device. */
    fd = open(VIDEO_DEV_NAME, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", VIDEO_DEV_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Verify the device exists. */
    struct stat st;
    if (stat(VIDEO_DEV_NAME, &st) < 0) {
        fprintf(stderr, "Cannot stat %s: %s\n", VIDEO_DEV_NAME, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }
    if (!S_ISCHR(st.st_mode)) {
        fprintf(stderr, "Device %s is not a character device.\n", VIDEO_DEV_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    /* Query capabilities. */
    if (query_camera_capabilities(fd) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    /* Enumerate supported frame sizes. */
    if (enumerate_frame_sizes(fd, &num_sizes, &sizes) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    /* Enumerate supported frame intervals. */
    if (enum_frame_intervals(fd, &num_intervals, &intervals) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    /* Query autofocus capability. */
    if (query_autofocus_capability(fd) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    /* Print summary. */
    printf("Camera: %s\n", VIDEO_DEV_NAME);
    printf("  Frame sizes: %d\n", num_sizes);
    printf("  Frame intervals: %d\n", num_intervals);
    printf("  Autofocus capability: %s\n", (autofocus_capability == 0) ? "not supported" : "supported");
    printf("  Device: %s\n", VIDEO_DEV_NAME);
    printf("  Open: %s\n", strerror(errno));

    /* Close the device. */
    if (fd >= 0) {
        close(fd);
    }

    return EXIT_SUCCESS;
}

