/*
 * Camera pan-tilt control using two hobby servos and four buttons.
 *
 * Hardware:
 *   - Pan servo: GPIO4 (BCM), 50 Hz PWM, center position 1500 µs.
 *   - Tilt servo: GPIO5 (BCM), 50 Hz PWM, center position 1500 µs.
 *   - UP, DOWN, LEFT, RIGHT buttons: GPIO6, GPIO7, GPIO8, GPIO9, all
 *     active-low, internal pull-up resistors.
 *
 * Build:  gcc -O2 -Wall -Wextra -o pan_tilt pan_tilt.c -lpigpio -lrt
 * Run:    sudo ./pan_tilt
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN      4
#define TILT_SERVO_PIN     5
#define UP_BUTTON_PIN      6
#define DOWN_BUTTON_PIN    7
#define LEFT_BUTTON_PIN    8
#define RIGHT_BUTTON_PIN   9

#define MIN_PULSE_US       1000
#define MAX_PULSE_US       2000
#define CENTER_PULSE_US    1500
#define PWM_FREQUENCY      50
#define PWM_RANGE          2000
#define LOOP_DELAY_US      50000   /* 50 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Return 0 on success, -1 on failure.
 * Assumes the pigpio library is already initialized.
 */
static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set PAN_SERVO_PIN %d as output.\n",
                PAN_SERVO_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TILT_SERVO_PIN %d as output.\n",
                TILT_SERVO_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(UP_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set UP_BUTTON_PIN %d as input.\n",
                UP_BUTTON_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set DOWN_BUTTON_PIN %d as input.\n",
                DOWN_BUTTON_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set LEFT_BUTTON_PIN %d as input.\n",
                LEFT_BUTTON_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set RIGHT_BUTTON_PIN %d as input.\n",
                RIGHT_BUTTON_PIN);
        gpioTerminate();
        return -1;
    }

    /* Ensure all inputs are low (default) */
    if (gpioSetMode(UP_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set UP_BUTTON_PIN %d as input.\n",
                UP_BUTTON_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set DOWN_BUTTON_PIN %d as input.\n",
                DOWN_BUTTON_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set LEFT_BUTTON_PIN %d as input.\n",
                LEFT_BUTTON_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set RIGHT_BUTTON_PIN %d as input.\n",
                RIGHT_BUTTON_PIN);
        gpioTerminate();
        return -1;
    }

    /* Ensure all outputs are LOW initially */
    if (gpioWrite(PAN_SERVO_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize PAN_SERVO_PIN %d.\n",
                PAN_SERVO_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(TILT_SERVO_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize TILT_SERVO_PIN %d.\n",
                TILT_SERVO_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup(void)
{
    /* Ensure PAN_SERVO_PIN is LOW before releasing pigpio */
    gpioWrite(PAN_SERVO_PIN, 0);
    gpioWrite(TILT_SERVO_PIN, 0);

    gpioTerminate();
}

/*
 * Return 0 on success, -1 on failure.
 * Assumes the pigpio library is already initialized.
 */
static int set_servo_pulse(int pin, int pulse_us)
{
    if (pulse_us < MIN_PULSE_US || pulse_us > MAX_PULSE_US) {
        fprintf(stderr, "Error: pulse width %d us out of range [%d, %d].\n",
                pulse_us, MIN_PULSE_US, MAX_PULSE_US);
        return -1;
    }

    if (gpioServo(pin, pulse_us) != 0) {
        fprintf(stderr, "Error: gpioServo(%d, %d) failed.\n", pin, pulse_us);
        return -1;
    }
    return 0;
}

int main(void)
{
    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Camera pan-tilt control started.\n");
    printf("Servo pins: PAN=%d, TILT=%d\n", PAN_SERVO_PIN, TILT_SERVO_PIN);
    printf("Buttons: UP=%d, DOWN=%d, LEFT=%d, RIGHT=%d\n",
           UP_BUTTON_PIN, DOWN_BUTTON_PIN, LEFT_BUTTON_PIN, RIGHT_BUTTON_PIN);
    printf("Press Ctrl+C to exit.\n");

    int center_pulse = CENTER_PULSE_US;
    int last_button_state = 0;

    while (g_running) {
        int current_pulse = gpioRead(UP_BUTTON_PIN);
        if (current_pulse < 0) {
            fprintf(stderr, "Error: gpioRead(%d) failed.\n", UP_BUTTON_PIN);
            break;
        }

        if (current_pulse != last_button_state) {
            if (set_servo_pulse(PAN_SERVO_PIN, center_pulse) != 0) {
                fprintf(stderr, "Error: failed to set PAN_SERVO_PIN.\n");
                break;
            }
            center_pulse = current_pulse;
            last_button_state = current_pulse;
            usleep(LOOP_DELAY_US);
        }

        int pulse_us = center_pulse + (rand() % (MAX_PULSE_US - MIN_PULSE_US + 1));
        if (set_servo_pulse(PAN_SERVO_PIN, pulse_us) != 0) {
            fprintf(stderr, "Error: failed to set PAN_SERVO_PIN.\n");
            break;
        }

        usleep(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

