/*
 * PIR motion-detection monitor for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   HC-SR501 OUT -> GPIO17 (BCM, physical pin 11)
 *   VCC -> 3.3 V, GND -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o pir_monitor pir_monitor.c -lrt -lpthread
 * Run:    ./pir_monitor <IP> <port>
 */

#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <pigpio.h>

#define PIR_GPIO_PIN        17
#define DEBOUNCE_TIME_SEC   2
#define POLL_INTERVAL_US    100000   /* 100 ms */
#define HTTP_PORT           8080
#define HTTP_IP             "127.0.0.1"
#define HTTP_PATH           "/upload"

/* ------------------------------------------------------------------ */
/* Global state                                                         */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;
static pthread_mutex_t g_mutex = PTHREAD_MUTEX_INITIALIZER;

/* ------------------------------------------------------------------ */
/* HTTP library                                                         */
/* ------------------------------------------------------------------ */

typedef struct {
    int http_fd;
    char  http_ip[INET_ADDRSTRLEN];
    int   http_port;
} http_t;

static http_t g_http;

static void http_init(http_t *h)
{
    memset(h, 0, sizeof(*h));
    h->http_fd = -1;
    h->http_ip[0] = '\0';
    h->http_port = 0;
}

static int http_open(http_t *h)
{
    char path[64];

    snprintf(path, sizeof(path), "%s", HTTP_PATH);

    h->http_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (h->http_fd < 0) {
        perror("socket");
        return -1;
    }

    int opt = 1;
    if (setsockopt(h->http_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt");
        close(h->http_fd);
        h->http_fd = -1;
        return -1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(HTTP_IP);
    addr.sin_port = htons(h->http_port);

    if (bind(h->http_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind");
        close(h->http_fd);
        h->http_fd = -1;
        return -1;
    }

    if (listen(h->http_fd, 3) < 0) {
        perror("listen");
        close(h->http_fd);
        h->http_fd = -1;
        return -1;
    }

