/* ------------------------------------------------------------------ */
/* Sensor driver                                                        */
/* ------------------------------------------------------------------ */

typedef struct {
    int gpio_pin;
    int debounce_time_sec;
    int last_state;
    int last_motion;
    int last_error;
} sensor_t;

static sensor_t g_sensor = {
    .gpio_pin = PIR_GPIO_PIN,
    .debounce_time_sec = DEBOUNCE_TIME_SEC,
    .last_state = 0,
    .last_motion = 0,
    .last_error = 0,
};

static void sensor_init(sensor_t *s)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        s->last_error = 1;
        return;
    }

    if (gpioSetMode(s->gpio_pin, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for pin %d\n", s->gpio_pin);
        s->last_error = 1;
        return;
    }

    if (gpioSetPullUpDown(s->gpio_pin, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for pin %d\n", s->gpio_pin);
        s->last_error = 1;
        return;
    }

    s->last_state = gpioRead(s->gpio_pin);
    s->last_error = 0;
}

static void sensor_read(sensor_t *s)
{
    int v = gpioRead(s->gpio_pin);
    if (v < 0) {
        fprintf(stderr, "gpioRead failed on pin %d\n", s->gpio_pin);
        s->last_error = 1;
        return;
    }

    if (v == 1) {
        s->last_state = 1;
        s->last_motion = 1;
    } else {
        s->last_state = 0;
        s->last_motion = 0;
    }
}

static void sensor_debounce(sensor_t *s)
{
    if (s->last_state == 1) {
        if (s->last_motion == 1) {
            s->last_motion = 0;
            s->last_error = 0;
            return;
        }
    } else if (s->last_state == 0) {
        if (s->last_motion == 1) {
            s->last_motion = 0;
            s->last_error = 0;
            return;
        }
    }
}

static void sensor_capture(sensor_t *s)
{
    char filename[64];
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (t == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        s->last_error = 1;
        return;
    }

    if (strftime(filename, sizeof(filename), HTTP_PATH "/motion_%Y-%m-%d_%H-%M-%S.jpg", t) == 0) {
        fprintf(stderr, "strftime failed\n");
        s->last_error = 1;
        return;
    }

    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", filename, strerror(errno));
        s->last_error = 1;
        return;
    }

    if (fprintf(fp, "{\"filename\":\"%s\",\"timestamp\":\"%s\",\"motion\":%s,\"gpio_pin\":%d}\n",
                filename, ctime(&now), s->last_motion ? "1" : "0", s->gpio_pin) < 0) {
        fprintf(stderr, "fprintf failed: %s\n", strerror(errno));
        fclose(fp);
        s->last_error = 1;
        return;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose failed: %s\n", strerror(errno));
        s->last_error = 1;
        return;
    }

    printf("Motion captured: %s\n", filename);
    s->last_error = 0;
}

/* ------------------------------------------------------------------ */
/* HTTP upload                                                         */
/* ------------------------------------------------------------------ */

static void http_upload(http_t *h, const char *filename)
{
    if (h->http_fd < 0) {
        fprintf(stderr, "HTTP fd not initialized\n");
        return;
    }

    char payload[1024];
    int payload_len = snprintf(payload, sizeof(payload),
                               "{\"filename\":\"%s\",\"timestamp\":\"%s\",\"motion\":%s,\"gpio_pin\":%d}",
                               filename, ctime(&(h->http_fd->last_timestamp)),
                               h->http_fd->last_motion ? "1" : "0",
                               h->http_fd->gpio_pin);
    if (payload_len < 0 || (size_t)payload_len >= sizeof(payload)) {
        fprintf(stderr, "payload too long\n");
        return;
    }

    if (send(h->http_fd, payload, (size_t)payload_len, 0) < 0) {
        perror("send");
        return;
    }

    printf("Uploaded: %s\n", filename);
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */

static void cleanup(http_t *h)
{
    if (h->http_fd >= 0) {
        close(h->http_fd);
        h->http_fd = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(int argc, char *argv[])
{
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <IP> <port>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int ip = strtol(argv[1], NULL, 16);
    if (ip == 0 || ip == INADDR_ANY) {
        ip = IP_ADDR_ANY;
    }

    int port = strtol(argv[2], NULL, 10);
    if (port <= 0 || port > 65535) {
        fprintf(stderr, "Invalid port %d\n", port);
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (http_open(&g_http) < 0) {
        fprintf(stderr, "HTTP initialisation failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    sensor_init(&g_sensor);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        cleanup(&g_http);
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        cleanup(&g_http);
        return EXIT_FAILURE;
    }

    printf("Monitoring PIR sensor on GPIO%d for motion...\n", g_sensor.gpio_pin);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        sensor_read(&g_sensor);
        sensor_debounce(&g_sensor);
        sensor_capture(&g_sensor);

        if (g_sensor.last_error) {
            fprintf(stderr, "Sensor error: %s\n", g_sensor.last_error_msg);
            g_sensor.last_error = 0;
        }

        if (g_sensor.last_motion) {
            http_upload(&g_http, g_sensor.filename);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup(&g_http);
    return EXIT_SUCCESS;
}

