    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction SIGINT");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction SIGTERM");
        return EXIT_FAILURE;
    }

    struct gpio_chip *chip = gpiochip_open("/dev/gpiochip0");
    if (!chip) {
        log_message("gpiochip_open failed");
        return EXIT_FAILURE;
    }

    struct gpio_line *line = gpio_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        log_message("gpio_chip_get_line failed");
        gpiochip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpio_line_request_falling_edge_events(line, "motion_capture") < 0) {
        log_message("gpio_line_request_falling_edge_events failed");
        gpiochip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Motion detection started on GPIO%d. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (running) {
        int ret = gpio_line_wait_falling_edge(line, DEBOUNCE_MS * 1000);
        if (ret < 0) {
            if (errno == EINTR) continue;
            log_message("gpio_line_wait_falling_edge failed");
            break;
        }
        if (ret == 0) {
            log_message("No motion detected");
            continue;
        }

        time_t now = time(NULL);
        if (now == (time_t)-1) {
            log_message("time() failed");
            continue;
        }

        struct tm tm_info;
        if (localtime_r(&now, &tm_info) == NULL) {
            log_message("localtime_r failed");
            continue;
        }

        char timestamp[32];
        if (strftime(timestamp, sizeof(timestamp),
                     "%Y%m%d_%H%M%S", &tm_info) == 0) {
            log_message("strftime failed");
            continue;
        }

        char filename[256];
        snprintf(filename, sizeof(filename), "%s/%s.jpg", IMAGES_DIR, timestamp);

        int capture_ok = capture_image(filename);
        if (capture_ok == -1) {
            log_message("Capture failed, skipping this frame");
        } else {
            if (log_message("Capture successful") == -1) {
                log_message("Failed to log capture event");
            }
        }

        if (capture_ok == 0) {
            log_message("No image saved");
        }
    }

    gpio_line_release(line);
    gpiochip_close(chip);
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

