#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN 17
#define TILT_SERVO_PIN 18
#define SERVO_FREQ 50
#define SERVO_STEP 5
#define SERVO_MIN_ANGLE 0
#define SERVO_MAX_ANGLE 180
#define SERVO_PWM_RANGE 1000
#define DELAY_MS 100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_servo_angle(int pin, int angle) {
    if (angle < SERVO_MIN_ANGLE || angle > SERVO_MAX_ANGLE) {
        fprintf(stderr, "Error: angle %d out of range [%d, %d]\n",
                angle, SERVO_MIN_ANGLE, SERVO_MAX_ANGLE);
        return -1;
    }
    if (gpioServo(pin, angle) < 0) {
        fprintf(stderr, "Error: gpioServo(%d, %d) failed\n", pin, angle);
        return -1;
    }
    return 0;
}

static int move_servo(int pin, int angle) {
    if (set_servo_angle(pin, angle) != 0) {
        return -1;
    }
    gpioDelay(DELAY_MS * 1000);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set PAN_SERVO_PIN %d as output\n",
                PAN_SERVO_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TILT_SERVO_PIN %d as output\n",
                TILT_SERVO_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioServo(PAN_SERVO_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize PAN_SERVO_PIN %d to 0\n",
                PAN_SERVO_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioServo(TILT_SERVO_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize TILT_SERVO_PIN %d to 0\n",
                TILT_SERVO_PIN);
        gpioServo(PAN_SERVO_PIN, 0);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioServo(PAN_SERVO_PIN, 0);
        gpioServo(TILT_SERVO_PIN, 0);
        gpioTerminate();
        return 1;
    }

    printf("Arrow-key driven servo control. Press Ctrl+C to exit.\n");

    while (running) {
        int key = getchar();
        if (key == EOF) {
            break;
        }
        if (key == 'q') {
            break;
        }

        int pan_angle = 0;
        int tilt_angle = 0;

        if (key == 'p') {
            printf("Pan: %d degrees\n", pan_angle);
            if (move_servo(PAN_SERVO_PIN, pan_angle) != 0) {
                fprintf(stderr, "Error: failed to move PAN_SERVO\n");
            }
        } else if (key == 't') {
            printf("Tilt: %d degrees\n", tilt_angle);
            if (move_servo(TILT_SERVO_PIN, tilt_angle) != 0) {
                fprintf(stderr, "Error: failed to move TILT_SERVO\n");
            }
        } else {
            printf("Unknown key: %c\n", key);
        }

        if (pan_angle > SERVO_MAX_ANGLE || pan_angle < SERVO_MIN_ANGLE) {
            fprintf(stderr, "Error: pan angle out of range [%d, %d]\n",
                    SERVO_MIN_ANGLE, SERVO_MAX_ANGLE);
            break;
        }
        if (tilt_angle > SERVO_MAX_ANGLE || tilt_angle < SERVO_MIN_ANGLE) {
            fprintf(stderr, "Error: tilt angle out of range [%d, %d]\n",
                    SERVO_MIN_ANGLE, SERVO_MAX_ANGLE);
            break;
        }

        if (move_servo(PAN_SERVO_PIN, pan_angle) != 0) {
            fprintf(stderr, "Error: failed to move PAN_SERVO\n");
            break;
        }
        if (move_servo(TILT_SERVO_PIN, tilt_angle) != 0) {
            fprintf(stderr, "Error: failed to move TILT_SERVO\n");
            break;
        }
        gpioDelay(DELAY_MS * 1000);
    }

    printf("\nCleaning up and exiting...\n");
    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);
    gpioTerminate();
    return 0;
}

