/*
 * YF-S201 Water Flow Sensor Reader + HD44780 LCD Display
 * Board: Raspberry Pi 4 Model B
 * Sensor: YF-S201 on GPIO17 (BCM)
 * LCD: HD44780 on I2C bus 1, address 0x27
 *
 * Build: gcc -O2 -Wall -o flow_monitor flow_monitor.c -lpigpio -lrt
 * Run:   sudo ./flow_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_GPIO 17
#define LCD_I2C_ADDR 0x27
#define I2C_BUS 1

#define FLOW_THRESHOLD_HIGH 1.0f
#define FLOW_THRESHOLD_LOW 0.5f
#define FLOW_RANGE_MIN 0.0f
#define FLOW_RANGE_MAX 1.0f

#define LCD_WIDTH 128
#define LCD_HEIGHT 16

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int lcd_handle = -1;

static float flow_rate = 0.0f;
static float total_volume = 0.0f;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    gpioSetMode(SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_GPIO, PI_PUD_UP);

    return 0;
}

static int init_lcd(void) {
    i2c_handle = i2cOpen(I2C_BUS, LCD_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X (handle=%d).\n",
                I2C_BUS, LCD_I2C_ADDR, i2c_handle);
        return -1;
    }

    /* HD44780: clear display, display off, cursor off, no shift */
    if (lcd_handle = i2cOpen(I2C_BUS, LCD_I2C_ADDR, 0)) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X (handle=%d).\n",
                I2C_BUS, LCD_I2C_ADDR, lcd_handle);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    /* Send command sequence for LCD initialization */
    if (lcd_handle = i2cWriteByteData(i2c_handle, 0x01, 0x01)) {
        fprintf(stderr, "Error: Failed to initialize LCD (write command).\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    /* Wait for LCD to be ready (display off) */
    usleep(100000);

    /* Send command sequence for LCD initialization */
    if (lcd_handle = i2cWriteByteData(i2c_handle, 0x01, 0x01)) {
        fprintf(stderr, "Error: Failed to initialize LCD (write command).\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    /* Wait for LCD to be ready (display off) */
    usleep(100000);

    /* Set LCD font size */
    if (lcd_handle = i2cWriteByteData(i2c_handle, 0x0C, 0x03)) {
        fprintf(stderr, "Error: Failed to set LCD font size.\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    /* Set LCD cursor position */
    if (lcd_handle = i2cWriteByteData(i2c_handle, 0x80, 0x00)) {
        fprintf(stderr, "Error: Failed to set cursor position.\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    /* Clear display */
    if (lcd_handle = i2cWriteByteData(i2c_handle, 0x01, 0x01)) {
        fprintf(stderr, "Error: Failed to clear LCD.\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    /* Set LCD display on */
    if (lcd_handle = i2cWriteByteData(i2c_handle, 0x28, 0x01)) {
        fprintf(stderr, "Error: Failed to set LCD display on.\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    return 0;
}

static int read_sensor(float *flow_rate) {
    int val = gpioRead(SENSOR_GPIO);
    if (val < 0) {
        fprintf(stderr, "Error: Failed to read GPIO %d.\n", SENSOR_GPIO);
        return -1;
    }
    *flow_rate = (float)val / 10.0f;
    return 0;
}

static void update_lcd(float flow_rate) {
    if (lcd_handle < 0) return;

    int16_t raw_data = (int16_t)(flow_rate * LCD_WIDTH);
    int16_t x = (int16_t)((LCD_WIDTH - 1) / 2);
    int16_t y = (int16_t)((LCD_HEIGHT - 1) / 2);

    /* Clear display */
    if (lcd_handle = i2cWriteByteData(i2c_handle, 0x00, 0x00)) {
        fprintf(stderr, "Error: Failed to clear LCD.\n");
        return;
    }

    /* Write data to LCD */
    if (lcd_handle = i2cWriteByteData(i2c_handle, 0x80, (uint8_t)raw_data)) {
        fprintf(stderr, "Error: Failed to write data to LCD.\n");
        return;
    }

    /* Display data */
    if (lcd_handle = i2cWriteByteData(i2c_handle, 0x40, (uint8_t)x)) {
        fprintf(stderr, "Error: Failed to write x position.\n");
        return;
    }

    if (lcd_handle = i2cWriteByteData(i2c_handle, 0x41, (uint8_t)y)) {
        fprintf(stderr, "Error: Failed to write y position.\n");
        return;
    }

    /* Display data */
    if (lcd_handle = i2cWriteByteData(i2c_handle, 0x40, (uint8_t)x)) {
        fprintf(stderr, "Error: Failed to write x position.\n");
        return;
    }

    if (lcd_handle = i2cWriteByteData(i2c_handle, 0x41, (uint8_t)y)) {
        fprintf(stderr, "Error: Failed to write y position.\n");
        return;
    }

    /* Display data */
    if (lcd_handle = i2cWriteByteData(i2c_handle, 0x40, (uint8_t)x)) {
        fprintf(stderr, "Error: Failed to write x position.\n");
        return;
    }

    if (lcd_handle = i2cWriteByteData(i2c_handle, 0x41, (uint8_t)y)) {
        fprintf(stderr, "Error: Failed to write y position.\n");
        return;
    }
}

static void log_data(float flow_rate, float total_volume) {
    printf("Flow Rate: %.2f L/min, Total Volume: %.2f L\n", flow_rate, total_volume);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    if (init_lcd() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    float flow_rate = 0.0f;
    float total_volume = 0.0f;

    while (running) {
        if (read_sensor(&flow_rate) == 0) {
            total_volume += flow_rate;
            flow_rate = 0.0f;
        }

        if (flow_rate > FLOW_THRESHOLD_HIGH) {
            flow_rate = FLOW_RANGE_MAX;
            total_volume = FLOW_RANGE_MAX;
        } else if (flow_rate < FLOW_THRESHOLD_LOW) {
            flow_rate = FLOW_RANGE_MIN;
            total_volume = FLOW_RANGE_MIN;
        }

        update_lcd(flow_rate);
        log_data(flow_rate, total_volume);

        sleep(1);
    }

    /* Graceful shutdown */
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (lcd_handle >= 0) {
        i2cClose(lcd_handle);
        lcd_handle = -1;
    }

    gpioTerminate();
    printf("\nProgram terminated cleanly.\n");
    return EXIT_SUCCESS;
}

