        fprintf(stderr, "Error: Failed to clear LCD.\n");
        return;
    }

    /* Write data to LCD */
    if (lcd_handle = i2cWriteByteData(i2c_handle, 0x80, (uint8_t)raw_data)) {
        fprintf(stderr, "Error: Failed to write data to LCD.\n");
        return;
    }

    /* Display data */
    if (lcd_handle = i2cWriteByteData(i2c_handle, 0x40, (uint8_t)x)) {
        fprintf(stderr, "Error: Failed to write x position.\n");
        return;
    }

    if (lcd_handle = i2cWriteByteData(i2c_handle, 0x41, (uint8_t)y)) {
        fprintf(stderr, "Error: Failed to write y position.\n");
        return;
    }

    /* Display data */
    if (lcd_handle = i2cWriteByteData(i2c_handle, 0x40, (uint8_t)x)) {
        fprintf(stderr, "Error: Failed to write x position.\n");
        return;
    }

    if (lcd_handle = i2cWriteByteData(i2c_handle, 0x41, (uint8_t)y)) {
        fprintf(stderr, "Error: Failed to write y position.\n");
        return;
    }

    /* Display data */
    if (lcd_handle = i2cWriteByteData(i2c_handle, 0x40, (uint8_t)x)) {
        fprintf(stderr, "Error: Failed to write x position.\n");
        return;
    }

    if (lcd_handle = i2cWriteByteData(i2c_handle, 0x41, (uint8_t)y)) {
        fprintf(stderr, "Error: Failed to write y position.\n");
        return;
    }
}

static void log_data(float flow_rate, float total_volume) {
    printf("Flow Rate: %.2f L/min, Total Volume: %.2f L\n", flow_rate, total_volume);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    if (init_lcd() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    float flow_rate = 0.0f;
    float total_volume = 0.0f;

    while (running) {
        if (read_sensor(&flow_rate) == 0) {
            total_volume += flow_rate;
            flow_rate = 0.0f;
        }

        if (flow_rate > FLOW_THRESHOLD_HIGH) {
            flow_rate = FLOW_RANGE_MAX;
            total_volume = FLOW_RANGE_MAX;
        } else if (flow_rate < FLOW_THRESHOLD_LOW) {
            flow_rate = FLOW_RANGE_MIN;
            total_volume = FLOW_RANGE_MIN;
        }

        update_lcd(flow_rate);
        log_data(flow_rate, total_volume);

        sleep(1);
    }

    /* Graceful shutdown */
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (lcd_handle >= 0) {
        i2cClose(lcd_handle);
        lcd_handle = -1;
    }

    gpioTerminate();
    printf("\nProgram terminated cleanly.\n");
    return EXIT_SUCCESS;
}

