#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_ROWS 8
#define NUM_COLS 8
#define NUM_CHIPS 1

/* BCM GPIO numbers for the 8x8 matrix */
static const int matrix_row_pins[NUM_ROWS] = {2, 3, 4, 17, 27, 22, 10, 9};
static const int matrix_col_pins[NUM_COLS] = {14, 15, 18, 23, 24, 25, 8, 7};

/* Global flag for graceful shutdown */
static volatile sig_atomic_t program_running = 1;

/* Signal handler for SIGINT and SIGTERM */
static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

/* Initialize the GPIO pins for the 8x8 matrix */
static int initialize_matrix(void) {
    for (int i = 0; i < NUM_ROWS; i++) {
        if (gpioSetMode(matrix_row_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: Failed to set GPIO %d as output\n", matrix_row_pins[i]);
            return -1;
        }
        if (gpioWrite(matrix_row_pins[i], 0) != 0) {
            fprintf(stderr, "Error: Failed to write GPIO %d LOW\n", matrix_row_pins[i]);
            return -1;
        }
    }
    for (int i = 0; i < NUM_COLS; i++) {
        if (gpioSetMode(matrix_col_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: Failed to set GPIO %d as output\n", matrix_col_pins[i]);
            return -1;
        }
        if (gpioWrite(matrix_col_pins[i], 1) != 0) {
            fprintf(stderr, "Error: Failed to write GPIO %d HIGH\n", matrix_col_pins[i]);
            return -1;
        }
    }
    return 0;
}

/* Set all column cathodes to LOW (off) */
static void set_all_columns_low(void) {
    for (int i = 0; i < NUM_COLS; i++) {
        if (gpioWrite(matrix_col_pins[i], 0) != 0) {
            fprintf(stderr, "Error: Failed to write GPIO %d LOW\n", matrix_col_pins[i]);
            return;
        }
    }
}

/* Set all row anodes to HIGH (on) */
static void set_all_row_high(void) {
    for (int i = 0; i < NUM_ROWS; i++) {
        if (gpioWrite(matrix_row_pins[i], 1) != 0) {
            fprintf(stderr, "Error: Failed to write GPIO %d HIGH\n", matrix_row_pins[i]);
            return;
        }
    }
}

/* Clear the entire 8x8 matrix by setting all column cathodes to LOW */
static void clear_matrix(void) {
    set_all_columns_low();
    gpioDelay(150000); /* 150 ms delay */
}

/* Set a single column of LEDs to a specific state (0 = off, 1 = on) */
static void set_column(int col, int state) {
    if (state == 0) {
        for (int i = 0; i < NUM_ROWS; i++) {
            if (gpioWrite(matrix_row_pins[i], 1) != 0) {
                fprintf(stderr, "Error: Failed to write GPIO %d HIGH\n", matrix_row_pins[i]);
                return;
            }
        }
    } else {
        for (int i = 0; i < NUM_ROWS; i++) {
            if (gpioWrite(matrix_row_pins[i], 0) != 0) {
                fprintf(stderr, "Error: Failed to write GPIO %d LOW\n", matrix_row_pins[i]);
                return;
            }
        }
    }
    /* Column cathodes are driven by a current-limiting resistor */
    if (state == 0) {
        for (int i = 0; i < NUM_COLS; i++) {
            if (gpioWrite(matrix_col_pins[i], 1) != 0) {
                fprintf(stderr, "Error: Failed to write GPIO %d HIGH\n", matrix_col_pins[i]);
                return;
            }
        }
    }
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to install SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to install SIGTERM handler\n");
    }

    /* Initialize the matrix */
    if (initialize_matrix() != 0) {
        fprintf(stderr, "Error: Matrix initialization failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Matrix animation started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (program_running) {
        clear_matrix();
        for (int col = 0; col < NUM_COLS && program_running; col++) {
            set_column(col, 1);
            gpioDelay(150000); /* 150 ms delay between columns */
            set_column(col, 0);
        }
        gpioDelay(150000); /* 150 ms delay between rows */
    }

    /* Cleanup */
    printf("\nCleaning up...\n");
    set_all_columns_low();
    gpioTerminate();
    printf("Matrix animation stopped.\n");
    return EXIT_SUCCESS;
}

