#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_SENSOR 4
#define GPIO_LED 17
#define LOG_FILE "proximity.log"
#define POLL_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Write an ISO-8601 UTC timestamped entry to the log file.
 * Returns 0 on success, -1 on error.
 */
static int log_entry(const char *filename)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&t, &tm_utc) == NULL) {
        fprintf(stderr, "gmtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s Object detected\n", timestamp) < 0) {
        fprintf(stderr, "fprintf() to log failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose() on log file failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/*
 * Blink the LED for the specified duration (in microseconds).
 * Returns 0 on success, -1 on error.
 */
static int blink_led(int gpio_pin)
{
    if (gpioWrite(gpio_pin, 1) < 0) {
        fprintf(stderr, "gpioWrite(1) failed on GPIO %d\n", gpio_pin);
        return -1;
    }
    gpioDelay(100000);  /* 100 ms */
    if (gpioWrite(gpio_pin, 0) < 0) {
        fprintf(stderr, "gpioWrite(0) failed on GPIO %d\n", gpio_pin);
        return -1;
    }
    return 0;
}

int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(GPIO_SENSOR, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(GPIO_SENSOR) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(GPIO_LED) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure LED is off at start */
    if (gpioWrite(GPIO_LED, 0) < 0) {
        fprintf(stderr, "gpioWrite(0) failed on GPIO %d\n", GPIO_LED);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Main polling loop */
    while (g_running) {
        int sensor_value = gpioRead(GPIO_SENSOR);
        if (sensor_value < 0) {
            fprintf(stderr, "gpioRead(GPIO_SENSOR) failed\n");
            break;
        }

        /* Sensor returns LOW when an object is within the calibrated range */
        if (sensor_value == 0) {
            /* Falling edge: object detected */
            if (log_entry(LOG_FILE) != 0) {
                fprintf(stderr, "Failed to log entry\n");
            }

            if (blink_led(GPIO_LED) != 0) {
                fprintf(stderr, "Failed to blink LED\n");
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* Cleanup */
    gpioWrite(GPIO_LED, 0);
