#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS "/dev/i2c-1"
#define APDS9960_ADDR 0x60
#define APDS9960_REG_PROXIMITY 0x00
#define APDS9960_REG_RAW_R 0x01
#define APDS9960_REG_RAW_G 0x02
#define APDS9960_REG_RAW_B 0x03
#define APDS9960_REG_CONFIG 0x04
#define APDS9960_CONFIG_PROXIMITY_THRESHOLD 200
#define PROXIMITY_THRESHOLD 200
#define POLL_INTERVAL_MS 100
#define CSV_FILE "color_proximity_log.csv"

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, unsigned char reg, unsigned char *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_apds9960(int fd) {
    if (i2c_write_reg(fd, APDS9960_REG_CONFIG, APDS9960_CONFIG_PROXIMITY_THRESHOLD) < 0) return -1;
    usleep(10000);
    return 0;
}

static int read_apds9960(int fd, unsigned char *r, unsigned char *g, unsigned char *b) {
    if (i2c_read_reg(fd, APDS9960_REG_RAW_R, r) < 0) return -1;
    if (i2c_read_reg(fd, APDS9960_REG_RAW_G, g) < 0) return -1;
    if (i2c_read_reg(fd, APDS9960_REG_RAW_B, b) < 0) return -1;
    return 0;
}

static int log_proximity(FILE *fp, int r, int g, int b, int proximity) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return -1;
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%d,%d,%d,%d\n", ts, r, g, b, proximity);
    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (log_file) { fclose(log_file); log_file = NULL; }
    if (i2c_fd >= 0) { close(i2c_fd); i2c_fd = -1; }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, APDS9960_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", APDS9960_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_apds9960(i2c_fd) < 0) {
        fprintf(stderr, "APDS9960 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(CSV_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open %s: %s\n", CSV_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,R,G,B,Proximity\n");
        fflush(log_file);
    }

    printf("Proximity monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        unsigned char r, g, b;
        if (read_apds9960(i2c_fd, &r, &g, &b) < 0) {
            fprintf(stderr, "I2C read error, reinitializing sensor\n");
            i2c_fd = open(I2C_BUS, O_RDWR);
            if (i2c_fd < 0) {
                fprintf(stderr, "Failed to reopen I2C bus: %s\n", strerror(errno));
                break;
            }
            if (init_apds9960(i2c_fd) < 0) {
                fprintf(stderr, "APDS9960 reinitialization failed\n");
                break;
            }
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        int proximity = (r > PROXIMITY_THRESHOLD) ? 1 : 0;
        if (log_proximity(log_file, r, g, b, proximity) < 0) {
            fprintf(stderr, "Logging failed\n");
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

