/*
 * VL53L0X Time-of-Flight sensor reader for Raspberry Pi 3 Model B+
 * Uses pigpio for I2C communication.
 *
 * Wiring:
 *   VL53L0X SDA -> GPIO 2 (I2C1 SDA)
 *   VL53L0X SCL -> GPIO 3 (I2C1 SCL)
 *   VL53L0X VDD -> 3.3 V
 *   VL53L0X GND -> GND
 *   GPIO 17 (BCM) -> I2C bus 1 SDA
 *
 * Build: gcc -Wall -o vl53l0x_reader vl53l0x_reader.c -lpigpio -lrt
 * Run:   sudo ./vl53l0x_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- VL53L0X constants ---- */
#define I2C_BUS        1
#define VL53L0X_ADDR   0x44
#define GPIO_TRIGGER   17
#define LOG_FILE       "distance_log.txt"
#define POLL_TIMEOUT_US 100000   /* 100 ms */

/* ---- VL53L0X register addresses ---- */
#define VL53L0X_REG_IDENTIFICATION_STATUS   0x00
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS 0x0C
#define VL53L0X_REG_RESULT_DISTANCE_MM     0x0F

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ---- Function prototypes ---- */
static int  init_i2c(void);
static int  init_gpio(void);
static int  read_distance(void);
static int  log_distance(int distance_mm);
static void signal_handler(int sig);
static void cleanup(void);

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Cleanup resources ---- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ---- Initialize I2C ---- */
static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (code %d)\n", g_i2c_handle);
        return -1;
    }
    return 0;
}

/* ---- Initialize GPIO ---- */
static int init_gpio(void)
{
    if (gpioSetMode(GPIO_TRIGGER, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", GPIO_TRIGGER);
        return -1;
    }
    if (gpioSetPullUpDown(GPIO_TRIGGER, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for GPIO %d\n", GPIO_TRIGGER);
        return -1;
    }
    return 0;
}

/* ---- Read distance with timeout ---- */
static int read_distance(void)
{
    uint32_t status_mask = 0;
    uint32_t status;
    int distance_mm;

    /* Poll RESULT_INTERRUPT_STATUS for falling edge */
    status_mask = VL53L0X_REG_RESULT_INTERRUPT_STATUS;
    status = i2cReadWordData(g_i2c_handle, status_mask);
    if (status < 0) {
        fprintf(stderr, "Error: i2cReadWordData failed (code %d)\n", status);
        return -1;
    }
    if (!(status & 0x00000001)) {
        fprintf(stderr, "Warning: no interrupt triggered (status=0x%08X)\n", status);
        return -1;
    }

    /* Poll RESULT_INTERRUPT_STATUS again to clear the interrupt */
    status_mask = VL53L0X_REG_RESULT_INTERRUPT_STATUS;
    status = i2cReadWordData(g_i2c_handle, status_mask);
    if (status < 0) {
        fprintf(stderr, "Error: i2cReadWordData failed (code %d)\n", status);
        return -1;
    }
    if (!(status & 0x00000001)) {
        fprintf(stderr, "Warning: interrupt cleared (status=0x%08X)\n", status);
        return -1;
    }

    /* Read distance with timeout */
    status_mask = VL53L0X_REG_RESULT_DISTANCE_MM;
    status = i2cReadWordData(g_i2c_handle, status_mask);
    if (status < 0) {
        fprintf(stderr, "Error: i2cReadWordData failed (code %d)\n", status);
        return -1;
    }
    if (status & 0x0000FFFF) {
        fprintf(stderr, "Error: distance read out of 16-bit range\n");
        return -1;
    }

    /* Clear interrupt */
    status_mask = VL53L0X_REG_RESULT_INTERRUPT_STATUS;
    status = i2cWriteWordData(g_i2c_handle, status_mask, 0x00000000);
    if (status < 0) {
        fprintf(stderr, "Error: i2cWriteWordData failed (code %d)\n", status);
        return -1;
    }

    distance_mm = (int)((status & 0x0000FFFF) << 1);

    return distance_mm;
}

/* ---- Log distance to file ---- */
static int log_distance(int distance_mm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s,%.2f\n", timestamp, distance_mm) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed\n");
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Error: fflush failed\n");
        return -1;
    }

    return 0;
}

/* ---- Main ---- */
int main(void)
{
    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Initialize I2C */
    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize GPIO */
    if (init_gpio() != 0) {
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error: fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("VL53L0X reader started. Logging to %s. Press Ctrl+C to exit.\n", LOG_FILE);

    /* Main loop */
    while (g_running) {
        int distance_mm = read_distance();

        if (distance_mm >= 0) {
            if (log_distance(distance_mm) != 0) {
                fprintf(stderr, "Warning: failed to log distance\n");
            }
