/*
 * CH101 Ultrasonic Distance Sensor Logger for Raspberry Pi 4 Model B
 * Uses libgpiod for I2C and pigpio for I2C.
 *
 * Wiring:
 *   CH101 VCC  -> 3.3 V (Pin 1)
 *   CH101 GND  -> GND  (Pin 9)
 *   CH101 SDA  -> GPIO2 / I2C1 SDA (Pin 3)
 *   CH101 SCL  -> GPIO3 / I2C1 SCL (Pin 5)
 *
 * Build: gcc -O2 -Wall -o ch101_logger ch101_logger.c -lpigpio -lgpiod
 * Run:   sudo ./ch101_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x00
#define LOG_FILE       "distance_log.txt"
#define SAMPLE_MS      200
#define TRIGGER_MS     50
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int handle, uint8_t byte)
{
    int rc = i2cWriteByteData(handle, 0, byte);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (handle %d, rc=%d)\n", handle, rc);
    }
    return rc;
}

static int i2c_read_byte(int handle, uint8_t *out)
{
    int rc = i2cReadByteData(handle, 0);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (handle %d, rc=%d)\n", handle, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* CH101 driver                                                         */
/* ------------------------------------------------------------------ */
typedef struct {
    int handle;
    int addr;
    int init_ok;
    int init_failed;
} ch101_t;

static int ch101_init(ch101_t *c)
{
    c->handle = -1;
    c->addr = I2C_ADDR;
    c->init_ok = 0;
    c->init_failed = 0;

    /* Verify sensor presence by writing 0x00 */
    if (i2c_write_byte(c->handle, 0x00) < 0) {
        fprintf(stderr, "CH101 not responding at 0x%02X\n", c->addr);
        c->init_failed = 1;
        return -1;
    }
    c->init_ok = 1;

    /* Verify sensor presence by reading 0x00 */
    uint8_t v;
    if (i2c_read_byte(c->handle, &v) < 0) {
        fprintf(stderr, "CH101 presence check failed\n");
        c->init_failed = 1;
        return -1;
    }
    if (v != 0x00) {
        fprintf(stderr, "CH101 presence check failed (got 0x%02X)\n", v);
        c->init_failed = 1;
        return -1;
    }

    /* Configure trigger: single shot, no debounce */
    if (i2c_write_byte(c->handle, 0x01) < 0) {
        fprintf(stderr, "CH101 trigger configuration failed\n");
        c->init_failed = 1;
        return -1;
    }

    /* Configure measurement: single shot, no debounce */
    if (i2c_write_byte(c->handle, 0x02) < 0) {
        fprintf(stderr, "CH101 measurement configuration failed\n");
        c->init_failed = 1;
        return -1;
    }

    c->init_ok = 1;
    return 0;
}

static int ch101_read_distance(ch101_t *c, int *distance_mm)
{
    if (c->init_ok) {
        /* Trigger the sensor */
        if (i2c_write_byte(c->handle, 0x01) < 0) {
            fprintf(stderr, "CH101 trigger failed\n");
            return -1;
        }
        gpioDelay(TRIGGER_MS * 1000);

        /* Read distance in mm (16-bit, big-endian) */
        uint8_t buf[2];
        if (i2c_read_byte(c->handle, buf) < 0) {
            fprintf(stderr, "CH101 distance read failed\n");
            return -1;
        }
        *distance_mm = (buf[0] << 8) | buf[1];
        return 0;
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_distance(FILE *fp, int distance_mm)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s, %d\n", ts, distance_mm) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                 */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (handle %d, rc=%d)\n", g_i2c_handle, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize CH101 sensor */
    ch101_t ch101 = {
        .handle = g_i2c_handle,
        .addr = I2C_ADDR,
        .init_ok = 0,
        .init_failed = 0,
    };
    if (ch101_init(&ch101) < 0) {
        fprintf(stderr, "CH101 initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed\n");
        fclose(g_log_file);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("CH101 distance logger started. Logging to '%s'. Press Ctrl-C to stop.\n", LOG_FILE);

    /* Main sampling loop */
    while (g_running) {
        int distance_mm;
        if (ch101_read_distance(&ch101, &distance_mm) < 0) {
            fprintf(stderr, "Sensor read failed; skipping sample\n");
            gpioDelay(SAMPLE_MS * 1000);
            continue;
        }

        if (log_distance(g_log_file, distance_mm) < 0) {
            fprintf(stderr, "Logging failed; skipping sample\n");
        }

        gpioDelay(SAMPLE_MS * 1000);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (g_log_file != NULL) {
        fclose(g_log_file);
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

