#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define LOG_FILE "obstacle_log.txt"
#define READ_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_reading(int sensor_pin, int reading) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t rawtime = time(NULL);
    if (rawtime == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm *timeinfo = localtime(&rawtime);
    if (!timeinfo) {
        fprintf(stderr, "Error converting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, Sensor %d: %d\n", timestamp, sensor_pin, reading) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Set GPIO pins as inputs */
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("IR proximity detection started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int reading1 = gpioRead(SENSOR_1_PIN);
        int reading2 = gpioRead(SENSOR_2_PIN);

        if (reading1 < 0 || reading2 < 0) {
            fprintf(stderr, "Error reading sensor pin %d or %d\n", SENSOR_1_PIN, SENSOR_2_PIN);
            log_reading(SENSOR_1_PIN, -1);
            log_reading(SENSOR_2_PIN, -1);
            gpioDelay(READ_INTERVAL_US);
            continue;
        }

        int reading1_err = (reading1 < 0);
        int reading2_err = (reading2 < 0);

        if (reading1_err) {
            fprintf(stderr, "Error reading sensor 1 (GPIO %d)\n", SENSOR_1_PIN);
            log_reading(SENSOR_1_PIN, -1);
        }
        if (reading2_err) {
            fprintf(stderr, "Error reading sensor 2 (GPIO %d)\n", SENSOR_2_PIN);
            log_reading(SENSOR_2_PIN, -1);
        }

        if (log_reading(SENSOR_1_PIN, reading1) != 0 ||
            log_reading(SENSOR_2_PIN, reading2) != 0) {
            fprintf(stderr, "Error logging readings\n");
        }

        gpioDelay(READ_INTERVAL_US);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    gpioTerminate();
    return EXIT_SUCCESS;
}

