/*
 * Raspberry Pi Zero W – TDK InvenSense ICU-20201 ultrasonic Time-of-Flight
 * reader + LED indicator.
 *
 * Wiring:
 *   ICU-20201 VCC  -> 3.3 V (pin 1)
 *   ICU-20201 GND  -> GND  (pin 9)
 *   ICU-20201 SDA  -> GPIO2 / I2C bus 1 SDA (pin 3)
 *   ICU-20201 SCL  -> GPIO3 / I2C bus 1 SCL (pin 5)
 *   LED anode      -> GPIO17 (BCM 17)
 *   LED cathode    -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o icu20201_led icu20201_led.c
 * Run:    sudo ./icu20201_led
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define I2C_ADDR       0x10
#define LED_PIN        17
#define DISTANCE_THRESHOLD_CM 20.0f
#define SAMPLE_DELAY_US  100000   /* 100 ms */
#define LOG_FILE        "distance_log.txt"

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_byte(0x%02X, 0x%02X): %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_byte(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "i2c_read_byte(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Distance measurement                                                */
/* ------------------------------------------------------------------ */

/*
 * Distance is measured in cm.
 * The ICU-20201 returns a 16-bit value in the range 0–65535.
 * A value of 0 indicates an error (sensor not present, bus fault, etc.).
 */
static float read_distance(int fd)
{
    uint8_t raw[2];
    if (i2c_read_byte(fd, 0x00, raw) < 0)
        return -1.0f;

    /* ICU-20201 returns a 16-bit value in the range 0–65535.
     * The 16-bit value is stored in the lower byte of the result.
     * The upper byte is reserved for future use. */
    uint16_t raw_u16 = (uint16_t)raw[0] | ((uint16_t)raw[1] << 8);

    /*
     * The ICU-20201 returns a distance in cm.
     * The raw value is a 16-bit unsigned integer.
     * The distance is calculated as:
     *   distance_cm = (raw_u16 / 65535.0f) * 100.0f;
     * If the raw value is 0, the distance is undefined.
     */
    if (raw_u16 == 0)
        return -1.0f;
    return (float)raw_u16 / 65535.0f * 100.0f;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static void log_distance(float distance)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s, Distance: %.2f cm\n", ts, distance);
    } else {
        fprintf(fp, "Timestamp error\n");
    }
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* Signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    int i2c_fd = i2c_open(I2C_BUS, I2C_ADDR);
    if (i2c_fd < 0)
        return EXIT_FAILURE;

    /* Open the LED GPIO pin as output */
    if (gpio_set_mode(LED_PIN, OUTPUT) < 0) {
        fprintf(stderr, "gpio_set_mode(%d): %s\n", LED_PIN, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("ICU-20201 LED monitor started. Logging to %s\n", LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance = read_distance(i2c_fd);

        if (distance < 0.0f) {
            fprintf(stderr, "Distance read error; skipping sample.\n");
        } else if (distance < DISTANCE_THRESHOLD_CM) {
            if (gpio_write(LED_PIN, 1) < 0) {
                fprintf(stderr, "gpio_write(1): %s\n", strerror(errno));
            } else {
                printf("Distance: %.2f cm < %.1f cm – LED ON\n",
                       distance, DISTANCE_THRESHOLD_CM);
            }
        } else {
            if (gpio_write(LED_PIN, 0) < 0) {
                fprintf(stderr, "gpio_write(0): %s\n", strerror(errno));
            } else {
                printf("Distance: %.2f cm > %.1f cm – LED OFF\n",
                       distance, DISTANCE_THRESHOLD_CM);
            }
        }

        /* Sleep 100 ms, but wake early on signal */
        for (int i = 0; i < 10 && g_running; i++)
            usleep(100000);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    gpio_write(LED_PIN, 0);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

