/*
 * Si1182-GMR Proximity & Ambient Light Logger for Raspberry Pi Zero W
 * Uses pigpio for I2C communication.
 *
 * Build: gcc -Wall -Wextra -O2 -o si1182_logger si1182_logger.c -lpigpio -lrt
 * Run:   sudo ./si1182_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x50
#define LOG_FILE       "biometric_log.txt"
#define SAMPLE_US      500000   /* 500 ms */
#define MAX_RETRIES    3
#define RETRY_DELAY_US 10000    /* 10 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_read_byte(int handle, uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %d\n",
                reg, val, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
static int read_proximity(int handle, uint16_t *prox)
{
    uint8_t buf[2];
    int rc;

    rc = i2c_read_byte(handle, 0x00, buf[0]);
    if (rc < 0) return -1;
