static int read_ambient_light(int handle, uint16_t *light)
{
    uint8_t buf[2];
    int rc;

    rc = i2c_read_byte(handle, 0x01, buf[0]);
    if (rc < 0) return -1;
    *light = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

