/*
 * Raspberry Pi Zero W - Omron B5L-LD50-07050 3D TOF Intrusion Detector
 *
 * Uses the pigpio library for I2C communication.
 *
 * Build: gcc -Wall -Wextra -O2 -o intrusion intrusion.c -lpigpio -lrt
 * Run:   sudo ./intrusion
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x5A
#define MEASURE_CMD    0x01
#define MEASURE_RESP   0x02
#define MEASURE_DELAY  10000   /* 10 ms */
#define SAMPLE_DELAY   100000  /* 100 ms */
#define LOG_FILE       "intrusion_log.txt"
#define DISTANCE_THRESH 1000   /* mm */
#define SAMPLE_COUNT   10
#define SAMPLE_DELAY   100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int fd, uint8_t byte)
{
    int rc = i2cWriteByteData(fd, 0, byte);
    if (rc < 0) {
        fprintf(stderr, "i2cWriteByteData failed (rc=%d)\n", rc);
    }
    return rc;
}

static int i2c_read_byte(int fd, uint8_t *out)
{
    int rc = i2cReadByteData(fd, 0);
    if (rc < 0) {
        fprintf(stderr, "i2cReadByteData failed (rc=%d)\n", rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

static int i2c_read_block(int fd, uint8_t *buf, int len)
{
    int rc = i2cReadI2CBlockData(fd, 0, buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "i2cReadI2CBlockData failed (rc=%d, expected=%d)\n",
                rc, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor helpers                                                      */
/* ------------------------------------------------------------------ */
static int sensor_init(int fd)
{
    if (i2c_write_byte(fd, MEASURE_CMD) < 0) {
        fprintf(stderr, "Failed to send measurement command\n");
        return -1;
    }
    gpioDelay(MEASURE_DELAY);

    uint8_t resp[15];
    if (i2c_read_block(fd, resp, sizeof(resp)) < 0) {
        fprintf(stderr, "Failed to read sensor response\n");
        return -1;
    }

    /* Verify header byte */
    if (resp[0] != MEASURE_RESP) {
        fprintf(stderr, "Unexpected response header: 0x%02X (expected 0x%02X)\n",
                resp[0], MEASURE_RESP);
        return -1;
    }

    /* Extract distance: 16-bit big-endian, little-endian on pigpio */
    uint16_t dist = ((uint16_t)resp[1] << 8) | resp[2];
    return 0;
}

static int sensor_read(int fd, float *distance)
{
    if (i2c_write_byte(fd, MEASURE_CMD) < 0) {
        return -1;
    }
    gpioDelay(MEASURE_DELAY);

    uint8_t buf[15];
    if (i2c_read_block(fd, buf, sizeof(buf)) < 0) {
        return -1;
    }

    /* Verify distance byte */
    if (buf[0] != MEASURE_RESP) {
        fprintf(stderr, "Unexpected response header: 0x%02X (expected 0x%02X)\n",
                buf[0], MEASURE_RESP);
        return -1;
    }

    /* Extract distance: 16-bit big-endian, little-endian on pigpio */
    uint16_t dist_raw = ((uint16_t)buf[1] << 8) | buf[2];
    *distance = (float)dist_raw / 1000.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_event(float avg_distance)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s, Avg Distance: %.2f mm\n", ts, avg_distance) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return -1;
    }
    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "i2cOpen failed (rc=%d)\n", g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (sensor_init(g_i2c_fd) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        i2cClose(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Intrusion detection started. Press Ctrl+C to exit.\n");

    float avg_distance = 0.0f;
    int intr_detected = 0;

    while (g_running) {
        float distance;
        if (sensor_read(g_i2c_fd, &distance) == 0) {
            avg_distance = distance;
            intr_detected = 1;
        } else {
            fprintf(stderr, "Sensor read failed; retrying next cycle\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_COUNT && g_running; i++) {
            gpioDelay(100000);
        }
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        i2cClose(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioTerminate();

    printf("Intrusion detection stopped.\n");
    return EXIT_SUCCESS;
}

