    float avg_distance = 0.0f;
    int intr_detected = 0;

    while (g_running) {
        float distance;
        if (sensor_read(g_i2c_fd, &distance) == 0) {
            avg_distance = distance;
            intr_detected = 1;
        } else {
            fprintf(stderr, "Sensor read failed; retrying next cycle\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_COUNT && g_running; i++) {
            gpioDelay(100000);
        }
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        i2cClose(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioTerminate();

    printf("Intrusion detection stopped.\n");
    return EXIT_SUCCESS;
}

