        return -1;
    }
    if (ioctl(*fd, I2C_SLAVE, MLX75030_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                MLX75030_ADDR, strerror(errno));
        close(*fd);
        *fd = -1;
        return -1;
    }
    return 0;
}

static int read_distance(int fd, uint16_t *distance)
{
    if (i2c_write_reg16(fd, MLX75030_REG_CMD_READ_MEASUREMENT, 0x00) < 0)
