{
    int fd = -1;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (init_i2c(&fd) < 0) {
        fprintf(stderr, "I2C initialization failed.\n");
        return EXIT_FAILURE;
    }

    printf("MLX75030 initialized on %s at 0x%02X.\n", I2C_BUS, MLX75030_ADDR);
    printf("Press Ctrl-C to exit.\n");

    while (g_running) {
        uint16_t distance;
        if (read_distance(fd, &distance) < 0) {
            fprintf(stderr, "Distance read failed; continuing.\n");
        } else {
            printf("Distance: %u mm\n", distance);
        }
        usleep(500000);
