#include <signal.h>

#define I2C_BUS        "/dev/i2c-1"
#define OPT3101_ADDR   0x50
#define DISTANCE_REG   0x00
#define LIGHT_REG      0x01
#define ERROR_FLAG_0   0x01
#define ERROR_FLAG_1   0x02
#define ERROR_FLAG_2   0x04
#define ERROR_FLAG_3   0x08
#define ERROR_FLAG_4   0x10
#define ERROR_FLAG_5   0x20
#define ERROR_FLAG_6   0x40
#define ERROR_FLAG_7   0x80

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, out, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int opt3101_init(int fd)
{
    if (i2c_write_byte(fd, DISTANCE_REG, 0x00) < 0)
        return -1;
    if (i2c_write_byte(fd, LIGHT_REG, 0x00) < 0)
        return -1;
    return 0;
}

static int opt3101_read_distance(int fd, float *distance)
{
    uint8_t err_flags = 0;
    uint16_t raw;

    if (i2c_read_word(fd, DISTANCE_REG, &raw) < 0)
        return -1;

    if (raw & ERROR_FLAG_0) {
        err_flags |= ERROR_FLAG_0;
    }
    if (raw & ERROR_FLAG_1) {
        err_flags |= ERROR_FLAG_1;
    }
    if (raw & ERROR_FLAG_2) {
        err_flags |= ERROR_FLAG_2;
    }
    if (raw & ERROR_FLAG_3) {
        err_flags |= ERROR_FLAG_3;
    }
    if (raw & ERROR_FLAG_4) {
        err_flags |= ERROR_FLAG_4;
    }
    if (raw & ERROR_FLAG_5) {
        err_flags |= ERROR_FLAG_5;
    }
    if (raw & ERROR_FLAG_6) {
        err_flags |= ERROR_FLAG_6;
    }
    if (raw & ERROR_FLAG_7) {
        err_flags |= ERROR_FLAG_7;
    }

    if (err_flags) {
        fprintf(stderr, "OPT3101 error: 0x%04X (0x%02X)\n",
                raw, err_flags);
        return -1;
    }

    *distance = (float)raw / 10.0f;
    return 0;
}

