{
    int fd = -1;
    float distance = 0.0f;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, OPT3101_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                OPT3101_ADDR, strerror(errno));
        goto cleanup;
    }

    if (opt3101_init(fd) < 0) {
        fprintf(stderr, "OPT3101 initialization failed.\n");
        goto cleanup;
    }

    printf("OPT3101 initialized on I2C bus %s. Press Ctrl+C to exit.\n",
           I2C_BUS);

    while (g_running) {
        if (opt3101_read_distance(fd, &distance) < 0) {
            fprintf(stderr, "Error reading distance, retrying in 500 ms.\n");
            usleep(500000);
            continue;
        }
        printf("Distance: %.2f mm\n", distance);
        fflush(stdout);
        usleep(500000);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);
    printf("\nExiting cleanly.\n");
    return rc;
}

