/*
 * HC-SR04 Ultrasonic Distance Sensor Reader
 * Board:  Raspberry Pi 3 Model B+
 * Sensor: HC-SR04 on GPIO 17 (BCM)  Trigger
 *         GPIO 18 (BCM)  Echo
 *
 * Wiring:
 *   HC-SR04 VCC  ->  3.3 V (Pin 1)
 *   HC-SR04 GND  ->  GND  (Pin 6)
 *   HC-SR04 TRIG -> GPIO 17 (BCM)
 *   HC-SR04 ECHO-> GPIO 18 (BCM)
 *
 * HC-SR04 operates at 5 V.  The Pi GPIO is 3.3 V tolerant; a 1 kΩ
 * resistor on the echo line within the library’s API call() is
 * recommended for 5 V operation.
 *
 * Build:  gcc -O2 -Wall -Wextra -o hcsr04_reader hcsr04_reader.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#include <gpiod.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18
#define POLL_TIMEOUT_US  200000   /* 200 ms */
#define READ_INTERVAL_S  1
#define MAX_RANGE_US     38000    /* HC-SR04 max range ~14 m */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        snprintf(buf, len, "UNKNOWN");
        return;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        snprintf(buf, len, "UNKNOWN");
        return;
    }
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_distance(float distance_m)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    printf("%s  Distance: %.2f m\n", ts, distance_m);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* HC-SR04 API                                                         */
/* ------------------------------------------------------------------ */
/*
 * Returns 0 on success, -1 on error.
 *
 * The HC-SR04 API call() provides microsecond precision.
 *
 * The echo line must be pulled low before the trigger is sent.
 * The library expects a 10 µs trigger pulse.
 *
 * The echo line must be pulled high after the echo pulse.
 *
 * The HC-SR04 operates at 5 V.  The Pi GPIO is 3.3 V tolerant;
 * a 1 kΩ resistor on the echo line within the library’s API call()
 * is recommended for 5 V operation.
 */
static int hcsr04_trigger_echo(struct gpiod_line *trigger,
                                struct gpiod_line *echo)
{
    if (!trigger || !echo) {
        fprintf(stderr, "hcsr04_trigger_echo: invalid GPIO handle\n");
        return -1;
    }

    /* Ensure trigger is low */
    if (gpiod_line_set_value(trigger, 0) < 0) {
        fprintf(stderr, "hcsr04_trigger_echo: set trigger low failed: %s\n",
                strerror(errno));
        return -1;
    }

    /* 10 µs trigger pulse */
    if (gpiod_line_set_value(trigger, 1) < 0) {
        fprintf(stderr, "hcsr04_trigger_echo: set trigger high failed: %s\n",
                strerror(errno));
        return -1;
    }

    /* Wait for echo rising edge */
    struct timespec ts_start;
    if (clock_gettime(CLOCK_MONOTONIC, &ts_start) < 0) {
        fprintf(stderr, "hcsr04_trigger_echo: clock_gettime failed: %s\n",
                strerror(errno));
        return -1;
    }
    struct timespec ts_wait;
    ts_wait.tv_sec  = 0;
    ts_wait.tv_nsec = POLL_TIMEOUT_US;
    if (nanosleep(&ts_wait, &ts_start) < 0) {
        fprintf(stderr, "hcsr04_trigger_echo: nanosleep failed: %s\n",
                strerror(errno));
        return -1;
    }

    ts_start.tv_sec  += ts_wait.tv_sec;
    ts_start.tv_nsec += ts_wait.tv_nsec;

    if (ts_start.tv_nsec >= MAX_RANGE_US) {
        fprintf(stderr, "hcsr04_trigger_echo: echo rising edge timeout\n");
        return -1;
    }

    /* Wait for echo falling edge */
    ts_wait.tv_sec  = 0;
    ts_wait.tv_nsec = POLL_TIMEOUT_US;
    if (nanosleep(&ts_wait, &ts_start) < 0) {
        fprintf(stderr, "hcsr04_trigger_echo: nanosleep failed: %s\n",
                strerror(errno));
        return -1;
    }

    ts_start.tv_sec  += ts_wait.tv_sec;
    ts_start.tv_nsec += ts_wait.tv_nsec;

    if (ts_start.tv_nsec >= MAX_RANGE_US) {
        fprintf(stderr, "hcsr04_trigger_echo: echo falling edge timeout\n");
        return -1;
    }

    /*
     * The HC-SR04 API call() provides microsecond precision.
     * The echo line must be pulled high after the echo pulse.
     */
    if (gpiod_line_set_value(echo, 1) < 0) {
        fprintf(stderr, "hcsr04_trigger_echo: set echo high failed: %s\n",
                strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open GPIO chip --- */
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Get GPIO lines --- */
    struct gpiod_line *trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger) {
        fprintf(stderr, "gpiod_chip_get_line(TRIGGER): %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct gpiod_line *echo   = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        fprintf(stderr, "gpiod_chip_get_line(ECHO): %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* --- Request lines --- */
    if (gpiod_line_request_output(trigger, "hcsr04_trigger", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output(TRIGGER): %s\n",
                strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(echo, "hcsr04_echo") < 0) {
        fprintf(stderr, "gpiod_line_request_input(ECHO): %s\n",
                strerror(errno));
        gpiod_line_release(trigger);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance reader started.  Press Ctrl+C to exit.\n");
    printf("  Trigger  -> GPIO %d\n", TRIGGER_PIN);
    printf("  Echo     -> GPIO %d\n", ECHO_PIN);
    printf("  Threshold: %.0f ms (max range ~14 m)\n", MAX_RANGE_US / 1000.0);
    printf("  Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        float distance = 0.0f;

        if (hcsr04_trigger_echo(trigger, echo) < 0) {
            fprintf(stderr, "Error: HC-SR04 trigger/echo failed\n");
            break;
        }

        distance = (float)distance_us_to_mm(distance);

        if (distance < 0.0f) {
            fprintf(stderr, "Error: distance conversion failed\n");
            break;
        }

        log_distance(distance);
        printf("Distance: %.2f mm\n", distance);

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < READ_INTERVAL_S * 10 && g_running; i++) {
            usleep(100000);
        }
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    gpiod_line_release(trigger);
    gpiod_line_release(echo);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

