#define THRESHOLD_DISTANCE 1.0f
#define ALERT_DURATION_MS 2000
#define LOG_FILE "intrusion_log.csv"
#define MAX_FRAME_SIZE 128
#define MAX_FRAME_LEN 64

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int initialize_uart(const char *device, speed_t baud) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud);
    cfsetispeed(&tty, baud);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);

    tty.c_lflag = 0;
    tty.c_oflag = 0;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 10;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_frame(int fd, float *range_data, int *frame_len) {
    unsigned char buffer[MAX_FRAME_LEN];
    int frame_size = 0;
    int bytes_read = 0;

    while (bytes_read < MAX_FRAME_LEN) {
        ssize_t n = read(fd, buffer + bytes_read, MAX_FRAME_LEN - bytes_read);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "Warning: UART read returned 0 bytes\n");
            return -1;
        }
        bytes_read += n;
    }

    if (frame_size == 0) {
        fprintf(stderr, "Error: No data frame received\n");
        return -1;
    }

    if (frame_size > MAX_FRAME_LEN) {
        fprintf(stderr, "Error: Frame size exceeds maximum allowed: %d\n", frame_size);
        return -1;
    }

    for (int i = 0; i < frame_size; i++) {
        int bin_index = (buffer[i] & 0x7F) << 1;
        if (buffer[i + 1] & 0x80) {
            bin_index++;
        }
        range_data[bin_index] = (float)buffer[i] * 0.01f;
    }

    return 0;
}

static float calculate_distance(const float *range_data, int frame_len) {
    if (frame_len == 0) return 0.0f;

    float sum_distance = 0.0f;
    for (int i = 0; i < frame_len; i++) {
        sum_distance += range_data[i];
    }
    return sum_distance / frame_len;
}

static int log_intrusion(const char *timestamp, float distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void activate_alert(int gpio_pin) {
    if (gpio_pin < 0) return;
    if (gpio_pin > 17) return;

    if (gpio_pin == 17) {
        printf("Alert LED activated on GPIO %d\n", gpio_pin);
    } else {
        printf("Alert LED deactivated on GPIO %d\n", gpio_pin);
    }
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    int uart_fd = initialize_uart(UART_DEVICE, SERIAL_BAUD_RATE);
    if (uart_fd < 0) {
        return 1;
    }

    printf("UART initialized on %s at %d baud. Press Ctrl+C to exit.\n", UART_DEVICE, SERIAL_BAUD_RATE);

    while (program_running) {
        float range_data[MAX_FRAME_LEN];
        int frame_len;

        if (read_frame(uart_fd, range_data, &frame_len) == 0) {
            float distance = calculate_distance(range_data, frame_len);

            if (distance < 0.0f) {
                fprintf(stderr, "Error calculating distance\n");
            } else {
                if (distance < THRESHOLD_DISTANCE) {
                    printf("Intrusion detected! Distance: %.2f meters\n", distance);
                    log_intrusion(time(NULL), distance);
                    activate_alert(ALERT_LED_GPIO);
                }
            }
        } else {
            fprintf(stderr, "Error reading UART frame\n");
        }

        usleep(ALERT_DURATION_MS * 1000);
    }

    printf("\nCleaning up...\n");
    if (uart_fd >= 0) {
        close(uart_fd);
    }
    printf("Program terminated.\n");
    return 0;
}

