#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_GPIO 17
#define BUZZER_GPIO 18
#define LOG_FILE "obstacle_log.txt"
#define POLL_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *event) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return -1;
    }
    fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fclose(fp);
    return 0;
}

static int read_sensor(int gpio) {
    int level = gpioRead(gpio);
    if (level < 0) {
        fprintf(stderr, "gpioRead failed on GPIO %d: %s\n", gpio, strerror(errno));
        return -1;
    }
    return level;
}

static void control_buzzer(int gpio, int state) {
    gpioWrite(gpio, state);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", BUZZER_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(BUZZER_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialise buzzer state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Obstacle detection started on GPIO %d (sensor) and GPIO %d (buzzer). Press Ctrl+C to exit.\n",
           SENSOR_GPIO, BUZZER_GPIO);

    while (running) {
        int sensor_value = read_sensor(SENSOR_GPIO);
        if (sensor_value < 0) {
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (sensor_value == 0) {
            printf("Obstacle detected!\n");
            if (log_event("Obstacle detected") != 0) {
                fprintf(stderr, "Failed to log obstacle event\n");
            }
            control_buzzer(BUZZER_GPIO, 1);
        } else {
            printf("No obstacle detected.\n");
            if (log_event("No obstacle detected") != 0) {
                fprintf(stderr, "Failed to log obstacle event\n");
            }
            control_buzzer(BUZZER_GPIO, 0);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    control_buzzer(BUZZER_GPIO, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

