/*
 * TDK Chirp ICU-20201 ultrasonic time-of-flight sensor reader for Raspberry Pi 4.
 *
 * Wiring:
 *   Sensor VCC  -> 3.3 V (Pin 1)
 *   Sensor GND  -> GND  (Pin 9)
 *   Sensor SDA  -> GPIO2 / I2C1 SDA (Pin 3)
 *   Sensor SCL  -> GPIO3 / I2C1 SCL (Pin 5)
 *   Sensor INT  -> GPIO14 / I2C1 SCL (Pin 5)
 *   Alert pin   -> GPIO17 / I2C1 SDA (Pin 7)
 *
 * Build:  gcc -O2 -Wall -Wextra -o chirp_icu chirp_icu.c -lrt
 * Run:    sudo ./chirp_icu
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SENSOR_ADDR    0x10
#define ALERT_PIN      17
#define DISTANCE_THRESHOLD_CM 10.0f
#define LOG_FILE       "distance_log.txt"
#define SAMPLE_DELAY_US 100000   /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_write_byte(int fd, uint8_t byte)
{
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C short read: got %zd of %zu\n", n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor helpers                                                      */
/* ------------------------------------------------------------------ */

static int read_distance(int fd)
{
    uint8_t cmd = 0x01;
    uint8_t buf[2] = {0};

    if (i2c_write_byte(fd, cmd) < 0)
        return -1;

    if (i2c_read_bytes(fd, buf, 2) < 0)
        return -1;

    return (int16_t)((buf[0] << 8) | buf[1]);
}

static int log_distance(float distance)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s, Distance: %.2f cm\n", ts, distance);
    } else {
        fprintf(fp, "Timestamp error\n");
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                       */
/* ------------------------------------------------------------------ */

static int setup_alert_pin(int fd)
{
    if (ioctl(fd, PI_I2C_SLAVE, SENSOR_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                SENSOR_ADDR, strerror(errno));
        return -1;
    }

    if (gpio_output(ALERT_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialize GPIO %d as output: %s\n",
                ALERT_PIN, strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    gpio_set_direction(ALERT_PIN, 0);
    gpio_write(ALERT_PIN, 0);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                SENSOR_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (setup_alert_pin(fd) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Chirp ICU-20201 monitoring started. Logging to '%s'.\n",
           LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance = read_distance(fd);

        if (distance < 0) {
            fprintf(stderr, "Sensor read error; retrying next cycle.\n");
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        if (distance < DISTANCE_THRESHOLD_CM) {
            if (gpio_write(ALERT_PIN, 1) < 0)
                fprintf(stderr, "Warning: failed to assert alert pin: %s\n",
                        strerror(errno));
            printf("Distance below threshold: %.2f cm. Alert active.\n",
                   distance);
        } else {
            if (gpio_write(ALERT_PIN, 0) < 0)
                fprintf(stderr, "Warning: failed to deassert alert pin: %s\n",
                        strerror(errno));
            printf("Distance above threshold: %.2f cm. No alert.\n",
                   distance);
        }

        if (log_distance(distance) < 0)
            fprintf(stderr, "Logging failed; continuing.\n");

        usleep(SAMPLE_DELAY_US);
    }

    printf("\nShutting down cleanly.\n");
    cleanup_gpio();
    close(fd);
    return EXIT_SUCCESS;
}

