static void cleanup_gpio(void)
{
    gpio_set_direction(ALERT_PIN, 0);
    gpio_write(ALERT_PIN, 0);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                SENSOR_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (setup_alert_pin(fd) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Chirp ICU-20201 monitoring started. Logging to '%s'.\n",
           LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance = read_distance(fd);

        if (distance < 0) {
            fprintf(stderr, "Sensor read error; retrying next cycle.\n");
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        if (distance < DISTANCE_THRESHOLD_CM) {
            if (gpio_write(ALERT_PIN, 1) < 0)
                fprintf(stderr, "Warning: failed to assert alert pin: %s\n",
                        strerror(errno));
            printf("Distance below threshold: %.2f cm. Alert active.\n",
                   distance);
        } else {
            if (gpio_write(ALERT_PIN, 0) < 0)
                fprintf(stderr, "Warning: failed to deassert alert pin: %s\n",
                        strerror(errno));
            printf("Distance above threshold: %.2f cm. No alert.\n",
                   distance);
        }

        if (log_distance(distance) < 0)
            fprintf(stderr, "Logging failed; continuing.\n");

        usleep(SAMPLE_DELAY_US);
    }

    printf("\nShutting down cleanly.\n");
    cleanup_gpio();
    close(fd);
    return EXIT_SUCCESS;
}

