/*
 * parking_assist.c — Raspberry Pi 3 Model B+
 *
 * Hardware:
 *   - VL53L1X Time-of-Flight sensor on I2C bus 1, address 0x53.
 *   - Parking guidance:
 *     - STOP  < 300 mm
 *     - APPROACH 300–600 mm
 *     - SLOW  600–1200 mm
 *     - CLEAR > 1200 mm
 *
 * Build:  gcc -O2 -Wall -Wextra -o parking_assist parking_assist.c
 * Run:    ./parking_assist
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS          "/dev/i2c-1"
#define VL53L1X_ADDR     0x53
#define LOG_FILE         "distance_log.csv"
#define POLL_MS          100

/* VL53L1X register addresses (from datasheet) */
#define VL53L1X_REG_SOFT_RESET   0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0081
#define VL53L1X_REG_RESULT_DISTANCE_MM 0x0088
#define VL53L1X_REG_RESULT_DISTANCE_MM_HIGH 0x0089
#define VL53L1X_REG_CONFIG_PARAMETER 0x00B0
#define VL53L1X_REG_CONFIG_PARAMETER_VALUE 0x00B1
#define VL53L1X_REG_RESULT_CONFIG_PARAMETER 0x00B2
#define VL53L1X_REG_RESULT_CONFIG_PARAMETER_VALUE 0x00B3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg(uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(g_i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(uint8_t reg, uint8_t *val)
{
    if (write(g_i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(g_i2c_fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(g_i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(g_i2c_fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read block from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* VL53L1X driver                                                      */
/* ------------------------------------------------------------------ */
static int vl53l1x_init(void)
{
    /* Soft reset */
    if (i2c_write_reg(VL53L1X_REG_SOFT_RESET, 0x00) < 0)
        return -1;
    usleep(10000); /* 10 ms */

    /* Configure measurement range: ~1.5 mm resolution */
    if (i2c_write_reg(VL53L1X_REG_CONFIG_PARAMETER, 0x00) < 0)
        return -1;
    if (i2c_write_reg(VL53L1X_REG_CONFIG_PARAMETER_VALUE, 0x00) < 0)
        return -1;
    if (i2c_write_reg(VL53L1X_REG_RESULT_CONFIG_PARAMETER, 0x00) < 0)
        return -1;
    if (i2c_write_reg(VL53L1X_REG_RESULT_CONFIG_PARAMETER_VALUE, 0x00) < 0)
        return -1;

    /* Start first measurement */
    if (i2c_write_reg(VL53L1X_REG_SOFT_RESET, 0x01) < 0)
        return -1;
    usleep(10000); /* 10 ms */

    return 0;
}

static int vl53l1x_read_distance(uint16_t *distance_mm)
{
    uint8_t status;
    uint8_t dist_mm[2];

    /* Read range status */
    if (i2c_read_reg(VL53L1X_REG_RESULT_RANGE_STATUS, &status) < 0)
        return -1;

    /* Check if measurement is complete (bit 0 of status) */
    if (!(status & 0x01)) {
        fprintf(stderr, "VL53L1X: measurement incomplete (status=0x%02X)\n",
                status);
        return -1;
    }

    /* Read distance (2 bytes, MSB first) */
    if (i2c_read_block(VL53L1X_REG_RESULT_DISTANCE_MM, dist_mm, 2) < 0)
        return -1;

    *distance_mm = (uint16_t)((dist_mm[1] << 8) | dist_mm[0]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_distance(uint16_t distance_mm)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s,%.2f\n", ts, distance_mm) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush log failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire sensor */
    if (vl53l1x_init() < 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        if (fprintf(g_log_fp, "timestamp,distance_mm\n") < 0) {
            fprintf(stderr, "fprintf header failed: %s\n", strerror(errno));
            fclose(g_log_fp);
            close(g_i2c_fd);
            return EXIT_FAILURE;
        }
        if (fflush(g_log_fp) != 0) {
            fprintf(stderr, "fflush header failed: %s\n", strerror(errno));
            fclose(g_log_fp);
            close(g_i2c_fd);
            return EXIT_FAILURE;
        }
    }

    printf("Parking assistance system started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        uint16_t distance_mm;

        if (vl53l1x_read_distance(&distance_mm) < 0) {
            fprintf(stderr, "Distance read failed; continuing.\n");
        } else {
            if (log_distance(distance_mm) < 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            } else {
                printf("Distance: %u mm\n", distance_mm);
            }
        }

        /* Sleep POLL_MS, checking g_running every 100 ms */
        for (int i = 0; i < POLL_MS && g_running; i++)
            usleep(100000);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    if (g_log_fp != NULL) {
        if (fclose(g_log_fp) != 0)
            fprintf(stderr, "fclose log failed: %s\n", strerror(errno));
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        if (close(g_i2c_fd) != 0)
            fprintf(stderr, "close i2c failed: %s\n", strerror(errno));
        g_i2c_fd = -1;
    }

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

