/*
 * Raspberry Pi 4 Model B – TDK InvenSense CH201 ultrasonic Time-of-Flight
 * reader + LED blinker (BCM GPIO 18, 330 Ω resistor to 3.3 V)
 *
 * Build:  gcc -O2 -Wall -Wextra -o ch201 ch201.c -lpigpio -lrt
 * Run:    sudo ./ch201
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS            1
#define I2C_ADDR           0x10          /* CH201 default address */
#define LED_GPIO           18
#define BLINK_DELAY_US     100000        /* 100 ms */
#define MAX_RETRIES        3
#define RETRY_DELAY_US     10000         /* 10 ms */
#define SAMPLE_PERIOD_US   100000        /* 100 ms */

/* CH201 register map (16-bit, big-endian on wire) */
#define CH201_REG_DISTANCE_MSB 0x00
#define CH201_REG_DISTANCE_LSB 0x01
#define CH201_REG_LED_GPIO     0x02
#define CH201_REG_LED_PWM      0x03
#define CH201_REG_LED_PWM_ON   0x04
#define CH201_REG_LED_PWM_OFF  0x05
#define CH201_REG_LED_PWM_ON_MS 0x06
#define CH201_REG_LED_PWM_OFF_MS 0x07

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int handle, uint8_t reg, uint8_t value)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteByteData(handle, reg, value);
        if (rc == 0)
            return 0;
        fprintf(stderr, "I2C write reg 0x%02X failed (attempt %d/%d): rc=%d\n",
                reg, attempt + 1, MAX_RETRIES, rc);
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int i2c_read_reg8(int handle, uint8_t reg, uint8_t *out)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cReadByteData(handle, reg);
        if (rc == 0) {
            *out = (uint8_t)rc;
            return 0;
        }
