#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define LOG_FILE "proximity_log.txt"
#define POLL_INTERVAL_US 10000
#define DEBOUNCE_US 50000
#define MAX_RETRIES 3

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_event(int sensor_id, const char *event_type) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s - Sensor %d: %s\n", timestamp, sensor_id, event_type) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "gpioRead failed on GPIO %d: %s\n", gpio_pin, pigpio_error(value));
        return -1;
    }
    return value;
}

static int debounce_sensor(int gpio_pin) {
    int last_value = read_sensor(gpio_pin);
    if (last_value < 0) return -1;
    gpioDelay(DEBOUNCE_US);
    int current_value = read_sensor(gpio_pin);
    if (current_value < 0) return -1;
    if (last_value != current_value) return -1;
    return 0;
}

static int read_sensor_with_retry(int gpio_pin) {
    int retries = 0;
    int value = -1;
    while (retries < MAX_RETRIES && value < 0) {
        value = read_sensor(gpio_pin);
        if (value < 0) {
            retries++;
            if (retries < MAX_RETRIES) gpioDelay(100000);
        } else {
            break;
        }
    }
