/*
 * TDK CH-101 Time-of-Flight distance sensor reader for Raspberry Pi 5.
 *
 * Wiring:
 *   TDK CH-101 VCC  -> 3.3 V (pin 1)
 *   TDK CH-101 GND  -> GND  (pin 9)
 *   TDK CH-101 SDA  -> GPIO2 / I2C bus 1 SDA (pin 3)
 *   TDK CH-101 SCL  -> GPIO3 / I2C bus 1 SCL (pin 5)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o ch101_reader ch101_reader.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define CH101_ADDR     0x5A
#define LOG_FILE       "distance_log.csv"
#define SAMPLE_MS      500
#define MEAS_STATUS_REG 0x00
#define MEAS_STATUS_VAL_READY 0x01

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * Write a single byte to the CH-101.
 * Returns 0 on success, -1 on failure.
 */
static int ch101_write_byte(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "write(reg=0x%02X, val=0x%02X): %s\n",
                reg, value, n < 0 ? strerror(errno) : "short write");
        return -1;
    }
    return 0;
}

/*
 * Read a single byte from the CH-101.
 * Returns 0 on success, -1 on failure.
 */
static int ch101_read_byte(int fd, uint8_t reg, uint8_t *out)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "write(reg=0x%02X): %s\n", reg, n < 0 ? strerror(errno) : "short write");
        return -1;
    }
    n = read(fd, out, 1);
    if (n != 1) {
        fprintf(stderr, "read(reg=0x%02X): %s\n", reg, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit big-endian value from the CH-101.
 * Returns 0 on success, -1 on failure.
 */
static int ch101_read_word(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    if (ch101_read_byte(fd, reg, buf) < 0)
        return -1;
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/*
 * Read a 16-bit little-endian value from the CH-101.
 * Returns 0 on success, -1 on failure.
 */
static int ch101_read_word_le(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    if (ch101_read_byte(fd, reg, buf[0]) < 0)
        return -1;
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Distance measurement                                               */
/* ------------------------------------------------------------------ */
static int ch101_read_distance(int fd, uint16_t *distance_mm)
{
    uint8_t status = 0;
    uint8_t val;

    /* Poll MEAS_STATUS until it becomes READY (0x01) or timeout */
    for (int i = 0; i < 50; i++) {
        if (ch101_read_byte(fd, MEAS_STATUS_REG, &status) < 0)
            return -1;
        if (status & MEAS_STATUS_VAL_READY)
            break;
        usleep(1000);
    }

    if (status & MEAS_STATUS_VAL_READY) {
        /* Read distance in 16-bit little-endian format */
        if (ch101_read_word_le(fd, MEAS_STATUS_REG, &val) < 0)
            return -1;
        *distance_mm = (uint16_t)val;
        return 0;
    }

    fprintf(stderr, "Distance measurement timeout (status=0x%02X)\n", status);
    return -1;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_distance(FILE *fp, uint16_t distance_mm)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time(): %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", ts, distance_mm) < 0) {
        fprintf(stderr, "fprintf to log: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush log: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    g_i2c_fd = i2c_open(I2C_BUS, CH101_ADDR);
    if (g_i2c_fd < 0)
        return EXIT_FAILURE;

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,distance_mm\n");
        fflush(g_log_fp);
    }

    printf("TDK CH-101 distance logger started. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t distance_mm = 0;

        if (ch101_read_distance(g_i2c_fd, &distance_mm) < 0) {
            fprintf(stderr, "Distance read failed; skipping sample.\n");
            usleep(SAMPLE_MS * 1000);
            continue;
        }

        if (log_distance(g_log_fp, distance_mm) < 0) {
            fprintf(stderr, "Logging failed; skipping sample.\n");
        }

        usleep(SAMPLE_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

