        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", ts, distance_mm) < 0) {
        fprintf(stderr, "fprintf to log: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush log: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    g_i2c_fd = i2c_open(I2C_BUS, CH101_ADDR);
    if (g_i2c_fd < 0)
        return EXIT_FAILURE;

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,distance_mm\n");
        fflush(g_log_fp);
    }

    printf("TDK CH-101 distance logger started. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t distance_mm = 0;

        if (ch101_read_distance(g_i2c_fd, &distance_mm) < 0) {
            fprintf(stderr, "Distance read failed; skipping sample.\n");
            usleep(SAMPLE_MS * 1000);
            continue;
        }

        if (log_distance(g_log_fp, distance_mm) < 0) {
            fprintf(stderr, "Logging failed; skipping sample.\n");
        }

        usleep(SAMPLE_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
