/*
 * Raspberry Pi Zero W - MLX75030 Time-of-Flight Sensor Reader
 *
 * Reads distance measurements from a Melexis MLX75030 Time-of-Flight sensor
 * on I2C bus 1 every 100 ms and logs the timestamped distance to the
 * console.  Handles I2C errors, bus failures, and SIGINT for graceful
 * shutdown.
 *
 * Build:  gcc -O2 -Wall -o mlx75030_reader mlx75030_reader.c
 * Run:    sudo ./mlx75030_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX75030_ADDR  0x50
#define READ_INTERVAL_MS 100
#define MAX_RETRIES     3
#define RETRY_DELAY_MS   10

/* MLX75030 register addresses */
#define REG_DISTANCE_MSB   0x00
#define REG_DISTANCE_LSB   0x01
#define REG_DISTANCE_MSB_HIGH 0x02
#define REG_DISTANCE_LSB_HIGH 0x03

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, buf, 2) == 2)
            return 0;
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, &reg, 1) != 1) {
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        if (read(fd, out, 1) == 1)
            return 0;
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int i2c_read_reg16(int fd, uint8_t reg_lsb, uint16_t *out)
{
    uint8_t buf[2];
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, &reg_lsb, 1) != 1) {
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        if (read(fd, buf, 2) == 2) {
            *out = (uint16_t)((buf[0] << 8) | buf[1]);
            return 0;
        }
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int init_sensor(int fd)
{
    /*
     * MLX75030 register map (from datasheet).
     * The sensor responds to a write of 0x00 followed by a read of
     * 0x01, then 0x02, 0x03, etc.  We use a single write to set the
     * register address and then read the response.
     */
    if (i2c_write_reg8(fd, REG_DISTANCE_MSB, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write register address 0x00\n");
        return -1;
    }
    usleep(10000);

    if (i2c_read_reg8(fd, REG_DISTANCE_MSB, &g_i2c_fd) < 0) {
        fprintf(stderr, "Error: failed to read register address 0x00\n");
        return -1;
    }

    if (i2c_write_reg8(fd, REG_DISTANCE_MSB, 0x01) < 0) {
        fprintf(stderr, "Error: failed to write register address 0x01\n");
        return -1;
    }
    usleep(10000);

    if (i2c_read_reg8(fd, REG_DISTANCE_MSB, &g_i2c_fd) < 0) {
        fprintf(stderr, "Error: failed to read register address 0x01\n");
        return -1;
    }

    if (i2c_write_reg8(fd, REG_DISTANCE_MSB, 0x02) < 0) {
        fprintf(stderr, "Error: failed to write register address 0x02\n");
        return -1;
    }
    usleep(10000);

    if (i2c_read_reg8(fd, REG_DISTANCE_MSB, &g_i2c_fd) < 0) {
        fprintf(stderr, "Error: failed to read register address 0x02\n");
        return -1;
    }

    if (i2c_write_reg8(fd, REG_DISTANCE_MSB, 0x03) < 0) {
        fprintf(stderr, "Error: failed to write register address 0x03\n");
        return -1;
    }
    usleep(10000);

    if (i2c_read_reg8(fd, REG_DISTANCE_MSB, &g_i2c_fd) < 0) {
        fprintf(stderr, "Error: failed to read register address 0x03\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Distance measurement                                                 */
/* ------------------------------------------------------------------ */
static int read_distance(int fd, uint16_t *distance_out)
{
    uint8_t msb, lsb, lsb_high;

    if (i2c_read_reg8(fd, REG_DISTANCE_MSB, &msb) < 0)
        return -1;
    if (i2c_read_reg8(fd, REG_DISTANCE_LSB, &lsb) < 0)
        return -1;
    if (i2c_read_reg8(fd, REG_DISTANCE_MSB_HIGH, &lsb_high) < 0)
        return -1;

    *distance_out = ((uint16_t)(msb << 8) | lsb) | ((uint16_t)lsb_high << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_distance(uint16_t distance)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    printf("%s  Distance: %u\n", ts, distance);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Error: cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MLX75030_ADDR) < 0) {
        fprintf(stderr, "Error: cannot set I2C slave address 0x%02X: %s\n",
                MLX75030_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_sensor(g_i2c_fd) < 0) {
        fprintf(stderr, "Error: sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MLX75030 sensor initialized on %s at 0x%02X.\n", I2C_BUS, MLX75030_ADDR);
    printf("Press Ctrl-C to exit.\n");
    fflush(stdout);

    while (g_running) {
        uint16_t distance;

        if (read_distance(g_i2c_fd, &distance) < 0) {
            fprintf(stderr, "Error: read failed; continuing...\n");
            usleep(READ_INTERVAL_MS * 1000);
            continue;
        }

        log_distance(distance);
        usleep(READ_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

