code:
/*
 * VL53L4CX Time-of-Flight Distance Sensor Reader for Raspberry Pi Zero W
 *
 * Wiring:
 *   VL53L4CX SDA -> GPIO2 (I2C bus 1 SDA)
 *   VL53L4CX SCL -> GPIO3 (I2C bus 1 SCL)
 *   VL53L4CX VDD -> 3.3 V
 *   VL53L4CX GND -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o vl53l4cx_reader vl53l4cx_reader.c -lgpiod -lpigpio -lrt
 *
 * Run:
 *   sudo ./vl53l4cx_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* VL53L4CX I2C address (7-bit) */
#define VL53L4CX_ADDR 0x29

/* VL53L4CX register addresses */
#define VL53L4CX_REG_SOFT_RESET       0x0000
#define VL53L4CX_REG_INT_STATUS       0x0003
#define VL53L4CX_REG_RESULT_DISTANCE  0x0087

/* Interrupt status register bits */
#define VL53L4CX_INT_STATUS_DIST_VALID 0x01

/* I2C bus on Raspberry Pi Zero W */
#define I2C_BUS 1

/* Sampling interval in microseconds */
#define SAMPLE_INTERVAL_US 500000

/* Global flag for graceful shutdown */
static volatile sig_atomic_t g_running = 1;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Initialize the VL53L4CX sensor */
static int init_vl53l4cx(int handle)
{
    /* Soft reset */
    if (i2cWriteByteData(handle, VL53L4CX_REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write soft reset (0x00)\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms delay for reset */

    /* Verify sensor is ready */
    int status = i2cReadByteData(handle, VL53L4CX_REG_SOFT_RESET);
    if (status < 0) {
        fprintf(stderr, "Error: Failed to read soft reset status\n");
        return -1;
    }
    if (status != 0x00) {
        fprintf(stderr, "Error: VL53L4CX not ready (status=0x%02X)\n", status);
        return -1;
    }

    /* Configure interrupt threshold: 0x01 = 1 mm, 0x00 = 2 mm */
    if (i2cWriteByteData(handle, VL53L4CX_REG_INT_STATUS, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to write interrupt status\n");
        return -1;
    }

    return 0;
}

/* Read distance from the VL53L4CX sensor */
static int read_distance(int handle, uint16_t *distance_mm)
{
    int status = i2cReadWordData(handle, VL53L4CX_REG_RESULT_DISTANCE);
    if (status < 0) {
        fprintf(stderr, "Error: Failed to read distance register (0x%02X)\n", status);
        return -1;
    }
    if (status != 0x00) {
        fprintf(stderr, "Error: Distance register read failed (status=0x%02X)\n", status);
        return -1;
    }

    /* Clear the interrupt status bit so the next measurement is read */
    if (i2cWriteByteData(handle, VL53L4CX_REG_INT_STATUS, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to clear interrupt status\n");
        return -1;
    }

    *distance_mm = (uint16_t)((status << 8) | (status >> 8));
    return 0;
}

/* Log distance with timestamp */
static void log_distance(uint16_t distance_mm)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("Timestamp: %s, Distance: %u mm\n", timestamp, distance_mm);
    fflush(stdout);
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    int handle = i2cOpen(I2C_BUS, VL53L4CX_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X (handle=%d)\n",
                I2C_BUS, VL53L4CX_ADDR, handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_vl53l4cx(handle) < 0) {
        fprintf(stderr, "Error: VL53L4CX sensor initialization failed\n");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L4CX distance reader started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        uint16_t distance_mm;

        if (read_distance(handle, &distance_mm) == 0) {
            log_distance(distance_mm);
        } else {
