#define I2C_ADDR 0x2E
#define BUZZER_PIN 22
#define DISTANCE_THRESHOLD 100
#define SAMPLE_INTERVAL_US 500000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

int read_distance(void) {
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C handle is invalid\n");
        return -1;
    }

    uint8_t cmd[2] = {0x00, 0x00};
    if (i2cWriteDevice(i2c_handle, cmd, 2) != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", i2c_handle);
        return -1;
    }

    gpioDelay(2000); // 2 ms delay for measurement

    uint8_t data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", i2c_handle);
        return -1;
    }

    return (data[0] << 8) | data[1];
}

void control_buzzer(int state) {
    gpioWrite(BUZZER_PIN, state);
}

void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioWrite(BUZZER_PIN, 0);

    while (running) {
        int distance = read_distance();
        if (distance < 0) {
            fprintf(stderr, "Error reading distance, skipping iteration\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (distance < DISTANCE_THRESHOLD) {
            control_buzzer(1);
            printf("Distance below threshold: %d mm\n", distance);
        } else {
            control_buzzer(0);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

