/*
 * parking-assist.c — Raspberry Pi 4 Model B
 *
 * HC-SR04 ultrasonic sensor + SG90 servo on GPIO 23/24/17.
 * Library: libgpiod (modern GPIO API).
 *
 * Build:  gcc -O2 -Wall -Wextra -o parking_assist parking_assist.c -lgpiod
 * Run:    ./parking_assist
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24
#define SERVO_PIN        17

#define TRIGGER_PULSE_US  10
#define ECHO_TIMEOUT_US   50000   /* 50 ms — sensor timeout */
#define LOOP_DELAY_US     200000  /* 200 ms between readings */
#define SAMPLE_PERIOD_US  (LOOP_DELAY_US * 1000)

#define MIN_DISTANCE      2.0f
#define MAX_DISTANCE      400.0f

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        snprintf(buf, len, "UNKNOWN");
        return;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        snprintf(buf, len, "UNKNOWN");
        return;
    }
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(float distance)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    FILE *fp = fopen("sensor_data.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    fprintf(fp, "%s  Distance: %.2f cm\n", ts, distance);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Sensor helpers                                                      */
/* ------------------------------------------------------------------ */
static float read_distance(struct gpiod_line *trigger,
                           struct gpiod_line *echo,
                           struct gpiod_line *servo)
{
    /* Ensure trigger is low before starting the pulse */
    if (gpiod_line_set_value(trigger, 0) < 0) {
        fprintf(stderr, "Error setting trigger low: %s\n", strerror(errno));
        return -1.0f;
    }

    /* 10 µs trigger pulse */
    if (gpiod_line_set_value(trigger, 1) < 0) {
        fprintf(stderr, "Error setting trigger high: %s\n", strerror(errno));
        return -1.0f;
    }
    usleep(TRIGGER_PULSE_US);
    if (gpiod_line_set_value(trigger, 0) < 0) {
        fprintf(stderr, "Error setting trigger low after pulse: %s\n", strerror(errno));
        return -1.0f;
    }

    /* Wait for echo to go high (sensor timeout) */
    struct timespec ts_timeout;
    ts_timeout.tv_sec  = ECHO_TIMEOUT_US / 1000000;
    ts_timeout.tv_nsec = (ECHO_TIMEOUT_US % 1000000) * 1000;
    while (gpiod_line_get_value(echo) == 0) {
        if (nanosleep(&ts_timeout, &ts_timeout) == -1) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Error waiting for echo high: %s\n", strerror(errno));
            return -1.0f;
        }
    }

    /* Wait for echo to go low (sensor timeout) */
    ts_timeout.tv_sec  = ECHO_TIMEOUT_US / 1000000;
    ts_timeout.tv_nsec = (ECHO_TIMEOUT_US % 1000000) * 1000;
    while (gpiod_line_get_value(echo) == 1) {
        if (nanosleep(&ts_timeout, &ts_timeout) == -1) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Error waiting for echo low: %s\n", strerror(errno));
            return -1.0f;
        }
    }

    /* Read echo pulse width (microseconds) */
    long pulse_us = gpiod_line_get_value_us(echo);
    if (pulse_us < 0) {
        fprintf(stderr, "Error reading echo pulse: %s\n", strerror(errno));
        return -1.0f;
    }

    /* Distance = (pulse_us / 2) / 29.1 us/cm */
    float distance = (float)pulse_us / 29.1f;

    return distance;
}

/* ------------------------------------------------------------------ */
/* Library API                                                         */
/* ------------------------------------------------------------------ */
static int set_servo_angle(struct gpiod_line *servo, float angle)
{
    if (gpiod_line_set_value(servo, angle) < 0) {
        fprintf(stderr, "Error setting servo angle: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error installing SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open GPIO chip 0 (BCM GPIO numbers on Raspberry Pi 4) */
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error opening gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get BCM GPIO lines */
    struct gpiod_line *trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    struct gpiod_line *echo   = gpiod_chip_get_line(chip, ECHO_PIN);
    struct gpiod_line *servo  = gpiod_chip_get_line(chip, SERVO_PIN);

    if (trigger == NULL || echo == NULL || servo == NULL) {
        fprintf(stderr, "Error getting GPIO lines: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request trigger line as output, initial value LOW */
    if (gpiod_line_request_output(trigger, "parking-assist", 0) < 0) {
        fprintf(stderr, "Error requesting trigger line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request echo line as input, no pull-down */
    if (gpiod_line_request_input(echo, "parking-assist") < 0) {
        fprintf(stderr, "Error requesting echo line as input: %s\n", strerror(errno));
        gpiod_line_release(trigger);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request servo line as output, initial value LOW */
    if (gpiod_line_request_output(servo, "parking-assist", 0) < 0) {
        fprintf(stderr, "Error requesting servo line as output: %s\n", strerror(errno));
        gpiod_line_release(trigger);
        gpiod_line_release(echo);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Parking-assist system started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        float distance = read_distance(trigger, echo, servo);

        if (distance < 0.0f) {
            fprintf(stderr, "Sensor timeout — skipping reading.\n");
            log_data(-1.0f);
        } else {
            float angle = (distance / MIN_DISTANCE) * 180.0f;
            if (angle < 0.0f) angle = 0.0f;
            if (angle > 180.0f) angle = 180.0f;

            if (set_servo_angle(servo, angle) < 0) {
                fprintf(stderr, "Error setting servo angle.\n");
            }

            char ts[32];
            get_timestamp(ts, sizeof(ts));
            log_data(distance);
            printf("Distance: %.2f cm  Angle: %.0f°  Timestamp: %s\n",
                   distance, angle, ts);
        }

        /* Sleep in 100 ms chunks so signals are caught promptly */
        for (int i = 0; i < LOOP_DELAY_US / 100 && g_running; i++) {
            usleep(100 * 100);
        }
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    set_servo_angle(servo, 0.0f);
    gpiod_line_release(trigger);
    gpiod_line_release(echo);
    gpiod_line_release(servo);
    gpiod_chip_close(chip);

    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

