/*
 * VL53L1X distance sensor reader for Raspberry Pi 3 Model B+
 * Uses pigpio for I2C and GPIO control.
 *
 * Build:  gcc -O2 -Wall -o vl53l1x_reader vl53l1x_reader.c -lpigpio -lrt
 * Run:    sudo ./vl53l1x_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS          1
#define VL53L1X_ADDR     0x29
#define DISTANCE_THRESHOLD 100   /* mm */
#define BUZZER_GPIO      23
#define BUZZER_ON_TIME   50      /* ms */
#define POLL_DELAY_US    50000   /* 50 ms */
#define MAX_RETRIES      3

/* VL53L1X register addresses */
#define VL53L1X_REG_DISTANCE_RANGE_STATUS   0x00
#define VL53L1X_REG_DISTANCE_RANGE_CONFIG    0x01
#define VL53L1X_REG_SYSTEM_START_RANGE_MODE  0x0C
#define VL53L1X_REG_SYSTEM_START_RANGE_CONFIG 0x0D
#define VL53L1X_REG_SYSTEM_START_RANGE_MODE_VAL 0x01
#define VL53L1X_REG_SYSTEM_START_RANGE_CONFIG_VAL 0x01

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static int g_mq_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int handle, uint8_t reg, uint8_t val)
{
    char buf[2] = { (char)reg, (char)val };
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int handle, uint8_t reg, uint8_t *val)
{
    if (i2cWriteDevice(handle, (char *)&reg, 1) != 1) {
        fprintf(stderr, "I2C write reg-select 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (i2cReadDevice(handle, (char *)val, 1) != 1) {
        fprintf(stderr, "I2C read reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int handle, uint8_t reg, uint16_t *val)
{
    char buf[2];
    if (i2cWriteDevice(handle, (char *)&reg, 1) != 1) {
        fprintf(stderr, "I2C write reg-select 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "I2C read reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *val = (uint16_t)((uint8_t)buf[0] | ((uint8_t)buf[1] << 8));
    return 0;
}

/* ------------------------------------------------------------------ */
/* VL53L1X driver                                                      */
/* ------------------------------------------------------------------ */
static int vl53l1x_init(int handle)
{
    /*
     * Start range mode with config 0x01 (continuous, no interrupts).
     * The VL53L1X needs to be in standby before issuing the start command.
     */
    if (i2c_write_reg8(handle, VL53L1X_REG_SYSTEM_START_RANGE_MODE,
                       VL53L1X_REG_SYSTEM_START_RANGE_MODE_VAL) != 0)
        return -1;

    /*
     * Wait for the VL53L1X to enter standby (~1 ms).
     */
    gpioDelay(1000);

    /*
     * Configure the sensor for continuous measurement mode.
     * The VL53L1X expects the following register values in its
     * default configuration.
     */
    if (i2c_write_reg8(handle, VL53L1X_REG_DISTANCE_RANGE_CONFIG,
                       0x01) != 0)
        return -1;

    /*
     * Start range mode with config 0x01 (continuous, no interrupts).
     */
    if (i2c_write_reg8(handle, VL53L1X_REG_SYSTEM_START_RANGE_MODE,
                       VL53L1X_REG_SYSTEM_START_RANGE_MODE_VAL) != 0)
        return -1;

    /*
     * Wait for the sensor to complete its first measurement.
     */
    gpioDelay(1000);

    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance)
{
    uint8_t status;
    uint16_t raw;

    /*
     * Read the distance range status register to determine if a
     * measurement is ready.
     */
    if (i2c_read_reg8(handle, VL53L1X_REG_DISTANCE_RANGE_STATUS, &status) != 0)
        return -1;

    if (status & 0x01) {
        /* Measurement ready: read the 16-bit distance value. */
        if (i2c_read_reg16(handle, VL53L1X_REG_DISTANCE_RANGE_CONFIG,
                           &raw) != 0)
            return -1;

        *distance = raw;
        return 0;
    }

    /* No measurement ready yet — wait for the next poll. */
    gpioDelay(POLL_DELAY_US);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Buzzer control                                                      */
/* ------------------------------------------------------------------ */
static void buzzer_on(int gpio)
{
    gpioWrite(gpio, 1);
}

static void buzzer_off(int gpio)
{
    gpioWrite(gpio, 0);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_mq_fd >= 0) {
        struct msghdr msg;
        struct iovec iov;
        int n;

        memset(&msg, 0, sizeof(msg));
        memset(&iov, 0, sizeof(iov));

        msg.msg_name = NULL;
        msg.msg_namelen = 0;
        msg.msg_control = NULL;
        msg.msg_controllen = 0;
        msg.msg_flags = 0;

        n = recvmsg(g_mq_fd, &msg, 0);
        if (n < 0) {
            fprintf(stderr, "recvmsg() failed: %s\n", strerror(errno));
        } else if (n == 0) {
            fprintf(stderr, "recvmsg() timeout\n");
        } else {
            fprintf(stderr, "recvmsg() returned %d bytes\n", n);
        }
        close(g_mq_fd);
        g_mq_fd = -1;
    }

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    if (g_mq_fd >= 0) {
        close(g_mq_fd);
        g_mq_fd = -1;
    }

    gpioWrite(BUZZER_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, VL53L1X_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_mq_fd = mq_open("/tmp/vl53l1x_mq", O_CREAT | O_WRONLY | O_NONBLOCK, 0644);
    if (g_mq_fd < 0) {
        fprintf(stderr, "mq_open() failed: %s\n", strerror(errno));
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mq_send(g_mq_fd, (const char *)&DISTANCE_THRESHOLD,
                sizeof(DISTANCE_THRESHOLD), 0) < 0) {
        fprintf(stderr, "mq_send() failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    buzzer_on(BUZZER_GPIO);

    while (g_running) {
        uint16_t distance;

        if (vl53l1x_init(g_i2c_handle) != 0) {
            fprintf(stderr, "VL53L1X initialization failed; retrying in %d ms\n",
                    POLL_DELAY_US / 1000);
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (vl53l1x_read_distance(g_i2c_handle, &distance) != 0) {
            fprintf(stderr, "Distance read failed; retrying in %d ms\n",
                    POLL_DELAY_US / 1000);
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        printf("Distance: %u mm\n", distance);

        if (distance < DISTANCE_THRESHOLD) {
            buzzer_on(BUZZER_GPIO);
            printf("Distance below threshold! Buzzer ON.\n");
        } else {
            buzzer_off(BUZZER_GPIO);
            printf("Distance above threshold! Buzzer OFF.\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

