/*
 * parking_sensor.c — HC-SR04 parking sensor on Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   HC-SR04 trigger  -> GPIO 17 (BCM)
 *   HC-SR04 echo    -> GPIO 27 (BCM)
 *   Buzzer          -> GPIO 22 (BCM)
 *
 * Build:  gcc -O2 -Wall -Wextra -o parking_sensor parking_sensor.c -lpigpio -lrt
 * Run:    sudo ./parking_sensor
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         27
#define BUZZER_PIN       22

#define SPEED_OF_SOUND_CM_PER_US 0.0343f   /* 343 m/s at 20 °C */
#define MIN_DISTANCE_CM      2.0f
#define MAX_DISTANCE_CM      400.0f
#define MIN_BUZZER_DURATION_US 10000   /* 10 ms on GPIO 22 */
#define MAX_BUZZER_DURATION_US 200000 /* 200 ms on GPIO 22 */
#define POLL_INTERVAL_US     100000   /* 100 ms */
#define ECHO_TIMEOUT_US      50000    /* 50 ms timeout for echo */
#define MAX_RETRIES          3

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure the echo time in microseconds.
 * Returns the distance in centimeters, or -1.0f on timeout or error.
 */
