/*
 * Gate control using VL53L1X and SG90 servo on Raspberry Pi Zero W.
 *
 * Wiring:
 *   VL53L1X SDA -> GPIO2 (I2C1 SDA, pin 3)
 *   VL53L1X SCL -> GPIO3 (I2C1 SCL, pin 5)
 *   VL53L1X VDD -> 3.3 V
 *   VL53L1X GND -> GND
 *   SG90 PWM  -> GPIO18 (BCM)
 *   SG90 IN1  -> GPIO17 (BCM)
 *   SG90 IN2  -> GPIO19 (BCM)
 *   SG90 IN3  -> GPIO20 (BCM)
 *   SG90 IN4  -> GPIO21 (BCM)
 *   SG90 IN5  -> GPIO22 (BCM)
 *   SG90 IN6  -> GPIO23 (BCM)
 *   SG90 IN7  -> GPIO24 (BCM)
 *   SG90 IN8  -> GPIO25 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o gate_control gate_control.c -lrt -lpthread
 *
 * Run:
 *   sudo ./gate_control
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L1X_ADDR   0x29
#define LOG_FILE       "gate_log.txt"
#define SERVO_PIN      18
#define SERVO_PWM_FREQ  1000
#define SERVO_PWM_RANGE 1000
#define OPEN_THRESHOLD  20.0f
#define CLOSE_THRESHOLD 20.0f
#define MAX_RETRIES     3
#define RETRY_DELAY_US  100000
#define POLL_DELAY_US   10000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint8_t reg, uint16_t *val)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read word failed (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
/* VL53L1X helpers                                                     */
/* ------------------------------------------------------------------ */
static int vl53l1x_init(int fd)
{
    /* Software reset */
    if (i2c_write_byte(fd, 0x00, 0x00) < 0) return -1;
    gpioDelay(10000); /* 10 ms */

    /* Wait for boot (~1.5 s) */
    gpioDelay(15000);
    if (i2c_read_byte(fd, 0x00, &g_i2c_fd) < 0) return -1;

    /* Start ranging */
    if (i2c_write_byte(fd, 0x01, 0x01) < 0) return -1;
    gpioDelay(10000); /* 10 ms */

    return 0;
}

static int vl53l1x_read_distance(int fd, float *distance_cm)
{
    uint8_t cmd = 0x01;
    uint8_t buf[2];

    /* Issue ranging command (start ranging) */
    if (i2c_write_byte(fd, 0x01, 0x01) < 0) return -1;
    gpioDelay(10000); /* 10 ms */

    /* Read 16-bit distance (big-endian) */
    if (i2c_read_word(fd, 0x00, buf) < 0) return -1;
    *distance_cm = (float)buf[0] | ((float)buf[1] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
/* SG90 servo helpers                                                  */
/* ------------------------------------------------------------------ */
static int servo_set_angle(int pin, float angle)
{
    if (gpioServo(pin, (int)angle) < 0) {
        fprintf(stderr, "gpioServo failed for pin %d: %s\n", pin, strerror(errno));
        return -1;
    }
    return 0;
}

static int servo_set_pwm(int pin, int pwm_value)
{
    if (gpioPWM(pin, pwm_value) < 0) {
        fprintf(stderr, "gpioPWM failed for pin %d: %s\n", pin, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(const char *event)
{
    if (!g_log_fp) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;
    fprintf(g_log_fp, "%04d-%02d-%02d %02d:%02d:%02d %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %d: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set I2C slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                VL53L1X_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize VL53L1X */
    if (vl53l1x_init(g_i2c_fd) < 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure servo PWM */
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", SERVO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(SERVO_PIN, SERVO_PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", SERVO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(SERVO_PIN, SERVO_PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", SERVO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioPWM(SERVO_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialize servo PWM on GPIO %d\n", SERVO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    printf("Gate control started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        float distance = 0.0f;
        int retries = 0;

        while (retries < MAX_RETRIES && g_running) {
            if (vl53l1x_read_distance(g_i2c_fd, &distance) == 0) {
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                gpioDelay(RETRY_DELAY_US);
            }
        }

        if (distance == 0.0f) {
            fprintf(stderr, "Distance read failed after %d retries\n", MAX_RETRIES);
            gpioPWM(SERVO_PIN, 0);
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        printf("Distance: %.2f cm\n", distance);

        if (distance <= OPEN_THRESHOLD) {
            printf("Object detected! Opening gate.\n");
            if (servo_set_angle(SERVO_PIN, 90) < 0) {
                fprintf(stderr, "Failed to set servo angle\n");
            }
            gpioDelay(POLL_DELAY_US);
            if (servo_set_angle(SERVO_PIN, 0) < 0) {
                fprintf(stderr, "Failed to close gate\n");
            }
            gpioDelay(POLL_DELAY_US);
            if (servo_set_angle(SERVO_PIN, 0) < 0) {
                fprintf(stderr, "Failed to close gate\n");
            }
            gpioDelay(POLL_DELAY_US);
        } else {
            printf("Gate closed.\n");
            gpioPWM(SERVO_PIN, 0);
            gpioDelay(POLL_DELAY_US);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

