/*
 * HC-SR04 ultrasonic distance measurement on Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   HC-SR04 VCC  -> 5 V (Pin 1)
 *   HC-SR04 GND  -> GND (Pin 6)
 *   HC-SR04 TRIG -> GPIO23 (BCM, physical pin 16)
 *   HC-SR04 ECHO-> GPIO24 (BCM, physical pin 18)
 *
 * The ECHO line is 5 V and must be level-shifted or divided to 3.3 V
 * on the Pi.  The HC-SR04 datasheet recommends a 10 kΩ pull-down on
 * ECHO to ensure a clean low.
 *
 * Build:  gcc -O2 -Wall -Wextra -o hcsr04_distance hcsr04_distance.c -lrt
 * Run:    ./hcsr04_distance
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>

#include <gpiod.h>

#define TRIG_PIN        23
#define ECHO_PIN        24
#define SAMPLE_PERIOD_US 200000   /* 200 ms = 5 Hz */
#define ECHO_TIMEOUT_US  60000    /* 60 ms timeout for no object */
#define NOISE_THRESHOLD_US 100000   /* 100 µs noise */
#define TIMEOUT_THRESHOLD_US 30000   /* 30 ms timeout for no object */
#define TRIGGER_PULSE_US  10        /* 10 µs trigger pulse */
#define ECHO_WIDE_US      30000     /* 30 ms echo wide-pulse timeout */
#define ECHO_SHORT_US     10000     /* 10 µs echo short-pulse timeout */

/* 32-bit tick wraps every ~72 min; we use a uint64_t for safety */
#define TICK_MAX_US      9223372036854775807UL

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                     */
/* ------------------------------------------------------------------ */
static void get_iso8601_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        snprintf(buf, len, "1970-01-01T00:00:00Z");
        return;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        snprintf(buf, len, "1970-01-01T00:00:00Z");
        return;
    }
    strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_info);
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                         */
/* ------------------------------------------------------------------ */
static int gpio_init(struct gpiod_chip *chip, int trig_pin, int echo_pin)
{
    struct gpiod_line *trig_line = NULL;
    struct gpiod_line *echo_line = NULL;
    struct gpiod_line_event event;
    int ret;

    /* --- Trigger line --- */
    trig_line = gpiod_chip_get_line(chip, trig_pin);
    if (!trig_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                trig_pin, strerror(errno));
        return -1;
    }
    ret = gpiod_line_request_output(trig_line, "hc-sr04-trigger", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO %d as output: %s\n",
                trig_pin, strerror(errno));
        goto fail;
    }

    /* --- Echo line --- */
    echo_line = gpiod_chip_get_line(chip, echo_pin);
    if (!echo_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                echo_pin, strerror(errno));
        goto fail;
    }
    ret = gpiod_line_request_input(echo_line, "hc-sr04-echo");
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO %d as input: %s\n",
                echo_pin, strerror(errno));
        goto fail;
    }

    /* --- Enable pull-down on ECHO line (HC-SR04 requires it) --- */
    ret = gpiod_line_request_flags_set_flags(echo_line,
                                              GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN,
                                              "hc-sr04-echo-pull-down");
    if (ret < 0) {
        fprintf(stderr, "Failed to request pull-down on GPIO %d: %s\n",
                echo_pin, strerror(errno));
        goto fail;
    }

    return 0;

fail:
    if (trig_line) gpiod_line_release(trig_line);
    if (echo_line)  gpiod_line_release(echo_line);
    return -1;
}

/* ------------------------------------------------------------------ */
/* ECHO callback                                                        */
/* ------------------------------------------------------------------ */
static void echo_callback(struct gpiod_line_event *event)
{
    (void)event;

    /* Rising edge: timestamp */
    char ts[32];
    get_iso8601_timestamp(ts, sizeof(ts));
    printf("[%s] ECHO rising edge\n", ts);

    /* Falling edge: timestamp */
    get_iso8601_timestamp(ts, sizeof(ts));
    printf("[%s] ECHO falling edge\n", ts);

    /* --- ECHO_TIMEOUT_US --- */
    if (event->value == 0) {
        char msg[128];
        snprintf(msg, sizeof(msg),
                 "ECHO timeout: no object detected within %d µs",
                 ECHO_TIMEOUT_US);
        printf("[%s] %s\n", ts, msg);
    }

    /* --- ECHO_SHORT_US --- */
    if (event->value == 1) {
        char msg[128];
        snprintf(msg, sizeof(msg),
                 "ECHO short pulse detected: %d µs",
                 ECHO_SHORT_US);
        printf("[%s] %s\n", ts, msg);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                              */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Trigger line */
    if (trig_line) {
        gpiod_line_release(trig_line);
        trig_line = NULL;
    }

    /* Echo line */
    if (echo_line) {
        gpiod_line_release(echo_line);
        echo_line = NULL;
    }

    /* Chip */
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                 */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig_line = NULL;
    struct gpiod_line *echo_line = NULL;
    int ret = EXIT_FAILURE;

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open GPIO chip --- */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Initialize GPIO --- */
    if (gpio_init(chip, TRIG_PIN, ECHO_PIN) < 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        goto cleanup;
    }

    /* --- Register echo callback --- */
    if (gpiod_line_request_event_flags_set_flags(echo_line,
                                                  GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN,
                                                  "hc-sr04-echo-callback") < 0) {
        fprintf(stderr, "Failed to request echo callback: %s\n",
                strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_event_register_line_events_flags(echo_line,
                                                     GPIOD_LINE_EVENT_RISING_EDGE,
                                                     ECHO_TIMEOUT_US,
                                                     &echo_callback) < 0) {
        fprintf(stderr, "Failed to register echo callback: %s\n",
                strerror(errno));
        goto cleanup;
    }

    printf("HC-SR04 distance measurement started.  Press Ctrl+C to exit.\n");
    printf("Echo: GPIO %d, Trigger: GPIO %d, Log: distance_log.txt\n",
           ECHO_PIN, TRIG_PIN);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        /* --- Trigger pulse --- */
        if (gpiod_line_set_value(trig_line, 1) < 0) {
            fprintf(stderr, "Failed to set trigger high: %s\n",
                    strerror(errno));
            break;
        }
        usleep(TRIGGER_PULSE_US);
        if (!g_running) break;
        if (gpiod_line_set_value(trig_line, 0) < 0) {
            fprintf(stderr, "Failed to set trigger low: %s\n",
                    strerror(errno));
            break;
        }
        usleep(TRIGGER_PULSE_US);

        /* --- Wait for echo with timeout --- */
        struct timespec ts_start = {0, 0};
        struct timespec ts_timeout = {0, 0};
        ts_timeout.tv_sec  = ECHO_TIMEOUT_US / 1000000;
        ts_timeout.tv_nsec = (ECHO_TIMEOUT_US % 1000000) * 1000;

        while (g_running && ts_start.tv_nsec < ts_timeout.tv_nsec) {
            if (!g_running) break;
            nanosleep(&ts_start, NULL);
            ts_start.tv_nsec += 1000000;
            if (ts_start.tv_nsec >= ts_timeout.tv_nsec) {
                fprintf(stderr, "Timeout waiting for echo (no object)\n");
                break;
            }
        }

        if (!g_running) break;

        /* --- Read echo pulse --- */
        struct timespec ts_start = {0, 0};
        ts_start.tv_sec  = ECHO_SHORT_US / 1000000;
        ts_start.tv_nsec = (ECHO_SHORT_US % 1000000) * 1000;

        while (g_running && ts_start.tv_nsec < ts_timeout.tv_nsec) {
            if (!g_running) break;
            nanosleep(&ts_start, NULL);
            ts_start.tv_nsec += 1000000;
            if (ts_start.tv_nsec >= ts_timeout.tv_nsec) {
                fprintf(stderr, "Timeout waiting for echo (no object)\n");
                break;
            }
        }

        if (!g_running) break;

        if (ts_start.tv_nsec < ts_timeout.tv_nsec) {
            fprintf(stderr, "Warning: echo timeout (no object)\n");
            continue;
        }

        /* --- Compute pulse width --- */
        uint64_t elapsed_us = ts_start.tv_sec * 1000000ULL +
                              ts_start.tv_nsec / 1000ULL;
        if (elapsed_us > TICK_MAX_US) {
            fprintf(stderr, "Warning: pulse width exceeds TICK_MAX_US (%u us)\n",
                    TICK_MAX_US);
            elapsed_us = TICK_MAX_US;
        }

        /* --- Distance calculation --- */
        uint64_t distance = elapsed_us - NOISE_THRESHOLD_US;
        if (distance > TIMEOUT_THRESHOLD_US) {
            fprintf(stderr, "Warning: distance exceeds TIMEOUT_THRESHOLD_US (%u us)\n",
                    TIMEOUT_THRESHOLD_US);
            distance = TIMEOUT_THRESHOLD_US;
        }

        /* --- Log to file --- */
        char log_file_path[128];
        get_iso8601_timestamp(log_file_path, sizeof(log_file_path));
        FILE *fp = fopen(log_file_path, "a");
        if (!fp) {
            fprintf(stderr, "Failed to open log file %s: %s\n",
                    log_file_path, strerror(errno));
            break;
        }
        fprintf(fp, "%s, %.2f\n", log_file_path, distance);
        fclose(fp);

        printf("[%s] Distance: %.2f meters\n", log_file_path, distance);

        /* --- Sleep until next trigger --- */
        while (g_running && elapsed_us < TRIGGER_PULSE_US) {
            nanosleep(&(struct timespec){0, 1000000}, NULL);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

