/*
 * Raspberry Pi 4 Model B – VL53L1X Time-of-Flight Sensor
 *
 * Reads distance measurements every 500 ms, logs object detection events
 * to gate_events.log, and controls the gate GPIO (GPIO 18) based on
 * whether an object is detected within 20 cm (200 mm).
 *
 * Build:  gcc -O2 -Wall -o gate_sensor gate_sensor.c -lpigpio -lrt
 * Run:    sudo ./gate_sensor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS            1
#define I2C_ADDR           0x29
#define GATE_GPIO          18
#define DISTANCE_THRESHOLD 200
#define LOG_FILE           "gate_events.log"
#define POLL_DELAY_US      500000   /* 500 ms */
#define SENSOR_TIMEOUT_US  50000    /* 50 ms */

/* VL53L1X register addresses */
#define VL53L1X_REG_SOFT_RESET   0x0000
#define VL53L1X_REG_SYSTEM_START 0x0003
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x00F0
#define VL53L1X_REG_RESULT_DISTANCE_MM 0x00F1
#define VL53L1X_REG_CONFIG_PARAMETER 0x00F2
#define VL53L1X_REG_RESULT_RANGE_CONFIG 0x00F3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg(uint16_t reg, uint8_t val)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = val;
    return i2cWriteDevice(g_i2c_handle, buf, 3);
}

static int i2c_read_reg(uint16_t reg, uint8_t *val)
{
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(g_i2c_handle, reg_buf, 2) != 0)
        return -1;
    if (i2cReadDevice(g_i2c_handle, (char *)val, 1) != 1)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int init_sensor(void)
{
    /* Soft reset */
    if (i2c_write_reg(VL53L1X_REG_SOFT_RESET, 0x00) != 0) {
        fprintf(stderr, "Error: failed to write soft reset\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    /* Configure timing budget: 20 ms per measurement */
    if (i2c_write_reg(VL53L1X_REG_CONFIG_PARAMETER, 0x0A) != 0) {
        fprintf(stderr, "Error: failed to configure timing budget\n");
        return -1;
    }

    /* Start ranging */
    if (i2c_write_reg(VL53L1X_REG_SYSTEM_START, 0x01) != 0) {
        fprintf(stderr, "Error: failed to start ranging\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Distance measurement                                                */
/* ------------------------------------------------------------------ */
static int read_distance(void)
{
    uint8_t status;
    uint16_t distance;

    /* Read range status */
    if (i2c_read_reg(VL53L1X_REG_RESULT_RANGE_STATUS, &status) != 0)
        return -1;

    if (!(status & 0x01)) {
        fprintf(stderr, "Error: no object detected (status=0x%02X)\n", status);
        return -1;
    }

    /* Read distance */
    if (i2c_read_reg(VL53L1X_REG_RESULT_DISTANCE_MM, &distance) != 0)
        return -1;

    return (int)distance;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(const char *event)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    if (fprintf(g_log_file, "%s %s\n", ts, event) < 0) {
        fprintf(stderr, "Error: failed to write to log file\n");
    }
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioWrite(GATE_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure gate GPIO */
    if (gpioSetMode(GATE_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", GATE_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GATE_GPIO, 0);

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_sensor() != 0) {
        fprintf(stderr, "Error: sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("VL53L1X gate controller started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        int distance = read_distance();

        if (distance < 0) {
            fprintf(stderr, "Warning: sensor read error, retrying in %d ms\n",
                    POLL_DELAY_US / 1000);
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (distance > 0) {
            printf("Distance: %d mm\n", distance);
            log_event("Object detected");
        } else {
            printf("Distance: unknown (0 mm)\n");
            log_event("No object detected");
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

