/*
 * VL53L1X distance sensor motor control for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   VL53L1X SDA -> GPIO2 (I2C1 SDA, pin 3)
 *   VL53L1X SCL -> GPIO3 (I2C1 SCL, pin 5)
 *   VL53L1X VDD -> 3.3 V
 *   VL53L1X GND -> GND
 *   Motor control: GPIO17 (forward), GPIO18 (backward)
 *
 * Build:  gcc -O2 -Wall -o vl53l1x_motor vl53l1x_motor.c -lpigpio -lrt
 * Run:    sudo ./vl53l1x_motor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS            1
#define I2C_ADDR           0x33
#define MOTOR_GPIO_FRONT   17
#define MOTOR_GPIO_BACK    18
#define DISTANCE_THRESHOLD 100
#define MOTOR_STOP_THRESHOLD 300
#define SENSOR_RESET_CMD   0x00
#define SENSOR_START_CMD   0x01
#define SENSOR_DATA_REG    0x00F0
#define SENSOR_STATUS_REG  0x00F1
#define SENSOR_DATA_LEN    2
#define SENSOR_DATA_VAL    0x0000
#define SENSOR_DATA_VAL_HIGH 0x0000
#define SENSOR_DATA_VAL_LOW  0x0000
#define SENSOR_DATA_VAL_ERR 0xFFFF

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static int g_motor_front = -1;
static int g_motor_back  = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void motor_stop(void)
{
    if (g_motor_front >= 0) {
        gpioWrite(g_motor_front, 0);
        g_motor_front = -1;
    }
    if (g_motor_back  >= 0) {
        gpioWrite(g_motor_back, 0);
        g_motor_back  = -1;
    }
}

static void motor_forward(void)
{
    if (g_motor_front >= 0) {
        gpioWrite(g_motor_front, 1);
        g_motor_front = -1;
    }
}

static void motor_backward(void)
{
    if (g_motor_back  >= 0) {
        gpioWrite(g_motor_back, 1);
        g_motor_back  = -1;
    }
}

static void motor_stop_and_log(void)
{
    motor_stop();
    printf("Motor stopped.\n");
}

static void motor_forward_and_log(void)
{
    motor_forward();
    printf("Motor forward.\n");
}

static void motor_backward_and_log(void)
{
    motor_backward();
    printf("Motor backward.\n");
}

static void motor_stop_and_log_err(void)
{
    motor_stop();
    printf("Motor stopped (sensor absent or bus error).\n");
}

static void motor_forward_and_log_err(void)
{
    motor_forward();
    printf("Motor forward (sensor absent or bus error).\n");
}

static void motor_backward_and_log_err(void)
{
    motor_backward();
    printf("Motor backward (sensor absent or bus error).\n");
}

static void i2c_write_byte(uint8_t reg, uint8_t val)
{
    if (i2cWriteByteData(g_i2c_handle, reg, val) < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X)\n", reg, val);
        motor_stop_and_log_err();
    }
}

static void i2c_read_byte(uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(g_i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X)\n", reg);
        motor_stop_and_log_err();
    } else {
        *out = (uint8_t)rc;
    }
}

static void i2c_read_word(uint8_t reg, uint16_t *out)
{
    uint8_t lo, hi;
    i2c_read_byte(reg, &lo);
    i2c_read_byte(reg + 1, &hi);
    *out = (uint16_t)((hi << 8) | lo);
}

static void i2c_write_word(uint8_t reg, uint16_t val)
{
    uint8_t lo, hi;
    hi = (uint8_t)(val >> 8);
    lo = (uint8_t)(val & 0xFF);
    i2c_write_byte(reg, hi);
    i2c_write_byte(reg + 1, lo);
}

static void vl53l1x_soft_reset(void)
{
    i2c_write_byte(SENSOR_RESET_CMD, SENSOR_DATA_VAL_HIGH);
    gpioDelay(2000);
    i2c_write_byte(SENSOR_RESET_CMD, SENSOR_DATA_VAL_LOW);
    gpioDelay(2000);
}

static int vl53l1x_init(void)
{
    if (i2c_write_byte(SENSOR_RESET_CMD, SENSOR_DATA_VAL_HIGH) < 0) {
        fprintf(stderr, "Soft reset failed.\n");
        return -1;
    }
    gpioDelay(2000);
    if (i2c_write_byte(SENSOR_RESET_CMD, SENSOR_DATA_VAL_LOW) < 0) {
        fprintf(stderr, "Soft reset failed.\n");
        return -1;
    }
    gpioDelay(2000);

    if (i2c_write_byte(SENSOR_START_CMD, SENSOR_DATA_VAL_HIGH) < 0) {
        fprintf(stderr, "Start command failed.\n");
        return -1;
    }
    gpioDelay(2000);
    if (i2c_write_byte(SENSOR_START_CMD, SENSOR_DATA_VAL_LOW) < 0) {
        fprintf(stderr, "Start command failed.\n");
        return -1;
    }
    gpioDelay(2000);

    return 0;
}

static int vl53l1x_read_distance(uint16_t *distance)
{
    uint8_t status;
    uint8_t data[SENSOR_DATA_LEN];

    if (i2c_read_byte(SENSOR_STATUS_REG, &status) < 0) {
        fprintf(stderr, "Status read failed.\n");
        return -1;
    }

    if (status & 0x01) {
        /* Data ready bit set: poll until data ready is clear */
        while (i2c_read_byte(SENSOR_STATUS_REG, &status) < 0) {
            gpioDelay(1000);
        }
        if (!(status & 0x01)) {
            fprintf(stderr, "Data not ready.\n");
            return -1;
        }
    }

    if (i2c_read_word(SENSOR_DATA_REG, distance) < 0) {
        fprintf(stderr, "Distance read failed.\n");
        return -1;
    }

    *distance = (uint16_t)((data[1] << 8) | data[0]);
    return 0;
}

static void signal_handler_ex(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "I2C open failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_motor_front = gpioOpen(MOTOR_GPIO_FRONT);
    g_motor_back  = gpioOpen(MOTOR_GPIO_BACK);
    if (g_motor_front < 0 || g_motor_back < 0) {
        fprintf(stderr, "GPIO open failed (front %d, back %d).\n",
                g_motor_front, g_motor_back);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR_GPIO_FRONT, PI_OUTPUT) < 0) {
        fprintf(stderr, "GPIO set mode failed.\n");
        motor_stop_and_log_err();
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_GPIO_BACK, PI_OUTPUT) < 0) {
        fprintf(stderr, "GPIO set mode failed.\n");
        motor_stop_and_log_err();
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(g_motor_front, 0) < 0 || gpioWrite(g_motor_back, 0) < 0) {
        fprintf(stderr, "GPIO write failed.\n");
        motor_stop_and_log_err();
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler_ex;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L1X distance sensor control started.\n");
    printf("I2C bus %d, addr 0x%02X, motor front %d, motor back %d.\n",
           I2C_BUS, I2C_ADDR, MOTOR_GPIO_FRONT, MOTOR_GPIO_BACK);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t distance;

        if (vl53l1x_init() < 0) {
            fprintf(stderr, "Sensor initialization failed.\n");
            motor_stop_and_log_err();
            gpioDelay(100000);
            continue;
        }

        if (vl53l1x_read_distance(&distance) < 0) {
            fprintf(stderr, "Distance read failed.\n");
            motor_stop_and_log_err();
            gpioDelay(100000);
            continue;
        }

        printf("Distance: %u mm\n", distance);

        if (distance < DISTANCE_THRESHOLD) {
            motor_forward_and_log_err();
        } else if (distance > MOTOR_STOP_THRESHOLD) {
            motor_forward_and_log();
        } else {
            motor_stop_and_log_err();
        }

        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    motor_stop_and_log_err();
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

