/*
 * Proximity-based Interactive Art Installation using MPR121 Capacitive Touch Sensor
 * Board: Raspberry Pi 3 Model B+
 * I2C Bus: /dev/i2c-1 (GPIO2=SDA, GPIO3=SCL)
 * GPIO Lines:
 *   BCM  | SDA  | SCL
 *   17   | GPIO2 | GPIO3
 *   18   | GPIO3 | GPIO2
 *   27   | GPIO5 | GPIO6
 *   22   | GPIO6 | GPIO5
 *
 * Build: gcc -O2 -Wall -o proximity_art proximity_art.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPR121_ADDR    0x60
#define NUM_ELECTRODE  12
#define GPIO_BCM       17
#define GPIO_SCL       18
#define GPIO_SDA       27
#define GPIO_RST       22
#define POLL_MS        50

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_DATA_L 0x02
#define MPR121_ELECTRODE_DATA_H 0x03
#define MPR121_SOFT_RESET 0x80

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpr121_reset(int fd) {
    if (i2c_write_reg8(fd, MPR121_SOFT_RESET, 0x00) < 0) return -1;
    usleep(10000);
    return 0;
}

static int mpr121_read_touch_data(int fd, uint8_t *data) {
    if (i2c_read_reg8(fd, MPR121_TOUCHSTATUS_L, data) < 0) return -1;
    if (i2c_read_reg8(fd, MPR121_TOUCHSTATUS_H, data + 1) < 0) return -1;
    return 0;
}

static int mpr121_read_electrode_data(int fd, uint8_t electrode, uint8_t *data) {
    if (i2c_read_reg8(fd, MPR121_ELECTRODE_DATA_L + (electrode - 1) * 2, data) < 0) return -1;
    if (i2c_read_reg8(fd, MPR121_ELECTRODE_DATA_H + (electrode - 1) * 2, data + 1) < 0) return -1;
    return 0;
}

static int mpr121_read_electrode_data_raw(int fd, uint8_t electrode, uint8_t *data) {
    if (i2c_read_reg8(fd, MPR121_ELECTRODE_DATA_L + (electrode - 1) * 2, data) < 0) return -1;
    if (i2c_read_reg8(fd, MPR121_ELECTRODE_DATA_H + (electrode - 1) * 2, data + 1) < 0) return -1;
    return 0;
}

static int mpr121_read_electrode_data_raw_with_mask(int fd, uint8_t electrode, uint8_t mask, uint8_t *data) {
    if (i2c_read_reg8(fd, MPR121_ELECTRODE_DATA_L + (electrode - 1) * 2 + 2, data) < 0) return -1;
    if (i2c_read_reg8(fd, MPR121_ELECTRODE_DATA_H + (electrode - 1) * 2 + 2, data + 1) < 0) return -1;
    if (i2c_read_reg8(fd, MPR121_ELECTRODE_DATA_L + (electrode - 1) * 2 + 4, data + 2) < 0) return -1;
    if (i2c_read_reg8(fd, MPR121_ELECTRODE_DATA_H + (electrode - 1) * 2 + 4, data + 3) < 0) return -1;
    if (i2c_read_reg8(fd, MPR121_ELECTRODE_DATA_L + (electrode - 1) * 2 + 6, data + 4) < 0) return -1;
    if (i2c_read_reg8(fd, MPR121_ELECTRODE_DATA_H + (electrode - 1) * 2 + 6, data + 5) < 0) return -1;
    if (i2c_read_reg8(fd, MPR121_ELECTRODE_DATA_L + (electrode - 1) * 2 + 8, data + 6) < 0) return -1;
    if (i2c_read_reg8(fd, MPR121_ELECTRODE_DATA_H + (electrode - 1) * 2 + 8, data + 7) < 0) return -1;
    return 0;
}

static int mpr121_read_electrode_data_with_mask(int fd, uint8_t electrode, uint8_t mask, uint8_t *data) {
    if (i2c_read_reg8(fd, MPR121_ELECTRODE_DATA_L + (electrode - 1) * 2 + 10, data) < 0) return -1;
    if (i2c_read_reg8(fd, MPR121_ELECTRODE_DATA_H + (electrode - 1) * 2 + 10, data + 1) < 0) return -1;
