    if (i2c_read_reg8(fd, MPR121_ELECTRODE_DATA_L + (electrode - 1) * 2 + 16, data + 6) < 0) return -1;
    if (i2c_read_reg8(fd, MPR121_ELECTRODE_DATA_H + (electrode - 1) * 2 + 16, data + 7) < 0) return -1;
    if (i2c_read_reg8(fd, MPR121_ELECTRODE_DATA_L + (electrode - 1) * 2 + 18, data + 8) < 0) return -1;
    if (i2c_read_reg8(fd, MPR121_ELECTRODE_DATA_H + (electrode - 1) * 2 + 18, data + 9) < 0) return -1;
    if (i2c_read_reg8(fd, MPR121_ELECTRODE_DATA_L + (electrode - 1) * 2 + 20, data + 10) < 0) return -1;
    if (i2c_read_reg8(fd, MPR121_ELECTRODE_DATA_H + (electrode - 1) * 2 + 20, data + 11) < 0) return -1;
    if (i2c_read_reg8(fd, MPR121_ELECTRODE_DATA_L + (electrode - 1) * 2 + 22, data + 12) < 0) return -1;
    if (i2c_read_reg8(fd, MPR121_ELECTRODE_DATA_H + (electrode - 1) * 2 + 22, data + 13) < 0) return -1;
    if (i2c_read_reg8(fd, MPR121_ELECTRODE_DATA_L + (electrode - 1) * 2 + 24, data + 14) < 0) return -1;
    if (i2c_read_reg8(fd, MPR121_ELECTRODE_DATA_H + (electrode - 1) * 2 +24, data + 15) < 0) return -1;
