/*
 * HC-SR04 ultrasonic distance measurement on Raspberry Pi Zero W.
 *
 * Wiring:
 *   HC-SR04 echo  -> GPIO18 (BCM)
 *   HC-SR04 trigger-> GPIO17 (BCM)
 *   HC-SR04 VCC   -> 3.3 V
 *   HC-SR04 GND   -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o distance_measure distance_measure.c
 * Run:    sudo ./distance_measure
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/time.h>

#include <gpiod.h>

#define TRIGGER_LINE_OFFSET 17
#define ECHO_LINE_OFFSET    18

#define TRIGGER_PULSE_US   5
#define ECHO_TIMEOUT_US    30000   /* 30 ms */
#define SAMPLE_PERIOD_US   1000000 /* 1 s */

#define SPEED_OF_SOUND_CM_S 343.0
#define MIN_DISTANCE_CM    2.0
#define MAX_DISTANCE_CM    400.0

#define LOG_FILE_NAME      "distance_log.txt"

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Send a 10 µs trigger pulse to the HC-SR04.
 * Returns 0 on success, -1 on error.
 */
static int trigger_sensor(struct gpiod_line *trigger, int level)
{
    if (gpiod_line_set_value(trigger, level) < 0) {
        fprintf(stderr, "Error: failed to set trigger line %d to %d: %s\n",
                TRIGGER_LINE_OFFSET, level, strerror(errno));
        return -1;
    }

    /* 10 µs trigger pulse */
    struct timespec ts = { 0, 0 };
    if (gpiod_line_set_value(trigger, 0) < 0) {
        fprintf(stderr, "Error: failed to reset trigger line %d: %s\n",
                TRIGGER_LINE_OFFSET, strerror(errno));
        return -1;
    }
    nanosleep(&ts, NULL);
    if (gpiod_line_set_value(trigger, 1) < 0) {
        fprintf(stderr, "Error: failed to reset trigger line %d: %s\n",
                TRIGGER_LINE_OFFSET, strerror(errno));
        return -1;
    }

    return 0;
}

/*
 * Read the echo pulse width with a timeout.
 * Returns the pulse width in microseconds, or -1 on timeout or error.
 */
static int read_echo_pulse(struct gpiod_line *echo, int timeout_us)
{
    struct timespec start, end;
    int pulse_us;

    if (clock_gettime(CLOCK_MONOTONIC, &start) < 0) {
        fprintf(stderr, "Error: clock_gettime failed: %s\n", strerror(errno));
        return -1;
    }

    /* Wait for echo rising edge (start of pulse) */
    while (gpiod_line_get_value(echo) == 0) {
        if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) {
            fprintf(stderr, "Error: clock_gettime failed: %s\n", strerror(errno));
            return -1;
        }
        if (end.tv_sec >= timeout_us.tv_sec ||
            end.tv_sec >= timeout_us.tv_nsec ||
            end.tv_nsec >= timeout_us.tv_nsec) {
            fprintf(stderr, "Error: echo rising edge timeout (no echo or sensor absent)\n");
            return -1;
        }
        usleep(1);
    }

    /* Wait for echo falling edge (end of pulse) */
    while (gpiod_line_get_value(echo) == 1) {
        if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) {
            fprintf(stderr, "Error: clock_gettime failed: %s\n", strerror(errno));
            return -1;
        }
        if (end.tv_sec >= timeout_us.tv_sec ||
            end.tv_sec >= timeout_us.tv_nsec ||
            end.tv_nsec >= timeout_us.tv_nsec) {
            fprintf(stderr, "Error: echo falling edge timeout (no echo or sensor absent)\n");
            return -1;
        }
        usleep(1);
    }

    /* Read pulse width */
    pulse_us = (int)(end.tv_sec - start.tv_sec) * 1000000 +
               (int)(end.tv_nsec - start.tv_nsec) / 1000;

    return pulse_us;
}

/*
 * Compute distance from pulse width.
 * Returns distance in centimeters, or -1.0 on error.
 */
static double calculate_distance(int pulse_us)
{
    if (pulse_us < 0) {
        return -1.0;
    }

    double time_s = (double)pulse_us / 1000000.0;
    double distance = (time_s * SPEED_OF_SOUND_CM_S) / 2.0;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        return -1.0;
    }

    return distance;
}

/*
 * Log a distance reading to the file.
 * Returns 0 on success, -1 on error.
 */
static int log_distance(double distance)
{
    FILE *fp = fopen(LOG_FILE_NAME, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error: time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&t, &tm_utc) == NULL) {
        fprintf(stderr, "Error: gmtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Warning: fflush failed: %s\n", strerror(errno));
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Warning: fclose failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    /* Install SIGINT handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi Zero W) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error: gpiod_chip_open_by_name failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_LINE_OFFSET);
    if (trigger == NULL) {
        fprintf(stderr, "Error: gpiod_chip_get_line(TRIGGER) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_LINE_OFFSET);
    if (echo == NULL) {
        fprintf(stderr, "Error: gpiod_chip_get_line(ECHO) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request trigger line as output, initially low */
    if (gpiod_line_request_output(trigger, "hc-sr04-trigger", 0) < 0) {
        fprintf(stderr, "Error: gpiod_line_request_output(TRIGGER) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request echo line as input */
    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        fprintf(stderr, "Error: gpiod_line_request_input(ECHO) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int pulse_us = -1;

        /* Trigger the sensor */
        if (trigger_sensor(trigger, 1) < 0) {
            fprintf(stderr, "Error: trigger failed\n");
            break;
        }

        /* Wait for echo rising edge (10 µs pulse) */
        if (gpiod_line_get_value(echo) == 1) {
            pulse_us = read_echo_pulse(echo, ECHO_TIMEOUT_US);
            if (pulse_us < 0) {
                fprintf(stderr, "Error: echo pulse read failed\n");
                break;
            }
        }

        /* Wait for echo falling edge (10 µs pulse) */
        if (gpiod_line_get_value(echo) == 0) {
            pulse_us = read_echo_pulse(echo, ECHO_TIMEOUT_US);
            if (pulse_us < 0) {
                fprintf(stderr, "Error: echo pulse read failed\n");
                break;
