/*
 * HC-SR04 Ultrasonic Distance Measurement for Raspberry Pi Zero W
 * Library: libgpiod (interrupt-driven echo pulse-width measurement)
 *
 * Wiring:
 *   TRIG -> GPIO17 (BCM)
 *   ECHO -> GPIO18 (BCM) via 1 kΩ / 2 kΩ voltage divider
 *
 * Build: gcc -O2 -Wall -o hcsr04 hcsr04.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIG_PIN      17
#define ECHO_PIN      18
#define LOG_FILE      "distance_log.txt"
#define ECHO_THRESHOLD_MIN 58  /* µs  */
#define ECHO_THRESHOLD_MAX 25  /* ms  */
#define SAMPLE_PERIOD_US 1000000  /* 1 s  */
#define ECHO_TIMEOUT_US 2000000  /* 2 ms  */
#define ECHO_TIMEOUT_S    2
#define ECHO_TIMEOUT_MS   (ECHO_TIMEOUT_S * 1000)

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* ISR callback for echo pulse width measurement                         */
/* ------------------------------------------------------------------ */
static void echo_isr(struct gpiod_line *line, void *ctx, uint32_t tick)
{
    (void)tick;
    (void)ctx;

    if (gpiod_line_get_value(line) != 0)
        return;

    /* Rising edge: start of echo pulse */
    if (gpiod_line_request_rising_edge_events(line, "hcsr04-echo") < 0)
        return;

    /* Wait for echo to fall (or timeout) */
    uint32_t timeout = tick + ECHO_TIMEOUT_S * 1000;
    while (gpiod_line_get_value(line) == 0) {
        if (gpiod_line_request_rising_edge_events(line, "hcsr04-echo") < 0)
            return;
        timeout = tick + ECHO_TIMEOUT_S * 1000;
        if (gpiod_line_request_rising_edge_events(line, "hcsr04-echo") < 0)
            return;
    }

    uint32_t pulse_start = tick;
    uint32_t pulse_end = 0;
    while (gpiod_line_get_value(line) == 1) {
        if (gpiod_line_request_rising_edge_events(line, "hcsr04-echo") < 0)
            return;
        pulse_end = tick;
        if (gpiod_line_request_rising_edge_events(line, "hcsr04-echo") < 0)
            return;
    }

    uint32_t pulse_duration = pulse_end - pulse_start;
    if (pulse_duration > ECHO_TIMEOUT_MS * 1000) {
        fprintf(stderr, "Echo timeout: pulse duration %u us\n", pulse_duration);
        return;
    }

    /* Validate pulse width: ~58 µs to ~25 ms */
    if (pulse_duration < ECHO_THRESHOLD_MIN || pulse_duration > ECHO_THRESHOLD_MAX) {
        fprintf(stderr, "Invalid echo pulse width: %u us\n", pulse_duration);
        return;
    }

    /* Distance = speed × time (speed of sound ~343 m/s) */
    float distance = (float)pulse_duration * 343000.0f / 2.0f;
    if (distance < 0.0f || distance > 4.0f) {
        fprintf(stderr, "Invalid distance: %.2f m\n", distance);
        return;
    }

    /* Append to log file */
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(g_log_file, "%s, %.2f m\n", ts, distance);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Disable ISR */
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpiod_line_release(ECHO_PIN);
    gpiod_line_release(TRIG_PIN);
    gpiod_chip_close(g_chip);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Open log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open GPIO chip --- */
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip0: %s\n", strerror(errno));
        fclose(g_log_file);
        return EXIT_FAILURE;
    }

    /* --- Get GPIO lines --- */
    struct gpiod_line *trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    struct gpiod_line *echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig_line || !echo_line) {
        fprintf(stderr, "Error getting GPIO lines: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Request lines --- */
    if (gpiod_line_request_output(trig_line, "hcsr04-trig", 0) < 0) {
        fprintf(stderr, "Error requesting trig line as output: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_input(echo_line, "hcsr04-echo") < 0) {
        fprintf(stderr, "Error requesting echo line as input: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Register ISR --- */
    if (gpiod_line_request_rising_edge_events(trig_line, "hcsr04-trig") < 0) {
        fprintf(stderr, "Error requesting trig line for ISR: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing signal handlers: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Main loop --- */
    while (g_running) {
        /* Trigger pulse */
        if (gpiod_line_set_value(trig_line, 1) < 0) {
            fprintf(stderr, "Error triggering pulse: %s\n", strerror(errno));
            break;
        }
        usleep(1);
        if (gpiod_line_set_value(trig_line, 0) < 0) {
            fprintf(stderr, "Error resetting pulse: %s\n", strerror(errno));
            break;
        }

        /* Wait for echo pulse with timeout */
        uint32_t start_tick = gpiod_line_get_value_us(echo_line);
        if (start_tick == 0) {
            fprintf(stderr, "Error: echo line never went low (timeout)\n");
            break;
        }
        uint32_t end_tick = gpiod_line_get_value_us(echo_line);
        if (end_tick == 0) {
            fprintf(stderr, "Error: echo line never went high (timeout)\n");
            break;
        }

        uint32_t pulse_duration = end_tick - start_tick;
        if (pulse_duration > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Warning: echo pulse duration %u us exceeds timeout\n",
                    pulse_duration);
        }

        /* Echo ISR callback */
        if (gpiod_line_request_rising_edge_events(echo_line, "hcsr04-echo") < 0) {
            fprintf(stderr, "Error requesting echo line for ISR: %s\n", strerror(errno));
            break;
        }

        /* Wait for echo pulse with timeout */
        uint32_t timeout = start_tick + ECHO_TIMEOUT_US;
        while (g_running && gpiod_line_get_value_us(echo_line) == 1) {
            if (gpiod_line_get_value_us(echo_line) == 0) {
                break;
            }
            if (gpiod_line_get_value_us(echo_line) > timeout) {
                fprintf(stderr, "Warning: echo pulse timeout\n");
                break;
            }
            usleep(1);
        }

        if (!g_running)
            break;

        /* Append to log file */
        time_t now = time(NULL);
        struct tm tm_buf;
        struct tm *t = localtime_r(&now, &tm_buf);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
        fprintf(g_log_file, "%s, %.2f m\n", ts, pulse_duration);
        fflush(g_log_file);
    }

    /* --- Cleanup --- */
    cleanup();
    return EXIT_SUCCESS;
}

