/*
 * VL53L1X Time-of-Flight Sensor Reader for Raspberry Pi 4 Model B
 * Uses pigpio for I2C communication and syslog for logging.
 *
 * Wiring:
 *   VL53L1X SDA -> GPIO2 (I2C1 SDA)
 *   VL53L1X SCL -> GPIO3 (I2C1 SCL)
 *   VL53L1X VDD -> 3.3V
 *   VL53L1X GND -> GND
 *   VL53L1X XSHUT -> GPIO27 (BCM 27)
 *
 * Build: gcc -Wall -Wextra -O2 -o vl53l1x_reader vl53l1x_reader.c -lpigpio -lrt
 * Run:   sudo ./vl53l1x_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x29
#define XSHUT_PIN      27
#define READ_INTERVAL  100000   /* microseconds (100 ms) */
#define MAX_RETRIES    3

/* VL53L1X register addresses */
#define VL53L1X_REG_SOFTRESET       0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0081
#define VL53L1X_REG_RESULT_DISTANCE_MM 0x0088
#define VL53L1X_REG_RESULT_DISTANCE_MM_HIGH 0x0089
#define VL53L1X_REG_RESULT_DISTANCE_MM_LOW 0x008A

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
    }
    return rc;
}

static int i2c_read_byte(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n",
                reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

static int i2c_read_word(int handle, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    if (i2c_read_byte(handle, reg, buf[0]) < 0)
        return -1;
    *out = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int vl53l1x_init(int handle)
{
    /* Soft reset */
    if (i2c_write_byte(handle, VL53L1X_REG_SOFTRESET, 0x01) < 0)
        return -1;
    gpioDelay(10000); /* 10 ms */

    /* Verify sensor is ready */
    uint8_t status;
    if (i2c_read_byte(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status) < 0)
        return -1;
    if (status != 0x00) {
        fprintf(stderr, "[ERROR] VL53L1X not ready (status=0x%02X)\n", status);
        return -1;
    }

    /* Configure XSHUT pin as output, high to enable sensor */
    if (gpioSetMode(XSHUT_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "[ERROR] gpioSetMode(XSHUT_PIN) failed\n");
        return -1;
    }
    if (gpioWrite(XSHUT_PIN, 1) < 0) {
        fprintf(stderr, "[ERROR] gpioWrite(XSHUT_PIN, HIGH) failed\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Distance measurement                                               */
/* ------------------------------------------------------------------ */
static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status;
    uint16_t distance_mm_high, distance_mm_low;

    /* Trigger a measurement */
    if (i2c_write_byte(handle, VL53L1X_REG_RESULT_RANGE_STATUS, 0x01) < 0)
        return -1;

    /* Wait for measurement to complete (max ~1.5 ms) */
    gpioDelay(2000); /* 2 ms */

    /* Read distance (high byte) */
    if (i2c_read_word(handle, VL53L1X_REG_RESULT_DISTANCE_MM_HIGH, &distance_mm_high) < 0)
        return -1;

    /* Read distance (low byte) */
    if (i2c_read_word(handle, VL53L1X_REG_RESULT_DISTANCE_MM_LOW, &distance_mm_low) < 0)
        return -1;

    *distance_mm = (uint16_t)((distance_mm_high << 8) | distance_mm_low);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_message(const char *level, const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    } else {
        strncpy(ts, "UNKNOWN", sizeof(ts));
        ts[sizeof(ts) - 1] = '\0';
    }

    char level_str[16];
    if (level) {
        snprintf(level_str, sizeof(level_str), "[%s] %s", ts, level);
    } else {
        snprintf(level_str, sizeof(level_str), "[%s] INFO", ts);
    }

    char msg_buf[256];
    snprintf(msg_buf, sizeof(msg_buf), "%s: %s", level_str, msg);

    if (level)
        fprintf(stderr, "%s\n", msg_buf);
    else
        fprintf(stderr, "%s\n", msg_buf);

    if (level)
        syslog(level, "%s", msg_buf);
    else
        syslog(LOG_INFO, "%s", msg_buf);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "[FATAL] VL53L1X initialization failed\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("VL53L1X reader started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t distance_mm;

        if (vl53l1x_read_distance(g_i2c_handle, &distance_mm) < 0) {
            fprintf(stderr, "[ERROR] Read failed; continuing.\n");
            gpioDelay(READ_INTERVAL);
            continue;
        }

        char level[16];
        if (distance_mm > 0) {
            snprintf(level, sizeof(level), "Distance: %u mm", distance_mm);
        } else {
            snprintf(level, sizeof(level), "Distance: unknown");
        }

        log_message(level, "Distance: %u mm");

        gpioDelay(READ_INTERVAL);
    }

    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

