#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define VL53L1X_ADDR 0x29
#define GATE_GPIO 24
#define DISTANCE_THRESHOLD_CM 20.0f
#define POLL_INTERVAL_MS 100
#define LOG_FILE "gate_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int init_vl53l1x(int fd) {
    if (i2c_write_reg8(fd, 0x00, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, 0x01, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x02, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x03, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x04, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x05, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x06, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x07, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x08, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x09, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x0A, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x0B, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x0C, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x0D, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x0E, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x0F, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x10, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x11, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x12, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0x13, 0x00) < 0) return -1;
