#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

#define DISTANCE_MIN_CM 2.0f
#define DISTANCE_MAX_CM 400.0f
#define SERVO_ANGLE_MIN_DEG 90
#define SERVO_ANGLE_MAX_DEG 180

#define ECHO_TIMEOUT_US 30000
#define SERVO_PULSE_WIDTH_US 1000
#define SERVO_PULSE_WIDTH_US_MIN 1000
#define SERVO_PULSE_WIDTH_US_MAX 2000

#define NUM_SAMPLES 5
#define SAMPLE_INTERVAL_US 100000

#define LOG_FILE "distance_log.csv"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

typedef struct {
    float distance;
    float angle;
} SensorData;

static volatile sig_atomic_t pulse_width = 0;
static volatile sig_atomic_t new_pulse = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void pulse_width_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 1) {
        pulse_width = 0;
        new_pulse = 1;
    } else if (level == 0) {
        pulse_width = 0;
        new_pulse = 0;
    }
}

static float calculate_distance(float pulse_width) {
    if (pulse_width < 0) return -1.0f;
    if (pulse_width > SERVO_PULSE_WIDTH_US) return -1.0f;
    float distance = (pulse_width - SERVO_PULSE_WIDTH_US) * 0.0343f / 2.0f;
    return distance;
}

static float move_servo_angle(int angle) {
    if (angle < SERVO_ANGLE_MIN_DEG) angle = SERVO_ANGLE_MIN_DEG;
    if (angle > SERVO_ANGLE_MAX_DEG) angle = SERVO_ANGLE_MAX_DEG;
    if (angle != new_pulse) {
        new_pulse = angle;
        return angle;
    }
    return new_pulse;
}

static void log_data(float distance, float angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, distance, angle);
    fflush(log_file);
}

static void cleanup_resources(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioServo(SERVO_PIN, 0);
    gpioSetMode(TRIGGER_PIN, PI_INPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set servo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(TRIGGER_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set trigger pull-up\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set echo pull-up\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SERVO_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set servo pull-up\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(TRIGGER_PIN, pulse_width_callback, NULL) < 0) {
        fprintf(stderr, "Failed to set alert function\n");
        gpioTerminate();
