static volatile sig_atomic_t pulse_width = 0;
static volatile sig_atomic_t new_pulse = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void pulse_width_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 1) {
        pulse_width = 0;
        new_pulse = 1;
    } else if (level == 0) {
        pulse_width = 0;
        new_pulse = 0;
    }
}

static float calculate_distance(float pulse_width) {
    if (pulse_width < 0) return -1.0f;
    if (pulse_width > SERVO_PULSE_WIDTH_US) return -1.0f;
    float distance = (pulse_width - SERVO_PULSE_WIDTH_US) * 0.0343f / 2.0f;
    return distance;
}

static float move_servo_angle(int angle) {
    if (angle < SERVO_ANGLE_MIN_DEG) angle = SERVO_ANGLE_MIN_DEG;
    if (angle > SERVO_ANGLE_MAX_DEG) angle = SERVO_ANGLE_MAX_DEG;
    if (angle != new_pulse) {
        new_pulse = angle;
        return angle;
    }
    return new_pulse;
}

