/*
 * Si1102 proximity sensor reader for Raspberry Pi Zero W.
 *
 * Wiring:
 *   Si1102 SDA -> GPIO2 (I2C1 SDA, pin 3)
 *   Si1102 SCL -> GPIO3 (I2C1 SCL, pin 5)
 *   Si1102 VDD -> 3.3 V
 *   Si1102 GND -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o si1102_reader si1102_reader.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./si1102_reader -t <threshold> -a <i2c_address>
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS            1
#define I2C_ADDR           0x60          /* Si1102 default address */
#define GPIO_PROX_PIN      27             /* BCM GPIO27 */
#define LOG_FILE           "proximity.log"
#define DEFAULT_THRESHOLD  1000
#define DEFAULT_ADDR       0x60

/* Si1102 register addresses (16-bit, big-endian on bus) */
#define REG_PROX_STATUS   0x00
#define REG_PROX_DATA     0x01

/* Si1102 interrupt configuration */
#define PROX_INT_GPIO     GPIO_PROX_PIN
#define PROX_INT_LEVEL    1             /* Rising edge */
#define PROX_INT_FLAGS    0x0000        /* Clear on read */

/* Global state */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int handle, uint8_t reg, uint8_t value)
{
    if (i2cWriteByteData(handle, reg, value) < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO setup                                                          */
/* ------------------------------------------------------------------ */
static int setup_gpio(void)
{
    if (gpioSetMode(GPIO_PROX_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", GPIO_PROX_PIN);
        return -1;
    }
    if (gpioSetPullUpDown(GPIO_PROX_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", GPIO_PROX_PIN);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, int16_t raw, const char *status)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    if (fprintf(fp, "%s,%d,%s\n", ts, (int)raw, status) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Proximity interrupt                                                 */
/* ------------------------------------------------------------------ */
static void interrupt_handler(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)tick;
    (void)userdata;

    if (level != 1) {
        return; /* only rising edge */
    }

    int16_t raw = 0;
    if (i2c_read_reg8(g_i2c_handle, REG_PROX_DATA, &raw) < 0) {
        return;
    }

    const char *status = (raw < DEFAULT_THRESHOLD) ? "ALERT" : "SAFE";
    if (log_data(g_log_file, raw, status) < 0) {
        fprintf(stderr, "Logging failed in interrupt handler\n");
    }

    /* Non-blocking: defer processing until the next tick */
    gpioSetAlertFunc(GPIO_PROX_PIN, NULL);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
