/*
 * HC-SR04 distance-controlled theremin using pigpio.
 *
 * Hardware:
 *   HC-SR04 trigger  -> GPIO23 (BCM)
 *   HC-SR04 echo     -> GPIO24 (BCM)
 *   8 ohm speaker      -> GPIO18 (BCM)
 *
 * Build:  gcc -O2 -Wall -o theremin theremin.c -lpigpio -lrt
 * Run:    sudo ./theremin
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24
#define SPEAKER_PIN      18

#define SPEAKER_DUTY_CYCLE_MIN   50
#define SPEAKER_DUTY_CYCLE_MAX   100
#define SPEAKER_DUTY_CYCLE_AVG  75
#define SPEAKER_DUTY_CYCLE_STEP 5

#define TRIGGER_PULSE_US      10
#define ECHO_TIMEOUT_US       200000   /* 200 ms */
#define SPEAKER_PULSE_US      (TRIGGER_PULSE_US * SPEAKER_DUTY_CYCLE_AVG)

#define MIN_DISTANCE_CM      2.0
#define MAX_DISTANCE_CM      200.0
#define MIN_FREQUENCY_HZ     200.0
#define MAX_FREQUENCY_HZ     2000.0

#define SAMPLE_PERIOD_US     10000
#define SPEAKER_PULSE_US     (SPEAKER_PULSE_US * SPEAKER_DUTY_CYCLE_AVG)

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Send a 10 µs trigger pulse on the trigger pin.
 * Returns 0 on success, -1 on timeout/error.
 */
static int trigger_pulse(int pin)
{
    if (gpioWrite(pin, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        return -1;
    }
    gpioDelay(2);
    if (gpioWrite(pin, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 1) failed\n");
        return -1;
    }
    gpioDelay(10);
    if (gpioWrite(pin, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        return -1;
    }
    return 0;
}

/*
 * Read the echo pin with a timeout.
 * Returns distance in cm, or -1.0 on timeout/error.
 */
static float read_distance(int pin)
{
    uint32_t start_tick = gpioTick();
    uint32_t elapsed = 0;

    while (gpioRead(pin) == 0) {
        if ((gpioTick() - start_tick) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo timeout on pin %d\n", pin);
            return -1.0;
        }
        gpioDelay(1);
    }

    uint32_t echo_start = gpioTick();
    while (gpioRead(pin) == 1) {
        if ((gpioTick() - echo_start) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo timeout on pin %d\n", pin);
            return -1.0;
        }
        gpioDelay(1);
    }

    uint32_t echo_end = gpioTick();
    elapsed = echo_end - echo_start;

    /* HC-SR04 distance = (echo_end - echo_start) * 34.2 cm / us */
    float distance = (float)elapsed * 0.0342f;
    return distance;
}

/*
 * Generate a tone on the speaker pin.
 * Returns 0 on success, -1 on error.
 */
static int generate_tone(float frequency)
{
    if (frequency < MIN_FREQUENCY_HZ || frequency > MAX_FREQUENCY_HZ) {
        fprintf(stderr, "Error: Frequency %.2f Hz out of range [%.0f, %.0f]\n",
                frequency, MIN_FREQUENCY_HZ, MAX_FREQUENCY_HZ);
        return -1;
    }

    int duty_cycle = (int)((frequency / MAX_FREQUENCY_HZ) * SPEAKER_DUTY_CYCLE_AVG);
    if (duty_cycle < SPEAKER_DUTY_CYCLE_MIN || duty_cycle > SPEAKER_DUTY_CYCLE_MAX) {
        fprintf(stderr, "Error: Duty cycle %.0f%% out of range [%.0f, %.0f]\n",
                duty_cycle, SPEAKER_DUTY_CYCLE_MIN, SPEAKER_DUTY_CYCLE_MAX);
        return -1;
    }

    if (gpioPWM(SPEAKER_PIN, duty_cycle) < 0) {
        fprintf(stderr, "Error: gpioPWM(speaker, %d) failed\n", duty_cycle);
        return -1;
    }
    return 0;
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure speaker pin as output */
    if (gpioSetMode(SPEAKER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(speaker, %d) failed\n", SPEAKER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure trigger pin as output, initially low */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(trigger, %d) failed\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure echo pin as input */
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(echo, %d) failed\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger is low on startup */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 theremin started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance = read_distance(ECHO_PIN);

        if (distance < 0.0f) {
            /* Error already reported; continue loop */
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        /* Logical AND: distance > 0.0 => valid reading */
        if (distance > 0.0f) {
            float frequency = (distance - MIN_DISTANCE_CM) /
                              (MAX_DISTANCE_CM - MIN_DISTANCE_CM) *
                              MAX_FREQUENCY_HZ;

            if (generate_tone(frequency) == 0) {
                printf("Distance: %.2f cm, Frequency: %.2f Hz\n",
                       distance, frequency);
            } else {
                fprintf(stderr, "Warning: Failed to generate tone\n");
            }
        } else {
            fprintf(stderr, "Warning: Distance reading out of range\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

