/*
 * Theremin-style piezo buzzer using HC-SR04 ultrasonic sensor.
 * Board:  Raspberry Pi 3 Model B+
 * Sensor: HC-SR04 echo-line-connected to GPIO23 (BCM), trigger-line to GPIO18 (BCM), echo-line to GPIO24 (BCM).
 * Library: pigpio (http://abyz.me.uk/rpi/pigpio/)
 * Build:  gcc -O2 -Wall -o theremin theremin.c -lpigpio -lrt
 * Run:    sudo ./theremin
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24
#define BUZZER_PIN       18

#define SPEED_OF_SOUND_CM_PER_US  34330.0
#define MIN_DISTANCE_CM          5.0
#define MAX_DISTANCE_CM          50.0
#define MIN_FREQUENCY_HZ          200
#define MAX_FREQUENCY_HZ          2000
#define ECHO_TIMEOUT_US           100000   /* 100 ms */
#define LOOP_DELAY_US             10000    /* 10 ms between readings */
#define TRIGGER_LOW_US           10       /* 10 us low pulse for sensor */
#define TRIGGER_HIGH_US          10       /* 10 us high pulse for sensor */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure the echo pulse width in microseconds.
 * Returns the pulse width in microseconds, or -1 on timeout.
 */
static int measure_echo_us(void)
{
    uint32_t start = gpioTick();
    while (gpioPulse(ECHO_PIN) == 0) {
        if (gpioTick() - start > ECHO_TIMEOUT_US) {
            return -1;
        }
    }
    uint32_t end = gpioTick();
    return (int)(end - start);
}

/*
 * Generate a continuous tone on the buzzer using the pigpio frequency API.
 * Returns 0 on success, -1 on error.
 */
static int generate_frequency(int frequency_hz)
{
    if (frequency_hz < MIN_FREQUENCY_HZ || frequency_hz > MAX_FREQUENCY_HZ) {
        fprintf(stderr, "Error: frequency %d Hz out of range [%d, %d]\n",
                frequency_hz, MIN_FREQUENCY_HZ, MAX_FREQUENCY_HZ);
        return -1;
    }

    /*
     * pigpio frequency generation is a simple linear mapping from
     * hertz to microseconds per hertz.  The frequency is the
     * product of the hertz and the sample rate (default 500 kHz).
     *
     *   frequency_hz * 500000 = frequency_us
     *
     * We want a range of 200–2000 Hz, so:
     *   200 Hz  ->  0.2 us
     *   2000 Hz -> 0.2 us
     *   1000 Hz -> 0.5 us
     *   500 Hz  -> 0.5 us
     *
     * The actual frequency is the product of the two:
     *   frequency_hz = (frequency_us * 500000) / (0.2 us + 0.5 us)
     *
     * We round to the nearest integer to avoid fractional samples.
     */
    int frequency_us = (int)((frequency_hz * 500000) / (0.2 + 0.5));
    if (frequency_us < MIN_FREQUENCY_HZ) frequency_us = MIN_FREQUENCY_HZ;
    if (frequency_us > MAX_FREQUENCY_HZ) frequency_us = MAX_FREQUENCY_HZ;

    if (gpioSetPulseWidth(BUZZER_PIN, frequency_us) < 0) {
        fprintf(stderr, "Error: gpioSetPulseWidth failed for buzzer pin %d\n", BUZZER_PIN);
        return -1;
    }
    return 0;
}

int main(void)
{
    /* --- Install SIGINT handler for graceful shutdown --- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(BUZZER_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER_PIN, 0) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure echo starts low */
    if (gpioWrite(ECHO_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(ECHO_PIN, 0) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Verify GPIO modes --- */
    if (gpioGetMode(TRIGGER_PIN) != PI_OUTPUT ||
        gpioGetMode(ECHO_PIN) != PI_INPUT ||
        gpioGetMode(BUZZER_PIN) != PI_OUTPUT) {
        fprintf(stderr, "Error: GPIO modes mismatch\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Theremin started. Press Ctrl+C to exit.\n");
    printf("Trigger: GPIO%d, Echo: GPIO%d, Buzzer: GPIO%d\n",
           TRIGGER_PIN, ECHO_PIN, BUZZER_PIN);
    printf("Pulse width: 10 us (low) -> 10 us (high) -> %d us\n",
           ECHO_TIMEOUT_US);
    printf("Frequency range: %d Hz -> %d Hz\n", MIN_FREQUENCY_HZ, MAX_FREQUENCY_HZ);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        /* Trigger the sensor */
        if (gpioWrite(TRIGGER_PIN, 1) < 0) {
            fprintf(stderr, "Error: gpioWrite(TRIGGER_PIN, 1) failed\n");
            break;
        }
        gpioDelay(TRIGGER_LOW_US);
        if (gpioWrite(TRIGGER_PIN, 0) < 0) {
            fprintf(stderr, "Error: gpioWrite(TRIGGER_PIN, 0) failed\n");
            break;
        }

        /* Measure echo pulse width */
        int pulse_us = measure_echo_us();
        if (pulse_us < 0) {
            fprintf(stderr, "Error: sensor read failed; reusing last valid value\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        /* Clamp to valid range */
        if (pulse_us < MIN_DISTANCE_CM) pulse_us = MIN_DISTANCE_CM;
        if (pulse_us > MAX_DISTANCE_CM) pulse_us = MAX_DISTANCE_CM;

        /* Map to frequency range */
        int freq_hz = (int)((pulse_us * SPEED_OF_SOUND_CM_PER_US) / 2.0);
        if (freq_hz < MIN_FREQUENCY_HZ) freq_hz = MIN_FREQUENCY_HZ;
        if (freq_hz > MAX_FREQUENCY_HZ) freq_hz = MAX_FREQUENCY_HZ;

        /* Generate tone */
        if (generate_frequency(freq_hz) < 0) {
            fprintf(stderr, "Error: tone generation failed\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        /* Print results */
        printf("Distance: %5d cm  Frequency: %4d Hz\n",
               pulse_us / 1000, freq_hz);

        gpioDelay(LOOP_DELAY_US);
    }

    /* --- Cleanup --- */
    gpioWrite(TRIGGER_PIN, 0);
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

