/*
 * HC-SR04 Ultrasonic Distance Sensor – Raspberry Pi Zero W
 * Trigger: GPIO17 (BCM), Echo: GPIO18 (BCM)
 * Library: pigpio (modern C API)
 *
 * Build: gcc -Wall -Wextra -O2 -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:   sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18
#define SPEED_OF_SOUND   34330.0  /* cm/s at 20 °C */
#define MIN_DISTANCE     2.0
#define MAX_DISTANCE     400.0
#define SAMPLE_INTERVAL  500000   /* microseconds (500 ms) */
#define ECHO_TIMEOUT_US  50000    /* 50 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure the echo pulse duration and return the distance in cm.
 * Returns -1.0 on timeout or invalid reading.
 */
static float measure_distance(void)
{
    uint32_t start_tick, end_tick;
    uint32_t pulse_duration;

    /* Ensure trigger is low before starting the measurement */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1.0f;
    }
    gpioDelay(2);

    /* Send 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 1) failed\n");
        return -1.0f;
    }
    gpioDelay(10);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1.0f;
    }

    /* Wait for echo to go high (start of pulse) */
    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - start_tick) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo start timeout\n");
            return -1.0f;
        }
    }

    /* Wait for echo to go low (end of pulse) */
    end_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - end_tick) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo end timeout\n");
            return -1.0f;
        }
    }

    pulse_duration = (uint32_t)(gpioTick() - start_tick);
    return (float)pulse_duration * SPEED_OF_SOUND / 2.0f / 1000000.0f;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure trigger pin as output, initial low */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER, OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure echo pin as input */
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO, INPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            fprintf(stderr, "Warning: Invalid reading (timeout or sensor error)\n");
        } else if (distance < MIN_DISTANCE) {
            fprintf(stderr, "Warning: Too close! Distance: %.2f cm\n", distance);
        } else if (distance > MAX_DISTANCE) {
            fprintf(stderr, "Warning: Too far! Distance: %.2f cm\n", distance);
        } else {
            printf("Distance: %.2f cm\n", distance);
        }

        gpioDelay(SAMPLE_INTERVAL);
    }

    /* Cleanup */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

