#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1175_ADDR    0x50
#define LOG_FILE       "proximity_log.csv"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg 0x%02X, val 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_ambient_light(int fd, uint16_t *als_visible)
{
    uint8_t reg = SI1175_ADDR;
    if (i2c_write_reg8(fd, reg, 0x00) < 0)
        return -1;
    usleep(10000);
    if (i2c_read_reg8(fd, reg, (uint8_t *)als_visible) < 0)
        return -1;
    return 0;
}

static int log_data(FILE *fp, const char *ts, uint16_t als_visible)
{
    if (fprintf(fp, "%s,%u\n", ts, als_visible) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SI1175_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                SI1175_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    uint8_t als_visible = 0;
    int rc = EXIT_SUCCESS;

    while (g_running) {
        if (read_ambient_light(fd, &als_visible) < 0) {
            fprintf(stderr, "Ambient light read failed; continuing.\n");
            usleep(SAMPLE_INTERVAL_SEC * 1000000);
            continue;
        }

        time_t now = time(NULL);
        char ts[32];
        if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S",
                     localtime(&now)) == 0) {
            fprintf(stderr, "strftime failed\n");
            continue;
        }

        if (log_data(stdout, ts, als_visible) < 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        printf("[%s] AL=%u\n", ts, als_visible);
        fflush(stdout);

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down cleanly.\n");
    if (close(fd) < 0)
        fprintf(stderr, "Warning: close(fd) failed: %s\n", strerror(errno));
    return rc;
}

