#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1182_ADDR    0x50
#define LOG_FILE       "biometric_log.txt"
#define MEAS_RATE_REG  0x00
#define PART_ID_REG    0x01
#define LOG_FILE_NAME  "biometric_log.txt"

#define SI1182_PART_ID_EXPECTED 0x00
#define SI1182_MEAS_RATE_VAL    0x0A

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int si1182_init(int fd)
{
    uint8_t part_id = 0;

    /* Verify sensor presence by reading the part ID register */
    if (i2c_read_reg8(fd, PART_ID_REG, &part_id) != 0) {
        fprintf(stderr, "Cannot read Si1182 part ID (sensor absent or bus error)\n");
        return -1;
    }
    if (part_id != SI1182_PART_ID_EXPECTED) {
        fprintf(stderr, "Unexpected Si1182 part ID: 0x%02X (expected 0x%02X)\n",
                part_id, SI1182_PART_ID_EXPECTED);
        return -1;
    }

    /* Configure measurement rate: 0x0A = 100 ms (0x0A = 0x0A) */
    if (i2c_write_reg8(fd, MEAS_RATE_REG, SI1182_MEAS_RATE_VAL) != 0)
        return -1;

    return 0;
}

