/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, int lux, int proximity)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *tm = localtime_r(&now, &tm_buf);
    char ts[32];
    if (tm == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f,%d\n", ts, lux, proximity) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the Si1182 sensor */
    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                SI1182_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (si1182_init(g_i2c_fd) != 0) {
        fprintf(stderr, "Si1182 initialization failed.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,lux,proximity\n");
        fflush(g_log_fp);
    }

    printf("Si1182-A-GM logging started. Press Ctrl+C to stop.\n");

    /* Main loop */
    while (g_running) {
        uint8_t part_id = 0;
        if (i2c_read_reg8(g_i2c_fd, PART_ID_REG, &part_id) != 0) {
            fprintf(stderr, "I2C read of PART_ID failed; continuing.\n");
            usleep(100000);
            continue;
        }

        if (part_id != SI1182_PART_ID_EXPECTED) {
            fprintf(stderr, "Unexpected Si1182 part ID: 0x%02X (expected 0x%02X)\n",
                    part_id, SI11II_PART_ID_EXPECTED);
            usleep(100000);
            continue;
        }

        /* Read ambient light (lux) */
        uint16_t lux = 0;
        if (i2c_read_reg16(g_i2c_fd, MEAS_RATE_REG, &lux) != 0) {
            fprintf(stderr, "I2C read of lux failed; continuing.\n");
            usleep(100000);
            continue;
        }

        /* Read proximity (0-255) */
        uint8_t proximity = 0;
        if (i2c_read_reg8(g_i2c_fd, MEAS_RATE_REG, &proximity) != 0) {
            fprintf(stderr, "I2C read of proximity failed; continuing.\n");
            usleep(100000);
            continue;
        }

        if (log_data(g_log_fp, lux, proximity) != 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        usleep(100000); /* 100 ms */
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }

    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

