/*
 * HC-SR04 Ultrasonic Distance Sensor with Buzzer Alarm
 * Board:  Raspberry Pi 4 Model B
 * Library: pigpio (modern C API)
 *
 * Wiring:
 *   HC-SR04 VCC -> 3.3 V (Pin 1)
 *   HC-SR04 GND -> GND  (Pin 9)
 *   HC-SR04 TRIG -> GPIO17 (Pin 11)
 *   HC-SR04 ECHO -> GPIO18 (Pin 12)
 *   HC-SR04 CLK  -> GPIO20 (Pin 21)
 *   Buzzer +     -> GPIO27 (Pin 24)
 *   Buzzer -     -> GND
 *
 * Build:  gcc -O2 -Wall -o hcsr04_buzzer hcsr04_buzzer.c -lpigpio -lrt
 * Run:    sudo ./hcsr04_buzzer
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18
#define BUZZER_PIN       27

#define DISTANCE_THRESHOLD_CM 20.0f
#define TRIGGER_PULSE_US   10
#define ECHO_TIMEOUT_US    50000   /* 50 ms max echo wait */
#define POLL_DELAY_US      10000   /* 10 ms poll interval */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly                 */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* pigpio callback: echo pulse arrived (rising)                         */
/* ------------------------------------------------------------------ */
static void echo_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;
    if (level != 1)
        return;

    /* Rising edge: start of echo pulse */
    if (tick == 0) {
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        long elapsed_us = (long)(ts.tv_sec * 1000000L + ts.tv_nsec / 1000L);
        if (elapsed_us < ECHO_TIMEOUT_US) {
            /* Falling edge: echo pulse ends */
            struct timespec ts_end;
            clock_gettime(CLOCK_MONOTONIC, &ts_end);
            long elapsed_us_end = (long)(ts_end.tv_sec * 1000000L + ts_end.tv_nsec / 1000L);
            float distance = (float)elapsed_us_end / (float)elapsed_us * 344.0f;
            printf("Distance: %.2f cm\n", distance);
        }
    }
}

/* ------------------------------------------------------------------ */
/* pigpio callback: interrupt on rising edge                           */
/* ------------------------------------------------------------------ */
static void trigger_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;
    if (level != 1)
        return;

    /* 10 µs trigger pulse */
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio library ---------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins ---------------------------------------- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set BUZZER_PIN %d as output.\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioWrite(BUZZER_PIN, 0);

    /* --- Register signal handler for graceful shutdown -------------- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio library ---------------------------------- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set BUZZER_PIN %d as output.\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure buzzer starts off */
    gpioWrite(BUZZER_PIN, 0);

    /* --- Register interrupt callback for echo pulse ---------------- */
    if (gpioSetISRFuncEx(ECHO_PIN, RISING_EDGE, 0, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: failed to register ISR on ECHO_PIN %d.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance sensor started.  Threshold: %.1f cm.  Ctrl+C to exit.\n",
           DISTANCE_THRESHOLD_CM);

    /* --- Main polling loop ------------------------------------------ */
    while (g_running) {
        gpioDelay(POLL_DELAY_US);
    }

    /* --- Clean shutdown --------------------------------------------- */
    printf("\nShutting down...\n");
    gpioWrite(BUZZER_PIN, 0);
    gpioSetISRFuncEx(ECHO_PIN, RISING_EDGE, 0, NULL, NULL);
    gpioSetMode(TRIGGER_PIN, PI_INPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioTerminate();

    return EXIT_SUCCESS;
}

