#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

#define DISTANCE_THRESHOLD_CM 200.0
#define DISTANCE_THRESHOLD_CM_CM 110.0
#define DISTANCE_THRESHOLD_CM_CM 20.0

#define SERVO_MIN_PULSE_US 1500
#define SERVO_MAX_PULSE_US 2500
#define SERVO_MIN_ANGLE 0
#define SERVO_MAX_ANGLE 180

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set servo pin mode\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_distance(void) {
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -1;
    }
    gpioDelay(2);
    if (gpioWrite(TRIGGER_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to set trigger high\n");
        return -1;
    }
    gpioDelay(10);
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -1;
    }

    uint32_t start_tick = 0, end_tick = 0;
    int timeout = 0;

    while (gpioRead(ECHO_PIN) == 0) {
        if (++timeout > 1000) {
            fprintf(stderr, "Error: echo timeout\n");
            return -1.0;
        }
        gpioDelay(1);
    }
    start_tick = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if (++timeout > 1000) {
            fprintf(stderr, "Error: echo timeout\n");
            return -1.0;
        }
        gpioDelay(1);
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    if (pulse_us == 0) {
        fprintf(stderr, "Error: echo timeout\n");
        return -1.0;
    }

    return (int)(pulse_us / 1000.0);
}

static void set_servo_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > SERVO_MAX_ANGLE) angle = SERVO_MAX_ANGLE;
    int pulse_us = (int)((SERVO_MAX_PULSE_US - SERVO_MIN_PULSE_US) * angle / SERVO_MAX_ANGLE + SERVO_MIN_PULSE_US);
    if (gpioServo(SERVO_PIN, pulse_us) != 0) {
        fprintf(stderr, "Error: gpioServo failed\n");
    }
}

static void update_distance_and_servo(float distance) {
    if (distance < DISTANCE_THRESHOLD_CM_CM) {
        set_servo_angle(SERVO_MIN_ANGLE);
    } else if (distance < DISTANCE_THRESHOLD_CM_CM + DISTANCE_THRESHOLD_CM) {
        set_servo_angle(SERVO_MIN_ANGLE + (distance - DISTANCE_THRESHOLD_CM) * (SERVO_MAX_ANGLE - SERVO_MIN_ANGLE) / (DISTANCE_THRESHOLD_CM + DISTANCE_THRESHOLD_CM));
    } else {
        set_servo_angle(SERVO_MAX_ANGLE);
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    printf("Parking Assist System started. Press Ctrl+C to exit.\n");

    while (running) {
        float distance = read_distance();
        if (distance < 0.0) {
            fprintf(stderr, "Error: distance reading failed\n");
            gpioServo(SERVO_PIN, 0);
            gpioDelay(100000);
            continue;
        }

        update_distance_and_servo(distance);
        printf("Distance: %.2f cm\n", distance);
        gpioDelay(100000);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

