/*
 * VL53L1X Time-of-Flight Sensor Reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   VL53L1X SDA -> GPIO2 (I2C bus 1 SDA)
 *   VL53L1X SCL -> GPIO3 (I2C bus 1 SCL)
 *   VL53L1X VDD -> 3.3 V
 *   VL53L1X GND -> GND
 *   Gate PWM  -> GPIO18 (hardware PWM-capable)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o vl53l1x_gate vl53l1x_gate.c -lrt
 *
 * Run:
 *   sudo ./vl53l1x_gate
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define VL53L1X_ADDR   0x29
#define GATE_PWM_PIN   18
#define GATE_PWM_FREQ   1000   /* Hz */
#define GATE_PWM_DURATION_US 1000   /* 1 ms */
#define GATE_OPEN_MM    250
#define GATE_CLOSE_MM   200
#define LOG_FILE       "gate_log.txt"
#define POLL_DELAY_US  100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, out, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
/* VL53L1X driver                                                      */
/* ------------------------------------------------------------------ */
static int vl53l1x_init(int fd)
{
    /* Verify model ID */
    uint8_t model_id;
    if (i2c_read_reg8(fd, 0x00, &model_id) != 0) {
        fprintf(stderr, "Failed to read model ID\n");
        return -1;
    }
    if (model_id != 0x00) {
        fprintf(stderr, "Unexpected model ID: 0x%02X (expected 0x00)\n",
                model_id);
        return -1;
    }

    /* Program timing budget */
    if (i2c_write_reg8(fd, 0x0C, 0x0A) != 0)
        return -1;
    if (i2c_write_reg8(fd, 0x0E, 0x00) != 0)
        return -1;
    if (i2c_write_reg8(fd, 0x10, 0x00) != 0)
        return -1;
