        return -1;
    if (i2c_write_reg8(fd, 0x16, 0x00) != 0)
        return -1;
    if (i2c_write_reg8(fd, 0x18, 0x00) != 0)
        return -1;
    if (i2c_write_reg8(fd, 0x1A, 0x00) != 0)
        return -1;
    if (i2c_write_reg8(fd, 0x1C, 0x00) != 0)
        return -1;
    if (i2c_write_reg8(fd, 0x1E, 0x00) != 0)
        return -1;
    if (i2c_write_reg8(fd, 0x20, 0x00) != 0)
        return -1;
