/*
 * VL53L1X Time-of-Flight Sensor Reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   VL53L1X SDA -> GPIO2 (I2C bus 1 SDA)
 *   VL53L1X SCL -> GPIO3 (I2C bus 1 SCL)
 *   VL53L1X VDD -> 3.3 V
 *   VL53L1X GND -> GND
 *   Gate PWM  -> GPIO18 (hardware PWM-capable)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o vl53l1x_gate vl53l1x_gate.c -lrt
 *
 * Run:
 *   sudo ./vl53l1x_gate
 */

#include <stdio.h>
