#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   18

#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US 50000  /* 50 ms */
#define SERVO_MIN_US   500
#define SERVO_MAX_US   2500
#define SERVO_ANGLE_MIN 0
#define SERVO_ANGLE_MAX 180
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define SERVO_PULSE_INTERVAL_US 100000 /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Send a 10 µs trigger pulse to the HC-SR04.
 * Returns 0 on success, -1 on timeout/error.
 */
static int trigger_sensor(void)
{
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER_PIN, 1) failed\n");
        return -1;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER_PIN, 0) failed\n");
        return -1;
    }
    return 0;
}

/*
 * Wait for the echo line to go high (rising edge) with timeout.
 * Returns 0 on success, -1 on timeout/error.
 */
static int wait_rising_edge(void)
{
    int level = 0;
    int elapsed = 0;

    while (gpioRead(ECHO_PIN) == 0) {
        gpioDelay(1);
        elapsed++;
        if (elapsed >= ECHO_TIMEOUT_US) {
            return -1;
        }
    }

    while (gpioRead(ECHO_PIN) == 1) {
        gpioDelay(1);
        elapsed++;
        if (elapsed >= ECHO_TIMEOUT_US) {
            return -1;
        }
    }

    return 0;
}

/*
 * Wait for the echo line to go low (falling edge) with timeout.
 * Returns 0 on success, -1 on timeout/error.
 */
static int wait_falling_edge(void)
{
    int level = 1;
    int elapsed = 0;

    while (gpioRead(ECHO_PIN) == 1) {
        gpioDelay(1);
        elapsed++;
        if (elapsed >= ECHO_TIMEOUT_US) {
            return -1;
        }
    }

    while (gpioRead(ECHO_PIN) == 0) {
        gpioDelay(1);
        elapsed++;
        if (elapsed >= ECHO_TIMEOUT_US) {
            return -1;
        }
    }

    return 0;
}

/*
 * Measure the distance in cm.
 * Returns distance on success, -1.0 on timeout/error.
 */
static float measure_distance(void)
{
    int level = 0;
    int elapsed = 0;

    if (trigger_sensor() < 0) {
        return -1.0f;
    }

    if (wait_rising_edge() < 0) {
        return -1.0f;
    }

    if (wait_falling_edge() < 0) {
        return -1.0f;
    }

