/*
 * Si7005 Humidity & Temperature Sensor Reader for Raspberry Pi 4 Model B
 * Uses pigpio for I2C communication.
 *
 * Wiring:
 *   Si7005 SDA -> GPIO2 (I2C1 SDA)
 *   Si7005 SCL -> GPIO3 (I2C1 SCL)
 *   Si7005 VDD -> 3.3V
 *   Si7005 GND -> GND
 *
 * Build: gcc -o si7005_reader si7005_reader.c -lpigpio -lrt
 * Run:   sudo ./si7005_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI7005_ADDR    0x40
#define CONFIG_REG     0x00
#define REG_CONFIG     0x01
#define REG_READ_REG   0x02

#define CONFIG_VAL_HUM 0x01
#define CONFIG_VAL_TEMP 0x02

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, rc);
    }
    return rc;
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading from register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int si7005_init(int handle) {
    if (i2c_write_reg(handle, CONFIG_REG, CONFIG_VAL_HUM) < 0) {
        fprintf(stderr, "Failed to write CONFIG register\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms conversion time */
    if (i2c_write_reg(handle, REG_CONFIG, CONFIG_VAL_TEMP) < 0) {
        fprintf(stderr, "Failed to write CONFIG register for temperature\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms conversion time */
    return 0;
}

static int read_sensor(int handle, uint8_t *humidity, uint8_t *temperature) {
    if (i2c_write_reg(handle, REG_READ_REG, CONFIG_VAL_HUM) < 0) {
        fprintf(stderr, "Failed to write CONFIG register for humidity\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms conversion time */

    uint8_t raw_humidity;
    if (i2c_read_reg(handle, REG_READ_REG, &raw_humidity) < 0) {
        fprintf(stderr, "Failed to read humidity register\n");
        return -1;
    }

    uint8_t raw_temperature;
    if (i2c_read_reg(handle, REG_READ_REG, &raw_temperature) < 0) {
        fprintf(stderr, "Failed to read temperature register\n");
        return -1;
    }

    *humidity = raw_humidity;
    *temperature = raw_temperature;
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, SI7005_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (si7005_init(i2c_handle) < 0) {
        fprintf(stderr, "Si7005 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si7005 initialized successfully. Reading every 2 seconds...\n");

    while (running) {
        uint8_t humidity, temperature;
        if (read_sensor(i2c_handle, &humidity, &temperature) == 0) {
            printf("Humidity: %u%%  Temperature: %u°C\n", humidity, temperature);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        sleep(2);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

