/*
 * Raspberry Pi 4 Model B - Adafruit SHT40 Temperature & Humidity Sensor
 *
 * Reads temperature and humidity from an Adafruit SHT40 on I2C bus 1.
 * Triggers a high-repeatability measurement, validates CRC, and logs
 * readings to the console every 5 seconds.
 *
 * Build:  gcc -O2 -Wall -o sht40_logger sht40_logger.c
 * Run:    sudo ./sht40_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SHT40_ADDR     0x44
#define MEASURE_HIGHREP 0x01
#define MEASURE_DELAY_US 10000   /* 10 ms */
#define LOG_INTERVAL_S  5

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* CRC-8 as used by the SHT40: poly 0x31, init 0xFF */
static uint8_t sht40_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/*
 * Reads a temperature and humidity measurement from the SHT40.
 * Returns 0 on success, -1 on I2C error, -2 on CRC failure.
 */
static int sht40_read(int fd, float *temperature, float *humidity)
{
    uint8_t cmd = MEASURE_HIGHREP | (0x00 << 4);  /* high-repeatability, no CRC */

    ssize_t n = write(fd, &cmd, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }

    usleep(MEASURE_DELAY_US);

    uint8_t buf[6];
    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }

    if (sht40_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -2;
    }
    if (sht40_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Humidity CRC mismatch\n");
        return -2;
    }

    uint16_t raw_t = (buf[0] << 8) | buf[1];
    uint16_t raw_h = (buf[3] << 8) | buf[4];

    *temperature = -45.0f + 175.0f * (float)raw_t / 65535.0f;
    *humidity   = 100.0f * (float)raw_h / 65535.0f;

    return 0;
}

