{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SHT40_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                SHT40_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /*
     * The SHT40 datasheet specifies a high-repeatability measurement
     * command that does not require a CRC.
     */
    if (write(fd, &MEASURE_HIGHREP, 1) != 1) {
        fprintf(stderr, "Cannot trigger measurement: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("SHT40 logger started. Logging every %d s. Press Ctrl+C to exit.\n",
           LOG_INTERVAL_S);

    while (g_running) {
        float temperature, humidity;

        if (sht40_read(fd, &temperature, &humidity) == 0) {
            time_t now = time(NULL);
            struct tm tm_info;
            char ts[32];
            localtime_r(&now, &tm_info);
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

            printf("%s  Temperature: %.2f C  Humidity: %.2f %%\n",
                   ts, temperature, humidity);
            fflush(stdout);
        } else {
            fprintf(stderr, "Sensor read failed; re-initializing I2C bus.\n");
            close(fd);
            fd = open(I2C_BUS, O_RDWR);
            if (fd < 0) {
                fprintf(stderr, "Cannot reopen I2C bus: %s\n", strerror(errno));
                continue;
            }
            if (ioctl(fd, I2C_SLAVE, SHT40_ADDR) < 0) {
                fprintf(stderr, "Cannot set I2C slave address: %s\n", strerror(errno));
                close(fd);
                continue;
            }
            if (write(fd, &MEASURE_HIGHREP, 1) != 1) {
                fprintf(stderr, "Cannot trigger measurement: %s\n", strerror(errno));
                close(fd);
                continue;
            }
        }

        sleep(LOG_INTERVAL_S);
    }

    printf("\nShutting down cleanly.\n");
    close(fd);
    return EXIT_SUCCESS;
}

