/*
 * Raspberry Pi 3 Model B+ - MLX90614ESF-BAA Temperature Logger
 *
 * Reads ambient and object temperatures from a Melexis MLX90614ESF-BAA
 * infrared sensor over I2C /dev/i2c-1 every 5 seconds and logs them
 * to temperature_log.csv.  Handles I2C initialisation failures,
 * sensor-absent scenarios, and SIGINT for graceful shutdown.
 *
 * Build:  gcc -O2 -Wall -o temperature_logger temperature_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX90614_ADDR  0x60
#define LOG_FILE       "temperature_log.csv"
#define SAMPLE_INTERVAL 5

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/*
 * Write a 16-bit value to an I2C register.
 * Returns 0 on success, -1 on failure.
 */
static int i2c_write_reg16(int fd, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(value & 0xFF);
    buf[2] = (uint8_t)((value >> 8) & 0xFF);

    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit value from an I2C register.
 * Returns 0 on success, -1 on failure.
 */
static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/*
 * Open the I2C bus and acquire the sensor.
 * Returns 0 on success, -1 on failure.
 */
static int init_i2c(void)
{
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                MLX90614_ADDR, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * Read ambient and object temperatures from the MLX90614.
 * Returns 0 on success, -1 on failure.
 */
static int read_temperature(int fd, float *ambient, float *object)
{
    uint16_t raw_ambient, raw_object;

    if (i2c_read_reg16(fd, 0x00, &raw_ambient) < 0)
        return -1;
    if (i2c_read_reg16(fd, 0x01, &raw_object) < 0)
        return -1;

    *ambient = (float)raw_ambient / 10.0f;
    *object   = (float)raw_object / 10.0f;

    return 0;
}

/*
 * Append a timestamped reading to the log file.
 * Returns 0 on success, -1 on failure.
 */
static int log_data(FILE *fp, float ambient, float object)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, ambient, object) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    int fd = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the log file in append mode */
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    fd = init_i2c();
    if (fd < 0) {
        fprintf(stderr, "Failed to initialize I2C bus.\n");
        goto cleanup;
    }

    printf("MLX90614 temperature logger started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_INTERVAL);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        float ambient, object;

        if (read_temperature(fd, &ambient, &object) == 0) {
            if (log_data(fp, ambient, object) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature data.\n");
        }

        /* Sleep for the sample interval, checking g_running every second */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down gracefully...\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        if (fclose(fp) != 0) {
            fprintf(stderr, "Warning: fclose failed: %s\n", strerror(errno));
        }
    }
    if (fd >= 0) {
        if (close(fd) != 0) {
            fprintf(stderr, "Warning: close failed: %s\n", strerror(errno));
        }
    }

    return rc;
}

