        return EXIT_FAILURE;
    }

    /* Open the log file in append mode */
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    fd = init_i2c();
    if (fd < 0) {
        fprintf(stderr, "Failed to initialize I2C bus.\n");
        goto cleanup;
    }

    printf("MLX90614 temperature logger started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_INTERVAL);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        float ambient, object;

        if (read_temperature(fd, &ambient, &object) == 0) {
            if (log_data(fp, ambient, object) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature data.\n");
        }

        /* Sleep for the sample interval, checking g_running every second */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down gracefully...\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        if (fclose(fp) != 0) {
            fprintf(stderr, "Warning: fclose failed: %s\n", strerror(errno));
        }
    }
    if (fd >= 0) {
        if (close(fd) != 0) {
            fprintf(stderr, "Warning: close failed: %s\n", strerror(errno));
        }
    }

    return rc;
}

