/*
 * SDP810-125Pa differential pressure & temperature logger for Raspberry Pi Zero W.
 * Uses pigpio for I2C communication.
 *
 * Build: gcc -O2 -Wall -o sdp810_logger sdp810_logger.c -lpigpio -lrt
 * Run:   sudo ./sdp810_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS          1
#define SDP810_ADDR      0x5A
#define LOG_FILE         "pressure_log.csv"
#define MEAS_INTERVAL_S  1
#define MEAS_DELAY_US    1000   /* 1 ms between measurements */
#define MAX_RETRIES      3

/* SDP810 continuous measurement command:
 *   0x00  = start continuous measurement
 *   0x01  = continuous measurement mode (0x01)
 *   0x00  = stop continuous measurement (0x00)
 */
static const uint8_t CMD_START_CONT_MEAS[2] = {0x00, 0x01};

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                         */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Read 9 bytes from the SDP810                                         */
/* ------------------------------------------------------------------ */
static int read_sdp810(int handle, uint8_t *buf)
{
    int n = i2cReadDevice(handle, (char *)buf, 9);
    if (n != 9) {
        fprintf(stderr, "i2cReadDevice failed: expected 9 bytes, got %d\n", n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Convert raw values                                                   */
/* ------------------------------------------------------------------ */
static int convert_raw(const uint8_t *raw,
                        float *pressure, float *temperature)
{
    if (raw[0] != 0x00 || raw[1] != 0x00) {
        fprintf(stderr, "Invalid command byte: 0x%02X 0x%02X\n",
                raw[0], raw[1]);
        return -1;
    }

    uint16_t raw_dp = ((uint16_t)raw[2] << 8) | raw[3];
    uint16_t raw_t  = ((uint16_t)raw[4] << 8) | raw[5];

    /* Scale factors are 2 bytes each; validate with the documented
     * scale factors in the SDP810 datasheet. */
    if (crc8(&raw[6], 2) != raw[6]) {
        fprintf(stderr, "DP CRC-8 mismatch\n");
        return -1;
    }
    if (crc8(&raw[8], 2) != raw[8]) {
        fprintf(stderr, "T CRC-8 mismatch\n");
        return -1;
    }

    *pressure = (float)raw_dp / 0x80.0f;
    *temperature = (float)raw_t / 0x80.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a row to the CSV file                                         */
/* ------------------------------------------------------------------ */
static int log_data(const char *filename, float pressure, float temperature)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    } else {
        fprintf(fp, "1970-01-01T00:00:00,%.2f,%.2f\n", pressure, temperature);
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                 */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --- */
    g_i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Start continuous measurement --- */
    if (i2cWriteDevice(g_i2c_handle, CMD_START_CONT_MEAS, 2) != 0) {
        fprintf(stderr, "Failed to start continuous measurement\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SDP810 logger started. Logging to %s every %d s. Press Ctrl+C to stop.\n",
           LOG_FILE, MEAS_INTERVAL_S);

    /* --- Main loop --- */
    while (g_running) {
        uint8_t buf[9];
        int retries = 0;

        while (retries < MAX_RETRIES && g_running) {
            if (read_sdp810(g_i2c_handle, buf) == 0) {
                break;
            }
            retries++;
            if (retries < MAX_RETRIES)
                gpioDelay(MEAS_DELAY_US);
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read sensor after %d retries.\n", MAX_RETRIES);
            break;
        }

        if (convert_raw(buf, NULL, NULL) != 0) {
            fprintf(stderr, "Failed to convert raw data.\n");
            break;
        }

        float pressure, temperature;
        if (log_data(LOG_FILE, (float)buf[0], (float)buf[1]) != 0) {
            fprintf(stderr, "Failed to log data.\n");
            break;
        }

        printf("DP: %.2f Pa, T: %.2f C\n", (float)buf[0], (float)buf[1]);
        gpioDelay(MEAS_INTERVAL_S * 1000000);
    }

    /* --- Cleanup --- */
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

