#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SHT40_ADDR     0x44
#define LOG_FILE       "sht40_log.txt"
#define SAMPLE_INTERVAL 5
#define MEASURE_DELAY_US 10000   /* 10 ms */

/* Sensirion SHT40 high-repeatability measurement command */
#define SHT40_MEAS_HIGH_REP  0x01

/* Sensirion CRC-8: polynomial 0x31, initial 0xFF */
static uint8_t sht40_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
