/*
 * SDP31 Differential Pressure & Temperature Logger for Raspberry Pi Zero W
 * Uses pigpio for I²C and libgpiod for GPIO.
 *
 * Build: gcc -O2 -Wall -o airflow airflow.c -lpigpio -lgpiod
 * Run:   sudo ./airflow
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS          1
#define I2C_ADDR         0x5A          /* SDP31 I2C address */
#define LOG_FILE         "airflow.log"
#define SAMPLE_INTERVAL  100000        /* 100 ms */
#define MAX_RETRIES      3
#define RETRY_DELAY_US   (1000000 * (MAX_RETRIES - 1))
#define MEAS_DELAY_US    1000          /* 1 ms for continuous measurement */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I²C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int handle, uint8_t cmd)
{
    int rc = i2cWriteByteData(handle, 0, cmd);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (cmd=0x%02X): %s\n",
                cmd, pigpio_error(rc));
    }
    return rc;
}

static int i2c_read_block(int handle, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadDevice(handle, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C read failed (got %d bytes, expected %u): %s\n",
                rc, len, rc < 0 ? pigpio_error(rc) : "short read");
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* SDP31 driver                                                        */
/* ------------------------------------------------------------------ */
static int sdp31_init(int handle)
{
    /* Trigger continuous measurement */
    if (i2c_write_cmd(handle, 0x01) < 0) {
        fprintf(stderr, "Failed to trigger SDP31 measurement\n");
        return -1;
    }
    gpioDelay(MEAS_DELAY_US);

    /* Read six bytes: pressure MSB, pressure LSB, CRC, temperature MSB,
     * temperature LSB, CRC */
    uint8_t buf[6];
    if (i2c_read_block(handle, buf, sizeof(buf)) < 0) {
        fprintf(stderr, "Failed to read SDP31 data\n");
        return -1;
    }

    /* CRC check (MSB first) */
    uint8_t crc_msb = buf[0];
    uint8_t crc_lsb = buf[1];
    if (crc_msb != buf[2] || crc_lsb != buf[3]) {
        fprintf(stderr, "CRC mismatch: pressure=0x%02X, temp=0x%02X\n",
                crc_msb, crc_lsb);
        return -1;
    }

    /* Parse 16-bit big-endian values */
    int16_t pressure_raw = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t temperature_raw = (int16_t)((buf[4] << 8) | buf[5]);

    /* Convert to physical units */
    /* SDP31 datasheet: pressure in Pa, temperature in °C */
    /* pressure_pa = pressure_raw / 1000.0 + 0.5;
    /* temperature_c = temperature_raw / 1000.0 + 0.5; */

    return 0;
}

static int sdp31_read(int handle, float *pressure_pa, float *temperature_c)
{
    if (i2c_write_cmd(handle, 0x01) < 0) {
        return -1;
    }
    gpioDelay(MEAS_DELAY_US);

    uint8_t buf[6];
    if (i2c_read_block(handle, buf, sizeof(buf)) < 0) {
        return -1;
    }

    /* CRC check (MSB first) */
    uint8_t crc_msb = buf[0];
    uint8_t crc_lsb = buf[1];
    if (crc_msb != buf[2] || crc_lsb != buf[3]) {
        fprintf(stderr, "CRC mismatch: pressure=0x%02X, temp=0x%02X\n",
                crc_msb, crc_lsb);
        return -1;
    }

    /* Parse 16-bit big-endian values */
    int16_t pressure_raw = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t temperature_raw = (int16_t)((buf[4] << 8) | buf[5]);

    *pressure_pa = (float)pressure_raw / 1000.0f + 0.5f;
    *temperature_c = (float)temperature_raw / 1000.0f + 0.5f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float pressure_pa, float temperature_c)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure_pa, temperature_c) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus=%d, addr=0x%02X): %s\n",
                I2C_BUS, I2C_ADDR, pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize SDP31 sensor */
    if (sdp31_init(g_i2c_handle) < 0) {
        fprintf(stderr, "SDP31 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen log");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,pressure_pa,temperature_c\n");
        fflush(g_log_file);
    }

    printf("SDP31 logger started. Logging to %s every %d ms. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_INTERVAL);

    /* Main sampling loop */
    while (g_running) {
        float pressure_pa, temperature_c;

        if (sdp31_read(g_i2c_handle, &pressure_pa, &temperature_c) == 0) {
            if (log_data(g_log_file, pressure_pa, temperature_c) != 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed; continuing\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            gpioDelay(100000);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

