        fprintf(stderr, "fflush failed\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus=%d, addr=0x%02X): %s\n",
                I2C_BUS, I2C_ADDR, pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize SDP31 sensor */
    if (sdp31_init(g_i2c_handle) < 0) {
        fprintf(stderr, "SDP31 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen log");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,pressure_pa,temperature_c\n");
        fflush(g_log_file);
    }

    printf("SDP31 logger started. Logging to %s every %d ms. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_INTERVAL);

    /* Main sampling loop */
    while (g_running) {
        float pressure_pa, temperature_c;

        if (sdp31_read(g_i2c_handle, &pressure_pa, &temperature_c) == 0) {
            if (log_data(g_log_file, pressure_pa, temperature_c) != 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed; continuing\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            gpioDelay(100000);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

