/*
 * Si7015 Temperature & Humidity Logger for Raspberry Pi 3 Model B+
 * Uses pigpio for I2C and logging.
 *
 * Wiring:
 *   Si7015 SDA -> GPIO2 (I2C bus 1 SDA)
 *   Si7015 SCL -> GPIO3 (I2C bus 1 SCL)
 *   Si7015 VDD -> 3.3 V
 *   Si7015 GND -> GND
 *
 * Build: gcc -O2 -Wall -o si7015_logger si7015_logger.c -lpigpio -lrt
 * Run:   sudo ./si7015_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x50
#define LOG_FILE       "sensor_data.txt"
#define SAMPLE_INTERVAL 5   /* seconds */
#define MAX_RETRIES    3
#define MEAS_TIMEOUT_US 200000 /* 200 ms max measurement time */

/* Si7015 command register (16-bit) */
#define CMD_TEMP_HOLD   0x01
#define CMD_HUM_HOLD    0x02
#define CMD_NO_HOLD     0x03

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(uint8_t cmd)
{
    int rc = i2cWriteByteData(i2c_handle, 0, cmd);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X): %s\n",
                cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(uint8_t *buf, int len)
{
    int rc = i2cReadDevice(i2c_handle, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if (rc != len) {
        fprintf(stderr, "I2C read short: got %d bytes, expected %d\n",
                rc, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int init_sensor(void)
{
    /*
     * Si7015 No Hold Master mode:
     *   Write CMD_NO_HOLD (0x03) to the command register.
     *   This sets the sensor to no hold mode and starts a measurement.
     */
    if (i2c_write_cmd(CMD_NO_HOLD) < 0)
        return -1;

    /*
     * Wait for the first measurement to be ready.
     * The datasheet specifies a maximum measurement time of ~20 ms.
     */
    gpioDelay(MEAS_TIMEOUT_US);

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read temperature and humidity                                        */
/* ------------------------------------------------------------------ */
static int read_sensor(float *temperature, float *humidity)
{
    uint8_t buf[2];

    /*
     * Read 2 bytes from the sensor.
     * The datasheet specifies the register address for a measurement
     * command is 0x00 (0x00,0x00) for temperature and 0x01 (0x01,0x01) for
     * humidity.
     */
    if (i2c_read_bytes(buf, 2) < 0)
        return -1;

    /*
     * The Si7015 returns the temperature in degrees Celsius and the
     * humidity in percent relative humidity.
     */
    int16_t raw_temp = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_hum  = (int16_t)((buf[1] << 8) | buf[2]);

    *temperature = (float)raw_temp / 100.0f;
    *humidity    = (float)raw_hum / 100.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(float temperature, float humidity)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n",
                timestamp, temperature, humidity) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(stdout, "Si7015 logger started. Logging to %s every %d s.\n",
            LOG_FILE, SAMPLE_INTERVAL);
    fprintf(stdout, "Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (!terminate) {
        float temperature, humidity;

        if (read_sensor(&temperature, &humidity) == 0) {
            if (log_data(temperature, humidity) < 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }

        /* Sleep in 1-second increments so SIGINT is caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL && !terminate; i++)
            gpioDelay(1000000);
    }

    /* Cleanup */
    fprintf(stdout, "\nShutting down...\n");
    fprintf(stdout, "Closing I2C bus %d, closing log file, terminating pigpio...\n",
            I2C_BUS);

    if (i2c_handle >= 0)
        i2cClose(i2c_handle);
    if (log_file != NULL)
        fclose(log_file);
    gpioTerminate();

    return EXIT_SUCCESS;
}

