code:
/*
 * SDP800-500Pa differential pressure logger for Raspberry Pi 3 Model B+
 * Uses Linux I2C syscalls (no pigpio or wiringPi).
 *
 * Wiring:
 *   SDP800 SDA -> GPIO2 (pin 3, I2C bus 1)
 *   SDP800 SCL -> GPIO3 (pin 5, I2C bus 1)
 *   SDP800 VDD -> 3.3 V
 *   SDP800 GND -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o airflow_logger airflow_logger.c
 *
 * Run:
 *   ./airflow_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP800_ADDR    0x5A
#define LOG_FILE       "airflow_data.txt"
#define READ_INTERVAL  100000   /* microseconds */
#define TRIGGER_MS     45
#define READ_DELAY_US  (TRIGGER_MS * 1000)

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* CRC-8 as used by Sensirion: poly 0x31, init 0xFF, no final XOR */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/*
 * Send a continuous-measurement trigger command to the SDP800.
 * Returns 0 on success, -1 on error.
 */
static int sdp800_trigger(int fd)
{
    uint8_t cmd[2] = { 0x00, 0x00 };
    ssize_t n = write(fd, cmd, 2);
    if (n != 2) {
        fprintf(stderr, "I2C write failed: %zd bytes (expected 2)\n", n);
        return -1;
    }
    return 0;
}

/*
 * Read nine bytes from the SDP800: 3 pressure, 3 temp, 3 scale.
 * Returns 0 on success, -1 on error.
 */
static int sdp800_read(int fd, uint8_t *buf, size_t len)
{
    if (len != 9) {
        fprintf(stderr, "Read: expected 9 bytes, got %zu\n", len);
        return -1;
    }

    ssize_t n = read(fd, buf, len);
    if (n != len) {
        fprintf(stderr, "I2C read failed: %zd bytes (expected %zu)\n", n, len);
        return -1;
    }
    return 0;
}

/*
 * Log a single line to the CSV file.
 * Returns 0 on success, -1 on error.
 */
static int log_line(FILE *fp, double pressure, double temp)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time");
        return -1;
    }
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        return -1;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temp) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open(" I2C_BUS ")");
        return EXIT_FAILURE;
    }

    /* Acquire the SDP800 slave address */
    if (ioctl(fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        close(fd);
        return EXIT_FAILURE;
    }

    /* Trigger the continuous-measurement command */
    if (sdp800_trigger(fd) != 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    /* Wait for the first measurement to complete (~45 ms) */
    usleep(READ_DELAY_US);

    /* Open the log file in append mode */
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        close(fd);
        return EXIT_FAILURE;
    }

    /* Write the header row */
    if (fprintf(fp, "Timestamp,Pressure (Pa),Temperature (C)\n") < 0) {
        perror("fprintf(header)");
        fclose(fp);
        close(fd);
        return EXIT_FAILURE;
    }
    if (fflush(fp) != 0) {
        perror("fflush(header)");
        fclose(fp);
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Logging SDP800 data to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    /* Main loop */
    while (g_running) {
        uint8_t buf[9];
        if (sdp800_read(fd, buf, sizeof(buf)) != 0) {
            fprintf(stderr, "Sensor read error; continuing.\n");
            usleep(READ_INTERVAL);
            continue;
        }

        /* Validate CRCs */
        if (crc8(&buf[0], 2) != buf[2]) {
            fprintf(stderr, "Pressure CRC mismatch\n");
            usleep(READ_INTERVAL);
            continue;
        }
        if (crc8(&buf[3], 2) != buf[5]) {
            fprintf(stderr, "Temperature CRC mismatch\n");
            usleep(READ_INTERVAL);
            continue;
        }
        if (crc8(&buf[6], 2) != buf[8]) {
            fprintf(stderr, "Scale-factor CRC mismatch\n");
            usleep(READ_INTERVAL);
            continue;
        }

        double pressure = (double)buf[0] / 256.0;
        double temp     = (double)buf[3] / 256.0;

        if (log_line(fp, pressure, temp) != 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

