/*
 * STS30-DIS Temperature Logger for Raspberry Pi Zero W
 * Uses pigpio for I2C communication.
 *
 * Build: gcc -Wall -Wextra -O2 -o sts30_logger sts30_logger.c -lpigpio -lrt
 * Run:   sudo ./sts30_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define STS30_ADDR 0x50
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"
#define SAMPLE_INTERVAL_US 100000  /* 100 ms */
#define CONVERSION_DELAY_US 15000   /* 15 ms */

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;
static FILE *error_log_file = NULL;

/* CRC-8 checksum for Sensirion sensors (polynomial 0x31, init 0xFF) */
static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (error_log_file != NULL) {
        fclose(error_log_file);
        error_log_file = NULL;
    }
    gpioTerminate();
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X (pigpio error %d)\n",
                I2C_BUS, STS30_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_sts30(float *temperature) {
    uint8_t cmd[2] = {0x00, 0x00};
    uint8_t data[3];
    int result;

    /* Issue single-shot high-repeatability measurement command */
    result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to write measurement command to I2C device (pigpio error %d)\n", result);
        return -1;
    }

    /* Wait for conversion to complete (datasheet: max conversion time ~15 ms) */
    gpioDelay(CONVERSION_DELAY_US);

    /* Read 3 bytes: temperature (2 data bytes) + CRC byte */
    result = i2cReadDevice(i2c_handle, (char *)data, 3);
    if (result != 3) {
        fprintf(stderr, "Error: Failed to read 3 bytes from I2C device (pigpio error %d)\n", result);
        return -1;
    }

    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "Error: CRC mismatch on temperature data (calc=0x%02X, recv=0x%02X)\n",
                crc8(data, 2), data[2]);
        return -1;
    }

    uint16_t raw_temp = ((uint16_t)data[0] << 8) | data[1];
    *temperature = -45.0f + (175.0f * raw_temp) / 65535.0f;
    return 0;
}

static void log_temperature(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

static void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (error_log_file != NULL) {
        fprintf(error_log_file, "%s, %s\n", timestamp, message);
        fflush(error_log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main(void) {
    float temperature;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (error_log_file == NULL) {
        fprintf(stderr, "Error: Failed to open error log file %s\n", ERROR_LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("STS30-DIS temperature logger started. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_sts30(&temperature) == 0) {
            log_temperature(temperature);
            printf("Temperature: %.2f C\n", temperature);
        } else {
            log_error("Failed to read temperature from sensor");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

