/*
 * SDP800-500Pa differential pressure sensor reader for Raspberry Pi 3 Model B+
 * Uses pigpio for I2C and a CSV log file.
 *
 * Wiring:
 *   SDP800 VCC  -> 3.3 V (pin 1)
 *   SDP800 GND  -> GND  (pin 9)
 *   SDP800 SDA  -> GPIO2 / I2C bus 1 SDA (pin 3)
 *   SDP800 SCL  -> GPIO3 / I2C bus 1 SCL (pin 5)
 *
 * Build: gcc -O2 -Wall -o airflow airflow.c -lpigpio -lrt
 * Run:   sudo ./airflow
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x5A          /* SDP800-500Pa default address */
#define LOG_FILE       "airflow_data.txt"
#define READ_DELAY_US  1000          /* 1 ms between reads */
#define MAX_RETRIES    3

/* SDP800-500Pa command: continuous measurement, no filter, no auto-ranging */
#define CMD_CONT_MEAS   0x01

/* CRC-8 polynomial: x^8 + x^5 + x^4 + 1 (Sensirion: 0x31) */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static void signal_handler(int sig)
{
    (void)sig;
    fprintf(stderr, "\nCaught signal, cleaning up...\n");
    fflush(stderr);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file >= 0) {
        fclose(log_file);
        log_file = -1;
    }
    gpioTerminate();
    exit(0);
}

static int init_i2c(void)
{
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int init_sensor(void)
{
    /* Start continuous measurement */
    if (i2cWriteByteData(i2c_handle, 0x01, CMD_CONT_MEAS) < 0) {
        fprintf(stderr, "Error starting continuous measurement\n");
        return -1;
    }
    gpioDelay(2000); /* 2 ms settle time */
    return 0;
}

static int read_sensor(float *pressure, float *temperature)
{
    uint8_t cmd[2] = { CMD_CONT_MEAS, 0x00 };
    uint8_t buf[6];
    int retries = MAX_RETRIES;

    while (retries > 0) {
        if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) < 0) {
            fprintf(stderr, "Error writing measurement command\n");
            retries--;
            gpioDelay(10000);
            continue;
        }

        gpioDelay(READ_DELAY_US);

        if (i2cReadDevice(i2c_handle, (char *)buf, 6) != 6) {
            fprintf(stderr, "Error reading sensor data\n");
            retries--;
            gpioDelay(10000);
            continue;
        }

        if (crc8(buf, 2) != buf[2]) {
            fprintf(stderr, "CRC mismatch on pressure data\n");
            retries--;
            gpioDelay(10000);
            continue;
        }
        if (crc8(buf + 3, 2) != buf[5]) {
            fprintf(stderr, "CRC mismatch on temperature data\n");
            retries--;
            gpioDelay(10000);
            continue;
        }

        uint16_t raw_pressure = ((uint16_t)buf[0] << 8) | buf[1];
        uint16_t raw_temperature = ((uint16_t)buf[3] << 8) | buf[4];

        *pressure = (float)raw_pressure / 100.0f;
        *temperature = (float)raw_temperature / 100.0f;
        return 0;
    }

    fprintf(stderr, "Failed to read sensor after %d retries\n", MAX_RETRIES);
    return -1;
}

static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tm_info;
    localtime_r(&now, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
}

static int log_data(float pressure, float temperature)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return -1;
    }

    char ts[32];
    get_timestamp(ts, sizeof(ts));

    fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    fclose(fp);
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    if (init_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("SDP800-500Pa sensor reader started. Press Ctrl+C to stop.\n");

    while (1) {
        float pressure, temperature;
        if (read_sensor(&pressure, &temperature) == 0) {
            printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);
            if (log_data(pressure, temperature) != 0) {
                fprintf(stderr, "Warning: failed to log data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }
        gpioDelay(100000); /* 100 ms */
    }

    /* Should not reach here */
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

