code:
/*
 * Si7021 humidity/temperature monitor for Raspberry Pi 4 Model B
 * Uses pigpio for I2C and GPIO control.
 *
 * Wiring:
 *   Si7021 SDA -> GPIO2 (I2C1 SDA)
 *   Si7021 SCL -> GPIO3 (I2C1 SCL)
 *   Si7021 VDD -> 3.3 V
 *   Si7021 GND -> GND
 *   Fan control -> GPIO18 (BCM, active-high)
 *
 * Build:  gcc -O2 -Wall -o si7021_monitor si7021_monitor.c -lpigpio -lrt
 * Run:    sudo ./si7021_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS          1
#define I2C_ADDR         0x40          /* Si7021 default address */
#define FAN_GPIO         18            /* BCM 18, active-high fan control */
#define TEMP_THRESHOLD   28.0f         /* °C */
#define FAN_ON_THRESHOLD 27.0f         /* °C */
#define BUFFER_SIZE      60
#define READ_INTERVAL_US 2000000       /* 2 s */
#define MAX_RETRIES      3
#define SENSOR_TIMEOUT_US 2000000       /* 2 s */

/* Si7021 register map (16-bit, big-endian on bus) */
#define REG_TEMP_MSB      0x00
#define REG_TEMP_LSB      0x01
#define REG_HUM_MSB       0x02
#define REG_HUM_LSB       0x03
#define REG_ID_MSB        0x04
#define REG_ID_LSB        0x05

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* Circular buffer of temperature readings (microseconds since boot) */
static uint32_t g_buffer[BUFFER_SIZE];
static int g_buffer_index = 0;
static int g_buffer_count = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int handle, uint8_t reg, uint8_t value)
{
    if (i2cWriteByteData(handle, reg, value) < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X)\n",
                reg, value);
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X)\n", reg);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int i2c_read_reg16(int handle, uint8_t reg, uint16_t *value)
{
    int msb = i2cReadByteData(handle, reg);
    if (msb < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X, msb)\n", reg);
        return -1;
    }
    int lsb = i2cReadByteData(handle, reg + 1);
    if (lsb < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X, lsb)\n", reg + 1);
        return -1;
    }
    *value = (uint16_t)((msb << 8) | lsb);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Si7021 helpers                                                      */
/* ------------------------------------------------------------------ */
static int si7021_init(int handle)
{
    uint8_t id = 0;
    if (i2c_read_reg8(handle, REG_ID_MSB, &id) < 0) {
        fprintf(stderr, "Failed to read Si7021 ID register\n");
        return -1;
    }
    if (id != 0x70) {
        fprintf(stderr, "Si7021 ID mismatch: 0x%02X (expected 0x70)\n", id);
        return -1;
    }

    /* Verify sensor presence by reading the HUM_MSB register */
    uint8_t hum_msb = 0;
    if (i2c_read_reg8(handle, REG_HUM_MSB, &hum_msb) < 0) {
        fprintf(stderr, "Failed to read Si7021 HUM_MSB register\n");
        return -1;
    }
    if (hum_msb != 0x00) {
        fprintf(stderr, "Si7021 HUM_MSB mismatch: 0x%02X (expected 0x00)\n", hum_msb);
        return -1;
    }

    /* Configure temperature measurement: MSB=1, LSB=0, ODR=0x00 (1 Hz) */
    if (i2c_write_reg8(handle, REG_TEMP_MSB, 0x01) < 0) return -1;
    if (i2c_write_reg8(handle, REG_HUM_MSB, 0x00) < 0) return -1;
    if (i2c_write_reg8(handle, REG_ODR_MSB, 0x00) < 0) return -1;

    /* Allow sensor to stabilize */
    gpioDelay(10000); /* 10 ms */
    return 0;
}

static int si7021_read_temp(int handle, float *temp_out)
{
    uint8_t msb = 0, lsb = 0;
    if (i2c_read_reg8(handle, REG_TEMP_MSB, &msb) < 0) return -1;
    if (i2c_read_reg8(handle, REG_TEMP_LSB, &lsb) < 0) return -1;

    int32_t raw = (int32_t)((msb << 8) | lsb);
    *temp_out = (float)raw / 100.0f;
    return 0;
}

static int si7021_read_hum(int handle, float *hum_out)
{
    uint8_t msb = 0, lsb = 0;
    if (i2c_read_reg8(handle, REG_HUM_MSB, &msb) < 0) return -1;
    if (i2c_read_reg8(handle, REG_HUM_LSB, &lsb) < 0) return -1;

    int32_t raw = (int32_t)((msb << 8) | lsb);
    *hum_out = (float)raw / 100.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Fan control                                                         */
/* ------------------------------------------------------------------ */
static void fan_set(int on)
{
    if (gpioWrite(FAN_GPIO, on ? 1 : 0) < 0) {
        fprintf(stderr, "gpioWrite failed on GPIO%d\n", FAN_GPIO);
    }
}

static void fan_off(void)
{
    fan_set(0);
}

/* ------------------------------------------------------------------ */
/* Circular buffer                                                     */
/* ------------------------------------------------------------------ */
static void buffer_add(float ts, float temp)
{
    g_buffer[g_buffer_index] = ts;
    g_buffer_index = (g_buffer_index + 1) % BUFFER_SIZE;
    if (g_buffer_count < BUFFER_SIZE) g_buffer_count++;
}

static void buffer_print(void)
{
    printf("[");
    for (int i = 0; i < g_buffer_count; i++) {
        printf("%u ", g_buffer[i]);
    }
    printf("] Temp: %.2f C  Hum: %.2f %%\n",
           g_buffer[g_buffer_index - g_buffer_count + 1],
           g_buffer[g_buffer_index - g_buffer_count + 2]);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C init --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
