        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Fan GPIO init --- */
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO%d\n", FAN_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fan_off();

    /* --- Signal handling --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Si7021 monitoring started. Fan control on GPIO%d (BCM).\n",
           FAN_GPIO);
    printf("Threshold: %.1f °C  Fan off at %.1f °C\n",
           TEMP_THRESHOLD, FAN_ON_THRESHOLD);
    printf("Press Ctrl+C to exit.\n");

