/*
 * SCD40 CO2 sensor reader for Raspberry Pi Zero W
 * Uses pigpio for I2C and libgpiod for GPIO.
 *
 * Wiring:
 *   SCD40 SDA -> GPIO2 (I2C1 SDA, pin 3)
 *   SCD40 SCL -> GPIO3 (I2C1 SCL, pin 5)
 *   SCD40 VDD -> 3.3 V
 *   SCD40 GND -> GND
 *
 * Build: gcc -O2 -Wall -o scd40_reader scd40_reader.c -lpigpio -lgpiod
 * Run:   sudo ./scd40_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- SCD40 constants ---- */
#define I2C_BUS            1
#define SCD40_ADDR         0x5A          /* 100 kHz clock-stretching-compatible speed */
#define MEASURE_PERIOD_US  1000000        /* 1 second between first read and periodic poll */
#define POLL_INTERVAL_US   5000000        /* 5 seconds between periodic polls */
#define DATA_READY_FLAG    0x01          /* Data ready flag bit in status register */

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ---- CRC-8 (Sensirion: poly 0x31, init 0xFF) ---- */
static uint8_t scd40_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ---- Initialize pigpio ---- */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }
    return 0;
}

/* ---- Initialize I2C ---- */
static int initialize_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d).\n", g_i2c_handle);
        return -1;
    }
    return 0;
}

/* ---- Send a command ---- */
static int send_command(uint8_t cmd)
{
    if (i2cWriteByteData(g_i2c_handle, SCD40_ADDR, cmd) < 0) {
        fprintf(stderr, "Error: i2cWriteByteData failed (cmd=0x%02X).\n", cmd);
        return -1;
    }
    return 0;
}

/* ---- Read a 9-byte block ---- */
static int read_sensor_data(uint8_t *data)
{
    if (i2cReadI2CBlockData(g_i2c_handle, SCD40_ADDR, (char *)data, 9) != 9) {
        fprintf(stderr, "Error: i2cReadI2CBlockData failed (expected 9 bytes).\n");
        return -1;
    }
    return 0;
}

/* ---- Read CO2 value ---- */
static int read_co2_ppm(uint16_t *co2_ppm)
{
    uint8_t data[3];
    if (read_sensor_data(data) != 0)
        return -1;

    /* CRC check for each 2-byte word */
    if (scd40_crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "Error: CRC mismatch on CO2 data word.\n");
        return -1;
    }

    *co2_ppm = (uint16_t)((data[0] << 8) | data[1]);
    return 0;
}

/* ---- Read temperature and humidity ---- */
static int read_sensor_data(float *temperature, float *humidity)
{
    uint8_t data[6];
    if (read_sensor_data(data) != 0)
        return -1;

    /* CRC check for each 2-byte word */
    if (scd40_crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "Error: CRC mismatch on temperature/humidity data word.\n");
        return -1;
    }
    if (scd40_crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "Error: CRC mismatch on humidity data word.\n");
        return -1;
    }

    uint16_t raw_temp = (data[0] << 8) | data[1];
    uint16_t raw_hum  = (data[3] << 8) | data[4];

    *temperature = -45.0f + 175.0f * (float)raw_temp / 65535.0f;
    *humidity    = 100.0f * (float)raw_hum / 65535.0f;
    return 0;
}

/* ---- Append data to log file ---- */
static int log_data(float co2_ppm, float temperature, float humidity)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return -1;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (fprintf(g_log_file, "%s,%.2f,%.2f,%.2f\n", ts, co2_ppm, temperature, humidity) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed.\n");
        return -1;
    }
    fflush(g_log_file);
    return 0;
}

/* ---- Main ---- */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize GPIO and I2C */
    if (initialize_gpio() != 0)
        return EXIT_FAILURE;
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen("air_quality.log", "a");
    if (g_log_file == NULL) {
        perror("Error: cannot open air_quality.log");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Start periodic measurement */
    if (send_command(0x01) != 0) {
        fprintf(stderr, "Error: failed to start periodic measurement.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("SCD40 CO2 sensor reader started. Press Ctrl+C to stop.\n");

    /* Main polling loop */
    while (g_running) {
        uint8_t data[9];
        int ready = 0;

        /* Check data ready flag */
        if (i2cReadI2CBlockData(g_i2c_handle, SCD40_ADDR, (char *)data, 9) == 9) {
            ready = (data[0] & 0x01) ? 1 : 0;
        }

        if (ready) {
            uint16_t co2_ppm;
            float temperature, humidity;

            if (read_co2_ppm(&co2_ppm) == 0) {
                printf("CO2: %u ppm\n", co2_ppm);
                if (log_data(co2_ppm, temperature, humidity) != 0)
                    fprintf(stderr, "Warning: failed to log data.\n");
            } else {
                fprintf(stderr, "Warning: failed to read CO2 data.\n");
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL_US / 100000 && g_running; i++)
            gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

