/*
 * TMP05 Digital Temperature Sensor Reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   TMP05 PWM  -> GPIO4 (BCM, physical pin 7)
 *   TMP05 VCC  -> 3.3 V (physical pin 1)
 *   TMP05 GND  -> GND  (physical pin 9)
 *
 * Build:  gcc -O2 -Wall -Wextra -o tmp05_reader tmp05_reader.c -lgpiod
 * Run:    sudo ./tmp05_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME   "gpiochip4"   /* BCM GPIO controller on Pi 4 */
#define GPIO_LINE_OFFSET 4            /* BCM GPIO4 */
#define LOG_FILE         "temperature_log.txt"
#define SAMPLE_INTERVAL  5000000      /* microseconds (5 s) */
#define TIMEOUT_US       50000        /* 50 ms timeout for edge wait */
#define MAX_READINGS     3
#define MIN_TEMP_C       -40.0f
#define MAX_TEMP_C       150.0f

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_iso8601_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm tm_info;

    time(&rawtime);
    if (localtime_r(&rawtime, &tm_info) == NULL) {
        snprintf(buf, len, "1970-01-01T00:00:00Z");
        return;
    }
    strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_info);
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_temperature(float temperature)
{
    char ts[32];
    get_iso8601_timestamp(ts, sizeof(ts));

    if (fprintf(g_log_file, "%s, Temperature: %.2f C\n", ts, temperature) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
    }
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* TMP05 driver                                                         */
/* ------------------------------------------------------------------ */
static int read_temperature(struct gpiod_line *line, float *temperature)
{
    int high_count = 0;
    int low_count  = 0;
    int total_count = 0;

    /*
     * TMP05 PWM output is a digital signal; we count high-to-low
     * transitions to measure the pulse width.
     */
    while (high_count < TIMEOUT_US && g_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            fprintf(stderr, "Error reading GPIO line: %s\n", strerror(errno));
            return -1;
        }
        if (val == 1) {
            high_count++;
        } else {
            low_count++;
        }
        usleep(1000);
    }

    if (!g_running) return -1;

    if (high_count == 0) {
        fprintf(stderr, "Error: TMP05 low-time (TL) is zero (sensor malfunction)\n");
        return -1;
    }

    /*
     * TMP05 high-to-low transition is the pulse width;
     * low-to-high is the total cycle duration.
     */
    total_count = high_count + low_count;

    /*
     * TMP05 outputs a square wave; the pulse width is half the
     * total cycle duration.
     */
    *temperature = (float)total_count * 0.5f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    float temperature;
    int consecutive_failures = 0;
    int consecutive_valid = 0;

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: failed to install SIGTERM handler: %s\n",
                strerror(errno));
    }

    /* ---- Open log file ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip ---- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        fclose(g_log_file);
        g_log_file = NULL;
        return EXIT_FAILURE;
    }

    /* ---- Get GPIO line ---- */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        fclose(g_log_file);
        g_log_file = NULL;
        return EXIT_FAILURE;
    }

    /* ---- Request line as input ---- */
    if (gpiod_line_request_input(line, "tmp05_reader") < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        fclose(g_log_file);
        g_log_file = NULL;
        return EXIT_FAILURE;
    }

    printf("TMP05 temperature reader started. Logging to '%s' every %d s.\n",
           LOG_FILE, SAMPLE_INTERVAL);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        if (read_temperature(line, &temperature) == 0) {
            consecutive_valid++;
            consecutive_failures = 0;

            if (temperature < MIN_TEMP_C || temperature > MAX_TEMP_C) {
                fprintf(stderr, "Error: temperature %.2f C out of valid range: %.2f C\n",
                        temperature, MIN_TEMP_C);
                consecutive_failures++;
                if (consecutive_failures >= MAX_READINGS) {
                    fprintf(stderr, "Error: too many consecutive failures; aborting.\n");
                    break;
                }
            } else {
                log_temperature(temperature);
                consecutive_valid = 0;
            }
        } else {
            consecutive_failures++;
            if (consecutive_failures >= MAX_READINGS) {
                fprintf(stderr, "Error: too many consecutive failures; aborting.\n");
                break;
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly. */
        usleep(100000);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");

    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    printf("Temperature reader stopped.\n");
    return EXIT_SUCCESS;
}

