/*
 * SHT35-DIS-B Greenhouse Temperature & Humidity Logger
 * Board:  Raspberry Pi 4 Model B
 * Bus:    I2C bus 1 (GPIO2/GPIO3 = SDA, GPIO5/GPIO9 = SCL)
 * Sensor: Sensirion SHT35-DIS-B
 *
 * Reads temperature and humidity every 5 s, logs to environmental_data.txt,
 * and handles retries on I2C errors.  Runs in a SIGINT-safe loop.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SHT35_ADDR     0x40
#define MEASURE_CMD    0x01
#define MEASURE_DELAY  15000   /* 15 ms */
#define LOG_INTERVAL   5       /* seconds */
#define MAX_RETRIES    3
#define RETRY_DELAY    1000000 /* 1 s */
#define SAMPLE_DELAY   500000  /* 500 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion: poly 0x31, init 0xFF, no final XOR)                */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, uint8_t cmd)
{
    uint8_t buf[2] = { cmd, 0x00 };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X): %s\n",
                cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* SHT35-DIS-B                                                         */
/* ------------------------------------------------------------------ */
static int sht35_init(int fd)
{
    if (i2c_write_cmd(fd, MEASURE_CMD) < 0)
        return -1;

    usleep(MEASURE_DELAY);

    uint8_t buf[6];
    if (i2c_read_bytes(fd, buf, 6) < 0)
        return -1;

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t raw_temp = ((uint16_t)buf[0] << 8) | buf[1];
