/*
 * SDP810-125Pa differential pressure sensor reader for Raspberry Pi 3 Model B+
 * Uses pigpio for I2C communication.
 *
 * Wiring:
 *   SDP810 SDA -> GPIO2 (I2C bus 1 SDA)
 *   SDP810 SCL -> GPIO3 (I2C bus 1 SCL)
 *   SDP810 VDD -> 3.3 V
 *   SDP810 GND -> GND
 *
 * Build: gcc -O2 -Wall -o airflow airflow.c -lpigpio -lrt
 * Run:   sudo ./airflow
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- SDP810 constants ---- */
#define I2C_BUS            1
#define SDP810_ADDR        0x5A          /* I2C address for SDP810-125Pa */

/* Continuous measurement command (documented in SDP810 datasheet) */
#define CMD_CONT_MEASURE   0x01

/* ---- Globals for signal-safe cleanup ---- */
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ---- CRC-8 (Sensirion polynomial 0x31, init 0xFF) ---- */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ---- Cleanup helper ---- */
static void cleanup(void)
{
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_fd >= 0) {
        i2cClose(i2c_fd);
        i2c_fd = -1;
    }
    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at SDP810 address */
    i2c_fd = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, SDP810_ADDR, i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("airflow.csv", "a");
    if (!log_file) {
        perror("Error: cannot open airflow.csv");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,pressure_pa,temperature_c\n");
        fflush(log_file);
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Main loop */
    while (!terminate) {
        /* Send continuous measurement command */
        if (i2cWriteByte(i2c_fd, CMD_CONT_MEASURE) < 0) {
            fprintf(stderr, "Error: failed to send measurement command.\n");
            cleanup();
            return EXIT_FAILURE;
        }

        /* Wait for conversion (datasheet: max conversion time ~45 ms) */
        gpioDelay(50000); /* 50 ms */

        /* Read 9 bytes: pressure, temperature, scale factor */
        char buf[9];
        int bytes_read = i2cReadDevice(i2c_fd, buf, 9);
        if (bytes_read != 9) {
            fprintf(stderr, "Error: I2C read failed (got %d bytes, expected 9).\n",
                    bytes_read);
            cleanup();
            return EXIT_FAILURE;
        }

        /* Validate CRCs */
        if (crc8(&buf[0], 2) != buf[2]) {
            fprintf(stderr, "Error: pressure CRC mismatch.\n");
            cleanup();
            return EXIT_FAILURE;
        }
        if (crc8(&buf[3], 2) != buf[5]) {
            fprintf(stderr, "Error: temperature CRC mismatch.\n");
            cleanup();
            return EXIT_FAILURE;
        }
        if (crc8(&buf[6], 2) != buf[8]) {
            fprintf(stderr, "Error: scale factor CRC mismatch.\n");
            cleanup();
            return EXIT_FAILURE;
        }

        /* Convert raw values to physical units */
        uint16_t pressure_raw = ((uint16_t)buf[0] << 8) | buf[1];
        uint16_t temp_raw    = ((uint16_t)buf[3] << 8) | buf[4];
        uint8_t  sf_raw      = buf[6];

        /* Convert to physical units */
        float pressure = (float)pressure_raw / (float)sf_raw;
        float temp     = (float)temp_raw / (float)sf_raw;

        /* Append to CSV */
        time_t now = time(NULL);
        struct tm tm_info;
        char ts[32];
        localtime_r(&now, &tm_info);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

        fprintf(log_file, "%s,%.2f,%.2f\n", ts, pressure, temp);
        fflush(log_file);

        printf("[%s] Pressure: %.2f Pa, Temperature: %.2f C\n",
               ts, pressure, temp);

        /* Sleep 1 second */
        gpioDelay(1000000);
    }

    /* Graceful shutdown */
    cleanup();
    return EXIT_SUCCESS;
}

