        char ts[32];
        localtime_r(&now, &tm_info);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

        fprintf(log_file, "%s,%.2f,%.2f\n", ts, pressure, temp);
        fflush(log_file);

        printf("[%s] Pressure: %.2f Pa, Temperature: %.2f C\n",
               ts, pressure, temp);

        /* Sleep 1 second */
        gpioDelay(1000000);
    }

    /* Graceful shutdown */
    cleanup();
    return EXIT_SUCCESS;
}

