/*
 * Si7021 Greenhouse Monitor — Raspberry Pi Zero W
 *
 * Reads temperature and humidity from an Adafruit Si7021 on I2C bus 1
 * (GPIO 2/3) and logs the data to environment.log every 5 s.
 *
 * Build:  gcc -O2 -Wall -Wextra -o si7021_monitor si7021_monitor.c
 * Run:    sudo ./si7021_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI7021_ADDR    0x40
#define LOG_FILE       "environment.log"
#define POLL_MS        100
#define READ_TIMEOUT_MS 100

/* Si7021 register addresses */
#define REG_TEMP_MSB    0x00
#define REG_TEMP_LSB    0x01
#define REG_HUM_MSB     0x02
#define REG_HUM_LSB     0x03
#define REG_STATUS      0x04
#define REG_RESET       0x05
#define REG_CONFIG      0x06
#define REG_DATA_CFG    0x07
#define REG_DATA_MSB    0x08
#define REG_DATA_LSB    0x09

#define CMD_RESET       0x01
#define CMD_READ_TEMP   0x01
#define CMD_READ_HUM    0x02

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (polynomial 0x31, initial 0xFF) as per Si7021 datasheet          */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Si7021 initialization                                               */
/* ------------------------------------------------------------------ */
static int si7021_init(int fd)
{
    /* Soft reset */
    if (i2c_write_byte(fd, REG_RESET, CMD_RESET) < 0)
        return -1;
    usleep(2000); /* 2 ms settle */

    /* Configure: default config (MSB=LSB=0, no auto-increment, no CRC) */
    if (i2c_write_byte(fd, REG_CONFIG, 0x00) < 0)
        return -1;

    /* Read current configuration */
    uint8_t cfg;
    if (i2c_read_bytes(fd, REG_CONFIG, &cfg, 1) < 0)
        return -1;

    /* Default: MSB=LSB=0, no CRC, no auto-increment */
    if (cfg != 0x00) {
        if (i2c_write_byte(fd, REG_CONFIG, 0x00) < 0)
            return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one measurement                                                */
/* ------------------------------------------------------------------ */
static int si7021_read_measurement(int fd, uint8_t reg, uint8_t *buf,
                                   size_t len)
{
    if (i2c_write_byte(fd, reg, CMD_READ_TEMP) < 0)
        return -1;
    usleep(READ_TIMEOUT_MS * 1000); /* 100 ms max */

    if (i2c_read_bytes(fd, reg, buf, len) < 0)
        return -1;

    /* Verify CRC */
    if (crc8(buf, len) != buf[len - 1]) {
        fprintf(stderr, "CRC mismatch on measurement 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the Si7021 slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                SI7021_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (si7021_init(g_i2c_fd) < 0) {
        fprintf(stderr, "Si7021 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(fp) == 0) {
        fprintf(fp, "timestamp,temperature_C,humidity_percent\n");
        fflush(fp);
    }

    printf("Si7021 monitoring started. Logging to %s every 5 s.\n",
           LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    /* Main loop */
    while (g_running) {
        uint8_t buf[3];
        if (si7021_read_measurement(g_i2c_fd, REG_TEMP_MSB, buf, 3) < 0) {
            fprintf(stderr, "Read failed; will retry next cycle.\n");
            usleep(POLL_MS * 1000);
            continue;
        }

        uint16_t raw_temp = (buf[0] << 8) | buf[1];
        uint16_t raw_hum  = (buf[2] << 8) | buf[3];

        /* Verify CRC */
        if (crc8(buf, 3) != buf[3]) {
            fprintf(stderr, "CRC mismatch on temperature data.\n");
            usleep(POLL_MS * 1000);
            continue;
        }
        if (crc8(buf + 4, 3) != buf[5]) {
            fprintf(stderr, "CRC mismatch on humidity data.\n");
            usleep(POLL_MS * 1000);
            continue;
        }

        /* Convert to Celsius */
        float temp_c = (float)raw_temp / 16.0f;

        /* Convert humidity to percentage */
        float hum_pct = (float)raw_hum / 65536.0f * 100.0f;

        /* Log data */
        time_t now = time(NULL);
        struct tm tm_info;
        char ts[32];
        localtime_r(&now, &tm_info);
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);

        fprintf(fp, "%s,%.2f,%.2f\n", ts, temp_c, hum_pct);
        fflush(fp);

        printf("%s  T=%.2f C  H=%.2f %%\n", ts, temp_c, hum_pct);

        /* Sleep for 5 s, but wake early on signal */
        for (int i = 0; i < 50 && g_running; i++)
            usleep(100000); /* 100 ms */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

