/*
 * SDP810-500Pa Differential Pressure & Temperature Logger
 * Board:  Raspberry Pi 4 Model B
 * Bus:    I2C bus 1 (GPIO2/3 = SDA, GPIO3/5 = SCL)
 * Address: 0x60 (documented)
 *
 * Build:  gcc -O2 -Wall -o sdp810_logger sdp810_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP810_ADDR    0x60
#define LOG_FILE       "airflow.dat"
#define SAMPLE_PERIOD  1
#define CONV_TIME_US   5000   /* 5 ms for 500 Pa conversion */

/* SDP810 command: continuous measurement (0x01) */
#define SDP810_CMD_CONT  0x01

/* CRC-8 polynomial 0x31, init 0xFF (Sensirion: 0x8D, 0xFF) */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x8D : (crc << 1);
    }
    return crc;
}

static void sig_handler(int sig)
{
    (void)sig;
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", sig);
    _exit(EXIT_FAILURE);
}

static int i2c_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int init_i2c(void)
{
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, SDP810_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                SDP810_ADDR, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int init_sensor(int fd)
{
    if (i2c_write_cmd(fd, SDP810_CMD_CONT) < 0)
        return -1;

    usleep(CONV_TIME_US);

    uint8_t buf[9];
    if (i2c_read_bytes(fd, buf, sizeof(buf)) < 0)
        return -1;

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(buf + 6, 2) != buf[8]) {
        fprintf(stderr, "Scale-factor CRC mismatch\n");
        return -1;
    }

    return 0;
}

static float read_pressure(int fd)
{
    uint8_t data[3];
    if (i2c_read_bytes(fd, data, sizeof(data)) < 0)
        return -1.0f;

    uint16_t raw_p = ((uint16_t)data[0] << 8) | data[1];
    uint16_t raw_t = ((uint16_t)data[3] << 8) | data[4];

    return (float)raw_p / 100.0f;
}

static float read_temperature(int fd)
{
    uint8_t data[3];
    if (i2c_read_bytes(fd, data, sizeof(data)) < 0)
        return -1.0f;

    uint16_t raw_t = ((uint16_t)data[0] << 8) | data[1];
    uint16_t scale = ((uint16_t)data[3] << 8) | data[4];

    return (float)raw_t * scale / 100.0f;
}

static int log_data(FILE *fp, float pressure, float temperature)
{
    if (fprintf(fp, "%.2f,%.2f\n", pressure, temperature) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void)
{
    int fd = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = init_i2c();
    if (fd < 0)
        goto cleanup;

    if (init_sensor(fd) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        goto cleanup;
    }

    fp = fopen(LOG_FILE, "ab");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    while (1) {
        float pressure = read_pressure(fd);
        float temperature = read_temperature(fd);

        if (pressure < 0.0f || temperature < 0.0f) {
            fprintf(stderr, "Sensor read error, skipping sample\n");
            sleep(SAMPLE_PERIOD);
            continue;
        }

        if (log_data(fp, pressure, temperature) < 0) {
            fprintf(stderr, "Logging failed, continuing\n");
        }

        sleep(SAMPLE_PERIOD);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fp) fclose(fp);
    if (fd >= 0) close(fd);
    return rc;
}

