/*
 * SDP800-500Pa differential pressure sensor reader for Raspberry Pi 3 Model B+
 * Uses pigpio for I2C communication.
 *
 * Wiring:
 *   SDP800 SDA -> GPIO 2 (I2C bus 1 SDA)
 *   SDP800 SCL -> GPIO 3 (I2C bus 1 SCL)
 *   SDP800 VDD -> 3.3 V
 *   SDP800 GND -> GND
 *
 * Build: gcc -Wall -o sdp800_reader sdp800_reader.c -lpigpio -lrt
 * Run:   sudo ./sdp800_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x5A          /* SDP800-500Pa I2C address */
#define LOG_FILE       "pressure_log.txt"
#define CONV_TIME_US   45000         /* 45 ms conversion time */
#define SAMPLE_US      5000000       /* 5 s between readings */
#define MAX_RETRIES    3

/* SDP800 continuous measurement command (16-bit MSB, 16-bit LSB) */
#define CMD_CONT_MSB    0x0000
#define CMD_CONT_LSB    0x0000

/* CRC-8 polynomial used by Sensirion (X^8 + X^5 + X^4 + 1) */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static void signal_handler(int sig)
{
    (void)sig;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", sig);
    gpioTerminate();
    exit(0);
}

static int i2c_write_cmd(int handle, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    int rc = i2cWriteDevice(handle, (char *)buf, 2);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (rc=%d)\n", rc);
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int handle, uint8_t *buf, int len)
{
    int rc = i2cReadDevice(handle, (char *)buf, len);
    if (rc != len) {
        fprintf(stderr, "I2C read failed (rc=%d, expected %d)\n", rc, len);
        return -1;
    }
    return 0;
}

static int read_pressure(int handle, float *pressure)
{
    uint8_t cmd[2] = { (uint8_t)(CMD_CONT_MSB >> 8), (uint8_t)(CMD_CONT_MSB & 0xFF) };
    uint8_t data[9];

    if (i2c_write_cmd(handle, cmd) != 0)
        return -1;

    gpioDelay(CONV_TIME_US);

    if (i2c_read_bytes(handle, data, 9) != 0)
        return -1;

    /* Validate CRC for each data word */
    for (int i = 0; i < 3; i++) {
        if (crc8(&data[i * 3], 2) != data[i * 3 + 2]) {
            fprintf(stderr, "CRC mismatch on data word %d\n", i);
            return -1;
        }
    }

    int16_t raw_pressure = (int16_t)((data[0] << 8) | data[1]);
    *pressure = (float)raw_pressure / 100.0f;
    return 0;
}

static void log_pressure(float pressure)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        return;
    }
    fprintf(fp, "%s, %.2f Pa\n", ts, pressure);
    fclose(fp);
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(stderr, "SDP800-500Pa reader started. Logging to %s every 5 s.\n", LOG_FILE);

    while (1) {
        float pressure;
        int retries = 0;

        while (retries < MAX_RETRIES && read_pressure(handle, &pressure) == 0) {
            retries++;
            if (retries < MAX_RETRIES)
                gpioDelay(1000000); /* 1 s between retries */
        }

        if (retries >= MAX_RETRIES) {
            fprintf(stderr, "Failed to read pressure after %d retries.\n", MAX_RETRIES);
            break;
        }

        if (pressure < 0.0f) {
            fprintf(stderr, "Sensor read failed after %d retries.\n", MAX_RETRIES);
            break;
        }

        log_pressure(pressure);
        printf("Pressure: %.2f Pa\n", pressure);

        gpioDelay(SAMPLE_US);
    }

    i2cClose(handle);
    gpioTerminate();
    fprintf(stderr, "Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

