/*
 * Raspberry Pi 3 Model B+ - Honeywell Zephyr HAF Series HAFBLF0100A2AX5 Digital Airflow Sensor
 *
 * Reads differential pressure from the HAF sensor over I2C, computes the
 * corresponding flow rate, and drives a PWM fan on GPIO18 using hardware PWM.
 * Logs each measurement to flow_log.txt.
 *
 * Build: gcc -O2 -Wall -o airflow airflow.c -lpigpio -lrt
 * Run:   sudo ./airflow
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS          1
#define I2C_ADDR         0x10
#define PWM_PIN          18
#define PWM_FREQUENCY    25000
#define SAMPLE_DELAY_US  100000   /* 100 ms */
#define LOG_FILE         "flow_log.txt"

/* HAF sensor register map (from datasheet) */
#define REG_PRESSURE_MSB  0x00
#define REG_PRESSURE_LSB  0x01
#define REG_TEMP_MSB       0x02
#define REG_TEMP_LSB       0x03
#define REG_CONFIG_MSB     0x04
#define REG_CONFIG_LSB     0x05
#define REG_STATUS_MSB     0x06
#define REG_STATUS_LSB     0x07
#define REG_CONFIG_DATA    0x08
#define REG_CONFIG_DATA_LSB 0x09

#define HAF_CONFIG_TEMP_ON  0x01
#define HAF_CONFIG_TEMP_OFF 0x00
#define HAF_CONFIG_PWM_ON   0x01
#define HAF_CONFIG_PWM_OFF  0x00

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg(int handle, uint8_t reg, uint8_t value)
{
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "[ERROR] I2C write to reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *value)
{
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(handle, reg_buf, 1) != 1) {
        fprintf(stderr, "[ERROR] I2C write (reg select) for reg 0x%02X failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, (char *)value, 1) != 1) {
        fprintf(stderr, "[ERROR] I2C read from reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int handle, uint8_t reg_lsb, uint16_t *value)
{
    char reg_buf[1] = { (char)reg_lsb };
    if (i2cWriteDevice(handle, reg_buf, 1) != 1) {
        fprintf(stderr, "[ERROR] I2C write (reg select) for reg 0x%02X failed\n", reg_lsb);
        return -1;
    }
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "[ERROR] I2C read from reg 0x%02X failed\n", reg_lsb);
        return -1;
    }
    *value = (uint16_t)((uint8_t)data[0] | ((uint8_t)data[1] << 8));
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor helpers                                                      */
/* ------------------------------------------------------------------ */
static int read_pressure(int handle, float *pressure_pa)
{
    uint8_t msb, lsb;
    if (i2c_read_reg16(handle, REG_PRESSURE_MSB, &msb) != 0)
        return -1;
    if (i2c_read_reg16(handle, REG_PRESSURE_LSB, &lsb) != 0)
        return -1;
    uint16_t raw = (uint16_t)((uint8_t)msb | ((uint8_t)lsb << 8));
    *pressure_pa = (float)raw / 100.0f;
    return 0;
}

static int read_temperature(int handle, float *temperature_c)
{
    uint8_t msb, lsb;
    if (i2c_read_reg16(handle, REG_TEMP_MSB, &msb) != 0)
        return -1;
    if (i2c_read_reg16(handle, REG_TEMP_LSB, &lsb) != 0)
        return -1;
    uint16_t raw = (uint16_t)((uint8_t)msb | ((uint8_t)lsb << 8));
    *temperature_c = (float)raw / 100.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Fan control                                                         */
/* ------------------------------------------------------------------ */
static int control_fan(float pressure_pa)
{
    if (pressure_pa < 0.0f)
        pressure_pa = 0.0f;
    if (pressure_pa > 1000.0f)
        pressure_pa = 1000.0f;

    /* PWM on GPIO18 */
    if (gpioPWM(PWM_PIN, pressure_pa * PWM_FREQUENCY) != 0) {
        fprintf(stderr, "[ERROR] gpioPWM failed\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float pressure_pa, float temperature_c)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        return -1;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f\n", timestamp, pressure_pa) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log failed\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "[ERROR] fflush failed\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (addr 0x%02X): %d\n",
                I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,pressure_Pa\n");
        fflush(g_log_file);
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[FATAL] sigaction failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure HAF sensor */
    if (i2c_write_reg(g_i2c_handle, REG_CONFIG_MSB, HAF_CONFIG_TEMP_ON) != 0) {
        fprintf(stderr, "[FATAL] Failed to configure HAF sensor\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (i2c_write_reg(g_i2c_handle, REG_CONFIG_LSB, HAF_CONFIG_TEMP_OFF) != 0) {
        fprintf(stderr, "[FATAL] Failed to configure HAF sensor\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (i2c_write_reg(g_i2c_handle, REG_CONFIG_DATA_MSB, HAF_CONFIG_PWM_ON) != 0) {
        fprintf(stderr, "[FATAL] Failed to configure HAF sensor\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (i2c_write_reg(g_i2c_handle, REG_CONFIG_DATA_LSB, HAF_CONFIG_PWM_OFF) != 0) {
        fprintf(stderr, "[FATAL] Failed to configure HAF sensor\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure PWM */
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode failed for PWM\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "[FATAL] gpioSetPWMfrequency failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(PWM_PIN, PWM_FREQUENCY) != 0) {
