        cleanup();
        return EXIT_FAILURE;
    }

    printf("HAF sensor monitoring started. Press Ctrl+C to stop.\n");

    /* Main loop */
    while (g_running) {
        float pressure_pa = 0.0f;
        float temperature_c = 0.0f;

        if (read_pressure(g_i2c_handle, &pressure_pa) != 0) {
