/*
 * Raspberry Pi Zero W – STLM75 Temperature Monitor
 *
 * Reads the STLM75 digital temperature sensor on I2C bus 1 once per second.
 * Stores each reading in a 10-element circular buffer and computes a
 * running average.  Drives an LED on GPIO17 (BCM) so that it is on
 * when the average temperature exceeds 28.0 °C and off otherwise.
 *
 * Build:  gcc -O2 -Wall -Wextra -o stlm75_monitor stlm75_monitor.c -lgpiod
 * Run:    sudo ./stlm75_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <math.h>

#include <gpiod.h>

#define I2C_BUS          1
#define I2C_ADDR         0x5A
#define LED_PIN          17
#define TEMP_THRESHOLD   28.0f
#define BUFFER_SIZE      10
#define SAMPLE_PERIOD_S  1

/* ---- Circular buffer ---- */

typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static CircularBuffer temp_buffer = {
    .head = 0,
    .count = 0,
};

/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", sig);
    /* Ensure LED is off before cleanup */
    if (gpio_line_set_value(LED_PIN, 0) < 0)
        fprintf(stderr, "Warning: failed to set LED off on signal.\n");
    exit(EXIT_SUCCESS);
}

/* ------------------------------------------------------------------ */

static void init_circular_buffer(CircularBuffer *cb)
{
    cb->head = 0;
    cb->count = 0;
}

static void add_to_circular_buffer(CircularBuffer *cb, float value)
{
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
