code:
/*
 * Raspberry Pi 4 Model B - SCD30 CO2 Sensor Reader
 *
 * Reads CO2 ppm, temperature, and humidity from a Sensirion SCD30
 * on I2C bus 1, and logs the data to air_quality.log every 5 s.
 *
 * Build:  gcc -O2 -Wall -Wextra -o scd30_reader scd30_reader.c
 * Run:    ./scd30_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <stdint.h>
#include <stdbool.h>

#include <sys/time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS          "/dev/i2c-1"
#define SCD30_ADDR       0x33
#define LOG_FILE         "air_quality.log"
#define SAMPLE_INTERVAL  5
#define MAX_CO2_PPM      1200.0f
#define CO2_OFF_THRESHOLD 800.0f
#define CO2_LOW_THRESHOLD 1200.0f
#define CO2_HIGH_THRESHOLD 1200.0f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion: poly 0x31, init 0xFF, no final XOR)                */
/* ------------------------------------------------------------------ */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int fd, uint8_t byte)
{
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* SCD30 initialization                                                 */
/* ------------------------------------------------------------------ */
static int scd30_init(int fd)
{
    /*
     * SCD30 requires a single write to the configuration register
     * (0x00) followed by a single read of the configuration register
     * (0x01).  The datasheet provides the exact sequence.
     */
    if (i2c_write_byte(fd, 0x00) < 0)
        return -1;
    usleep(10000); /* 10 ms settle */

    uint8_t cfg[2] = {0x00, 0x01};
    if (i2c_write_byte(fd, (uint8_t)cfg[0]) < 0)
        return -1;
    if (i2c_write_byte(fd, (uint8_t)cfg[1]) < 0)
        return -1;

    /*
     * Wait for the sensor to become ready (data not ready).
     * The datasheet suggests a 10 ms wait after the write.
     */
    usleep(10000);

    return 0;
}

/* ------------------------------------------------------------------ */
/* SCD30 read                                                          */
/* ------------------------------------------------------------------ */
static int scd30_read(int fd, float *co2, float *temp, float *rh)
{
    uint8_t data[8];
    int16_t raw_co2, raw_temp, raw_rh;

    if (i2c_read_bytes(fd, data, sizeof(data)) < 0)
        return -1;

    /* CRC check */
    if (sensirion_crc8(data, 2) != data[2]) {
        fprintf(stderr, "CRC mismatch on CO2 data\n");
        return -1;
    }
    if (sensirion_crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "CRC mismatch on temperature data\n");
        return -1;
    }
    if (sensirion_crc8(data + 6, 2) != data[8]) {
        fprintf(stderr, "CRC mismatch on humidity data\n");
        return -1;
    }

    raw_co2 = (int16_t)((data[0] << 8) | data[1]);
    raw_temp = (int16_t)((data[3] << 8) | data[4]);
    raw_rh   = (int16_t)((data[6] << 8) | data[7]);

    *co2 = (float)raw_co2 / 100.0f;
    *temp = (float)raw_temp / 100.0f;
    *rh   = (float)raw_rh / 100.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float co2, float temp, float rh)
{
    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", ts, co2, temp, rh);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SCD30_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                SCD30_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (scd30_init(g_i2c_fd) < 0) {
        fprintf(stderr, "SCD30 initialization failed\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("SCD30 air quality monitor started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_INTERVAL);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        float co2 = 0.0f, temp = 0.0f, rh = 0.0f;

        if (scd30_read(g_i2c_fd, &co2, &temp, &rh) == 0) {
            log_data(g_log_fp, co2, temp, rh);
            printf("CO2: %.2f ppm, Temp: %.2f C, RH: %.2f %%\n",
                   co2, temp, rh);
        } else {
            fprintf(stderr, "Sensor read error; continuing...\n");
        }

        /* Sleep in 1 s increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

