/*
 * SDP810-125Pa differential pressure sensor reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   SDP810 SDA  -> GPIO2 (BCM)  -> I2C bus 1 SDA
 *   SDP810 SCL  -> GPIO3 (BCM)  -> I2C bus 1 SCL
 *   SDP810 VDD  -> 3.3 V
 *   SDP810 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp810_reader sdp810_reader.c
 * Run:    sudo ./sdp810_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP810_ADDR    0x50
#define READ_INTERVAL  1.0
#define CONVERSION_DELAY_MS  45
#define POLL_INTERVAL_S      1

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* CRC-8 as used by Sensirion: poly 0x31, init 0xFF, no final XOR */
static uint8_t sdp_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static int i2c_read_block(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C short read: got %zd of %zu\n", n, len);
        return -1;
    }
    return 0;
}

static int sdp_init(int fd)
{
    /* Verify sensor presence by reading the device ID */
    uint8_t id[3] = {0x00, 0x00, 0x00};
    if (i2c_read_block(fd, id, 3) != 0) {
        fprintf(stderr, "Sensor not responding at 0x%02X\n", SDP810_ADDR);
        return -1;
    }
    if (sdp_crc8(id, 2) != id[2]) {
        fprintf(stderr, "CRC mismatch on device ID\n");
        return -1;
    }

    /* Verify CRC on the first 8 bytes of the device ID */
    if (sdp_crc8(id, 0) != id[0]) {
        fprintf(stderr, "CRC mismatch on device ID\n");
        return -1;
    }
    if (sdp_crc8(id + 1, 1) != id[1]) {
        fprintf(stderr, "CRC mismatch on device ID\n");
        return -1;
    }

    /* Verify CRC on the remaining data */
    if (sdp_crc8(id + 2, 2) != id[3]) {
        fprintf(stderr, "CRC mismatch on device ID\n");
        return -1;
    }

    /* Configure: single-shot, continuous mode, default configuration */
    uint8_t cfg[3] = {0x00, 0x00, 0x00};
    if (i2c_read_block(fd, cfg, 3) != 0) {
        fprintf(stderr, "Failed to configure SDP810\n");
        return -1;
    }

    return 0;
}

static int sdp_read_raw(int fd, uint16_t *pressure, uint16_t *temperature)
{
    uint8_t data[9];
    if (i2c_read_block(fd, data, 9) != 0)
        return -1;

    /* Pressure: MSB first */
    *pressure = (uint16_t)((data[0] << 8) | data[1]);

    /* Temperature: MSB first */
    *temperature = (uint16_t)((data[2] << 8) | data[3]);

    /* Scale factors: MSB first */
    uint8_t sf_p = data[4];
    uint8_t sf_t = data[5];
    *pressure = (uint16_t)((sf_p << 8) | sf_t);

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SDP810_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                SDP810_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (sdp_init(fd) != 0) {
        fprintf(stderr, "SDP810 initialization failed\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("SDP810-125Pa reader started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t pressure, temperature;

        if (sdp_read_raw(fd, &pressure, &temperature) == 0) {
            printf("Pressure: %u Pa, Temperature: %u C\n",
                   pressure, temperature);
        } else {
            fprintf(stderr, "Read failed; continuing.\n");
        }

        sleep(POLL_INTERVAL_S);
    }

    printf("\nShutting down cleanly...\n");
    close(fd);
    return EXIT_SUCCESS;
}

