#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define HDC1000_ADDR   0x40
#define TEMP_REG       0x00
#define HUM_REG        0x01
#define DRDY_REG       0x02
#define CONV_DELAY_US  20000  /* 20 ms */
#define POLL_INTERVAL  5      /* seconds */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, out, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int hdc1000_init(int fd)
{
    /*
     * HDC1000 requires a write to the device address (0x40) followed by
     * a write to the device address + 0x01 (0x41) to set the conversion
     * rate.
     */
    if (i2c_write_byte(fd, HDC1000_ADDR, 0x41) < 0)
        return -1;
    return 0;
}

static int hdc1000_read_temp(int fd, float *temp_out)
{
    uint8_t raw[2];
    if (i2c_read_byte(fd, TEMP_REG, raw) < 0)
        return -1;
    *temp_out = (float)raw[0] / 16.0f;
    return 0;
}

static int hdc1000_read_hum(int fd, float *hum_out)
{
    uint8_t raw[2];
    if (i2c_read_byte(fd, HUM_REG, raw) < 0)
        return -1;
    *hum_out = (float)raw[0] / 16.0f;
    return 0;
}

static int hdc1000_read_drdy(int fd, uint8_t *drdy_out)
{
    uint8_t raw[1];
    if (i2c_read_byte(fd, DRDY_REG, raw) < 0)
        return -1;
    *drdy_out = raw[0];
    return 0;
}

static int log_data(float temp, float hum)
{
    printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, hum);
    fflush(stdout);
    return 0;
}

int main(void)
{
    int fd = -1;
    int ret = EXIT_FAILURE;

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Configure I2C slave address --- */
    if (ioctl(fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                HDC1000_ADDR, strerror(errno));
        goto cleanup;
    }

    /* --- Initialize sensor --- */
    if (hdc1000_init(fd) < 0) {
        fprintf(stderr, "HDC1000 initialization failed.\n");
        goto cleanup;
    }

    /* --- Main loop --- */
    while (g_running) {
        float temp, hum;

        if (hdc1000_read_temp(fd, &temp) < 0) {
            fprintf(stderr, "Temperature read failed; continuing.\n");
        } else if (hdc1000_read_hum(fd, &hum) < 0) {
            fprintf(stderr, "Humidity read failed; continuing.\n");
        } else {
            if (log_data(temp, hum) < 0)
                fprintf(stderr, "Logging failed.\n");
        }

        /*
         * DRDYn is not a true ACK; the sensor does not respond to
         * repeated read attempts. We rely on the fixed delay for
         * conversion.
         */
        usleep(CONV_DELAY_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);
    return ret;
}

