#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define SI7051_ADDR 0x48
#define READ_TEMP_CMD 0x01
#define READ_CONFIG_CMD 0x02
#define READ_CONFIG_RESPONSE_LEN 2
#define READ_TEMP_RESPONSE_LEN 2
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read short: got %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

static int read_si7051_config(int fd, uint16_t *config) {
    uint8_t buf[READ_CONFIG_RESPONSE_LEN];
    if (i2c_write_byte(fd, READ_CONFIG_CMD) < 0) return -1;
    usleep(10000);
    if (i2c_read_bytes(fd, buf, READ_CONFIG_RESPONSE_LEN) < 0) return -1;
    *config = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_si7051_temperature(int fd, float *temp_c) {
    uint8_t buf[READ_TEMP_RESPONSE_LEN];
    if (i2c_write_byte(fd, READ_TEMP_CMD) < 0) return -1;
    usleep(10000);
    if (i2c_read_bytes(fd, buf, READ_TEMP_RESPONSE_LEN) < 0) return -1;
    uint16_t raw = (buf[0] << 8) | buf[1];
    *temp_c = (float)raw / 100.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SI7051_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SI7051_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    uint16_t config;
    if (read_si7051_config(fd, &config) < 0) {
        fprintf(stderr, "Failed to read Si7051 configuration\n");
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        float temp;
        if (read_si7051_temperature(fd, &temp) < 0) {
            fprintf(stderr, "Failed to read temperature\n");
        } else {
            printf("Temperature: %.2f C\n", temp);
        }
        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");
    close(fd);
    return EXIT_SUCCESS;
}

