/*
 * MLX90833 Pressure Sensor Reader for Raspberry Pi 4 Model B
 *
 * Reads the absolute pressure from a Melexis MLX90833 sensor over I2C
 * bus 1 (GPIO2=SDA, GPIO3=SCL) and logs the pressure value to the console
 * every 500 ms.
 *
 * Build: gcc -O2 -Wall -o mlx90833_reader mlx90833_reader.c
 * Run:   sudo ./mlx90833_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX90833_ADDR  0x50
#define READ_INTERVAL  500   /* ms */
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/*
 * Read a 16-bit big-endian pressure value from the MLX90833.
 * Returns 0 on success, -1 on I2C error.
 */
static int read_mlx90833_pressure(int fd, uint16_t *pressure_out)
{
    uint8_t buf[2];
    ssize_t n;

    /*
     * MLX90833:
     *   Address  = 0x50
     *   Data     = [0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00]
     *   Pressure = [0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00]
     *
     * The sensor responds with a single byte of pressure data.
     */
    n = read(fd, buf, sizeof(buf));
    if (n != sizeof(buf)) {
        fprintf(stderr, "I2C read error: expected 2 bytes, got %zd\n", n);
        return -1;
    }

    *pressure_out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

int main(void)
{
    int fd = -1;
    uint16_t pressure;
    struct timespec ts;
    struct sigaction sa;
    char ts_str[32];

    /* --- Signal handling --- */
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MLX90833_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                MLX90833_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("MLX90833 reader started on %s (addr 0x%02X). Press Ctrl+C to exit.\n",
           I2C_BUS, MLX90833_ADDR);

    /* --- Main loop --- */
    while (g_running) {
        if (read_mlx90833_pressure(fd, &pressure) == 0) {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            ts_str[0] = (char)now.tv_sec;
            ts_str[1] = (char)(now.tv_nsec / 1000000);
            snprintf(ts_str + 2, sizeof(ts_str) - 2, "%09ld", now.tv_nsec);

            printf("[%s] Pressure: %u Pa\n", ts_str, pressure);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read pressure after %d retries.\n",
                    MAX_RETRIES);
        }

        /* Sleep in 100 ms increments so signals are caught promptly. */
        for (int i = 0; i < MAX_RETRIES && g_running; i++) {
            nanosleep(&(struct timespec){0, 100000}, NULL);
        }
    }

    /* --- Cleanup --- */
    if (fd >= 0) {
        close(fd);
    }
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

