/*
 * ICP-10101 barometric pressure sensor reader for Raspberry Pi Zero W.
 *
 * Wiring:
 *   ICP-10101 SDA -> GPIO2 (I2C bus 1 SDA)
 *   ICP-10101 SCL -> GPIO3 (I2C bus 1 SCL)
 *   ICP-10101 VDD -> 3.3 V
 *   ICP-10101 GND -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o icp10101_reader icp10101_reader.c
 *
 * Run:
 *   ./icp10101_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define ICP10101_ADDR  0x50
#define MEASURE_CMD    0x01
#define READ_CMD       0x02
#define READ_LEN       2
#define MEASURE_DELAY_US 10000   /* 10 ms */
#define LOOP_DELAY_US  5000000 /* 5 s */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Write a single byte to the ICP-10101.
 * Returns 0 on success, -1 on error.
 */
static int i2c_write_byte(int fd, uint8_t val)
{
    if (write(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read exactly `len` bytes from the ICP-10101.
 * Returns 0 on success, -1 on error.
 */
static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C short read: got %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

/*
 * Trigger a measurement and read the result.
 * Returns 0 on success, -1 on error.
 */
static int read_icp10101(int fd, float *temperature, float *pressure)
{
    uint8_t cmd = MEASURE_CMD;
    uint8_t data[READ_LEN];

    /* Trigger measurement */
    if (i2c_write_byte(fd, cmd) < 0)
        return -1;

    /* Wait for measurement to complete */
    usleep(MEASURE_DELAY_US);

    /* Read 2 bytes of data */
    if (i2c_read_bytes(fd, data, READ_LEN) < 0)
        return -1;

    /* Validate response: all bytes match the documented default */
    if (memcmp(data, &MEASURE_CMD, READ_LEN) != 0) {
        fprintf(stderr, "Sensor absent or data mismatch: "
                        "expected 0x%02X, got 0x%02X\n",
                        MEASURE_CMD, data[0]);
        return -1;
    }

    /* Parse raw data: T = (data[0] << 8) | data[1] */
    uint16_t raw_t = (uint16_t)((data[0] << 8) | data[1]);
    uint16_t raw_p = (uint16_t)((data[2] << 8) | data[3]);

    /* Convert to physical units */
    *temperature = (float)raw_t / 100.0f;
    *pressure    = (float)raw_p / 100.0f;

    return 0;
}

int main(void)
{
    int fd = -1;
    float temperature = 0.0f, pressure = 0.0f;
    int rc = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Open I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    /* Acquire I2C slave address */
    if (ioctl(fd, I2C_SLAVE, ICP10101_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                ICP10101_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Main loop */
    while (g_running) {
        if (read_icp10101(fd, &temperature, &pressure) == 0) {
            time_t now = time(NULL);
            struct tm tm_info;
            char ts[32];

            if (localtime_r(&now, &tm_info) != NULL) {
                strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);
                printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n",
                       ts, temperature, pressure);
            } else {
                printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n",
                       ts, temperature, pressure);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < LOOP_DELAY_US / 10000 && g_running; i++)
            usleep(10000);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return rc;
}

