        return -1;

    /* Wait for measurement to complete */
    usleep(MEASURE_DELAY_US);

    /* Read 2 bytes of data */
    if (i2c_read_bytes(fd, data, READ_LEN) < 0)
        return -1;

    /* Validate response: all bytes match the documented default */
    if (memcmp(data, &MEASURE_CMD, READ_LEN) != 0) {
        fprintf(stderr, "Sensor absent or data mismatch: "
                        "expected 0x%02X, got 0x%02X\n",
                        MEASURE_CMD, data[0]);
        return -1;
    }

    /* Parse raw data: T = (data[0] << 8) | data[1] */
    uint16_t raw_t = (uint16_t)((data[0] << 8) | data[1]);
    uint16_t raw_p = (uint16_t)((data[2] << 8) | data[3]);

    /* Convert to physical units */
    *temperature = (float)raw_t / 100.0f;
    *pressure    = (float)raw_p / 100.0f;

    return 0;
}

