    float temperature = 0.0f, pressure = 0.0f;
    int rc = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Open I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    /* Acquire I2C slave address */
    if (ioctl(fd, I2C_SLAVE, ICP10101_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                ICP10101_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Main loop */
    while (g_running) {
        if (read_icp10101(fd, &temperature, &pressure) == 0) {
            time_t now = time(NULL);
            struct tm tm_info;
            char ts[32];

            if (localtime_r(&now, &tm_info) != NULL) {
                strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);
                printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n",
                       ts, temperature, pressure);
            } else {
                printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n",
                       ts, temperature, pressure);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < LOOP_DELAY_US / 10000 && g_running; i++)
            usleep(10000);
    }

    rc = EXIT_SUCCESS;

