/*
 * Raspberry Pi 5 - MLX90819 Digital I2C Pressure Sensor Reader
 *
 * Reads pressure from the MLX90819 digital I2C sensor over I2C bus 1
 * at a 1-second interval. Handles I2C errors and exits cleanly on SIGINT/SIGTERM.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX90819_ADDR  0x5A
#define READ_INTERVAL  1
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_pressure(int fd, float *pressure)
{
    uint8_t raw[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_read_byte(fd, MLX90819_ADDR, raw) == 0) {
            break;
        }
        retries++;
        if (retries < MAX_RETRIES) {
            usleep(10000);
        }
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read pressure after %d retries.\n",
                MAX_RETRIES);
        return -1;
    }

    uint16_t raw_pressure = (raw[0] << 8) | raw[1];
    *pressure = (float)raw_pressure / 10.0f;
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MLX90819_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                MLX90819_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("MLX90819 pressure sensor reader started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float pressure;
        if (read_pressure(fd, &pressure) == 0) {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
            printf("%s - Pressure: %.2f Pa\n", timestamp, pressure);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read pressure after %d retries.\n",
                    READ_INTERVAL);
        }

        sleep(READ_INTERVAL);
    }

    printf("\nExiting gracefully...\n");
    close(fd);
    return EXIT_SUCCESS;
}

