/*
 * SDP800-500Pa differential pressure logger for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   SDP800 VCC  -> 3.3 V (pin 1)
 *   SDP800 GND  -> GND  (pin 9)
 *   SDP800 SDA  -> GPIO2 / I2C1 SDA (pin 3)
 *   SDP800 SCL  -> GPIO3 / I2C1 SCL (pin 5)
 *
 * Build:  gcc -O2 -Wall -Wextra -o airflow_logger airflow_logger.c
 * Run:    ./airflow_logger   (requires root or sudo)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP800_ADDR    0x5A
#define LOG_FILE       "airflow_log.csv"
#define TRIGGER_DELAY_US 10000   /* 10 ms */
#define POLL_INTERVAL_US  100000 /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* CRC-8 as used by Sensirion: polynomial 0x31, init 0xFF */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/*
 * Read a 3-byte measurement from the SDP800.
 * Returns 0 on success, -1 on I2C error.
 */
static int read_sdp800(int fd, uint16_t *pressure_raw)
{
    uint8_t buf[3];
    ssize_t n;

    /* Trigger a measurement */
    if (write(fd, &trigger_byte, 1) != 1) {
        fprintf(stderr, "I2C write trigger failed: %s\n", strerror(errno));
        return -1;
    }

    /* Wait for measurement to complete (~8 ms for 500 Pa) */
    usleep(TRIGGER_DELAY_US);

    /* Read 3 bytes: MSB, LSB, CRC */
    n = read(fd, buf, 3);
    if (n != 3) {
        fprintf(stderr, "I2C read failed: expected 3 bytes, got %zd: %s\n",
                n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    /* CRC check */
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on measurement data\n");
        return -1;
    }

    /* Convert to pressure (Pa) */
    *pressure_raw = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int log_data(const char *filename, float pressure)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char ts[64];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", ts, pressure) < 0) {
        fprintf(stderr, "fprintf to %s failed: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose on %s failed: %s\n", filename, strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the SDP800 sensor */
    if (ioctl(fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                SDP800_ADDR, strerror(errno));
        goto cleanup;
    }

    printf("SDP800-500Pa logger started. Logging to %s. Press Ctrl+C to stop.\n",
           LOG_FILE);

    while (g_running) {
        uint16_t pressure_raw;

        if (read_sdp800(fd, &pressure_raw) == 0) {
            float pressure = (float)pressure_raw / 100.0f;
            if (log_data(LOG_FILE, pressure) != 0) {
                fprintf(stderr, "Warning: failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Error reading pressure data.\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < 10 && g_running; i++)
            usleep(100000);
    }

    printf("\nShutting down cleanly...\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return rc;
}

