#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS          1
#define I2C_ADDR         0x01
#define LOG_FILE         "environmental_data.log"
#define MEASUREMENT_DELAY_US 5000000   /* 5 seconds */
#define TRIGGER_DELAY_US  40000        /* 40 ms */
#define MAX_LOG_SIZE      1048576       /* 1 MB */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int handle, unsigned char byte)
{
    int rc = i2cWriteByteData(handle, 0, byte);
    if (rc < 0) {
        fprintf(stderr, "i2cWriteByteData failed (handle %d, rc=%d)\n",
                handle, rc);
    }
    return rc;
}

static int i2c_read_bytes(int handle, char *buf, int len)
{
    int rc = i2cReadDevice(handle, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "i2cReadDevice failed (handle %d, rc=%d)\n",
                handle, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor helpers                                                      */
/* ------------------------------------------------------------------ */
static int read_sensor_data(int handle, float *temperature, float *humidity)
{
    char data[6];
    int rc;

    /* Trigger a measurement */
    rc = i2c_write_byte(handle, 0x01);
    if (rc < 0) {
        fprintf(stderr, "Failed to trigger measurement on handle %d\n", handle);
        return -1;
    }

    /* Wait for measurement to complete (datasheet: ~40 ms) */
    gpioDelay(TRIGGER_DELAY_US);

    /* Read 6 bytes: temperature, humidity, status, crc, crc, crc */
    rc = i2c_read_bytes(handle, data, 6);
    if (rc < 0) {
        fprintf(stderr, "Failed to read sensor data on handle %d\n", handle);
        return -1;
    }

    /* Validate status bits (bit 0 = measurement complete, bit 1 = data ready) */
    if ((data[0] & 0x01) == 0) {
        fprintf(stderr, "Sensor not ready on handle %d\n", handle);
        return -1;
    }

    /* Data is little-endian: temperature = (data[1] << 8) | data[2] */
    *temperature = (float)((data[1] << 8) | data[2]);

    /* Data is little-endian: humidity = (data[3] << 8) | data[4] */
    *humidity = (float)((data[3] << 8) | data[4]);

    /* Status bits: bit 0 = data ready, bit 1 = measurement complete */
    if ((data[5] & 0x01) == 0) {
        fprintf(stderr, "Sensor data not ready on handle %d\n", handle);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float temperature, float humidity)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n",
                timestamp, temperature, humidity) < 0) {
        fprintf(stderr, "fprintf() failed\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush() failed\n");
        return -1;
    }

    if (fseek(fp, 0, SEEK_END) != 0) {
        fprintf(stderr, "fseek() failed\n");
        return -1;
    }

    long file_size = ftell(fp);
    if (file_size == 0) {
        if (fprintf(fp, "Log file is empty\n") < 0) {
            fprintf(stderr, "fprintf() failed\n");
            return -1;
        }
    }

    if (fseek(fp, 0, SEEK_END) != 0) {
        fprintf(stderr, "fseek() failed\n");
        return -1;
    }

    if (file_size + 1 > MAX_LOG_SIZE) {
        if (fprintf(fp, "Log file exceeds 1 MB. Truncating.\n") < 0) {
            fprintf(stderr, "fprintf() failed\n");
            return -1;
        }
        fflush(fp);
        fseek(fp, 0, SEEK_END);
        long file_size_trunc = ftell(fp);
        if (file_size_trunc > MAX_LOG_SIZE) {
            fprintf(stderr, "Truncated file: %ld bytes\n", file_size_trunc);
            fprintf(fp, "Log file truncated to %ld bytes\n", MAX_LOG_SIZE);
            fflush(fp);
        }
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (handle %d, rc=%d)\n",
                g_i2c_handle, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Environmental sensor monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float temperature, humidity;

        if (read_sensor_data(g_i2c_handle, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);

            if (log_data(LOG_FILE, temperature, humidity) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < MEASUREMENT_DELAY_US / 1000000 && g_running; i++) {
            gpioDelay(1000000);
        }
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

