/*
 * Raspberry Pi 3 Model B+ – Melexis MLX90824 SENT pressure sensor reader
 *
 * Wiring:
 *   MLX90824 VCC  -> 3.3 V (pin 1)
 *   MLX90824 GND  -> GND  (pin 9)
 *   MLX90824 SOUT -> GPIO4 (BCM, pin 7)
 *   MLX90824 SIN  -> GPIO3 (BCM, pin 5)
 *   MLX90824 VDD  -> 3.3 V (pin 1)
 *   MLX90824 GND  -> GND  (pin 9)
 *
 * The SENT protocol uses a single wire (GPIO4) and a synchronization pulse
 * of 56 ticks.  The typical 3 µs tick time is used.
 *
 * Build:  gcc -O2 -Wall -Wextra -o mlx90824_reader mlx90824_reader.c
 * Run:    ./mlx90824_reader
 */

#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define SENSOR_PIN          4          /* BCM GPIO4 – SENT single-wire output */
#define LOG_FILE            "pressure_log.txt"
#define SAMPLE_PERIOD_US    100000     /* 100 ms – well within the ~3 µs tick time */
#define SYNC_TICKS          56         /* SENT sync pulse */
#define NIBBLE_MIN          12         /* 12 ticks – typical low-end nibble */
#define NIBBLE_MAX          271        /* 271 ticks – typical high-end nibble */
#define MAX_NIBBLES         3
#define MAX_PRESSURE_PA     1000.0f
#define SENSOR_ABSENT_THRESHOLD_US (SYNC_TICKS * 3) /* 56 ticks – >56 µs gap */

/* ----------------------------- Globals ---------------------------------- */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ----------------------------- Prototypes -------------------------------- */

static void signal_handler(int sig);
static int  read_sensor(int pin, float *pressure_pa);
static int  log_reading(float pressure_pa);
static int  detect_sensor_absent(void);
static int  detect_bus_error(void);

/* ----------------------------- Signal handler ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Read sensor -------------------------------- */

static int read_sensor(int pin, float *pressure_pa)
{
    uint32_t start_tick = gpioTick();
    uint32_t last_sync_tick = 0;
    uint32_t last_data_tick = 0;
    uint32_t last_nibble = 0;
    uint32_t last_nibble_state = 0;
    uint32_t last_pulse_width = 0;
    uint32_t pulse_width = 0;
    int nibbles = 0;
    int ret = -1;

    /*
     * SENT single-wire protocol:
     *   - Sync pulse (56 ticks)
     *   - Nibble 1: 12–271 ticks (36–813 µs)
     *   - Nibble 2: 12–271 ticks (36–813 µs)
     *   - Nibble 3: 12–271 ticks (36–813 µs)
     *   - Checksum: nibble 1 + nibble 2 + nibble 3
     */

    /*
     * Wait for the sync pulse.
     * gpioTick() returns the number of microseconds since boot;
     * we use the 32-bit tick value to avoid overflow.
     */
    while (gpioTick() - start_tick < SYNC_TICKS) {
        if (!g_running)
            return -1;
        gpioDelay(1);
    }

    last_sync_tick = gpioTick();

    /*
     * Read nibbles.
     * We use a simple loop that reads the pulse width of each tick
     * and increments the nibble counter when a valid nibble is found.
     */
    while (nibbles < MAX_NIBBLES) {
        /* Wait for the next tick */
        while (gpioTick() - last_sync_tick < SYNC_TICKS) {
            gpioDelay(1);
        }
        last_sync_tick = gpioTick();

        /* Read pulse width */
        pulse_width = gpioTick() - start_tick;

        /*
         * SENT nibble: 12–271 ticks (36–813 µs)
         * We use a simple loop that reads the pulse width of each tick
         * and increments the nibble counter when a valid nibble is found.
         */
        for (uint32_t i = 0; i < MAX_NIBBLES; i++) {
            if (pulse_width < NIBBLE_MIN || pulse_width > NIBBLE_MAX) {
                fprintf(stderr,
                        "Warning: pulse width %u ticks (tick %u) out of range "
                        "for nibble %u\n",
                        pulse_width, last_pulse_width, i);
                continue;
            }
            if (pulse_width >= NIBBLE_MIN && pulse_width <= NIBBLE_MAX) {
                if (last_nibble_state == 0) {
                    last_nibble = (uint8_t)pulse_width;
                    last_nibble_state = 1;
                } else if (last_nibble_state == 1) {
                    last_nibble |= (uint8_t)pulse_width;
                    last_nibble_state = 2;
                }
            } else {
                last_nibble_state = 0;
            }
        }

        /*
         * Checksum: nibble 1 + nibble 2 + nibble 3
         */
        uint8_t checksum = (uint8_t)(last_nibble + last_nibble_state);
        if (checksum != last_nibble_state) {
            fprintf(stderr,
                    "Warning: checksum mismatch (got 0x%02X, expected 0x%02X)\n",
                    checksum, last_nibble_state);
        }

        nibbles++;
        last_pulse_width = pulse_width;
    }

    ret = 0;
    if (nibbles == MAX_NIBBLES) {
        fprintf(stderr,
                "Error: no valid nibbles read – sensor absent or bus error\n");
    }
    return ret;
}

/* ----------------------------- Logging ----------------------------------- */

static int log_reading(float pressure_pa)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s, Pressure: %.2f Pa\n", ts, pressure_pa) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "Error: fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ----------------------------- Bus errors --------------------------------- */

static int detect_sensor_absent(void)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r failed: %s\n", strerror(errno));
        return 1;
    }

    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return 1;
    }

    fprintf(stderr,
            "Warning: SENT sensor absent (no sync pulse, "
            "%s, %d ticks wide – sensor absent or bus error)\n",
            ts, last_nibble);
    return 0;
}

static int detect_bus_error(void)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r failed: %s\n", strerror(errno));
        return 1;
    }

    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return 1;
    }

    fprintf(stderr,
            "Warning: SENT bus error (no sync pulse, "
            "%s, %d ticks wide – bus error or sensor absent)\n",
            ts, last_nibble);
    return 0;
}

/* ----------------------------- Main ------------------------------------- */

int main(void)
{
    int ret = EXIT_FAILURE;

    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open log file --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error: cannot open %s: %s\n",
                LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed: %s\n",
                strerror(errno));
    }

    /* --- main loop --- */
    while (g_running) {
        float pressure_pa;

        if (read_sensor(SENSOR_PIN, &pressure_pa) == 0) {
            if (log_reading(pressure_pa) == 0) {
                if (detect_sensor_absent()) {
                    fprintf(stderr, "Warning: SENT sensor absent – "
                            "bus error or sensor absent.\n");
                } else if (detect_bus_error()) {
                    fprintf(stderr, "Warning: SENT bus error – "
                            "sensor absent or bus error.\n");
                } else {
                    fprintf(stderr, "Warning: SENT pressure reading "
                            "out of range (%.2f Pa).\n", pressure_pa);
                }
            } else {
                fprintf(stderr, "Error: failed to log reading.\n");
            }
        } else {
            fprintf(stderr, "Error: failed to read sensor.\n");
        }

        /*
         * Sleep in 100 ms increments so signals are caught promptly.
         * gpioDelay() returns the number of microseconds used.
         */
        for (int i = 0; i < SAMPLE_PERIOD_US / 1000 && g_running; i++) {
            gpioDelay(1000);
        }
    }

    ret = EXIT_SUCCESS;
    fprintf(stderr, "\nShutting down cleanly.\n");
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
