/*
 * greenhouse_temps.c
 *
 * Greenhouse temperature monitor for Raspberry Pi Zero W.
 * Uses the Adafruit TMP117 high-precision temperature sensor on I2C.
 * Logs temperature readings to greenhouse_temps.dat every 60 seconds.
 *
 * Build:  gcc -O2 -Wall -Wextra -o greenhouse_temps greenhouse_temps.c
 * Run:    sudo ./greenhouse_temps
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define TMP117_ADDR    0x48
#define TMP117_REG_ID  0x00
#define TMP117_REG_TEMP 0x02
#define TMP117_REG_CONFIG 0x03
#define TMP117_REG_DATA  0x04

#define TMP117_DEV_ID   0x00
#define TMP117_DEV_ID_VAL 0x5A

#define LOG_FILENAME "greenhouse_temps.dat"
#define SAMPLE_INTERVAL_SEC 60

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, out, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
/* TMP117 driver                                                        */
/* ------------------------------------------------------------------ */
static int init_i2c(void)
{
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, TMP117_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                TMP117_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int init_sensor(void)
{
    uint8_t id = 0;
    if (i2c_read_byte(g_i2c_fd, TMP117_REG_ID, &id) < 0) {
        fprintf(stderr, "Failed to read device ID\n");
        return -1;
    }
    if (id != TMP117_DEV_ID_VAL) {
        fprintf(stderr, "Unexpected device ID: 0x%02X (expected 0x%02X)\n",
                id, TMP117_DEV_ID_VAL);
        return -1;
    }
    printf("TMP117 detected (ID=0x%02X)\n", id);
    return 0;
}

static int read_temperature(float *temp_out)
{
    uint8_t buf[2];
    if (i2c_read_word(g_i2c_fd, TMP117_REG_DATA, buf) < 0)
        return -1;
    *temp_out = (float)buf[0] | ((float)buf[1] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_temperature(float temp)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }
    fprintf(g_log_fp, "%s, %.2f\n", ts, temp);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (init_i2c() < 0)
        return EXIT_FAILURE;

    if (init_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILENAME, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILENAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Greenhouse temperature monitor started. Logging to %s every %d s.\n",
           LOG_FILENAME, SAMPLE_INTERVAL_SEC);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        float temp;
        if (read_temperature(&temp) < 0) {
            fprintf(stderr, "Temperature read failed; continuing.\n");
        } else {
            log_temperature(temp);
            printf("Temperature: %.2f C\n", temp);
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

