/*
 * Raspberry Pi Zero W - SHT40 Temperature & Humidity Logger
 *
 * Reads temperature and humidity from an Adafruit SHT40 sensor on I2C bus 1
 * (GPIO2 = SDA, GPIO3 = SCL) and logs the data to environmental_data.txt every 5
 * seconds.  The SHT40 requires a conversion delay of at least 8.5 ms after each
 * command; this program waits for the conversion to complete before reading
 * again.
 *
 * Build:  gcc -O2 -Wall -o sht40_logger sht40_logger.c
 * Run:    sudo ./sht40_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SHT40_ADDR     0x44
#define LOG_FILE       "environmental_data.txt"
#define SAMPLE_INTERVAL 5
#define CONV_DELAY_MS  8
#define MAX_RETRIES    3

/* SHT40 command byte sequence (datasheet, page 7) */
static const uint8_t CMD_TEMP[2] = {0x00, 0x04};
static const uint8_t CMD_HUMID[2] = {0x00, 0x08};

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                         */
/* ------------------------------------------------------------------ */
static uint8_t sht40_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, const uint8_t *cmd, size_t len)
{
    if (write(fd, cmd, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* SHT40 initialization                                                */
/* ------------------------------------------------------------------ */
static int sht40_init(int fd)
{
    if (i2c_write_cmd(fd, CMD_TEMP, 2) != 0)
        return -1;
    usleep(CONV_DELAY_MS * 1000);

    if (i2c_write_cmd(fd, CMD_HUMID, 2) != 0)
        return -1;
    usleep(CONV_DELAY_MS * 1000);

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one temperature and humidity sample                             */
/* ------------------------------------------------------------------ */
static int sht40_read(int fd, float *temp, float *hum)
{
    uint8_t buf[6];

    if (i2c_read_bytes(fd, buf, sizeof(buf)) != 0)
        return -1;

    if (sht40_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (sht40_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t raw_temp = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t raw_hum  = ((uint16_t)buf[3] << 8) | buf[4];

    *temp = (float)raw_temp / 10.0f;
    *hum  = (float)raw_hum / 10.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float temp, float hum)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }

    if (fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, temp, hum) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SHT40_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                SHT40_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (sht40_init(g_i2c_fd) != 0) {
        fprintf(stderr, "SHT40 initialization failed\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    fprintf(stderr, "Logging to %s every %d s. Press Ctrl+C to stop.\n",
            LOG_FILE, SAMPLE_INTERVAL);

    while (g_running) {
        float temp, hum;
        if (sht40_read(g_i2c_fd, &temp, &hum) == 0) {
            if (log_data(g_log_fp, temp, hum) != 0)
                fprintf(stderr, "Logging failed\n");
        } else {
            fprintf(stderr, "Sensor read failed; continuing\n");
        }
        sleep(SAMPLE_INTERVAL);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

