#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define TEMP_REG 0x00
#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;
static int buffer_index = 0;
static int buffer_size = 0;

typedef struct {
    float temperature;
    time_t timestamp;
} TemperatureData;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_temperature(float *temperature) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: expected 2 bytes, got %d\n", result);
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | (uint8_t)buf[1];
    *temperature = (float)raw / 16.0f;
    return 0;
}

static void add_to_buffer(float temperature) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error getting current time: %s\n", strerror(errno));
        return;
    }
    struct tm *tm_info = localtime(&now);
    if (tm_info == NULL) {
        fprintf(stderr, "Error converting time: %s\n", strerror(errno));
        return;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return;
    }
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    buffer_size++;
    if (buffer_size > BUFFER_SIZE) {
        buffer_size = BUFFER_SIZE;
    }
    buffer[buffer_index].temperature = temperature;
    buffer[buffer_index].timestamp = now;
    fflush(log_file);
}

static void log_data(float temperature) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error getting current time: %s\n", strerror(errno));
        return;
    }
    struct tm *tm_info = localtime(&now);
    if (tm_info == NULL) {
        fprintf(stderr, "Error converting time: %s\n", strerror(errno));
        return;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return;
    }
    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen("temperature_log.dat", "wb");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Temperature logging started. Press Ctrl+C to stop.\n");

    while (running) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            add_to_buffer(temperature);
            log_data(temperature);
            printf("Temperature: %.2f C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature, skipping sample.\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

