#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SHTC3_ADDR     0x44
#define LOG_FILE       "shtc3_environment.log"
#define SAMPLE_INTERVAL_S 5
#define CONV_DELAY_MS   12

/* SHTC3 command byte: 0x01 (start conversion) */
#define CMD_START_CONV   0x01

/* SHTC3 register addresses */
#define REG_TEMP_MSB     0x00
#define REG_TEMP_LSB     0x01
#define REG_HUM_MSB      0x02
#define REG_HUM_LSB      0x03
#define REG_CONFIG       0x0F
#define REG_MEAS_CONFIG  0x10

/* SHTC3 measurement configuration */
#define CONFIG_TEMP_HUM_ON  0x01
#define CONFIG_TEMP_HUM_OFF 0x00
#define CONFIG_TEMP_HUM_AUTO 0x02

/* SHTC3 CRC-8 polynomial: x^8 + x^5 + x^4 + 1 (0x31) */
static const uint8_t shtc3_crc8[8] = {
    0x31, 0x28, 0x25, 0x1C, 0x1B, 0x18, 0x15, 0x12
};

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a single byte to an SHTC3 register */
static int shtc3_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a single byte from an SHTC3 register */
static int shtc3_read_reg(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit little-endian big-endian (SHTC3) */
static int shtc3_read_word(int fd, uint8_t reg_msb, uint16_t *out)
{
    uint8_t buf[2];
    if (write(fd, &reg_msb, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg_msb, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
