    return 0;
}

/* CRC-8 calculation for SHTC3 (polynomial 0x31, init 0x00) */
static uint8_t shtc3_crc8_calc(const uint8_t *data, size_t len)
{
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ shtc3_crc8[b]);
            else
                crc = (uint8_t)(crc << 1);
        }
