        shtc3_crc8_calc(&h_msb, 2) != h_msb ||
        shtc3_crc8_calc(&h_lsb, 2) != h_lsb) {
        fprintf(stderr, "CRC check failed for SHTC3 data\n");
        return -1;
    }

