    *temperature = (float)t_msb * 0.01f + (float)t_lsb * 0.01f;
    *humidity    = (float)h_msb * 0.01f + (float)h_lsb * 0.01f;

    return 0;
}

/* Log a valid reading to the file */
static void log_reading(FILE *fp, float temperature, float humidity)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
