    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the I2C slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, SHTC3_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus access: %s\n", strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Initialize SHTC3: start conversion, auto-configure */
    if (shtc3_write_reg(g_i2c_fd, REG_MEAS_CONFIG, CONFIG_TEMP_HUM_AUTO) < 0) {
        fprintf(stderr, "Failed to initialize SHTC3: %s\n", strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("SHTC3 logger started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_INTERVAL_S);

    /* Main sampling loop */
    while (g_running) {
        float temperature, humidity;

        if (shtc3_read_shtc3(g_i2c_fd, &temperature, &humidity) == 0) {
            log_reading(g_log_file, temperature, humidity);
        } else {
