/*
 * TMP117 Temperature Logger for Raspberry Pi 3 Model B+
 * Uses pigpio for I2C communication.
 *
 * Wiring:
 *   TMP117 SDA -> GPIO2 (I2C1 SDA)
 *   TMP117 SCL -> GPIO3 (I2C1 SCL)
 *   TMP117 VDD -> 3.3 V
 *   TMP117 GND -> GND
 *
 * Build: gcc -Wall -o tmp117_logger tmp117_logger.c -lpigpio -lrt
 * Run:   sudo ./tmp117_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define LOG_FILE       "temperature_log.txt"
#define MAX_RETRIES    3
#define SAMPLE_PERIOD  1.0  /* seconds */

/* TMP117 register addresses */
#define TMP117_REG_TEMP_MSB 0x00
#define TMP117_REG_TEMP_LSB 0x01
#define TMP117_REG_CONFIG   0x02
#define TMP117_REG_INT_CFG  0x03
#define TMP117_REG_INT_STATUS 0x04
#define TMP117_REG_INT_CLEAR 0x05

#define TMP117_INT_CLEAR_BIT 0x01
#define TMP117_INT_CLEAR_ALL 0xFF

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int handle, uint8_t reg, uint8_t value)
{
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int handle, uint8_t reg, uint8_t *out)
{
    if (i2cWriteDevice(handle, (char *)&reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed\n", reg);
        return -1;
    }
    char buf[1];
    if (i2cReadDevice(handle, buf, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed\n", reg);
        return -1;
    }
    *out = (uint8_t)buf[0];
    return 0;
}

static int i2c_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];
    if (i2cWriteDevice(handle, (char *)&reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed\n", reg);
        return -1;
    }
    *out = (uint16_t)((uint8_t)buf[0] | ((uint8_t)buf[1] << 8));
    return 0;
}

/* ------------------------------------------------------------------ */
/* TMP117 initialization                                               */
/* ------------------------------------------------------------------ */
static int init_i2c(void)
{
    int retries = 0;
    int handle = -1;

    while (retries < MAX_RETRIES) {
        handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
        if (handle >= 0) {
            /* Clear any pending interrupts */
            if (i2c_write_reg8(handle, TMP117_REG_INT_CLEAR, TMP117_INT_CLEAR_ALL) != 0) {
                fprintf(stderr, "Failed to clear interrupts on handle %d\n", handle);
                i2cClose(handle);
                handle = -1;
                retries++;
                continue;
            }
            return handle;
        }
        fprintf(stderr, "I2C open failed (attempt %d/%d): %s\n",
                retries + 1, MAX_RETRIES, pigpio_error(handle));
        retries++;
        gpioDelay(100000); /* 100 ms backoff */
    }
    fprintf(stderr, "Failed to open I2C bus after %d attempts\n", MAX_RETRIES);
    return -1;
}

static int init_sensor(int handle)
