/*
 * Raspberry Pi Zero W - Honeywell HAF Series HAFUHH0025PA3 Flow Sensor Reader
 *
 * Reads flow (14-bit) and temperature (12-bit) from a Honeywell HAFUHH0025PA3
 * over I2C bus 1, logs to flow_log.txt, and handles SIGINT/SIGTERM for
 * graceful shutdown.
 *
 * Build: gcc -O2 -Wall -o flow_reader flow_reader.c -lpigpio -lrt
 * Run:   sudo ./flow_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS          1
#define I2C_ADDR         0x25
#define LOG_FILE         "flow_log.txt"
#define SAMPLE_INTERVAL  1          /* seconds between readings */
#define MAX_RETRIES      3
#define MAX_RETRIES_WAIT 1          /* seconds between retries */

/*
 * HAFUHH0025PA3 API call:
 *   Read 4 bytes starting at 0x00.
 *   Byte 0: 14-bit flow (bits [15:8] of a 16-bit value)
 *   Byte 1: 12-bit temperature (bits [7:4] of a 16-bit value)
 *   Byte 2: reserved (always 0)
 *   Byte 3: reserved (always 0)
 *   Byte 4: reserved (always 0)
 *
 * The sensor returns the first two reads after power-up; the
 * datasheet does not guarantee a valid first read.
 */
#define API_READ_SIZE   4

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_read_block(int handle, uint8_t *buf, int len)
{
    int rc = i2cReadDevice(handle, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C read failed: expected %d bytes, got %d\n",
                len, rc);
        return -1;
    }
    return 0;
}

static int i2c_write_byte(int handle, uint8_t val)
{
    int rc = i2cWriteDevice(handle, (char *)&val, 1);
    if (rc != 1) {
        fprintf(stderr, "I2C write failed: %d\n", rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor API                                                          */
/* ------------------------------------------------------------------ */
static int sensor_init(void)
{
    /*
     * The HAFUHH0025PA3 has a built-in power-on self-test.
     * After a power-up, the first two reads are stale.
     * A warm-up period is recommended before reading flow.
     */
    if (i2c_write_byte(g_i2c_handle, 0x00) != 0) {
        fprintf(stderr, "Sensor not responding on I2C bus %d\n", I2C_BUS);
        return -1;
    }
    gpioDelay(100000); /* 100 ms */

    /*
     * Read the first two power-up readings.
     * The datasheet does not guarantee a valid first read.
     */
    uint8_t buf[API_READ_SIZE];
    if (i2c_read_block(g_i2c_handle, buf, API_READ_SIZE) != 0) {
        fprintf(stderr, "Sensor not responding after power-up\n");
        return -1;
    }

    /*
     * The sensor returns the first two reads after power-up.
     * The datasheet does not guarantee a valid first read.
     */
    if (i2c_read_block(g_i2c_handle, buf, API_READ_SIZE) != 0) {
        fprintf(stderr, "Sensor not responding after power-up\n");
        return -1;
    }

    /*
     * Read 14-bit flow value.
     */
    if (i2c_read_block(g_i2c_handle, buf, API_READ_SIZE) != 0) {
        fprintf(stderr, "Sensor not responding after power-up\n");
        return -1;
    }
    uint16_t flow_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t flow_14bit = (flow_raw >> 8) & 0x0FFF;

    /*
     * Read 12-bit temperature value.
     */
    if (i2c_read_block(g_i2c_handle, buf, API_READ_SIZE) != 0) {
        fprintf(stderr, "Sensor not responding after power-up\n");
        return -1;
    }
    uint16_t temp_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t temp_12bit = (temp_raw >> 4) & 0x0FFF;

    /*
     * Combine 14-bit flow and 12-bit temperature into a single 16-bit value.
     */
    uint16_t combined = (flow_14bit << 8) | temp_12bit;
    g_i2c_handle = -1;
    return 0;
}

static int sensor_read(uint16_t *flow, uint16_t *temp)
{
    uint8_t buf[API_READ_SIZE];
    if (i2c_read_block(g_i2c_handle, buf, API_READ_SIZE) != 0) {
        return -1;
    }

    /*
     * The sensor returns the first two reads after power-up.
     * The datasheet does not guarantee a valid first read.
     */
    if (i2c_read_block(g_i2c_handle, buf, API_READ_SIZE) != 0) {
        return -1;
    }

    /*
     * 14-bit flow value.
     */
    uint16_t flow_raw = ((uint16_t)buf[0] << 8) | buf[1];
    *flow = (uint16_t)flow_raw;

    /*
     * 12-bit temperature value.
     */
    uint16_t temp_raw = ((uint16_t)buf[2] << 4) | buf[3];
    *temp = (uint16_t)temp_raw;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(uint16_t flow, uint16_t temp)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(g_log_file, "%s, Flow: %u SLPM, Temperature: %u °C\n",
                timestamp, flow, temp) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(g_log_file);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (sensor_init() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': ", LOG_FILE);
        perror("");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "Timestamp,Flow (SLPM),Temperature (°C)\n");
        fflush(g_log_file);
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Main loop */
    while (g_running) {
        uint16_t flow, temp;

        if (sensor_read(&flow, &temp) == 0) {
            if (log_data(flow, temp) != 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed; continuing\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    /* Graceful shutdown */
    cleanup();
    return EXIT_SUCCESS;
}

