#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <errno.h>

#define I2C_BUS        "/dev/i2c-1"
#define SHT31D_ADDR    0x44
#define LOG_FILE       "sht31d_data.log"
#define SAMPLE_INTERVAL 5
#define MAX_RETRIES     3

/* SHT31-D command: start measurement, then read 6 bytes */
#define SHT31D_CMD_START_MEASUREMENT 0x01
#define SHT31D_CMD_STOP_MEASUREMENT  0x02
#define SHT31D_CMD_READ_HUMIDITY     0x03
#define SHT31D_CMD_READ_TEMPERATURE  0x04

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* CRC-8 as used by the SHT31-D: poly 0x31, init 0xFF */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd)
{
    uint8_t buf[2] = { cmd, 0x00 };
    ssize_t n = write(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "I2C read: unexpected EOF (expected %zu bytes)\n", len);
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

static int sht31d_init(int fd)
{
    if (i2c_write_cmd(fd, SHT31D_CMD_START_MEASUREMENT) < 0)
        return -1;
    usleep(10000); /* 10 ms settling time */

    uint8_t cmd = SHT31D_CMD_READ_HUMIDITY;
    if (i2c_write_cmd(fd, cmd) < 0)
        return -1;
    usleep(10000); /* 10 ms conversion time */

    uint8_t cmd_stop = SHT31D_CMD_STOP_MEASUREMENT;
    if (i2c_write_cmd(fd, cmd_stop) < 0)
        return -1;
    usleep(10000); /* 10 ms conversion time */

    return 0;
}

static int sht31d_read(int fd, float *temperature, float *humidity)
{
    uint8_t buf[6];
    if (i2c_read_bytes(fd, buf, sizeof(buf)) < 0)
        return -1;

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t raw_humidity = ((uint16_t)buf[3] << 8) | buf[4];
    uint16_t raw_temp = ((uint16_t)buf[0] << 8) | buf[1];

    *humidity = (float)raw_humidity / 10.0f;
    *temperature = (float)raw_temp / 10.0f;
    return 0;
}

static int log_data(FILE *fp, float temperature, float humidity)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, temperature, humidity) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SHT31D_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                SHT31D_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (sht31d_init(g_i2c_fd) < 0) {
        fprintf(stderr, "SHT31-D initialization failed\n");
        cleanup();
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    fprintf(stderr, "SHT31-D logging started. Logging to %s every %d s.\n",
            LOG_FILE, SAMPLE_INTERVAL);

    while (g_running) {
        float temperature, humidity;

        if (sht31d_read(g_i2c_fd, &temperature, &humidity) == 0) {
            if (log_data(g_log_fp, temperature, humidity) < 0) {
                fprintf(stderr, "Logging failed; continuing...\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed; continuing...\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

    fprintf(stderr, "\nShutting down...\n");
    cleanup();
    return 0;
}

