        if (sht31d_read(g_i2c_fd, &temperature, &humidity) == 0) {
            if (log_data(g_log_fp, temperature, humidity) < 0) {
                fprintf(stderr, "Logging failed; continuing...\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed; continuing...\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

    fprintf(stderr, "\nShutting down...\n");
    cleanup();
    return 0;
}

