/*
 * Raspberry Pi 4 Model B - MLX90824 Absolute Pressure Sensor Reader
 *
 * Reads the absolute pressure and temperature from a Melexis MLX90824
 * absolute pressure sensor over I2C, and logs the readings to
 * pressure_log.txt every 2 seconds.
 *
 * Build:  gcc -O2 -Wall -o mlx90824_reader mlx90824_reader.c
 * Run:    ./mlx90824_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX90824_ADDR  0x5A
#define LOG_FILE       "pressure_log.txt"
#define READ_INTERVAL  2
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a 16-bit big-endian word from the MLX90824.
 * Returns 0 on success, -1 on error.
 */
static int read_mlx90824(int fd, uint16_t *out)
{
    uint8_t buf[2];

    /*
     * MLX90824:
     *   Address  = 0x5A
     *   Data     = [MSB, LSB]
     *   Reserved  = [bit 15, bit 14]
     *   Reserved  = [bit 13, bit 12]
     *   Reserved  = [bit 11, bit 10]
     *   Reserved  = [bit 9, bit 8]
     *   Reserved  = [bit 7, bit 6]
     *   Reserved  = [bit 5, bit 4]
     *   Reserved  = [bit 3, bit 2]
     *   Reserved  = [bit 1, bit 0]
     *   Data     = [MSB, LSB]
     */
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }

    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int log_data(FILE *fp, const char *timestamp,
                    float pressure, float temperature)
{
    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    int fd = -1;
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    /* --- Initialize MLX90824 --- */
    if (read_mlx90824(fd, &(uint16_t){0x00, 0x00}) != 0) {
        fprintf(stderr, "MLX90824 not detected on %s\n", I2C_BUS);
        goto cleanup;
    }

    /* --- Main loop --- */
    while (g_running) {
        char ts[32];
        time_t now = time(NULL);
        struct tm tm_info;

        if (localtime_r(&now, &tm_info) == NULL) {
            fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
            goto cleanup;
        }

        if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
            fprintf(stderr, "strftime failed\n");
            goto cleanup;
        }

        float pressure = 0.0f;
        float temperature = 0.0f;

        if (read_mlx90824(fd, &(uint16_t){0x00, 0x00}) == 0) {
            pressure = (float)((uint16_t)buf[0] << 8) | (uint16_t)buf[1];
        }

        if (log_data(fp, ts, pressure, temperature) != 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        /* Sleep in 1-second increments so signals are caught promptly. */
        for (int i = 0; i < READ_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fp) {
        fclose(fp);
    }
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

