    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n",
                LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    } else {
        fprintf(fp, "[unknown time] %s\n", msg);
    }
    fclose(fp);
}

/* ---- Signal handling ---- */

static void signal_handler(int sig) {
    (void)sig;
    fan_stop_all(FAN_GPIO_LINE);
    exit(0);
}

/* ---- Main ---- */

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LM75B_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                LM75B_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Open GPIO chip and request fan line as output */
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    FAN_GPIO_LINE = gpiod_chip_get_line_by_number(chip, FAN_GPIO_LINE);
    if (!FAN_GPIO_LINE) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                FAN_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(FAN_GPIO_LINE, "lm75b_fan", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO %d as output: %s\n",
                FAN_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Initialize circular buffer */
    buffer_init(&temp_buffer);

    printf("LM75B fan monitoring started. Press Ctrl+C to exit.\n");

    while (1) {
        int reg = i2c_read_byte(i2c_fd, LM75B_ADDR);
        if (reg < 0) {
            log_message("I2C read failed");
            sleep(SAMPLE_PERIOD);
            continue;
        }

        int raw = i2c_read_word(i2c_fd, reg);
        if (raw < 0) {
            log_message("I2C read word failed");
            sleep(SAMPLE_PERIOD);
            continue;
        }

        float temp = raw / 100.0f;

        buffer_add(&temp_buffer, temp);
        float avg = buffer_average(&temp_buffer);

        printf("LM75B: raw=0x%04X, temp=%.2f C, avg=%.2f C\n",
               raw, temp, avg);

        int fan_on = (avg > TEMP_THRESHOLD) ? 1 : 0;
        fan_set_speed(FAN_GPIO_LINE, fan_on ? FAN_MAX_TEMP : FAN_MIN_TEMP);

        if (fan_on) {
            printf("Fan ON (avg %.2f C)\n", avg);
        } else {
            printf("Fan OFF (avg %.2f C)\n", avg);
        }

        sleep(SAMPLE_PERIOD);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    fan_stop_all(FAN_GPIO_LINE);
    gpiod_line_release(FAN_GPIO_LINE);
    gpiod_chip_close(chip);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

