/*
 * SDP810-500Pa differential pressure logger for Raspberry Pi Zero W.
 *
 * Wiring:
 *   SDP810 VCC  -> 3.3 V (Pin 1)
 *   SDP810 GND  -> GND  (Pin 9)
 *   SDP810 SDA  -> GPIO2 / I2C1 SDA (Pin 3)
 *   SDP810 SCL  -> GPIO3 / I2C1 SCL (Pin 5)
 *
 * Build:  gcc -O2 -Wall -Wextra -o airflow airflow.c
 * Run:    ./airflow
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP810_ADDR    0x50
#define LOG_FILE       "airflow.log"
#define PRESSURE_THRESHOLD 5.0f
#define SAMPLE_INTERVAL_S 1
#define MEAS_DELAY_US   45000   /* 45 ms after first measurement */

/* CRC-8 polynomial 0x31 (Sensirion: 0x31, init 0xFF) */
static const uint8_t sdp_crc8[8] = {
    0x31, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
};

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion: poly 0x31, init 0xFF, no final XOR)                */
/* ------------------------------------------------------------------ */
static uint8_t sdp_crc8_calc(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ sdp_crc8[b] : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor helpers                                                      */
/* ------------------------------------------------------------------ */
static int sdp_init(int fd)
{
    if (i2c_write_cmd(fd, 0x01) < 0)
        return -1;   /* sensor not present */
    usleep(10000);   /* 10 ms settle */

    /* Issue measurement command */
    if (i2c_write_cmd(fd, 0x00) < 0)
        return -1;

    usleep(MEAS_DELAY_US);
    return 0;
}

static int sdp_read_raw(int fd, uint8_t *buf, size_t len)
{
    if (i2c_read_bytes(fd, buf, len) < 0)
        return -1;
    return 0;
}

static int sdp_read_pressure(int fd, float *pressure_pa)
{
    uint8_t buf[9];
    if (sdp_read_raw(fd, buf, sizeof(buf)) < 0)
        return -1;

    /* Validate CRC for each byte */
    for (size_t i = 0; i < 8; i++) {
        if (sdp_crc8(&buf[i], 2) != buf[i]) {
            fprintf(stderr, "CRC mismatch on pressure byte %zu\n", i);
            return -1;
        }
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *pressure_pa = (float)raw / 100.0f;
    return 0;
}

static int sdp_read_temperature(int fd, float *temperature_c)
{
    uint8_t buf[2];
    if (sdp_read_raw(fd, buf, 2) < 0)
        return -1;

    /* Validate CRC for each byte */
    for (size_t i = 0; i < 2; i++) {
        if (sdp_crc8(&buf[i], 2) != buf[i]) {
            fprintf(stderr, "CRC mismatch on temperature byte %zu\n", i);
            return -1;
        }
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *temperature_c = (float)raw / 100.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float pressure, float temperature)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "1970-01-01 00:00:00");

    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SDP810_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                SDP810_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (sdp_init(g_i2c_fd) < 0) {
        fprintf(stderr, "SDP810 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(stderr, "SDP810 logger started. Logging to %s every %d s.\n",
            LOG_FILE, SAMPLE_INTERVAL_S);

    while (g_running) {
        float pressure = 0.0f;
        float temperature = 0.0f;

        if (sdp_read_pressure(g_i2c_fd, &pressure) < 0) {
            fprintf(stderr, "Pressure read failed; continuing.\n");
        } else if (sdp_read_temperature(g_i2c_fd, &temperature) < 0) {
            fprintf(stderr, "Temperature read failed; continuing.\n");
        } else {
            if (pressure > PRESSURE_THRESHOLD) {
                fprintf(stderr, "Pressure exceeds threshold: %.2f Pa\n",
                        pressure);
            }
            if (log_data(g_log_fp, pressure, temperature) < 0)
                fprintf(stderr, "Logging failed; continuing.\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++)
            usleep(100000);
    }

    fprintf(stderr, "\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

