/*
 * Raspberry Pi 4 Model B - Sensirion SDP800-500Pa Differential Pressure & Temperature Logger
 *
 * Reads differential pressure and temperature from a Sensirion SDP800-500Pa sensor
 * over I2C bus 1, waits at least 45 ms after initiating a measurement, and logs
 * the data to flow_data.txt.  Handles I2C errors and the sensor-absent condition.
 *
 * Build:  gcc -O2 -Wall -o flow_logger flow_logger.c
 * Run:    sudo ./flow_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP800_ADDR    0x50
#define MEASURE_DELAY_MS 50
#define LOG_FILE       "flow_data.txt"

/* SDP800-500Pa register addresses */
#define REG_CONFIG        0x00
#define REG_MEAS_CONFIG   0x01
#define REG_MEAS_DATA     0x02
#define REG_SCALE_FACTOR  0x03
#define REG_CRC_POLY      0x00
#define REG_CRC_INIT      0x00

#define CRC8_POLY        0x31
#define CRC8_INIT        0xFF

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion: poly 0x31, init 0xFF)                             */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ CRC8_POLY);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* SDP800-500Pa initialization                                         */
/* ------------------------------------------------------------------ */
static int sdp800_init(int fd)
{
    /*
     * SDP800-500Pa requires a measurement configuration.
     * The following sequence sets the measurement configuration
     * register (REG_MEAS_CONFIG) to 0x00 (no measurement) and
     * the measurement register (REG_MEAS_DATA) to 0x00 (no data).
     */
    if (i2c_write_reg(fd, REG_MEAS_CONFIG, 0x00) < 0)
        return -1;
    if (i2c_write_reg(fd, REG_MEAS_DATA, 0x00) < 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read differential pressure and temperature                         */
/* ------------------------------------------------------------------ */
static int sdp800_read(int fd, float *pressure, float *temperature)
{
    uint8_t data[9];
    uint8_t crc;

    /*
     * SDP800-500Pa requires a measurement configuration before a
     * measurement can be triggered.  The following sequence
     * sets the measurement configuration register (REG_MEAS_CONFIG)
     * to 0x00 (no measurement) and the measurement register (REG_MEAS_DATA)
     * to 0x00 (no data).
     */
    if (i2c_write_reg(fd, REG_MEAS_CONFIG, 0x00) < 0)
        return -1;
    if (i2c_write_reg(fd, REG_MEAS_DATA, 0x00) < 0)
        return -1;

    /*
     * Wait for the measurement to complete.
     * SDP800-500Pa takes ~50 ms for a full measurement.
     */
    usleep(MEASURE_DELAY_MS * 1000);

    /*
     * Read 9 bytes: 2 bytes of differential pressure, 2 bytes of
     * temperature, and 3 bytes of scale factor.
     */
    if (i2c_read_block(fd, REG_MEAS_DATA, data, sizeof(data)) < 0)
        return -1;

    /*
     * Validate the CRC for each byte of the measurement data.
     */
    for (int i = 0; i < 6; i++) {
        crc = crc8(&data[i * 2], 2);
        if (crc != data[i * 2 + 2]) {
            fprintf(stderr, "CRC mismatch at byte %d\n", i);
            return -1;
        }
    }

    /*
     * Scale factor is stored in the last 3 bytes of the measurement data.
     */
    *pressure = (float)data[0] * 0.5f + (float)data[1] * 0.5f;
    *temperature = (float)data[3] * 0.5f + (float)data[4] * 0.5f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float pressure, float temperature)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (fprintf(fp, "%s, %.2f, %.2f\n", ts, pressure, temperature) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_i2c_fd >= 0) {
        g_i2c_fd = -1;
    }
    if (g_i2c_fd >= 0) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SDP800_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (sdp800_init(g_i2c_fd) < 0) {
        fprintf(stderr, "SDP800-500Pa initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(g_log_fp, "# SDP800-500Pa flow data\n");
    fflush(g_log_fp);

    printf("SDP800-500Pa logger started. Logging to %s. Press Ctrl+C to stop.\n",
           LOG_FILE);

    while (g_running) {
        float pressure, temperature;

        if (sdp800_read(g_i2c_fd, &pressure, &temperature) == 0) {
            if (log_data(g_log_fp, pressure, temperature) < 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }

        /*
         * Sleep in 100 ms increments so signals are caught promptly.
         */
        for (int i = 0; i < 50 && g_running; i++)
            usleep(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

