 * Raspberry Pi Zero W – STS40 I2C Temperature Logger
 *
 * Reads the temperature from a Sensirion STS40 sensor on I2C bus 1
 * (address 0x60) every 5 seconds and logs the reading to
 * temperature_log.txt.  Handles errors gracefully and exits cleanly
 * on SIGINT or SIGTERM.
 *
 * Build:  gcc -O2 -Wall -o sts40_logger sts40_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
