#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define STS40_ADDR     0x60
#define LOG_FILE       "temperature_log.txt"
#define SAMPLE_MS      5000
#define CONV_MS        10

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* CRC-8 as used by Sensirion: polynomial 0x31, init 0xFF, no final XOR */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "read: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "read: short read (%zd of %zu)\n", n, len);
        return -1;
    }
    return 0;
}

static int log_temperature(FILE *fp, float temperature)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time(): %s\n", strerror(errno));
        return -1;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r: %s\n", strerror(errno));
        return -1;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime: buffer too small\n");
        return -1;
    }
    if (fprintf(fp, "%s,%.2f\n", ts, temperature) < 0) {
        fprintf(stderr, "fprintf: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = i2c_open(I2C_BUS, STS40_ADDR);
    if (fd < 0)
        return EXIT_FAILURE;

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("STS40 logger started.  Logging to %s every %d ms.\n",
           LOG_FILE, SAMPLE_MS);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        uint8_t data[3];
        if (i2c_read_bytes(fd, data, sizeof(data)) < 0) {
            fprintf(stderr, "I2C read failed; continuing.\n");
            usleep(CONV_MS * 1000);
            continue;
        }

        /* Sensirion CRC-8: poly 0x31, init 0xFF, no final XOR */
        if (crc8(data, 2) != data[2]) {
            fprintf(stderr, "CRC mismatch: calc=0x%02X recv=0x%02X\n",
                    crc8(data, 2), data[2]);
            usleep(CONV_MS * 1000);
            continue;
        }

        float temperature = (float)data[0] / 16.0f;
        if (log_temperature(fp, temperature) < 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }
        printf("Temperature: %.2f C\n", temperature);
        usleep(SAMPLE_MS * 1000);
    }

    printf("\nShutting down cleanly.\n");
    fclose(fp);
    close(fd);
    return EXIT_SUCCESS;
}

