/*
 * SCD40 CO2 Sensor Reader for Raspberry Pi 4 Model B
 * Uses pigpio for I2C and thread-safe circular buffer.
 *
 * Build:  gcc -O2 -Wall -Wextra -o scd40_reader scd40_reader.c -lpigpio -lrt
 * Run:    sudo ./scd40_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS          1
#define SCD40_ADDR       0x48
#define BUFFER_SIZE      100
#define LOG_FILE         "/var/log/scd40_data/scd40_data.csv"
#define ERROR_LOG_FILE   "/var/log/scd40_error.log"
#define SAMPLE_INTERVAL  5
#define READ_DELAY_US    1000000   /* 1 second between first read */
#define LOG_INTERVAL_S   60

/* CRC-8 polynomial 0x31, initial 0xFF (Sensirion spec) */
static const uint8_t scd40_crc8[8] = {
    0x31, 0xFF, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
};

typedef struct {
    float co2;
    float temperature;
    float humidity;
} SensorData;

typedef struct {
    SensorData data[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion: poly 0x31, init 0xFF)                             */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ scd40_crc8[j]);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int handle, uint8_t cmd)
{
    int rc = i2cWriteByteData(handle, 0, cmd);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(0x%02X) failed: %d\n", cmd, rc);
        return -1;
    }
    return 0;
}

static int i2c_read_block(int handle, uint8_t *buf, int len)
{
    int rc = i2cReadI2CBlockData(handle, 0, (char *)buf, len);
    if (rc != len) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData(len=%d) failed: %d\n", len, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* SCD40 driver                                                        */
/* ------------------------------------------------------------------ */
static int scd40_init(int handle)
{
    if (i2c_write_cmd(handle, 0x01) < 0)
        return -1;   /* start periodic measurement */

    /* Wait for first measurement to complete (~1.5 s at 100 Hz) */
    gpioDelay(2000);

    /* Send start-periodic-measurement command */
    if (i2c_write_cmd(handle, 0x02) < 0)
        return -1;

    /* Wait for first measurement to complete (~1.5 s at 100 Hz) */
    gpioDelay(2000);

    return 0;
}

static int scd40_read(int handle, SensorData *data)
{
    uint8_t buf[8];

    if (i2c_read_block(handle, buf, sizeof(buf)) < 0)
        return -1;

    /* CRC validation */
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "[ERROR] CRC mismatch on CO2 (buf[2] = 0x%02X)\n", buf[2]);
        return -1;
    }
    if (crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "[ERROR] CRC mismatch on temperature (buf[5] = 0x%02X)\n", buf[5]);
        return -1;
    }
    if (crc8(buf + 6, 2) != buf[8]) {
        fprintf(stderr, "[ERROR] CRC mismatch on humidity (buf[8] = 0x%02X)\n", buf[8]);
        return -1;
    }

    data->co2 = (float)buf[0] * 100.0f;
    data->temperature = (float)buf[1] * 0.1f;
    data->humidity = (float)buf[3] * 0.1f;

    return 0;
}

static void scd40_buffer_add(CircularBuffer *cb, SensorData data)
{
    cb->data[cb->head] = data;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

static void scd40_buffer_flush(CircularBuffer *cb)
{
    if (cb->count > 0) {
        FILE *fp = fopen(LOG_FILE, "a");
        if (fp) {
            time_t t = time(NULL);
            struct tm tm;
            if (localtime_r(&t, &tm)) {
                fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, CO2: %.2f, Temp: %.2f, Hum: %.2f\n",
                        tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                        tm.tm_hour, tm.tm_min, tm.tm_sec,
                        data.co2, data.temperature, data.humidity);
                fclose(fp);
            }
            free(fp);
        }
    }
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                         */
/* ------------------------------------------------------------------ */
static void log_data(const char *filename, const SensorData *data)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("[ERROR] fopen(log)");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, CO2: %.2f, Temp: %.2f, Hum: %.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                data->co2, data->temperature, data->humidity);
    } else {
        fprintf(fp, "Error: localtime_r failed\n");
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C init --- */
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SCD40_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- SCD40 init --- */
    if (scd40_init(i2c_handle) < 0) {
        fprintf(stderr, "[FATAL] SCD40 init failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Circular buffer --- */
    CircularBuffer buffer;
    buffer.head = 0;
    buffer.count = 0;

    /* --- Log file --- */
    FILE *log_fp = fopen(LOG_FILE, "w");
    if (!log_fp) {
        perror("[FATAL] fopen(log)");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(log_fp, "Timestamp,CO2,Temperature,Humidity\n");
    fclose(log_fp);

    /* --- Log file error log --- */
    log_fp = fopen(ERROR_LOG_FILE, "a");
    if (!log_fp) {
        perror("[FATAL] fopen(error_log)");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(log_fp, "Timestamp,ERROR_CODE\n");
    fclose(log_fp);

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SCD40 CO2 logger started. Logging to %s every %d s. Press Ctrl+C to stop.\n",
           LOG_FILE, READ_DELAY_S);

    /* --- Main loop --- */
    while (running) {
        SensorData data;
        if (scd40_read(i2c_handle, &data) == 0) {
            scd40_buffer_add(&buffer, data);
            scd40_buffer_flush(&buffer);
            log_data(LOG_FILE, &buffer);
        } else {
            fprintf(stderr, "[WARN] SCD40 read failed; skipping this sample.\n");
        }

        /* Sleep in 1 s increments so signals are caught promptly */
        for (int i = 0; i < READ_DELAY_S && running; i++)
            gpioDelay(1000000);
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

