}

static void scd40_buffer_add(CircularBuffer *cb, SensorData data)
{
    cb->data[cb->head] = data;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

static void scd40_buffer_flush(CircularBuffer *cb)
{
    if (cb->count > 0) {
        FILE *fp = fopen(LOG_FILE, "a");
        if (fp) {
            time_t t = time(NULL);
            struct tm tm;
            if (localtime_r(&t, &tm)) {
                fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, CO2: %.2f, Temp: %.2f, Hum: %.2f\n",
                        tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                        tm.tm_hour, tm.tm_min, tm.tm_sec,
                        data.co2, data.temperature, data.humidity);
                fclose(fp);
            }
            free(fp);
        }
    }
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                         */
/* ------------------------------------------------------------------ */
static void log_data(const char *filename, const SensorData *data)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("[ERROR] fopen(log)");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, CO2: %.2f, Temp: %.2f, Hum: %.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                data->co2, data->temperature, data->humidity);
    } else {
        fprintf(fp, "Error: localtime_r failed\n");
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C init --- */
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SCD40_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- SCD40 init --- */
    if (scd40_init(i2c_handle) < 0) {
        fprintf(stderr, "[FATAL] SCD40 init failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Circular buffer --- */
    CircularBuffer buffer;
    buffer.head = 0;
    buffer.count = 0;

    /* --- Log file --- */
    FILE *log_fp = fopen(LOG_FILE, "w");
    if (!log_fp) {
        perror("[FATAL] fopen(log)");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(log_fp, "Timestamp,CO2,Temperature,Humidity\n");
    fclose(log_fp);

    /* --- Log file error log --- */
    log_fp = fopen(ERROR_LOG_FILE, "a");
    if (!log_fp) {
        perror("[FATAL] fopen(error_log)");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(log_fp, "Timestamp,ERROR_CODE\n");
    fclose(log_fp);

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SCD40 CO2 logger started. Logging to %s every %d s. Press Ctrl+C to stop.\n",
           LOG_FILE, READ_DELAY_S);

    /* --- Main loop --- */
    while (running) {
        SensorData data;
        if (scd40_read(i2c_handle, &data) == 0) {
            scd40_buffer_add(&buffer, data);
            scd40_buffer_flush(&buffer);
            log_data(LOG_FILE, &buffer);
        } else {
            fprintf(stderr, "[WARN] SCD40 read failed; skipping this sample.\n");
        }

        /* Sleep in 1 s increments so signals are caught promptly */
        for (int i = 0; i < READ_DELAY_S && running; i++)
            gpioDelay(1000000);
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

