#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x10
#define SAMPLE_INTERVAL_SEC 5
#define SAMPLE_INTERVAL_US (SAMPLE_INTERVAL_SEC * 1000000)
#define TRIGGER_DELAY_US 10000
#define FILE_NAME "environmental_data.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_i2c(void) {
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sensor(float *pressure, float *temperature) {
    char buf[2];
    int ret;

    ret = i2cReadDevice(g_i2c_handle, buf, 2);
    if (ret != 2) {
        fprintf(stderr, "Error reading sensor data: expected 2 bytes, got %d\n", ret);
        return -1;
    }

    int raw_pressure = (buf[0] << 8) | buf[1];
    int raw_temperature = (buf[0] << 8) | buf[1];

    *pressure = (float)raw_pressure / 10.0f;
    *temperature = (float)raw_temperature / 10.0f;
    return 0;
}

static int log_data(float pressure, float temperature) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }

    if (fprintf(g_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature) < 0) {
        fprintf(stderr, "Error writing to file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_file) != 0) {
        fprintf(stderr, "Error flushing file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (g_file != NULL) {
        fclose(g_file);
        g_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    float pressure, temperature;
    int ret;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(I2C_BUS, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting I2C mode on bus %d\n", I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetI2CDataLine(I2C_BUS, I2C_ADDR) != 0) {
        fprintf(stderr, "Error setting I2C data line\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_file = fopen(FILE_NAME, "a");
    if (g_file == NULL) {
        fprintf(stderr, "Error opening file %s: %s\n", FILE_NAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Starting data logging. Press Ctrl+C to stop.\n");

    while (g_running) {
        ret = read_sensor(&pressure, &temperature);
        if (ret != 0) {
            fprintf(stderr, "Sensor read error, skipping sample\n");
        } else {
            if (log_data(pressure, temperature) != 0) {
                fprintf(stderr, "Logging error, skipping sample\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

