/*
 * Raspberry Pi 4 Model B - TDK ICP-10125 barometric pressure sensor reader
 *
 * Reads six bytes per trigger (pressure, temperature, CRC) and logs
 * the result to stdout.  The sensor must be polled once per second,
 * and a warning LED on GPIO17 blinks at 1 Hz when the pressure falls
 * below 95 000 Pa.  A 5 Hz pattern is used when the pressure drops
 * below this threshold.
 *
 * Build:  gcc -O2 -Wall -o icp10125 icp10125.c -lm
 * Run:    sudo ./icp10125
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS        "/dev/i2c-1"
#define I2C_ADDR       0x10
#define PRESSURE_THRESHOLD 95000
#define WARNING_LED_GPIO 17
#define POLL_INTERVAL_S  1
#define READ_INTERVAL_S  1
#define TRIGGER_DELAY_S  20
#define LED_ON_DELAY_MS  500
#define LED_OFF_DELAY_MS 500

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * CRC-16 (polynomial 0x8005, initial 0xFF00) as used by the
 * TDK ICP-10125.
 */
static uint16_t crc16(const uint8_t *data, size_t len)
{
    uint16_t crc = 0xFF00;
    for (size_t i = 0; i < len; i++) {
        crc ^= (uint16_t)data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x0001)
                crc = (crc >> 1) ^ 0x8005;
            else
                crc >>= 1;
        }
    }
    return crc;
}

/*
 * Read a single byte from the I2C device.
 * Returns 0 on success, -1 on error.
 */
static int i2c_read_byte(int fd, uint8_t reg)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return (int)val;
}

/*
 * Read a block of bytes from the I2C device.
 * Returns 0 on success, -1 on error.
 */
static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read (reg 0x%02X, %zu bytes) failed: %s\n",
                reg, len, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a block of pressure data from the sensor.
 * Returns 0 on success, -1 on error.
 */
static int read_pressure(int fd, uint8_t *buf)
{
    if (i2c_read_block(fd, 0x00, buf, 6) != 0)
        return -1;

    /* Verify CRC on the first two bytes (pressure MSB, LSB) */
    if (crc16(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc16(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }

    /* Pressure is two bytes, little-endian */
    int16_t pressure = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/*
 * Read a block of temperature data from the sensor.
 * Returns 0 on success, -1 on error.
 */
static int read_temperature(int fd, uint8_t *buf)
{
    if (i2c_read_block(fd, 0x01, buf, 2) != 0)
        return -1;

    /* Verify CRC on the first two bytes (temperature MSB, LSB) */
    if (crc16(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (crc16(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }

    /* Temperature is two bytes, little-endian */
    int16_t temperature = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/*
 * Read a block of CRC data from the sensor.
 * Returns 0 on success, -1 on error.
 */
static int read_crc(int fd, uint8_t *buf)
{
    if (i2c_read_block(fd, 0x02, buf, 2) != 0)
        return -1;

    /* Verify CRC on the first two bytes (CRC, data) */
    if (crc16(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch\n");
        return -1;
    }
    if (crc16(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Data CRC mismatch\n");
        return -1;
    }

    return 0;
}

/*
 * Trigger a single measurement and log the result.
 * Returns 0 on success, -1 on error.
 */
static int trigger_measurement(int fd)
{
    uint8_t buf[6];

    if (i2c_read_block(fd, 0x00, buf, 6) != 0)
        return -1;

    /* Verify CRC on the first two bytes (pressure MSB, LSB) */
    if (crc16(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc16(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }

    /* Pressure is two bytes, little-endian */
    int16_t pressure = (int16_t)((buf[0] << 8) | buf[1]);

    /* Temperature is two bytes, little-endian */
    int16_t temperature = (int16_t)((buf[3] << 8) | buf[4]);

    /*
     * The ICP-10125 sends the pressure in units of 0.01 Pa.
     * The temperature is in degrees Celsius.
     */
    printf("Pressure: %d Pa, Temperature: %d C\n", pressure, temperature);
    fflush(stdout);

    return 0;
}

int main(void)
{
    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the I2C slave address */
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                I2C_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Configure sensor: no auto-increment, no slave-repeat */
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                I2C_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Open GPIO 17 as output */
    if (gpio_request_output(WARNING_LED_GPIO, 0) != 0) {
        fprintf(stderr, "Cannot request GPIO %d as output: %s\n",
                WARNING_LED_GPIO, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Set LED to off */
    if (gpio_write(WARNING_LED_GPIO, 0) != 0) {
        fprintf(stderr, "Cannot set GPIO %d to off: %s\n",
                WARNING_LED_GPIO, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("ICP-10125 monitoring started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* Main polling loop */
    while (g_running) {
        if (trigger_measurement(fd) != 0) {
            fprintf(stderr, "Trigger failed; continuing.\n");
            /* Sleep briefly to avoid busy-waiting */
            usleep(TRIGGER_DELAY_MS * 1000);
            continue;
        }

        /* Wait for the next trigger interval */
        struct timespec ts = {
            .tv_sec  = POLL_INTERVAL_S  * 1000,
            .tv_nsec = 0
        };
        nanosleep(&ts, NULL);

        /* Check for pressure below threshold */
        if (pressure_below_threshold(fd)) {
            printf("Warning: pressure below threshold %d Pa\n",
                   PRESSURE_THRESHOLD);
            fflush(stdout);
            /* Blink the LED */
            if (gpio_write(WARNING_LED_GPIO, 1) != 0)
                fprintf(stderr, "Warning LED on failed: %s\n",
                        strerror(errno));
            gpio_write(WARNING_LED_GPIO, 0);
        }

        /* Check for LED blinking */
        if (gpio_read(WARNING_LED_GPIO) == 0) {
            printf("Warning LED blinking\n");
            fflush(stdout);
        }

        /* Sleep for the remaining poll interval */
        struct timespec ts_rem = {
            .tv_sec  = POLL_INTERVAL_S  * 1000,
            .tv_nsec = 0
        };
        nanosleep(&ts_rem, NULL);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    gpio_write(WARNING_LED_GPIO, 0);
    close(fd);
    return EXIT_SUCCESS;
}

