#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <pigpio.h>

#define I2C_BUS "/dev/i2c-1"
#define MLX90614_ADDR 0xAA
#define FAN_GPIO 18
#define TEMP_THRESHOLD 30.0
#define TEMP_THRESHOLD_LOW 28.0
#define LOG_FILE "temperature_log.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

static int i2c_fd = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int read_mlx90614(int fd, float *temp) {
    uint8_t buf[2];
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_read_reg8(fd, 0x00, buf) == 0) {
            int16_t raw = (buf[0] << 8) | buf[1];
            *temp = (float)raw / 100.0f;
            return 0;
        }
        fprintf(stderr, "I2C read failed (attempt %d): %s\n", attempt + 1, strerror(errno));
        if (attempt < MAX_RETRIES - 1) usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int log_temperature(float temp) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, temp);
    fclose(fp);
    return 0;
}

static void control_fan(float temp) {
    if (temp > TEMP_THRESHOLD) {
        gpioWrite(FAN_GPIO, 1);
    } else {
        gpioWrite(FAN_GPIO, 0);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C bus");
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_GPIO);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }
    gpioWrite(FAN_GPIO, 0);

    while (running) {
        float temp;
        if (read_mlx90614(i2c_fd, &temp) == 0) {
            printf("Temperature: %.2f C\n", temp);
            if (log_temperature(temp) != 0) {
                fprintf(stderr, "Failed to log temperature\n");
            }
            control_fan(temp);
        } else {
            fprintf(stderr, "Failed to read temperature after %d attempts\n", MAX_RETRIES);
        }
        for (int i = 0; i < 2 && running; i++) {
            sleep(2);
        }
    }

    printf("\nShutting down...\n");
    gpioWrite(FAN_GPIO, 0);
    if (i2c_fd >= 0) close(i2c_fd);
    gpioTerminate();
    return 0;
}

