/*
 * SHT40 Temperature & Humidity Monitor for Raspberry Pi 4 Model B
 * Uses pigpio for I2C communication.
 *
 * Build: gcc -O2 -Wall -o sht40_monitor sht40_monitor.c -lpigpio -lrt
 * Run:   sudo ./sht40_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SHT40_ADDR     0x44
#define MEASURE_CMD    0x01
#define MEASURE_DELAY  10000   /* 10 ms */
#define RETRY_COUNT    3
#define RETRY_DELAY_US 10000   /* 10 ms */
#define HTTP_PORT      8080
#define HUMIDITY_MIN   0.0
#define HUMIDITY_MAX   100.0

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int handle, uint8_t cmd)
{
    int rc = i2cWriteByteData(handle, 0, cmd);
    if (rc < 0) {
        fprintf(stderr, "i2cWriteByteData failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int handle, uint8_t *buf, int len)
{
    int rc = i2cReadDevice(handle, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "i2cReadDevice failed: got %d of %d bytes (%s)\n",
                rc, len, rc < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* SHT40 read                                                          */
/* ------------------------------------------------------------------ */
static int sht40_read(int handle, float *temperature, float *humidity)
{
    uint8_t cmd[2] = {MEASURE_CMD, 0x00};
    uint8_t buf[6];

    /* Send measurement command */
    if (i2c_write_cmd(handle, MEASURE_CMD) < 0)
        return -1;

    /* Wait for measurement to complete */
    gpioDelay(MEASURE_DELAY);

    /* Read 6 bytes: temperature (2), humidity (2), status (1) */
    if (i2c_read_bytes(handle, buf, 6) < 0)
        return -1;

    /* Status byte is the first byte of the response */
    if (buf[0] != 0x00) {
        fprintf(stderr, "SHT40 status byte mismatch: 0x%02X\n", buf[0]);
        return -1;
    }

    /* Humidity: 2 bytes, big-endian */
    uint16_t raw_humidity = ((uint16_t)buf[1] << 8) | buf[2];

    /* Temperature: 2 bytes, big-endian */
    uint16_t raw_temp = ((uint16_t)buf[3] << 8) | buf[4];

    /* Clamp humidity to range 0–100 % */
    if (raw_humidity < HUMIDITY_MIN || raw_humidity > HUMIDITY_MAX) {
        fprintf(stderr, "Humidity out of range: %u %%. Sensor may be absent.\n",
                raw_humidity);
        return -1;
    }

    *humidity = (float)raw_humidity / 100.0f;
    *temperature = (float)raw_temp / 100.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* HTTP server                                                         */
/* ------------------------------------------------------------------ */
static int http_serve(const char *path)
{
    int port = 8080;
    char *path_copy = strdup(path);
    if (!path_copy) {
        fprintf(stderr, "strdup failed: %s\n", strerror(errno));
        return -1;
    }

    if (strncmp(path_copy, "/", 1) == 0) {
        free(path_copy);
        return -1;
    }

    char *slash = strrchr(path_copy, '/');
    if (!slash) {
        free(path_copy);
        return -1;
    }
    *slash = '\0';

    char *path_slash = strrchr(path_copy, '/');
    if (!path_slash) {
        free(path_copy);
        return -1;
    }
    *path_slash = '\0';

    char *path_slash_slash = strrchr(path_copy, '/');
    if (!path_slash_slash) {
        free(path_copy);
        return -1;
    }
    *path_slash_slash = '\0';

    char *path_slash_slash_slash = strrchr(path_copy, '/');
    if (!path_slash_slash_slash) {
        free(path_copy);
        return -1;
    }
    *path_slash_slash_slash = '\0';

    char *path_slash_slash_slash_slash = strrchr(path_copy, '/');
    if (!path_slash_slash_slash_slash) {
        free(path_copy);
        return -1;
    }
    *path_slash_slash_slash_slash = '\0';

    char *path_slash_slash_slash_slash_slash = strrchr(path_copy, '/');
    if (!path_slash_slash_slash_slash_slash) {
        free(path_copy);
        return -1;
    }
    *path_slash_slash_slash_slash_slash = '\0';

    char *path_slash_slash_slash_slash_slash = strrchr(path_copy, '/');
    if (!path_slash_slash_slash_slash_slash) {
