    *path_slash_slash_slash_slash_slash = '\0';

    char *path_slash_slash_slash_slash_slash_slash = strrchr(path_copy, '/');
    if (!path_slash_slash_slash_slash_slash_slash) {
        free(path_copy);
        return -1;
    }
    *path_slash_slash_slash_slash_slash_slash = '\0';

    char *path_slash_slash_slash_slash_slash_slash_slash = strrchr(path_copy, '/');
    if (!path_slash_slash_slash_slash_slash_slash_slash) {
        free(path_copy);
        return -1;
