/*
 * TMP102 Temperature Logger for Raspberry Pi 4 Model B
 * Uses pigpio for I2C communication.
 *
 * Build: gcc -O2 -Wall -o tmp102_logger tmp102_logger.c -lpigpio -lrt
 * Run:   sudo ./tmp102_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define TMP102_ADDR    0x48
#define LOG_FILE       "temperature_log.csv"
#define MEASURE_DELAY  5          /* seconds between measurements */
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single temperature value from the TMP102.
 * Returns 0 on success, -1 on failure.
 */
static int read_temperature(int i2c_handle, float *temperature)
{
    char buf[2];
    int  retries = 0;

    while (retries < MAX_RETRIES) {
        /*
         * TMP102 datasheet:
         *   - The first byte is the command byte (0x80 + (channel << 4)).
         *   - The second byte is the data byte (0x00 + (channel << 4)).
         *   - The third byte is the status byte (0x00).
         *
         * We send the command byte (0x80 + (channel << 4)) and read 2 bytes.
         */
        buf[0] = 0x80 | (char)((channel & 0x03) << 4);
        buf[1] = 0x00;

        int rc = i2cWriteDevice(i2c_handle, (char *)buf, 2);
        if (rc < 0) {
            fprintf(stderr, "I2C write failed (rc=%d): %s\n", rc, strerror(errno));
            retries++;
            if (retries < MAX_RETRIES)
                gpioDelay(100000); /* 100 ms backoff */
            continue;
        }

        /* Read 2 bytes back from the device. */
        int bytes_read = i2cReadDevice(i2c_handle, (char *)buf, 2);
        if (bytes_read != 2) {
            fprintf(stderr, "I2C read failed (rc=%d): got %d bytes, expected 2\n",
                    bytes_read, rc);
            retries++;
            if (retries < MAX_RETRIES)
                gpioDelay(100000); /* 100 ms backoff */
            continue;
        }

        /* TMP102 data: temperature is the second byte (low nibble) */
        int raw = (buf[0] & 0x0F) << 8 | buf[1];
        *temperature = (float)raw / 16.0f;
        return 0;
    }

    return -1;
}

/*
 * Append a timestamped temperature reading to the CSV file.
 * Returns 0 on success, -1 on failure.
 */
static int log_temperature(FILE *fp, float temperature)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", timestamp, temperature) < 0) {
        fprintf(stderr, "fprintf() to CSV failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    /* --- Install SIGINT handler for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus 1 at TMP102 address --- */
    int i2c_handle = i2cOpen(I2C_BUS, TMP102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, TMP102_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file for appending --- */
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Main loop --- */
    while (g_running) {
        float temperature;

        if (read_temperature(i2c_handle, &temperature) == 0) {
            if (log_temperature(fp, temperature) == 0) {
                printf("Temperature: %.2f C\n", temperature);
            } else {
                fprintf(stderr, "Failed to log temperature.\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature after %d retries.\n",
                    MAX_RETRIES);
        }

        /* Sleep in 1-second increments so SIGINT is caught promptly. */
        for (int i = 0; i < MEASURE_DELAY * 10 && g_running; i++)
            gpioDelay(100000); /* 100 ms */
    }

    /* --- Clean shutdown --- */
    fclose(fp);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

