/*
 * HDC2010 Temperature & Humidity Reader for Raspberry Pi Zero W
 * Uses pigpio for I2C communication.
 *
 * Wiring:
 *   HDC2010 SDA -> GPIO2 (I2C1 SDA)
 *   HDC2010 SCL -> GPIO3 (I2C1 SCL)
 *   HDC2010 VDD -> 3.3 V
 *   HDC2010 GND -> GND
 *
 * Build: gcc -Wall -o hdc2010 hdc2010.c -lpigpio -lrt
 * Run:   sudo ./hdc2010
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define HDC2010_ADDR   0x40
#define MEASURE_CONFIG 0x00
#define MEASURE_CONFIG_CLEAR 0x01
#define MAX_RETRIES    3
#define TIMEOUT_US     500000   /* 500 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
    }
    return rc;
}

static int i2c_read_byte(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

static int i2c_read_word(int handle, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    if (i2c_read_byte(handle, reg, buf[0]) < 0)
        return -1;
    *out = (uint16_t)((uint8_t)buf[0] | ((uint8_t)buf[1] << 8));
    return 0;
}

/* ------------------------------------------------------------------ */
/* HDC2010 API                                                         */
/* ------------------------------------------------------------------ */
static int hdc2010_init(int handle)
{
    /*
     * Start measurement by setting MEASURE_CONFIG = 0x01 (clear).
     * The sensor responds with a status byte in the MEASURE_CONFIG register.
     * We wait for the first byte to be written (status = 0x00) or the
     * timeout (status = 0xFF).
     */
    if (i2c_write_byte(handle, MEASURE_CONFIG, MEASURE_CONFIG_CLEAR) < 0)
        return -1;

    /*
     * Wait for the first byte of the status register to be written.
     * We poll every 100 ms until the first byte is read.
     */
    for (int i = 0; i < TIMEOUT_US / 100; i++) {
        uint8_t status;
        if (i2c_read_byte(handle, MEASURE_CONFIG, &status) < 0)
            return -1;
        if (status == 0x00)
            break;
        gpioDelay(100000); /* 100 ms */
    }

    if (status != 0x00) {
        fprintf(stderr, "HDC2010 not responding (status=0x%02X)\n", status);
        return -1;
    }

    return 0;
}

static int hdc2010_read(int handle, float *temperature, float *humidity)
{
    uint8_t status;
    uint16_t raw_temp, raw_hum;

    /*
     * Read temperature (MSB first).
     * We wait for the first byte to be written (status = 0x00) or the
     * timeout (status = 0xFF).
     */
    for (int i = 0; i < TIMEOUT_US / 100; i++) {
        if (i2c_read_byte(handle, MEASURE_CONFIG, &status) < 0)
            return -1;
        if (status == 0x00)
            break;
        gpioDelay(100000);
    }

    if (status != 0x00) {
        fprintf(stderr, "HDC2010 status read error (status=0x%02X)\n", status);
        return -1;
    }

    if (i2c_read_word(handle, MEASURE_CONFIG, &raw_temp) < 0)
        return -1;

    if (i2c_read_word(handle, MEASURE_CONFIG, &raw_hum) < 0)
        return -1;

    /*
     * HDC2010 temperature is MSB of the 16-bit word, humidity is LSB.
     */
    *temperature = (float)raw_temp / 10.0f;
    *humidity    = (float)raw_hum / 10.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for Ctrl+C and SIGTERM */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, HDC2010_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, HDC2010_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (hdc2010_init(g_i2c_handle) < 0) {
        fprintf(stderr, "HDC2010 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HDC2010 temperature & humidity reader started.\n");
    printf("Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        float temperature, humidity;

        if (hdc2010_read(g_i2c_handle, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        /* Sleep for 5 seconds, checking g_running every 100 ms */
        for (int i = 0; i < 50 && g_running; i++)
            gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

