/*
 * Reflow Oven Controller for Raspberry Pi 3 Model B+
 *
 * Hardware:
 *   - MAX6675 thermocouple amplifier (SPI0 CE0/CE1)
 *   - Solid-state relay (GPIO17, BCM 17)
 *   - MAX6675 SPI interface (CE0/CE1)
 *   - Target temperature profile file (profile.txt)
 *
 * Build:
 *   gcc -O2 -Wall -o reflow_oven reflow_oven.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP       "gpiochip4"
#define GPIO_LINE       17
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define LOG_FILE        "reflow_log.csv"
#define SAMPLE_PERIOD_S 1
#define MAX_ERROR_MS    1000

#define PID_KP         0.1
#define PID_KI         0.01
#define PID_KD         0.1

#define MAX_TEMP_C    100.0
#define MIN_TEMP_C    -50.0

#define LOG_FILE_SIZE  (SAMPLE_PERIOD_S * 1000)

typedef struct {
    time_t timestamp;
    float temperature;
} TemperatureData;

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_relay_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_init(void) {
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int spi_read_register(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "SPI write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "SPI read (reg 0x%02X, len %zu) failed: %s\n", reg, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int spi_write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "SPI write (reg 0x%02X, value 0x%02X) failed: %s\n", reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_temperature(float *temperature) {
    uint8_t buf[3];
    if (spi_read_register(g_spi_fd, 0x00, buf, 3) < 0) {
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    if (raw & 0x8000) {
        raw |= 0xFFFF0000;
    }
    *temperature = (float)raw / 16.0f;
    return 0;
}

static int read_profile(float *target_temp) {
    FILE *fp = fopen(profile_file, "r");
    if (!fp) {
        fprintf(stderr, "Error opening profile file %s: %s\n", profile_file, strerror(errno));
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *endptr;
        long val = strtol(line, &endptr, 10);
        if (endptr == line || *endptr != '\n') {
            fprintf(stderr, "Invalid line format in profile file\n");
            fclose(fp);
            return -1;
        }
        if (val >= 0 && val <= MAX_TEMP_C) {
            *target_temp = (float)val;
            return 0;
        }
    }

    fclose(fp);
    fprintf(stderr, "No valid temperature profile found in %s\n", profile_file);
    return -1;
}

static int calculate_pid(float current_temp, float target_temp, float *error, float *integral, float *derivative) {
    *error = target_temp - current_temp;
    *integral += *error;
    *derivative = (*error - *integral) / SAMPLE_PERIOD_S;
    float output = PID_KP * *error + PID_KI * *integral + PID_KD * *derivative;
    if (output < 0.0f) output = 0.0f;
    if (output > 1.0f) output = 1.0f;
    return (int)(output * 100.0f);
}

static int control_relay(float duty_cycle) {
    if (duty_cycle < 0.0f) duty_cycle = 0.0f;
    if (duty_cycle > 1.0f) duty_cycle = 1.0f;

    if (gpiod_line_set_value(g_relay_line, (int)duty_cycle) < 0) {
        fprintf(stderr, "Error setting relay value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void log_data(float temperature, int duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    fprintf(fp, "%s,%.2f,%.2f\n", ts, temperature, duty_cycle);
    fclose(fp);
}

static void cleanup(void) {
    if (g_relay_line) {
        gpiod_line_set_value(g_relay_line, 0);
        gpiod_line_release(g_relay_line);
        g_relay_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting signal handler: %s\n", strerror(errno));
        return 1;
    }

    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        return 1;
    }

    g_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!g_chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        cleanup();
        return 1;
    }

    g_relay_line = gpiod_chip_get_line(g_chip, GPIO_LINE);
    if (!g_relay_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(g_relay_line, "reflow_relay", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    float target_temp = 0.0f;
    float integral = 0.0f;
    float derivative = 0.0f;
    float previous_error = 0.0f;

    while (g_running) {
        float temperature = 0.0f;
        if (read_temperature(&temperature) < 0) {
            fprintf(stderr, "Error reading temperature, retrying in 1 second...\n");
            sleep(1);
            continue;
        }

        float pid_output = calculate_pid(temperature, target_temp, &previous_error, &integral, &derivative);
        int duty_cycle = (int)pid_output;

        if (control_relay(duty_cycle) < 0) {
            fprintf(stderr, "Error controlling relay\n");
        }

        target_temp = (float)pid_output;
        integral += previous_error;
        previous_error = pid_output;

        float log_data = 0.0f;
        if (read_profile(&log_data) < 0) {
            fprintf(stderr, "Error reading profile, retrying in 1 second...\n");
            sleep(1);
            continue;
        }

        log_data += log_data;
        if (log_data > LOG_FILE_SIZE) {
            log_data = LOG_FILE_SIZE;
        }

        float duty_cycle_total = (float)duty_cycle;
        if (duty_cycle_total > 1.0f) duty_cycle_total = 1.0f;
        if (duty_cycle_total < 0.0f) duty_cycle_total = 0.0f;

        float duty_cycle_avg = (duty_cycle_total + previous_error) / 2.0f;
        if (duty_cycle_avg > 1.0f) duty_cycle_avg = 1.0f;
        if (duty_cycle_avg < 0.0f) duty_cycle_avg = 0.0f;

        float duty_cycle_change = duty_cycle_avg - previous_error;
        if (duty_cycle_change > MAX_ERROR_MS) {
            duty_cycle_change = MAX_ERROR_MS;
        } else if (duty_cycle_change < -MAX_ERROR_MS) {
            duty_cycle_change = -MAX_ERROR_MS;
        }

        if (duty_cycle_change > 0.0f) {
            if (control_relay(duty_cycle_change) < 0) {
                fprintf(stderr, "Error changing relay state\n");
            }
        }

        sleep(SAMPLE_PERIOD_S);
    }

    cleanup();
    return 0;
}

