/*
 * AHT20 humidity monitor for Raspberry Pi 5 (I2C bus 1, address 0x60).
 *
 * Wiring:
 *   AHT20 SDA -> GPIO2 (pin 3)
 *   AHT20 SCL -> GPIO3 (pin 5)
 *   AHT20 VDD -> 3.3 V
 *   AHT20 GND -> GND
 *   Relay control -> GPIO17 (active-high)
 *
 * Build:  gcc -O2 -Wall -Wextra -o aht20_monitor aht20_monitor.c
 * Run:    sudo ./aht20_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define AHT20_ADDR     0x60
#define HUMIDITY_THRESHOLD_HIGH 60.0f
#define HUMIDITY_THRESHOLD_LOW  55.0f
#define GPIO_PIN        17
#define POLL_INTERVAL_S  5
#define MAX_RETRIES      3
#define RETRY_DELAY_MS   10
#define MEASURE_DELAY_US 80000   /* 80 ms */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_write_byte(int fd, uint8_t byte)
{
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C short read: got %zd of %zu\n", n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* AHT20                                                               */
/* ------------------------------------------------------------------ */

/*
 * AHT20 datasheet:
 *   Status byte (bit 0) = 0 -> calibrated, busy = 1 -> not ready.
 *   Calibration data:
 *     MSB  LSB  Resolution
 *     [0x00, 0x00] [0x00, 0x00]
 *     [0x01, 0x00] [0x00, 0x00]
 *     [0x02, 0x00] [0x00, 0x00]
 *     [0x03, 0x00] [0x00, 0x00]
 *     [0x04, 0x00] [0x00, 0x00]
 *     [0x05, 0x00] [0x00, 0x00]
 *     [0x06, 0x00] [0x00, 0x00]
 *     [0x07, 0x00] [0x00, 0x00]
 *     [0x08, 0x00] [0x00, 0x00]
 *     [0x09, 0x00] [0x00, 0x00]
 *     [0x0A, 0x00] [0x00, 0x00]
 *     [0x0B, 0x00] [0x00, 0x00]
 *     [0x0C, 0x00] [0x00, 0x00]
 *     [0x0D, 0x00] [0x00, 0x00]
 *     [0x0E, 0x00] [0x00, 0x00]
 *     [0x0F, 0x00] [0x00, 0x00]
 *   Status byte (bit 1) = 0 -> not busy, 1 -> busy.
 */
static int aht20_read_humidity(int fd, float *humidity)
{
    uint8_t buf[6];

    if (i2c_write_byte(fd, 0x00) < 0)
        return -1;

    if (i2c_read_bytes(fd, buf, sizeof(buf)) < 0)
        return -1;

    if (buf[0] & 0x01) {
        fprintf(stderr, "AHT20: status byte 0x%02X is busy (not ready)\n",
                buf[0]);
        return -1;
    }

    if (buf[0] & 0x01) {
        fprintf(stderr, "AHT20: status byte 0x%02X is not ready\n",
                buf[0]);
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[1] << 8) | buf[2];
    *humidity = (float)raw / 65536.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO                                                               */
/* ------------------------------------------------------------------ */

static int gpio_init(void)
{
    if (gpio_pin < 0 || gpio_pin > 31) {
        fprintf(stderr, "Invalid GPIO pin %d\n", gpio_pin);
        return -1;
    }

    if (ioctl(open("/dev/gpiochip4"), request_gpio_output, GPIO_PIN) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output: %s\n",
                GPIO_PIN, strerror(errno));
        return -1;
    }

    if (gpio_pin < 0) {
        fprintf(stderr, "GPIO %d is already in use by another process\n",
                GPIO_PIN);
        return -1;
    }

    if (gpio_pin < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_PIN);
        return -1;
    }

    if (gpio_pin < 0) {
        fprintf(stderr, "Failed to request GPIO %d as output\n", GPIO_PIN);
        return -1;
    }

    return 0;
}

