/*
 * Raspberry Pi Zero W - HTU21D Relative Humidity Monitor
 *
 * Reads the HTU21D sensor on I2C bus 1 (address 0x5A) and posts the
 * relative humidity as a JSON document to http://api.example.com/humidity.
 *
 * Build:  gcc -O2 -Wall -Wextra -o humidity_monitor humidity_monitor.c -lrt
 * Run:    sudo ./humidity_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <syslog.h>

#define I2C_BUS        "/dev/i2c-1"
#define HTU21D_ADDR    0x5A
#define POST_URL       "http://api.example.com/humidity"
#define POLL_INTERVAL  60
#define MAX_RETRIES    3

/* HTU21D register addresses */
#define REG_CONTROL    0x01
#define REG_DATA_MSB   0x02
#define REG_DATA_LSB   0x03

/* Control register bits */
#define CTRL_RESET     0x01
#define CTRL_MEASURE   0x80

/* Data register bits */
#define DATA_MSB        0x01
#define DATA_LSB        0x02

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        syslog(LOG_ERR, "I2C write to reg 0x%02X failed: %s", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        syslog(LOG_ERR, "I2C write (reg select 0x%02X) failed: %s", reg, strerror(errno));
        return -1;
    }
    if (read(fd, out, 1) != 1) {
        syslog(LOG_ERR, "I2C read from reg 0x%02X failed: %s", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        syslog(LOG_ERR, "I2C write (reg select 0x%02X) failed: %s", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        syslog(LOG_ERR, "I2C read from reg 0x%02X failed: %s", reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
/* HTU21D helpers                                                      */
/* ------------------------------------------------------------------ */
static int htu21d_init(int fd)
{
    if (i2c_write_byte(fd, REG_CONTROL, CTRL_RESET) < 0)
        return -1;
    usleep(10000); /* 10 ms reset settle */

    for (int i = 0; i < MAX_RETRIES; i++) {
        if (i2c_read_byte(fd, REG_CONTROL, &ctl) < 0)
            return -1;
        if (ctl & CTRL_RESET)
            break;
        usleep(10000);
    }
    if (ctl & CTRL_RESET) {
        syslog(LOG_ERR, "HTU21D reset not acknowledged (sensor absent?)");
        return -1;
    }

    if (i2c_write_byte(fd, REG_CONTROL, CTRL_MEASURE) < 0)
        return -1;
    usleep(10000); /* 10 ms measurement settle */
    return 0;
}

static int htu21d_read(int fd, uint16_t *rh)
{
    uint8_t msb, lsb;
    if (i2c_read_word(fd, REG_DATA_MSB, &msb) < 0)
        return -1;
    if (i2c_read_word(fd, REG_DATA_LSB, &lsb) < 0)
        return -1;
    *rh = (uint16_t)msb | ((uint16_t)lsb << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
/* HTTP POST                                                            */
/* ------------------------------------------------------------------ */
static int post_humidity(const char *url)
{
    int sockfd = -1;
    struct sockaddr_in servaddr;
    int rc;

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        syslog(LOG_ERR, "socket() failed: %s", strerror(errno));
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(80);
    if (inet_pton(AF_INET, url, &servaddr.sin_addr) <= 0) {
        syslog(LOG_ERR, "inet_pton() failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    if (connect(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        syslog(LOG_ERR, "connect() failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    rc = send(sockfd, "POST /humidity HTTP/1.1\r\n"
              "Host: api.example.com\r\n"
              "Connection: close\r\n"
              "Content-Type: application/json\r\n"
              "Content-Length: %zu\r\n"
              "\r\n"
              "{\"humidity\": %u}\r\n",
              (unsigned)strlen(url), (unsigned)strlen(url));
    if (rc < 0) {
        syslog(LOG_ERR, "send() failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    syslog(LOG_INFO, "Sent humidity: %u", (unsigned)rc);
    close(sockfd);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                 */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("humidity_monitor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction() failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        syslog(LOG_ERR, "open(%s) failed: %s", I2C_BUS, strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "ioctl(I2C_SLAVE, 0x%02X) failed: %s",
               HTU21D_ADDR, strerror(errno));
        close(g_i2c_fd);
        closelog();
        return EXIT_FAILURE;
    }

    if (htu21d_init(g_i2c_fd) < 0) {
        syslog(LOG_ERR, "HTU21D initialization failed");
        close(g_i2c_fd);
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "HTU21D monitoring started on %s (addr 0x%02X)",
           I2C_BUS, HTU21D_ADDR);

    while (g_running) {
        uint16_t rh;
        if (htu21d_read(g_i2c_fd, &rh) < 0) {
            syslog(LOG_ERR, "I2C read failed; retrying in %d s",
                   POLL_INTERVAL);
            usleep(POLL_INTERVAL * 1000);
            continue;
        }

        time_t now = time(NULL);
        struct tm tm_info;
        char ts[32];
        localtime_r(&now, &tm_info);
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);

        if (post_humidity(POST_URL) < 0) {
            syslog(LOG_ERR, "HTTP POST failed");
        } else {
            syslog(LOG_INFO, "%s - Humidity: %u%%", ts, (unsigned)rh);
        }

        usleep(POLL_INTERVAL * 1000);
    }

    syslog(LOG_INFO, "Shutting down gracefully");
    if (g_i2c_fd >= 0)
        close(g_i2c_fd);
    closelog();
    return EXIT_SUCCESS;
}

