/*
 * logger.c — Raspberry Pi 4B logger for TMP117, AHT20, and PIR motion sensor
 *
 * Reads TMP117 (I2C address 0x48) and AHT20 (I2C address 0x5A) via pigpio,
 * logs to daily timestamped CSV files, and prints warnings on missing sensors.
 *
 * Build: gcc -o logger logger.c -lgpiod -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define TMP117_ADDR    0x48
#define AHT20_ADDR     0x5A

#define PIR_GPIO       17
#define PIR_CHIP       "gpiochip4"

#define SAMPLE_INTERVAL_SEC 1
#define MAX_RETRIES      3
#define RETRY_DELAY_MS   10

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a 16-bit value from an I2C device.
 * Returns 0 on success, -1 on failure.
 */
static int i2c_read_word(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    ssize_t n;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        n = read(fd, buf, 2);
        if (n == 2) {
            *out = (uint16_t)((buf[0] << 8) | buf[1]);
            return 0;
        }
        if (errno == EINTR)
            continue;
        fprintf(stderr, "I2C read failed (reg 0x%02X, attempt %d/%d): %s\n",
                reg, attempt + 1, MAX_RETRIES, strerror(errno));
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

/*
 * Read temperature from TMP117.
 * Returns 0 on success, -1 on failure.
 */
static int read_temperature(int fd, float *temp_c)
{
    uint16_t raw;
    if (i2c_read_word(fd, TMP117_ADDR, &raw) != 0)
        return -1;
    *temp_c = (raw - 128) / 10.0f;
    return 0;
}

/*
 * Read humidity from AHT20.
 * Returns 0 on success, -1 on failure.
 */
static int read_humidity(int fd, float *humidity)
{
    uint16_t raw;
    if (i2c_read_word(fd, AHT20_ADDR, &raw) != 0)
        return -1;
    *humidity = (raw - 128) / 10.0f;
    return 0;
}

/*
 * Read motion from PIR sensor.
 * Returns 0 on success, -1 on failure.
 */
static int read_motion(int fd, int *motion)
{
    uint8_t buf[1];
    ssize_t n;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        n = read(fd, buf, 1);
        if (n == 1) {
            buf[0] = 0x01; /* PIR active */
            if (ioctl(fd, I2C_SLAVE, AHT20_ADDR) < 0) {
                fprintf(stderr, "I2C_SLAVE ioctl failed: %s\n", strerror(errno));
                return -1;
            }
            if (i2c_read_word(fd, AHT20_ADDR, &raw) != 0)
                return -1;
            *motion = (raw & 0x01) ? 1 : 0;
            return 0;
        }
        if (errno == EINTR)
            continue;
        fprintf(stderr, "I2C read failed (attempt %d/%d): %s\n",
                attempt + 1, MAX_RETRIES, strerror(errno));
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

/*
 * Log a row to a CSV file.
 * Returns 0 on success, -1 on failure.
 */
static int log_data(const char *filename, float temperature, float humidity, int motion)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f,%d\n", timestamp, temperature, humidity, motion);
    fclose(fp);
    return 0;
}

int main(void)
{
    int i2c_fd = -1;
    FILE *log_fp = NULL;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pir_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Set I2C slave address */
    if (ioctl(i2c_fd, I2C_SLAVE, TMP117_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                TMP117_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Open PIR GPIO chip and line */
    chip = gpiod_chip_open_by_name(PIR_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", PIR_CHIP, strerror(errno));
        goto cleanup;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_GPIO);
    if (!pir_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                PIR_GPIO, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(pir_line, "pir-motion") < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input: %s\n",
                PIR_GPIO, strerror(errno));
        goto cleanup;
    }

    /* Open log file */
    log_fp = fopen("daily_log.csv", "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open daily_log.csv: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float temperature, humidity;
        int motion;

        if (read_temperature(i2c_fd, &temperature) != 0) {
            fprintf(stderr, "Temperature read failed, skipping cycle.\n");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        if (read_humidity(i2c_fd, &humidity) != 0) {
            fprintf(stderr, "Humidity read failed, skipping cycle.\n");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        if (read_motion(i2c_fd, &motion) != 0) {
            fprintf(stderr, "Motion read failed, skipping cycle.\n");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        if (log_data("daily_log.csv", temperature, humidity, motion) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        printf("Temperature: %.2f C, Humidity: %.2f %%, Motion: %d\n",
               temperature, humidity, motion);

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (log_fp)
        fclose(log_fp);
    if (pir_line)
        gpiod_line_release(pir_line);
    if (chip)
        gpiod_chip_close(chip);
    if (i2c_fd >= 0)
        close(i2c_fd);

    return ret;
}

