        fprintf(stderr, "Error: failed to set IN2 high\n");
        gpioWrite(in1, 0);
        gpioWrite(en, 0);
        return -1;
    }
    if (gpioWrite(in3, 1) < 0) {
        fprintf(stderr, "Error: failed to set IN3 high\n");
        gpioWrite(in2, 0);
        gpioWrite(in1, 0);
        gpioWrite(en, 0);
        return -1;
