#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS "/dev/i2c-1"
#define RGB_LED_PIN_RED 17
#define RGB_LED_PIN_GREEN 22
#define RGB_LED_PIN_BLUE 27
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define SAMPLE_INTERVAL_MS 500

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, unsigned char reg) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select) failed: %s\n", strerror(errno));
        return -1;
    }
    unsigned char val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return val;
}

static int set_led_color(int red, int green, int blue) {
    if (i2c_write_byte(RGB_LED_PIN_RED, red) < 0) return -1;
    if (i2c_write_byte(RGB_LED_PIN_GREEN, green) < 0) return -1;
    if (i2c_write_byte(RGB_LED_PIN_BLUE, blue) < 0) return -1;
    return 0;
}

static int read_cpu_load(int *load) {
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        fprintf(stderr, "Failed to open /proc/stat: %s\n", strerror(errno));
        return -1;
    }
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        if (strncmp(line, "cpu", 3) == 0) {
            char *endptr;
            long load_val = strtol(line + 4, &endptr, 10);
            if (endptr == line + 4) {
                *load = (int)load_val;
                return 0;
            }
        }
    }
    fclose(fp);
    fprintf(stderr, "CPU load not found in /proc/stat\n");
    return -1;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    int red_val = 0, green_val = 0, blue_val = 0;
    int prev_red = 0, prev_green = 0, prev_blue = 0;

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, RGB_LED_PIN_RED) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", RGB_LED_PIN_RED, strerror(errno));
        close(fd);
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, RGB_LED_PIN_GREEN) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", RGB_LED_PIN_GREEN, strerror(errno));
        close(fd);
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, RGB_LED_PIN_BLUE) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", RGB_LED_PIN_BLUE, strerror(errno));
        close(fd);
        return 1;
    }

    while (running) {
        int cpu_load = read_cpu_load(&cpu_load);
        if (cpu_load < 0) {
            fprintf(stderr, "Failed to read CPU load, retrying in %d ms...\n", SAMPLE_INTERVAL_MS);
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }

        int red = cpu_load * PWM_RANGE;
        int green = (cpu_load - 50) * PWM_RANGE;
        int blue = (cpu_load - 100) * PWM_RANGE;

        if (set_led_color(red, green, blue) < 0) {
            fprintf(stderr, "Failed to set LED color\n");
        }

        prev_red = red;
        prev_green = green;
        prev_blue = blue;

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    close(fd);
    return 0;
}

