/*
 * BMP280 Temperature & Pressure Sensor Reader & UDP Broadcaster
 * Board:  Raspberry Pi 4 Model B
 * Sensor: Bosch BMP280 (I2C address 0x76 on SDA=GPIO2, SCL=GPIO3)
 * Library: pigpio (modern I2C API)
 *
 * Build:  gcc -O2 -Wall -o bmp280_udp bmp280_udp.c -lpigpio -lrt
 * Run:    sudo ./bmp280_udp
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <pigpio.h>

#define BMP280_ADDR          0x76
#define I2C_BUS              1
#define UDP_HOST             "192.168.1.100"
#define UDP_PORT             5000
#define MEASUREMENT_DELAY_US 200000   /* 200 ms */
#define SAMPLE_INTERVAL_S    5

/* BMP280 register map (datasheet) */
#define BMP280_REG_CONTROL   0xF4
#define BMP280_REG_MSB       0xF6
#define BMP280_REG_XLSB      0xF7
#define BMP280_REG_CAL_AC1   0x88
#define BMP280_REG_CAL_AC2   0x8A
#define BMP280_REG_CAL_AC3   0x8C
#define BMP280_REG_CAL_AC4   0x8E
#define BMP280_REG_CAL_AC5   0x90
#define BMP280_REG_CAL_AC6   0x92
#define BMP280_REG_CAL_AC7   0x94
#define BMP280_REG_CAL_BC1   0x96
#define BMP280_REG_CAL_BC2   0x98
#define BMP280_REG_CAL_BC3   0x9A
#define BMP280_REG_CAL_BC4   0x9C
#define BMP280_REG_CAL_BC5   0x9E
#define BMP280_REG_CAL_BC6   0xA0
#define BMP280_REG_CAL_BC7   0xA2
#define BMP280_REG_PRESS_MSB 0xA4
#define BMP280_REG_TEMP_MSB  0xA6

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static int g_udp_socket = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg(uint8_t reg, uint8_t val)
{
    if (i2cWriteByteData(g_i2c_handle, reg, val) < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(g_i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* BMP280 calibration                                                 */
/* ------------------------------------------------------------------ */
static int read_calibration(int handle)
{
    uint8_t buf[24];
    if (i2c_read_reg(BMP280_REG_CAL_AC1, buf) < 0)
        return -1;
    if (i2c_read_reg(BMP280_REG_CAL_AC2, buf) < 0)
        return -1;
    if (i2c_read_reg(BMP280_REG_CAL_AC3, buf) < 0)
        return -1;
    if (i2c_read_reg(BMP280_REG_CAL_AC4, buf) < 0)
        return -1;
    if (i2c_read_reg(BMP280_REG_CAL_AC5, buf) < 0)
        return -1;
    if (i2c_read_reg(BMP280_REG_CAL_AC6, buf) < 0)
        return -1;
    if (i2c_read_reg(BMP280_REG_CAL_AC7, buf) < 0)
        return -1;
    if (i2c_read_reg(BMP280_REG_CAL_BC1, buf) < 0)
        return -1;
    if (i2c_read_reg(BMP280_REG_CAL_BC2, buf) < 0)
        return -1;
    if (i2c_read_reg(BMP280_REG_CAL_BC3, buf) < 0)
        return -1;
    if (i2c_read_reg(BMP280_REG_CAL_BC4, buf) < 0)
        return -1;
    if (i2c_read_reg(BMP280_REG_CAL_BC5, buf) < 0)
        return -1;
    if (i2c_read_reg(BMP280_REG_CAL_BC6, buf) < 0)
        return -1;
    if (i2c_read_reg(BMP280_REG_CAL_BC7, buf) < 0)
        return -1;
    memcpy(cal_ac1, buf, 2);
    memcpy(cal_ac2, buf + 2, 2);
    memcpy(cal_ac3, buf + 4, 2);
    memcpy(cal_ac4, buf + 6, 2);
    memcpy(cal_ac5, buf + 8, 2);
    memcpy(cal_ac6, buf + 10, 2);
    memcpy(cal_ac7, buf + 12, 2);
    memcpy(cal_bc1, buf + 14, 2);
    memcpy(cal_bc2, buf + 16, 2);
    memcpy(cal_bc3, buf + 18, 2);
    memcpy(cal_bc4, buf + 20, 2);
    memcpy(cal_bc5, buf + 22, 2);
    memcpy(cal_bc6, buf + 24, 2);
    memcpy(cal_bc7, buf + 26, 2);
    return 0;
}

/* ------------------------------------------------------------------ */
/* BMP280 conversion                                                   */
/* ------------------------------------------------------------------ */
static int32_t read_raw_temperature(int handle)
{
    uint8_t msb, lsb;
    if (i2c_read_reg(BMP280_REG_PRESS_MSB, &msb) < 0)
        return -1;
    if (i2c_read_reg(BMP280_REG_TEMP_MSB, &lsb) < 0)
        return -1;
    int32_t raw = ((int32_t)msb << 12) | ((int32_t)lsb >> 4);
    return raw;
}

static int32_t read_raw_pressure(int handle)
{
    uint8_t msb, lsb;
    if (i2c_read_reg(BMP280_REG_PRESS_MSB, &msb) < 0)
        return -1;
    if (i2c_read_reg(BMP280_REG_XLSB, &lsb) < 0)
        return -1;
    int32_t raw = ((int32_t)msb << 12) | ((int32_t)lsb >> 4);
    return raw;
}

static int32_t calc_temperature(int32_t raw, int32_t *ac1, int32_t *ac2,
                                int32_t *ac3, int32_t *ac4, int32_t *ac5,
                                int32_t *ac6, int32_t *ac7)
{
    int32_t b1, b2;
    b1 = ((int32_t)ac6 * 6 + c5) >> 2;
    b2 = ((int32_t)ac7 * 2 + c6) >> 2;
    *ac1 = (b1 >> 2) - 512;
    *ac2 = b2 - 400;
    *ac3 = (b1 * b1 * b1) >> 12;
    *ac4 = (b2 * b2 * b2) >> 16;
    *ac5 = (*ac3 + *ac4) >> 8;
    *ac6 = (*ac3 + *ac4) - 16384;
    *ac7 = (*b1 * b2 * b3) >> 13;
    return 0;
}

static int32_t calc_pressure(int32_t raw, int32_t *ac1, int32_t *ac2,
                             int32_t *ac3, int32_t *ac4, int32_t *ac5,
                             int32_t *ac6, int32_t *ac7)
{
    int32_t b5, b6, b7;
    b5 = ((int32_t)ac5 * 2) + 32768;
    b6 = ((int32_t)ac2 * (b5 >> 15)) + 2;
    b7 = ((int32_t)ac1 * b5) >> 15;
    int32_t p;
    p = (b7 + (b6 * 30)) / 100;
    *ac3 = (p - (int32_t)ac6) * (int32_t)ac4 / 32768;
    *ac4 = p - *ac3;
    *ac2 = b6 * 2;
    *ac1 = (int32_t)(p - *ac3) * 50000 / (int32_t)b7;
    return (int32_t)(p - *ac3) * 5 / (int32_t)b7;
}

/* ------------------------------------------------------------------ */
/* UDP send                                                            */
/* ------------------------------------------------------------------ */
static int send_udp_data(int socket, const char *json_str)
{
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(UDP_PORT);
    if (inet_pton(AF_INET, UDP_HOST, &addr.sin_addr) <= 0) {
        fprintf(stderr, "[ERROR] inet_pton(%s, %s) failed\n",
                UDP_HOST, UDP_PORT ? UDP_HOST : "0.0.0.0");
        return -1;
    }
    if (sendto(socket, json_str, strlen(json_str), 0,
               (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "[ERROR] sendto(udp) failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("[ERROR] sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, BMP280_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, BMP280_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open UDP socket */
    g_udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (g_udp_socket < 0) {
        fprintf(stderr, "[ERROR] socket() failed: %s\n", strerror(errno));
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Read calibration */
    if (read_calibration(g_i2c_handle) < 0) {
        fprintf(stderr, "[ERROR] Failed to read BMP280 calibration\n");
        close(g_udp_socket);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("BMP280 UDP listener started. Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        int32_t raw_temp, raw_press;
        int32_t ac1, ac2, ac3, ac4, ac5, ac6, ac7;
        int32_t utc_time;

        /* Read temperature and pressure */
        if (read_raw_temperature(g_i2c_handle) < 0) {
            fprintf(stderr, "[WARN] Temperature read failed; continuing.\n");
        } else if (read_raw_pressure(g_i2c_handle) < 0) {
            fprintf(stderr, "[WARN] Pressure read failed; continuing.\n");
        } else {
            /* Convert to UTC timestamp */
            utc_time = (int32_t)(time(NULL) / 86400) * 86400;

            /* Format as JSON */
            char json_buf[256];
            snprintf(json_buf, sizeof(json_buf),
                     "{\"utc_time\": %ld, \"temperature\": %.2f, \"pressure\": %.2f}",
                     utc_time, (double)raw_temp / 100.0, (double)raw_press / 100.0);

            /* Send UDP packet */
            if (send_udp_data(g_udp_socket, json_buf) < 0) {
                fprintf(stderr, "[WARN] UDP send failed; continuing.\n");
            }
        }

        /* Sleep for sample_interval_s seconds */
        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++)
            sleep(1);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    close(g_udp_socket);
    i2cClose(g_i2c_handle);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

