/*
 * BMP180 I2C sensor reader for Raspberry Pi Zero W
 * Uses pigpio for I2C and GPIO control.
 *
 * Wiring:
 *   BMP180 SDA -> GPIO2 (I2C bus 1 SDA)
 *   BMP180 SCL -> GPIO3 (I2C bus 1 SCL)
 *   BMP180 VDD -> 3.3 V
 *   BMP180 GND -> GND
 *   BMP180 A4  -> GPIO8 (SDA)
 *   BMP180 A5  -> GPIO9 (SCL)
 *   BMP180 A3  -> GND
 *
 * Build: gcc -Wall -o bmp180_logger bmp180_logger.c -lpigpio -lrt
 * Run:   sudo ./bmp180_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define BMP180_ADDR    0x76
#define LOG_FILE       "altitude_log.txt"
#define SAMPLE_INTERVAL_S 1

/* BMP180 register addresses */
#define BMP180_REG_ID      0xAA
#define BMP180_REG_CTRL_MEAS 0xF4
#define BMP180_REG_CONFIG   0xF5
#define BMP180_REG_DATA     0xF6

/* Oversampling settings (OSS=3) */
#define BMP180_OSS_3       0x17

/* Calibration data */
typedef struct {
    uint16_t dig_T1;
    int16_t  dig_T2;
    int16_t  dig_T3;
    uint16_t dig_P1;
    int16_t  dig_P2;
    int16_t  dig_P3;
    int16_t  dig_P4;
    int16_t  dig_P5;
    int16_t  dig_P6;
    int16_t  dig_P7;
    int16_t  dig_P8;
    int16_t  dig_P9;
} bmp180_calib_data;

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Read a single byte from a BMP180 register.
 * Returns 0 on success, -1 on error.
 */
static int read_bmp180_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

/*
 * Write a single byte to a BMP180 register.
 * Returns 0 on success, -1 on error.
 */
static int write_bmp180_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

/*
 * Read calibration data from the BMP180.
 * Returns 0 on success, -1 on error.
 */
static int read_bmp180_calibration(int handle, bmp180_calib_data *cal) {
    uint8_t buf[24];

    if (read_bmp180_register(handle, BMP180_REG_DATA, buf) != 0) {
        return -1;
    }

    cal->dig_T1 = (uint16_t)(buf[0]  | (buf[1]  << 8));
    cal->dig_T2 = (int16_t)(buf[2]  | (buf[3]  << 8));
    cal->dig_T3 = (int16_t)(buf[4]  | (buf[5]  << 8));
    cal->dig_P1 = (uint16_t)(buf[6]  | (buf[7]  << 8));
    cal->dig_P2 = (int16_t)(buf[8]  | (buf[9]  << 8));
    cal->dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    cal->dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    cal->dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    cal->dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    cal->dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    cal->dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    cal->dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));

    return 0;
}

/*
 * Read temperature and pressure using OSS=3.
 * Returns 0 on success, -1 on error.
 */
static int read_bmp180_data(int handle, int32_t *temperature, int32_t *pressure) {
    uint8_t buf[6];

    if (read_bmp180_register(handle, BMP180_REG_CTRL_MEAS, &buf[0]) != 0) {
        return -1;
    }

    /* OSS=3: bit 0 = 0 -> start conversion */
    if (write_bmp180_register(handle, BMP180_REG_CTRL_MEAS, BMP180_OSS_3) != 0) {
        return -1;
    }

    gpioDelay(5000); /* 5 ms */

    if (read_bmp180_register(handle, BMP180_REG_DATA, buf) != 0) {
        return -1;
    }

    *temperature = (int32_t)((buf[0] << 8) | buf[1]);
    *pressure   = (int32_t)((buf[2] << 8) | buf[3]);

    return 0;
}

/*
 * Append a line to the log file.
 */
static void log_data(FILE *fp, int32_t temperature, int32_t pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, pressure);
    fflush(fp);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, BMP180_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,temperature_c,pressure_pa\n");
        fflush(log_file);
    }

    /* Configure GPIO2 as falling-edge interrupt with internal pull-up */
    if (gpioSetMode(2, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO2 as input\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(2, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error setting pull-up on GPIO2\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register interrupt callback for falling edge */
    if (gpioSetAlertFuncEx(2, interrupt_callback, NULL) != 0) {
        fprintf(stderr, "Error setting alert function on GPIO2\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not register SIGINT handler\n");
    }

    printf("BMP180 logger started. Logging to %s every %d s. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_INTERVAL_S);

    /* Main loop */
    while (running) {
        int32_t temperature, pressure;

        if (read_bmp180_data(i2c_handle, &temperature, &pressure) == 0) {
            log_data(log_file, temperature, pressure);
            printf("Temperature: %.2f C, Pressure: %.2f Pa\n", temperature, pressure);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        /* Sleep for SAMPLE_INTERVAL_S seconds, checking running flag every second */
        for (int i = 0; i < SAMPLE_INTERVAL_S && running; i++) {
            gpioDelay(1000000); /* 1 second */
        }
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

