        .rx_buf        = (unsigned long)rx,
        .len           = 2,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs   = SPI_DELAY_US,
        .cs_change     = 0,
    };

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    *val = (uint8_t)rx[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit big-endian word from a MAX31865 register.              */
/* Returns 0 on success, -1 on SPI error.                               */
/* ------------------------------------------------------------------ */
static int spi_read_word(uint8_t reg, uint16_t *out)
{
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 2,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs   = SPI_DELAY_US,
        .cs_change     = 0,
    };

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    *out = ((uint16_t)rx[1] << 8) | rx[0];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the Callendar-Van Dusen temperature.                            */
/* Returns 0 on success, -1 on SPI error.                               */
/* ------------------------------------------------------------------ */
static int read_max31865(float *temp_out)
{
    uint8_t status = 0;
    uint16_t raw;

    if (spi_read_reg(REG_STATUS, &status) < 0)
        return -1;

    if (status & 0x01) {
        fprintf(stderr, "MAX31865 fault: status=0x%02X\n", status);
        return -1;
    }

    if (spi_read_word(REG_TEMP_MSB, &raw) < 0)
        return -1;

    /*
     * The MAX31865 returns the temperature in microdegrees Celsius.
     * The Callendar-Van Dusen equation requires the raw value in
     * microdegrees Celsius (T_raw) and the bias voltage (V_bias).
     * The raw value is the ADC count divided by the conversion factor.
     */
    float t_raw = (float)raw / (float)c6;
    *temp_out = c0 + c1 * t_raw + c2 * t_raw * t_raw +
                c3 * t_raw * t_raw * t_raw +
                c4 * t_raw * t_raw * t_raw * t_raw +
                c5 * t_raw * t_raw * t_raw * t_raw +
                c6 * t_raw * t_raw * t_raw * t_raw;
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float temp, const char *op)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%s\n", ts, temp, op);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
