/*
 * BME280 Temperature, Humidity, Pressure Logger for Raspberry Pi Zero W
 * Uses pigpio for I2C communication.
 *
 * Wiring:
 *   BME280 SDA -> GPIO2 (I2C1 SDA)
 *   BME280 SCL -> GPIO3 (I2C1 SCL)
 *   BME280 VDD -> 3.3 V
 *   BME280 GND -> GND
 *
 * Build: gcc -O2 -Wall -o bme280_logger bme280_logger.c -lpigpio -lrt
 * Run:   sudo ./bme280_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BME280_ADDR          0x76
#define BME280_CHIP_ID       0x58
#define BME280_RESET_CMD     0xB6
#define BME280_REG_ID        0xD0
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_CTRL_ME  0xF4
#define BME280_REG_CTRL_P   0xF5
#define BME280_REG_PRESS_MSB 0xF7
#define BME280_REG_TEMP_MSB  0xFA
#define BME280_REG_HUM_MSB   0xFD

#define LOG_FILE "bme280_log.csv"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int handle, uint8_t reg, uint8_t *value) {
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(handle, reg_buf, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, (char *)value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

static int i2c_read_word(int handle, uint8_t reg, uint16_t *value) {
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(handle, reg_buf, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed\n", reg);
        return -1;
    }
    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed\n", reg);
        return -1;
    }
    *value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int bme280_init(int handle) {
    uint8_t chip_id;
    if (i2c_read_byte(handle, BME280_REG_ID, &chip_id) != 0) {
        fprintf(stderr, "Failed to read BME280 chip ID\n");
        return -1;
    }
    if (chip_id != BME280_CHIP_ID) {
        fprintf(stderr, "BME280 chip ID mismatch: got 0x%02X, expected 0x%02X\n",
                chip_id, BME280_CHIP_ID);
        return -1;
    }

    if (i2c_write_byte(handle, BME280_REG_CTRL_HUM, 0x01) != 0) {
        fprintf(stderr, "Failed to set HUM_CTRL\n");
        return -1;
    }
    if (i2c_write_byte(handle, BME280_REG_CTRL_ME, 0x01) != 0) {
        fprintf(stderr, "Failed to set ME_CTRL\n");
        return -1;
    }
    if (i2c_write_byte(handle, BME280_REG_CTRL_P, 0x01) != 0) {
        fprintf(stderr, "Failed to set P_CTRL\n");
        return -1;
    }

    if (i2c_write_byte(handle, BME280_REG_PRESS_MSB, 0x00) != 0) {
        fprintf(stderr, "Failed to set PRESS_MSB\n");
        return -1;
    }
    if (i2c_write_byte(handle, BME280_REG_TEMP_MSB, 0x00) != 0) {
        fprintf(stderr, "Failed to set TEMP_MSB\n");
        return -1;
    }
    if (i2c_write_byte(handle, BME280_REG_HUM_MSB, 0x00) != 0) {
        fprintf(stderr, "Failed to set HUM_MSB\n");
        return -1;
    }

    if (i2c_write_byte(handle, BME280_REG_RESET_CMD, 0x01) != 0) {
        fprintf(stderr, "Failed to reset BME280\n");
        return -1;
    }
    gpioDelay(2000);

    uint8_t status;
    if (i2c_read_byte(handle, BME280_REG_ID, &status) != 0) {
        fprintf(stderr, "Failed to read BME280 status\n");
        return -1;
    }
    if (status != BME280_CHIP_ID) {
        fprintf(stderr, "BME280 chip not responding: got 0x%02X, expected 0x%02X\n",
                status, BME280_CHIP_ID);
        return -1;
    }

    return 0;
}

static int bme280_read_data(int handle, float *temperature, float *humidity,
                            float *pressure) {
    uint8_t buf[8];
    if (i2c_read_word(handle, BME280_REG_PRESS_MSB, buf) != 0) {
        return -1;
    }
    int32_t raw_pressure = (int32_t)((buf[0] << 12) | (buf[1] << 4) | (buf[2] >> 4));
    int32_t raw_temp = (int32_t)((buf[3] << 12) | (buf[4] << 4) | (buf[5] >> 4));
    int32_t raw_hum = (int32_t)((buf[6] << 8) | buf[7]);

    *temperature = (float)raw_temp / 16384.0f - 50.0f;
    *humidity = (float)raw_hum / 65536.0f * 100.0f;
    *pressure = (float)raw_pressure / 25600.0f - 60000.0f;

    return 0;
}

static int log_data(FILE *fp, float temperature, float humidity, float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, temperature, humidity, pressure) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(1, BME280_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X: %d\n", BME280_ADDR, g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (bme280_init(g_i2c_handle) != 0) {
        fprintf(stderr, "BME280 initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("Failed to open log file");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    fseek(g_log_fp, 0, SEEK_END);
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "Timestamp,Temperature(C),Humidity(%),Pressure(hPa)\n");
    }

    while (g_running) {
        float temperature, humidity, pressure;
        if (bme280_read_data(g_i2c_handle, &temperature, &humidity, &pressure) == 0) {
            if (log_data(g_log_fp, temperature, humidity, pressure) != 0) {
                fprintf(stderr, "Logging failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000);
    }

    fprintf(stderr, "\nShutting down...\n");
    if (g_log_fp) {
        fclose(g_log_fp);
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return 0;
}

