/*
 * BMP180 Pressure Sensor Monitor for Raspberry Pi 4 Model B
 * Uses pigpio for I2C communication and a hardware timer for 50 ms sampling.
 * Alerts on GPIO24 when pressure deviates by more than 5 hPa from the last 60 s.
 *
 * Build: gcc -Wall -Wextra -O2 -o bmp180_monitor bmp180_monitor.c -lpigpio -lrt
 * Run:   sudo ./bmp180_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR          0x76
#define BMP180_REG_CONTROL   0xF4
#define BMP180_REG_MSB       0xF6
#define BMP180_REG_XLSB      0xF7
#define BMP180_REG_CAL_AC1   0xAA
#define BMP180_REG_CAL_AC2   0xAC
#define BMP180_REG_CAL_AC3   0xAE
#define BMP180_REG_CAL_AC4   0xB0
#define BMP180_REG_CAL_AC5   0xB2
#define BMP180_REG_CAL_AC6   0xB4
#define BMP180_REG_CAL_B1    0xB6
#define BMP180_REG_CAL_B2    0xB8
#define BMP180_REG_CAL_MB    0xBA
#define BMP180_REG_CAL_MC    0xBC
#define BMP180_REG_CAL_MD    0xBE
#define BMP180_REG_CAL_XLSB  0xF7

#define BMP180_CTRL_CALIB    0x2E
#define BMP180_CTRL_CAL_MODE 0x34

#define BMP180_CAL_AC1_INIT  0xAA
#define BMP180_CAL_AC2_INIT  0xAC
#define BMP180_CAL_AC3_INIT  0xAE
#define BMP180_CAL_AC4_INIT  0xB0
#define BMP180_CAL_AC5_INIT  0xB2
#define BMP180_CAL_AC6_INIT  0xB4
#define BMP180_CAL_B1_INIT   0xB6
#define BMP180_CAL_B2_INIT   0xB8
#define BMP180_CAL_MB_INIT   0xBA
#define BMP180_CAL_MC_INIT   0xBC
#define BMP180_CAL_MD_INIT   0xBE

#define ALERT_GPIO 24
#define SAMPLE_INTERVAL_US 50000  /* 50 ms */
#define SAMPLE_PERIOD_US   (SAMPLE_INTERVAL_US * 1000)
#define BUFFER_SIZE        60
#define PRESSURE_THRESHOLD 5.0f
#define PRESSURE_DEVIATION 5.0f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static int g_gpio_initialized = 0;

typedef struct {
    time_t timestamp;
    float pressure;
} PressureSample;

static PressureSample g_pressure_buffer[BUFFER_SIZE];
static int g_pressure_buffer_index = 0;
static int g_pressure_buffer_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int bmp180_write_reg(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "Error: I2C write failed (reg=0x%02X, val=0x%02X)\n", reg, value);
        return -1;
    }
    return 0;
}

static int bmp180_read_reg(int handle, uint8_t reg, uint8_t *value) {
    if (i2cWriteDevice(handle, (char *)&reg, 1) != 0) {
        fprintf(stderr, "Error: I2C select failed (reg=0x%02X)\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, (char *)value, 1) != 1) {
        fprintf(stderr, "Error: I2C read failed (reg=0x%02X)\n", reg);
        return -1;
    }
    return 0;
}

static int bmp180_init(int handle) {
    uint8_t cal_buf[24];
    if (bmp180_read_reg(handle, BMP180_REG_CAL_AC1, cal_buf) != 0) {
        fprintf(stderr, "Error: Failed to read calibration data\n");
        return -1;
    }
    cal_buf[0] = BMP180_CAL_AC1_INIT;
    cal_buf[1] = (cal_buf[1] << 8) | cal_buf[0];
    cal_buf[2] = (cal_buf[2] << 8) | cal_buf[1];
    cal_buf[3] = (cal_buf[3] << 8) | cal_buf[2];
    cal_buf[4] = (cal_buf[4] << 8) | cal_buf[3];
    cal_buf[5] = (cal_buf[5] << 8) | cal_buf[4];
    cal_buf[6] = (cal_buf[6] << 8) | cal_buf[5];
    cal_buf[7] = (cal_buf[7] << 8) | cal_buf[6];
    cal_buf[8] = (cal_buf[8] << 8) | cal_buf[7];
    cal_buf[9] = (cal_buf[9] << 8) | cal_buf[8];
    cal_buf[10] = (cal_buf[10] << 8) | cal_buf[9];
    cal_buf[11] = (cal_buf[11] << 8) | cal_buf[10];
    cal_buf[12] = (cal_buf[12] << 8) | cal_buf[11];
    cal_buf[13] = (cal_buf[13] << 8) | cal_buf[12];
    cal_buf[14] = (cal_buf[14] << 8) | cal_buf[13];
    cal_buf[15] = (cal_buf[15] << 8) | cal_buf[14];

    if (bmp180_write_reg(handle, BMP180_REG_CAL_CALIB, cal_buf[0]) != 0) return -1;
    if (bmp180_write_reg(handle, BMP180_REG_CAL_MODE, BMP180_CAL_MODE_CAL_CONTINUOUS) != 0) return -1;
    gpioDelay(10000); /* 10 ms */

    if (bmp180_read_reg(handle, BMP180_REG_CAL_XLSB, cal_buf) != 0) return -1;
    if (bmp180_read_reg(handle, BMP180_REG_CAL_AC2, cal_buf) != 0) return -1;
    if (bmp180_read_reg(handle, BMP180_REG_CAL_AC3, cal_buf) != 0) return -1;
    if (bmp180_read_reg(handle, BMP180_REG_CAL_AC4, cal_buf) != 0) return -1;
    if (bmp180_read_reg(handle, BMP180_REG_CAL_AC5, cal_buf) != 0) return -1;
    if (bmp180_read_reg(handle, BMP180_REG_CAL_AC6, cal_buf) != 0) return -1;
    if (bmp180_read_reg(handle, BMP180_REG_CAL_B1, cal_buf) != 0) return -1;
    if (bmp180_read_reg(handle, BMP180_REG_CAL_B2, cal_buf) != 0) return -1;
    if (bmp180_read_reg(handle, BMP180_REG_CAL_MB, cal_buf) != 0) return -1;
    if (bmp180_read_reg(handle, BMP180_REG_CAL_MC, cal_buf) != 0) return -1;
    if (bmp180_read_reg(handle, BMP180_REG_CAL_MD, cal_buf) != 0) return -1;

    if (bmp180_write_reg(handle, BMP180_REG_CAL_CALIB, 0x00) != 0) return -1;
    if (bmp180_write_reg(handle, BMP180_REG_CAL_MODE, BMP180_CAL_MODE_CAL_CONTINUOUS) != 0) return -1;
    gpioDelay(10000); /* 10 ms */

    return 0;
}

static int bmp180_read_pressure(int handle, float *pressure) {
    uint8_t msb, lsb;
    if (bmp180_read_reg(handle, BMP180_REG_MSB, &msb) != 0) return -1;
    if (bmp180_read_reg(handle, BMP180_REG_LSB, &lsb) != 0) return -1;
    uint16_t raw = ((uint16_t)msb << 8) | lsb;
    int32_t var1 = (((int32_t)raw) - ((int32_t)BMP180_CAL_AC1)) * ((int32_t)BMP180_CAL_AC2) / 32768;
    int32_t var2 = var1 * ((int32_t)BMP180_CAL_AC3) / 32768;
    int32_t var3 = var2 * ((int32_t)BMP180_CAL_AC4) / 524288;
    int32_t var4 = var3 * ((int32_t)BMP180_CAL_AC5) / 2147483648;
    int32_t var5 = var4 * ((int32_t)BMP180_CAL_AC6) / 4;
    int32_t b5 = var5 + 64;
    *pressure = (float)(b5 + 8) / 16.0f;
    return 0;
}

static void add_pressure_sample(float pressure) {
    g_pressure_buffer[g_pressure_buffer_index].pressure = pressure;
    g_pressure_buffer[g_pressure_buffer_index].timestamp = time(NULL);
    g_pressure_buffer_index = (g_pressure_buffer_index + 1) % BUFFER_SIZE;
    if (g_pressure_buffer_count < BUFFER_SIZE) g_pressure_buffer_count++;
}

static void calculate_average_pressure(void) {
    if (g_pressure_buffer_count == 0) return;
    float sum = 0.0f;
    for (int i = 0; i < g_pressure_buffer_count; i++) {
        sum += g_pressure_buffer[i].pressure;
    }
    float avg = sum / g_pressure_buffer_count;
    printf("Average Pressure: %.2f hPa\n", avg);
}

static void check_pressure_deviation(void) {
    if (g_pressure_buffer_count == 0) return;
    float deviation = fabsf(g_pressure_buffer[0].pressure - avg_pressure);
    if (deviation > PRESSURE_DEVIATION) {
        printf("Pressure deviation: %.2f hPa exceeds threshold %.2f hPa\n", deviation, PRESSURE_THRESHOLD);
        if (gpioWrite(ALERT_GPIO, 1) == 0) {
            printf("Alert: Pressure deviation detected!\n");
        }
    } else {
        printf("Pressure deviation: %.2f hPa below threshold %.2f hPa\n", deviation, PRESSURE_THRESHOLD);
    }
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_gpio_initialized) {
        gpioWrite(ALERT_GPIO, 0);
        gpioTerminate();
        g_gpio_initialized = 0;
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    g_gpio_initialized = 1;

    g_i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (addr=0x%02X)\n", BMP180_ADDR);
        gpioTerminate();
        return 1;
    }

    if (bmp180_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: BMP180 initialisation failed\n");
        cleanup();
        return 1;
    }

    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as output\n", ALERT_GPIO);
        cleanup();
        return 1;
    }
    gpioWrite(ALERT_GPIO, 0);

    printf("BMP180 monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float pressure;
        if (bmp180_read_pressure(g_i2c_handle, &pressure) == 0) {
            add_pressure_sample(pressure);
            calculate_average_pressure();
            check_pressure_deviation();
        } else {
            fprintf(stderr, "Error: Failed to read BMP180 pressure\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

