#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define PWM_GPIO 18
#define PWM_FREQ 25000
#define PWM_RANGE 255
#define LOG_FILE "fan_log.txt"
#define SAMPLE_INTERVAL 5

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int pigpio_initialized = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(void) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", TEMP_FILE, strerror(errno));
        return -1;
    }

    char buf[16];
    if (fgets(buf, sizeof(buf), fp) == NULL) {
        fprintf(stderr, "Error reading %s: %s\n", TEMP_FILE, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    char *endptr;
    long temp_raw = strtol(buf, &endptr, 10);
    if (endptr == buf || *endptr != '\n') {
        fprintf(stderr, "Error parsing temperature from %s: %s\n", TEMP_FILE, strerror(errno));
        return -1;
    }
    return (int)temp_raw;
}

static int map_temperature(int temp) {
    if (temp < 40) return 0;
    if (temp > 70) return PWM_RANGE;
    return (int)((temp - 40) * PWM_RANGE / 30);
}

static int set_pwm(int duty) {
    if (gpioPWM(PWM_GPIO, duty) != 0) {
        fprintf(stderr, "Error setting PWM on GPIO %d: %s\n", PWM_GPIO, strerror(errno));
        return -1;
    }
    return 0;
}

static void log_data(int temp, int duty) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    if (log_file) {
        fprintf(log_file, "%s, Temperature: %d, Duty Cycle: %d\n", timestamp, temp, duty);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file not open.\n");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    pigpio_initialized = 1;

    if (gpioSetMode(PWM_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", PWM_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(PWM_GPIO, PWM_FREQ) != 0) {
        fprintf(stderr, "Error setting PWM frequency on GPIO %d\n", PWM_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(PWM_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Error setting PWM range on GPIO %d\n", PWM_GPIO);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return 1;
    }

    printf("Fan control started. Press Ctrl+C to exit.\n");

    while (running) {
        int temp = read_temperature();
        if (temp < 0) {
            fprintf(stderr, "Error reading temperature, retrying in %d seconds.\n", SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        int duty = map_temperature(temp);
        if (set_pwm(duty) != 0) {
            fprintf(stderr, "Error setting PWM duty cycle.\n");
        }

        log_data(temp, duty);
        printf("Temperature: %d, Duty Cycle: %d\n", temp, duty);

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down...\n");
    set_pwm(0);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

