    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select) for reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select) for reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int init_lm75(int fd)
{
    uint8_t config[6];
    config[0] = LM75_CMD_TEMP_L;
    config[1] = LM75_CMD_TEMP_H;
    config[2] = LM75_CMD_CONFIG;
    config[3] = LM75_CMD_CONFIG_1;
    config[4] = LM75_CMD_CONFIG_2;
    config[5] = LM75_CMD_CONFIG_3;

    if (i2c_write_reg8(fd, REG_CONFIG, config[0]) < 0) return -1;
    if (i2c_write_reg8(fd, REG_CONFIG, config[1]) < 0) return -1;
    if (i2c_write_reg8(fd, REG_CONFIG, config[2]) < 0) return -1;
    if (i2c_write_reg8(fd, REG_CONFIG, config[3]) < 0) return -1;
    if (i2c_write_reg8(fd, REG_CONFIG, config[4]) < 0) return -1;
    if (i2c_write_reg8(fd, REG_CONFIG, config[5]) < 0) return -1;

    /* Allow sensor to settle */
    gpioDelay(100000); /* 100 ms */
    return 0;
}

static int read_temperature(int fd, float *temp_out)
{
    uint8_t buf[2];
    if (i2c_read_reg8(fd, REG_TEMP_L, buf) < 0) return -1;
    uint16_t raw = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    *temp_out = (float)raw / 10.0f;
    return 0;
}

static void update_buffer(float temp)
{
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    struct timespec ts_elapsed;
    clock_gettime(CLOCK_MONOTONIC, &ts_elapsed);
    long elapsed_ms = (ts_elapsed.tv_sec - ts.tv_sec) * 1000L +
                      (ts_elapsed.tv_nsec - ts.tv_nsec) / 1000000L;

    if (elapsed_ms > POLL_INTERVAL) {
        float temp_c = (float)raw / 10.0f;
        if (temp_c > TEMP_THRESHOLD) {
