int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_led_on = 0;
    g_i2c_fd = -1;

    if (init_lm75(g_i2c_fd) < 0) {
        fprintf(stderr, "LM75 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    printf("LM75 monitoring started on I2C bus %d, LED on GPIO %d\n", I2C_BUS, LED_GPIO);

    while (g_running) {
        float temp;
        if (read_temperature(g_i2c_fd, &temp) < 0) {
            fprintf(stderr, "Temperature read failed; continuing\n");
        } else {
            update_buffer(temp);
        }
        gpioDelay(POLL_INTERVAL * 1000000); /* microseconds */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

