/*
 * BMP180 temperature & pressure logger for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   BMP180 SDA -> GPIO2 (pin 3)
 *   BMP180 SCL -> GPIO3 (pin 5)
 *   BMP180 VDD -> 3.3 V
 *   BMP180 GND -> GND
 *   Fan control -> GPIO18 (active-high)
 *
 * Build:  gcc -O2 -Wall -Wextra -o bmp180_logger bmp180_logger.c -lmpideepio
 * Run:    sudo ./bmp180_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        1
#define BMP180_ADDR    0x76
#define FAN_GPIO       18
#define TEMP_THRESHOLD 30.0f
#define BUFFER_SIZE    60
#define SAMPLE_INTERVAL_US 500000  /* 500 ms */

/* BMP180 calibration constants (from datasheet) */
#define BMP180_CAL_AC1  0xAA11  /* 0xAA11 = 0x55 */
#define BMP180_CAL_AC2  0x6D    /* 0x6D  = 0x3B */
#define BMP180_CAL_AC3  0x99    /* 0x99  = 0xDB */
#define BMP180_CAL_AC4  0xD1    /* 0xD1  = 0x8D */
#define BMP180_CAL_AC5  0xBF    /* 0xBF  = 0x8B */
#define BMP180_CAL_AC6  0xE5    /* 0xE5  = 0x8D */
#define BMP180_CAL_B1   0x2E    /* 0x2E  = 0xDB */
#define BMP180_CAL_B2   0x44    /* 0x44  = 0x8B */
#define BMP180_CAL_MB   0x2F    /* 0x2F  = 0xDB */
#define BMP180_CAL_MC   0x30    /* 0x30  = 0x8D */
#define BMP180_CAL_MD   0x21    /* 0x21  = 0xDB */

#define BMP180_REG_CONTROL 0xFA
#define BMP180_REG_MSB     0xF7
#define BMP180_REG_XLSB    0xF7
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0x6D
#define BMP180_REG_CAL_AC3 0x99
#define BMP180_REG_CAL_AC4 0xD1
#define BMP180_REG_CAL_AC5 0xBF
#define BMP180_REG_CAL_AC6 0xE5
#define BMP180_REG_CAL_B1  0x2E
#define BMP180_REG_CAL_B2  0x44
#define BMP180_REG_CAL_MB  0x2F
#define BMP180_REG_CAL_MC  0x30
#define BMP180_REG_CAL_MD  0x21

#define BMP180_REG_PRESSURE 0xF4
#define BMP180_REG_TEMP     0xF6

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, uint32_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (int)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* BMP180 calibration                                                 */
/* ------------------------------------------------------------------ */
static int read_calibration(int fd, uint16_t *ac1, uint16_t *ac2,
                            uint16_t *ac3, uint16_t *ac4,
                            uint16_t *ac5, uint16_t *ac6)
{
    uint8_t buf[24];

    if (i2c_read_block(fd, BMP180_REG_CAL_AC1, buf, sizeof(buf)) != 0)
        return -1;
    *ac1 = (uint16_t)((buf[0] << 8) | buf[1]);

    if (i2c_read_block(fd, BMP180_REG_CAL_AC2, buf, sizeof(buf)) != 0)
        return -1;
    *ac2 = (uint16_t)((buf[0] << 8) | buf[1]);

    if (i2c_read_block(fd, BMP180_REG_CAL_AC3, buf, sizeof(buf)) != 0)
        return -1;
    *ac3 = (uint16_t)((buf[0] << 8) | buf[1]);

    if (i2c_read_block(fd, BMP180_REG_CAL_AC4, buf, sizeof(buf)) != 0)
        return -1;
    *ac4 = (uint16_t)((buf[0] << 8) | buf[1]);

    if (i2c_read_block(fd, BMP180_REG_CAL_AC5, buf, sizeof(buf)) != 0)
        return -1;
    *ac5 = (uint16_t)((buf[0] << 8) | buf[1]);

    if (i2c_read_block(fd, BMP180_REG_CAL_AC6, buf, sizeof(buf)) != 0)
        return -1;
    *ac6 = (uint16_t)((buf[0] << 8) | buf[1]);

    if (i2c_read_block(fd, BMP180_REG_CAL_B1, buf, sizeof(buf)) != 0)
        return -1;
    *b1 = (uint16_t)((buf[0] << 8) | buf[1]);

    if (i2c_read_block(fd, BMP180_REG_CAL_B2, buf, sizeof(buf)) != 0)
        return -1;
    *b2 = (uint16_t)((buf[0] << 8) | buf[1]);

    if (i2c_read_block(fd, BMP180_REG_CAL_MB, buf, sizeof(buf)) != 0)
        return -1;
    *mb = (uint16_t)((buf[0] << 8) | buf[1]);

    if (i2c_read_block(fd, BMP180_REG_CAL_MC, buf, sizeof(buf)) != 0)
        return -1;
    *mc = (uint16_t)((buf[0] << 8) | buf[1]);

    if (i2c_read_block(fd, BMP180_REG_CAL_MD, buf, sizeof(buf)) != 0)
        return -1;
    *md = (uint16_t)((buf[0] << 8) | buf[1]);

    return 0;
}

/* ------------------------------------------------------------------ */
/* BMP180 temperature                                                  */
/* ------------------------------------------------------------------ */
static int read_temperature(int fd, float *temp_out)
{
    uint8_t buf[3];

    if (i2c_read_block(fd, BMP180_REG_PRESSURE, buf, sizeof(buf)) != 0)
        return -1;

    int32_t raw_ut = ((int32_t)buf[0] << 12) | ((int32_t)buf[1] << 4) |
                     ((int32_t)buf[2] >> 4);

    int32_t var1 = ((((raw_ut - (int32_t)ac6) * (int32_t)mc) >> 15) +
                    ((int32_t)md));
    int32_t var2 = ((int32_t)b2 * ((int32_t)var1 >> 11)) >> 11;
    int32_t t_fine = var1 - var2;

    *temp_out = (float)t_fine / 100.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Fan control                                                         */
/* ------------------------------------------------------------------ */
static void control_fan(float temp)
{
    if (temp > TEMP_THRESHOLD) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            printf("Fan ON (temp %.1f C)\n", temp);
        } else {
            fprintf(stderr, "Failed to turn on fan: %s\n", strerror(errno));
        }
    } else {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            printf("Fan OFF\n");
        } else {
            fprintf(stderr, "Failed to turn off fan: %s\n", strerror(errno));
        }
    }
}

/* ------------------------------------------------------------------ */
