    long elapsed_ms = (ts_elapsed.tv_sec - ts.tv_sec) * 1000L +
                      (ts_elapsed.tv_nsec - ts.tv_nsec) / 1000000L;

    fprintf(stdout, "%s.%03ld Temp: %.2f C | Fan: %s\n",
            ts_buf, ts.tv_nsec / 1000000L, temp, fan_on ? "ON" : "OFF");
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C --- */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                BMP180_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Calibration --- */
    uint16_t ac1, ac2, ac3, ac4, ac5, ac6, b1, b2, mb, mc, md;
    if (read_calibration(g_i2c_fd, &ac1, &ac2, &ac3, &ac4,
                         &ac5, &ac6, &b1, &b2, &mb, &mc, &md) != 0) {
        fprintf(stderr, "Failed to read BMP180 calibration data\n");
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- GPIO --- */
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0);

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("BMP180 logger started. Sampling every %d ms. Ctrl+C to exit.\n",
           SAMPLE_INTERVAL_US / 1000);

    /* --- Main loop --- */
    while (g_running) {
        float temp;
        if (read_temperature(g_i2c_fd, &temp) == 0) {
            control_fan(temp);
            add_reading(temp, (int)gpioRead(FAN_GPIO));
        } else {
            fprintf(stderr, "Failed to read temperature; skipping fan control.\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
