 *
 * Hardware:
 *   MAX31855 on SPI0 CE0 (GPIO8, MOSI, MISO, SCLK)
 *   Solid-state relay on GPIO17 (PWM)
 *   Heater resistance (e.g., 100 Ω)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o heater_control heater_control.c -lm
 *
 * Run:
 *   ./heater_control [target_temp_C] [max_duty_percent]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE        "/dev/spidev0.0"
#define SPI_SPEED_HZ      2000000U
#define SPI_BITS_PER_WORD 8U
#define SPI_MODE          0U
#define MAX31855_CS_PIN   8
#define HEATER_PIN        17
#define LOG_FILE          "heater_log.csv"
#define DEFAULT_TEMP      25.0f
#define DEFAULT_MAX_DUTY  80
#define MAX_DUTY_PERCENT   80.0f
#define MAX_DUTY_ERROR_PERCENT 100.0f
#define MAX_DUTY_ERROR_DUTY 0.0f

#define SPI_TIMEOUT_US   50000U
#define SPI_READ_TIMEOUT_US 100000U

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single byte from the MAX31855.
 * Returns 0 on success, -1 on SPI error.
 */
static int max31855_read_byte(int fd)
{
    uint8_t tx[2] = { 0x00, 0x00 };
    uint8_t rx[2] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 2,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        return -1;
    }
    return (rx[1] & 0x0F) << 8 | rx[0];
}

/*
 * Read the temperature from the MAX31855.
 * Returns 0 on success, -1 on SPI error.
 */
static int max31855_read_temperature(int fd, float *temp_out)
{
    uint8_t tx[2] = { 0x00, 0x00 };
    uint8_t rx[2] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 2,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        return -1;
    }

    uint16_t raw = ((uint16_t)rx[1] << 8) | rx[0];
    *temp_out = (float)raw / 10.0f;
    return 0;
}

/*
 * Drive the relay PWM signal.
 * duty_percent: 0-100, duty_error: 0-100.
 * duty_error_percent: 0-100.
 */
static void drive_relay(int duty_percent, float duty_error, float target_temp)
{
    if (duty_percent < 0) duty_percent = 0;
    if (duty_percent > 100) duty_percent = 100;
    if (duty_error < 0) duty_error = 0;
