#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>

#include <gpiod.h>

#define RED_PIN      17
#define GREEN_PIN    18
#define BLUE_PIN     27
#define TEMP_FILE    "cpu_temp.txt"
#define PWM_RANGE    255
#define PWM_DUTY     255
#define TEMP_THRESHOLD_LOW  40000
#define TEMP_THRESHOLD_HIGH 60000
#define LOOP_DELAY_US     500000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_led_color(struct gpiod_line *red, struct gpiod_line *green, struct gpiod_line *blue, int duty)
{
    if (gpiod_line_set_value(red, duty) < 0) {
        fprintf(stderr, "Error: failed to set red GPIO %d: %s\n", RED_PIN, strerror(errno));
        return -1;
    }
    if (gpiod_line_set_value(green, duty) < 0) {
        fprintf(stderr, "Error: failed to set green GPIO %d: %s\n", GREEN_PIN, strerror(errno));
        return -1;
    }
    if (gpiod_line_set_value(blue, duty) < 0) {
        fprintf(stderr, "Error: failed to set blue GPIO %d: %s\n", BLUE_PIN, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_temperature(float *temp_out)
{
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error: cannot open %s: %s\n", TEMP_FILE, strerror(errno));
        return -1;
    }

    if (ferror(fp)) {
        fprintf(stderr, "Error: %s: %s\n", TEMP_FILE, strerror(errno));
        fclose(fp);
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error: %s: %s\n", TEMP_FILE, strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);

    char *endptr;
    long val = strtol(line, &endptr, 10);
    if (endptr == line || *endptr != '\n') {
        fprintf(stderr, "Error: invalid temperature format in %s\n", TEMP_FILE);
        return -1;
    }

    *temp_out = (float)val / 1000.0f;
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *red_line = NULL, *green_line = NULL, *blue_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to install signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: cannot open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    red_line = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);
    if (!red_line || !green_line || !blue_line) {
        fprintf(stderr, "Error: cannot get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(red_line, "cpu_led", 0) < 0 ||
        gpiod_line_request_output(green_line, "cpu_led", 0) < 0 ||
        gpiod_line_request_output(blue_line, "cpu_led", 0) < 0) {
        fprintf(stderr, "Error: cannot request GPIO lines as output: %s\n", strerror(errno));
        goto cleanup;
    }

    while (g_running) {
        float temp;
        if (read_temperature(&temp) == 0) {
            int red_duty = (int)((temp - TEMP_THRESHOLD_LOW) * PWM_RANGE / (TEMP_THRESHOLD_HIGH - TEMP_THRESHOLD_LOW));
            int green_duty = (int)((temp - TEMP_THRESHOLD_LOW) * PWM_RANGE / (TEMP_THRESHOLD_HIGH - TEMP_THRESHOLD_LOW));
            int blue_duty = (int)((temp - TEMP_THRESHOLD_LOW) * PWM_RANGE / (TEMP_THRESHOLD_HIGH - TEMP_THRESHOLD_LOW));

            if (set_led_color(red_line, green_line, blue_line, red_duty) < 0) {
                fprintf(stderr, "Error: failed to set LED color\n");
            } else {
                printf("Temperature: %.2f °C, Red: %d, Green: %d, Blue: %d\n", temp, red_duty, green_duty, blue_duty);
            }
        } else {
            fprintf(stderr, "Warning: temperature read failed, skipping update cycle\n");
        }

        usleep(LOOP_DELAY_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (red_line) gpiod_line_release(red_line);
    if (green_line) gpiod_line_release(green_line);
    if (blue_line) gpiod_line_release(blue_line);
    if (chip) gpiod_chip_close(chip);

    return ret;
}

