    if (gpiod_line_request_output(red_line, "cpu_led", 0) < 0 ||
        gpiod_line_request_output(green_line, "cpu_led", 0) < 0 ||
        gpiod_line_request_output(blue_line, "cpu_led", 0) < 0) {
        fprintf(stderr, "Error: cannot request GPIO lines as output: %s\n", strerror(errno));
        goto cleanup;
    }

    while (g_running) {
        float temp;
        if (read_temperature(&temp) == 0) {
            int red_duty = (int)((temp - TEMP_THRESHOLD_LOW) * PWM_RANGE / (TEMP_THRESHOLD_HIGH - TEMP_THRESHOLD_LOW));
            int green_duty = (int)((temp - TEMP_THRESHOLD_LOW) * PWM_RANGE / (TEMP_THRESHOLD_HIGH - TEMP_THRESHOLD_LOW));
            int blue_duty = (int)((temp - TEMP_THRESHOLD_LOW) * PWM_RANGE / (TEMP_THRESHOLD_HIGH - TEMP_THRESHOLD_LOW));

            if (set_led_color(red_line, green_line, blue_line, red_duty) < 0) {
                fprintf(stderr, "Error: failed to set LED color\n");
            } else {
                printf("Temperature: %.2f °C, Red: %d, Green: %d, Blue: %d\n", temp, red_duty, green_duty, blue_duty);
            }
        } else {
            fprintf(stderr, "Warning: temperature read failed, skipping update cycle\n");
        }

        usleep(LOOP_DELAY_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (red_line) gpiod_line_release(red_line);
    if (green_line) gpiod_line_release(green_line);
    if (blue_line) gpiod_line_release(blue_line);
    if (chip) gpiod_chip_close(chip);

    return ret;
}

