#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define DHT22_PIN 4
#define DHT22_SERVER "http://yourserver.com/api/humidity"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define TIMEOUT_MS 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int dht22_read(int pin, float *humidity, float *temperature) {
    unsigned char data[5];
    int retries = 0;
    int timeout_count = 0;

    while (retries < MAX_RETRIES) {
        gpioWrite(pin, PI_LOW);
        gpioDelay(2000);
        gpioWrite(pin, PI_HIGH);
        gpioDelay(2000);

        if (gpioRead(pin) == PI_HIGH) {
            gpioDelay(TIMEOUT_MS * 1000);
            if (gpioRead(pin) == PI_HIGH) {
                int bits = 0;
                for (int i = 0; i < 8; i++) {
                    if (gpioRead(pin) == PI_HIGH) {
                        bits |= (1 << i);
                    }
                }
                if (bits == 0x80) {
                    if (humidity) *humidity = (float)bits / 16.0f;
                    if (temperature) *temperature = (float)(bits >> 8) / 10.0f;
                    return 0;
                }
            }
        }
        retries++;
        timeout_count++;
        if (timeout_count > MAX_RETRIES * RETRY_DELAY_MS) {
            fprintf(stderr, "DHT22 read timeout on pin %d\n", pin);
            return -1;
        }
    }
    return -1;
}

static int send_http_request(const char *url, const char *json_data) {
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("socket");
        return -1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(80);
    if (inet_pton(AF_INET, DHT22_SERVER, &addr.sin_addr) <= 0) {
        perror("inet_pton");
        close(sock);
        return -1;
    }

    if (connect(sock, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("connect");
        close(sock);
        return -1;
    }

    if (send(sock, json_data, strlen(json_data), 0) < 0) {
        perror("send");
        close(sock);
        return -1;
    }

    if (close(sock) < 0) {
        perror("close");
        return -1;
    }

    return 0;
}

static int get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", timeinfo) == 0) {
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(DHT22_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set DHT22 pin mode\n");
        gpioTerminate();
        return 1;
    }

    float humidity = 0.0f, temperature = 0.0f;
    int retries = 0;
    int consecutive_errors = 0;

    while (running) {
        if (dht22_read(DHT22_PIN, &humidity, &temperature) == 0) {
            consecutive_errors = 0;
            if (get_timestamp(buf, sizeof(buf)) == 0) {
                if (send_http_request(DHT22_SERVER, buf) == 0) {
                    printf("Humidity: %.2f%%  Temperature: %.2f°C\n", humidity, temperature);
                } else {
                    fprintf(stderr, "HTTP request failed\n");
                }
            } else {
                fprintf(stderr, "Failed to get timestamp\n");
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "DHT22 read failed (attempt %d/%d)\n", retries + 1, MAX_RETRIES);
            if (consecutive_errors >= MAX_RETRIES) {
                fprintf(stderr, "Max retries reached, exiting\n");
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                gpioDelay(RETRY_DELAY_MS * 1000);
            }
        }
        gpioDelay(50000);
    }

    gpioTerminate();
    return 0;
}

