/*
 * PID-controlled resistive heater PWM on Raspberry Pi Zero W.
 *
 * Hardware PWM on GPIO18 (pin 11) at 1 kHz, duty range 0–100 %,
 * SPI0 CLK=GPIO11, CS=GPIO8/CE0, DO=GPIO9.
 *
 * Logs every second to heater_log.txt:
 *   [timestamp]   temperature   duty_cycle   pid_error
 *
 * PID defaults: Kp=1.0, Ki=0.1, Kd=0.01.
 * Failsafe: temperature > 100 °C or < 0 °C disables the heater.
 *
 * Build:  gcc -O2 -Wall -Wextra -o heater_pid heater_pid.c -lpigpio -lrt
 * Run:    sudo ./heater_pid
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HEATER_PIN        18
#define SPI_CHANNEL       0
#define SPI_SPEED_HZ      500000
#define SPI_FLAGS         0
#define PWM_FREQUENCY     1000
#define PWM_RANGE         100
#define PID_KP            1.0
#define PID_KI            0.1
#define PID_KD            0.01
#define HEATER_FALLBACK   100.0
#define HEATER_MAX        100.0
#define HEATER_MIN        0.0
#define HEATER_SAMPLE_US  1000000   /* 1 s */
#define LOG_FILE          "heater_log.txt"
#define MAX_FAULT_BITS    4
#define MAX_FAULT_VAL     0x7FFF

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */
static int spi_init(void)
{
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED_HZ, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (handle=%d)\n", g_spi_handle);
        return -1;
    }
    return 0;
}

static void spi_close(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
}

/* ------------------------------------------------------------------ */
/* MAX31855 fault bit parsing                                          */
/* ------------------------------------------------------------------ */
static bool is_fault(uint16_t raw)
{
    /* Open-circuit: bit 0 (0x0001) */
    if (raw & 0x0001)
        return true;

    /* Short-to-GND: bit 1 (0x0002) */
    if (raw & 0x0002)
        return true;

    /* Short-to-VCC: bit 2 (0x0004) */
    if (raw & 0x0004)
        return true;

    return false;
}

/* ------------------------------------------------------------------ */
/* PID controller                                                      */
/* ------------------------------------------------------------------ */
static void pid_init(void)
{
    /*
     * Initialize PID with default gains.
     * The integral term is reset to zero on each startup.
     */
    double integral = 0.0;
    double prev_error = 0.0;
    double last_error = 0.0;
    double integral_term = 0.0;
    double derivative_term = 0.0;
    double output = 0.0;
    double error = 0.0;
    int   i_count = 0;
    int   d_count = 0;
}

static void pid_update(double error, double dt)
{
    double p = PID_KP * error;
    double i = PID_KI * (error - last_error) + integral_term;
    double d = PID_KD * (error - last_error) + derivative_term;

    integral += i * dt;
    last_error = error;

    double output = p + i + d;

    if (output < 0.0) output = 0.0;
    if (output > PWM_RANGE) output = PWM_RANGE;

    double duty = (double)output * PWM_RANGE / PWM_FREQUENCY;
    if (duty < 0.0) duty = 0.0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;

    /* Clamp duty to valid range */
    if (duty < 0.0) duty = 0.0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;

    /* Disable heater on fault */
    if (is_fault(error)) {
        gpioPWM(HEATER_PIN, 0);
        return;
    }

    /* Disable heater on failsafe */
    if (error > HEATER_FALLBACK) {
        gpioPWM(HEATER_PIN, 0);
        return;
    }

    /* Update integral and derivative terms */
    integral_term += (error - prev_error) * dt;
    d_count++;
    if (d_count >= MAX_FAULT_COUNT) {
        d_count = 0;
        integral_term = 0.0;
    }

    prev_error = error;
    output = p + i + d;

    /* Clamp output to valid range */
    if (output < 0.0) output = 0.0;
    if (output > PWM_RANGE) output = PWM_RANGE;

    /* Disable heater on fault */
    if (is_fault(error)) {
        gpioPWM(HEATER_PIN, 0);
        return;
    }

    /* Disable heater on failsafe */
    if (error > HEATER_FALLBACK) {
        gpioPWM(HEATER_PIN, 0);
        return;
    }

    /* Update PID state */
    double error_sum = error - last_error;
    last_error = error;

    /* Integrate error over time */
    integral += error_sum * dt;

    /* Compute derivative */
    double derivative = (error - prev_error) / dt;

    /* Compute PID output */
    double control = PID_KP * error + PID_KI * integral_term + PID_KD * derivative;

    /* Clamp output to valid range */
    if (control < 0.0) control = 0.0;
    if (control > PWM_RANGE) control = PWM_RANGE;

    /* Disable heater on fault */
    if (is_fault(error)) {
        gpioPWM(HEATER_PIN, 0);
        return;
    }

    /* Disable heater on failsafe */
    if (error > HEATER_FALLBACK) {
        gpioPWM(HEATER_PIN, 0);
        return;
    }

    /* Update PID state */
    integral_term = PID_KI * (error - prev_error) + PID_KD * derivative_term;
    prev_error = error;
    d_count = 0;
    integral_term = 0.0;
    output = control;
    last_error = error;
    i_count = 0;
    d_count = 0;
}

/* ------------------------------------------------------------------ */
/* Heater control                                                     */
/* ------------------------------------------------------------------ */
static void heater_control(double temperature)
{
    double duty = (temperature - HEATER_MIN) / (HEATER_MAX - HEATER_MIN) * PWM_RANGE;
    if (duty < 0.0) duty = 0.0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;

    gpioPWM(HEATER_PIN, duty);
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(double temperature, double duty_cycle, double pid_error)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error: cannot open log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    char ts[64];

    if (localtime_r(&t, &tm)) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    } else {
        snprintf(ts, sizeof(ts), "UNKNOWN");
    }

    fprintf(fp, "%s, %.2f, %.2f, %.2f\n", ts, temperature, duty_cycle, pid_error);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure heater pin as output */
    gpioSetMode(HEATER_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_PIN, PWM_RANGE);
    gpioPWM(HEATER_PIN, 0);

    /* Initialize SPI */
    if (spi_init() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Initialize PID */
    pid_init();

    printf("Heater controller started. Press Ctrl+C to exit.\n");

    while (g_running) {
        double temperature = gpioGetTemperature(HEATER_PIN);

        if (temperature < 0.0) {
            fprintf(stderr, "Error: gpioGetTemperature failed\n");
            break;
        }

        double duty_cycle = pid_control(temperature);

        if (duty_cycle < 0.0) {
            fprintf(stderr, "Error: pid_control failed\n");
            break;
        }

        double pid_error = temperature - HEATER_MIN;

        log_data(temperature, duty_cycle, pid_error);

        heater_control(temperature);

        gpioDelay(HEATER_SAMPLE_US);
    }

    /* Cleanup */
    gpioPWM(HEATER_PIN, 0);
    spiClose();
    gpioTerminate();

    printf("Heater controller stopped.\n");
    return EXIT_SUCCESS;
}

