    if (output < 0.0) output = 0.0;
    if (output > PWM_RANGE) output = PWM_RANGE;

    double duty = (double)output * PWM_RANGE / PWM_FREQUENCY;
    if (duty < 0.0) duty = 0.0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;

    /* Clamp duty to valid range */
    if (duty < 0.0) duty = 0.0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;

    /* Disable heater on fault */
    if (is_fault(error)) {
        gpioPWM(HEATER_PIN, 0);
        return;
    }

    /* Disable heater on failsafe */
    if (error > HEATER_FALLBACK) {
        gpioPWM(HEATER_PIN, 0);
        return;
    }

    /* Update integral and derivative terms */
    integral_term += (error - prev_error) * dt;
    d_count++;
    if (d_count >= MAX_FAULT_COUNT) {
        d_count = 0;
        integral_term = 0.0;
    }

    prev_error = error;
    output = p + i + d;

    /* Clamp output to valid range */
    if (output < 0.0) output = 0.0;
    if (output > PWM_RANGE) output = PWM_RANGE;

    /* Disable heater on fault */
    if (is_fault(error)) {
        gpioPWM(HEATER_PIN, 0);
        return;
    }

    /* Disable heater on failsafe */
    if (error > HEATER_FALLBACK) {
        gpioPWM(HEATER_PIN, 0);
        return;
    }

    /* Update PID state */
    double error_sum = error - last_error;
    last_error = error;

    /* Integrate error over time */
    integral += error_sum * dt;

    /* Compute derivative */
    double derivative = (error - prev_error) / dt;

    /* Compute PID output */
    double control = PID_KP * error + PID_KI * integral_term + PID_KD * derivative;

    /* Clamp output to valid range */
    if (control < 0.0) control = 0.0;
    if (control > PWM_RANGE) control = PWM_RANGE;

    /* Disable heater on fault */
    if (is_fault(error)) {
        gpioPWM(HEATER_PIN, 0);
        return;
    }

    /* Disable heater on failsafe */
    if (error > HEATER_FALLBACK) {
        gpioPWM(HEATER_PIN, 0);
        return;
    }

    /* Update PID state */
    integral_term = PID_KI * (error - prev_error) + PID_KD * derivative_term;
    prev_error = error;
    d_count = 0;
    integral_term = 0.0;
    output = control;
    last_error = error;
    i_count = 0;
    d_count = 0;
}

/* ------------------------------------------------------------------ */
/* Heater control                                                     */
/* ------------------------------------------------------------------ */
static void heater_control(double temperature)
{
    double duty = (temperature - HEATER_MIN) / (HEATER_MAX - HEATER_MIN) * PWM_RANGE;
    if (duty < 0.0) duty = 0.0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;

    gpioPWM(HEATER_PIN, duty);
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(double temperature, double duty_cycle, double pid_error)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error: cannot open log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    char ts[64];

    if (localtime_r(&t, &tm)) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    } else {
        snprintf(ts, sizeof(ts), "UNKNOWN");
    }

    fprintf(fp, "%s, %.2f, %.2f, %.2f\n", ts, temperature, duty_cycle, pid_error);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure heater pin as output */
    gpioSetMode(HEATER_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_PIN, PWM_RANGE);
    gpioPWM(HEATER_PIN, 0);

    /* Initialize SPI */
    if (spi_init() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Initialize PID */
    pid_init();

    printf("Heater controller started. Press Ctrl+C to exit.\n");

    while (g_running) {
        double temperature = gpioGetTemperature(HEATER_PIN);

        if (temperature < 0.0) {
            fprintf(stderr, "Error: gpioGetTemperature failed\n");
            break;
        }

        double duty_cycle = pid_control(temperature);

        if (duty_cycle < 0.0) {
            fprintf(stderr, "Error: pid_control failed\n");
            break;
        }

        double pid_error = temperature - HEATER_MIN;

        log_data(temperature, duty_cycle, pid_error);

        heater_control(temperature);

        gpioDelay(HEATER_SAMPLE_US);
    }

    /* Cleanup */
    gpioPWM(HEATER_PIN, 0);
    spiClose();
    gpioTerminate();

    printf("Heater controller stopped.\n");
    return EXIT_SUCCESS;
}

