#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define PWM_DUTY_MIN 0
#define PWM_DUTY_MAX 100
#define LOG_FILE "cooling_log.csv"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_temperature(float temperature, int duty_percent) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.0f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                temperature, duty_percent);
    } else {
        fprintf(fp, "Timestamp error,%.2f,%.0f\n", temperature, duty_percent);
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int set_fan_speed(int duty_percent) {
    if (duty_percent < 0) duty_percent = 0;
    if (duty_percent > 100) duty_percent = 100;

    int freq = PWM_FREQUENCY;
    int duty = (duty_percent * (PWM_FREQUENCY - 1)) / 100;
    if (gpioPWM(FAN_GPIO, duty) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle on GPIO%d: %s\n",
                FAN_GPIO, pigpio_error(gpioPWM(FAN_GPIO, duty)));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO%d\n", FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(FAN_GPIO, 100) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO%d\n", FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Fan control started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature = 40.0f;
        int duty_percent = (int)((temperature - 40.0f) * (PWM_DUTY_MAX - PWM_DUTY_MIN) / (40.0f - 0.0f) + PWM_DUTY_MIN);
        if (duty_percent < 0) duty_percent = 0;
        if (duty_percent > PWM_DUTY_MAX) duty_percent = PWM_DUTY_MAX;

        if (set_fan_speed(duty_percent) != 0) {
            fprintf(stderr, "Failed to set fan speed\n");
        }

        time_t now = time(NULL);
        if (now == (time_t)-1) {
            fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        } else {
            if (log_temperature(temperature, duty_percent) != 0) {
                fprintf(stderr, "Error logging temperature\n");
            }
        }

        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

