/*
 * Raspberry Pi Zero W - Dual Sensirion SLF3S-1300F Liquid Flow Sensor Reader
 *
 * Wiring:
 *   Sensor 1: SDA -> GPIO2 (I2C1 SDA), VDD -> 3.3V, GND -> GND
 *   Sensor 2: SDA -> GPIO3 (I2C1 SCL), VDD -> 3.3V, GND -> GND
 *   Sensor 3: SDA -> GPIO4 (I2C1 SDA), VDD -> 3.3V, GND -> GND
 *
 * The Sensirion SF06 multiplexer breakout or hub is assumed; the
 * SLF3S-1300F is wired to the I2C bus.  The program reads three bytes
 * from each sensor, validates the CRC-8 checksum, and appends the
 * result to flow_log.txt.
 *
 * Build:  gcc -O2 -Wall -o flow_reader flow_reader.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define LOG_FILE       "flow_log.txt"
#define POLL_INTERVAL  1
#define MAX_RETRIES    3

/* SLF3S-1300F register addresses */
#define SLF3S_REG_ID      0x00
#define SLF3S_REG_DATA_1  0x01
#define SLF3S_REG_DATA_2  0x02
#define SLF3S_REG_DATA_3  0x03
#define SLF3S_REG_CRC_1   0x04
#define SLF3S_REG_CRC_2   0x05

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* CRC-8 as used by Sensirion: poly 0x31, init 0xFF, no final XOR */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/*
 * Read a single byte from a sensor register.
 * Returns 0 on success, -1 on I2C error.
 */
static int i2c_read_reg(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, out, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a 3-byte sequence from a sensor register.
 * Returns 0 on success, -1 on I2C error.
 */
static int i2c_read_seq(int fd, uint8_t reg, uint8_t *out)
{
    uint8_t buf[3];
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "I2C write (reg 0x%02X) failed (attempt %d/%d): %s\n",
                    reg, attempt + 1, MAX_RETRIES, strerror(errno));
            usleep(10000);
            continue;
        }
        if (read(fd, buf, 3) != 3) {
            fprintf(stderr, "I2C read (reg 0x%02X) failed (attempt %d/%d): %s\n",
                    reg, attempt + 1, MAX_RETRIES, strerror(errno));
            usleep(10000);
            continue;
        }
        if (crc8(buf, 2) != buf[2]) {
            fprintf(stderr, "CRC mismatch on register 0x%02X\n", reg);
            usleep(10000);
            continue;
        }
        memcpy(out, buf, 3);
        return 0;
    }
    return -1;
}

/*
 * Read a single 16-bit little-endian value from a sensor register.
 * Returns 0 on success, -1 on I2C error.
 */
static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on register 0x%02X\n", reg);
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/*
 * Read a single 16-bit little-endian value from a sensor register.
 * Returns 0 on success, -1 on I2C error.
 */
static int i2c_read_reg16_le(int fd, uint8_t reg, int16_t *out)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on register 0x%02X\n", reg);
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/*
 * Read a single 16-bit big-endian value from a sensor register.
 * Returns 0 on success, -1 on I2C error.
 */
static int i2c_read_reg16_be(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on register 0x%02X\n", reg);
        return -1;
    }
    *out = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/*
 * Read a single 16-bit little-endian value from a sensor register.
 * Returns 0 on success, -1 on I2C error.
 */
static int i2c_read_reg16_le_le(int fd, uint8_t reg, int16_t *out)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on register 0x%02X\n", reg);
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/*
 * Read a single 16-bit big-endian value from a sensor register.
 * Returns 0 on success, -1 on I2C error.
 */
static int i2c_read_reg16_be_le(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on register 0x%02X\n", reg);
        return -1;
    }
    *out = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/*
 * Append a line to the flow_log.txt file.
 * Returns 0 on success, -1 on I2C error.
 */
static int log_flow_data(FILE *fp, int16_t flow1, int16_t flow2)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, flow1, flow2) < 0) {
        fprintf(stderr, "fprintf to flow_log.txt failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    int fd = -1;
    int ret = EXIT_FAILURE;

    /* Signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
