#define QUADRATURE_DEGREE 360.0f

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(GPIO_A, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as output.\n", GPIO_A);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(GPIO_B, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as output.\n", GPIO_B);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(GPIO_A, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: Failed to enable pull-up on GPIO%d.\n", GPIO_A);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(GPIO_B, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: Failed to enable pull-up on GPIO%d.\n", GPIO_B);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_encoder(int a_pin, int b_pin) {
    int a_val = gpioRead(a_pin);
    int b_val = gpioRead(b_pin);

    if (a_val < 0 || b_val < 0) {
        fprintf(stderr, "Error: Failed to read GPIO%d and GPIO%d.\n", a_pin, b_pin);
        return -1;
    }

    int q = (a_val == 0) ? 1 : (b_val == 0) ? -1 : 0;
    return q;
}

static float calculate_angle(int a_val, int b_val) {
    if (a_val == 0 && b_val == 0) return 0.0f;
    if (a_val == 0) return (float)b_val * QUADRATURE_DEGREE;
    if (b_val == 0) return (float)a_val * QUADRATURE_DEGREE;
    return (float)a_val * QUADRATURE_DEGREE + (float)b_val * QUADRATURE_DEGREE;
}

static int log_position(float angle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f\n", timestamp, angle);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Encoder monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int a_val = read_encoder(GPIO_A, GPIO_B);
        if (a_val < 0) {
            gpioDelay(100000);
            continue;
        }

        int b_val = read_encoder(GPIO_A, GPIO_B);
        if (b_val < 0) {
            gpioDelay(100000);
            continue;
