/*
 * ADPD144RI Red & Infrared Photometric Sensor Logger
 * Board: Raspberry Pi 3 Model B+
 * Bus: /dev/i2c-1
 * Sensor: Analog Devices ADPD144RI (I2C address 0x1A)
 * LED: GPIO17 (active-high)
 *
 * Build: gcc -O2 -Wall -o adpd144ri_logger adpd144ri_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADPD144RI_ADDR 0x1A
#define LED_GPIO       17
#define THRESHOLD      2000
#define LOG_FILE       "adpd144ri_log.txt"
#define SAMPLE_MS      100

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_write_byte(int fd, uint8_t val)
{
    if (write(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C short read: got %zd of %zu\n", n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor                                                              */
/* ------------------------------------------------------------------ */

static int adpd144ri_init(int fd)
{
    /* ADPD144RI: I2C address 0x1A */
    if (i2c_write_byte(fd, ADPD144RI_ADDR) < 0)
        return -1;

    /* Verify sensor presence by reading a dummy register */
    uint8_t dummy;
    if (i2c_read_bytes(fd, &dummy, 1) < 0)
        return -1;

    return 0;
}

static int adpd144ri_read(int fd, uint16_t *ir_raw)
{
    uint8_t buf[2];

    if (i2c_read_bytes(fd, buf, 2) < 0)
        return -1;

    *ir_raw = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* LED control                                                         */
/* ------------------------------------------------------------------ */

static int led_set(int gpio, int on)
{
    if (gpio_output(gpio) < 0) {
        fprintf(stderr, "gpio_output failed: %s\n", strerror(errno));
        return -1;
    }
    if (gpio_write(gpio, on ? 1 : 0) < 0) {
        fprintf(stderr, "gpio_write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static int log_reading(int ir_raw, int threshold)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%s, IR: %u, Threshold: %d\n", ts, ir_raw, threshold);
    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                ADPD144RI_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (adpd144ri_init(fd) < 0) {
        fprintf(stderr, "ADPD144RI initialization failed\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("ADPD144RI initialized on %s at address 0x%02X. Logging to %s\n",
           I2C_BUS, ADPD144RI_ADDR, LOG_FILE);

    while (g_running) {
        uint16_t ir_raw;
        if (adpd144ri_read(fd, &ir_raw) < 0) {
            fprintf(stderr, "Sensor read failed; retrying in %d ms\n",
                    SAMPLE_MS);
            usleep(SAMPLE_MS * 1000);
            continue;
        }

        int ir_above_threshold = (ir_raw > THRESHOLD);

        if (led_set(LED_GPIO, ir_above_threshold) < 0)
            fprintf(stderr, "LED control failed\n");

        if (log_reading(ir_raw, ir_above_threshold) < 0)
            fprintf(stderr, "Logging failed\n");

        printf("IR: %u, Threshold: %d, LED: %s\n",
               ir_raw, THRESHOLD, ir_above_threshold ? "ON" : "OFF");

        usleep(SAMPLE_MS * 1000);
    }

    printf("\nShutting down cleanly...\n");
    led_set(LED_GPIO, 0);
    close(fd);
    return EXIT_SUCCESS;
}

