#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define AUDIO_INPUT_PIN 17
#define GAIN_OUTPUT_PIN 18
#define LOG_FILE "audio_log.txt"
#define POLL_INTERVAL_US 10000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_event(int level) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s LEVEL\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(AUDIO_INPUT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", AUDIO_INPUT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GAIN_OUTPUT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", GAIN_OUTPUT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(GAIN_OUTPUT_PIN, 0) != 0) {
        fprintf(stderr, "Failed to set GPIO%d LOW\n", GAIN_OUTPUT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Audio monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int level = gpioRead(AUDIO_INPUT_PIN);
        if (level < 0) {
            fprintf(stderr, "Error reading GPIO%d\n", AUDIO_INPUT_PIN);
            break;
        }

        if (level == 1) {
            if (log_event(1) != 0) {
                break;
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    gpioWrite(GAIN_OUTPUT_PIN, 0);
    gpioTerminate();
    printf("Audio monitoring stopped.\n");
    return EXIT_SUCCESS;
}

