/*
 * Raspberry Pi Zero W – Sensirion SLF3S-4000B liquid flow monitor
 *
 * Wiring:
 *   SLF3S-4000B VDD  -> 3.3 V (Pin 1)
 *   SLF3S-4000B GND  -> GND  (Pin 9)
 *   SLF3S-4000B SDA  -> GPIO2 / I2C1 SDA (Pin 3)
 *   SLF3S-4000B SCL  -> GPIO3 / I2C1 SCL (Pin 5)
 *
 * Build:  gcc -O2 -Wall -Wextra -o flow_monitor flow_monitor.c
 * Run:    ./flow_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SLF3S_ADDR     0x50
#define LOG_FILE       "flow_log.csv"
#define SAMPLE_MS      1000

/* SLF3S-4000B register map (from datasheet) */
#define SLF3S_REG_ID    0x00
#define SLF3S_REG_MSB   0x01
#define SLF3S_REG_LSB   0x02
#define SLF3S_REG_CRC   0x03
#define SLF3S_REG_DATA  0x04

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, initial 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read block from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int slf3s_init(int fd)
{
    uint8_t id = 0;
    if (i2c_read_reg(fd, SLF3S_REG_ID, &id) < 0)
        return -1;
    if (id != 0x40) {
        fprintf(stderr, "SLF3S-4000B ID mismatch: got 0x%02X, expected 0x40\n",
                id);
        return -1;
    }

    /* Write 0x00 to register 0x00 to reset the sensor */
    if (i2c_write_reg(fd, SLF3S_REG_MSB, 0x00) < 0)
        return -1;
    if (i2c_write_reg(fd, SLF3S_REG_LSB, 0x00) < 0)
        return -1;
    if (i2c_write_reg(fd, SLF3S_REG_CRC, 0x00) < 0)
        return -1;

    /* Allow the sensor to settle after reset */
    usleep(100000);

    /* Read the CRC to confirm the sensor is ready */
    uint8_t crc = sensirion_crc8(&id, 2);
    if (i2c_read_reg(fd, SLF3S_REG_CRC, &crc) < 0)
        return -1;
    if (crc != id) {
        fprintf(stderr, "CRC mismatch: got 0x%02X, expected 0x%02X\n",
                crc, id);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Flow measurement                                                     */
/* ------------------------------------------------------------------ */
static int slf3s_read_flow(int fd, float *flow_rate_uL_min)
{
    uint8_t msb = 0, lsb = 0;
    if (i2c_read_reg(fd, SLF3S_REG_MSB, &msb) < 0)
        return -1;
    if (i2c_read_reg(fd, SLF3S_REG_LSB, &lsb) < 0)
        return -1;

    uint8_t crc = sensirion_crc8(&msb, 1);
    if (crc != msb) {
        fprintf(stderr, "CRC mismatch: got 0x%02X, expected 0x%02X\n",
                crc, msb);
        return -1;
    }

    uint16_t raw = ((uint16_t)msb << 8) | lsb;
    *flow_rate_uL_min = (float)raw / 1000.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_flow_data(FILE *fp, float flow_rate_uL_min)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", ts, flow_rate_uL_min) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SLF3S_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SLF3S_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (slf3s_init(g_i2c_fd) < 0) {
        fprintf(stderr, "SLF3S-4000B initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(stderr, "Flow monitoring started. Logging to %s\n", LOG_FILE);
    fprintf(stderr, "Press Ctrl+C to stop.\n");

    while (g_running) {
        float flow_rate_uL_min = 0.0f;
        if (slf3s_read_flow(g_i2c_fd, &flow_rate_uL_min) < 0) {
            fprintf(stderr, "Flow read failed; skipping cycle\n");
            usleep(SAMPLE_MS * 1000);
            continue;
        }

        if (log_flow_data(g_log_fp, flow_rate_uL_min) < 0) {
            fprintf(stderr, "Logging failed; continuing\n");
        }

        usleep(SAMPLE_MS * 1000);
    }

    fprintf(stderr, "\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

