static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg-select 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg-select 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int sensor_init(int fd)
{
    /*
     * MICS-VZ-89TE:
     *   TVOC_HIGH = 0x00, TVOC_LOW = 0x00, TVOC_HIGH_F = 0x00, TVOC_LOW_F = 0x00
     *   TVOC_HIGH_H = 0x00, TVOC_LOW_H = 0x00, TVOC_HIGH_F_H = 0x00, TVOC_LOW_F_H = 0x00
     *   TVOC_HIGH_F_F = 0x00, TVOC_LOW_F_F = 0x00
     *
     * The sensor is a 16-bit ADC with a 16-bit high-resolution register.
     * The 16-bit register is split into two 8-bit registers:
     *   TVOC_HIGH = 0x00, TVOC_LOW = 0x00
     *   TVOC_HIGH_F = 0x00, TVOC_LOW_F = 0x00
     *   TVOC_HIGH_F_H = 0x00, TVOC_LOW_F_H = 0x00
     *   TVOC_HIGH_F_F = 0x00, TVOC_LOW_F_F = 0x00
     *
     * The 16-bit register is mapped to the 16-bit register 0x00.
     */
    if (i2c_write_reg8(fd, REG_CONFIG, 0x00) < 0)
        return -1;
    usleep(10000); /* 10 ms settle */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read sensor data                                                    */
/* ------------------------------------------------------------------ */
static int read_sensor_data(int fd, uint16_t *tvoc_high, uint16_t *tvoc_low)
{
    uint8_t reg = REG_TVOC;
    uint8_t val;

    if (i2c_read_reg8(fd, reg, &val) < 0)
        return -1;

    *tvoc_high = (uint16_t)val;
    *tvoc_low  = (uint16_t)val;
    return 0;
