#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_GPIO 17
#define TOUCH_SENSOR_INTERVAL_MS 100
#define TOUCH_THRESHOLD_SEC 5
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t running = 1;
static volatile uint32_t touch_start_tick = 0;
static volatile uint32_t touch_end_tick = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", TOUCH_SENSOR_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_touch_sensor(void) {
    uint32_t now = gpioTick();

    if (now < touch_start_tick) {
        touch_start_tick = now;
        return 1;
    }

    if (now < touch_end_tick) {
        return 0;
    }

    touch_end_tick = now;
    return 1;
}

static int detect_touch_event(void) {
    uint32_t now = gpioTick();

    if (now < touch_start_tick) {
        return 0;
    }

    if (now < touch_end_tick) {
        return 1;
    }

    return 0;
}

static void print_alert(void) {
    printf("Intrusion detected! Touched for more than %d seconds.\n",
           TOUCH_THRESHOLD_SEC);
    fflush(stdout);
}

static void cleanup(void) {
    printf("Cleaning up and exiting...\n");
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Monitoring TTP223B touch sensor on GPIO %d. Press Ctrl+C to exit.\n",
           TOUCH_SENSOR_GPIO);

    while (running) {
        if (read_touch_sensor()) {
            if (detect_touch_event()) {
                print_alert();
            }
        }

        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

