#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2s.h>
#include <linux/i2s_ioctl.h>
#include <pigpio.h>

#define I2S_DEVICE "/dev/snd/pcmC0D0c"
#define GPIO_LEFT_CH_SELECT 17
#define RAW_FILE_NAME "audio_capture.pcm"
#define BUFFER_SIZE 4096

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2s_init(int *fd) {
    int fd = -1;
    int retries = 3;
    int i;

    for (i = 0; i < retries; i++) {
        fd = open(I2S_DEVICE, O_RDWR);
        if (fd < 0) {
            fprintf(stderr, "Error opening I2S device %s: %s\n", I2S_DEVICE, strerror(errno));
            gpioDelay(100000);
            continue;
        }

        if (ioctl(fd, I2S_SET_INPUT, 0) < 0) {
            fprintf(stderr, "Error setting I2S input: %s\n", strerror(errno));
            close(fd);
            gpioDelay(100000);
            continue;
        }

        if (ioctl(fd, I2S_SET_FORMAT, I2S_FMT_16_BIT) < 0) {
            fprintf(stderr, "Error setting I2S format: %s\n", strerror(errno));
            close(fd);
            gpioDelay(100000);
            continue;
        }

        if (ioctl(fd, I2S_SET_SPEED, I2S_SPEED_48000) < 0) {
            fprintf(stderr, "Error setting I2S speed: %s\n", strerror(errno));
            close(fd);
            gpioDelay(100000);
            continue;
        }

        printf("I2S initialized successfully on %s\n", I2S_DEVICE);
        return fd;
    }

    fprintf(stderr, "Failed to initialize I2S after %d retries.\n", retries);
    return -1;
}

static int i2s_read(int fd, int16_t *buffer, int buffer_size) {
    int bytes_read = 0;
    int bytes_written = 0;

    while (bytes_read < buffer_size) {
        int bytes_available = ioctl(fd, I2S_READ_AVAILABLE, &bytes_available);
        if (bytes_available < 0) {
            fprintf(stderr, "Error reading available bytes: %s\n", strerror(errno));
            return -1;
        }

        if (bytes_available == 0) {
            break;
        }

        int bytes_to_read = (int)bytes_available;
        int bytes_to_write = (int)buffer_size - bytes_read;

