#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define FLAME_SENSOR_GPIO 4
#define PWM_PIN 18
#define LOG_FILE "flame_log.txt"
#define DEBOUNCE_US 50000  /* 50 ms */
#define PWM_FREQ 100        /* 100 Hz */
#define PWM_RANGE 255       /* 255 levels */
#define POLL_DELAY_US 50000 /* 50 ms */

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *event) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (t == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s - %s\n", timestamp, event) < 0) {
        fprintf(stderr, "fprintf() to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioPWM(PWM_PIN, 0);
    gpioSetMode(PWM_PIN, PI_INPUT);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", FLAME_SENSOR_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", PWM_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO%d\n", PWM_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO%d\n", PWM_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioPWM(PWM_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise PWM on GPIO%d\n", PWM_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Flame detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        int sensor_value = gpioRead(FLAME_SENSOR_GPIO);
        if (sensor_value < 0) {
            fprintf(stderr, "Failed to read GPIO%d: %s\n", FLAME_SENSOR_GPIO, strerror(errno));
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (sensor_value == 0) {
            /* Sensor absent: no valid reading */
            if (log_event("Sensor absent: no valid reading") != 0) {
                fprintf(stderr, "Failed to log sensor absent event\n");
            }
            gpioDelay(DEBOUNCE_US);
            continue;
        }

        if (log_event("Flame detected") != 0) {
            fprintf(stderr, "Failed to log flame event\n");
        }

        if (gpioPWM(PWM_PIN, 1) != 0) {
            fprintf(stderr, "Failed to start PWM on GPIO%d\n", PWM_PIN);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

