/*
 * AWR1642 mmWave Radar SPI Interface for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   AWR1642 VDD  -> 3.3 V (Pin 1)
 *   AWR1642 VREF -> 3.3 V (Pin 1)
 *   AWR1642 GND  -> GND  (Pin 6)
 *   AWR1642 CS   -> GPIO8 (SPI0 CE0)
 *   AWR1642 D0   -> GPIO9 (SPI0 S0)
 *   AWR1642 D1   -> GPIO10 (SPI0 S1)
 *   AWR1642 D2   -> GPIO11 (SPI0 S2)
 *   AWR1642 D3   -> GPIO12 (SPI0 S3)
 *   AWR1642 D4   -> GPIO13 (SPI0 S4)
 *   AWR1642 D5   -> GPIO14 (SPI0 S5)
 *   AWR1642 D6   -> GPIO15 (SPI0 S6)
 *   AWR1642 D7   -> GPIO16 (SPI0 S7)
 *   AWR1642 CSN  -> GPIO33 (SPI0 CS0)
 *   AWR1642 TX   -> GPIO10 (SPI0 MOSI)
 *   AWR1642 RX   -> GPIO11 (SPI0 MISO)
 *   AWR1642 CLK  -> GPIO13 (SPI0 SCL)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o awr1642_spi awr1642_spi.c -lrt -lm
 *
 * Run:
 *   ./awr1642_spi
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
