#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8
#define SPI_BITS_PER_WORD 8
#define SPI_DELAY_US    0
#define SPI_TIMEOUT_US  50000U

#define GPIO_CS         8
#define GPIO_TX         10
#define GPIO_RX         11
#define GPIO_IRQ        24

#define CONFIG_MAGIC_SIZE 4
#define CONFIG_SIZE       (CONFIG_MAGIC_SIZE + sizeof(mmWaveConfig_t))

#define CONFIG_SIZE_BYTES (CONFIG_MAGIC_SIZE + sizeof(mmWaveConfig_t))

#define RANGE_DOLLAR_PER_S  0.01f
#define RANGE_DOLLAR_PER_S_MAX 0.1f

#define LOG_FILE_NAME "awr1642_heatmap.bin"

typedef struct {
    float start_freq;
    float end_freq;
    int num_chirps;
    int num_samples;
} mmWaveConfig_t;

