/*
 * flame_sensor.c
 *
 * Raspberry Pi Zero W — KY-026 Flame Sensor monitor
 *
 * Wiring:
 *   KY-026 VCC  -> 3.3 V (Pin 1)
 *   KY-026 GND  -> GND  (Pin 9)
 *   KY-026 OUT  -> GPIO20 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o flame_sensor flame_sensor.c -lrt
 *
 * Run:
 *   sudo ./flame_sensor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define GPIO_PIN        20
#define LOG_FILE        "flame_log.txt"
#define POLL_INTERVAL_US 100000   /* 100 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int gpio_init(void)
{
    int fd = open("/dev/gpiochip0", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: cannot open /dev/gpiochip0: %s\n",
                strerror(errno));
        return -1;
    }

    if (ioctl(fd, GPIO_IOCTL_GET_LINE_STATE, &gpio_pin) < 0) {
        fprintf(stderr, "Error: cannot get GPIO line %d: %s\n",
                GPIO_PIN, strerror(errno));
        close(fd);
        return -1;
    }

    if (ioctl(fd, GPIO_IOCTL_SET_LINE_STATE, &gpio_pin) < 0) {
        fprintf(stderr, "Error: cannot set GPIO line %d: %s\n",
                GPIO_PIN, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/* ------------------------------------------------------------------ */
/* KY-026 state detection                                               */
/* ------------------------------------------------------------------ */
static int read_flame_sensor(int fd)
{
    int level = gpio_read(fd);
    if (level < 0) {
        fprintf(stderr, "Error: gpio_read failed on GPIO %d: %s\n",
                GPIO_PIN, strerror(errno));
        return -1;
    }
    return level;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_flame_event(int new_state)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open %s: %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error: time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&t, &tm_utc) == NULL) {
        fprintf(stderr, "Error: gmtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Flame sensor state changed to %s\n",
                timestamp, new_state ? "FLAME_DETECTED" : "FLAME_CLEARED") < 0) {
        fprintf(stderr, "Error: fprintf to log failed: %s\n",
                strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error: fclose failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed: %s\n",
                strerror(errno));
    }

    int fd = gpio_init();
    if (fd < 0) {
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started on GPIO%d. Press Ctrl+C to exit.\n",
           GPIO_PIN);

    while (g_running) {
        int current = read_flame_sensor(fd);
        if (current < 0) {
            /* GPIO read error — skip this cycle and retry on next poll */
            usleep(POLL_INTERVAL_US);
            continue;
        }

        int new_state = (current == 1) ? 1 : 0;

        if (log_flame_event(new_state) < 0) {
            /* Logging error — continue polling */
            usleep(POLL_INTERVAL_US);
            continue;
        }

        printf("Flame sensor state changed to %s\n",
               new_state ? "FLAME_DETECTED" : "FLAME_CLEARED");
        fflush(stdout);

        usleep(POLL_INTERVAL_US);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    if (close(fd) < 0) {
        fprintf(stderr, "Warning: close(GPIO chip) failed: %s\n",
                strerror(errno));
    }
    return EXIT_SUCCESS;
}

