/*
 * ambient_light_logger.c
 *
 * Raspberry Pi Zero W — OPT3001 Ambient Light Sensor logger
 *
 * Wiring:
 *   OPT3001 SDA -> GPIO2 (I2C bus 1 SDA)
 *   OPT3001 SCL -> GPIO3 (I2C bus 1 SCL)
 *   OPT3001 VDD -> 3.3 V
 *   OPT3001 GND -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o ambient_light_logger ambient_light_logger.c
 *
 * Run:
 *   ./ambient_light_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define OPT3001_ADDR   0x50
#define LIGHT_DATA_FILE "light_data.txt"
#define CONVERSION_DELAY_US 100000   /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Write a 16-bit value to the OPT3001 register address.
 * Returns 0 on success, -1 on failure.
 */
static int opt3001_write_reg(int fd, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;

    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit value from the OPT3001 register address.
 * Returns 0 on success, -1 on failure.
 */
static int opt3001_read_reg(int fd, uint8_t reg, uint16_t *value)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/*
 * Read a lux value from the OPT3001.
 * Returns 0 on success, -1 on failure.
 */
static int opt3001_read_lux(int fd, uint16_t *lux)
{
    uint16_t raw;

    if (opt3001_read_reg(fd, 0x00, &raw) != 0)
        return -1;

    *lux = raw;
    return 0;
}

/*
 * Append a timestamped lux reading to the light_data.txt file.
 * Returns 0 on success, -1 on failure.
 */
static int log_light_data(const char *filename, uint16_t lux)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, %u\n", timestamp, lux) < 0) {
        fprintf(stderr, "fprintf to %s failed: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose on %s failed: %s\n", filename, strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    int i2c_fd = -1;
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Open I2C bus */
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                OPT3001_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Configure OPT3001 for continuous conversion mode */
    if (opt3001_write_reg(i2c_fd, 0x01, 0x0F) != 0) {
        fprintf(stderr, "Failed to configure OPT3001 for continuous conversion.\n");
        goto cleanup;
    }

    printf("Ambient Light Sensor logger started. Logging to %s\n",
           LIGHT_DATA_FILE);
    printf("Press Ctrl+C to stop.\n");

    /* Main loop */
    while (g_running) {
        uint16_t lux;

        if (opt3001_read_lux(i2c_fd, &lux) != 0) {
            fprintf(stderr, "Failed to read lux value. Retrying in 100 ms.\n");
            usleep(CONVERSION_DELAY_US);
            continue;
        }

        if (log_light_data(LIGHT_DATA_FILE, lux) != 0) {
            fprintf(stderr, "Failed to log lux value.\n");
        }

        usleep(CONVERSION_DELAY_US);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (fp) {
        fclose(fp);
    }
    return ret;
}

