/*
 * flame_detect.c - Raspberry Pi 3 Model B+
 *
 * Reads the SainSmart IR Flame Detection Sensor Module over the GPIO
 * bus using the v2 API and logs the flame status to the console once
 * every second.
 *
 * Wiring:
 *   Sensor DOUT -> GPIO17 (BCM)
 *   VCC -> 3.3 V (Pin 1)
 *   GND -> GND  (Pin 9)
 *
 * Build: gcc -Wall -Wextra -O2 -o flame_detect flame_detect.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>

#include <gpiod.h>

#define GPIO_CHIP_NAME   "gpiochip0"
#define GPIO_LINE_OFFSET 17          /* BCM 17, active-low DOUT */
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    return 0;
}

static int setup_gpio(struct gpiod_chip *chip, struct gpiod_line *line)
{
    if (gpiod_line_request_input_flags(line, "flame_detect",
                                        GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Failed to request GPIO %d as input with pull-up: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        return -1;
    }

    /* Request the line as input with the default line direction (active-low). */
    if (gpiod_line_request_input(line, GPIO_CHIP_NAME) < 0) {
        fprintf(stderr, "Failed to request GPIO %d as input: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        return -1;
    }

    return 0;
}

static int read_flame_sensor(struct gpiod_line *line)
{
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Failed to read GPIO %d: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        return -1;
    }
    return value;
}

static void log_flame_status(int flame_detected)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    printf("[%s] Flame Detected: %s\n", timestamp, flame_detected ? "YES" : "NO");
    fflush(stdout);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() != 0) {
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (setup_gpio(chip, line) != 0) {
        goto cleanup;
    }

    printf("Flame detection started on GPIO %d. Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET);
    fflush(stdout);

    while (g_running) {
        int flame_detected = read_flame_sensor(line);
        if (flame_detected < 0) {
            fprintf(stderr, "Error reading flame sensor.\n");
            break;
        }

        if (flame_detected == 0) {
            log_flame_status(0);
        } else {
            log_flame_status(1);
        }

        /* Sleep for POLL_INTERVAL_SEC seconds, checking g_running every
         * second so we can interrupt the loop if the signal is caught. */
        for (int i = 0; i < POLL_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    printf("\nExiting gracefully.\n");
    return ret;
}

