/*
 * TTP226 8-channel digital touch sensor reader for Raspberry Pi Zero W.
 *
 * Wiring:
 *   TTP226 OUT1 -> GPIO2 (BCM 2)
 *   TTP226 OUT2 -> GPIO3 (BCM 3)
 *   TTP226 OUT3 -> GPIO4 (BCM 4)
 *   TTP226 OUT4 -> GPIO5 (BCM 5)
 *   TTP226 OUT5 -> GPIO6 (BCM 6)
 *   TTP226 OUT6 -> GPIO7 (BCM 7)
 *   TTP226 OUT7 -> GPIO8 (BCM 8)
 *   TTP226 OUT8 -> GPIO9 (BCM 9)
 *
 * Build: gcc -O2 -Wall -o touch_sensor touch_sensor.c -lpigpio -lrt
 * Run:   sudo ./touch_sensor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_US 100000   /* 100 ms */

/* BCM GPIO pins for the eight channels */
static const int channel_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        snprintf(buf, len, "UNKNOWN");
        return;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        snprintf(buf, len, "UNKNOWN");
        return;
    }
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
}

/* ------------------------------------------------------------------ */
/* Read a single channel                                               */
/* ------------------------------------------------------------------ */
static int read_channel(int channel_pin)
{
    int value = gpioRead(channel_pin);
    if (value < 0) {
        fprintf(stderr, "Error: gpioRead failed on pin %d (returned %d)\n",
                channel_pin, value);
        return -1;
    }
    return value;
}

/* ------------------------------------------------------------------ */
/* Print a timestamped line for a single channel                        */
/* ------------------------------------------------------------------ */
static void print_channel_line(int channel_pin, int value)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    printf("%s Channel %d: %s\n", ts, channel_pin,
           value ? "1" : "0");
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure all eight channels as outputs */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(channel_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for channel %d\n",
                    channel_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("TTP226 touch sensor reader started. Press Ctrl+C to exit.\n");
    printf("  Channel 1: GPIO2\n");
    printf("  Channel 2: GPIO3\n");
    printf("  Channel 3: GPIO4\n");
    printf("  Channel 4: GPIO5\n");
    printf("  Channel 5: GPIO6\n");
    printf("  Channel 6: GPIO7\n");
    printf("  Channel 7: GPIO8\n");
    printf("  Channel 8: GPIO9\n");
    printf("  Press Ctrl+C to exit.\n");
    fflush(stdout);

    int last_state[NUM_CHANNELS] = {0, 0, 0, 0, 0, 0, 0, 0};

    while (g_running) {
        int current_state[NUM_CHANNELS];

        for (int i = 0; i < NUM_CHANNELS; i++) {
            current_state[i] = read_channel(channel_pins[i]);
            if (current_state[i] < 0) {
                /* Non-fatal: continue reading */
                continue;
            }
        }

        /* Print the current state */
        for (int i = 0; i < NUM_CHANNELS; i++) {
            print_channel_line(channel_pins[i], current_state[i]);
        }

        /* Wait for the next poll interval */
        gpioDelay(POLL_INTERVAL_US);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpioWrite(channel_pins[i], 0);
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

