#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define SAMPLE_INTERVAL_US 100000  /* 100 ms */

/* GPIO pins for the eight sensor outputs (BCM numbering) */
static const int sensor_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/*
 * Read a single channel from the TTP226.
 * Returns 0 on success and stores the value in *out, or -1 on error.
 */
static int read_channel(int channel)
{
    if (channel < 0 || channel > NUM_CHANNELS - 1) {
        fprintf(stderr, "Error: invalid channel %d\n", channel);
        return -1;
    }

    int value = gpioRead(sensor_pins[channel]);
    if (value < 0) {
        fprintf(stderr, "Error: gpioRead failed on pin %d\n", sensor_pins[channel]);
        return -1;
    }

    /* TTP226 outputs are active-low: 0 = high, 1 = low. */
    return value;
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize the pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure the GPIO pins as inputs with pull-down resistors */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(sensor_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", sensor_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(sensor_pins[i], PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Error: gpioSetPullUpDown failed for pin %d\n", sensor_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* Open the TTP226 library and configure it for 8 channels */
    if (ttp226_init(NUM_CHANNELS) != 0) {
        fprintf(stderr, "Error: TTP226 initialization failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("TTP226 touch sensor initialized. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (program_running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int value = read_channel(i);
            if (value < 0) {
                fprintf(stderr, "Error: failed to read channel %d\n", i);
                break;
            }
            printf("[+%d ms] CH%d=%d\n", SAMPLE_INTERVAL_US / 1000, i, value);
        }
        usleep(SAMPLE_INTERVAL_US);
    }

    /* Clean shutdown: call the library’s API once before exiting */
    if (ttp226_close() != 0) {
        fprintf(stderr, "Error: TTP226 close failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioTerminate();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

