#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_US 50000  /* 50 ms */
#define NUM_RETRIES 3

/* BCM GPIO pins for the TTP226 channels */
static const int channel_pins[NUM_CHANNELS] = {2, 3, 4, 17, 27, 22, 10, 9};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/*
 * Read the state of all eight TTP226 channels.
 * Returns 0 on success, -1 on error.
 */
static int read_sensor_data(int *data)
{
    int retries = NUM_RETRIES;
    int i;

    while (retries > 0) {
        int values[NUM_CHANNELS];

        for (i = 0; i < NUM_CHANNELS; i++) {
            int val = gpioRead(channel_pins[i]);
            if (val < 0) {
                fprintf(stderr, "Error reading GPIO pin %d: %s\n",
                        channel_pins[i], strerror(errno));
                return -1;
            }
            values[i] = val;
        }

        /* pigpio returns 0 on success, -1 on error. */
        if (gpioWrite(channel_pins[0], 0) < 0) {
            fprintf(stderr, "Error writing to GPIO pin %d: %s\n",
                    channel_pins[0], strerror(errno));
            return -1;
        }

        /* Read the state of all channels. */
        int state = 0;
        for (i = 0; i < NUM_CHANNELS; i++) {
            state |= values[i];
        }

        /* pigpio returns 0 on success, -1 on error. */
        if (gpioWrite(channel_pins[0], 1) < 0) {
            fprintf(stderr, "Error writing to GPIO pin %d: %s\n",
                    channel_pins[0], strerror(errno));
            return -1;
        }

        data[i] = state;
        retries--;
    }

    return 0;
}

static void get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        snprintf(buf, len, "1970-01-01T00:00:00Z");
        return;
    }
    strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &timeinfo);
}

int main(void)
{
    int data[NUM_CHANNELS];
    char timestamp[32];
    int ret;

    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Configure each channel as input with bias disabled */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        ret = gpioSetMode(channel_pins[i], PI_INPUT);
        if (ret < 0) {
            fprintf(stderr, "Failed to set GPIO %d as input: %s\n",
                    channel_pins[i], strerror(errno));
            gpioTerminate();
            return EXIT_FAILURE;
        }
        ret = gpioSetPullUpDown(channel_pins[i], PI_PUD_OFF);
        if (ret < 0) {
            fprintf(stderr, "Failed to set pull-up/down on GPIO %d: %s\n",
                    channel_pins[i], strerror(errno));
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("TTP226 sensor array reader started. Press Ctrl+C to exit.\n");

    while (program_running) {
        ret = read_sensor_data(data);
        if (ret < 0) {
            fprintf(stderr, "Sensor read failed, retrying...\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        get_timestamp(timestamp, sizeof(timestamp));

        for (int i = 0; i < NUM_CHANNELS; i++) {
            printf("%s, ", timestamp);
            if (data[i] != 0) {
                printf("1, ");
            } else {
                printf("0, ");
            }
        }

        printf("\n");
        fflush(stdout);

        gpioDelay(POLL_INTERVAL_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    gpioTerminate();
    return EXIT_SUCCESS;
}

