/*
 * Raspberry Pi Zero W – Omron D7E-1 tilt sensor monitor
 *
 * Wiring:
 *   D7E-1 OUT  -> GPIO4 (BCM pin 7)
 *   VCC        -> 3.3 V
 *   GND        -> GND
 *
 * The D7E-1 output is a digital signal; the internal pull-up is enabled.
 * The library's API call is used to read the GPIO pin.
 *
 * Build:  gcc -O2 -Wall -Wextra -o tilt_monitor tilt_monitor.c -lpigpio -lrt
 * Run:    sudo ./tilt_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN        4
#define POLL_DELAY_US   100000   /* 100 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read the GPIO pin with error checking                               */
/* ------------------------------------------------------------------ */
static bool read_gpio_pin(int gpio_pin)
{
    int level = gpioRead(gpio_pin);
    if (level < 0) {
        fprintf(stderr, "Error: gpioRead failed on pin %d (code %d).\n",
                gpio_pin, level);
        return false;
    }
    return (level == 0);  /* LOW = tilted, HIGH = not tilted */
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install SIGINT handler so Ctrl-C always exits cleanly */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pin as input with internal pull-up */
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed on pin %d.\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed on pin %d.\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Tilt sensor monitor started on GPIO%d. Press Ctrl-C to exit.\n",
           GPIO_PIN);

    /* Main polling loop */
    while (g_running) {
        bool tilt_changed = read_gpio_pin(GPIO_PIN);
        if (!tilt_changed) {
            /*
             * gpioRead returned an error; the loop will exit and
             * the error will be printed on the next iteration.
             */
            break;
        }

        if (tilt_changed) {
            printf("Tilted\n");
        } else {
            printf("Not Tilted\n");
        }

        /* Sleep 100 ms; the signal handler will wake us early if
         * Ctrl-C is pressed. */
        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown */
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

