/*
 * Raspberry Pi 5 – Dual Sensirion SLF3S-0600F Liquid Flow Sensor Reader
 *
 * Reads two SLF3S-0600F sensors on I2C /dev/i2c-1 and logs the average flow
 * rate to flow_log.txt every second.  Drives an alarm on GPIO17 when
 * the average falls below 0.5 ml/min.
 *
 * Build:  gcc -O2 -Wall -o flow_monitor flow_monitor.c -lm
 * Run:    sudo ./flow_monitor
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SENSOR_1_ADDR  0x50
#define SENSOR_2_ADDR  0x51
#define ALARM_GPIO     17
#define FLOW_LOG_FILE  "flow_log.txt"
#define MEASUREMENT_DELAY_US 100000   /* 100 ms */
#define SENSOR_READ_DELAY_US  1000000 /* 1 s */
#define ALARM_THRESHOLD_ML   0.5f
#define ALARM_LOW_THRESHOLD_ML 0.0f
#define ALARM_HIGH_THRESHOLD_ML 1.0f

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int fd, uint8_t byte)
{
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int sensor_init(int fd, uint8_t addr)
{
    if (i2c_write_byte(fd, 0x00) < 0)
        return -1;   /* sensor not responding */
    usleep(1000);

    if (i2c_write_byte(fd, addr) < 0)
        return -1;   /* invalid address */

    /* Start command: single byte, no data */
    if (i2c_write_byte(fd, 0x01) < 0)
        return -1;

    usleep(1000);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Flow measurement                                                     */
/* ------------------------------------------------------------------ */
static float measure_flow(int fd)
{
    uint8_t buf[2];
    uint8_t crc;

    if (i2c_read_bytes(fd, buf, 2) < 0)
        return -1.0f;

    crc = sensirion_crc8(buf, 2);
    if (crc != buf[2]) {
        fprintf(stderr, "CRC mismatch on sensor %d: got 0x%02X, expected 0x%02X\n",
                fd, crc, buf[2]);
        return -1.0f;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    float flow = (float)raw / 1000.0f;
    return flow;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_flow(float avg_flow)
{
    FILE *fp = fopen(FLOW_LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", FLOW_LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s, %.2f ml/min\n", ts, avg_flow);
    } else {
        fprintf(fp, "Error: localtime_r failed\n");
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Alarm control                                                       */
/* ------------------------------------------------------------------ */
static void alarm_set(int gpio, int on)
{
    if (gpio_set_level(gpio, on) < 0) {
        fprintf(stderr, "Failed to set GPIO %d to %d\n", gpio, on);
        return;
    }
    if (on)
        fprintf(stderr, "Alarm set to %s\n", gpio_get_level(gpio) ? "ON" : "OFF");
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Ensure alarm is off */
    gpio_set_level(ALARM_GPIO, 0);

    /* Release I2C */
    if (fd_i2c >= 0) {
        close(fd_i2c);
        fd_i2c = -1;
    }

    /* Close log file */
    if (fp) {
        fclose(fp);
        fp = NULL;
    }

    /* Release GPIO */
    gpio_set_direction(ALARM_GPIO, 0);
    gpio_set_level(ALARM_GPIO, 0);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize GPIO */
    if (gpio_set_direction(ALARM_GPIO, 0) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", ALARM_GPIO);
        return EXIT_FAILURE;
    }
    if (gpio_set_level(ALARM_GPIO, 0) < 0) {
        fprintf(stderr, "Failed to initialize GPIO %d to LOW\n", ALARM_GPIO);
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    fd_i2c = open(I2C_BUS, O_RDWR);
    if (fd_i2c < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize sensors */
    if (sensor_init(fd_i2c, SENSOR_1_ADDR) < 0) {
        fprintf(stderr, "Sensor 1 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sensor_init(fd_i2c, SENSOR_2_ADDR) < 0) {
        fprintf(stderr, "Sensor 2 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    fp = fopen(FLOW_LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", FLOW_LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Flow monitoring started.  Sensors: %d, %d.  Logging to %s\n",
           SENSOR_1_ADDR, SENSOR_2_ADDR, FLOW_LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        float avg_flow = -1.0f;
        int ok = 0;

        for (int i = 0; i < 10 && g_running; i++) {
            float f = measure_flow(fd_i2c);
            if (f >= 0.0f) {
                avg_flow = (float)i / 10.0f;
