#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define BUFFER_SIZE 100
#define POLL_INTERVAL_US 50000  /* 50 ms */
#define SAMPLE_INTERVAL_US 50000 /* 50 ms */

/* KY-033 output: LOW = obstacle detected, HIGH = clear */
#define OBSTACLE_THRESHOLD_LOW 1
#define OBSTACLE_THRESHOLD_HIGH 0

typedef struct {
    time_t timestamp;
    int obstacle_detected;
} sensor_data_t;

static volatile sig_atomic_t g_running = 1;
static int g_gpio_initialized = 0;
static int g_buffer_full = 0;
static sensor_data_t g_buffer[BUFFER_SIZE];
static int g_buffer_index = 0;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", gpioInitialise());
        return -1;
    }
    g_gpio_initialized = 1;

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", GPIO_PIN);
        return -1;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to enable pull-up on GPIO %d.\n", GPIO_PIN);
        return -1;
    }

    return 0;
}

static int read_sensor(void) {
    int value = gpioRead(GPIO_PIN);
    if (value < 0) {
        fprintf(stderr, "Error: gpioRead failed on GPIO %d (code %d).\n", GPIO_PIN, value);
        return -1;
    }
    return value;
}

static void add_to_buffer(int obstacle_detected) {
    g_buffer[g_buffer_index].timestamp = time(NULL);
    g_buffer[g_buffer_index].obstacle_detected = obstacle_detected;
    g_buffer_index = (g_buffer_index + 1) % BUFFER_SIZE;
    if (g_buffer_full) {
        g_buffer_index = (g_buffer_index + BUFFER_SIZE - 1) % BUFFER_SIZE;
    }
}

static void print_buffer(void) {
    printf("--- Sensor Data Buffer (Timestamp, Obstacle Detected) ---\n");
    for (int i = 0; i < g_buffer_index; i++) {
        time_t t = g_buffer[i].timestamp;
        int d = g_buffer[i].obstacle_detected;
        printf("[%ld] Obstacle Detected: %s\n", t, d ? "Yes" : "No");
    }
    printf("--- End of Buffer ---\n");
}

static void cleanup(void) {
    if (g_gpio_initialized) {
        gpioTerminate();
        g_gpio_initialized = 0;
    }
    if (g_buffer_full) {
        print_buffer();
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to register SIGINT handler: %s\n", strerror(errno));
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Obstacle avoidance sensor started on GPIO %d. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (g_running) {
        int obstacle_detected = read_sensor();
        if (obstacle_detected < 0) {
            fprintf(stderr, "Error: failed to read sensor on GPIO %d.\n", GPIO_PIN);
            break;
        }

        if (obstacle_detected) {
            add_to_buffer(obstacle_detected);
            printf("Obstacle detected on GPIO %d!\n", GPIO_PIN);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

