/*
 * Raspberry Pi 5 - Omron D7S Vibration Sensor Reader
 *
 * Wiring:
 *   D7S SDA -> GPIO2 (BCM)
 *   D7S SCL -> GPIO3 (BCM)
 *   D7S VDD -> 3.3 V
 *   D7S GND -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o d7s_reader d7s_reader.c -lrt
 *
 * Run:
 *   ./d7s_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SENSOR_ADDR    0x50
#define SAMPLE_INTERVAL_US 500000   /* 500 ms */
#define POLL_DELAY_US    500000   /* 500 ms */
#define MAX_RETRIES     3
#define SAMPLE_DELAY_US  500000   /* 500 ms */
#define MAX_CONSEC_RETRIES 3

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Write a single byte to the sensor's register.
 * Returns 0 on success, -1 on failure.
 */
static int sensor_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

/*
 * Read a single byte from the sensor's register.
 * Returns 0 on success, -1 on failure.
 */
static int sensor_read_reg(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, out, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit big-endian value from the sensor's acceleration registers.
 * Returns 0 on success, -1 on failure.
 */
static int sensor_read_accel(int fd, int16_t *out)
{
    uint8_t buf[2];

    if (sensor_read_reg(fd, 0x00, buf) < 0)
        return -1;

    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/*
 * Write a CSV header row to the file if it is newly created.
 */
static int write_header(const char *filename)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s for writing: %s\n",
                filename, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "timestamp,x_axis,y_axis,z_axis\n") < 0) {
        fprintf(stderr, "Cannot write header: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", filename, strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    int fd = -1;
    FILE *fp = NULL;
    int16_t accel_x, accel_y, accel_z;
    int retries = 0;
    int consecutive_errors = 0;

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                SENSOR_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* --- Open CSV file --- */
    fp = fopen("fan_health.csv", "a");
    if (!fp) {
        fprintf(stderr, "Cannot open fan_health.csv: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Write header if file is newly created */
    if (fstat(fileno(fp), &fstat_buf) < 0) {
        fprintf(stderr, "Cannot stat fan_health.csv: %s\n", strerror(errno));
        fclose(fp);
        close(fd);
        return EXIT_FAILURE;
    }
    if (fstat_buf.st_size == 0) {
        if (write_header(fp) < 0) {
            fclose(fp);
            close(fd);
            return EXIT_FAILURE;
        }
    }

    /* --- Main loop --- */
    while (g_running) {
        if (sensor_read_accel(fd, &accel_x) < 0) {
            consecutive_errors++;
            if (consecutive_errors >= MAX_RETRIES) {
                fprintf(stderr, "Sensor read failed after %d attempts.\n",
                        MAX_RETRIES);
                fprintf(stderr, "Sensor may not be active or I2C bus may be busy.\n");
                break;
            }
            usleep(SAMPLE_DELAY_US);
            continue;
        }
        consecutive_errors = 0;

        if (write_header(fp) < 0) {
            fprintf(stderr, "Failed to write header to CSV file.\n");
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        time_t now = time(NULL);
        if (now == (time_t)-1) {
            fprintf(stderr, "time() failed: %s\n", strerror(errno));
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        struct tm tm_buf;
        struct tm *tm = localtime_r(&now, &tm_buf);
        if (!tm) {
            fprintf(stderr, "localtime_r() failed: %s\n", strerror(errno));
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        char ts[32];
        if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", tm) == 0) {
            fprintf(stderr, "strftime() failed\n");
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        if (fprintf(fp, "%s,%.2f,%.2f,%.2f\n", ts,
                    (double)accel_x, (double)accel_y, (double)accel_z) < 0) {
            fprintf(stderr, "fprintf to CSV failed: %s\n", strerror(errno));
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        if (fflush(fp) != 0) {
            fprintf(stderr, "fflush failed: %s\n", strerror(errno));
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        usleep(SAMPLE_DELAY_US);
    }

    /* --- Cleanup --- */
    if (fp) {
        fclose(fp);
    }
    if (fd >= 0) {
        close(fd);
    }
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

