/*
 * Raspberry Pi 4 Model B - KY-032 Obstacle Avoidance Sensor
 *
 * Wiring:
 *   Sensor 1 OUT -> GPIO23 (BCM)
 *   Sensor 2 OUT -> GPIO24 (BCM)
 *   LED Anode  -> GPIO25 (BCM) via 220-330 Ω resistor to GND
 *
 * Build: gcc -O2 -Wall -o ky032_obstacle ky032_obstacle.c -lpigpio -lrt
 * Run:   sudo ./ky032_obstacle
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_PIN  23
#define SENSOR2_PIN  24
#define LED_PIN      25

#define OBSTACLE_THRESHOLD_CM 10.0f
#define POLL_INTERVAL_US 100000   /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a KY-032 sensor.
 * Returns 0 on success (sensor reading LOW), -1 on error.
 */
static int read_sensor(int pin)
{
    int level = gpioRead(pin);
    if (level < 0) {
        fprintf(stderr, "Error: gpioRead failed on pin %d\n", pin);
        return -1;
    }
    return level;
}

/*
 * Drive the LED.
 * Returns 0 on success, -1 on error.
 */
static int drive_led(int pin, int state)
{
    if (gpioWrite(pin, state) < 0) {
        fprintf(stderr, "Error: gpioWrite failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

int main(void)
{
    /* --- Signal handling --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure sensor pins as inputs --- */
    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for sensor 1 pin %d\n", SENSOR1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for sensor 2 pin %d\n", SENSOR2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for LED pin %d\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure LED is off at startup */
    if (drive_led(LED_PIN, 0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("KY-032 obstacle avoidance system started.\n");
    printf("Sensor 1 OUT -> GPIO%d, Sensor 2 OUT -> GPIO%d, LED -> GPIO%d\n",
           SENSOR1_PIN, SENSOR2_PIN, LED_PIN);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main polling loop --- */
    while (g_running) {
        int s1 = read_sensor(SENSOR1_PIN);
        int s2 = read_sensor(SENSOR2_PIN);

        if (s1 < 0 || s2 < 0) {
            /* Sensor read error already reported; continue polling. */
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        /* KY-032 outputs LOW when obstacle detected */
        if (s1 == 0 && s2 == 0) {
            if (drive_led(LED_PIN, 1) != 0) {
                gpioDelay(POLL_INTERVAL_US);
                continue;
            }
            printf("Obstacle detected! LED ON.\n");
            gpioDelay(POLL_INTERVAL_US);
            if (drive_led(LED_PIN, 0) != 0) {
                gpioDelay(POLL_INTERVAL_US);
                continue;
            }
            printf("LED OFF.\n");
            gpioDelay(POLL_INTERVAL_US);
        } else {
            gpioDelay(POLL_INTERVAL_US);
        }
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    drive_led(LED_PIN, 0);
    gpioTerminate();
    printf("Resources released. Exiting.\n");
    return EXIT_SUCCESS;
}

