/*
 * TMAG5170-Q1 3D Hall-Effect Sensor I2C reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   TMAG5170-Q1 SDA -> GPIO2 (I2C1 SDA, pin 3)
 *   TMAG5170-Q1 SCL -> GPIO3 (I2C1 SCL, pin 5)
 *   TMAG5170-Q1 VDD -> 3.3 V
 *   TMAG5170-Q1 GND -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o tmag5170_log tmag5170_log.c
 * Run:    ./tmag5170_log   (or use sudo if /dev/i2c-1 is not writable)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define TMAG5170_ADDR  0x60
#define LOG_FILE       "magnetic_log.csv"
#define SAMPLE_US      100000   /* 100 ms */

/* TMAG5170 register addresses */
#define TMAG5170_REG_CONFIG   0x00
#define TMAG5170_REG_DATA_X   0x01
#define TMAG5170_REG_DATA_Y   0x02
#define TMAG5170_REG_DATA_Z   0x03

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                          */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, out, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
/* TMAG5170 library                                                    */
/* ------------------------------------------------------------------ */
/*
 * The TMAG5170-Q1 library provides a C API for reading magnetic field
 * values from the sensor.  It is available in the TI MSP430-TMAG5170
 * software package (https://www.ti.com/tool/TMAG5170-Q1).
 *
 * The library provides a single function:
 *   int tmag5170_read_mag(int fd, float *x, float *y, float *z)
 *   Returns 0 on success, -1 on I2C error, -2 on data-read error.
 */
static int tmag5170_read_mag(int fd, float *x, float *y, float *z)
{
    uint8_t reg = TMAG5170_REG_DATA_X;
    uint8_t data[3];

    if (i2c_write_reg8(fd, reg, 0x00) != 0)
        return -1;

    if (i2c_read_reg8(fd, reg, data) != 0)
        return -1;

    *x = (float)data[0] / 0x80.0f;
    *y = (float)data[1] / 0x80.0f;
    *z = (float)data[2] / 0x80.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float x, float y, float z)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.3f,%.3f,%.3f\n", ts, x, y, z) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the I2C slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, TMAG5170_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                TMAG5170_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure sensor: continuous-conversion mode, all axes enabled */
    if (i2c_write_reg8(g_i2c_fd, TMAG5170_REG_CONFIG, 0x0F) != 0) {
        fprintf(stderr, "Failed to configure TMAG5170\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open CSV log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_fp, 0, SEEK_END);
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,x,y,z\n");
        fflush(g_log_fp);
    }

    printf("TMAG5170 logging started. Press Ctrl-C to stop.\n");

    /* Main loop */
    while (g_running) {
        float x, y, z;

        if (tmag5170_read_mag(g_i2c_fd, &x, &y, &z) == 0) {
            if (log_data(g_log_fp, x, y, z) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_US / 100000 && g_running; i++)
            usleep(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

