    /* Configure sensor: continuous-conversion mode, all axes enabled */
    if (i2c_write_reg8(g_i2c_fd, TMAG5170_REG_CONFIG, 0x0F) != 0) {
        fprintf(stderr, "Failed to configure TMAG5170\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open CSV log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_fp, 0, SEEK_END);
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,x,y,z\n");
        fflush(g_log_fp);
    }

    printf("TMAG5170 logging started. Press Ctrl-C to stop.\n");

    /* Main loop */
    while (g_running) {
        float x, y, z;

        if (tmag5170_read_mag(g_i2c_fd, &x, &y, &z) == 0) {
            if (log_data(g_log_fp, x, y, z) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_US / 100000 && g_running; i++)
            usleep(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

