/*
 * Raspberry Pi Zero W - Water Level Sensor Alert Daemon
 *
 * Wiring:
 *   SEN0193 VCC  -> 3.3V (Pin 1)
 *   SEN0193 GND  -> GND  (Pin 6)
 *   SEN0193 OUT  -> GPIO23 (Pin 11, BCM)
 *   Pull-down:  10kΩ resistor to GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o water_alert water_alert.c -lpigpio -lrt
 * Run:    sudo ./water_alert
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_PIN        23
#define LOG_FILE          "flood_log.txt"
#define POLL_INTERVAL_S   2
#define REINIT_INTERVAL_S 60
#define MAX_RETRIES       3

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read the SEN0193 digital output.
 * Returns 0 on success (water detected), 1 on dry, -1 on error.
 */
static int read_sensor(void)
{
    int level = gpioRead(SENSOR_PIN);
    if (level < 0) {
        fprintf(stderr, "Error: gpioRead failed on pin %d (code %d).\n",
                SENSOR_PIN, level);
        return -1;
    }
    return level;
}

/*
 * Append a timestamped alert to the log file.
 * Returns 0 on success, -1 on error.
 */
static int log_alert(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return -1;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: cannot open %s for appending.\n", LOG_FILE);
        return -1;
    }

    if (fprintf(fp, "%s ALERT: Water detected\n", timestamp) < 0) {
        fprintf(stderr, "Error: failed to write to log file.\n");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error: failed to close log file.\n");
        return -1;
    }

    return 0;
}

/*
 * Re-initialize the GPIO driver.
 * Returns 0 on success, -1 on error.
 */
static int reinit_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: gpioInitialise failed.\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d.\n", SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for pin %d.\n", SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: gpioInitialise failed.\n");
        return EXIT_FAILURE;
    }

    if (reinit_gpio() != 0) {
        fprintf(stderr, "Error: GPIO reinitialization failed.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Water level sensor daemon started.\n");
    printf("  Sensor pin: GPIO%d\n", SENSOR_PIN);
    printf("  Log file: %s\n", LOG_FILE);
    printf("  Polling every %d seconds. Press Ctrl+C to exit.\n", POLL_INTERVAL_S);

    while (g_running) {
        int level = read_sensor();

        if (level < 0) {
            /* Sensor read error; attempt re-initialization. */
            if (g_running) {
                fprintf(stderr, "Warning: sensor read error; re-initializing GPIO.\n");
                if (reinit_gpio() != 0) {
                    fprintf(stderr, "Error: GPIO reinitialization failed.\n");
                    break;
                }
            }
            continue;
        }

        if (level == 1) {
            printf("Water detected!\n");
            if (log_alert() != 0) {
                fprintf(stderr, "Warning: failed to log alert.\n");
            }
        }

        /* Sleep in small increments so signals are caught promptly. */
        for (int i = 0; i < POLL_INTERVAL_S && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    printf("\nShutting down...\n");
    gpioTerminate();
    return EXIT_SUCCESS;
}

