/*
 * RPM counter for a Melexis MLX90217 Hall-effect sensor on Raspberry Pi 4.
 *
 * Wiring:
 *   MLX90217 OUT -> GPIO4 (BCM 4)
 *   MLX90217 VCC -> 3.3 V
 *   MLX90217 GND -> GND
 *
 * The sensor output is a digital signal; the internal pull-up is enabled
 * on BCM 4.  The library provides a callback that increments a pulse-count
 * register on each rising edge; the program reads this register once per
 * second and computes revolutions per minute.
 *
 * Build:  gcc -O2 -Wall -Wextra -o rpm_counter rpm_counter.c -lpigpio -lrt
 * Run:    sudo ./rpm_counter
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_GPIO        4
#define LOG_FILE           "rpm_log.txt"
#define SAMPLE_PERIOD_US   1000000   /* 1 second */
#define PULSE_COUNT_THRESH 0        /* pulses per second */

/* ------------------------------------------------------------------ */
/* Globals                                                             */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static void log_rpm(float rpm)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time");
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        perror("localtime_r");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(g_log_fp, "%s RPM: %.2f\n", ts, rpm) < 0) {
        perror("fprintf");
    }
    if (fflush(g_log_fp) != 0) {
        perror("fflush");
    }
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */

/*
 * Read the pulse-count register once per second.
 * Returns the pulse count (0–255) on success, or -1 on error.
 */
static int read_pulse_count(void)
{
    int count = gpioRead(SENSOR_GPIO);
    if (count < 0) {
        fprintf(stderr, "gpioRead failed on GPIO %d: %s\n",
                SENSOR_GPIO, pigpio_error(count));
        return -1;
    }
    return count;
}

/*
 * Install a rising-edge interrupt on the GPIO pin.
 * Returns 0 on success, -1 on failure.
 */
static int install_rising_edge_interrupt(void)
{
    if (gpioSetAlertFunc(SENSOR_GPIO, read_pulse_count) != 0) {
        fprintf(stderr, "gpioSetAlertFunc failed on GPIO %d\n", SENSOR_GPIO);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */

static void cleanup_gpio(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

static void cleanup_all(void)
{
    gpioTerminate();
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* --- Install signal handlers ----------------------------------- */
    install_signal_handlers();

    /* --- Open log file ---------------------------------------------- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio ------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO as input with pull-up ---------------------------- */
    if (gpioSetMode(SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", SENSOR_GPIO);
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for GPIO %d\n", SENSOR_GPIO);
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    /* --- Register rising-edge interrupt --------------------------------*/
    if (install_rising_edge_interrupt() != 0) {
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    printf("RPM counter started. Logging to %s every second. Press Ctrl+C to exit.\n",
           LOG_FILE);

    /* --- Main sampling loop ------------------------------------------ */
    while (g_running) {
        int pulse_count = read_pulse_count();
        if (pulse_count < 0) {
            /* Error already reported; continue. */
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        /* Compute revolutions per minute. */
        float rpm = (float)pulse_count / PULSE_COUNT_THRESH;
        if (rpm < 0.0f) {
            rpm = 0.0f;
        }

        log_rpm(rpm);
        printf("RPM: %.2f\n", rpm);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Graceful shutdown ------------------------------------------- */
    printf("\nShutting down...\n");
    cleanup_all();
    return EXIT_SUCCESS;
}

