 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o rotation_monitor rotation_monitor.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./rotation_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR_A_GPIO 17
#define SENSOR_B_GPIO 27
#define LOG_FILE "rotation_log.txt"
#define POLL_DELAY_US 10000   /* 10 ms */
#define MAX_CONSECUTIVE_ERRORS 10

/* Quadrature state machine */
typedef enum {
    QUADRATURE_STATE_INIT,
    QUADRATURE_STATE_A_CCW,
    QUADRATURE_STATE_B_CCW,
    QUADRATURE_STATE_A_CW,
    QUADRATURE_STATE_B_CW,
    QUADRATURE_STATE_ERROR
} QuadratureState;

static volatile sig_atomic_t g_running = 1;
static volatile sig_atomic_t g_log_ready = 0;
static volatile sig_atomic_t g_log_flush = 0;
static volatile sig_atomic_t g_log_file_open = 0;

/* ------------------------------------------------------------------ */
/* Mutex for shared state between ISR and main thread                */
/* ------------------------------------------------------------------ */
static volatile sig_atomic_t g_mutex_lock_count = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_rotation(QuadratureState state)
{
    FILE *fp = NULL;
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    if (g_log_file_open) {
        fp = fopen(LOG_FILE, "a");
        if (!fp) {
            fprintf(stderr, "Error opening log file '%s': %s\n",
                    LOG_FILE, strerror(errno));
            return;
        }
        if (fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d.%03d, Quadrature State: %s\n",
                    (int)time(NULL),
                    tm_year(timeinfo), tm_mon(timeinfo),
                    tm_mday(timeinfo),
                    tm_hour(timeinfo),
                    tm_min(timeinfo),
                    tm_sec(timeinfo),
                    (int)g_log_flush) < 0) {
            fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        }
        fclose(fp);
        g_log_file_open = 0;
    }

    if (state == QUADRATURE_STATE_ERROR) {
        snprintf(timestamp, sizeof(timestamp), "ERROR: Sensor A or Sensor B error");
    } else {
        snprintf(timestamp, sizeof(timestamp), "Rotation: Quadrature State: %s",
                 state == QUADRATURE_STATE_A_CCW ? "A_CCW" :
                 state == QUADRATURE_STATE_B_CCW ? "B_CCW" :
                 state == QUADRATURE_STATE_A_CW ? "A_CW" :
                 state == QUADRATURE_STATE_B_CW ? "B_CW" :
                 "ERROR");
    }

    if (g_log_flush) {
        time(&rawtime);
        if (localtime_r(&rawtime, &timeinfo) != NULL) {
            if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                         &timeinfo) > 0) {
                if (g_log_flush) {
                    if (fprintf(stdout, "%s, %s\n", timestamp, timestamp) < 0) {
                        fprintf(stderr, "Error writing to stdout: %s\n", strerror(errno));
                    }
                    g_log_flush = 0;
                }
            }
        }
    }
}

/* ------------------------------------------------------------------ */
/* Interrupt service routine                                           */
/* ------------------------------------------------------------------ */
static void sensor_isr(int gpio, int level, uint32_t tick, void *user_data)
{
    (void)gpio;
    (void)tick;
    (void)user_data;

    if (level == 1) {
        /* Sensor A: edge-triggered alert */
        g_mutex_lock_count++;
        if (g_mutex_lock_count == 1) {
            g_log_flush = 1;
        }
        g_log_ready = 1;
    } else if (level == 0) {
        /* Sensor B: edge-triggered alert */
        g_mutex_lock_count++;
        if (g_mutex_lock_count == 1) {
            g_log_flush = 1;
        }
        g_log_ready = 1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int ret = EXIT_FAILURE;

    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_file_open = 1;
    g_log_flush = 0;
    g_log_ready = 0;

    /* --- Open log file in append mode --- */
    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGTERM handler: %s\n",
                strerror(errno));
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(SENSOR_A_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", SENSOR_A_GPIO);
        goto cleanup;
    }
    if (gpioSetMode(SENSOR_B_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", SENSOR_B_GPIO);
        goto cleanup;
    }

    /* Enable pull-up resistors on the sensors */
    if (gpioSetPullUpDown(SENSOR_A_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error setting pull-up on GPIO %d\n", SENSOR_A_GPIO);
        goto cleanup;
    }
    if (gpioSetPullUpDown(SENSOR_B_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error setting pull-up on GPIO %d\n", SENSOR_B_GPIO);
        goto cleanup;
    }

    /* --- Register ISR --- */
    if (gpioSetISRFuncEx(SENSOR_A_GPIO, EITHER_EDGE, 0,
                         sensor_isr, NULL) != 0) {
        fprintf(stderr, "Error setting ISR for GPIO %d\n", SENSOR_A_GPIO);
        goto cleanup;
    }
    if (gpioSetISRFuncEx(SENSOR_B_GPIO, EITHER_EDGE, 0,
                         sensor_isr, NULL) != 0) {
        fprintf(stderr, "Error setting ISR for GPIO %d\n", SENSOR_B_GPIO);
        goto cleanup;
    }

    printf("Rotation monitor started. Sensor A: GPIO%d, Sensor B: GPIO%d\n",
           SENSOR_A_GPIO, SENSOR_B_GPIO);
    printf("Logging to '%s'. Press Ctrl+C to exit.\n", LOG_FILE);

    /* --- Main loop --- */
    while (g_running) {
        /* --- Wait for log ready signal --- */
        if (g_log_ready) {
            g_log_ready = 0;
            g_log_flush = 1;
            g_log_ready = 1;
        } else {
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* --- Wait for ISR to fire --- */
        if (g_log_ready) {
            g_log_ready = 0;
            g_log_flush = 1;
            g_log_ready = 1;
        } else {
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* --- ISR fires: log rotation --- */
        QuadratureState prev_state = QUADRATURE_STATE_ERROR;
        QuadratureState curr_state = QUADRATURE_STATE_ERROR;

        if (g_log_ready) {
            curr_state = QUADRATURE_STATE_A_CCW;
            prev_state = QUADRATURE_STATE_A_CCW;
        } else {
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (curr_state == QUADRATURE_STATE_A_CCW) {
            if (prev_state == QUADRATURE_STATE_A_CW) {
                log_rotation(QUADRATURE_STATE_A_CCW);
            } else if (prev_state == QUADRATURE_STATE_B_CCW) {
                log_rotation(QUADRATURE_STATE_B_CCW);
            } else {
                log_rotation(QUADRATURE_STATE_A_CW);
            }
        } else if (curr_state == QUADRATURE_STATE_B_CCW) {
            if (prev_state == QUADRATURE_STATE_A_CW) {
                log_rotation(QUADRATURE_STATE_B_CCW);
            } else if (prev_state == QUADRATURE_STATE_A_CCW) {
                log_rotation(QUADRATURE_STATE_A_CCW);
            } else {
                log_rotation(QUADRATURE_STATE_B_CW);
            }
        } else if (curr_state == QUADRATURE_STATE_A_CW) {
            if (prev_state == QUADRATURE_STATE_B_CCW) {
                log_rotation(QUADRATURE_STATE_A_CW);
            } else if (prev_state == QUADRATURE_STATE_B_CCW) {
                log_rotation(QUADRATURE_STATE_B_CCW);
            } else {
                log_rotation(QUADRATURE_STATE_A_CCW);
            }
        } else if (curr_state == QUADRATURE_STATE_B_CW) {
            if (prev_state == QUADRATURE_STATE_A_CCW) {
                log_rotation(QUADRATURE_STATE_B_CW);
            } else if (prev_state == QUADRATURE_STATE_A_CCW) {
                log_rotation(QUADRATURE_STATE_A_CCW);
            } else {
                log_rotation(QUADRATURE_STATE_B_CW);
            }
        } else {
            /* Error state: log a generic error */
            log_rotation(QUADRATURE_STATE_ERROR);
        }

        /* --- Flush log file periodically --- */
        if (g_log_flush) {
            if (g_log_ready) {
                g_log_ready = 0;
                g_log_flush = 1;
            } else {
                gpioDelay(POLL_DELAY_US);
                continue;
            }
        }
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* --- Close log file --- */
    if (g_log_file_open) {
        fclose(fp);
        g_log_file_open = 0;
    }

    /* --- Terminate pigpio --- */
    gpioTerminate();

    return ret;
}

