#define SENSOR_PIN 23
#define LED_PIN    18
#define POLL_DELAY_US 50000  /* 50 ms */
#define MAX_CONSECUTIVE_ERRORS 10

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_message(int priority, const char *msg)
{
    char buf[256];
    snprintf(buf, sizeof(buf),
             "%s: %s (errno=%d: %s)",
             priority == LOG_ERR ? "ERROR" : "INFO",
             msg,
             errno,
             strerror(errno));
    syslog(priority, "%s", buf);
}

static int setup_gpio(void)
{
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        log_message(LOG_ERR, "Failed to set sensor pin mode");
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        log_message(LOG_ERR, "Failed to set LED pin mode");
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        log_message(LOG_ERR, "Failed to initialise LED pin state");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_sensor(void)
{
    int val = gpioRead(SENSOR_PIN);
    if (val < 0) {
        log_message(LOG_ERR, "Failed to read sensor pin");
        return -1;
    }
    return val;
}

static void control_led(int state)
{
    if (gpioWrite(LED_PIN, state) != 0) {
        log_message(LOG_ERR, "Failed to write to LED pin");
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        log_message(LOG_ERR, "Failed to install SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        log_message(LOG_ERR, "Failed to install SIGTERM handler");
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0) {
        log_message(LOG_ERR, "GPIO setup failed, exiting");
        return EXIT_FAILURE;
    }

    log_message(LOG_INFO, "GPIO initialized successfully");

    int consecutive_errors = 0;

    while (g_running) {
        int sensor_val = read_sensor();
        if (sensor_val < 0) {
            consecutive_errors++;
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                log_message(LOG_ERR, "Too many consecutive GPIO read errors, aborting");
                break;
            }
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        consecutive_errors = 0;

        if (sensor_val == 1) {
            control_led(1);
        } else {
            control_led(0);
        }

        gpioDelay(POLL_DELAY_US);
    }

    log_message(LOG_INFO, "Shutting down GPIO");
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

