#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define LED1_PIN 27
#define LED2_PIN 22
#define BUFFER_SIZE 100
#define DEBOUNCE_MS 50
#define POLL_INTERVAL_MS 100

typedef struct {
    int pin;
    time_t timestamp;
    bool state;
    uint32_t overflow_count;
} sensor_data_t;

static sensor_data_t log_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_touch(int pin) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error: time() failed\n");
        return;
    }
    log_buffer[buffer_index].pin = pin;
    log_buffer[buffer_index].timestamp = now;
    log_buffer[buffer_index].state = true;
    log_buffer[buffer_index].overflow_count = 0;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

static void log_release(int pin) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error: time() failed\n");
        return;
    }
    log_buffer[buffer_index].pin = pin;
    log_buffer[buffer_index].timestamp = now;
    log_buffer[buffer_index].state = false;
    log_buffer[buffer_index].overflow_count = 0;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

static void cleanup(void) {
    if (gpioInitialise() >= 0) {
        gpioWrite(LED1_PIN, 0);
        gpioWrite(LED2_PIN, 0);
        gpioTerminate();
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set SENSOR1_PIN %d as input\n", SENSOR1_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set SENSOR2_PIN %d as input\n", SENSOR2_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set LED1_PIN %d as output\n", LED1_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set LED2_PIN %d as output\n", LED2_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on SENSOR1_PIN\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on SENSOR2_PIN\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(LED1_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on LED1_PIN\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(LED2_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on LED2_PIN\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to register SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to register SIGTERM handler\n");
    }

    printf("Touch sensor logging started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor1_val = gpioRead(SENSOR1_PIN);
        int sensor2_val = gpioRead(SENSOR2_PIN);

        if (sensor1_val < 0 || sensor2_val < 0) {
            fprintf(stderr, "Error: failed to read sensor pins\n");
            gpioDelay(POLL_INTERVAL_MS * 1000);
            continue;
        }

        bool touch1 = (sensor1_val == 1);
        bool touch2 = (sensor2_val == 1);

        if (touch1) {
            log_touch(SENSOR1_PIN);
            gpioWrite(LED1_PIN, 1);
            gpioWrite(LED2_PIN, 0);
        } else if (touch2) {
            log_touch(SENSOR2_PIN);
            gpioWrite(LED1_PIN, 0);
            gpioWrite(LED2_PIN, 1);
        } else {
            gpioWrite(LED1_PIN, 0);
            gpioWrite(LED2_PIN, 0);
        }

        gpioDelay(DEBOUNCE_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Log buffer cleared.\n");
    return EXIT_SUCCESS;
}

