#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define RAINDROP_GPIO 17
#define LOG_FILE "/var/log/rain_events.log"
#define POLL_INTERVAL_US 500000  /* 500 ms */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly                */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a timestamped message to the log file                          */
/* ------------------------------------------------------------------ */
static void log_event(const char *message)
{
    if (!g_log_file)
        return;

    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (fprintf(g_log_file, "[%s] %s\n", timestamp, message) < 0) {
        fprintf(stderr, "fprintf() to log file failed: %s\n", strerror(errno));
    } else {
        fflush(g_log_file);
    }
}

/* ------------------------------------------------------------------ */
/* Read the rain sensor state from the GPIO pin                        */
/* ------------------------------------------------------------------ */
static int read_rain_sensor(int gpio_pin)
{
    int level = gpioRead(gpio_pin);
    if (level < 0) {
        fprintf(stderr, "gpioRead(%d) failed: %s\n",
                gpio_pin, pigpio_error(level));
        return -1;
    }
    return level;
}

/* ------------------------------------------------------------------ */
/* Write a log entry                                                    */
/* ------------------------------------------------------------------ */
static void log_event_with_timestamp(const char *message)
{
    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S",
                 localtime(&(time_t)time(NULL))) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    log_event(timestamp);
    printf("%s\n", message);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pin as input with pull-up --- */
    if (gpioSetMode(RAINDROP_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", RAINDROP_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(RAINDROP_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_UP) failed\n",
                RAINDROP_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Open log file in append mode --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Raindrop monitoring started on GPIO%d. Press Ctrl+C to exit.\n",
           RAINDROP_GPIO);

    /* --- Main polling loop --- */
    while (g_running) {
        int rain_detected = read_rain_sensor(RAINDROP_GPIO);
        if (rain_detected < 0) {
            /* Error already reported; skip this cycle. */
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (rain_detected == 0) {
            log_event("Rain Detected");
        } else {
            log_event("No Rain");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

