#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define DEBOUNCE_MS 5
#define LOG_FILE "shaft_log.txt"
#define POLL_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hall_effect(int pin) {
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", pin, strerror(errno));
        return -1;
    }
    return v;
}

static int debounce(int v, int last) {
    return (v == last) ? 0 : 1;
}

static int log_data(int sensor1, int sensor2) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%d,%d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                sensor1, sensor2);
    } else {
        fprintf(fp, "Timestamp error\n");
    }
    fclose(fp);
    return 0;
}

static double calculate_rpm(int sensor1, int sensor2) {
    int v1 = debounce(read_hall_effect(SENSOR1_PIN), 0);
    int v2 = debounce(read_hall_effect(SENSOR2_PIN), 0);
    if (v1 < 0 || v2 < 0) return -1.0;
    return (double)v1 * 60.0 + (double)v2 * 60.0 / 60.0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", SENSOR1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", SENSOR2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring RPM on GPIO %d and %d. Press Ctrl+C to exit.\n",
           SENSOR1_PIN, SENSOR2_PIN);

    while (running) {
        int v1 = read_hall_effect(SENSOR1_PIN);
        int v2 = read_hall_effect(SENSOR2_PIN);
        if (v1 < 0 || v2 < 0) {
            fprintf(stderr, "Sensor read error, retrying...\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        int debounced1 = debounce(v1, 0);
        int debounced2 = debounce(v2, 0);
        if (debounced1 < 0 || debounced2 < 0) {
            fprintf(stderr, "Debounce error, retrying...\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        double rpm = calculate_rpm(debounced1, debounced2);
        if (rpm < 0.0) {
            fprintf(stderr, "Invalid RPM calculation, retrying...\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (log_data(debounced1, debounced2) != 0) {
            fprintf(stderr, "Logging failed, retrying...\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        printf("Sensor1: %d, Sensor2: %d, RPM: %.2f\n",
               debounced1, debounced2, rpm);
        gpioDelay(POLL_DELAY_US);
    }

    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

