/*
 * Si1182 I2C optical heart rate and SpO2 monitor for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   Si1182 SDA -> GPIO 2 (I2C bus 1 SDA)
 *   Si1182 SCL -> GPIO 3 (I2C bus 1 SCL)
 *   Si1182 VDD -> 3.3 V
 *   Si1182 GND -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o si1182_monitor si1182_monitor.c -lm
 *
 * Run:
 *   ./si1182_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1182_ADDR    0x50
#define LOG_FILE       "biometric_log.txt"
#define SAMPLE_INTERVAL_SEC 1

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a 16-bit register from the Si1182.
 * Returns 0 on success, -1 on error.
 */
static int si1182_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    ssize_t n;

    /* Write the register address */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }

    /* Read 2 bytes */
    n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read reg 0x%02X failed: got %zd bytes, %s\n",
                reg, n, strerror(errno));
        return -1;
    }

    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/*
 * Read a 16-bit register from the Si1182.
 * Returns 0 on success, -1 on error.
 */
static int si1182_read_reg16_u(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    ssize_t n;

    /* Write the register address */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }

    /* Read 2 bytes */
    n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read reg 0x%02X failed: got %zd bytes, %s\n",
                reg, n, strerror(errno));
        return -1;
    }

    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/*
 * Read a 16-bit register from the Si1182.
 * Returns 0 on success, -1 on error.
 */
static int si1182_read_reg16_u_p(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    ssize_t n;

    /* Write the register address */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }

    /* Read 2 bytes */
    n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read reg 0x%02X failed: got %zd bytes, %s\n",
                reg, n, strerror(errno));
        return -1;
    }

    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/*
 * Read a 16-bit register from the Si1182.
 * Returns 0 on success, -1 on error.
 */
static int si1182_read_reg16_p(int fd, uint8_t reg, int16_t *out)
{
    uint8_t buf[2];
    ssize_t n;

    /* Write the register address */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }

    /* Read 2 bytes */
    n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read reg 0x%02X failed: got %zd bytes, %s\n",
                reg, n, strerror(errno));
        return -1;
    }

    *out = (int16_t)((uint16_t)buf[0] | ((uint16_t)buf[1] << 8));
    return 0;
}

/*
 * Read a 16-bit register from the Si1182.
 * Returns 0 on success, -1 on error.
 */
static int si1182_read_reg16_p_u(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    ssize_t n;

    /* Write the register address */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }

    /* Read 2 bytes */
    n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read reg 0x%02X failed: got %zd bytes, %s\n",
                reg, n, strerror(errno));
        return -1;
    }

    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/*
 * Read a 16-bit register from the Si1182.
 * Returns 0 on success, -1 on error.
 */
static int si1182_read_reg16_p_u_p(int fd, uint8_t reg, int16_t *out)
{
    uint8_t buf[2];
    ssize_t n;

    /* Write the register address */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }

    /* Read 2 bytes */
    n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read reg 0x%02X failed: got %zd bytes, %s\n",
                reg, n, strerror(errno));
        return -1;
    }

    *out = (int16_t)((uint16_t)buf[0] | ((uint16_t)buf[1] << 8));
    return 0;
}

/*
 * Open the I2C bus and acquire the Si1182 sensor.
 * Returns 0 on success, -1 on error.
 */
static int open_i2c(void)
{
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                SI1182_ADDR, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * Close the I2C bus and the log file.
 */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

int main(void)
{
    int fd = -1;
    int16_t heart_rate = -1;
    int spo2 = -1;
    time_t now = time(NULL);
    struct tm *tm_info;
    char timestamp[32];
    char log_line[256];

    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Write the header if the file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "Heart Rate: 0 BPM, SpO2: 0%%\n");
        fflush(g_log_fp);
    }

    /* Open the I2C bus */
    fd = open_i2c();
    if (fd < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Acquire the Si1182 sensor */
    if (si1182_read_reg16_p_u_p(fd, SI1182_ADDR, &spo2) != 0) {
        fprintf(stderr, "Failed to acquire Si1182 sensor data.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Read the heart rate */
    if (si1182_read_reg16_p_u(fd, SI1182_ADDR, &heart_rate) != 0) {
        fprintf(stderr, "Failed to read heart rate data.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Get the current time */
    tm_info = localtime(&now);
    if (!tm_info) {
        fprintf(stderr, "Failed to get local time: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Format the timestamp */
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    /* Append the data to the log file */
    snprintf(log_line, sizeof(log_line), "%s, Heart Rate: %d BPM, SpO2: %d%%",
             timestamp, heart_rate, spo2);
    if (fprintf(g_log_fp, "%s\n", log_line) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
