#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define ALARM_PIN 27
#define LOG_FILE "bridge_integrity.log"
#define POLL_INTERVAL_US 100000
#define ALARM_DURATION_SEC 2

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_event(const char *event_type) {
    if (!log_file) return -1;
    time_t now = time(NULL);
    if (now == (time_t)-1) return -1;
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) return -1;
    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) return -1;
    if (fprintf(log_file, "%s - %s\n", timestamp, event_type) < 0) return -1;
    if (fflush(log_file) != 0) return -1;
    return 0;
}

static int log_error(const char *message) {
    time_t now = time(NULL);
    if (now == (time_t)-1) return -1;
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) return -1;
    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) return -1;
    if (fprintf(log_file, "%s - ERROR: %s\n", timestamp, message) < 0) return -1;
    if (fflush(log_file) != 0) return -1;
    return 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR1_PIN);
        return -1;
    }
    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR2_PIN);
        return -1;
    }
    if (gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO%d\n", SENSOR1_PIN);
        return -1;
    }
    if (gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO%d\n", SENSOR2_PIN);
        return -1;
    }
    if (gpioSetMode(ALARM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", ALARM_PIN);
        return -1;
    }
    if (gpioWrite(ALARM_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize GPIO%d LOW\n", ALARM_PIN);
        return -1;
    }
    return 0;
}

static int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Failed to read GPIO%d\n", pin);
        return -1;
    }
    return value;
}

static void cleanup(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(ALARM_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        gpioWrite(ALARM_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Bridge integrity monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor1 = read_sensor(SENSOR1_PIN);
        int sensor2 = read_sensor(SENSOR2_PIN);

        if (sensor1 < 0 || sensor2 < 0) {
            log_error("Sensor read error");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (sensor1 == 1 && sensor2 == 1) {
            if (log_event("ALARM_THRESHOLD_EXCEEDED") != 0) {
                log_error("Failed to log alarm event");
            }
            if (gpioWrite(ALARM_PIN, 1) != 0) {
                log_error("Failed to activate alarm");
            }
        } else if (sensor1 == 1 && sensor2 == 0) {
            if (log_event("ALARM_START") != 0) {
                log_error("Failed to log alarm start event");
            }
            if (gpioWrite(ALARM_PIN, 1) != 0) {
                log_error("Failed to activate alarm");
            }
        } else if (sensor1 == 0 && sensor2 == 1) {
            if (log_event("ALARM_START") != 0) {
                log_error("Failed to log alarm start event");
            }
            if (gpioWrite(ALARM_PIN, 1) != 0) {
                log_error("Failed to activate alarm");
            }
        } else if (sensor1 == 0 && sensor2 == 0) {
            if (log_event("ALARM_STOP") != 0) {
                log_error("Failed to log alarm stop event");
            }
            if (gpioWrite(ALARM_PIN, 0) != 0) {
                log_error("Failed to deactivate alarm");
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

