/*
 * Raspberry Pi 5 - Four KY-032 Obstacle Avoidance Sensor Reader
 *
 * Wiring:
 *   KY-032 OUT -> GPIO4, GPIO17, GPIO27, GPIO22 (BCM)
 *   LED anode -> GPIO18 (BCM)
 *
 * Behavior:
 *   Reads the four sensor OUT pins every 50 ms.
 *   LED is ON when any sensor reports an object (active-low).
 *   Clean shutdown on SIGINT/SIGTERM.
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_SENSORS 4
#define LED_PIN      18
#define POLL_DELAY_US 50000   /* 50 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single KY-032 OUT pin.
 * Returns 0 (object detected) or 1 (no object).
 * The sensor is active-low; a logic 0 indicates an object.
 */
static int read_sensor(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "gpioRead(%d) failed: %d\n", pin, v);
        return -1;
    }
    return (v == 0) ? 1 : 0;
}

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure sensor pins as inputs --- */
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (gpioSetMode(i, PI_INPUT) < 0) {
            fprintf(stderr, "gpioSetMode(%d) failed\n", i);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        /* KY-032 OUT is active-low; 0 = object detected. */
        if (gpioSetPullUpDown(i, PI_PUD_DOWN) < 0) {
            fprintf(stderr, "gpioSetPullUpDown(%d) failed\n", i);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

