/*
 * flame_monitor.c — Raspberry Pi 3 Model B+
 *
 * Five KY-026 flame sensors on BCM GPIO 2, 3, 4, 17, 27.
 * Polling once per second; on a change from HIGH to LOW,
 * performs a 50 ms debounce re-read to confirm the flame event.
 *
 * Build:  gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lgpiod
 * Run:    sudo ./flame_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/file.h>
#include <sys/flock.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <gpiod.h>

#define NUM_SENSORS 5
#define POLL_INTERVAL_SEC 1
#define DEBOUNCE_MS   50
#define LOG_FILE      "/var/log/flame_events.log"

/* BCM GPIO pins for the KY-026 sensors */
static const unsigned int sensor_pins[NUM_SENSORS] = {
    2, 3, 4, 17, 27
};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(const char *sensor_id, int gpio_pin)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s - Sensor %s (GPIO %u) - Flame Detected\n",
                ts, sensor_id, gpio_pin);
    } else {
        fprintf(fp, "Error: localtime_r failed\n");
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
    }
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* File I/O                                                            */
/* ------------------------------------------------------------------ */
static int acquire_line(struct gpiod_line *line, const char *filename)
{
    int fd = open(filename, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", filename, strerror(errno));
        return -1;
    }

    if (flock(fd, LOCK_EX) == -1) {
        fprintf(stderr, "Error locking %s: %s\n", filename, strerror(errno));
        close(fd);
        return -1;
    }

    char buf[4096];
    ssize_t n = read(fd, buf, sizeof(buf) - 1);
    if (n < 0) {
        if (errno == EINTR) {
            /* Interrupted by signal; continue */
            continue;
        }
        fprintf(stderr, "Error reading %s: %s\n", filename, strerror(errno));
        flock(fd, LOCK_UN);
        close(fd);
        return -1;
    }
    buf[n] = '\0';
    if (n == 0) {
        fprintf(stderr, "Error: %s is empty\n", filename);
        flock(fd, LOCK_UN);
        close(fd);
        return -1;
    }

    if (flock(fd, LOCK_UN) == -1) {
        fprintf(stderr, "Error unlocking %s: %s\n", filename, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
static int read_sensor(struct gpiod_line *line, int gpio_pin)
{
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        fprintf(stderr, "Error reading GPIO %u: %s\n",
                gpio_pin, strerror(errno));
        return -1;
    }
    return val;
}

/* ------------------------------------------------------------------ */
/* Flame detection                                                     */
/* ------------------------------------------------------------------ */
static int detect_flame(struct gpiod_line *line, int gpio_pin)
{
    int val = read_sensor(line, gpio_pin);
    if (val < 0)
        return -1;

    /* KY-026: HIGH = flame detected, LOW = no flame */
    return (val == 0) ? 1 : 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Release all requested lines */
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (g_lines[i]) {
            gpiod_line_release(g_lines[i]);
            g_lines[i] = NULL;
        }
    }

    /* Close the chip */
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }

    /* Close log file */
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_SENSORS];
    int ret = EXIT_FAILURE;

    /* Open the gpiochip (gpiochip4 on RPi 3B+; gpiochip0 on older models) */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire all five lines */
    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting GPIO line %u: %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup_chip;
        }
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n",
                strerror(errno));
        goto cleanup_chip;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error installing SIGTERM handler: %s\n",
                strerror(errno));
        goto cleanup_chip;
    }

    /* Open the log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        goto cleanup_chip;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int val = detect_flame(lines[i], sensor_pins[i]);
            if (val < 0) {
                fprintf(stderr, "Error reading sensor %d\n", i);
                continue;
            }

            if (val == 1) {
                log_event(sensor_pins[i], sensor_pins[i]);
                printf("Sensor %d: Flame detected!\n", sensor_pins[i]);
            }
        }

        /* Sleep for POLL_INTERVAL_SEC seconds, checking for signals */
        for (int i = 0; i < POLL_INTERVAL_SEC && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup_chip:
    cleanup();
    return ret;
}

