/*
 * TTP226 8-channel capacitive touch sensor reader for Raspberry Pi 3 Model B+
 * Uses the gpiochip4 GPIO controller on the Pi 3B+.
 *
 * Wiring:
 *   TTP226 OUT0 -> BCM GPIO 5
 *   TTP226 OUT1 -> BCM GPIO 6
 *   TTP226 OUT2 -> BCM GPIO 13
 *   TTP226 OUT3 -> BCM GPIO 19
 *   TTP226 OUT4 -> BCM GPIO 26
 *   TTP226 OUT5 -> BCM GPIO 12
 *   TTP226 OUT6 -> BCM GPIO 16
 *   TTP226 OUT7 -> BCM GPIO 20
 *
 * Build: gcc -Wall -Wextra -o touch_sensor touch_sensor.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 50

static const unsigned int gpio_pins[NUM_CHANNELS] = {5, 6, 13, 19, 26, 12, 16, 20};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    program_running = 0;
}

static void log_touch_event(int channel, int value)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    printf("[%s] Channel %d: BCM GPIO %u - Touch detected (value %d)\n",
           timestamp, channel, gpio_pins[channel], value);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int ret;
    int i;

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the gpiochip4 GPIO controller */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get all the GPIO lines */
    for (i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n",
                    gpio_pins[i], strerror(errno));
            goto cleanup_chip;
        }
    }

    /* Request each line as input */
    for (i = 0; i < NUM_CHANNELS; i++) {
        ret = gpiod_line_request_input(lines[i], "ttp226-touch-sensor");
