#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define LED_PIN 17
#define POLL_INTERVAL_US 50000  /* 50 ms */
#define DEBOUNCE_DELAY_US 100000 /* 100 ms */
#define LOG_FILE "touch_log.txt"

/* TTP226 touch sensor channel configuration */
typedef enum {
    CHANNEL_1,
    CHANNEL_2,
    CHANNEL_3,
    CHANNEL_4,
    CHANNEL_5,
    CHANNEL_6,
    CHANNEL_7,
    CHANNEL_8
} Channel;

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */
static void log_event(int channel)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (t == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (fprintf(g_log_file, "%s – Channel %d Touched\n", timestamp, channel) < 0) {
        fprintf(stderr, "fprintf() to log file failed: %s\n", strerror(errno));
        return;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Turn off LED */
    if (gpioWrite(LED_PIN, 0) < 0) {
        fprintf(stderr, "Warning: failed to turn off LED (gpioWrite failed)\n");
    }

    /* Release pigpio resources */
    gpioTerminate();

    /* Close log file */
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED pin as output */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED pin %d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins as inputs with pull-down resistors */
    for (int i = 2; i <= NUM_CHANNELS; i++) {
        if (gpioSetMode(i, PI_INPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO %d as input\n", i);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(i, PI_PUD_DOWN) < 0) {
            fprintf(stderr, "Failed to set pull-down on GPIO %d\n", i);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");
    printf("LED on GPIO%d, 8-channel TTP226 on GPIO%d.\n", LED_PIN, NUM_CHANNELS);
    printf("Logging to '%s'. Press Ctrl+C to exit.\n", LOG_FILE);

    /* Main polling loop */
    while (g_running) {
        int prev_state = -1;
        int current_state;

        /* Read all channels */
        for (int i = 2; i <= NUM_CHANNELS; i++) {
            current_state = gpioRead(i);
            if (current_state < 0) {
                fprintf(stderr, "gpioRead(%d) failed: %s\n", i, strerror(errno));
                break;
            }
            if (current_state != prev_state) {
                /* Channel has changed */
                if (current_state == 1) {
                    log_event(i);
                }
                prev_state = current_state;
            }
        }

        /* Debounce: wait for next poll interval before re-reading */
        gpioDelay(DEBOUNCE_DELAY_US);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

