/*
 * Greenhouse Smart Sensor Monitor for Raspberry Pi 4 Model B
 *
 * Reads ambient light data from a Texas Instruments OPT3001 sensor
 * on I2C bus 1 (/dev/i2c-1) once per second, waits at least 100 ms
 * after writing the configuration, and formats each measurement as
 * "YYYY-MM-DD HH:MM:SS, <lux_value>" into a file named light_data.txt
 * and prints it to stdout.
 *
 * Build:  gcc -O2 -Wall -Wextra -o greenhouse_monitor greenhouse_monitor.c
 * Run:    ./greenhouse_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define OPT3001_ADDR   0x50
#define CONFIG_REG     0x00
#define MEASURE_REG    0x01
#define CONFIG_VAL     0x01
#define MEASURE_VAL    0x01
#define LOG_FILE       "light_data.txt"
#define SAMPLE_MS      1000
#define WAIT_MS        100

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit value to a 16-bit register in the OPT3001. */
static int opt3001_write_reg16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (val >> 8) & 0xFF;
    buf[2] = val & 0xFF;

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit value from a 16-bit register in the OPT3001. */
static int opt3001_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/*
 * Read a 16-bit value from the OPT3001.
 * The driver library uses little-endian byte order; the sensor
 * provides big-endian data.  Byte-swap the 16-bit result.
 */
static int opt3001_read_reg16_be(int fd, uint16_t *out)
{
    uint8_t buf[2];

    if (write(fd, &MEASURE_REG, 1) != 1) {
        fprintf(stderr, "I2C write (measurement reg) failed: %s\n",
                strerror(errno));
        return -1;
    }

    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read from measurement reg failed: %s\n",
                strerror(errno));
        return -1;
    }

    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/*
 * Format a 16-bit value as a YYYY-MM-DD HH:MM:SS string.
 */
static int format_lux_value(uint16_t lux_value, char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(buf, len, "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    return 0;
}

/*
 * Write a lux value to the log file.
 * Returns 0 on success, -1 on failure.
 */
static int log_lux_value(const char *filename, uint16_t lux_value)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", filename, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%s, %u\n", filename, lux_value) < 0) {
        fprintf(stderr, "fprintf to %s failed: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose(%s) failed: %s\n", filename, strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    int i2c_fd = -1;
    int rc = EXIT_FAILURE;

    /* Install SIGINT handler for graceful shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus. */
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the I2C slave address. */
    if (ioctl(i2c_fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                OPT3001_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Write the configuration register to configure the OPT3001. */
    if (opt3001_write_reg16(i2c_fd, CONFIG_REG, CONFIG_VAL) < 0) {
        goto cleanup;
    }

    /* Write the measurement register to start a measurement. */
    if (opt3001_write_reg16(i2c_fd, MEASURE_REG, MEASURE_VAL) < 0) {
        goto cleanup;
    }

    /* Wait for the measurement to complete. */
    usleep(WAIT_MS * 1000);

    /* Read the measurement register. */
    uint16_t lux_value;
    if (opt3001_read_reg16_be(i2c_fd, &lux_value) < 0) {
        goto cleanup;
    }

    /* Format the value as a string. */
    char formatted_value[32];
    if (format_lux_value(lux_value, formatted_value, sizeof(formatted_value)) < 0) {
        goto cleanup;
    }

    /* Open the log file. */
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    /* Write the lux value to the log file. */
    if (log_lux_value(LOG_FILE, lux_value) < 0) {
        fprintf(stderr, "log_lux_value failed: %s\n", strerror(errno));
    }

    /* Print to stdout. */
    printf("Ambient light: %s, Lux: %s\n", formatted_value, lux_value);

    rc = EXIT_SUCCESS;

cleanup:
    /* Close the I2C bus. */
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    /* Ensure the log file is flushed. */
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }

    return rc;
}

