#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_PIN 4
#define ALERT_PIN 17
#define LOG_FILE "fire_events.log"
#define POLL_INTERVAL_US 500000
#define ALERT_DURATION_US 1000000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_event(FILE *fp, const char *message) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char ts[64];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    if (fprintf(fp, "%s: %s\n", ts, message) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(ALERT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", ALERT_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(ALERT_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise GPIO%d to LOW\n", ALERT_PIN);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "gpioRead failed on GPIO%d: %s\n", gpio_pin, strerror(errno));
        return -1;
    }
    return value;
}

static void set_alert(int gpio_pin, int duration_us) {
    if (gpioWrite(gpio_pin, 1) != 0) {
        fprintf(stderr, "Failed to set GPIO%d HIGH\n", gpio_pin);
        return;
    }
    gpioDelay(duration_us);
    if (gpioWrite(gpio_pin, 0) != 0) {
        fprintf(stderr, "Failed to set GPIO%d LOW\n", gpio_pin);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return 1;
    }

    printf("Monitoring flame sensor on GPIO%d. Press Ctrl+C to exit.\n", SENSOR_PIN);

    while (program_running) {
        int sensor_value = read_sensor(SENSOR_PIN);
        if (sensor_value < 0) {
            fprintf(stderr, "Sensor read error, continuing...\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (sensor_value == 0) {
            printf("Flame detected!\n");
            set_alert(ALERT_PIN, ALERT_DURATION_US);
            if (log_event(fp, "Flame detected!") != 0) {
                fprintf(stderr, "Failed to log event\n");
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (fclose(fp) != 0) {
        fprintf(stderr, "Failed to close log file: %s\n", strerror(errno));
    }
    gpioWrite(ALERT_PIN, 0);
    gpioTerminate();
    return 0;
}

