#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define LOG_FILE "touch_log.txt"
#define DEBOUNCE_MS 50
#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int log_touch_event(const char *timestamp)
{
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s: Touch Detected\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int read_gpio_pin(int gpio_pin)
{
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO pin %d: %s\n", gpio_pin, strerror(errno));
        return -1;
    }
    return value;
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGTERM handler: %s\n", strerror(errno));
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pin as input with pull-down bias */
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: failed to set pull-down on GPIO %d.\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started on GPIO %d. Press Ctrl+C to exit.\n", GPIO_PIN);

    /* Main polling loop */
    while (running) {
        int touch_state = read_gpio_pin(GPIO_PIN);
        if (touch_state < 0) {
            /* Error already reported; skip this cycle */
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* Detect press (rising edge) */
        if (touch_state == 1) {
            if (log_touch_event("Touch Detected") != 0) {
                fprintf(stderr, "Warning: failed to log touch event.\n");
            }
        }

        /* Detect release (falling edge) */
        if (touch_state == 0) {
            if (log_touch_event("Touch Released") != 0) {
                fprintf(stderr, "Warning: failed to log touch event.\n");
            }
        }

        gpioDelay(DEBOUNCE_MS * 1000);  /* debounce delay in microseconds */
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    return EXIT_SUCCESS;
}

