/*
 * Raspberry Pi Zero W – Sensirion SLF3S-1300F Liquid Flow Sensor
 * I2C bus 1, GPIO2=SDA, GPIO3=SCL
 *
 * Build:  gcc -O2 -Wall -o slf3s_monitor slf3s_monitor.c
 * Run:    ./slf3s_monitor
 */

#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SLF3S_ADDR     0x27
#define FLOW_CMD       0x01
#define FLOW_READ_MS   2
#define SAMPLE_PERIOD  1
#define CSV_FILE       "cooling_log.csv"

/* CRC-8 polynomial: x^8 + x^5 + x^4 + 1 (Sensirion: 0x31) */
static const uint8_t crc8_poly = 0x31;
static const uint8_t crc8_init = 0x00;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_csv_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion: poly 0x31, init 0x00)                              */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = crc8_init;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ crc8_poly);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write cmd 0x%02X failed: %s\n",
                cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: got %zd of %zu bytes: %s\n",
                n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int slf3s_init(int fd)
{
    if (i2c_write_cmd(fd, FLOW_CMD) < 0)
        return -1;

    usleep(FLOW_READ_MS * 1000);

    uint8_t buf[3];
    if (i2c_read_bytes(fd, buf, sizeof(buf)) < 0)
        return -1;

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on initial read\n");
        return -1;
    }

    uint16_t flow_raw = ((uint16_t)buf[0] << 8) | buf[1];
    if (flow_raw < 0 || flow_raw > 10000) {
        fprintf(stderr, "Flow out of range: %u (raw 0x%04X)\n",
                flow_raw, flow_raw);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one sample                                                     */
/* ------------------------------------------------------------------ */
static int slf3s_read(int fd, float *flow_out)
{
    if (i2c_write_cmd(fd, FLOW_CMD) < 0)
        return -1;

    usleep(FLOW_READ_MS * 1000);

    uint8_t buf[3];
    if (i2c_read_bytes(fd, buf, sizeof(buf)) < 0)
        return -1;

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on read\n");
        return -1;
    }

    uint16_t flow_raw = ((uint16_t)buf[0] << 8) | buf[1];
    if (flow_raw < 0 || flow_raw > 10000) {
        fprintf(stderr, "Flow out of range: %u (raw 0x%04X)\n",
                flow_raw, flow_raw);
        return -1;
    }

    *flow_out = (float)flow_raw / 10000.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                         */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float flow, int status)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                flow, status,
                (status == 0) ? "VALID" : "INVALID") < 0) {
        fprintf(stderr, "fprintf to CSV failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush CSV failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_csv_fp) {
        fclose(g_csv_fp);
        g_csv_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SLF3S_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SLF3S_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (slf3s_init(g_i2c_fd) < 0) {
        fprintf(stderr, "SLF3S initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_csv_fp = fopen(CSV_FILE, "a");
    if (!g_csv_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", CSV_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(g_csv_fp, "Timestamp,Flow Rate (ml/min),Status\n");
    fflush(g_csv_fp);

    printf("SLF3S monitoring started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float flow;
        int status;

        if (slf3s_read(g_i2c_fd, &flow) < 0) {
            fprintf(stderr, "I2C read error; will retry next cycle\n");
            usleep(SAMPLE_PERIOD * 1000);
            continue;
        }

        status = (flow < 0.0f) ? 1 : 0;

        if (log_data(g_csv_fp, flow, status) < 0) {
            fprintf(stderr, "Logging failed; continuing\n");
        }

        printf("Flow: %.2f ml/min  Status: %s\n", flow,
               (status == 0) ? "VALID" : "INVALID");

        usleep(SAMPLE_PERIOD * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

