#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define GPIO_CHIP_NAME "/dev/gpiochip4"
#define TOUCH_SENSOR_PIN 23
#define LED_PIN 24
#define LOG_FILE "touch_log.txt"
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_touch_event(int led_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error converting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - LED: %s\n", timestamp, led_state ? "ON" : "OFF") < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpio_chip *chip = gpiochip_open(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip '%s': %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpio_line *touch_line = gpio_chip_get_line(chip, TOUCH_SENSOR_PIN);
    if (!touch_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", TOUCH_SENSOR_PIN, strerror(errno));
        gpiochip_close(chip);
        return EXIT_FAILURE;
    }

    struct gpio_line *led_line = gpio_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_PIN, strerror(errno));
        gpio_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpio_line_request_input(touch_line, "touch_sensor") < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input: %s\n", TOUCH_SENSOR_PIN, strerror(errno));
        gpio_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpio_line_request_output(led_line, "led_control", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", LED_PIN, strerror(errno));
        gpio_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Touch-activated lamp simulation started. Press Ctrl+C to exit.\n");

    while (running) {
        int ret = gpio_line_get_value(touch_line);
        if (ret < 0) {
            fprintf(stderr, "Error reading touch sensor: %s\n", strerror(errno));
            break;
        }

        if (ret == 1) {
            int led_state = !(gpio_line_get_value(led_line) == 1);
            if (log_touch_event(led_state) < 0) {
                fprintf(stderr, "Error logging touch event\n");
            }
            if (gpio_line_set_value(led_line, led_state) < 0) {
                fprintf(stderr, "Error setting LED state: %s\n", strerror(errno));
            }
        }

        struct timespec ts = {0, POLL_TIMEOUT_MS * 1000000L};
        int ret = select(0, NULL, NULL, NULL, &ts);
        if (ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error during select: %s\n", strerror(errno));
            break;
        } else if (ret == 0) {
            fprintf(stderr, "Timeout waiting for touch event\n");
            break;
        }
    }

    if (gpio_line_set_value(led_line, 0) < 0) {
        fprintf(stderr, "Error setting LED to off: %s\n", strerror(errno));
    }

    gpio_chip_close(chip);
    printf("Lamp turned off.\n");
    return EXIT_SUCCESS;
}

