/*
 * flame_alert.c — Raspberry Pi 3 Model B+
 *
 * Flame sensor (KY-026) + buzzer safety system.
 *
 * Wiring:
 *   KY-026 DO  -> GPIO17 (BCM, physical pin 11)
 *   Buzzer  -> GPIO18 (BCM, physical pin 12)
 *   Buzzer  -> 3.3 V via ~330 Ω resistor
 *
 * Build:  gcc -Wall -Wextra -O2 -o flame_alert flame_alert.c -lgpiod
 */

#include <errno.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#include <gpiod.h>

#define FLAME_SENSOR_PIN  17
#define BUZZER_PIN        18
#define LOG_FILE          "alert_log.txt"
#define POLL_INTERVAL_US  500000   /* 500 ms */
#define BUZZER_DURATION_S 2       /* 2 s  */
#define SAMPLE_INTERVAL_US 100000 /* 100 ms slices */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void log_event(const char *msg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    } else {
        fprintf(fp, "[unknown time] %s\n", msg);
    }

    if (fclose(fp) != 0)
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Ensure buzzer is off before releasing GPIO lines */
    if (g_running) {
        gpiod_line_set_value(BUZZER_PIN, 0);
    }

    /* Release all lines */
    if (g_running) {
        gpiod_chip_close(g_chip);
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor_line = NULL;
    struct gpiod_line *buzzer_line = NULL;
    int ret = EXIT_FAILURE;

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip ---- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name failed: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

