#define TOUCH_SENSOR_PIN 4
#define LED_PIN 17
#define LOG_FILE "touch_log.txt"
#define DEBOUNCE_MS 200
#define POLL_INTERVAL_US 10000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file not open.\n");
        return -1;
    }
    if (fprintf(log_file, "%s\n", timestamp) < 0) {
        fprintf(stderr, "Error: Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: Failed to flush log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_touch_sensor(void) {
    int level = gpioRead(TOUCH_SENSOR_PIN);
    if (level < 0) {
        fprintf(stderr, "Error: gpioRead failed on pin %d: %s\n", TOUCH_SENSOR_PIN, pigpio_error(level));
        return -1;
    }
    return level;
}

static int debounce_touch(void) {
    int level = read_touch_sensor();
    if (level < 0) {
        return -1;
    }
    if (level == 1) {
        return 1;
    }
    gpioDelay(DEBOUNCE_MS * 1000);
    return 0;
}

