    if (gpioWrite(LED_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite failed on pin %d: %s\n", LED_PIN, pigpio_error(0));
    } else {
        gpioDelay(100000);
        if (gpioWrite(LED_PIN, 0) < 0) {
            fprintf(stderr, "Error: gpioWrite failed on pin %d: %s\n", LED_PIN, pigpio_error(0));
        }
    }
}

