/*
 * TMAG5110A1 Hall-Effect Latch Sensor Monitor
 * Board:  Raspberry Pi 4 Model B
 * Sensors: 3x TMAG5110A1 on GPIO4 (BCM), GPIO17 (BCM), GPIO27 (BCM)
 *
 * Wiring:
 *   Sensor 1 OUT -> GPIO4 (BCM)
 *   Sensor 2 OUT -> GPIO17 (BCM)
 *   Sensor 3 OUT -> GPIO27 (BCM)
 *
 * Behavior:
 *   The TMAG5110A1 latch outputs a south pole when a magnet is present
 *   (logic low) and a north pole when the magnet is removed (logic high).
 *   The library's API call() returns 0 on success and -1 on error.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o magnet_monitor magnet_monitor.c -lpigpio -lrt
 * Run:
 *   sudo ./magnet_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_PIN  4
#define SENSOR2_PIN  17
#define SENSOR3_PIN  27
#define LOG_FILE     "magnet_log.txt"
#define POLL_DELAY_US 100000   /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Log a magnet state change with timestamp                             */
/* ------------------------------------------------------------------ */
static void log_magnet_state(int sensor_id, int magnet_present)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (g_log_file != NULL) {
        fprintf(g_log_file,
                "%s - Sensor %d: magnet_present=%d\n",
                timestamp, sensor_id, magnet_present);
        fflush(g_log_file);
    } else {
        fprintf(stderr, "Log file not open\n");
    }
}

/* ------------------------------------------------------------------ */
/* Read a single TMAG5110A1 latch pin                                  */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int read_sensor(int pin)
{
    int level = gpioRead(pin);
    if (level < 0) {
        fprintf(stderr, "gpioRead failed on pin %d\n", pin);
        return -1;
    }
    return level;
}

/* ------------------------------------------------------------------ */
/* Initialize pigpio and configure sensor pins as inputs with pull-up.   */
/* Returns 0 on success, -1 on failure.                                 */
/* ------------------------------------------------------------------ */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    /* Configure each sensor pin as input with internal pull-up. */
    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for Sensor 1\n");
        return -1;
    }
    if (gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for Sensor 1\n");
        return -1;
    }

    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for Sensor 2\n");
        return -1;
    }
    if (gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for Sensor 2\n");
        return -1;
    }

    if (gpioSetMode(SENSOR3_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for Sensor 3\n");
        return -1;
    }
    if (gpioSetPullUpDown(SENSOR3_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for Sensor 3\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup: close log file and terminate pigpio.                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open log file in append mode. */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio. */
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("TMAG5110A1 magnet monitor started.  Sensors: S1=GPIO%d, S2=GPIO%d, S3=GPIO%d\n",
           SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN);
    printf("Logging to %s. Press Ctrl+C to exit.\n", LOG_FILE);

    /* Main polling loop. */
    while (g_running) {
        int s1 = read_sensor(SENSOR1_PIN);
        int s2 = read_sensor(SENSOR2_PIN);
        int s3 = read_sensor(SENSOR3_PIN);

        if (s1 < 0 || s2 < 0 || s3 < 0) {
            fprintf(stderr, "Sensor read error; continuing.\n");
        } else {
            /*
             * TMAG5110A1 latch outputs a south pole when a magnet is
             * present (logic low) and a north pole when the magnet is
             * removed (logic high).  We log the state change with a
             * timestamp and sensor ID.
             */
            log_magnet_state(1, s1);
            log_magnet_state(2, s2);
            log_magnet_state(3, s3);
        }

        /* Sleep 100 ms, but wake early on signal. */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(POLL_DELAY_US);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

