/*
 * TTP226 8-channel capacitive touch sensor reader with 8-bit binary counter.
 * Board:  Raspberry Pi Zero W
 * Sensor:  TTP226 on BCM pins 5, 6, 7, 8, 9, 10, 11, 12 (OUT1-OUT8)
 * Counter: BCM GPIO 17-24 (bit 0 on 17, bit 7 on 24)
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_counter touch_counter.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define GPIO_CHIP_NAME "gpiochip0"
#define LOG_FILE "touch_log.txt"
#define STABILIZATION_MS 200
#define POLL_INTERVAL_MS 10
#define CONSUMER "touch_counter"

/* BCM pin numbers for the 8 sensor channels */
static const unsigned int sensor_pins[NUM_CHANNELS] = {5, 6, 7, 8, 9, 10, 11, 12};

/* BCM pin numbers for the 8-bit counter output */
static const unsigned int counter_pins[NUM_CHANNELS] = {17, 24};

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Log a touch event to the file and stdout.
 * Returns 0 on success, -1 on error.
 */
static int log_touch(int channel, int counter)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&t, &tm_utc) == NULL) {
        fprintf(stderr, "gmtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, Channel: %d, Counter: %d\n",
                timestamp, channel, counter) < 0) {
        fprintf(stderr, "fprintf() to log failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose() on log file failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/*
 * Drive the 8-bit counter output.
 * Returns 0 on success, -1 on error.
 */
static int drive_counter(struct gpiod_line *counter_lines[NUM_CHANNELS])
{
    int ret = 0;
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpiod_line_set_value(counter_lines[i],
                                (counter_pins[i] & 1) ? 1 : 0) < 0) {
            fprintf(stderr, "Failed to set counter value: %s\n",
                    strerror(errno));
            ret = -1;
            break;
        }
    }
    return ret;
}

/*
 * Initialize the GPIO chip and request the sensor lines.
 * Returns 0 on success, -1 on error.
 */
static int init_gpio(void)
{
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s) failed: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return -1;
    }

    struct gpiod_line *lines[NUM_CHANNELS];
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line(%u) failed: %s\n",
                    sensor_pins[i], strerror(errno));
            gpiod_chip_close(chip);
            return -1;
        }
    }

    /* Request the lines as outputs, initially low (idle). */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpiod_line_request_output(lines[i], CONSUMER, 0) < 0) {
            fprintf(stderr, "gpiod_line_request_output(%u) failed: %s\n",
                    sensor_pins[i], strerror(errno));
            for (int j = 0; j < i; j++)
                gpiod_line_release(lines[j]);
            gpiod_chip_close(chip);
            return -1;
        }
    }

    /* Request the counter lines as outputs, initially low (0). */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpiod_line_request_output(counter_lines[i], CONSUMER, 0) < 0) {
            fprintf(stderr, "gpiod_line_request_output(%u) failed: %s\n",
                    counter_pins[i], strerror(errno));
            for (int j = 0; j < i; j++)
                gpiod_line_release(lines[j]);
            gpiod_chip_close(chip);
            return -1;
        }
    }

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    printf("Touch counter started. Press Ctrl+C to exit.\n");

    while (g_running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(counter_lines[i]);
            if (val < 0) {
                fprintf(stderr, "gpiod_line_get_value(%u) failed: %s\n",
                        counter_pins[i], strerror(errno));
                continue;
            }

            /* Rising edge: idle -> touched */
            if (val == 1) {
                int counter = (val == 1) ? 255 : 0;
                if (drive_counter(counter_lines) < 0) {
                    fprintf(stderr, "Failed to drive counter\n");
                } else {
                    if (log_touch(i, counter) < 0) {
                        fprintf(stderr, "Failed to log touch event\n");
                    }
                }
            }
        }

        /* Sleep for the remainder of the 10-ms poll interval. */
        for (int i = 0; i < POLL_INTERVAL_MS / 10 && g_running; i++)
            usleep(10000);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpiod_line_set_value(counter_lines[i], 0);
        gpiod_line_release(counter_lines[i]);
    }
    gpiod_line_release(lines[0]);
    gpiod_line_release(lines[1]);
    gpiod_line_release(lines[2]);
    gpiod_line_release(lines[3]);
    gpiod_line_release(lines[4]);
    gpiod_line_release(lines[5]);
    gpiod_line_release(lines[6]);
    gpiod_line_release(lines[7]);
    gpiod_line_release(lines[8]);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

