/*
 * Four-Way IR Tracking Module Logger for Raspberry Pi 5
 * Sensors: KY-033 on GPIO17 (BCM), GPIO18 (BCM), GPIO27 (BCM), GPIO22 (BCM)
 * Logs: tracking_log.csv (timestamp,sensor1,sensor2,sensor3,sensor4)
 *
 * Build: gcc -O2 -Wall -o ir_tracker ir_tracker.c -lpigpio -lrt
 * Run:   sudo ./ir_tracker
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define SENSOR3_PIN 27
#define SENSOR4_PIN 22

#define LOG_FILE "tracking_log.csv"
#define POLL_INTERVAL_US 100000   /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single KY-033 sensor.
 * Returns 0 on success (line detected), 1 on no line, -1 on error.
 */
static int read_sensor(int pin)
{
    int level = gpioRead(pin);
    if (level < 0) {
        fprintf(stderr, "Error: gpioRead failed on pin %d (code %d)\n", pin, level);
        return -1;
    }
    return level;
}

/*
 * Append a row to the CSV file.
 * Returns 0 on success, -1 on write failure.
 */
static int append_to_csv(const char *timestamp, int sensor1, int sensor2,
                          int sensor3, int sensor4)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open %s for appending\n", LOG_FILE);
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d,%d\n", timestamp,
                sensor1, sensor2, sensor3, sensor4) < 0) {
        fprintf(stderr, "Error: cannot write to %s\n", LOG_FILE);
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error: fclose failed on %s\n", LOG_FILE);
        return -1;
    }
    return 0;
}

int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins as inputs */
    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for sensor1 pin %d\n",
                SENSOR1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for sensor2 pin %d\n",
                SENSOR2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR3_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for sensor3 pin %d\n",
                SENSOR3_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR4_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for sensor4 pin %d\n",
                SENSOR4_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure all sensors are initially inactive */
    if (gpioWrite(SENSOR1_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite failed for sensor1 pin %d\n",
                SENSOR1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(SENSOR2_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite failed for sensor2 pin %d\n",
                SENSOR2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(SENSOR3_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite failed for sensor3 pin %d\n",
                SENSOR3_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(SENSOR4_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite failed for sensor4 pin %d\n",
                SENSOR4_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("IR tracking system started. Logging to %s\n", LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        int s1 = read_sensor(SENSOR1_PIN);
        int s2 = read_sensor(SENSOR2_PIN);
        int s3 = read_sensor(SENSOR3_PIN);
        int s4 = read_sensor(SENSOR4_PIN);

        if (s1 < 0 || s2 < 0 || s3 < 0 || s4 < 0) {
            /* Error already printed; continue */
        } else {
            if (s1 == 1 || s2 == 1 || s3 == 1 || s4 == 1) {
                printf("Sensor %d: line detected\n", SENSOR1_PIN);
            } else {
                printf("Sensor %d: no line\n", SENSOR1_PIN);
            }
            if (append_to_csv(time(NULL), s1, s2, s3, s4) != 0) {
                fprintf(stderr, "Warning: failed to append to CSV\n");
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    gpioWrite(SENSOR1_PIN, 0);
    gpioWrite(SENSOR2_PIN, 0);
    gpioWrite(SENSOR3_PIN, 0);
    gpioWrite(SENSOR4_PIN, 0);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

