#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define LOG_FILE "/var/log/tilt_events.log"
#define POLL_INTERVAL_US 100000  /* 100 ms */
#define DEBOUNCE_US 50000        /* 50 ms */

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Log a tilt event                                                    */
/* ------------------------------------------------------------------ */
static void log_tilt_event(int sensor_pin)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(log_file, "%s, Sensor %d tilted\n", timestamp, sensor_pin) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
    } else {
        fflush(log_file);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    /* Release pigpio resources */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int ret;

    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "gpioInitialise failed: %s\n", strerror(ret));
        return EXIT_FAILURE;
    }

    /* --- Configure sensor pins as inputs with pull-up --- */
    ret = gpioSetMode(SENSOR1_PIN, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "gpioSetMode(SENSOR1_PIN) failed: %s\n", strerror(ret));
        cleanup();
        return EXIT_FAILURE;
    }
    ret = gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_UP);
    if (ret != 0) {
        fprintf(stderr, "gpioSetPullUpDown(SENSOR1_PIN) failed: %s\n", strerror(ret));
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpioSetMode(SENSOR2_PIN, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "gpioSetMode(SENSOR2_PIN) failed: %s\n", strerror(ret));
        cleanup();
        return EXIT_FAILURE;
    }
    ret = gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_UP);
    if (ret != 0) {
        fprintf(stderr, "gpioSetPullUpDown(SENSOR2_PIN) failed: %s\n", strerror(ret));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Tilt sensor monitoring started. Press Ctrl+C to exit.\n");
    printf("Sensor 1: GPIO%d, Sensor 2: GPIO%d\n", SENSOR1_PIN, SENSOR2_PIN);
    printf("Logging to %s\n", LOG_FILE);

    /* --- Main polling loop --- */
    while (program_running) {
        int s1 = gpioRead(SENSOR1_PIN);
        int s2 = gpioRead(SENSOR2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "gpioRead failed: %s\n", strerror(errno));
            /* Continue; read errors are transient and do not require immediate exit */
        } else {
            /* Sensor 1: active-low pull-up; Sensor 2: active-low pull-up */
            if (s1 == 1 && s2 == 0) {
                log_tilt_event(SENSOR1_PIN);
                log_tilt_event(SENSOR2_PIN);
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

