#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN 17
#define CENTER_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22

#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input.\n", LEFT_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input.\n", CENTER_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input.\n", RIGHT_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: Failed to set pull-up on GPIO %d.\n", LEFT_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(CENTER_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: Failed to set pull-up on GPIO %d.\n", CENTER_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: Failed to set pull-up on GPIO %d.\n", RIGHT_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_sensor(int pin) {
    int level = gpioRead(pin);
    if (level < 0) {
        fprintf(stderr, "Error: Failed to read GPIO %d.\n", pin);
        return -1;
    }
    return level;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("SunFounder 3-Way Tracing Sensor Reader\n");
    printf("Left: GPIO%d, Center: GPIO%d, Right: GPIO%d\n", LEFT_SENSOR_PIN, CENTER_SENSOR_PIN, RIGHT_SENSOR_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (program_running) {
        int left = read_sensor(LEFT_SENSOR_PIN);
        int center = read_sensor(CENTER_SENSOR_PIN);
        int right = read_sensor(RIGHT_SENSOR_PIN);

        if (left < 0 || center < 0 || right < 0) {
            fprintf(stderr, "Error: Failed to read sensor data.\n");
            break;
        }

        printf("Left: %d, Center: %d, Right: %d\n", left, center, right);
        fflush(stdout);

        gpioDelay(POLL_INTERVAL_US);
    }

    gpioTerminate();
    printf("\nProgram terminated cleanly.\n");
    return EXIT_SUCCESS;
}

