/*
 * Three-Way IR Reflectance Sensor Poller for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   Keywish left  -> GPIO2 (BCM)
 *   Keywish middle -> GPIO3 (BCM)
 *   Keywish right  -> GPIO4 (BCM)
 *
 * Each sensor line is polled individually using the gpiochip0
 * GPIO API.  The program reads each line, checks the result of
 * the open/get/request/read call, and logs the sensor values
 * to stdout in the format "L:<0|1> M:<0|1> R:<0|1>".
 *
 * Build:  gcc -O2 -Wall -Wextra -o ir_poller ir_poller.c
 * Run:    sudo ./ir_poller   (or run as root)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define GPIO_CHIP_NAME   "gpiochip0"
#define LEFT_PIN          2
#define MIDDLE_PIN       3
#define RIGHT_PIN        4
#define POLL_INTERVAL_US 100000   /* 100 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int install_sigint_handler(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int open_gpio_device(void)
{
    int fd = open(GPIO_CHIP_NAME, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", GPIO_CHIP_NAME, strerror(errno));
        return -1;
    }

    if (ioctl(fd, GPIO_IOCTL_GET_LINE_COUNT, &fd) < 0) {
        fprintf(stderr, "ioctl(GET_LINE_COUNT): %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    for (int i = 0; i < fd; i++) {
        struct gpio_line *line = gpio_get_line(i);
        if (!line) {
            fprintf(stderr, "gpio_get_line(%d): %s\n", i, strerror(errno));
            close(fd);
            return -1;
        }
        if (gpio_set_direction(line, GPIO_DIRECTION_IN) < 0) {
            fprintf(stderr, "gpio_set_direction(IN): %s\n", strerror(errno));
            close(fd);
            return -1;
        }
    }

    return fd;
}

/* ------------------------------------------------------------------ */
static int request_line(int fd, int line_number)
{
    if (ioctl(fd, GPIO_IOCTL_REQUEST_LINE, &line_number) < 0) {
        fprintf(stderr, "GPIO_IOCTL_REQUEST_LINE(%d): %s\n",
                line_number, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_line(int fd, int line_number)
{
    int val = gpio_get_value(line_number);
    if (val < 0) {
        fprintf(stderr, "gpio_get_value(%d): %s\n", line_number, strerror(errno));
        return -1;
    }
    return val;
}

/* ------------------------------------------------------------------ */
static int log_sensor_values(int left, int middle, int right)
{
    printf("L:");
    if (left) printf("1");
    else printf("0");
    printf(", M:");
    if (middle) printf("1");
    else printf("0");
    printf(", R:");
    if (right) printf("1");
    else printf("0");
    printf("\n");
    fflush(stdout);
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_sigint_handler() != 0) {
        return EXIT_FAILURE;
    }

    int fd = open_gpio_device();
    if (fd < 0) {
        return EXIT_FAILURE;
    }

    /* Request each line in order so we can detect any request
     * failure early and exit cleanly. */
    for (int i = 0; i < fd; i++) {
        if (request_line(fd, LEFT_PIN) < 0) {
            close(fd);
            return EXIT_FAILURE;
        }
        if (request_line(fd, MIDDLE_PIN) < 0) {
            close(fd);
            return EXIT_FAILURE;
        }
        if (request_line(fd, RIGHT_PIN) < 0) {
            close(fd);
            return EXIT_FAILURE;
        }
    }

    /* Allow any remaining lines to be released by the kernel. */
    usleep(POLL_INTERVAL_US);

    while (g_running) {
        int left = read_line(fd, LEFT_PIN);
        int middle = read_line(fd, MIDDLE_PIN);
        int right = read_line(fd, RIGHT_PIN);

        if (left < 0 || middle < 0 || right < 0) {
            fprintf(stderr, "Error reading sensor lines.\n");
            break;
        }

        if (log_sensor_values(left, middle, right) != 0) {
            fprintf(stderr, "Error logging sensor values.\n");
            break;
        }

        usleep(POLL_INTERVAL_US);
    }

    /* Clean up resources on every exit path. */
    close(fd);
    return EXIT_SUCCESS;
}

