#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <time.h>
#include <math.h>
#include <pigpio.h>

#define RED_PIN      17
#define GREEN_PIN    18
#define BLUE_PIN     27

#define PWM_FREQ     1000
#define PWM_RANGE    255
#define PWM_INTERVAL 5
#define STEPS        50
#define HUE_MIN      0.0f
#define HUE_MAX      1.0f
#define HUE_RANGE    1.0f

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (gpioInitialise() >= 0) {
        gpioPWM(RED_PIN, 0);
        gpioPWM(GREEN_PIN, 0);
        gpioPWM(BLUE_PIN, 0);
        gpioTerminate();
    }
    syslog(LOG_INFO, "Cleanup complete: LED off, resources released.");
}

static void generate_hue(float *hue)
{
    time_t rawtime;
    struct tm timeinfo;
    char buf[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &timeinfo);

    *hue = (float)rand() / (float)RAND_MAX * HUE_RANGE;
}

static void fade_rgb(float *r, float *g, float *b, float t)
{
    float h = HUE_MIN + (HUE_MAX - HUE_MIN) * t;
    generate_hue(&h);

    float hf = h * HUE_RANGE;
    float hf_r = hf * r[0];
    float hf_g = hf * g[0];
    float hf_b = hf * b[0];

    *r = (1.0f - hf_r) * r[0] + hf_r * r[1];
    *g = (1.0f - hf_g) * g[0] + hf_g * g[1];
    *b = (1.0f - hf_b) * b[0] + hf_b * b[1];
}

int main(void)
{
    openlog("rgb_fade", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "gpioInitialise failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode failed: %s", strerror(errno));
        cleanup();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(BLUE_PIN, PWM_FREQ) != 0) {
        syslog(LOG_ERR, "gpioSetPWMfrequency failed: %s", strerror(errno));
        cleanup();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(BLUE_PIN, PWM_RANGE) != 0) {
        syslog(LOG_ERR, "gpioSetPWMrange failed: %s", strerror(errno));
        cleanup();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Starting RGB fade loop (PWM %d Hz, %d steps, %d s)",
           PWM_FREQ, STEPS, PWM_INTERVAL);

    while (g_running) {
        float r, g, b;
        float t = (float)STEPS / PWM_INTERVAL;

        fade_rgb(&r, &g, &b, t);

        syslog(LOG_INFO, "Hue: %.2f, RGB: R=%d G=%d B=%d",
               HUE_MIN + (HUE_MAX - HUE_MIN) * t, r, g, b);

        gpioPWM(RED_PIN, (int)r);
        gpioPWM(GREEN_PIN, (int)g);
        gpioPWM(BLUE_PIN, (int)b);

        usleep(PWM_INTERVAL * 1000);
    }

    cleanup();
    syslog(LOG_INFO, "Shutdown complete.");
    closelog();
    return EXIT_SUCCESS;
}

