/*
 * TCS34725 color sensor reader for Raspberry Pi 4 Model B
 * Uses pigpio for I2C and GPIO control.
 *
 * Wiring:
 *   TCS34725 SDA -> GPIO2 (I2C bus 1 SDA)
 *   TCS34725 SCL -> GPIO3 (I2C bus 1 SCL)
 *   TCS34725 VDD -> 3.3 V
 *   TCS34725 GND -> GND
 *   LED anode -> GPIO17 (BCM) via 330 ohm resistor
 *
 * Build: gcc -Wall -o tcs34725 tcs34725.c -lpigpio -lrt
 * Run:   sudo ./tcs34725
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x00
#define LED_GPIO       17
#define RED_THRESHOLD  200
#define POLL_DELAY_US  200000   /* 200 ms */
#define INTEGRATION_MS 154

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a 16-bit big-endian value from the TCS34725.
 * Returns 0 on success, -1 on error.
 */
static int tcs34725_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];
    if (i2cWriteByte(handle, reg) < 0) {
        fprintf(stderr, "i2cWriteByte(reg=0x%02X) failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "i2cReadDevice failed\n");
        return -1;
    }
    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/*
 * Read the calibrated red, green, blue, and clear values.
 * Returns 0 on success, -1 on error.
 */
static int tcs34725_read_cube(int handle, uint16_t *red, uint16_t *green,
                              uint16_t *blue, uint16_t *clear)
{
    if (tcs34725_read_reg16(handle, 0x01, red) < 0)
        return -1;
    if (tcs34725_read_reg16(handle, 0x02, green) < 0)
        return -1;
    if (tcs34725_read_reg16(handle, 0x03, blue) < 0)
        return -1;
    if (tcs34725_read_reg16(handle, 0x04, clear) < 0)
        return -1;
    return 0;
}

static void control_led(int gpio, uint16_t red)
{
    if (red > RED_THRESHOLD)
        gpioWrite(gpio, 1);
    else
        gpioWrite(gpio, 0);
}

int main(void)
{
    int handle = -1;
    int ret = EXIT_FAILURE;

    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus 1 at address 0x00 --- */
    handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, handle);
        goto cleanup;
    }

    /* --- Configure LED GPIO as output, initially LOW --- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", LED_GPIO);
        goto cleanup;
    }
    if (gpioWrite(LED_GPIO, 0) != 0) {
        fprintf(stderr, "gpioWrite(%d, 0) failed\n", LED_GPIO);
        goto cleanup;
    }

    /* --- Power on sensor (PON) and enable RGBC (AEN) --- */
    if (i2cWriteByte(handle, 0x01) < 0) {
        fprintf(stderr, "TCS34725 power-on failed\n");
        goto cleanup;
    }
    if (i2cWriteByte(handle, 0x00) < 0) {
        fprintf(stderr, "TCS34725 AEN enable failed\n");
        goto cleanup;
    }

    /* --- Configure integration time --- */
    if (tcs34725_read_reg16(handle, 0x05, NULL) < 0) {
        fprintf(stderr, "Failed to read integration time register\n");
        goto cleanup;
    }
    uint16_t int_ms = INTEGRATION_MS;
    if (int_ms > 0xFFFF)
        int_ms = 0xFFFF;
    if (i2cWriteByte(handle, (uint8_t)(int_ms & 0xFF)) < 0) {
        fprintf(stderr, "Failed to write integration time register\n");
        goto cleanup;
    }

    printf("TCS34725 initialized.  Reading every %d ms.  Press Ctrl+C to exit.\n",
           POLL_DELAY_US / 1000);

    /* --- Main polling loop --- */
    while (g_running) {
        uint16_t red, green, blue, clear;
        if (tcs34725_read_cube(handle, &red, &green, &blue, &clear) < 0) {
            fprintf(stderr, "Sensor read failed; re-initializing...\n");
            if (i2cClose(handle) < 0) {
                fprintf(stderr, "i2cClose failed; continuing anyway\n");
            }
            handle = -1;
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        printf("Red: %u, Green: %u, Blue: %u, Clear: %u\n",
               red, green, blue, clear);

        control_led(LED_GPIO, red);

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (handle >= 0)
        i2cClose(handle);
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    return ret;
}

