/*
 * BH1750 Ambient Light Sensor to WS2812B LED Strip
 * Board:  Raspberry Pi 4 Model B
 * Sensor: BH1750 digital light sensor (I2C address 0x23)
 * Strip:  WS2812B 10-LED strip on GPIO18 (BCM)
 *
 * Build:  gcc -O2 -Wall -o bh1750_ws2812 bh1750_ws2812.c -lpigpio -lrt
 * Run:    sudo ./bh1750_ws2812
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BH1750_ADDR          0x23
#define BH1750_CMD_READ_LUX  0x01
#define BH1750_CMD_RESET     0x04
#define BH1750_CMD_PWR_DOWN 0x80

#define WS2812B_GPIO          18
#define WS2812B_PWM_FREQ      1000000  /* 1 MHz */
#define WS2812B_PWM_RANGE     256
#define WS2812B_PWM_PERIOD    (1000000 / WS2812B_PWM_FREQ)
#define WS2812B_PWM_ON_US     (1000000 / (WS2812B_PWM_FREQ * WS2812B_PWM_RANGE))
#define WS2812B_PWM_OFF_US    (1000000 / (WS2812B_PWM_FREQ * WS2812B_PWM_RANGE))

#define LUX_THRESHOLD        1000.0f
#define SAMPLE_DELAY_US      180000   /* 180 ms */
#define MAX_RETRIES          3

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single lux value from the BH1750.
 * Returns 0 on success, -1 on I2C error.
 */
static int read_bh1750(int handle, float *lux_out)
{
    uint8_t cmd = BH1750_CMD_READ_LUX;
    uint8_t data[2];

    /* Issue the read command */
    if (i2cWriteDevice(handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "Error: BH1750 write command failed (handle %d)\n", handle);
        return -1;
    }

    /* Wait for the sensor to complete the conversion */
    gpioDelay(SAMPLE_DELAY_US);

    /* Read 2 bytes of data */
    if (i2cReadDevice(handle, (char *)data, 2) != 2) {
        fprintf(stderr, "Error: BH1750 read failed (handle %d)\n", handle);
        return -1;
    }

    /* Combine the two bytes into a 16-bit lux value */
    uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
    *lux_out = (float)raw / 65535.0f;
    return 0;
}

/*
 * Generate the WS2812B timing for a single LED.
 * Returns 0 on success, -1 on I2C error.
 */
static int generate_ws2812_timing(int gpio, int period_us, int on_us, int off_us)
{
    /*
     * WS2812B timing:
     *   Pulse width = (period_us / 2) * (1 - duty_cycle)
     *   Duty cycle = (on_us / period_us) * (1 - (off_us / period_us))
     *   duty_cycle = 1 - duty_cycle
     *
     * The WS2812B library uses hardware PWM/wave capability, so we
     * generate the pulse width directly in microseconds.
     */
    int duty_cycle = (on_us / period_us) * (1.0f - (off_us / period_us));
    int pulse_width = (period_us / 2) * (1.0f - duty_cycle);

    if (gpioSetPWMfrequency(gpio, period_us) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed (period=%d)\n", period_us);
        return -1;
    }
    if (gpioSetPWMrange(gpio, WS2812B_PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed\n");
        return -1;
    }
    if (gpioPWM(gpio, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioPWM failed\n");
        return -1;
    }
    return 0;
}

/*
 * Generate the WS2812B data line for a single LED.
 * Returns 0 on success, -1 on I2C error.
 */
static int generate_ws2812_data(int gpio, int led_index, int *data_out)
{
    int data_len = WS2812B_PWM_PERIOD / WS2812B_PWM_RANGE;
    int *data = malloc(data_len * sizeof(int));
    if (!data) {
        fprintf(stderr, "Error: malloc failed\n");
        return -1;
    }

    /*
     * WS2812B data line:
     *   LEDs are driven in sequence, with each LED having a single
     *   pulse of the required period.
     *   The data line is a stream of 1-bit pulses, with the
     *   LEDs being driven in order.
     */
    for (int i = 0; i < data_len; i++) {
        int pulse_us = (led_index * WS2812B_PWM_RANGE) / data_len;
        if (gpioSetPWMfrequency(gpio, WS2812B_PWM_FREQ) < 0) {
            fprintf(stderr, "Error: gpioSetPWMfrequency failed (led %d)\n", led_index);
            free(data);
            return -1;
        }
        if (gpioPWM(gpio, pulse_us) < 0) {
            fprintf(stderr, "Error: gpioPWM failed (led %d)\n", led_index);
            free(data);
            return -1;
        }
        data[i] = 1;
    }

    *data_out = data;
    return 0;
}

int main(void)
{
    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO18 as output and set it to LOW */
    if (gpioSetMode(WS2812B_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO%d\n", WS2812B_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(WS2812B_GPIO, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite failed for GPIO%d\n", WS2812B_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    int i2c_handle = i2cOpen(1, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    float lux_value = 0.0f;
    int retries = 0;

    while (g_running) {
        if (read_bh1750(i2c_handle, &lux_value) == 0) {
            int led_index = (int)((lux_value / LUX_THRESHOLD) * WS2812B_PWM_RANGE);
            if (generate_ws2812_data(WS2812B_GPIO, led_index, &data_out) == 0) {
                printf("Lux: %.2f\n", lux_value);
                for (int i = 0; i < data_len; i++) {
                    gpioPWM(WS2812B_GPIO, data_out[i]);
                }
                gpioDelay(SAMPLE_DELAY_US);
            } else {
                fprintf(stderr, "Warning: Failed to generate WS2812B data\n");
            }
        } else {
            fprintf(stderr, "Warning: BH1750 read failed (attempt %d/%d)\n", retries + 1, MAX_RETRIES);
            retries++;
            if (retries >= MAX_RETRIES) {
                fprintf(stderr, "Error: BH1750 read failed after %d retries\n", MAX_RETRIES);
                break;
            }
            gpioDelay(SAMPLE_DELAY_US);
        }
        gpioDelay(SAMPLE_DELAY_US);
    }

    /* Cleanup */
    gpioPWM(WS2812B_GPIO, 0);
    gpioWrite(WS2812B_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();

