/*
 * BH1750 ambient light sensor reader for Raspberry Pi 3 Model B+
 *
 * Hardware:
 *   - 3 BH1750 I2C sensors on I2C bus 1 (addresses 0x01, 0x02, 0x03)
 *   - APA102 RGB LED strip on GPIO10 (BCM) and GPIO11 (BCM)
 *   - Hardware SPI: MOSI=GPIO10, SCLK=GPIO11, CS=GPIO8 (CE0)
 *
 * Build:  gcc -O2 -Wall -o bh1750_apd bh1750_apd.c -lm
 * Run:    sudo ./bh1750_apd
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define I2C_BUS        1
#define BH1750_ADDR_1  0x01
#define BH1750_ADDR_2  0x02
#define BH1750_ADDR_3  0x03

#define APA102_DATA_PIN  10
#define APA102_CLK_PIN   11
#define APA102_CS_PIN    8

#define NUM_SENSORS      3
#define SPI_DEVICE       "/dev/spidev0.0"
#define SPI_SPEED_HZ     1000000
#define SPI_BITS_PER_WORD 8
#define SPI_DELAY_US     10000
#define SPI_MODE         0

#define NUM_FADES        5
#define FADE_DELAY_US    500000
#define FADE_DELAY_MS    (FADE_DELAY_US / 1000)
#define FADE_MAX_US      (FADE_DELAY_US * NUM_FADES)

#define SAMPLE_DELAY_US  100000
#define SAMPLE_DELAY_MS  (SAMPLE_DELAY_US / 1000)

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int i2c_read_byte(int fd, uint8_t reg)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_byte(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "i2c_read_byte(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return val;
}

static int i2c_read_word(int fd, uint8_t reg)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_word(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_read_word(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */

static int spi_open(const char *device, uint32_t speed_hz, uint8_t bits,
                    uint32_t delay_us)
{
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", device, strerror(errno));
        return -1;
    }
    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    uint8_t bits_per_word = bits;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_per_word) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    uint32_t speed = speed_hz;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    uint32_t delay = delay_us;
    if (ioctl(fd, SPI_IOC_WR_DELAY_US, &delay) < 0) {
        fprintf(stderr, "SPI_IOC_WR_DELAY_US: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int spi_write(int fd, const uint8_t *buf, size_t len)
{
    size_t total = 0;
    while (total < len) {
        ssize_t n = write(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "SPI write: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "SPI write: unexpected EOF\n");
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor helpers                                                      */
/* ------------------------------------------------------------------ */

static int read_bh1750(int fd, uint8_t addr, uint8_t *data)
{
    if (i2c_write(fd, addr) < 0)
        return -1;
    if (i2c_read_byte(fd, 0x00) < 0)
        return -1;
    if (i2c_read_byte(fd, 0x01) < 0)
        return -1;
    if (i2c_read_byte(fd, 0x02) < 0)
        return -1;
    if (i2c_read_byte(fd, 0x03) < 0)
        return -1;
    *data = (uint8_t)data[0] | ((uint8_t)data[1] << 8);
    return 0;
}

static int read_sensor(int fd, uint8_t addr, uint8_t *data)
{
    if (read_bh1750(fd, addr, data) < 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Fade helpers                                                        */
/* ------------------------------------------------------------------ */

static void fade_set(int fade_index, float target_brightness)
{
    if (fade_index < 0 || fade_index >= NUM_FADES)
        return;

    float frac = (float)fade_index / NUM_FADES;
    float frac_max = 1.0f - frac;
    float frac_min = frac_max;

    float r = frac_max * target_brightness;
    float g = frac_min * target_brightness;
    float b = frac_max * target_brightness;

    float r_new = r + frac * (target_brightness - r);
    float g_new = g + frac * (target_brightness - g);
    float b_new = b + frac * (target_brightness - b);

    if (r_new < 0.0f) r_new = 0.0f;
    if (r_new > 255.0f) r_new = 255.0f;
    if (g_new < 0.0f) g_new = 0.0f;
    if (g_new > 255.0f) g_new = 255.0f;
    if (b_new < 0.0f) b_new = 0.0f;
    if (b_new > 255.0f) b_new = 255.0f;

    gpioWrite(APA102_DATA_PIN, (int)r_new);
    gpioWrite(APA102_CLK_PIN, (int)g_new);
    gpioWrite(APA102_CS_PIN, (int)b_new);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --- */
    int i2c_fd = i2c_open(SPI_DEVICE, BH1750_ADDR_1);
    if (i2c_fd < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    i2c_fd = i2c_open(SPI_DEVICE, BH1750_ADDR_2);
    if (i2c_fd < 0) {
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    i2c_fd = i2c_open(SPI_DEVICE, BH1750_ADDR_3);
    if (i2c_fd < 0) {
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- APA102 init --- */
    gpioSetMode(APA102_DATA_PIN, PI_OUTPUT);
    gpioSetMode(APA102_CLK_PIN, PI_OUTPUT);
    gpioSetMode(APA102_CS_PIN, PI_OUTPUT);

    gpioWrite(APA102_DATA_PIN, 0);
    gpioWrite(APA102_CLK_PIN, 0);
    gpioWrite(APA102_CS_PIN, 0);

    /* --- SPI open --- */
    int spi_fd = spi_open(SPI_DEVICE, SPI_SPEED_HZ, SPI_BITS_PER_WORD,
                         SPI_DELAY_US);
    if (spi_fd < 0) {
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("BH1750 ambient light reader started. Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        uint8_t data[3];
        if (read_sensor(i2c_fd, BH1750_ADDR_1, data) < 0) {
            fprintf(stderr, "Sensor read failed; skipping cycle.\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }
        uint8_t raw[3];
        if (read_bh1750(i2c_fd, BH1750_ADDR_1, raw) < 0) {
            fprintf(stderr, "BH1750 read failed; skipping cycle.\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }
        if (read_bh1750(i2c_fd, BH1750_ADDR_2, raw) < 0) {
            fprintf(stderr, "BH1750 read failed; skipping cycle.\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }
        if (read_bh1750(i2c_fd, BH1750_ADDR_3, raw) < 0) {
            fprintf(stderr, "BH1750 read failed; skipping cycle.\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        uint8_t b1 = raw[0];
        uint8_t b2 = raw[1];
        uint8_t b3 = raw[2];

        float r = (float)b1 / 255.0f;
        float g = (float)b2 / 255.0f;
        float b = (float)b3 / 255.0f;

        float target = r + (g - r) * 0.5f + (b - r) * 0.5f;
        float brightness = (float)target * 255.0f;

        fade_set(0, brightness);
        gpioDelay(FADE_DELAY_US);

        uint8_t data_b = (uint8_t)(r + (g - r) * 0.5f + (b - r) * 0.5f);
        fade_set(1, data_b);
        gpioDelay(FADE_DELAY_US);

        uint8_t data_g = (uint8_t)(g + (b - r) * 0.5f);
        fade_set(2, data_g);
        gpioDelay(FADE_DELAY_US);

        uint8_t data_r = (uint8_t)(r + (g - r) * 0.5f + (b - r) * 0.5f);
        fade_set(3, data_r);
        gpioDelay(FADE_DELAY_US);
    }

    /* --- Cleanup --- */
    gpioWrite(APA102_DATA_PIN, 0);
    gpioWrite(APA102_CLK_PIN, 0);
    gpioWrite(APA102_CS_PIN, 0);
    close(i2c_fd);
    close(spi_fd);
    gpioTerminate();
    printf("\nExiting cleanly.\n");

