/*
 * KY-026 flame sensor self-test on Raspberry Pi 5.
 *
 * Wiring:
 *   KY-026 VCC  -> 3.3 V (pin 1)
 *   KY-026 GND  -> GND  (pin 6)
 *   KY-026 DO   -> BCM GPIO4 (pin 7)
 *   Buzzer      -> BCM GPIO17 (pin 11)
 *   LED         -> BCM GPIO18 (pin 12)
 *
 * Behavior:
 *   - LED blinks 500 ms on/500 ms off twice while flame sensor is read.
 *   - If any of the five readings is LOW (flame detected), the buzzer
 *     and LED are turned on continuously until a subsequent HIGH
 *     reading is received.
 *   - On normal termination or SIGINT, the LED is turned off and
 *     all lines are released.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN  4
#define BUZZER_PIN        17
#define LED_PIN           18

#define FLAME_SENSOR_READS 5
#define READ_INTERVAL_US  100000   /* 100 ms */
#define BLINK_DURATION_MS 500
#define BLINK_REPEAT_COUNT 5
#define ERROR_THRESHOLD_MS 1000
#define POLL_INTERVAL_US  50000   /* 50 ms */

static volatile sig_atomic_t g_terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

/*
 * Read the KY-026 flame sensor.
 * Returns 0 (HIGH) or 1 (LOW) on success, -1 on error.
 */
static int read_flame_sensor(void)
{
    int level = gpioRead(FLAME_SENSOR_PIN);
    if (level < 0) {
        fprintf(stderr, "Error: gpioRead failed on pin %d: %s\n",
                FLAME_SENSOR_PIN, strerror(errno));
        return -1;
    }
    return level;
}

/*
 * Blink the LED once and log the timestamp.
 */
static void blink_led(void)
{
    gpioWrite(LED_PIN, 1);
    gpioDelay(BLINK_DURATION_MS * 1000);
    gpioWrite(LED_PIN, 0);
    gpioDelay(BLINK_DURATION_MS * 1000);
}

/*
 * Log a timestamped event with severity.
 */
static void log_event(const char *message, int severity)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(stderr, "[%s] %s (severity %d)\n", ts, message, severity);
}

/*
 * Perform a self-test: read the flame sensor five times and log the
 * readings. If any LOW is observed, sound the buzzer and blink the LED.
 */
static void self_test(void)
{
    for (int i = 0; i < FLAME_SENSOR_READS; i++) {
        int level = read_flame_sensor();
        if (level < 0) {
            log_event("Error: failed to read flame sensor", 1);
            gpioDelay(READ_INTERVAL_US);
            continue;
        }

        log_event("Flame sensor read: %d", level);

        if (level == 0) {
            log_event("Flame detected (all readings LOW)", 1);
            blink_led();
            gpioDelay(ERROR_THRESHOLD_MS * 1000);
            gpioWrite(LED_PIN, 0);
            gpioWrite(BUZZER_PIN, 0);
            gpioDelay(ERROR_THRESHOLD_MS * 1000);
            gpioWrite(LED_PIN, 0);
            gpioWrite(BUZZER_PIN, 0);
            gpioDelay(ERROR_THRESHOLD_MS * 1000);
        }
    }
}

/*
 * Main loop: read the flame sensor and log events.
 */
static void main_loop(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return;
    }

    /* Configure GPIO pins as inputs with pull-up resistors. */
    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for flame sensor pin %d\n",
                FLAME_SENSOR_PIN);
        gpioTerminate();
        return;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for buzzer pin %d\n",
                BUZZER_PIN);
        gpioTerminate();
        return;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for LED pin %d\n",
                LED_PIN);
        gpioTerminate();
        return;
    }

    /* Ensure LED is off at startup. */
    gpioWrite(LED_PIN, 0);
    gpioWrite(BUZZER_PIN, 0);

    /* Register signal handler for graceful shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed: %s\n",
                strerror(errno));
    }

    log_event("Program started", 0);

    self_test();

    log_event("Program terminated", 0);
    gpioWrite(LED_PIN, 0);
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    main_loop();

    gpioWrite(LED_PIN, 0);
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

