#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR    0x23
#define LED_GPIO       17
#define BUFFER_SIZE    60
#define SAMPLE_PERIOD  1000000  /* microseconds */
#define LED_FREQ_MIN   0.5
#define LED_FREQ_MAX   5.0
#define LUX_THRESHOLD  1000
#define SAMPLE_COUNT   60

/* BH1750 register map */
#define BH1750_REG_ID      0x00
#define BH1750_REG_CTRL     0x01
#define BH1750_REG_DATA     0x02

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_bh1750(int fd, uint16_t *lux)
{
    uint8_t id;
    if (i2c_read_reg8(fd, BH1750_REG_ID, &id) < 0)
        return -1;
    if (id != 0x6B) {
        fprintf(stderr, "BH1750 ID mismatch: got 0x%02X, expected 0x6B\n", id);
        return -1;
    }

    uint8_t ctrl;
    if (i2c_read_reg8(fd, BH1750_REG_CTRL, &ctrl) < 0)
        return -1;

    /* Enable data conversion (bit 0) */
    if (i2c_write_reg8(fd, BH1750_REG_CTRL, 0x01) < 0)
        return -1;

    /* Wait for conversion to complete (~1.5 ms at ~1.5 MHz clock) */
    usleep(2000);

    uint8_t data;
    if (i2c_read_reg8(fd, BH1750_REG_DATA, &data) < 0)
        return -1;

    *lux = (data << 8) | 0x00;
    return 0;
}

static float calculate_lux(uint16_t raw)
{
    return (float)raw / 65535.0f;
}

static void control_led(int frequency)
{
    if (frequency < LED_FREQ_MIN) frequency = LED_FREQ_MIN;
    if (frequency > LED_FREQ_MAX) frequency = LED_FREQ_MAX;
    if (frequency < 0) frequency = 0;
    if (frequency > 1000) frequency = 1000;

    int duty_cycle = (int)((float)frequency / (float)LED_FREQ_MAX * 100.0f);
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;

    if (gpio_set_mode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
