/*
 * 74HC595 bit-banged seven-segment display driver for Raspberry Pi.
 *
 * Wiring:
 *   74HC595 data  -> GPIO17 (BCM)
 *   74HC595 clock -> GPIO18 (BCM)
 *   74HC595 latch -> GPIO27 (BCM)
 *   74HC595 output -> common cathode (segment a-g)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o seven_seg seven_seg.c -lpigpio -lrt
 * Run:
 *   sudo ./seven_seg
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* 74HC595 pin assignments (BCM numbering) */
#define DATA_PIN      17
#define CLOCK_PIN     18
#define LATCH_PIN     27

/* 74HC595 output segments (common-cathode) */
#define SEG_A        0
#define SEG_B        1
#define SEG_C        2
#define SEG_D        3
#define SEG_E        4
#define SEG_F        5
#define SEG_G        6
#define SEG_DP       7

/* Segment patterns for digit '5' */
static const uint8_t digit_5[8] = {
    0b01111111, /* A */
    0b01111111, /* B */
    0b01111111, /* C */
    0b01111111, /* D */
    0b01111111, /* E */
    0b01111111, /* F */
    0b01111111, /* G */
    0b01111111   /* DP (unused) */
};

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Send a byte of 8 bits to the 74HC595.
 * Returns 0 on success, -1 on error.
 */
static int hc595_send_byte(int data)
{
    if (data < 0 || data > 7) {
        fprintf(stderr, "Error: invalid data value %d\n", data);
        return -1;
    }

    /*
     * 74HC595:
     *   Data line (Q0..Q7) -> shift register input
     *   Clock line (CLK) -> rising edge every 8 bits
     *   Latch line (LATCH) -> low-to-high transition after 8 bits
     *
     * We send 8 bits MSB-first, then latch.
     */
    if (gpioWrite(CLOCK_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set CLOCK low\n");
        return -1;
    }
    if (gpioWrite(DATA_PIN, data) < 0) {
        fprintf(stderr, "Error: failed to set DATA %d\n", data);
        return -1;
    }
    if (gpioWrite(LATCH_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set LATCH high\n");
        return -1;
    }

    /*
     * Wait for clock edge (~1.5 us per bit, ~1.5 us total).
     */
    gpioDelay(1500);

    if (gpioWrite(LATCH_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set LATCH low\n");
        return -1;
    }

    return 0;
}

/*
 * Shift a byte of 8 bits out to the 74HC595.
 * Returns 0 on success, -1 on error.
 */
static int hc595_shift_out(int data)
{
    if (data < 0 || data > 7) {
        fprintf(stderr, "Error: invalid data value %d\n", data);
        return -1;
    }

    for (int i = 0; i < 8; i++) {
        if (gpioWrite(CLOCK_PIN, 1) < 0) {
            fprintf(stderr, "Error: failed to set CLOCK high\n");
            return -1;
        }
        if (gpioWrite(DATA_PIN, data & 0x01) < 0) {
            fprintf(stderr, "Error: failed to set DATA %d\n", data);
            return -1;
        }
        if (gpioWrite(CLOCK_PIN, 0) < 0) {
            fprintf(stderr, "Error: failed to set CLOCK low\n");
            return -1;
        }

        /*
         * 74HC595:
         *   Clock line (CLK) -> rising edge every 8 bits
         *   Latch line (LATCH) -> low-to-high transition after 8 bits
         */
        gpioDelay(1500);
    }

    return 0;
}

/*
 * Blink a digit on the display.
 * Returns 0 on success, -1 on error.
 */
static int blink_digit(int digit)
{
    if (digit < 0 || digit > 7) {
        fprintf(stderr, "Error: invalid digit %d\n", digit);
        return -1;
    }

    /* On: blink for 500 ms, off for 500 ms. */
    if (gpioWrite(CLOCK_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set CLOCK high\n");
        return -1;
    }
    gpioDelay(500000); /* 500 ms */
    if (gpioWrite(CLOCK_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set CLOCK low\n");
        return -1;
    }
    gpioDelay(500000); /* 500 ms */

    return 0;
}

int main(void)
{
    /* Install signal handlers for graceful shutdown. */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library. */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins as outputs. */
    if (gpioSetMode(DATA_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set DATA_PIN %d as output\n", DATA_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(CLOCK_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set CLOCK_PIN %d as output\n", CLOCK_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LATCH_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set LATCH_PIN %d as output\n", LATCH_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure all outputs are LOW initially. */
    if (gpioWrite(DATA_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize DATA_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(CLOCK_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize CLOCK_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LATCH_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize LATCH_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Seven-segment display blinking on 74HC595. Press Ctrl+C to exit.\n");

    while (g_running) {
        /* Shift out 8 bits of digit '5' */
        if (hc595_shift_out(digit_5[0]) < 0) {
            fprintf(stderr, "Error: failed to shift out digit '5'\n");
            break;
        }

        /* Blink the digit */
        if (blink_digit(5) < 0) {
            fprintf(stderr, "Error: failed to blink digit\n");
            break;
        }

        /* Delay between blinks */
        gpioDelay(500000); /* 500 ms */
    }

    /* Cleanup: ensure all outputs are LOW. */
    gpioWrite(DATA_PIN, 0);
    gpioWrite(CLOCK_PIN, 0);
    gpioWrite(LATCH_PIN, 0);

    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

