#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define LED_PIN 5
#define BLINK_DELAY_MS 750

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void delay_ms(unsigned ms) {
    struct timespec ts = {
        .tv_sec = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to write GPIO%d to LOW.\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        gpioWrite(LED_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Blinking LED on GPIO%d (BCM) every %d ms. Press Ctrl+C to exit.\n",
           LED_PIN, BLINK_DELAY_MS);

    while (running) {
        if (gpioWrite(LED_PIN, 1) != 0) {
            fprintf(stderr, "Error: failed to set GPIO%d HIGH.\n", LED_PIN);
            break;
        }
        delay_ms(BLINK_DELAY_MS);
        if (gpioWrite(LED_PIN, 0) != 0) {
            fprintf(stderr, "Error: failed to set GPIO%d LOW.\n", LED_PIN);
            break;
        }
        delay_ms(BLINK_DELAY_MS);
    }

    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("\nClean exit.\n");
    return EXIT_SUCCESS;
}

