        fprintf(stderr, "Error: failed to set LED pin %d as output.\n", LED_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set button pin %d as input.\n", BUTTON_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: failed to set pull-down on button pin %d.\n", BUTTON_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED pin %d to LOW.\n", LED_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void blink_led(void)
{
    if (gpioWrite(LED_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to turn LED on.\n");
        return;
