    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0) {
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(BUTTON_PIN, button_callback, NULL) != 0) {
        fprintf(stderr, "Error: failed to set alert function on button pin %d.\n", BUTTON_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("LED blinking on GPIO%d (button on GPIO%d) every %d ms. Press Ctrl-C to exit.\n",
           LED_PIN, BUTTON_PIN, BLINK_MS);

    while (running) {
        gpioDelay(100000); /* 100 ms */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

