#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define RED_PIN    24
#define GREEN_PIN  23
#define BLUE_PIN   18

#define PWM_FREQ   100   /* 100 Hz software PWM */
#define PWM_PERIOD 10    /* 10 ms period */
#define PWM_RANGE  100   /* 100 intensity levels */
#define PWM_STEP   1     /* 1-100 steps per PWM cycle */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    gpioWrite(RED_PIN, 0);
    gpioWrite(GREEN_PIN, 0);
    gpioWrite(BLUE_PIN, 0);
    gpioTerminate();
}

static void generate_random_intensity(int *r, int *g, int *b)
{
    time_t rawtime;
    struct tm timeinfo;
    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    *r = (int)((timeinfo.tm_year + 1900) * 365 +
               (timeinfo.tm_mon + 6) / 12 * 30 +
               (timeinfo.tm_mday - 1) / 31 +
               (timeinfo.tm_hour + 11) / 12 +
               (timeinfo.tm_min + 0.5) / 2 +
               (timeinfo.tm_sec + 0.5) / 2);
    *g = (int)((timeinfo.tm_year + 1900) * 365 +
               (timeinfo.tm_mon + 6) / 12 * 30 +
               (timeinfo.tm_mday - 1) / 31 +
               (timeinfo.tm_hour + 11) / 12 +
               (timeinfo.tm_min + 0.5) / 2 +
               (timeinfo.tm_sec + 0.5) / 2);
    *b = (int)((timeinfo.tm_year + 1900) * 365 +
               (timeinfo.tm_mon + 6) / 12 * 30 +
               (timeinfo.tm_mday - 1) / 31 +
               (timeinfo.tm_hour + 11) / 12 +
               (timeinfo.tm_min + 0.5) / 2 +
               (timeinfo.tm_sec + 0.5) / 2);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins as outputs */
    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", RED_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", GREEN_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", BLUE_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure all outputs start LOW */
    gpioWrite(RED_PIN, 0);
    gpioWrite(GREEN_PIN, 0);
    gpioWrite(BLUE_PIN, 0);

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("RGB LED control started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int r, g, b;
        generate_random_intensity(&r, &g, &b);

        /* Software PWM: 100 Hz, 10 ms period, 1-100 steps */
        for (int i = 0; i < PWM_RANGE && g_running; i++) {
            int pwm_val = (i * PWM_STEP) / PWM_RANGE;
            if (gpioPWM(RED_PIN, pwm_val) != 0) {
                fprintf(stderr, "Error: gpioPWM failed on GPIO%d.\n", RED_PIN);
                break;
            }
            if (gpioPWM(GREEN_PIN, pwm_val) != 0) {
                fprintf(stderr, "Error: gpioPWM failed on GPIO%d.\n", GREEN_PIN);
                break;
            }
            if (gpioPWM(BLUE_PIN, pwm_val) != 0) {
                fprintf(stderr, "Error: gpioPWM failed on GPIO%d.\n", BLUE_PIN);
                break;
            }
            gpioDelay(PWM_PERIOD);
        }
        if (g_running) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

