    }

    printf("RGB LED control started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int r, g, b;
        generate_random_intensity(&r, &g, &b);

        /* Software PWM: 100 Hz, 10 ms period, 1-100 steps */
        for (int i = 0; i < PWM_RANGE && g_running; i++) {
            int pwm_val = (i * PWM_STEP) / PWM_RANGE;
            if (gpioPWM(RED_PIN, pwm_val) != 0) {
                fprintf(stderr, "Error: gpioPWM failed on GPIO%d.\n", RED_PIN);
