            if (gpioPWM(GREEN_PIN, pwm_val) != 0) {
                fprintf(stderr, "Error: gpioPWM failed on GPIO%d.\n", GREEN_PIN);
                break;
            }
            if (gpioPWM(BLUE_PIN, pwm_val) != 0) {
                fprintf(stderr, "Error: gpioPWM failed on GPIO%d.\n", BLUE_PIN);
                break;
            }
            gpioDelay(PWM_PERIOD);
        }
        if (g_running) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

