/*
 * LSM303DLHC impact monitor for Raspberry Pi Zero W
 *
 * Reads the accelerometer's X, Y, Z axes at 10 Hz, computes the total
 * G-force magnitude, and triggers an impact interrupt on GPIO17 when
 * the magnitude exceeds a configurable threshold (default 2.0 G).
 *
 * Build:  gcc -O2 -Wall -o impact_monitor impact_monitor.c -lm
 * Run:    ./impact_monitor [-t <threshold_g>]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define I2C_ADDR       0x53          /* LSM303DLHC default address */
#define GPIO_CHIP      "gpiochip0"
#define GPIO_LINE      17            /* BCM 17 */
#define LOG_FILE       "impact_log.txt"
#define POLL_US        100000       /* 100 ms between samples */
#define IMPACT_DURATION_US 50000000   /* 50 ms impact pulse */
#define DEFAULT_THRESHOLD 2.0f
#define SAMPLE_PERIOD_US (POLL_US * 1000)

/* ------------------------------------------------------------------ */
/* Globals                                                             */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_line = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                          */
/* ------------------------------------------------------------------ */

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* LSM303DLHC initialization                                           */
/* ------------------------------------------------------------------ */

static int lsm303_init(int fd)
{
    /*
     * LSM303DLHC default register map (datasheet, Table 1).
     * The accelerometer is enabled by default; we only need to
     * verify the device is present.
     */
    uint8_t dev_id;
    if (i2c_read_bytes(fd, 0x00, &dev_id, 1) < 0)
        return -1;
    if (dev_id != 0x53) {
        fprintf(stderr, "LSM303DLHC not detected (got 0x%02X)\n", dev_id);
        return -1;
    }

    /*
     * Enable the accelerometer (bit 0 of register 0x0C).
     * The LSM303DLHC datasheet specifies the default value
     * of 0x00, but the actual register address is 0x0C.
     */
    if (i2c_write_byte(fd, 0x0C, 0x00) < 0)
        return -1;

    /*
     * Enable the magnetometer (bit 0 of register 0x0D).
     * The LSM303DLHC datasheet specifies the default value
     * of 0x00, but the actual register address is 0x0D.
     */
    if (i2c_write_byte(fd, 0x0D, 0x00) < 0)
        return -1;

    /*
     * Wake up the accelerometer (bit 0 of register 0x0E).
     * The LSM303DLHC datasheet specifies the default value
     * of 0x00, but the actual register address is 0x0E.
     */
    if (i2c_write_byte(fd, 0x0E, 0x00) < 0)
        return -1;

    /*
     * Wake up the magnetometer (bit 0 of register 0x0F).
     * The LSM303DLHC datasheet specifies the default value
     * of 0x00, but the actual register address is 0x0F.
     */
    if (i2c_write_byte(fd, 0x0F, 0x00) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO setup                                                           */
/* ------------------------------------------------------------------ */

static int setup_gpio(void)
{
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!g_chip) {
        fprintf(stderr, "gpiod_chip_open(%s) failed: %s\n",
                GPIO_CHIP, strerror(errno));
        return -1;
    }

    g_line = gpiod_chip_get_line(g_chip, GPIO_LINE);
    if (!g_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                GPIO_LINE, strerror(errno));
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(g_line, "lsm303_impact", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output failed: %s\n",
                strerror(errno));
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        g_line = NULL;
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Impact detection                                                      */
/* ------------------------------------------------------------------ */

static int impact_detected(void)
{
    int x, y, z;
    int x_g, y_g, z_g;

    if (i2c_read_bytes(g_i2c_fd, 0x00, &x, 1) < 0)
        return 0;
    if (i2c_read_bytes(g_i2c_fd, 0x01, &y, 1) < 0)
        return 0;
    if (i2c_read_bytes(g_i2c_fd, 0x02, &z, 1) < 0)
        return 0;

    x_g = (int)((float)x * 0.5f);
    y_g = (int)((float)y * 0.5f);
    z_g = (int)((float)z * 0.5f);

    return (x_g * x_g + y_g * y_g + z_g * z_g > DEFAULT_THRESHOLD * DEFAULT_THRESHOLD);
}

/* ------------------------------------------------------------------ */
/* Logging                                                              */
/* ------------------------------------------------------------------ */

static void log_data(float x, float y, float z)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, X: %.2f, Y: %.2f, Z: %.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                x, y, z);
    } else {
        fprintf(fp, "UNKNOWN, X: %.2f, Y: %.2f, Z: %.2f\n",
                x, y, z);
    }

    if (fclose(fp) != 0)
        perror("fclose");
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                              */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    if (g_line) {
        gpiod_line_set_value(g_line, 0);
        gpiod_line_release(g_line);
        g_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                 */
/* ------------------------------------------------------------------ */

int main(int argc, char *argv[])
{
    int opt;
    int threshold = DEFAULT_THRESHOLD;

    /* Parse command-line arguments */
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                if (threshold <= 0.0f) {
                    fprintf(stderr, "Threshold must be positive (default %.2f)\n",
                            DEFAULT_THRESHOLD);
                    return EXIT_FAILURE;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    /* Install signal handlers */
    if (install_signal_handlers() < 0)
        return EXIT_FAILURE;

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Set slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize LSM303DLHC */
    if (lsm303_init(g_i2c_fd) < 0) {
        fprintf(stderr, "LSM303DLHC initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure GPIO */
    if (setup_gpio() < 0) {
        fprintf(stderr, "GPIO setup failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("LSM303DLHC impact monitor started. Threshold: %.2f G\n",
           threshold);
    printf("Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        int impact = impact_detected();

        if (impact) {
            printf("Impact detected! Impact duration: %d us\n",
                   SAMPLE_PERIOD_US);
            log_data(0.0f, 0.0f, 0.0f);
            usleep(IMACTIVATION_DURATION_US);
            impact_duration = 0;
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < POLL_US / 10 && g_running; i++)
            usleep(10);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

