/*
 * FXOS8700CQ 6-axis accelerometer/magnetometer reader for Raspberry Pi Zero W.
 *
 * Wiring:
 *   SDA  -> GPIO 2  (I2C bus 1 SDA)
 *   SCL  -> GPIO 3  (I2C bus 1 SCL)
 *   VCC  -> 3.3 V
 *   GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o fxos8700 fxos8700.c -lgpiod
 * Run:    sudo ./fxos8700
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define FXOS8700_ADDR  0x68
#define WHO_AM_I       0x75
#define WHO_AM_I_VAL   0x77

#define ACCEL_XOUT_H   0x3B
#define ACCEL_YOUT_H   0x3D
#define ACCEL_ZOUT_H   0x3F
#define ACCEL_DATA_H   0x43
#define ACCEL_DATA_L   0x41

#define ACCEL_RANGE_2G  0x00
#define ACCEL_DATA_RATE_200HZ 0x00

#define MAG_XOUT_H      0x3E
#define MAG_YOUT_H      0x3C
#define MAG_ZOUT_H      0x3A
#define MAG_DATA_H      0x3C
#define MAG_DATA_L      0x3E

#define ACCEL_THRESHOLD_MG 2.0f
#define LOG_FILE        "impact_log.txt"
#define I2C_RETRIES     3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        if (write(fd, buf, 2) == 2)
            return 0;
        fprintf(stderr, "I2C write to reg 0x%02X failed (attempt %d/%d): %s\n",
                reg, attempt + 1, I2C_RETRIES, strerror(errno));
        usleep(10000);
    }
    return -1;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "I2C write (reg select 0x%02X) failed (attempt %d/%d): %s\n",
                    reg, attempt + 1, I2C_RETRIES, strerror(errno));
            usleep(10000);
            continue;
        }
        if (read(fd, buf, len) == (ssize_t)len)
            return 0;
        fprintf(stderr, "I2C read from reg 0x%02X failed (attempt %d/%d): %s\n",
                reg, attempt + 1, I2C_RETRIES, strerror(errno));
        usleep(10000);
    }
    return -1;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    return i2c_read_block(fd, reg, val, 1);
}

static int init_fxos8700(int fd)
{
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(fd, WHO_AM_I, &who_am_i) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I: %s\n", strerror(errno));
        return -1;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, WHO_AM_I_VAL);
        return -1;
    }

    if (i2c_write_byte(fd, ACCEL_XOUT_H, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, ACCEL_YOUT_H, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, ACCEL_ZOUT_H, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, ACCEL_DATA_H, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, ACCEL_DATA_L, 0x00) < 0) return -1;

    if (i2c_write_byte(fd, ACCEL_RANGE_2G, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, ACCEL_DATA_RATE_200HZ, 0x00) < 0) return -1;

    return 0;
}

static int read_accel_data(int fd, float *x, float *y, float *z)
{
    uint8_t buf[6];
    if (i2c_read_block(fd, ACCEL_DATA_H, buf, 6) < 0)
        return -1;

    int16_t x_raw = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t y_raw = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t z_raw = (int16_t)((buf[4] << 8) | buf[5]);

    *x = (float)x_raw / 16384.0f;
    *y = (float)y_raw / 16384.0f;
    *z = (float)z_raw / 16384.0f;
    return 0;
}

static float calc_magnitude(float x, float y, float z)
{
    return sqrtf(x * x + y * y + z * z);
}

static int log_impact(float x, float y, float z, float mag)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.3f,%.3f,%.3f,%.3f\n", ts, x, y, z, mag);
    fclose(fp);
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, FXOS8700_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                FXOS8700_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (init_fxos8700(g_i2c_fd) < 0) {
        fprintf(stderr, "FXOS8700 initialization failed.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("FXOS8700 initialized. Logging to %s every %d ms.\n",
           LOG_FILE, I2C_RETRIES);

    while (g_running) {
        float x, y, z;
        if (read_accel_data(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Sensor read error, continuing...\n");
        } else {
            float mag = calc_magnitude(x, y, z);
            if (mag > ACCEL_THRESHOLD_MG) {
                if (log_impact(x, y, z, mag) < 0)
                    fprintf(stderr, "Logging impact failed.\n");
            }
        }
        usleep(50000);
    }

    printf("\nShutting down cleanly...\n");
    if (g_i2c_fd >= 0)
        close(g_i2c_fd);
    return EXIT_SUCCESS;
}

