static int log_impact(float x, float y, float z, float mag)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.3f,%.3f,%.3f,%.3f\n", ts, x, y, z, mag);
    fclose(fp);
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, FXOS8700_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                FXOS8700_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (init_fxos8700(g_i2c_fd) < 0) {
        fprintf(stderr, "FXOS8700 initialization failed.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("FXOS8700 initialized. Logging to %s every %d ms.\n",
           LOG_FILE, I2C_RETRIES);

    while (g_running) {
        float x, y, z;
        if (read_accel_data(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Sensor read error, continuing...\n");
        } else {
            float mag = calc_magnitude(x, y, z);
            if (mag > ACCEL_THRESHOLD_MG) {
                if (log_impact(x, y, z, mag) < 0)
                    fprintf(stderr, "Logging impact failed.\n");
            }
        }
        usleep(50000);
    }

    printf("\nShutting down cleanly...\n");
    if (g_i2c_fd >= 0)
        close(g_i2c_fd);
    return EXIT_SUCCESS;
}

