/*
 * LSM303DLHC accelerometer + magnetometer reader for Raspberry Pi Zero W.
 *
 * Wiring:
 *   LSM303DLHC SDA -> GPIO2 (I2C bus 1 SDA)
 *   LSM303DLHC SCL -> GPIO3 (I2C bus 1 SCL)
 *   LSM303DLHC VDD -> 3.3 V
 *   LSM303DLHC GND -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o compass compass.c -lpigpio -lrt
 * Run:    sudo ./compass
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x68          /* LSM303DLHC default address */
#define ACCEL_XOUT_H   0x3B
#define MAG_XOUT_H      0x3D
#define ACCEL_DATA_LEN  6
#define MAG_DATA_LEN    6
#define SAMPLE_US      100000       /* 100 ms */
#define LOG_FILE       "compass_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_accel_handle = -1;
static int g_mag_handle   = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C read block failed (reg=0x%02X, rc=%d, expected=%u)\n",
                reg, rc, len);
        return -1;
    }
    return 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X, rc=%d)\n",
                reg, val, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Accelerometer                                                       */
/* ------------------------------------------------------------------ */
static int read_accel(int handle, float *x, float *y, float *z)
{
    uint8_t buf[ACCEL_DATA_LEN];
    if (i2c_read_block(handle, ACCEL_XOUT_H, buf, ACCEL_DATA_LEN) != 0)
        return -1;

    int16_t x_raw = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t y_raw = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t z_raw = (int16_t)((buf[5] << 8) | buf[4]);

    *x = (float)x_raw / 16384.0f;
    *y = (float)y_raw / 16384.0f;
    *z = (float)z_raw / 16384.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Magnetometer                                                        */
/* ------------------------------------------------------------------ */
static int read_mag(int handle, float *x, float *y, float *z)
{
    uint8_t buf[MAG_DATA_LEN];
    if (i2c_read_block(handle, MAG_XOUT_H, buf, MAG_DATA_LEN) != 0)
        return -1;

    int16_t x_raw = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t y_raw = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t z_raw = (int16_t)((buf[5] << 8) | buf[4]);

    *x = (float)x_raw / 32768.0f;
    *y = (float)y_raw / 32768.0f;
    *z = (float)z_raw / 32768.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Tilt-compensated heading                                            */
/* ------------------------------------------------------------------ */
static float calculate_heading(float ax, float ay, float az)
{
    float hx = atan2f(ay, az) * 180.0f / (float)M_PI;
    float hy = atan2f(-ax, sqrtf(ay * ay + az * az)) * 180.0f / (float)M_PI;
    float hz = atan2f(az, ax) * 180.0f / (float)M_PI;
    return hx + hy + hz;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(float ax, float ay, float az, float h)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s,%.3f,%.3f,%.3f,%.3f\n", ts, ax, ay, az, h);
    } else {
        fprintf(fp, "timestamp,ax,ay,az,h\n");
    }
    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_accel_handle >= 0) {
        i2cClose(g_accel_handle);
        g_accel_handle = -1;
    }
    if (g_mag_handle >= 0) {
        i2cClose(g_mag_handle);
        g_mag_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_accel_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_accel_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, g_accel_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_mag_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_mag_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, g_mag_handle);
        i2cClose(g_accel_handle);
        g_accel_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(stderr, "LSM303DLHC reader started. Logging to %s\n", LOG_FILE);

    while (g_running) {
        float ax, ay, az, h;

        if (read_accel(g_accel_handle, &ax, &ay, &az) != 0) {
            fprintf(stderr, "Accelerometer read error; continuing\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        if (read_mag(g_mag_handle, &hx, &hy, &hz) != 0) {
            fprintf(stderr, "Magnetometer read error; continuing\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        h = calculate_heading(ax, ay, az);

        if (log_data(ax, ay, az, h) != 0) {
            fprintf(stderr, "Logging error; continuing\n");
        }

        gpioDelay(SAMPLE_US);
    }

    fprintf(stderr, "\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

