/*
 * Raspberry Pi 3 Model B+ – VL6180X Time-of-Flight distance logger
 *
 * Wiring:
 *   VL6180X SDA  -> GPIO2 (I2C bus 1 SDA, pin 3)
 *   VL6180X SCL  -> GPIO3 (I2C bus 1 SCL, pin 5)
 *   VL6180X VCC  -> 3.3 V
 *   VL6180X GND  -> GND
 *
 * Build:  gcc -O2 -Wall -o vl6180x_logger vl6180x_logger.c
 * Run:    sudo ./vl6180x_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define VL6180X_ADDR   0x55
#define LOG_FILE       "distance_log.txt"
#define SAMPLE_US      100000   /* 100 ms */
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a 16-bit big-endian value from the VL6180X.
 * Returns 0 on success, -1 on error.
 */
static int vl6180x_read_16bit(int fd, uint16_t *out)
{
    uint8_t buf[2];
    ssize_t n;

    n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "read: expected 2 bytes, got %zd\n", n);
        return -1;
    }

    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/*
 * Initialize the VL6180X sensor.
 * Returns 0 on success, -1 on failure.
 */
static int vl6180x_init(int fd)
{
    uint8_t init_cmd[2] = {0x00, 0x00};
    uint8_t init_resp[2] = {0x00, 0x00};

    if (write(fd, init_cmd, 2) != 2) {
        fprintf(stderr, "init write failed: %s\n", strerror(errno));
        return -1;
    }

    usleep(10000); /* 10 ms settle */

    if (read(fd, init_resp, 2) != 2) {
        fprintf(stderr, "init read failed: %s\n", strerror(errno));
        return -1;
    }

    if (init_resp[0] != 0x55 || init_resp[1] != 0x55) {
        fprintf(stderr, "VL6180X init failed: unexpected response 0x%02X 0x%02X\n",
                init_resp[0], init_resp[1]);
        return -1;
    }

    return 0;
}

/*
 * Read the distance in mm.
 * Returns 0 on success, -1 on error.
 */
static int vl6180x_read_distance(int fd, uint16_t *distance_mm)
{
    uint8_t cmd[2] = {0x00, 0x01};
    uint8_t data[2] = {0};
    ssize_t n;

    /* Write measurement command */
    if (write(fd, cmd, 2) != 2) {
        fprintf(stderr, "measurement write failed: %s\n", strerror(errno));
        return -1;
    }

    usleep(10000); /* 10 ms conversion time */

    /* Read 2 bytes of distance data */
    n = read(fd, data, 2);
    if (n != 2) {
        fprintf(stderr, "measurement read failed: %s\n", strerror(errno));
        return -1;
    }

    *distance_mm = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/*
 * Log the distance to a file.
 * Returns 0 on success, -1 on error.
 */
static int log_distance(const char *filename, uint16_t distance_mm)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s, %u\n", ts, distance_mm);
    } else {
        fprintf(fp, "TIME_ERROR\n");
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose(%s) failed: %s\n", filename, strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    int fd = -1;
    uint16_t distance_mm = 0;
    int retries = 0;

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the I2C slave address */
    if (ioctl(fd, I2C_SLAVE, VL6180X_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                VL6180X_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Initialize the sensor */
    if (vl6180x_init(fd) != 0) {
        fprintf(stderr, "VL6180X initialization failed.\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("VL6180X initialized. Logging distance every %d ms.\n", SAMPLE_US / 1000);

    /* Main sampling loop */
    while (g_running) {
        if (vl6180x_read_distance(fd, &distance_mm) == 0) {
            printf("Distance: %u mm\n", distance_mm);

            if (distance_mm < 100) {
                printf("DOOR_OPEN\n");
                if (log_distance(LOG_FILE, distance_mm) != 0) {
                    fprintf(stderr, "Warning: failed to log distance.\n");
                }
            } else {
                printf("DOOR_CLOSED\n");
            }
        } else {
            fprintf(stderr, "Sensor read error. Retrying...\n");
            retries++;
            if (retries >= MAX_RETRIES) {
                fprintf(stderr, "Max retries reached. Exiting.\n");
                break;
            }
            usleep(SAMPLE_US);
            continue;
        }

        usleep(SAMPLE_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (fd >= 0) {
        close(fd);
    }
    printf("Done.\n");
    return EXIT_SUCCESS;
}

