/*
 * Raspberry Pi 4 Model B - Two STMicroelectronics IMP23ABSU Ultrasonic MEMS Microphone
 * sensors on I2C bus 1, sampling 16-bit signed audio samples every 10 ms.
 *
 * Build:  gcc -O2 -Wall -Wextra -o audio_log audio_log.c -lpigpio -lrt
 * Run:    sudo ./audio_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS          1
#define I2C_ADDR         0x28          /* IMP23ABSU default I2C address */
#define SAMPLE_PERIOD_US 10000          /* 10 ms */
#define LOG_FILE         "audio_log.dat"
#define MAX_SENSORS      2

/*
 * IMP23ABSU registers (16-bit, big-endian on the bus).
 * Register addresses are the 16-bit values sent to the device during
 * initialization; the actual registers are 16-bit words starting at
 * 0x00.  The IMP23ABSU datasheet provides the full register map.
 */
#define REG_CH1_AUDIO_DATA_L  0x00
#define REG_CH1_AUDIO_DATA_H  0x01
#define REG_CH2_AUDIO_DATA_L  0x02
#define REG_CH2_AUDIO_DATA_H  0x03

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle_ch1 = -1;
static int g_i2c_handle_ch2 = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly                  */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to a 16-bit register (big-endian on the bus)      */
/* ------------------------------------------------------------------ */
static int imp23_write_reg16(int handle, uint16_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value >> 8);
    buf[2] = (char)(value & 0xFF);

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "Error: i2cWriteDevice(reg=0x%04X, val=0x%04X) failed\n",
                reg, value);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from a 16-bit register (big-endian on the bus) */
/* ------------------------------------------------------------------ */
static int imp23_read_reg16(int handle, uint16_t reg, uint16_t *value)
{
    char buf[2];

    /* Write the 16-bit register address */
    if (i2cWriteDevice(handle, (char *)&reg, 1) != 1) {
        fprintf(stderr, "Error: i2cWriteDevice(reg=0x%04X) failed\n", reg);
        return -1;
    }

    /* Read 2 bytes back */
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error: i2cReadDevice(reg=0x%04X) failed\n", reg);
        return -1;
    }

    /* pigpio returns the data as big-endian */
    *value = ((uint16_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the IMP23ABSU driver library                             */
/* ------------------------------------------------------------------ */
static int imp23_init(int handle)
{
    /*
     * Register 0x00 is the device ID register.
     * The IMP23ABSU responds with a 16-bit value containing
     * the device type (0x01 for the IMP23ABSU).
     */
    if (imp23_read_reg16(handle, 0x00, &handle) != 0) {
        fprintf(stderr, "Error: cannot read device ID register\n");
        return -1;
    }
