/* ------------------------------------------------------------------ */
/* Write a 16-bit value to a 16-bit register (big-endian on the bus)      */
/* ------------------------------------------------------------------ */
static int imp23_write_reg16(int handle, uint16_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value >> 8);
    buf[2] = (char)(value & 0xFF);

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "Error: i2cWriteDevice(reg=0x%04X, val=0x%04X) failed\n",
                reg, value);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from a 16-bit register (big-endian on the bus) */
/* ------------------------------------------------------------------ */
static int imp23_read_reg16(int handle, uint16_t reg, uint16_t *value)
{
    char buf[2];

    /* Write the 16-bit register address */
    if (i2cWriteDevice(handle, (char *)&reg, 1) != 1) {
        fprintf(stderr, "Error: i2cWriteDevice(reg=0x%04X) failed\n", reg);
        return -1;
    }

    /* Read 2 bytes back */
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error: i2cReadDevice(reg=0x%04X) failed\n", reg);
        return -1;
    }

    /* pigpio returns the data as big-endian */
    *value = ((uint16_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

