    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = len;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS_PER_WORD;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Gyroscope                                                            */
/* ------------------------------------------------------------------ */
static int read_gyro_raw(float *gyro_x, float *gyro_y, float *gyro_z)
{
    uint8_t tx[2] = { 0x00, 0x00 };
    uint8_t rx[2] = { 0 };

    if (spi_transfer(tx, rx, 2) < 0)
        return -1;

    int16_t raw = (int16_t)((rx[0] << 8) | rx[1]);
    *gyro_x = (float)raw * GYRO_SENSITIVITY;
    *gyro_y = (float)raw * GYRO_SENSITIVITY;
    *gyro_z = (float)raw * GYRO_SENSITIVITY;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Accelerometer                                                      */
/* ------------------------------------------------------------------ */
static int read_accel_raw(float *accel_x, float *accel_y, float *accel_z)
{
    uint8_t tx[3] = { 0x00, 0x00, 0x00 };
    uint8_t rx[3] = { 0 };

    if (spi_transfer(tx, rx, 3) < 0)
        return -1;

    int16_t raw = (int16_t)((rx[0] << 8) | rx[1]);
    *accel_x = (float)raw * ACCEL_SENSITIVITY;
    *accel_y = (float)raw * ACCEL_SENSITIVITY;
    *accel_z = (float)raw * ACCEL_SENSITIVITY;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_csv_fp) {
        fclose(g_csv_fp);
        g_csv_fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed.\n");
        return EXIT_FAILURE;
    }

    g_csv_fp = fopen(CSV_FILENAME, "a");
    if (!g_csv_fp) {
        fprintf(stderr, "fopen(%s): %s\n", CSV_FILENAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(g_csv_fp, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");
    fflush(g_csv_fp);

    printf("IMU reader started. Logging to %s every %d ms. Press Ctrl+C to stop.\n",
           CSV_FILENAME, SAMPLE_PERIOD_MS);

    while (g_running) {
        float gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

        if (read_gyro_raw(&gyro_x, &gyro_y, &gyro_z) < 0) {
            fprintf(stderr, "Gyro read failed; skipping sample.\n");
            usleep(READ_RETRY_US);
            continue;
        }
        if (read_accel_raw(&accel_x, &accel_y, &accel_z) < 0) {
            fprintf(stderr, "Accel read failed; skipping sample.\n");
            usleep(READ_RETRY_US);
            continue;
        }

        time_t now = time(NULL);
        struct tm tm_buf;
        struct tm *tm = localtime_r(&now, &tm_buf);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);

        fprintf(g_csv_fp, "%s,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n",
                ts, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
        fflush(g_csv_fp);

        usleep(SAMPLE_PERIOD_MS * 1000U);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

