/*
 * ADIS16448 IMU SPI reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADIS16448 VDD  -> 3.3 V (Pin 1)
 *   ADIS16448 GND  -> GND  (Pin 9)
 *   ADIS16448 SDA  -> GPIO2 / SDA1 (Pin 3)
 *   ADIS16448 SCL  -> GPIO3 / SCL1 (Pin 5)
 *   ADIS16448 CS   -> GPIO8 / CE0  (Pin 24)
 *
 * SPI:
 *   SPI mode 3, 1 MHz max, 8-bit words, MSB-first
 *   CS0 active low
 *
 * Build:
 *   gcc -O2 -Wall -o imu_reader imu_reader.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_3
#define SPI_CS_PIN      8          /* BCM GPIO8 */
#define SAMPLE_PERIOD_US 100000U   /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-register SPI transaction: send the 8-bit register address
 * (bit 7 set) in the first 16-bit cycle, then capture the 16-bit data
 * response in the second cycle.
 */
static int spi_read_reg(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 2,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
        .tx_nbits      = 0,
        .rx_nbits      = 0,
        .pad           = 0
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE failed: %s\n", strerror(errno));
        return -1;
    }

    *out = ((uint16_t)(rx[0] & 0x7F) << 8) | rx[1];
    return 0;
}

static int read_imu_data(int fd, float *gyro_x, float *gyro_y,
                         float *gyro_z, float *accel_x, float *accel_y,
                         float *accel_z)
{
    uint16_t gyro_x_raw, gyro_y_raw, gyro_z_raw,
           accel_x_raw, accel_y_raw, accel_z_raw;

    if (spi_read_reg(fd, 0x00, &gyro_x_raw) < 0) return -1;
    if (spi_read_reg(fd, 0x01, &gyro_y_raw) < 0) return -1;
    if (spi_read_reg(fd, 0x02, &gyro_z_raw) < 0) return -1;
    if (spi_read_reg(fd, 0x03, &accel_x_raw) < 0) return -1;
    if (spi_read_reg(fd, 0x04, &accel_y_raw) < 0) return -1;
    if (spi_read_reg(fd, 0x05, &accel_z_raw) < 0) return -1;

    *gyro_x = (float)gyro_x_raw * 0.02f;
    *gyro_y = (float)gyro_y_raw * 0.02f;
    *gyro_z = (float)gyro_z_raw * 0.02f;
    *accel_x = (float)accel_x_raw * 0.00025f;
    *accel_y = (float)accel_y_raw * 0.00025f;
    *accel_z = (float)accel_z_raw * 0.00025f;

    return 0;
}

int main(void)
{
    int fd = -1;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open SPI device */
    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Configure SPI mode, bits, and speed */
    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        goto cleanup;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        goto cleanup;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Configure CS pin as output, active low */
    if (ioctl(fd, SPI_IOC_WR_CS_PIN, &SPI_CS_PIN) < 0) {
        fprintf(stderr, "SPI_IOC_WR_CS_PIN failed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("ADIS16448 IMU reader started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float gyro_x, gyro_y, gyro_z,
               accel_x, accel_y, accel_z;

        if (read_imu_data(fd, &gyro_x, &gyro_y, &gyro_z,
                          &accel_x, &accel_y, &accel_z) < 0) {
            fprintf(stderr, "SPI read error; retrying in 100 ms\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        printf("Gyro X: %.3f  Gyro Y: %.3f  Gyro Z: %.3f\n",
               gyro_x, gyro_y, gyro_z);
        printf("Accel X: %.3f  Accel Y: %.3f  Accel Z: %.3f\n",
               accel_x, accel_y, accel_z);

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

