code:
/*
 * ADIS16448 IMU reader for Raspberry Pi 4 Model B
 * SPI: CE0 (GPIO8), 1 MHz, Mode 0
 * Library: pigpio (modern C API)
 *
 * Build: gcc -O2 -Wall -o adis16448_reader adis16448_reader.c -lpigpio -lrt
 * Run:   sudo ./adis16448_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL      0
#define SPI_SPEED        1000000   /* 1 MHz */
#define SPI_FLAGS        0         /* Mode 0, active-low CE */
#define SPI_DELAY_US     0         /* 0-40 µs stall between transfers */
#define READ_INTERVAL_US 100000    /* 100 ms */

/* ADIS16448 register addresses (from datasheet) */
#define ADIS16448_REG_GYRO_XOUT_H   0x00
#define ADIS16448_REG_GYRO_XOUT_L   0x01
#define ADIS16448_REG_GYRO_YOUT_H   0x02
#define ADIS16448_REG_GYRO_YOUT_L   0x03
#define ADIS16448_REG_GYRO_ZOUT_H   0x04
#define ADIS16448_REG_GYRO_ZOUT_L   0x05
#define ADIS16448_REG_ACCEL_XOUT_H  0x06
#define ADIS16448_REG_ACCEL_XOUT_L  0x07
#define ADIS16448_REG_ACCEL_YOUT_H  0x08
#define ADIS16448_REG_ACCEL_YOUT_L  0x09
#define ADIS16448_REG_ACCEL_ZOUT_H  0x0A
#define ADIS16448_REG_ACCEL_ZOUT_L  0x0B

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */
static int spi_transfer(uint8_t *tx, uint8_t *rx, int len)
{
    int bytes_written = spiXfer(g_spi_handle, (char *)tx, (char *)rx, len);
    if (bytes_written != len) {
        fprintf(stderr, "SPI transfer failed (wrote %d, expected %d)\n",
                bytes_written, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register                                              */
/* ------------------------------------------------------------------ */
static int read_register(uint8_t reg, uint16_t *out)
{
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = { 0 };

    if (spi_transfer(tx, rx, 2) != 0)
        return -1;

    *out = ((uint16_t)rx[0] << 8) | rx[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register pair (big-endian)                            */
/* ------------------------------------------------------------------ */
static int read_register_pair(uint8_t reg_h, uint16_t *out)
{
    uint8_t tx[2] = { (uint8_t)(reg_h | 0x80), 0x00 };
    uint8_t rx[2] = { 0 };

    if (spi_transfer(tx, rx, 2) != 0)
        return -1;

    *out = ((uint16_t)rx[0] << 8) | rx[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Scale gyroscope values                                               */
/* ------------------------------------------------------------------ */
static float gyro_scale(uint16_t raw)
{
    return (float)raw * 0.05f;
}

/* ------------------------------------------------------------------ */
/* Scale accelerometer values                                          */
/* ------------------------------------------------------------------ */
static float accel_scale(uint16_t raw)
{
    return (float)raw * 0.00025f;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI open --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handling --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADIS16448 IMU reader started. Press Ctrl+C to exit.\n");
    printf("SPI channel %d, 1 MHz, Mode 0, 0 delay.\n", SPI_CHANNEL);
    printf("Press Ctrl+C to exit.\n");

    /* --- main loop --- */
    while (g_running) {
        uint16_t gyro_raw = 0, accel_raw = 0;

        if (read_register_pair(ADIS16448_REG_GYRO_XOUT_H, &gyro_raw) != 0) {
            fprintf(stderr, "Failed to read gyroscope data\n");
            gpioDelay(READ_INTERVAL_US);
            continue;
        }

        if (read_register_pair(ADIS16448_REG_ACCEL_XOUT_H, &accel_raw) != 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            gpioDelay(READ_INTERVAL_US);
