/*
 * MPU-6886 IMU reader for Raspberry Pi 4 Model B
 * Uses pigpio for I2C communication.
 *
 * Wiring:
 *   MPU-6886 SDA -> GPIO2 (I2C1 SDA)
 *   MPU-6886 SCL -> GPIO3 (I2C1 SCL)
 *   MPU-6886 VDD -> 3.3 V
 *   MPU-6886 GND -> GND
 *
 * Build: gcc -Wall -o mpu6886_reader mpu6886_reader.c -lpigpio -lrt
 * Run:   sudo ./mpu6886_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x68          /* MPU-6886 default I2C address */
#define ACCEL_XOUT_H   0x3B
#define GYRO_XOUT_H    0x43

#define ACCEL_SCALE_X  16384.0f
#define GYRO_SCALE_X   32768.0f

#define READ_DELAY_US  50000         /* 50 ms */
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Reads a 16-bit big-endian value from a 16-bit register.
 * Returns 0 on success, -1 on I2C error.
 */
static int read_reg16(int fd, uint8_t reg, int16_t *out)
{
    int v = i2cReadWordData(fd, reg);
    if (v < 0) {
        fprintf(stderr, "I2C read error (reg 0x%02X): %d\n", reg, v);
        return -1;
    }
    *out = (int16_t)((v & 0xFF) | ((v >> 8) & 0xFF) << 8);
    return 0;
}

/*
 * Reads a 16-bit big-endian value from a 16-bit register.
 * Returns 0 on success, -1 on I2C error.
 */
static int read_reg16_u(int fd, uint8_t reg, uint16_t *out)
{
    int v = i2cReadWordData(fd, reg);
    if (v < 0) {
        fprintf(stderr, "I2C read error (reg 0x%02X): %d\n", reg, v);
        return -1;
    }
    *out = (uint16_t)((v & 0xFF) | ((v >> 8) & 0xFF) << 8);
    return 0;
}

/*
 * Reads a 16-bit big-endian value from a 16-bit register.
 * Returns 0 on success, -1 on I2C error.
 */
static int read_reg16_u_ex(int fd, uint8_t reg, uint16_t *out)
{
    int v = i2cReadWordData(fd, reg);
    if (v < 0) {
        fprintf(stderr, "I2C read error (reg 0x%02X): %d\n", reg, v);
        return -1;
    }
    *out = (uint16_t)((v & 0xFF) | ((v >> 8) & 0xFF) << 8);
    return 0;
}

int main(void)
{
    int fd = -1;
    int retries = 0;

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus to MPU-6886 */
    fd = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MPU-6886 reader started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int16_t accel_x, accel_y, accel_z;
        uint16_t gyro_x, gyro_y, gyro_z;

        /* Read accelerometer */
        if (read_reg16_u_ex(fd, ACCEL_XOUT_H, &accel_x) != 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            retries++;
            if (retries >= MAX_RETRIES) {
                fprintf(stderr, "Max retries reached, aborting\n");
                break;
            }
            gpioDelay(READ_DELAY_US);
            continue;
        }

        /* Read gyroscope */
        if (read_reg16_u_ex(fd, GYRO_XOUT_H, &gyro_x) != 0) {
            fprintf(stderr, "Failed to read gyroscope data\n");
            retries++;
            if (retries >= MAX_RETRIES) {
                fprintf(stderr, "Max retries reached, aborting\n");
                break;
            }
            gpioDelay(READ_DELAY_US);
            continue;
        }

        /* Convert to g-force */
        accel_x /= ACCEL_SCALE_X;
        accel_y /= ACCEL_SCALE_X;
        accel_z /= ACCEL_SCALE_X;

        gyro_x /= GYRO_SCALE_X;
        gyro_y /= GYRO_SCALE_X;
        gyro_z /= GYRO_SCALE_X;

        printf("Accel: X=%6d Y=%6d Z=%6d  Gyro: X=%6d Y=%6d Z=%6d\n",
               accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);

        gpioDelay(READ_DELAY_US);
    }

    /* Clean shutdown */
    if (fd >= 0) {
        i2cClose(fd);
    }
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

