#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define ICM20602_ADDR 0x68
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43
#define ACCEL_XOUT_L 0x3C
#define GYRO_XOUT_L 0x44
#define ACCEL_YOUT_H 0x3D
#define GYRO_YOUT_H 0x45
#define ACCEL_YOUT_L 0x3E
#define GYRO_YOUT_L 0x46
#define ACCEL_ZOUT_H 0x3F
#define GYRO_ZOUT_H 0x47
#define ACCEL_ZOUT_L 0x38
#define GYRO_ZOUT_L 0x48

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read burst failed (len %d): %s\n", len, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read block failed (len %d): %s\n", len, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_accel(int fd, int16_t *ax, int16_t *ay, int16_t *az) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, ACCEL_XOUT_H, buf, 6) < 0) return -1;
    *ax = (int16_t)((buf[0] << 8) | buf[1]);
    *ay = (int16_t)((buf[2] << 8) | buf[3]);
    *az = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static int i2c_read_gyro(int fd, int16_t *gx, int16_t *gy, int16_t *gz) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, GYRO_XOUT_H, buf, 6) < 0) return -1;
    *gx = (int16_t)((buf[0] << 8) | buf[1]);
    *gy = (int16_t)((buf[2] << 8) | buf[3]);
    *gz = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static int log_data(FILE *fp, int16_t ax, int16_t ay, int16_t az, int16_t gx, int16_t gy, int16_t gz) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d,%d,%d,%d\n", timestamp, ax, ay, az, gx, gy, gz) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ICM20602_ADDR) < 0) {
        perror("Failed to acquire I2C bus access");
        close(i2c_fd);
        return 1;
    }

    if (i2c_write_byte(i2c_fd, ACCEL_XOUT_H, 0x00) < 0) {
        close(i2c_fd);
        return 1;
    }
    if (i2c_write_byte(i2c_fd, GYRO_XOUT_H, 0x00) < 0) {
        close(i2c_fd);
        return 1;
    }
    if (i2c_write_byte(i2c_fd, ACCEL_XOUT_L, 0x00) < 0) {
        close(i2c_fd);
        return 1;
    }
    if (i2c_write_byte(i2c_fd, GYRO_XOUT_L, 0x00) < 0) {
        close(i2c_fd);
        return 1;
    }
    if (i2c_write_byte(i2c_fd, ACCEL_YOUT_H, 0x00) < 0) {
        close(i2c_fd);
        return 1;
    }
    if (i2c_write_byte(i2c_fd, GYRO_YOUT_H, 0x00) < 0) {
        close(i2c_fd);
        return 1;
    }
    if (i2c_write_byte(i2c_fd, ACCEL_YOUT_L, 0x00) < 0) {
        close(i2c_fd);
        return 1;
    }
    if (i2c_write_byte(i2c_fd, GYRO_YOUT_L, 0x00) < 0) {
        close(i2c_fd);
