/*
 * GY-45 MMA8451Q accelerometer reader with LED alert on impact.
 * Board:  Raspberry Pi 3 Model B+
 * I2C bus:  BCM 1 (GPIO2=SDA, GPIO3=SCL)
 * LED:     GPIO17 (BCM 17)
 *
 * Build:  gcc -O2 -Wall -o impact_reader impact_reader.c -lm
 * Run:    sudo ./impact_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define MMA8451_ADDR   0x53
#define LED_PIN        17
#define THRESHOLD_G    2.0f
#define POLL_MS        100
#define LED_ON_MS      500
#define LOG_FILE       "impact_log.txt"

/* MMA8451Q register addresses */
#define MMA8451_REG_ID      0x00
#define MMA8451_REG_DATA_XG  0x08

/* MMA8451Q ID register: expected value 0x68 */
#define MMA8451_ID_EXPECTED  0x68

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static struct gpiod_line *g_led_line = NULL;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg 0x%02X, val 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_i2c(void)
{
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, MMA8451_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                MMA8451_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int init_gpio(void)
{
    g_led_line = gpiod_line_request_output(LED_PIN, "gy45_led", 0);
    if (!g_led_line) {
        fprintf(stderr, "Cannot request GPIO %d as output: %s\n",
                LED_PIN, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_sensor(void)
{
    uint8_t id = 0;
    if (i2c_read_reg8(g_i2c_fd, MMA8451_REG_ID, &id) < 0)
        return -1;
    if (id != MMA8451_ID_EXPECTED) {
        fprintf(stderr, "MMA8451 ID mismatch: got 0x%02X, expected 0x%02X\n",
                id, MMA8451_ID_EXPECTED);
        return -1;
    }
    printf("MMA8451Q detected (ID=0x%02X)\n", id);
    return 0;
}

static int read_acceleration(float *x, float *y, float *z)
{
    uint8_t buf[6];
    if (i2c_read_reg8(g_i2c_fd, MMA8451_REG_DATA_XG, buf) < 0)
        return -1;

    int16_t x_raw = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t y_raw = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t z_raw = (int16_t)((buf[4] << 8) | buf[5]);

    *x = (float)x_raw / 16384.0f;
    *y = (float)y_raw / 16384.0f;
    *z = (float)z_raw / 16384.0f;
    return 0;
}

static void log_impact(float x, float y, float z)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];
    localtime_r(&t, &tm);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(g_log_fp, "%s, X: %.2f g, Y: %.2f g, Z: %.2f g\n",
            ts, x, y, z);
    fflush(g_log_fp);
}

static void cleanup(void)
{
    if (g_led_line) {
        gpiod_line_set_value(g_led_line, 0);
        gpiod_line_release(g_led_line);
        g_led_line = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_i2c() < 0)
        return EXIT_FAILURE;

    if (init_gpio() < 0) {
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (init_sensor() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Impact detection started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float x, y, z;
        if (read_acceleration(&x, &y, &z) < 0) {
            fprintf(stderr, "Sensor read error; continuing...\n");
            usleep(POLL_MS * 1000);
            continue;
        }

        if (fabsf(x) > THRESHOLD_G || fabsf(y) > THRESHOLD_G ||
            fabsf(z) > THRESHOLD_G) {
            printf("Impact detected! X: %.2f g, Y: %.2f g, Z: %.2f g\n",
                   x, y, z);
            log_impact(x, y, z);
            gpiod_line_set_value(g_led_line, 1);
            usleep(LED_ON_MS * 1000);
            gpiod_line_set_value(g_led_line, 0);
        }

        usleep(POLL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

