/*
 * ADXL345 free-fall detector for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADXL345 INT1 -> GPIO17 (BCM 17, physical pin 11)
 *   ADXL345 SDA  -> GPIO2 / I2C bus 1 SDA
 *   ADXL345 SCL  -> GPIO3 / I2C bus 1 SCL
 *   ADXL345 VDD  -> 3.3 V
 *   ADXL345 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -o freefall freefall.c -lm
 * Run:    ./freefall
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <sys/stat.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADXL345_ADDR   0x53
#define INT1_PIN       17
#define LOG_FILE       "freefall_log.csv"
#define POLL_TIMEOUT_MS 100

/* ADXL345 register addresses */
#define ADXL345_REG_DEVID   0x00
#define ADXL345_REG_PWR_MGMT_1 0x2D
#define ADXL345_REG_INT_ENABLE 0x2E
#define ADXL345_REG_INT_STATUS 0x2F
#define ADXL345_REG_DATA_FORMAT 0x31
#define ADXL345_REG_DATAX0    0x32

#define ADXL345_DEVID_VAL   0x65

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to an ADXL345 register.                          */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int adxl_write_reg(uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(g_i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from an ADXL345 register.                        */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int adxl_read_reg(uint8_t reg, uint8_t *val)
{
    if (write(g_i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(g_i2c_fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian value from two consecutive registers.   */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int adxl_read_16(uint8_t reg_low, int16_t *out)
{
    uint8_t lo, hi;
    if (adxl_read_reg(reg_low, &lo) != 0)
        return -1;
    if (adxl_read_reg(reg_low + 1, &hi) != 0)
        return -1;
    *out = (int16_t)((uint16_t)hi << 8 | (uint16_t)lo);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the ADXL345 sensor.                                       */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int adxl_init(void)
{
    uint8_t devid;

    /* Verify device ID */
    if (adxl_read_reg(ADXL345_REG_DEVID, &devid) != 0) {
        fprintf(stderr, "Cannot read device ID; sensor absent or bus error.\n");
        return -1;
    }
    if (devid != ADXL345_DEVID_VAL) {
        fprintf(stderr, "Unexpected device ID: 0x%02X (expected 0x%02X).\n",
                devid, ADXL345_DEVID_VAL);
        return -1;
    }
    printf("ADXL345 detected (ID=0x%02X).\n", devid);

    /* Standby mode: write 0x00 to PWR_MGMT_1 */
    if (adxl_write_reg(ADXL345_REG_PWR_MGMT_1, 0x00) != 0)
        return -1;

    /* Allow sensor to settle */
    usleep(100000);

    /* Enable INT1 (default is disabled) */
    if (adxl_write_reg(ADXL345_REG_INT_ENABLE, 0x08) != 0)
        return -1;

    /* Allow sensor to settle after INT1 enable */
    usleep(100000);

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read acceleration data from the ADXL345.                             */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int adxl_read_accel(int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t int_status;

    /* Read INT_STATUS to clear any pending interrupts */
    if (adxl_read_reg(ADXL345_REG_INT_STATUS, &int_status) != 0)
        return -1;

    /* Check if INT1 is pending (bit 0) */
    if (int_status & 0x01) {
        /* Clear the interrupt by writing 0x00 to INT_ENABLE */
        if (adxl_write_reg(ADXL345_REG_INT_ENABLE, 0x00) != 0)
            return -1;

        /* Poll for the next event (max 100 ms) */
        for (int i = 0; i < POLL_TIMEOUT_MS; i++) {
            int_status = 0;
            if (adxl_read_reg(ADXL345_REG_INT_STATUS, &int_status) != 0)
                return -1;
            if (!(int_status & 0x01))
                break;
            usleep(10000); /* 10 ms */
        }
    }

    /* Read X, Y, Z */
    if (adxl_read_16(ADXL345_REG_DATAX0, x) != 0)
        return -1;
    if (adxl_read_16(ADXL345_REG_DATAX1, x + 2) != 0)
        return -1;
    if (adxl_read_16(ADXL345_REG_DATAY0, y) != 0)
        return -1;
    if (adxl_read_16(ADXL345_REG_DATAY1, y + 2) != 0)
        return -1;
    if (adxl_read_16(ADXL345_REG_DATAA0, z) != 0)
        return -1;
    if (adxl_read_16(ADXL345_REG_DATAA1, z + 2) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Write a CSV row to the log file.                                    */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int log_data(int16_t x, int16_t y, int16_t z)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s,%d,%d,%d\n", ts, x, y, z) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup all resources.                                              */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the ADXL345 slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                ADXL345_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize the ADXL345 */
    if (adxl_init() != 0) {
        fprintf(stderr, "ADXL345 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open the CSV log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write the CSV header if the file is empty */
    if (ftell(g_log_fp) == 0) {
        if (fprintf(g_log_fp, "timestamp,x_g,y_g,z_g\n") < 0) {
            fprintf(stderr, "Cannot write CSV header: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        if (fflush(g_log_fp) != 0) {
            fprintf(stderr, "fflush failed: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
    }

    printf("Free-fall detection started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        int16_t x, y, z;

        if (adxl_read_accel(&x, &y, &z) == 0) {
            if (log_data(x, y, z) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data.\n");
        }

        /* Sleep for 100 ms (max poll interval) */
        usleep(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

