/*
 * ADIS16266 Gyroscope Data Logger for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   ADIS16266 VDD  -> 3.3V (Pin 1)
 *   ADIS16266 GND  -> GND  (Pin 9)
 *   ADIS16266 SCL  -> GPIO11 (Pin 3, SPI0 SCLK)
 *   ADIS16266 SDA  -> GPIO9  (Pin 5, SPI0 MISO)
 *   ADIS16266 CS   -> GPIO8  (Pin 6, SPI0 CE0)
 *
 * Build: gcc -O2 -Wall -o gyro_logger gyro_logger.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_BITS_PER_WORD 8U
#define SPI_MODE        SPI_MODE_3
#define SPI_DELAY_US    0U

#define GYRO_REG_WHO_AM_I 0x00
#define GYRO_REG_GYRO_XOUT_H 0x20
#define GYRO_REG_GYRO_XOUT_L 0x21

#define GYRO_SCALE_FACTOR 0.0305f
#define GYRO_SAMPLE_US   10000U   /* 10 ms */
#define LOG_FILE_NAME    "gyro_log.csv"

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a 16-bit register from the ADIS16266.
 * Returns 0 on success, -1 on error.
 */
static int spi_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t tx[3] = { (uint8_t)(reg | 0x80), 0x00, 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = SPI_DELAY_US,
        .cs_change = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        return -1;
    }

    *out = ((uint16_t)(rx[0] & 0x03) << 8) | rx[1];
    return 0;
}

static int spi_write_reg16(int fd, uint8_t reg, uint16_t value)
{
    uint8_t tx[3] = { (uint8_t)(reg | 0x80), (uint8_t)(value & 0xFF), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = SPI_DELAY_US,
        .cs_change = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        return -1;
    }

    return 0;
}

static int read_gyro_data(float *gyro_x, float *gyro_y, float *gyro_z)
{
    uint16_t raw_x, raw_y, raw_z;

    if (spi_read_reg16(g_spi_fd, GYRO_REG_GYRO_XOUT_H, &raw_x) < 0) {
        fprintf(stderr, "Error: failed to read gyro X register.\n");
        return -1;
    }
    if (spi_read_reg16(g_spi_fd, GYRO_REG_GYRO_XOUT_L, &raw_y) < 0) {
        fprintf(stderr, "Error: failed to read gyro Y register.\n");
        return -1;
    }
    if (spi_read_reg16(g_spi_fd, GYRO_REG_GYRO_XOUT_H + 1, &raw_z) < 0) {
        fprintf(stderr, "Error: failed to read gyro Z register.\n");
        return -1;
    }

    *gyro_x = (float)raw_x * GYRO_SCALE_FACTOR;
    *gyro_y = (float)raw_y * GYRO_SCALE_FACTOR;
    *gyro_z = (float)raw_z * GYRO_SCALE_FACTOR;
    return 0;
}

static int log_data(FILE *fp, float gyro_x, float gyro_y, float gyro_z)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error: time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r() failed.\n");
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime() failed.\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, gyro_x, gyro_y, gyro_z) < 0) {
        fprintf(stderr, "Error: fprintf() to log file failed.\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error: fflush() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Error: cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error: cannot set SPI mode: %s\n", strerror(errno));
        close(g_spi_fd);
        return EXIT_FAILURE;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error: cannot set SPI bits per word: %s\n", strerror(errno));
        close(g_spi_fd);
        return EXIT_FAILURE;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error: cannot set SPI speed: %s\n", strerror(errno));
        close(g_spi_fd);
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE_NAME, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error: cannot open %s: %s\n", LOG_FILE_NAME, strerror(errno));
        close(g_spi_fd);
        return EXIT_FAILURE;
    }

    fprintf(stderr, "Logging gyroscope data to %s. Press Ctrl+C to stop.\n", LOG_FILE_NAME);

    while (g_running) {
        float gyro_x, gyro_y, gyro_z;

        if (read_gyro_data(&gyro_x, &gyro_y, &gyro_z) == 0) {
            if (log_data(g_log_fp, gyro_x, gyro_y, gyro_z) != 0) {
                fprintf(stderr, "Warning: failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Warning: failed to read gyro data.\n");
        }

        usleep(GYRO_SAMPLE_US);
    }

    fprintf(stderr, "\nShutting down gracefully...\n");

    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }

    return EXIT_SUCCESS;
}

