/*
 * KY-026 Flame Sensor Monitor for Raspberry Pi Zero W
 *
 * Wiring:
 *   KY-026 VCC  -> 3.3 V (Pin 1)
 *   KY-026 GND  -> GND  (Pin 9)
 *   KY-026 DO   -> GPIO17 (BCM 17, physical pin 11)
 *
 * The KY-026 is an open-collector module: LOW indicates flame, HIGH
 * indicates no flame.  The internal pull-up is enabled on the BCM17
 * line so that the sensor reads HIGH when no flame is present.
 *
 * Build:  gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lpigpio -lrt
 * Run:    sudo ./flame_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 17          /* BCM 17, physical pin 11 */
#define LOG_FILE_NAME   "flame_events.log"
#define POLL_INTERVAL_US 500000        /* 500 ms */
#define MAX_RETRIES     3

/* ------------------------------------------------------------------ */
/* Globals                                                            */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                            */
/* ------------------------------------------------------------------ */

static void log_event(const char *event_type)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
