/*
 * Raspberry Pi 5 - Omron D7S-0001 Vibration Sensor Reader
 *
 * Reads acceleration data from an Omron D7S-0001 vibration sensor over I2C
 * bus /dev/i2c-1, and logs each sample to vibration_log.csv with a
 * timestamp in ISO-8601 UTC format.
 *
 * Build:  gcc -O2 -Wall -Wextra -o vibration_reader vibration_reader.c
 * Run:    ./vibration_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SENSOR_ADDR    0x00
#define SAMPLE_PERIOD_US 100000   /* 100 ms */
#define LOG_FILE       "vibration_log.csv"

/*
 * Omron D7S-0001:
 *   - I2C address: 0x00 (default)
 *   - X, Y, Z axes: 16-bit signed, little-endian.
 *   - Data rate: ~1.2 kHz (typical)
 */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/*
 * Write a 16-bit little-endian value to the D7S-0001's 16-bit register
 * address `reg`.  Returns 0 on success, -1 on error.
 */
static int d7s_write_reg(int fd, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(value & 0xFF);
    buf[2] = (uint8_t)((value >> 8) & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read `len` bytes from the D7S-0001's 16-bit register `reg`.
 * Returns 0 on success, -1 on error.
 */
static int d7s_read_reg(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit little-endian value from the D7S-0001's 16-bit register
 * address `reg`.  Returns 0 on success, -1 on error.
 */
static int d7s_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    uint8_t buf[2];

    if (d7s_read_reg(fd, reg, buf, sizeof(buf)) != 0)
        return -1;

    *out = (int16_t)((uint16_t)buf[0] | ((uint16_t)buf[1] << 8));
    return 0;
}

/*
 * Read the X, Y, and Z acceleration values from the D7S-0001.
 * Returns 0 on success, -1 on error.
 */
static int d7s_read_data(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    int16_t x_raw, y_raw, z_raw;

    if (d7s_read_reg16(fd, SENSOR_ADDR, &x_raw) != 0)
        return -1;
    if (d7s_read_reg16(fd, SENSOR_ADDR + 2, &y_raw) != 0)
        return -1;
    if (d7s_read_reg16(fd, SENSOR_ADDR + 4, &z_raw) != 0)
        return -1;

    *x = x_raw;
    *y = y_raw;
    *z = z_raw;
    return 0;
}

/*
 * Append a CSV row to the log file.
 * Returns 0 on success, -1 on error.
 */
static int log_data(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        fprintf(stderr, "gmtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    int fd = -1;
    FILE *fp = NULL;
    int16_t x, y, z;
    int rc = EXIT_FAILURE;

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Acquire sensor address --- */
    if (ioctl(fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SENSOR_ADDR, strerror(errno));
        goto cleanup;
    }

    /* --- Open log file --- */
    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("Vibration sensor reader started. Logging to %s. Press Ctrl+C to stop.\n",
           LOG_FILE);

    /* --- Main sampling loop --- */
    while (g_running) {
        if (d7s_read_data(fd, &x, &y, &z) == 0) {
            if (log_data(fp, x, y, z) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed; skipping sample.\n");
        }

        /* Sleep 100 ms, but wake early on signal */
        for (int i = 0; i < SAMPLE_PERIOD_US / 100000 && g_running; i++)
            usleep(100000);
    }

    printf("\nShutting down cleanly...\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fp) {
        fclose(fp);
    }
    if (fd >= 0) {
        close(fd);
    }
    return rc;
}

