                SENSOR_ADDR, strerror(errno));
        goto cleanup;
    }

    /* --- Open log file --- */
    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("Vibration sensor reader started. Logging to %s. Press Ctrl+C to stop.\n",
           LOG_FILE);

    /* --- Main sampling loop --- */
    while (g_running) {
        if (d7s_read_data(fd, &x, &y, &z) == 0) {
            if (log_data(fp, x, y, z) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed; skipping sample.\n");
        }

        /* Sleep 100 ms, but wake early on signal */
        for (int i = 0; i < SAMPLE_PERIOD_US / 100000 && g_running; i++)
            usleep(100000);
    }

    printf("\nShutting down cleanly...\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fp) {
        fclose(fp);
    }
    if (fd >= 0) {
        close(fd);
    }
    return rc;
}

