 * Conveyor Hall-Effect Sensor Monitor for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   - DRV5032 Hall-Effect sensor 1: GPIO17 (BCM), internal pull-up enabled
 *   - DRV5032 Hall-Effect sensor 2: GPIO27 (BCM), internal pull-up enabled
 *
 * Build: gcc -O2 -Wall -o conveyor_monitor conveyor_monitor.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_HALL1 17
#define GPIO_HALL2 27
#define LOG_FILE "conveyor_log.txt"
#define SAMPLE_INTERVAL_US 50000   /* 50 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single DRV5032 Hall-Effect sensor.
 * Returns 0 (logic 1) or -1 (error).
 */
static int read_hall_sensor(int gpio)
{
    int val = gpioRead(gpio);
    if (val < 0) {
        fprintf(stderr, "Error: gpioRead failed on GPIO %d: %s\n",
                gpio, pigpio_error(val));
        return -1;
    }
    return val;
}

/*
 * Log the current state of both sensors to the log file.
 * Returns 0 on success, -1 on error.
 */
static int log_sensor_states(void)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    time_t rawtime = time(NULL);
    if (rawtime == (time_t)-1) {
        fprintf(stderr, "Error: time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm timeinfo;
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Hall1: %d, Hall2: %d\n",
                timestamp, read_hall_sensor(GPIO_HALL1),
                read_hall_sensor(GPIO_HALL2)) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed: %s\n",
                strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error: fclose() on log file failed: %s\n",
                strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed: %s\n",
                strerror(errno));
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins as inputs with internal pull-ups */
    if (gpioSetMode(GPIO_HALL1, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n",
                GPIO_HALL1);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GPIO_HALL2, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n",
                GPIO_HALL2);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(GPIO_HALL1, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for GPIO %d\n",
                GPIO_HALL1);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(GPIO_HALL2, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for GPIO %d\n",
                GPIO_HALL2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Conveyor Hall-Effect Monitor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int hall1 = read_hall_sensor(GPIO_HALL1);
        int hall2 = read_hall_sensor(GPIO_HALL2);

        if (hall1 < 0 || hall2 < 0) {
            fprintf(stderr, "Warning: sensor read error, skipping sample\n");
        } else {
            if (hall1 == 1 && hall2 == 1) {
                printf("Conveyor halted by user.\n");
                fflush(stdout);
                /*
                 * Simulate a halt by printing a message and halting the
                 * program. This is a safety measure to prevent the
                 * conveyor from running indefinitely in case of a
                 * transient error.
                 */
                printf("HALT: Conveyor halted due to Hall-Effect sensor 1 and 2.\n");
                fflush(stdout);
                fflush(stderr);
                gpioDelay(100000); /* 100 ms */
                printf("HALT: Conveyor halted.\n");
                fflush(stdout);
                fflush(stderr);
            }
        }

        if (log_sensor_states() != 0) {
            fprintf(stderr, "Warning: failed to log sensor states.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

