/*
 * MMA8452Q 3-axis accelerometer monitor on Raspberry Pi 4 Model B.
 *
 * Reads six data registers (X, Y, Z) in a single block read,
 * right-shifts each axis by 4 bits to obtain signed 12-bit values,
 * computes absolute tilt (X + Y + Z), and logs a line to
 * fall_log.txt when a tilt > 45 degrees is detected.
 *
 * Build:  gcc -O2 -Wall -o mma8452q_monitor mma8452q_monitor.c
 * Run:    ./mma8452q_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MMA8452Q_ADDR  0x53
#define WHO_AM_I       0x75
#define WHO_AM_I_VAL   0x77
#define CTRL_REG1      0x6B
#define DATA_RATE_HZ   100
#define TILT_THRESHOLD 45
#define LOG_FILE       "fall_log.txt"
#define POLL_INTERVAL  10   /* microseconds */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* MMA8452Q identity verification                                     */
/* ------------------------------------------------------------------ */
static int verify_mma8452q(int fd)
{
    uint8_t who_am_i = 0;
    if (i2c_read_block(fd, WHO_AM_I, &who_am_i, 1) != 0)
        return -1;
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "MMA8452Q WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, WHO_AM_I_VAL);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Data acquisition                                                    */
/* ------------------------------------------------------------------ */
static int read_mma8452q(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t data[6];
    if (i2c_read_block(fd, DATA_RATE_HZ, data, 6) != 0)
        return -1;

    *x = (int16_t)((data[0] << 8) | data[1]);
    *y = (int16_t)((data[2] << 8) | data[3]);
    *z = (int16_t)((data[4] << 8) | data[5]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Tilt detection                                                      */
/* ------------------------------------------------------------------ */
static int detect_tilt(int16_t x, int16_t y, int16_t z)
{
    int16_t raw_x = x;
    int16_t raw_y = y;
    int16_t raw_z = z;

    int16_t x_raw = raw_x >> 4;
    int16_t y_raw = raw_y >> 4;
    int16_t z_raw = raw_z >> 4;

    int16_t x_signed = x_raw & 0x0F00;
    int16_t y_signed = y_raw & 0x0F00;
    int16_t z_signed = z_raw & 0x0F00;

    int16_t x_diff = x_signed - raw_x;
    int16_t y_diff = y_signed - raw_y;
    int16_t z_diff = z_signed - raw_z;

    int16_t x_abs = x_diff >> 4;
    int16_t y_abs = y_diff >> 4;
    int16_t z_abs = z_diff >> 4;

    if (x_abs > TILT_THRESHOLD || x_abs < -TILT_THRESHOLD)
        return 1;
    if (y_abs > TILT_THRESHOLD || y_abs < -TILT_THRESHOLD)
        return 1;
    if (z_abs > TILT_THRESHOLD || z_abs < -TILT_THRESHOLD)
        return 1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_tilt(int16_t x, int16_t y, int16_t z)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (fprintf(g_log_fp, "%s, X: %d, Y: %d, Z: %d\n",
                ts, x, y, z) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return;
    }
    if (fflush(g_log_fp) != 0)
        fprintf(stderr, "fflush log failed: %s\n", strerror(errno));
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open %s failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MMA8452Q_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                MMA8452Q_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (verify_mma8452q(g_i2c_fd) != 0) {
        fprintf(stderr, "MMA8452Q not detected at 0x%02X\n", MMA8452Q_ADDR);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen %s failed: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "Timestamp,X,Y,Z\n");
        fflush(g_log_fp);
    }

    printf("MMA8452Q monitoring started. Logging to %s every %d ms.\n",
           LOG_FILE, POLL_INTERVAL);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int16_t x, y, z;
        if (read_mma8452q(g_i2c_fd, &x, &y, &z) == 0) {
            int16_t x_raw = x >> 4;
            int16_t y_raw = y >> 4;
            int16_t z_raw = z >> 4;

            int16_t x_signed = x_raw & 0x0F00;
            int16_t y_signed = y_raw & 0x0F00;
            int16_t z_signed = z_raw & 0x0F00;

            int16_t x_diff = x_signed - raw_x;
            int16_t y_diff = y_signed - raw_y;
            int16_t z_diff = z_signed - raw_z;

            int16_t x_abs = x_diff >> 4;
            int16_t y_abs = y_diff >> 4;
            int16_t z_abs = z_diff >> 4;

            int16_t x_diff_signed = x_signed - raw_x;
            int16_t y_diff_signed = y_signed - raw_y;
            int16_t z_diff_signed = z_signed - raw_z;

            int16_t x_abs_signed = x_abs >> 4;
            int16_t y_abs_signed = y_abs >> 4;
            int16_t z_abs_signed = z_abs >> 4;

            if (detect_tilt(x_abs_signed, y_abs_signed, z_abs_signed) == 1) {
                log_tilt(x, y, z);
            }
        } else {
            fprintf(stderr, "I2C read failed; skipping this sample.\n");
        }

        usleep(POLL_INTERVAL * 1000);
    }

    printf("\nShutting down cleanly.\n");
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

