/*
 * ADIS16362 IMU reader for Raspberry Pi Zero W
 * SPI: CE0 (GPIO8), 1 MHz, Mode 3, 16-bit read protocol
 * Logs timestamped gyro/accel data to imu_log.csv
 *
 * Build: gcc -O2 -Wall -o imu_reader imu_reader.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_MODE        SPI_MODE_3
#define SPI_BITS        8
#define SPI_BITS_PER_WORD 8
#define SPI_DELAY_US    0
#define SAMPLE_DELAY_US 10000  /* 10 ms between samples */
#define LOG_FILE        "imu_log.csv"
#define GYRO_SCALE      0.05f
#define ACCEL_SCALE     0.0025f
#define MAX_RETRIES     3

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                          */
/* ------------------------------------------------------------------ */
static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_WR_MODE): %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_WR_BITS_PER_WORD): %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_WR_MAX_SPEED_HZ): %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

static int spi_read_reg(uint8_t reg, uint8_t *buf, size_t len)
{
    if (len > 1) {
        fprintf(stderr, "spi_read_reg: len=%zu (expected 1)\n", len);
        return -1;
    }

    uint8_t tx[2] = { reg, 0x00 };
    uint8_t rx[2] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 2,
        .speed_hz      = SPI_SPEED_HZ,
        .delay_usecs   = SPI_DELAY_US,
        .bits_per_word = SPI_BITS,
        .cs_change     = 0,
    };

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_MESSAGE): %s\n", strerror(errno));
        return -1;
    }

    memcpy(buf, rx, len);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Gyroscope                                                            */
/* ------------------------------------------------------------------ */
static int read_gyro(float *gyro_out)
{
    uint8_t buf[2];
    if (spi_read_reg(0x00, buf, 2) < 0)
        return -1;

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *gyro_out = (float)raw * GYRO_SCALE;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Accelerometer                                                       */
/* ------------------------------------------------------------------ */
static int read_accel(float *accel_out)
{
    uint8_t buf[2];
    if (spi_read_reg(0x01, buf, 2) < 0)
        return -1;

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *accel_out = (float)raw * ACCEL_SCALE;
    return 0;
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                          */
/* ------------------------------------------------------------------ */
static int log_data(float gyro_x, float gyro_y, float gyro_z,
                    float accel_x, float accel_y, float accel_z)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n",
                timestamp, gyro_x, gyro_y, gyro_z,
                accel_x, accel_y, accel_z) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(g_log_fp, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");
    fflush(g_log_fp);

    printf("ADIS16362 IMU reader started. Logging to %s. Press Ctrl-C to stop.\n",
           LOG_FILE);

    while (g_running) {
        float gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

        if (read_gyro(&gyro_x) < 0) {
            fprintf(stderr, "Gyro read failed; skipping sample\n");
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        if (read_accel(&accel_x) < 0) {
            fprintf(stderr, "Accel read failed; skipping sample\n");
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        if (log_data(gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z) < 0) {
            fprintf(stderr, "Logging failed; continuing\n");
        }

        usleep(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

