/*
 * Raspberry Pi 5 - E18-D80NK IR Obstacle Sensor Reader
 *
 * Reads the E18-D80NK IR obstacle sensor on GPIO17 (BCM) once per second.
 * When the sensor reports a LOW level (obstacle detected), logs a message
 * to the console and triggers a simulated self-parking sequence.
 *
 * Build: gcc -O2 -Wall -o e18_d80nk e18_d80nk.c
 * Run:   sudo ./e18_d80nk
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <stdbool.h>

#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip4"
#define GPIO_LINE_OFFSET 17
