/*
 * KY-032 IR obstacle-avoidance sensor reader for Raspberry Pi 3 Model B+.
 *
 * Wiring:
 *   KY-032 VCC  -> 3.3 V (pin 1)
 *   KY-032 GND  -> GND  (pin 6)
 *   KY-032 OUT  -> GPIO17 (physical pin 11)
 *   KY-032 IN   -> GPIO27 (physical pin 13)
 *
 * The KY-032 outputs a logic-level signal: 0 = obstacle detected, 1 = path
 * clear.  The bulk-read API returns a single byte that is interpreted as
 * a single bit: 0 = obstacle, 1 = clear.
 *
 * Build:  gcc -O2 -Wall -Wextra -o ky032_reader ky032_reader.c
 * Run:    sudo ./ky032_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_PIN  17
#define SENSOR2_PIN  27
#define SAMPLE_US    100000   /* 100 ms */
#define POLL_US      SAMPLE_US * 3 /* 3 samples per poll */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        snprintf(buf, len, "UNKNOWN");
        return;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        snprintf(buf, len, "UNKNOWN");
        return;
    }
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
}

/* ------------------------------------------------------------------ */
/* KY-032 bulk-read                                                     */
/* ------------------------------------------------------------------ */
static int read_sensors(int sensor1, int sensor2)
{
    char ts[32];
    int raw1 = gpioRead(sensor1);
    int raw2 = gpioRead(sensor2);

    if (raw1 < 0 || raw2 < 0) {
        fprintf(stderr, "Error: gpioRead failed on GPIO%d or GPIO%d\n",
                sensor1, sensor2);
        return -1;
    }

    /* KY-032 outputs a logic-level signal: 0 = obstacle, 1 = clear. */
    int obstacle = (raw1 == 0) ? 1 : 0;
    int clear   = (raw2 == 0) ? 1 : 0;

    get_timestamp(ts, sizeof(ts));
    printf("[%s] Sensor1: %s  Sensor2: %s\n", ts,
           obstacle ? "Obstacle detected" : "Path clear",
           clear ? "Clear" : "Obstacle");
    fflush(stdout);

    return (obstacle || clear) ? 0 : -1;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n",
                gpioInitialise());
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins as inputs --- */
    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO%d\n",
                SENSOR1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO%d\n",
                SENSOR2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Allow sensor to settle after power-up --- */
    gpioDelay(100000);  /* 100 ms */

    /* --- Bulk-read: read both lines together --- */
    int result = read_sensors(SENSOR1_PIN, SENSOR2_PIN);

    /* --- Release pigpio resources on exit --- */
    gpioTerminate();

    if (result < 0) {
        fprintf(stderr, "Warning: read_sensors failed; continuing.\n");
    }

    if (result == 0) {
        fprintf(stderr, "Warning: sensor 1 or 2 still detects obstacle.\n");
    }

    return (result == 0) ? EXIT_SUCCESS : EXIT_FAILURE;
}

