code:
/*
 * ADIS16266 Gyroscope reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADIS16266 VDD  -> 3.3 V (Pin 1)
 *   ADIS16266 VREF -> 3.3 V (Pin 1)
 *   ADIS16266 GND  -> GND
 *   ADIS16266 SDA  -> GPIO2 / SPI0 SCLK (Pin 3)
 *   ADIS16266 SCL  -> GPIO3 / SPI0 MISO (Pin 5)
 *   ADIS16266 CS    -> GPIO8 / SPI0 CE0 (Pin 24)
 *
 * Build:  gcc -O2 -Wall -o adis16266_gyro adis16266_gyro.c
 * Run:    sudo ./adis16266_gyro
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE        "/dev/spidev0.0"
#define SPI_SPEED_HZ      1000000U
#define SPI_MODE          SPI_MODE_3
#define SPI_BITS_PER_WORD 8U
#define SPI_BITS_PER_WORD_8BIT 8U
#define SAMPLE_PERIOD_US  100000U   /* 100 ms */
#define GYRO_SCALE_FACTOR 0.02f   /* deg/sec per LSB */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */

static int spi_open(const char *device, uint32_t speed_hz, uint8_t mode,
                    uint8_t bits_per_word)
{
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", device, strerror(errno));
        return -1;
    }

    uint8_t mode_val = (uint8_t)(mode & 0x07);
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_val) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_WR_MODE): %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits_per_word_val = (uint8_t)(bits_per_word & 0x07);
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_per_word_val) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_WR_BITS_PER_WORD): %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed_val = (uint32_t)(speed_hz / 1000000U);
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_val) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_WR_MAX_SPEED_HZ): %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * Read a 2-byte transfer from the ADIS16266.
 * The first byte is the address byte (MSB first), followed by the 2-byte
 * data.  The ADIS16266 returns the data in little-endian format.
 */
static int spi_read_two_bytes(int fd, uint8_t *buf, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = NULL;
    tr.rx_buf = buf;
    tr.len = len;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS_PER_WORD;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_MESSAGE): %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a single byte from the ADIS16266.
 * The ADIS16266 returns the data in little-endian format.
 */
static int spi_read_byte(int fd, uint8_t *buf)
{
    return spi_read_two_bytes(fd, buf, 1);
}

/* ------------------------------------------------------------------ */
/* Gyroscope data                                                       */
/* ------------------------------------------------------------------ */

typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

static int read_gyro_data(int fd, gyro_data_t *data)
{
    uint8_t buf[3];

    if (spi_read_two_bytes(fd, buf, sizeof(buf)) < 0) {
        return -1;
    }

    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    data->x = (float)raw_x * GYRO_SCALE_FACTOR;
    data->y = (float)raw_y * GYRO_SCALE_FACTOR;
    data->z = (float)raw_z * GYRO_SCALE_FACTOR;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                 */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open SPI device */
    int spi_fd = spi_open(SPI_DEVICE, SPI_SPEED_HZ, SPI_MODE, SPI_BITS_PER_WORD);
    if (spi_fd < 0) {
        return EXIT_FAILURE;
    }

    /* Open console for logging */
    FILE *log_fp = fopen("gyro_data.log", "a");
    if (!log_fp) {
        fprintf(stderr, "fopen(gyro_data.log): %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    printf("ADIS16266 gyroscope reader started.  Press Ctrl+C to exit.\n");

    while (g_running) {
        gyro_data_t gyro_data;

        if (read_gyro_data(spi_fd, &gyro_data) < 0) {
            fprintf(stderr, "SPI read error; continuing.\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        printf("X: %.3f deg/s, Y: %.3f deg/s, Z: %.3f deg/s\n",
               gyro_data.x, gyro_data.y, gyro_data.z);

        if (fprintf(log_fp, "X: %.3f deg/s, Y: %.3f deg/s, Z: %.3f deg/s\n",
