/*
 * LSM6DSR IMU reader for Raspberry Pi 3 Model B+
 * Uses pigpio for I2C communication.
 *
 * Wiring:
 *   LSM6DSR SDA -> GPIO 2 (I2C1 SDA)
 *   LSM6DSR SCL -> GPIO 3 (I2C1 SCL)
 *   LSM6DSR VDD -> 3.3 V
 *   LSM6DSR GND -> GND
 *
 * Build: gcc -O2 -Wall -o imu_reader imu_reader.c -lpigpio -lrt
 * Run:   sudo ./imu_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define LSM6DSR_ADDR   0x6B
#define WHO_AM_I       0x0F
#define WHO_AM_I_VAL   0x18
#define ACCEL_XOUT_H   0x1C
#define GYRO_XOUT_H    0x20

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "I2C block read failed (reg 0x%02X, len %u): %d\n",
                reg, len, rc);
        return -1;
    }
    if (rc != (uint32_t)len) {
        fprintf(stderr, "I2C block read short: got %d bytes, expected %u\n",
                rc, len);
        return -1;
    }
    return 0;
}

static int lsm6dsr_init(int handle)
{
    uint8_t who_am_i = 0;
    if (i2c_read_reg(handle, WHO_AM_I, &who_am_i) != 0)
        return -1;
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, WHO_AM_I_VAL);
        return -1;
    }

    if (i2c_write_reg(handle, 0x00, 0x00) != 0)
        return -1;
    if (i2c_write_reg(handle, 0x01, 0x00) != 0)
        return -1;
    if (i2c_write_reg(handle, 0x02, 0x00) != 0)
        return -1;
    if (i2c_write_reg(handle, 0x03, 0x00) != 0)
        return -1;
    if (i2c_write_reg(handle, 0x04, 0x00) != 0)
        return -1;
    if (i2c_write_reg(handle, 0x05, 0x00) != 0)
        return -1;
    if (i2c_write_reg(handle, 0x06, 0x00) != 0)
        return -1;
    if (i2c_write_reg(handle, 0x07, 0x00) != 0)
        return -1;
    if (i2c_write_reg(handle, 0x08, 0x00) != 0)
        return -1;
    if (i2c_write_reg(handle, 0x09, 0x00) != 0)
        return -1;
    if (i2c_write_reg(handle, 0x0A, 0x00) != 0)
        return -1;
    if (i2c_write_reg(handle, 0x0B, 0x00) != 0)
        return -1;
    if (i2c_write_reg(handle, 0x0C, 0x00) != 0)
        return -1;
    if (i2c_write_reg(handle, 0x0D, 0x00) != 0)
        return -1;
    if (i2c_write_reg(handle, 0x0E, 0x00) != 0)
        return -1;
    if (i2c_write_reg(handle, 0x0F, 0x00) != 0)
        return -1;

    return 0;
}

static int lsm6dsr_read_accel(int handle, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (i2c_read_block(handle, ACCEL_XOUT_H, buf, 6) != 0)
        return -1;

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static int lsm6dsr_read_gyro(int handle, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (i2c_read_block(handle, GYRO_XOUT_H, buf, 6) != 0)
        return -1;

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, LSM6DSR_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, LSM6DSR_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (lsm6dsr_init(g_i2c_handle) != 0) {
        fprintf(stderr, "LSM6DSR initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("LSM6DSR IMU reader started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int16_t ax, ay, az, gx, gy, gz;

        if (lsm6dsr_read_accel(g_i2c_handle, &ax, &ay, &az) != 0) {
            fprintf(stderr, "Error reading accelerometer data\n");
            break;
        }
        if (lsm6dsr_read_gyro(g_i2c_handle, &gx, &gy, &gz) != 0) {
            fprintf(stderr, "Error reading gyroscope data\n");
            break;
        }

        printf("Accel: %d %d %d  Gyro: %d %d %d\n",
               ax, ay, az, gx, gy, gz);
        fflush(stdout);

        gpioDelay(100000); /* 100 ms */
    }

    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

