/*
 * FXOS8700 accelerometer + magnetometer reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   FXOS8700 SDA  -> GPIO2 (BCM)  -> I2C bus 1 SDA
 *   FXOS8700 SCL  -> GPIO3 (BCM)  -> I2C bus 1 SCL
 *   FXOS8700 VDD  -> 3.3 V
 *   FXOS8700 GND  -> GND
 *
 * The FXOS8700 has a 16-bit identification register at 0x00.
 * The documented value is 0x0C.
 *
 * Build:  gcc -O2 -Wall -Wextra -o fxos8700 fxos8700.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define FXOS8700_ADDR  0x6B

#define FXOS8700_ID_REG  0x00
#define FXOS8700_ID_VAL  0x0C

#define FXOS8700_REG_ACCEL_XOUT_H 0x2C
#define FXOS8700_REG_MAG_XOUT_H  0x3E

#define ACCEL_XOUT_H_LEN 6
#define MAG_XOUT_H_LEN 6

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
