/*
 * KY-038 sound sensor monitor for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   KY-038 OUT -> GPIO17 (BCM 17, physical pin 11)
 *   KY-038 VCC -> 3.3 V (pin 1)
 *   KY-038 GND -> GND  (pin 9)
 *
 * Build:  gcc -O2 -Wall -Wextra -o ky038_monitor ky038_monitor.c
 * Run:    ./ky038_monitor <threshold>
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_LINE_OFFSET 17          /* BCM 17, physical pin 11 */
#define SAMPLE_INTERVAL_US 1000000 /* 1 ms */
#define WINDOW_DURATION_US  5000000 /* 5 seconds */
#define POLL_INTERVAL_US    100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Print a timestamped alert or status line to stdout.
 * Returns 0 on success, -1 on error.
 */
static int print_alert_or_status(int gpio_line, int threshold)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    printf("[%s] ALERT: Count of high readings (%d) exceeds threshold (%d)!\n",
           timestamp, gpio_line, threshold, threshold);
    fflush(stdout);
    return 0;
}

int main(int argc, char *argv[])
{
    int threshold = -1;
    int ret = EXIT_FAILURE;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return EXIT_FAILURE;
    }

    if (sscanf(argv[1], "%d", &threshold) != 1) {
        fprintf(stderr, "Invalid threshold format. Use: <threshold> (e.g., 10)\n");
        return EXIT_FAILURE;
    }

    if (threshold <= 0 || threshold > 100) {
        fprintf(stderr, "Threshold must be between 1 and 100 (inclusive).\n");
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as input */
    if (gpiod_line_request_input(line, "ky038_monitor") < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Monitoring KY-038 sound sensor on GPIO%d (BCM). Threshold: %d\n",
           GPIO_LINE_OFFSET, threshold);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    int window_start = 0;
    int window_end = 0;
    int window_count = 0;

    while (g_running) {
        int high_count = 0;

        for (int i = 0; i < WINDOW_DURATION_US / SAMPLE_INTERVAL_US && g_running; i++) {
            int val = gpiod_line_get_value(line);
            if (val < 0) {
                fprintf(stderr, "Failed to read GPIO line %d: %s\n",
                        GPIO_LINE_OFFSET, strerror(errno));
                break;
            }
            high_count += (val == 1);
            usleep(SAMPLE_INTERVAL_US);
        }

        if (g_running) {
            if (high_count > threshold) {
                if (print_alert_or_status(GPIO_LINE_OFFSET, threshold) == 0) {
                    window_count++;
                }
            } else {
                window_count = 0;
            }

            if (window_count >= WINDOW_DURATION_US / POLL_INTERVAL_US) {
                window_end = 1;
                window_start = (window_end - window_count) + 1;
                window_count = 0;
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return ret;
}

