#define POLL_TIMEOUT  5
#define ENTRY_DELAY   5
#define UNLOCK_TIME   5
#define MAX_CODE      60000

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int init_gpio(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line_a = NULL;
    struct gpiod_line *line_b = NULL;
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip0\")");
        return -1;
    }

    line_a = gpiod_chip_get_line(chip, DOOR_A_GPIO);
    if (!line_a) {
        perror("gpiod_chip_get_line(DOOR_A)");
        gpiod_chip_close(chip);
        return -1;
    }

    line_b = gpiod_chip_get_line(chip, DOOR_B_GPIO);
    if (!line_b) {
        perror("gpiod_chip_get_line(DOOR_B)");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(line_a, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(DOOR_A)");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(line_b, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(DOOR_B)");
        gpiod_line_release(line_a);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

