/*
 * LSM303DLHC magnetometer reader for Raspberry Pi Zero W
 * Uses pigpio for I2C and hardware PWM.
 *
 * Wiring:
 *   LSM303DLHC SDA -> GPIO2 (I2C1 SDA)
 *   LSM303DLHC SCL -> GPIO3 (I2C1 SCL)
 *   LSM303DLHC VDD -> 3.3 V
 *   LSM303DLHC GND -> GND
 *   LED anode -> GPIO17 (BCM 17)
 *   LED cathode -> GND
 *
 * Build: gcc -Wall -Wextra -O2 -o lsm303_led lsm303_led.c -lpigpio -lrt
 * Run:   sudo ./lsm303_led
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x68          /* LSM303DLHC default address */
#define LED_GPIO       17
#define SAMPLE_US      100000       /* 100 ms */
#define LOG_FILE       "magnetometer.log"

/* LSM303DLHC register addresses */
#define REG_CTRL_REG1   0x20
#define REG_CTRL_REG2   0x21
#define REG_OUT_X_L     0x28
#define REG_OUT_X_H     0x29
#define REG_OUT_Y_L     0x2A
#define REG_OUT_Y_H     0x2B
#define REG_OUT_Z_L     0x2C
#define REG_OUT_Z_H     0x2D

/* CTRL_REG1: ODR=100Hz, MUX=0 (Z-axis) */
#define CTRL_REG1_VAL   0x0C

/* CTRL_REG2: POWER_DOWN=0, ODR=100Hz, MUX=0 (Z-axis) */
#define CTRL_REG2_VAL   0x0C

/* CTRL_REG1 bits: Z_AXIS_EN=1, ODR_EN=1, POWER_DOWN=0 */
#define CTRL_REG1_BIT   0x08

/* CTRL_REG2 bits: Z_AXIS_EN=1, ODR_EN=1, POWER_DOWN=0 */
#define CTRL_REG2_BIT   0x08

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_error(const char *msg)
{
    if (!g_log_fp) return;
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];
    localtime_r(&t, &tm);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(g_log_fp, "[%s] ERROR: %s\n", ts, msg);
    fflush(g_log_fp);
}

static int i2c_write_reg(uint8_t reg, uint8_t val)
{
    char buf[2] = { (char)reg, (char)val };
    if (i2cWriteDevice(g_i2c_handle, buf, 2) != 2) {
        log_error("I2C write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_reg(uint8_t reg, uint8_t *val)
{
    if (i2cWriteDevice(g_i2c_handle, (char *)&reg, 1) != 1) {
        log_error("I2C write (reg select) failed");
        return -1;
    }
    if (i2cReadDevice(g_i2c_handle, (char *)val, 1) != 1) {
        log_error("I2C read failed");
        return -1;
    }
    return 0;
}

static int init_magnetometer(void)
{
    /* Power down */
    if (i2c_write_reg(REG_CTRL_REG1, CTRL_REG1_VAL) != 0)
        return -1;
    gpioDelay(10000); /* 10 ms */

    /* Enable magnetometer (Z-axis) */
    if (i2c_write_reg(REG_CTRL_REG2, CTRL_REG2_VAL) != 0)
        return -1;
    gpioDelay(10000); /* 10 ms */

    return 0;
}

static int read_magnetometer(float *z_out)
{
    uint8_t buf[6];
    int rc;

    /* Block read: 6 bytes starting at OUT_X_L */
    rc = i2cReadDevice(g_i2c_handle, (char *)buf, 6);
    if (rc != 6) {
        log_error("I2C block read failed");
        return -1;
    }

    /* LSM303DLHC: Z-axis data is in OUT_X_L..OUT_X_H, little-endian */
    int16_t z_raw = (int16_t)((buf[0] << 8) | buf[1]);
    *z_out = (float)z_raw;
    return 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_magnetometer() != 0) {
        log_error("Magnetometer initialization failed");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        log_error("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Magnetometer reader started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float z_out;
        if (read_magnetometer(&z_out) == 0) {
            printf("Z-axis: %.2f\n", z_out);
            gpioPWM(LED_GPIO, (int)z_out);
        } else {
            log_error("Failed to read magnetometer");
        }
        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

