code:
/*
 * lsm303d_mon.c — LSM303D accelerometer/magnetometer monitor for Raspberry Pi Zero W
 *
 * Reads acceleration data from an LSM303D over I2C at roughly 10 ms intervals,
 * stores each sample in a 64-entry circular buffer, and dumps the last ten
 * buffered samples to the console on a rising edge of the INT1 pin (BCM GPIO 23,
 * physical pin 16).  On SIGINT (Ctrl+C), the accelerometer is disabled by writing
 * the documented value to the control register.
 *
 * Build:  gcc -O2 -Wall -Wextra -o lsm303d_mon lsm303d_mon.c -lgpiod
 * Run:    sudo ./lsm303d_mon
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS          "/dev/i2c-1"
#define LSM303D_ADDR     0x6B
#define INT1_PIN         23
#define BUFFER_SIZE      64
#define SENSITIVITY_MG   0.061f   /* LSM303D sensitivity: mg/LSB */
#define INT1_THRESHOLD   2000      /* mg  */
#define SAMPLE_INTERVAL  10000     /* microseconds */

/* LSM303D register addresses */
#define REG_DEVID        0x00
#define REG_CTRL_REG1    0x1B
#define REG_CTRL_REG2    0x1C
#define REG_OUT_X_L      0x32
#define REG_OUT_X_H      0x33
#define REG_OUT_Y_L      0x34
#define REG_OUT_Y_H      0x35
#define REG_OUT_Z_L      0x36
#define REG_OUT_Z_H      0x37

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint8_t reg, uint16_t *val)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Circular buffer                                                     */
/* ------------------------------------------------------------------ */

typedef struct {
    float  x[BUFFER_SIZE];
    float  y[BUFFER_SIZE];
    float  z[BUFFER_SIZE];
    int    head;
    int    count;
} circular_buffer_t;

static void cb_init(circular_buffer_t *cb)
{
    cb->head = 0;
    cb->count = 0;
}

static void cb_add(circular_buffer_t *cb, float x, float y, float z)
{
    cb->x[cb->head] = x;
    cb->y[cb->head] = y;
    cb->z[cb->head] = z;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

static void cb_dump(const circular_buffer_t *cb)
{
    printf("Last %d samples:\n", cb->count);
    for (int i = 0; i < cb->count; i++) {
        float x = cb->x[i];
        float y = cb->y[i];
        float z = cb->z[i];
        printf("  X: %.3f mg, Y: %.3f mg, Z: %.3f mg\n",
               x * SENSITIVITY_MG, y * SENSITIVITY_MG, z * SENSITIVITY_MG);
    }
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* LSM303D initialization                                              */
/* ------------------------------------------------------------------ */

static int lsm303d_init(int fd)
{
    uint8_t devid;
    if (i2c_read_byte(fd, REG_DEVID, &devid) != 0) {
        fprintf(stderr, "Cannot read DEVID; sensor may not be present.\n");
        return -1;
    }
    if (devid != 0x6B) {
        fprintf(stderr, "DEVID mismatch: got 0x%02X, expected 0x6B.\n", devid);
        return -1;
    }

    /* Control register: 0x1B = 0x1B = enable accelerometer, magnetometer,
     * and temperature. */
    if (i2c_write_byte(fd, REG_CTRL_REG1, 0x1B) != 0)
        return -1;

    /* Control register: 0x1C = 0x00 = no interrupts, zero duration. */
    if (i2c_write_byte(fd, REG_CTRL_REG2, 0x00) != 0)
        return -1;

