#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define SOLENOID1_PIN 17
#define SOLENOID2_PIN 27
#define POLL_INTERVAL_US 500000  /* 500 ms */
#define POLL_TIMEOUT_US 1000000 /* 1 s */

static volatile sig_atomic_t g_terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n", gpioInitialise());
        return -1;
    }

    if (gpioSetMode(SOLENOID1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", SOLENOID1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(SOLENOID2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", SOLENOID2_PIN);
        gpioTerminate();
        return -1;
    }

    /* Ensure both lines are initially LOW */
    if (gpioWrite(SOLENOID1_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to write GPIO %d LOW.\n", SOLENOID1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(SOLENOID2_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to write GPIO %d LOW.\n", SOLENOID2_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    /* Ensure solenoids are off before releasing pigpio resources */
    gpioWrite(SOLENOID1_PIN, 0);
    gpioWrite(SOLENOID2_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Solenoid control started. Press Ctrl+C to exit.\n");

    while (!g_terminate) {
        /* Switch active line every 500 ms */
        if (gpioWrite(SOLENOID1_PIN, 1) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d HIGH.\n", SOLENOID1_PIN);
            break;
        }
        if (gpioDelay(POLL_INTERVAL_US) != 0) {
            fprintf(stderr, "Error: gpioDelay failed.\n");
            break;
        }

        if (gpioWrite(SOLENOID2_PIN, 1) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d HIGH.\n", SOLENOID2_PIN);
            break;
        }
        if (gpioDelay(POLL_INTERVAL_US) != 0) {
            fprintf(stderr, "Error: gpioDelay failed.\n");
            break;
        }

        /* Ensure both lines are LOW before the next cycle */
        if (gpioWrite(SOLENOID1_PIN, 0) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d LOW.\n", SOLENOID1_PIN);
            break;
        }
        if (gpioWrite(SOLENOID2_PIN, 0) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d LOW.\n", SOLENOID2_PIN);
            break;
        }
    }

    cleanup_gpio();
    printf("Solenoid control stopped.\n");
    return EXIT_SUCCESS;
}

