/*
 * Dual-factor door-lock authentication using two UART ports.
 *
 * Hardware:
 *   - Raspberry Pi 4 Model B
 *   - Two 12 V electromechanical door locks (relays driven by GPIO17 and GPIO27)
 *   - Primary UART on GPIO14/15 (9600 8N1)
 *   - Secondary UART on GPIO27 (9600 8N1)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o door_lock door_lock.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./door_lock
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <pigpio.h>

#define UART_PORT_1 "/dev/serial0"
#define UART_PORT_2 "/dev/serial1"
#define EXPECTED_CODE "123456"
#define READ_TIMEOUT_US 50000   /* 50 ms per port */
#define LOCK_DURATION_US 2000000 /* 2 s per port */
#define READ_TIMEOUT_US_PER_PORT 50000
#define MAX_RETRIES 3

static volatile sig_atomic_t g_running = 1;
static int g_port1 = -1;
static int g_port2 = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    /*
     * BCM numbering:
     *   GPIO17 = 17, GPIO27 = 27, GPIO14/15 = 14/15
     */
    if (gpioSetMode(17, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO17 (BCM 17) as output.\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(27, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO27 (BCM 27) as output.\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(14, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO14 (BCM 14) as output.\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(15, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO15 (BCM 15) as output.\n");
        gpioTerminate();
        return -1;
    }

    /* Ensure both relays are LOW initially */
    if (gpioWrite(17, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize GPIO17 LOW.\n");
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(27, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize GPIO27 LOW.\n");
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(14, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize GPIO14 LOW.\n");
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(15, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize GPIO15 LOW.\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void release_gpio(void)
{
    /* Ensure both relays are LOW before releasing pigpio */
