/* ------------------------------------------------------------------ */
/* UART helpers                                                        */
/* ------------------------------------------------------------------ */
static int open_uart(const char *port, uint32_t baud)
{
    int fd = open(port, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        fprintf(stderr, "Error: open(%s) failed: %s\n", port, strerror(errno));
        return -1;
    }

