     * 9600 8N1:
     *   line discipline = NONE (raw)
     *   flow control = none
     *   speed = baud
     */
    if (fcntl(fd, F_SETFL, 0) < 0) {
        fprintf(stderr, "Error: fcntl(F_SETFL) failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = baud;
    if (ioctl(fd, TIOCMGET, &speed) < 0) {
        fprintf(stderr, "Error: TIOCMGET failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (speed != baud) {
        fprintf(stderr, "Error: speed mismatch: got %u, expected %u\n",
                speed, baud);
        close(fd);
        return -1;
    }

    return fd;
