}

static void lock_door(int fd, uint8_t *buf, size_t len)
{
    if (read_lock_code(fd, buf, len) == 0) {
        printf("Door locked.\n");
        gpioWrite(17, 1);
        gpioWrite(27, 1);
        gpioDelay(LOCK_DURATION_US);
