#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define PIR_PIN 4
#define DOOR_STRIKE_PIN 17
#define POLL_INTERVAL_MS 50
#define FAILSAFE_THRESHOLD_SEC 10
#define FAILSAFE_DURATION_SEC 1
#define LOG_FILE "/var/log/pir_failsafe.log"

static volatile sig_atomic_t running = 1;
static int door_strike_line = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_message(const char *message) {
    if (!log_file) return -1;
    if (fprintf(log_file, "%s\n", message) < 0) {
        syslog(LOG_ERR, "Failed to write to log file: %s", strerror(errno));
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (door_strike_line >= 0) {
        if (gpio_set_line_value(door_strike_line, 0) < 0) {
            syslog(LOG_ERR, "Failed to de-energize relay: %s", strerror(errno));
        }
        door_strike_line = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (gpio_chip_open() < 0) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", strerror(errno));
    }
    gpio_chip_close();
    syslog(LOG_INFO, "Cleanup complete");
}

static int init_gpio(void) {
    int fd = open("/dev/gpiochip0", O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", strerror(errno));
        return -1;
    }
    if (ioctl(fd, GPIO_GET_LINE_COUNT) < 0) {
        syslog(LOG_ERR, "Failed to get GPIO line count: %s", strerror(errno));
        close(fd);
        return -1;
    }
    int lines = GPIO_GET_LINE_COUNT();
    if (lines < 0) {
        syslog(LOG_ERR, "Failed to get GPIO line count: %s", strerror(errno));
        close(fd);
        return -1;
    }
    for (int i = 0; i < lines; i++) {
        if (i == PIR_PIN) continue;
        if (i == DOOR_STRIKE_PIN) continue;
        int line = GPIO_LINE(i);
        if (gpio_set_direction(line, GPIO_INPUT) < 0) {
            syslog(LOG_ERR, "Failed to set GPIO direction: %s", strerror(errno));
            close(fd);
            return -1;
        }
        if (gpio_set_pull_up_down(line, GPIO_PUD_OFF) < 0) {
            syslog(LOG_ERR, "Failed to set pull-up/down: %s", strerror(errno));
            close(fd);
            return -1;
        }
    }
    if (ioctl(fd, GPIO_REQUEST_LINE_INPUT, PIR_PIN) < 0) {
        syslog(LOG_ERR, "Failed to request PIR line: %s", strerror(errno));
        close(fd);
        return -1;
    }
    if (ioctl(fd, GPIO_REQUEST_LINE_INPUT, DOOR_STRIKE_PIN) < 0) {
        syslog(LOG_ERR, "Failed to request door strike line: %s", strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int read_pir_sensor(void) {
    int val = gpio_get_line_value(PIR_PIN);
    if (val < 0) {
        syslog(LOG_ERR, "Failed to read PIR sensor: %s", strerror(errno));
        return -1;
    }
    return val;
}

static int read_door_strike_sensor(void) {
    int val = gpio_get_line_value(DOOR_STRIKE_PIN);
    if (val < 0) {
        syslog(LOG_ERR, "Failed to read door strike sensor: %s", strerror(errno));
        return -1;
    }
    return val;
}

static void log_event(const char *message) {
    if (!log_file) return;
    if (log_message(message) < 0) {
        syslog(LOG_ERR, "Failed to log event: %s", message);
    }
}

static void activate_door_strike(void) {
    if (door_strike_line >= 0) {
        if (gpio_set_line_value(DOOR_STRIKE_PIN, 1) < 0) {
            syslog(LOG_ERR, "Failed to activate relay: %s", strerror(errno));
            return;
        }
        log_event("Door strike relay activated");
        if (log_message("Door strike relay activated") < 0) {
            syslog(LOG_ERR, "Failed to log activation event");
        }
        sleep(1);
        if (gpio_set_line_value(DOOR_STRIKE_PIN, 0) < 0) {
            syslog(LOG_ERR, "Failed to deactivate relay: %s", strerror(errno));
        }
        log_event("Door strike relay deactivated");
        if (log_message("Door strike relay deactivated") < 0) {
            syslog(LOG_ERR, "Failed to log deactivation event");
        }
    }
}

static void failsafe_relay(void) {
    if (door_strike_line >= 0) {
        if (gpio_set_line_value(DOOR_STRIKE_PIN, 0) < 0) {
            syslog(LOG_ERR, "Failed to deactivate relay: %s", strerror(errno));
            return;
        }
        log_event("Failsafe relay deactivated");
        if (log_message("Failsafe relay deactivated") < 0) {
            syslog(LOG_ERR, "Failed to log deactivation event");
        }
    }
    if (log_message("Failsafe relay deactivated") < 0) {
        syslog(LOG_ERR, "Failed to log deactivation event");
    }
}

int main(void) {
    openlog("pir_failsafe", LOG_PID | LOG_CONS, LOG_USER);
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        closelog();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to register SIGINT handler: %s", strerror(errno));
        fclose(log_file);
        closelog();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to register SIGTERM handler: %s", strerror(errno));
        fclose(log_file);
        closelog();
        return 1;
    }

    int ret = 0;
    if (init_gpio() < 0) {
        ret = 1;
    } else {
        log_event("PIR sensor initialized");
    }

    while (running) {
        int pir = read_pir_sensor();
        if (pir < 0) {
            log_event("PIR sensor read error");
            sleep(POLL_INTERVAL_MS / 1000);
            continue;
        }

        int door_strike = read_door_strike_sensor();
        if (door_strike < 0) {
            log_event("Door strike sensor read error");
            sleep(POLL_INTERVAL_MS / 1000);
            continue;
        }

        if (pir && !door_strike) {
            log_event("Motion detected");
            if (log_message("Motion detected") < 0) {
                syslog(LOG_ERR, "Failed to log motion event");
            }
            activate_door_strike();
            if (log_message("Door strike relay activated") < 0) {
                syslog(LOG_ERR, "Failed to log activation event");
            }
        } else if (!pir && door_strike) {
            log_event("Failsafe triggered");
            if (log_message("Failsafe triggered") < 0) {
                syslog(LOG_ERR, "Failed to log failsafe event");
            }
            failsafe_relay();
            if (log_message("Failsafe relay deactivated") < 0) {
                syslog(LOG_ERR, "Failed to log deactivation event");
            }
        }

        sleep(POLL_INTERVAL_MS / 1000);
    }

    cleanup();
    return ret;
}

