static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void delay_seconds(int seconds) {
    struct timespec ts;
    ts.tv_sec = seconds;
    ts.tv_nsec = 0;
    nanosleep(&ts, NULL);
}

static int set_relay(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Error: gpioWrite failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

