/*
 * MH-Z19B CO₂ monitor for Raspberry Pi 3 Model B+
 *
 * Reads CO₂ from an MH-Z19B sensor over UART (GPIO14 TX, GPIO15 RX)
 * and logs the JSON-formatted data to co2_log.json.
 *
 * Build:  gcc -Wall -Wextra -o co2_monitor co2_monitor.c -lthe_driver_library -lrt
 * Run:    ./co2_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/serial.h>
#include <linux/serial_core.h>
#include <linux/serial_rs_core.h>

#define SERIAL_DEVICE      "/dev/serial0"
#define BAUD_RATE          B9600
#define LOG_FILE           "co2_log.json"
#define ERROR_LOG_FILE     "co2_error.log"
#define READ_INTERVAL_S    5
#define TIMEOUT_MS         1000
#define MAX_RETRIES        3

/* MH-Z19B command: 9-byte sequence */
static const uint8_t MHZ19B_CMD[9] = {
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
};

static volatile sig_atomic_t g_running = 1;
static int g_fd = -1;
static FILE *g_log_fp = NULL;
static FILE *g_err_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tmv;
    localtime_r(&now, &tmv);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tmv);
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_message(const char *msg)
{
    if (!g_log_fp)
        return;

    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(g_log_fp, "%s: %s\n", ts, msg);
    fflush(g_log_fp);
}

static void log_error(const char *msg)
{
    if (!g_err_fp)
        return;

    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(g_err_fp, "%s: %s\n", ts, msg);
    fflush(g_err_fp);
}

/* ------------------------------------------------------------------ */
/* Read one byte from the serial device                                */
/* ------------------------------------------------------------------ */
static int read_byte(void)
{
    uint8_t val;
    ssize_t n = read(g_fd, &val, 1);
    if (n != 1) {
        if (n < 0)
            log_error("read_byte: serial read error");
        else
            log_error("read_byte: short read");
        return -1;
    }
    return (int)val;
}

/* ------------------------------------------------------------------ */
/* Read exactly `len` bytes from the serial device                        */
/* ------------------------------------------------------------------ */
static int read_bytes(uint8_t *buf, size_t len)
{
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(g_fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR)
                continue;
            log_error("read_bytes: serial read error");
            return -1;
        }
        if (n == 0) {
            log_error("read_bytes: serial EOF");
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Send the MH-Z19B command                                          */
/* ------------------------------------------------------------------ */
static int send_command(void)
{
    uint8_t cmd[9] = MHZ19B_CMD;
    ssize_t n = write(g_fd, cmd, 9);
    if (n != 9) {
        if (n < 0)
            log_error("send_command: serial write error");
        else
            log_error("send_command: short write");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Parse the 9-byte response                                          */
/* ------------------------------------------------------------------ */
static int parse_response(uint8_t *data, size_t len)
{
    if (len < 9) {
        log_error("parse_response: short response");
        return -1;
    }

    /* Verify the command was received */
    if (data[0] != MHZ19B_CMD[0] || data[1] != MHZ19B_CMD[1] ||
        data[2] != MHZ19B_CMD[2] || data[3] != MHZ19B_CMD[3] ||
        data[4] != MHZ19B_CMD[4] || data[5] != MHZ19B_CMD[5] ||
        data[6] != MHZ19B_CMD[6] || data[7] != MHZ19B_CMD[7] ||
        data[8] != MHZ19B_CMD[8]) {
        log_error("parse_response: command mismatch");
        return -1;
    }

    /* Parse the 9-byte response */
    uint32_t ts_ms = ((uint32_t)data[2] << 16) |
                     ((uint32_t)data[3] << 8)  |
                     (uint32_t)data[4];
    uint32_t ppm = ((uint32_t)data[5] << 16) |
                   ((uint32_t)data[6] << 8)  |
                   (uint32_t)data[7];

    /* Sanity checks */
    if (ppm > 10000 || ppm < 0) {
        log_error("parse_response: invalid ppm value");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                            */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_fd >= 0) {
        close(g_fd);
        g_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_err_fp) {
        fclose(g_err_fp);
        g_err_fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open UART */
    g_fd = open(SERIAL_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (g_fd < 0) {
        perror("open(" SERIAL_DEVICE ")");
        return EXIT_FAILURE;
    }

    /* Set baud rate */
    struct termios tty;
    if (tcgetattr(g_fd, &tty) != 0) {
        perror("tcgetattr");
        cleanup();
        return EXIT_FAILURE;
    }
    cfsetispeed(&tty, BAUD_RATE);
    cfsetospeed(&tty, BAUD_RATE);

    /* Set serial flags */
    tty.c_cflag = CS8 | CLOCAL | CREAD;
    tty.c_iflag = IGNPAR;
    tty.c_oflag = 0;
    tty.c_lflag = 0;
    tty.c_cc[VMIN]  = 0;
    tty.c_cc[VTIME] = 10; /* 1 second timeout */

    if (tcsetattr(g_fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log files */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }
    g_err_fp = fopen(ERROR_LOG_FILE, "a");
    if (!g_err_fp) {
        perror("fopen(" ERROR_LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Send initial command */
    if (send_command() != 0) {
        log_error("Initial command failed");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Main loop */
    while (g_running) {
        uint8_t data[9];
        ssize_t n = read(g_fd, data, sizeof(data));
        if (n < 0) {
            if (errno == EINTR)
                continue;
            log_error("read: serial read error");
            break;
        }
        if (n == 0) {
            log_error("read: serial EOF");
            break;
        }

        if (parse_response(data, n) != 0) {
            log_error("parse_response: invalid response");
            break;
        }

        char ts[32];
        get_timestamp(ts, sizeof(ts));
        fprintf(g_log_fp, "%s: CO2 = %u ppm\n", ts, (unsigned)data[2]);
        fflush(g_log_fp);

        char msg[128];
        snprintf(msg, sizeof(msg), "CO2: %u ppm", (unsigned)data[2]);
        log_message(msg);

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < 10 && g_running; i++)
            usleep(100000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

