 * Run:    sudo ./motor_control [distance_a_cm] [distance_b_cm]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define MOTOR_A_IN1  17
#define MOTOR_A_IN2  18
#define MOTOR_B_IN3  22
#define MOTOR_B_IN4  23

#define PWM_IN2_PIN  22
#define PWM_IN4_PIN  23

#define PWM_FREQ_HZ  1000
#define PWM_RANGE    255

#define DISTANCE_MIN  10.0f
#define DISTANCE_MAX 100.0f

#define DISTANCE_THRESHOLD_FOR_FORWARD  50.0f
#define DISTANCE_THRESHOLD_FOR_BACKWARD 50.0f

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/*
 * Reads a simulated ultrasonic distance value in cm.
 * Returns 0 on success, -1 on error.
 */
static int read_distance(float *distance_out)
{
    /*
     * Simulated ultrasonic distance reading.
     * In reality, a real ultrasonic sensor would return a raw
     * reading in cm or inches.  For this example, we use a
     * simple linear mapping from distance to duty cycle.
     */
    *distance_out = (float)rand() / (float)RAND_MAX;
    return 0;
}

/*
 * Sets the specified GPIO pin high (1) or low (0).
 * Returns 0 on success, -1 on failure.
 */
static int gpio_set_value(struct gpiod_line *line, int value)
{
    if (gpiod_line_set_value(line, value) < 0) {
        perror("gpiod_line_set_value");
        return -1;
    }
    return 0;
}

/*
 * Sets the PWM duty cycle for the specified GPIO pin.
 * Returns 0 on success, -1 on failure.
 */
static int gpio_set_pwm_duty(struct gpiod_line *line, int duty)
{
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;

    if (gpiod_line_set_value(line, 1) < 0) {
        perror("gpiod_line_set_value high");
        return -1;
    }

    if (gpiod_line_set_value(line, 0) < 0) {
        perror("gpiod_line_set_value low");
        return -1;
    }

    /*
     * L298N: IN2 = PWM_IN2_PIN, IN4 = PWM_IN4_PIN
     */
    uint32_t pwm_period_us = 1000000 / PWM_FREQ_HZ;
    uint32_t pwm_duty_us  = (duty * pwm_period_us) / PWM_RANGE;

    if (gpiod_line_set_pwm_duty(line, PWM_IN2_PIN, pwm_duty_us) < 0) {
        perror("gpiod_line_set_pwm_duty");
        return -1;
    }

    return 0;
}

/*
 * Initializes the L298N for forward (IN1/IN3) or backward (IN1/IN3)
 * mode.  Returns 0 on success, -1 on failure.
 */
static int l298n_init(struct gpiod_line *in1, struct gpiod_line *in2,
                       struct gpiod_line *in3, struct gpiod_line *in4)
{
    if (gpiod_line_request_output(in1, "l298n_in1", 0) < 0) {
        perror("gpiod_line_request_output in1");
        return -1;
    }
    if (gpiod_line_request_output(in2, "l298n_in2", 0) < 0) {
        perror("gpiod_line_request_output in2");
        return -1;
    }
    if (gpiod_line_request_output(in3, "l298n_in3", 0) < 0) {
        perror("gpiod_line_request_output in3");
        return -1;
    }
    if (gpiod_line_request_output(in4, "l298n_in4", 0) < 0) {
        perror("gpiod_line_request_output in4");
        return -1;
    }

    /* L298N: IN1 = IN2 = IN3 = IN4 = 0 (forward) or 1 (backward) */
    if (gpiod_line_set_value(in1, 0) < 0) {
        perror("gpiod_line_set_value in1");
        return -1;
    }
    if (gpiod_line_set_value(in2, 0) < 0) {
        perror("gpiod_line_set_value in2");
        return -1;
    }
    if (gpiod_line_set_value(in3, 0) < 0) {
        perror("gpiod_line_set_value in3");
        return -1;
    }
    if (gpiod_line_set_value(in4, 0) < 0) {
        perror("gpiod_line_set_value in4");
        return -1;
    }

    return 0;
}

/*
 * Sets the motor speed for forward (IN1/IN3) or backward (IN1/IN3)
 * direction.  Returns 0 on success, -1 on failure.
 */
static int set_motor_speed(struct gpiod_line *in1, struct gpiod_line *in2,
                           struct gpiod_line *in3, struct gpiod_line *in4,
                           int forward)
{
    int duty = forward ? PWM_RANGE : 0;
    if (gpio_set_pwm_duty(in1, duty) < 0)
        return -1;
    if (gpio_set_pwm_duty(in2, duty) < 0)
        return -1;
    if (gpio_set_pwm_duty(in3, duty) < 0)
        return -1;
    if (gpio_set_pwm_duty(in4, duty) < 0)
        return -1;
    return 0;
}

int main(int argc, char *argv[])
{
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <distance_a_cm> <distance_b_cm>\n", argv[0]);
        return EXIT_FAILURE;
    }

    float distance_a = 0.0f;
    float distance_b = 0.0f;

    if (read_distance(&distance_a) != 0) {
        fprintf(stderr, "Failed to read distance A.\n");
        return EXIT_FAILURE;
    }
    if (read_distance(&distance_b) != 0) {
        fprintf(stderr, "Failed to read distance B.\n");
        return EXIT_FAILURE;
    }

    if (install_signal_handlers() != 0) {
        fprintf(stderr, "Failed to install signal handlers.\n");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    struct gpiod_line *in1 = gpiod_chip_get_line(chip, MOTOR_A_IN1);
    struct gpiod_line *in2 = gpiod_chip_get_line(chip, MOTOR_A_IN2);
    struct gpiod_line *in3 = gpiod_chip_get_line(chip, MOTOR_B_IN3);
    struct gpiod_line *in4 = gpiod_chip_get_line(chip, MOTOR_B_IN4);

    if (!in1 || !in2 || !in3 || !in4) {
        fprintf(stderr, "Failed to get GPIO lines.\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (l298n_init(in1, in2, in3, in4) != 0) {
        fprintf(stderr, "Failed to initialize L298N.\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Motor A IN1/IN2 -> GPIO%d, IN3/IN4 -> GPIO%d\n",
           MOTOR_A_IN1, MOTOR_A_IN2);
    printf("Motor B IN3/IN4 -> GPIO%d, IN1/IN2 -> GPIO%d\n",
           MOTOR_B_IN3, MOTOR_B_IN4);
    printf("Distance threshold: %.1f cm -> %.1f cm\n",
           DISTANCE_THRESHOLD_FOR_FORWARD, DISTANCE_THRESHOLD_FOR_BACKWARD);

    while (g_running) {
        int a_duty = (distance_a < DISTANCE_THRESHOLD_FOR_FORWARD) ?
                     PWM_RANGE : 0;
        int b_duty = (distance_b < DISTANCE_THRESHOLD_FOR_BACKWARD) ?
                     PWM_RANGE : 0;

        if (set_motor_speed(in1, in2, in3, in4, a_duty) != 0) {
            fprintf(stderr, "Failed to set motor speed.\n");
            break;
        }

        usleep(100000); /* 100 ms */
    }

    /* Clean shutdown */
    set_motor_speed(in1, in2, in3, in4, 0);
    gpiod_line_set_value(in1, 0);
    gpiod_line_set_value(in2, 0);
    gpiod_line_set_value(in3, 0);
    gpiod_line_set_value(in4, 0);
    gpiod_line_release(in1);
    gpiod_line_release(in2);
    gpiod_line_release(in3);
    gpiod_line_release(in4);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

