/*
 * Door-lock control using a 28BYJ-48 stepper motor and L293D H-bridge.
 *
 * Hardware:
 *   - Raspberry Pi GPIO 17, 18, 27, 22 (BCM) -> L293D IN1-IN4 (4-wire)
 *   - L293D IN1 -> stepper coil 1 (coil 1)
 *   - L293D IN2 -> stepper coil 2 (coil 2)
 *   - L293D IN3 -> stepper coil 3 (coil 3)
 *   - L293D IN4 -> stepper coil 4 (coil 4)
 *   - LOCK button (BCM) -> L293D IN5
 *   - UNLOCK button (BCM) -> L293D IN6
 *
 * Build: gcc -O2 -Wall -o door_lock door_lock.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define STEPPER_PIN1 17
#define STEPPER_PIN2 18
#define STEPPER_PIN3 27
#define STEPPER_PIN4 22
#define LOCK_PIN    24
#define UNLOCK_PIN  23

#define STEPPER_DELAY_US   20000   /* 2 ms per step */
#define STEP_DELAY_US      500000  /* 500 ms between steps */
#define STEP_COUNT         512
#define STEP_DURATION_MS   500

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                         */
/* ------------------------------------------------------------------ */

static int gpio_init(int pin, uint8_t mode)
{
    if (gpio_set_mode(pin, mode) < 0) {
        fprintf(stderr, "Error: gpio_set_mode(%d, %u) failed: %s\n",
                pin, mode, strerror(errno));
        return -1;
    }
    return 0;
}

static int gpio_write(int pin, int value)
{
    if (gpio_set_value(pin, value) < 0) {
        fprintf(stderr, "Error: gpio_set_value(%d, %d) failed: %s\n",
                pin, value, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* L293D H-bridge                                                      */
/* ------------------------------------------------------------------ */

static int l293d_init(void)
{
    if (gpio_write(STEPPER_PIN1, 0) < 0)
        return -1;
    if (gpio_write(STEPPER_PIN2, 0) < 0)
        return -1;
    if (gpio_write(STEPPER_PIN3, 0) < 0)
        return -1;
    if (gpio_write(STEPPER_PIN4, 0) < 0)
        return -1;
    if (gpio_write(LOCK_PIN, 0) < 0)
        return -1;
    if (gpio_write(UNLOCK_PIN, 0) < 0)
        return -1;

    /* L293D IN1-IN4 are open-collector; drive them high for LOW input */
    if (gpio_write(STEPPER_PIN1, 1) < 0)
        return -1;
    if (gpio_write(STEPPER_PIN2, 1) < 0)
        return -1;
    if (gpio_write(STEPPER_PIN3, 1) < 0)
        return -1;
    if (gpio_write(STEPPER_PIN4, 1) < 0)
        return -1;

    return 0;
}

static void l293d_deinit(void)
{
    /* Ensure all coils are low before release */
    if (gpio_write(STEPPER_PIN1, 0) < 0)
        fprintf(stderr, "Warning: failed to deinit L293D IN1\n");
    if (gpio_write(STEPPER_PIN2, 0) < 0)
        fprintf(stderr, "Warning: failed to deinit L293D IN2\n");
    if (gpio_write(STEPPER_PIN3, 0) < 0)
        fprintf(stderr, "Warning: failed to deinit L293D IN3\n");
    if (gpio_write(STEPPER_PIN4, 0) < 0)
        fprintf(stderr, "Warning: failed to deinit L293D IN4\n");
}

/*
 * Full-step two-phase drive:
 *   Coil 1: H-H-L-L
 *   Coil 2: L-H-H-L
 *   Coil 3: L-L-H-H
 *   Coil 4: H-L-L-H
 *
 * Each step takes STEP_DELAY_US.
 */
static void step_forward(void)
{
    for (int i = 0; i < STEP_COUNT; i++) {
        if (gpio_write(STEPPER_PIN1, 1) < 0)
            return;
        if (gpio_write(STEPPER_PIN2, 0) < 0)
            return;
        if (gpio_write(STEPPER_PIN3, 0) < 0)
            return;
        if (gpio_write(STEPPER_PIN4, 0) < 0)
            return;
        usleep(STEP_DELAY_US);
    }
    for (int i = 0; i < STEP_COUNT; i++) {
        if (gpio_write(STEPPER_PIN1, 0) < 0)
            return;
        if (gpio_write(STEPPER_PIN2, 1) < 0)
            return;
        if (gpio_write(STEPPER_PIN3, 0) < 0)
            return;
        if (gpio_write(STEPPER_PIN4, 0) < 0)
            return;
        usleep(STEP_DELAY_US);
    }
}

static void step_backward(void)
{
    for (int i = 0; i < STEP_COUNT; i++) {
        if (gpio_write(STEPPER_PIN1, 0) < 0)
            return;
        if (gpio_write(STEPPER_PIN2, 1) < 0)
            return;
        if (gpio_write(STEPPER_PIN3, 0) < 0)
            return;
        if (gpio_write(STEPPER_PIN4, 0) < 0)
            return;
        usleep(STEP_DELAY_US);
    }
    for (int i = 0; i < STEP_COUNT; i++) {
        if (gpio_write(STEPPER_PIN1, 1) < 0)
            return;
        if (gpio_write(STEPPER_PIN2, 0) < 0)
            return;
        if (gpio_write(STEPPER_PIN3, 0) < 0)
            return;
        if (gpio_write(STEPPER_PIN4, 0) < 0)
            return;
        usleep(STEP_DELAY_US);
    }
}

/* ------------------------------------------------------------------ */
/* Door-lock control                                                     */
/* ------------------------------------------------------------------ */

static void lock_door(void)
{
    if (gpio_write(LOCK_PIN, 1) < 0)
        return;
    printf("Locking door...\n");
    step_forward();
    printf("Door locked.\n");
}

static void unlock_door(void)
{
    if (gpio_write(LOCK_PIN, 0) < 0)
        return;
    printf("Unlocking door...\n");
    step_backward();
    printf("Door unlocked.\n");
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                              */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    l293d_deinit();
    gpio_write(LOCK_PIN, 0);
    gpio_write(UNLOCK_PIN, 0);
    printf("Cleanup complete.\n");
}

/* ------------------------------------------------------------------ */
/* Main                                                                 */
/* ------------------------------------------------------------------ */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpio_init(STEPPER_PIN1, GPIO_OUTPUT) < 0)
        return EXIT_FAILURE;
    if (gpio_init(STEPPER_PIN2, GPIO_OUTPUT) < 0)
        return EXIT_FAILURE;
    if (gpio_init(STEPPER_PIN3, GPIO_OUTPUT) < 0)
        return EXIT_FAILURE;
    if (gpio_init(STEPPER_PIN4, GPIO_OUTPUT) < 0)
        return EXIT_FAILURE;
    if (gpio_init(LOCK_PIN, GPIO_INPUT) < 0)
        return EXIT_FAILURE;
    if (gpio_init(UNLOCK_PIN, GPIO_INPUT) < 0)
        return EXIT_FAILURE;

    if (l293d_init() < 0) {
        fprintf(stderr, "Error: L293D initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Door-lock control started. Press Ctrl+C to exit.\n");

    while (g_running) {
        bool lock_pressed = (gpio_read(LOCK_PIN) == 1);
        bool unlock_pressed = (gpio_read(UNLOCK_PIN) == 1);

        if (lock_pressed && !unlock_pressed) {
            lock_door();
        } else if (!lock_pressed && unlock_pressed) {
            unlock_door();
        }

        usleep(STEP_DELAY_US);
    }

