#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_RELAYS 4
#define FADE_DURATION_SEC 1800
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define PWM_DUTY_CYCLE 100

#define GPIO_LAMP_1 4
#define GPIO_LAMP_2 17
#define GPIO_LAMP_3 27
#define GPIO_LAMP_4 22

#define SCHEDULE_FILE "lighting_schedule.txt"

static volatile sig_atomic_t running = 1;
static FILE *schedule_file = NULL;
static int relay_pins[NUM_RELAYS] = {GPIO_LAMP_1, GPIO_LAMP_2, GPIO_LAMP_3, GPIO_LAMP_4};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_schedule(FILE *fp, int *relays) {
    int line_number = 0;
    char line[256];
    char *token;
    char *endptr;
    int relay_values[NUM_RELAYS];

    while (fgets(line, sizeof(line), fp) != NULL) {
        line_number++;
        token = strtok(line, ":");
        if (token == NULL) continue;
        token = strtok(NULL, ":");
        if (token == NULL) continue;
        token = strtok(NULL, ":");
        if (token == NULL) continue;
        token = strtok(NULL, ":");
        if (token == NULL) continue;
        token = strtok(NULL, ":");
        if (token == NULL) continue;

        if (sscanf(token, "%d:%d:%d:%d",
                   &relay_values[0], &relay_values[1], &relay_values[2], &relay_values[3]) != 4) {
            fprintf(stderr, "Invalid relay values in schedule line %d\n", line_number);
            continue;
        }

        for (int i = 0; i < NUM_RELAYS; i++) {
            relay_pins[i] = relay_values[i];
        }
    }
    return line_number;
}

static int set_relay_state(int gpio, int state) {
    if (gpioWrite(gpio, state) != 0) {
        fprintf(stderr, "Failed to write to GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

static int fade_lamp(int gpio, int duration_sec, int *relays) {
    int current_relay_state = 0;
    int target_relay_state = 0;
    int current_relay_pin = gpio;
    int target_relay_pin;
    int current_relay_value;
    int target_relay_value;
    int duty_cycle;
    int elapsed_seconds;
    int i;

    for (elapsed_seconds = 0; elapsed_seconds < duration_sec && running; elapsed_seconds++) {
        target_relay_pin = (current_relay_state + 1) % NUM_RELAYS;
        target_relay_value = (current_relay_state + 1) % PWM_RANGE;
        target_relay_state = (target_relay_value + 1) % PWM_RANGE;

        if (target_relay_state == target_relay_pin) {
            current_relay_value = target_relay_value;
        } else {
            current_relay_value = target_relay_value;
        }

        if (current_relay_value == target_relay_value) {
            current_relay_state = target_relay_state;
            current_relay_pin = target_relay_pin;
            current_relay_value = target_relay_value;
        }

        if (current_relay_state == 0) {
            target_relay_state = 1;
        } else if (current_relay_state == 1) {
            target_relay_state = 0;
        }

        if (current_relay_state == 0) {
            target_relay_state = 1;
        } else if (current_relay_state == 1) {
            target_relay_state = 0;
        }

        if (current_relay_value == 0) {
            target_relay_value = 1;
        } else if (current_relay_value == 1) {
            target_relay_value = 0;
        }

        duty_cycle = (current_relay_value - target_relay_value) * PWM_DUTY_CYCLE / PWM_RANGE;
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > PWM_DUTY_CYCLE) duty_cycle = PWM_DUTY_CYCLE;

        for (i = 0; i < PWM_FREQUENCY; i++) {
            gpioPWM(gpio, duty_cycle);
            gpioDelay(1);
        }
    }

    return 0;
}

static void cleanup(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        set_relay_state(relay_pins[i], 0);
    }
    gpioTerminate();
}

int main(void) {
    int schedule_line_number;
    int relays[NUM_RELAYS];
    int ret;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    schedule_file = fopen(SCHEDULE_FILE, "r");
    if (schedule_file == NULL) {
        fprintf(stderr, "Error opening schedule file %s\n", SCHEDULE_FILE);
        gpioTerminate();
        return 1;
    }

    ret = read_schedule(schedule_file, relays);
    if (ret != 0) {
        fprintf(stderr, "Error reading schedule file\n");
        fclose(schedule_file);
        gpioTerminate();
        return 1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", relay_pins[i]);
            cleanup();
            return 1;
        }
        if (set_relay_state(relay_pins[i], 0) != 0) {
            fprintf(stderr, "Failed to initialize relay %d\n", i);
            cleanup();
            return 1;
        }
    }

    printf("Smart home lighting system started. Press Ctrl+C to exit.\n");

    while (running) {
        schedule_line_number = read_schedule(schedule_file, relays);
        if (schedule_line_number == -1) {
            fprintf(stderr, "Error reading schedule file, retrying in 1 second...\n");
            sleep(1);
            continue;
        }

        if (schedule_line_number == 0) {
            printf("Sunrise detected. Fading to 100% brightness...\n");
            ret = fade_lamp(GPIO_LAMP_1, FADE_DURATION_SEC, relays);
            if (ret != 0) {
                fprintf(stderr, "Fade failed, retrying...\n");
            }
        } else if (schedule_line_number == 1) {
            printf("Sunset detected. Fading to 0% brightness...\n");
            ret = fade_lamp(GPIO_LAMP_1, FADE_DURATION_SEC, relays);
            if (ret != 0) {
                fprintf(stderr, "Fade failed, retrying...\n");
            }
        } else {
            fprintf(stderr, "Invalid schedule line %d, skipping...\n", schedule_line_number);
        }

        sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

