/*
 * Raspberry Pi Zero W - Theremin using HC-SR04 Ultrasonic Sensor
 *
 * Hardware:
 *   - HC-SR04 Trigger  -> GPIO23 (BCM)
 *   - HC-SR04 Echo     -> GPIO24 (BCM)
 *   - HC-SR04 VCC      -> 3.3 V
 *   - HC-SR04 GND      -> GND
 *   - PWM Buzzer        -> GPIO18 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o theremin theremin.c -lgpiod
 *
 * Run:
 *   sudo ./theremin
 */

