#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24
#define BUZZER_PIN       18

#define SPEED_OF_SOUND_CM_PER_US 0.0343f
#define MIN_DISTANCE_CM       60.0f
#define MAX_DISTANCE_CM       400.0f
#define MIN_FREQUENCY_HZ      50.0f
#define MAX_FREQUENCY_HZ      1000.0f
#define SAMPLE_INTERVAL_US    100000  /* 100 ms = ~10 Hz */
#define MIN_GAP_US            60000   /* 60 ms gap between measurements */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Trigger the HC-SR04: sends a 10 µs pulse on the trigger pin.
 * Returns 0 on success, -1 on failure.
 */
static int trigger_sensor(struct gpiod_line *trigger, struct gpiod_line *echo)
{
    if (gpiod_line_set_value(trigger, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high\n");
        return -1;
    }
    usleep(10);
    if (gpiod_line_set_value(trigger, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -1;
    }
    return 0;
}

/*
 * Read the echo pulse duration in microseconds.
 * Returns the duration in microseconds on success, -1 on timeout.
 */
static int read_echo_us(struct gpiod_line *echo)
{
    struct timespec start, end;
    int elapsed_us;

    if (gpiod_line_set_value(echo, 0) < 0) {
        fprintf(stderr, "Error: failed to set echo low\n");
        return -1;
    }
    usleep(1);

    if (gpiod_line_set_value(echo, 1) < 0) {
        fprintf(stderr, "Error: failed to set echo high\n");
        return -1;
    }
    usleep(10);

    if (gpiod_line_set_value(echo, 0) < 0) {
        fprintf(stderr, "Error: failed to set echo low\n");
        return -1;
    }

    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(echo) == 1) {
        if (clock_gettime(CLOCK_MONOTONIC, &end) == 0) {
            elapsed_us = (end.tv_sec - start.tv_sec) * 1000000 +
                         (end.tv_nsec - start.tv_nsec) / 1000;
            return elapsed_us;
        }
