    }

    return -1;
}

/*
 * Compute the buzzer frequency from the echo pulse duration.
 * Returns the frequency in Hz, or -1.0 on error.
 */
static float compute_frequency(int elapsed_us)
{
    if (elapsed_us < 0) {
