 * Apply the computed frequency to the buzzer pin.
 * Returns 0 on success, -1 on failure.
 */
static int set_buzzer_frequency(struct gpiod_line *buzzer, float frequency)
{
    if (gpiod_line_set_value(buzzer, (int)frequency) < 0) {
        fprintf(stderr, "Error: failed to set buzzer frequency\n");
        return -1;
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL;
    struct gpiod_line *echo   = NULL;
    struct gpiod_line *buzzer = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        goto cleanup;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi Zero W) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo   = gpiod_chip_get_line(chip, ECHO_PIN);
    buzzer = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!trigger || !echo || !buzzer) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request trigger as output, initially low */
    if (gpiod_line_request_output(trigger, "theremin-trigger", 0) < 0) {
        perror("gpiod_line_request_output trigger");
        goto cleanup;
    }

    /* Request echo as input */
    if (gpiod_line_request_input(echo, "theremin-echo") < 0) {
        perror("gpiod_line_request_input echo");
        goto cleanup;
    }

    /* Request buzzer as output, initially low */
    if (gpiod_line_request_output(buzzer, "theremin-buzzer", 0) < 0) {
        perror("gpiod_line_request_output buzzer");
        goto cleanup;
    }

    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int elapsed_us = read_echo_us(echo);
        if (elapsed_us < 0) {
            fprintf(stderr, "Error: sensor read failed, retrying in %d ms\n",
                    MIN_GAP_US / 1000);
            usleep(MIN_GAP_US / 1000);
            continue;
        }

        float frequency = compute_frequency(elapsed_us);
        if (frequency < 0.0f) {
            fprintf(stderr, "Error: invalid frequency, retrying in %d ms\n",
                    MIN_GAP_US / 1000);
            usleep(MIN_GAP_US / 1000);
            continue;
        }

        if (set_buzzer_frequency(buzzer, frequency) < 0) {
            fprintf(stderr, "Error: failed to set buzzer frequency\n");
            break;
        }

        printf("Frequency: %.2f Hz\n", frequency);
        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (buzzer) {
        set_buzzer_frequency(buzzer, -1.0f);
        gpiod_line_release(buzzer);
    }
    if (echo) {
        gpiod_line_release(echo);
    }
    if (trigger) {
        gpiod_line_release(trigger);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

