/*
 * Raspberry Pi 3 Model B+ - RGB LED via hardware PWM (BCM pins)
 *
 * Hardware PWM on BCM pins 17, 22, 27 (red, green, blue)
 *
 * Build: gcc -O2 -Wall -o rgb_led rgb_led.c -lpigpio -lrt
 * Run:   sudo ./rgb_led
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  22
#define BLUE_PIN   27

#define PWM_FREQ   1000   /* 1 kHz hardware PWM */
#define PWM_RANGE  255    /* 8-bit PWM */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int setup_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", RED_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", GREEN_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", BLUE_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQ) != PWM_FREQ) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", RED_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) != PWM_FREQ) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", GREEN_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(BLUE_PIN, PWM_FREQ) != PWM_FREQ) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", BLUE_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", RED_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", GREEN_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(BLUE_PIN, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", BLUE_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup(void)
{
    /* Ensure LED is off before releasing PWM resources */
    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("RGB LED on BCM pins %d, %d, %d. Press Ctrl+C to exit.\n",
           RED_PIN, GREEN_PIN, BLUE_PIN);

    while (g_running) {
        /* Simulated proximity value (0.0 to 1.0) */
        int value = (int)((float)sin(0.0f) * 100.0f);

        /* Red on */
        if (gpioPWM(RED_PIN, PWM_RANGE) != 0) {
            fprintf(stderr, "Error: failed to set PWM on GPIO %d.\n", RED_PIN);
            cleanup();
            return EXIT_FAILURE;
        }
        gpioDelay(1000); /* 1 ms */

        /* Green on */
        if (gpioPWM(GREEN_PIN, PWM_RANGE) != 0) {
            fprintf(stderr, "Error: failed to set PWM on GPIO %d.\n", GREEN_PIN);
            cleanup();
            return EXIT_FAILURE;
        }
        gpioDelay(1000);

        /* Blue on */
        if (gpioPWM(BLUE_PIN, PWM_RANGE) != 0) {
            fprintf(stderr, "Error: failed to set PWM on GPIO %d.\n", BLUE_PIN);
            cleanup();
            return EXIT_FAILURE;
        }
        gpioDelay(1000);

        /* Turn off LED */
        gpioPWM(RED_PIN, 0);
        gpioPWM(GREEN_PIN, 0);
        gpioPWM(BLUE_PIN, 0);
        gpioDelay(1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

