#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6050_ADDR   0x68
#define LOG_FILE       "gyro_log.txt"
#define SAMPLE_MS      100

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a 16-bit big-endian register from the MPU-6050.
 * Returns 0 on success, -1 on error.
 */
static int mpu6050_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "read_reg16: expected 2 bytes, got %zd\n", n);
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/*
 * Read a 16-bit register from the MPU-6050.
 * Returns 0 on success, -1 on error.
 */
static int mpu6050_read_reg16_p(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "read_reg16_p: expected 2 bytes, got %zd\n", n);
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/*
 * Read a 16-bit big-endian register from the MPU-6050.
 * Returns 0 on success, -1 on error.
 */
static int mpu6050_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
