        fprintf(stderr, "read_reg16: expected 2 bytes, got %zd\n", n);
        return -1;
    }
    *out = ((int16_t)buf[0] << 8) | buf[1];
    return 0;
}

/*
 * Read a 16-bit big-endian register from the MPU-6050.
 * Returns 0 on success, -1 on error.
 */
static int mpu6050_read_reg16_p(int fd, uint8_t reg, int16_t *out)
{
    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
