        return -1;
    }
    *out = ((int16_t)buf[0] << 8) | buf[1];
    return 0;
}

/*
 * Read the angular velocity in degrees per second.
 * Returns 0 on success, -1 on error.
 */
static int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint16_t x_raw, y_raw, z_raw;

    if (mpu6050_read_reg16_p(fd, MPU6050_ADDR, &x_raw) != 0)
        return -1;
    if (mpu6050_read_reg16_p(fd, MPU6050_ADDR + 1, &y_raw) != 0)
        return -1;
    if (mpu6050_read_reg16_p(fd, MPU6050_ADDR + 2, &z_raw) != 0)
        return -1;

    *x = (int16_t)x_raw;
    *y = (int16_t)y_raw;
    *z = (int16_t)z_raw;
    return 0;
}

/*
 * Append a timestamped line to the log file.
 * Returns 0 on success, -1 on error.
 */
static int log_data(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(fp, "%s, %d, %d, %d\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "log_data: fprintf failed\n");
        return -1;
    }
    fflush(fp);
    return 0;
