    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the MPU-6050 slave address */
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                MPU6050_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Open the log file in append mode */
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("MPU-6050 gyroscope reader started. Logging to %s every %d ms.\n",
           LOG_FILE, SAMPLE_MS);
    printf("Press Ctrl+C to stop.\n");

