    while (g_running) {
        if (read_gyro_data(fd, &x, &y, &z) == 0) {
            if (log_data(fp, x, y, z) != 0) {
                fprintf(stderr, "log_data failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "read_gyro_data failed; continuing.\n");
        }
        usleep(SAMPLE_MS * 1000);
    }

    printf("\nShutting down gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        fclose(fp);
    }
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

