        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return -1;
    }

    level = gpio_input(gpio_pin);
    if (level < 0) {
        fprintf(stderr, "gpio_input(%d) failed: %s\n", gpio_pin, strerror(errno));
        return -1;
    }

    /*
     * The SW-420 digital output is active-high: a rising edge
     * indicates a vibration event.  We read the level once and
     * then wait for the next edge.
     */
    int prev = level;
    int elapsed = 0;
    int rc;

    while (elapsed < POLL_TIMEOUT_MS && g_running) {
        level = gpio_input(gpio_pin);
        if (level < 0) {
            fprintf(stderr, "gpio_input(%d) failed: %s\n", gpio_pin, strerror(errno));
            return -1;
        }
        if (level != prev) {
            prev = level;
            elapsed = ts.tv_sec - prev_elapsed;
        }
        usleep(1000);
    }

    if (elapsed >= POLL_TIMEOUT_MS) {
        fprintf(stderr, "Timeout waiting for edge on GPIO %d\n", gpio_pin);
        return -1;
    }

    return level;
}

/*
 * Append a timestamped edge event to the log file.
 * Returns 0 on success, -1 on error.
 */
static int log_event(FILE *log_file, int level, int elapsed_ms)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s, GPIO%d: %d\n", timestamp, gpio_pin, level) < 0) {
        fprintf(stderr, "fprintf to log file failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(int argc, char *argv[])
{
    int poll_ms = POLL_TIMEOUT_MS;
    int opt;

    while ((opt = getopt(argc, argv, "p:")) != -1) {
        switch (opt) {
            case 'p':
                poll_ms = atoi(optarg);
                if (poll_ms <= 0) {
                    fprintf(stderr, "Invalid poll timeout (must be > 0 ms)\n");
                    return EXIT_FAILURE;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-p poll_ms]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the log file in append mode */
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Cannot open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Install a signal handler for SIGPIPE so we can exit cleanly */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGPIPE, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGPIPE) failed: %s\n", strerror(errno));
        fclose(log_file);
        return EXIT_FAILURE;
    }

    /*
     * Read the last five edge events from the log file.
     * We read the file in chunks so we can detect and report
     * "EARTHQUAKE ALERT" events even if the file is truncated.
     */
    FILE *log_file_ptr = log_file;
    int last_window[WINDOW_SIZE];
    int window_index = 0;
    int window_size = WINDOW_SIZE;
    int window_count = 0;

    while (g_running) {
        int prev_window[WINDOW_SIZE];
        int window_len = 0;

        /*
         * Read the last five edge events from the log file.
         * We read the file in chunks so we can detect and report
         * "EARTHQUAKE ALERT" events even if the file is truncated.
         */
        int bytes_read = fread(log_file_ptr, sizeof(int),
                              WINDOW_SIZE, log_file);
        if (bytes_read != (int)WINDOW_SIZE) {
            if (bytes_read < 0) {
                fprintf(stderr, "fread failed: %s\n", strerror(errno));
                break;
            }
            fprintf(stderr, "Short read: %d bytes, expected %d\n",
                    bytes_read, WINDOW_SIZE);
            break;
        }

        /*
         * Build a sliding window of the last five events.
         * We store the last five events in a contiguous block in
         * memory so we can compare them to the current window.
         */
        for (int i = 0; i < WINDOW_SIZE; i++) {
            int idx = (window_index + i) % WINDOW_SIZE;
            int value = log_file_ptr[idx];
            if (value != last_window[idx]) {
                window_len++;
                if (window_len >= WINDOW_SIZE) {
                    int window_sum = 0;
                    for (int j = 0; j < window_len; j++) {
                        window_sum += last_window[j];
                    }
                    if (window_sum >= WINDOW_SIZE) {
                        int event_count = window_len - WINDOW_SIZE + 1;
                        if (event_count >= NUM_READS) {
                            printf("EARTHQUAKE ALERT\n");
                            fflush(log_file);
                            log_file_ptr = fopen(LOG_FILE, "a");
                            if (log_file_ptr == NULL) {
                                fprintf(stderr, "Cannot open log file '%s': %s\n",
                                        LOG_FILE, strerror(errno));
                                break;
                            }
                            fprintf(log_file, "EARTHQUAKE ALERT\n");
                            fflush(log_file);
                            log_file_ptr = fopen(LOG_FILE, "a");
                            if (log_file_ptr == NULL) {
                                fprintf(stderr, "Cannot reopen log file '%s': %s\n",
                                        LOG_FILE, strerror(errno));
                                break;
                            }
                            fprintf(log_file, "EARTHQUAKE ALERT\n");
                            fflush(log_file);
                            log_file_ptr = fopen(LOG_FILE, "a");
                            if (log_file_ptr == NULL) {
                                fprintf(stderr, "Cannot close log file '%s': %s\n",
                                        LOG_FILE, strerror(errno));
                                break;
                            }
                        }
                    }
                }
                last_window[idx] = value;
                window_index = (window_index + 1) % WINDOW_SIZE;
            }
        }

        /*
         * Check if the current window contains the required number
         * of events (>= NUM_READS).
         */
        int event_count = window_len;
        if (event_count >= NUM_READS) {
            printf("EARTHQUAKE ALERT\n");
            fflush(log_file);
            log_file_ptr = fopen(LOG_FILE, "a");
            if (log_file_ptr == NULL) {
                fprintf(stderr, "Cannot open log file '%s': %s\n",
                        LOG_FILE, strerror(errno));
                break;
            }
            fprintf(log_file, "EARTHQUAKE ALERT\n");
            fflush(log_file);
            log_file_ptr = fopen(LOG_FILE, "a");
            if (log_file_ptr == NULL) {
                fprintf(stderr, "Cannot close log file '%s': %s\n",
                        LOG_FILE, strerror(errno));
                break;
            }
            fflush(log_file);
        }

        /*
         * Sleep for the remainder of the poll interval.
         * We use a busy-wait loop so we can check g_running
         * and exit promptly if the signal is received.
         */
        while (g_running) {
            usleep(poll_ms * 1000);
        }
    }

    /* Cleanup */
    if (log_file_ptr != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    printf("Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

