#include <errno.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_MS 200
#define LOG_FILE "relay_log.json"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *state) {
    if (!log_file) return -1;
    time_t now = time(NULL);
    if (now == (time_t)-1) return -1;
    struct tm tm_buf;
    if (!localtime_r(&now, &tm_buf)) return -1;
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_buf) == 0) return -1;
    if (fprintf(log_file, "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"}", ts, state) < 0) return -1;
    if (fflush(log_file) != 0) return -1;
    return 0;
}

static int debounce_touch(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    static int last_state = -1;
    if (tick < last_tick) return 1;
    last_tick = tick;
    int state = level;
    if (state != last_state) {
        if (gpioWrite(relay_pin, state) != 0) return 1;
        last_state = state;
        if (log_event(state ? "ON" : "OFF") != 0) return 1;
        return 0;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0);
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetAlertFunc(TOUCH_SENSOR_PIN, debounce_touch) != 0) {
        fprintf(stderr, "Failed to set alert function on GPIO%d\n", TOUCH_SENSOR_PIN);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    printf("Touch sensor monitoring started on GPIO%d. Relay on GPIO%d. Logging to %s\n",
           TOUCH_SENSOR_PIN, RELAY_PIN, LOG_FILE);
    while (running) {
        gpioDelay(100000);
    }
    printf("\nShutting down...\n");
    gpioWrite(RELAY_PIN, 0);
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

