#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define NUM_RELAYS 4
#define MOISTURE_THRESHOLD 30
#define RELAY_ACTIVE_HIGH 1
#define RELAY_INACTIVE_HIGH 0
#define RELAY_ACTIVE_LOW 0
#define RELAY_INACTIVE_LOW 1
#define LOG_FILE "irrigation_log.txt"
#define POLL_INTERVAL_SEC 10
#define RELAY_ACTIVE_DURATION_SEC 5
#define RELAY_INACTIVE_DURATION_SEC 1

static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int activate_relay(int relay_number) {
    if (gpioWrite(relay_number, RELAY_ACTIVE_HIGH) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d high\n", relay_number);
        return -1;
    }
    return 0;
}

static int deactivate_relay(int relay_number) {
    if (gpioWrite(relay_number, RELAY_INACTIVE_HIGH) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d low\n", relay_number);
        return -1;
    }
    return 0;
}

static int log_irrigation_event(int relay_number, int moisture_level) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s, Relay %d, Moisture: %d\n", timestamp, relay_number, moisture_level) < 0) {
        fprintf(stderr, "Error: failed to write to log file\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: failed to flush log file\n");
        return -1;
    }

    return 0;
}

static int initialize_gpio(void) {
    int i;
    for (i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(i, PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output\n", i);
            return -1;
        }
        if (gpioWrite(i, RELAY_INACTIVE_LOW) != 0) {
            fprintf(stderr, "Error: failed to initialize GPIO %d low\n", i);
            return -1;
        }
    }
    return 0;
}

static void cleanup(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioWrite(i, RELAY_INACTIVE_LOW) != 0) {
            fprintf(stderr, "Warning: failed to deactivate GPIO %d during cleanup\n", i);
        }
    }
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    int relay_numbers[NUM_RELAYS];
    int i;
    int moisture_level;
    int relay_active_time;
    int relay_inactive_time;
    int consecutive_errors = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Smart irrigation system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        moisture_level = rand() % 100;
        printf("Moisture level: %d\n", moisture_level);

        for (i = 0; i < NUM_RELAYS; i++) {
            if (activate_relay(i) != 0) {
                consecutive_errors++;
                fprintf(stderr, "Error activating relay %d\n", i);
                if (consecutive_errors >= 5) {
                    fprintf(stderr, "Error: too many consecutive failures, aborting\n");
                    break;
                }
                gpioDelay(RELAY_ACTIVE_DURATION_SEC * 1000000);
                continue;
            }
            relay_active_time = RELAY_ACTIVE_DURATION_SEC;
            relay_inactive_time = RELAY_INACTIVE_DURATION_SEC;
        }

        if (consecutive_errors >= 5) {
            fprintf(stderr, "Error: too many consecutive failures, aborting\n");
            break;
        }

        for (i = 0; i < NUM_RELAYS; i++) {
            if (deactivate_relay(i) != 0) {
                consecutive_errors++;
                fprintf(stderr, "Error deactivating relay %d\n", i);
                if (consecutive_errors >= 5) {
                    fprintf(stderr, "Error: too many consecutive failures, aborting\n");
                    break;
                }
                gpioDelay(RELAY_INACTIVE_DURATION_SEC * 1000000);
                continue;
            }
            relay_inactive_time = RELAY_INACTIVE_DURATION_SEC;
        }

        if (consecutive_errors >= 5) {
            fprintf(stderr, "Error: too many consecutive failures, aborting\n");
            break;
        }

        if (log_irrigation_event(0, moisture_level) != 0) {
            fprintf(stderr, "Error logging irrigation event\n");
        }

        if (gpioDelay(POLL_INTERVAL_SEC * 1000000) != 0) {
            fprintf(stderr, "Warning: gpioDelay failed\n");
        }
    }

    cleanup();
    printf("Smart irrigation system stopped.\n");
    return EXIT_SUCCESS;
}

