/*
 * MPU-6050 gyroscope reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   MPU-6050 SDA -> GPIO2 (I2C bus 1 SDA)
 *   MPU-6050 SCL -> GPIO3 (I2C bus 1 SCL)
 *   MPU-6050 VDD -> 3.3 V
 *   MPU-6050 GND -> GND
 *
 * Build: gcc -O2 -Wall -o gyro_log gyro_log.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6050_ADDR   0x68          /* MPU-6050 default address */
#define LOG_FILE       "gyro_log.txt"
#define SAMPLE_PERIOD  1000000       /* microseconds */
#define MAX_SAMPLES    100

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single byte from the MPU-6050.
 * Returns 0 on success, -1 on error.
 */
static int mpu6050_read_byte(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit big-endian value from the MPU-6050.
 * Returns 0 on success, -1 on error.
 */
static int mpu6050_read_16bit(int fd, uint8_t reg, uint16_t *val)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/*
 * Read the X, Y, and Z angular velocities from the MPU-6050.
 * Returns 0 on success, -1 on error.
 */
static int mpu6050_read_gyro(int fd, float *x, float *y, float *z)
{
    uint8_t buf[6];

    if (mpu6050_read_byte(fd, MPU6050_ADDR + 0x00, buf[0]) < 0)
        return -1;
    if (mpu6050_read_byte(fd, MPU6050_ADDR + 0x01, buf[1]) < 0)
        return -1;
    if (mpu6050_read_byte(fd, MPU6050_ADDR + 0x02, buf[2]) < 0)
        return -1;
    if (mpu6050_read_byte(fd, MPU6050_ADDR + 0x03, buf[3]) < 0)
        return -1;
    if (mpu6050_read_byte(fd, MPU6050_ADDR + 0x04, buf[4]) < 0)
        return -1;
    if (mpu6050_read_byte(fd, MPU6050_ADDR + 0x05, buf[5]) < 0)
        return -1;

    *x = (float)buf[0] | ((float)buf[1] << 8) | ((float)buf[2] << 16);
    *y = (float)buf[3] | ((float)buf[4] << 8) | ((float)buf[5] << 16);
    *z = (float)buf[6] | ((float)buf[7] << 8) | ((float)buf[8] << 16);
    return 0;
}

static void get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        snprintf(buf, len, "1970-01-01T00:00:00");
        return;
    }
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &timeinfo);
}

static int log_data(FILE *fp, float x, float y, float z)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    if (fprintf(fp, "%s,%f,%f,%f\n", ts, x, y, z) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    int fd = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the MPU-6050 slave address */
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus access to 0x%02X: %s\n",
                MPU6050_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Open the log file in append mode */
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("Logging MPU-6050 data to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    /* Main sampling loop */
    while (g_running) {
        float x, y, z;

        if (mpu6050_read_gyro(fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Failed to read gyroscope data. Retrying in 1 s.\n");
            sleep(1);
            continue;
        }

        if (log_data(fp, x, y, z) < 0) {
            fprintf(stderr, "Failed to write to log file. Retrying in 1 s.\n");
            sleep(1);
            continue;
        }

        printf("X: %f, Y: %f, Z: %f\n", x, y, z);
        fflush(stdout);

        /* Sleep for the sample period, but wake early on signal */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++)
            sleep(1);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        if (fclose(fp) != 0)
            fprintf(stderr, "Warning: fclose failed: %s\n", strerror(errno));
    }
    if (fd >= 0) {
        if (close(fd) != 0)
            fprintf(stderr, "Warning: close failed: %s\n", strerror(errno));
    }
    return rc;
}

