#define LOCK_PIN 4
#define UNLOCK_PIN 17
#define DRIVE_PIN 27
#define DEBOUNCE_DELAY_US 5000
#define STEP_DELAY_US 3000
#define STEP_COUNT 512
#define DEBOUNCE_COUNTS 4
#define DEBOUNCE_THRESHOLD 50

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int step(int coil1, int coil2, int coil3, int coil4, int direction) {
    if (gpioWrite(coil1, direction) != 0) return -1;
    if (gpioWrite(coil2, !direction) != 0) return -1;
    if (gpioWrite(coil3, direction) != 0) return -1;
    if (gpioWrite(coil4, !direction) != 0) return -1;
    return 0;
}

static int lock_step(void) {
    return step(1, 0, 0, 0, 1);
}

static int unlock_step(void) {
    return step(0, 1, 0, 0, 1);
}

static int deactivate_all(void) {
    for (int i = 1; i <= 4; i++) {
        if (gpioWrite(i, 0) != 0) return -1;
    }
    return 0;
}

static int activate_all(void) {
    for (int i = 1; i <= 4; i++) {
        if (gpioWrite(i, 1) != 0) return -1;
    }
    return 0;
}

static int lock_unlock(int direction) {
    int prev_state = gpioRead(LOCK_PIN);
    if (prev_state < 0) return -1;
    if (gpioWrite(LOCK_PIN, 1) != 0) return -1;
    if (gpioDelay(DEBOUNCE_DELAY_US) < 0) return -1;
    int debounced = gpioRead(LOCK_PIN);
    if (debounced < 0) return -1;
    if (debounced != prev_state) {
        if (direction == 1) {
            if (lock_step() != 0) return -1;
        } else {
            if (unlock_step() != 0) return -1;
        }
    }
    gpioDelay(STEP_DELAY_US);
    return 0;
