    int level = 0;
    int timeout = 0;

    /* Wait for echo rising edge with timeout */
    while (gpioRead(ECHO_PIN) == 0 && timeout < ECHO_TIMEOUT_US) {
        gpioDelay(1);
        timeout++;
    }
    if (timeout >= ECHO_TIMEOUT_US) {
        fprintf(stderr, "Error: echo timeout waiting for rising edge.\n");
        return ECHO_TIMEOUT_ERROR;
    }

    /* Wait for echo falling edge with timeout */
    while (gpioRead(ECHO_PIN) == 1 && timeout < ECHO_TIMEOUT_US) {
        gpioDelay(1);
        timeout++;
    }
    if (timeout >= ECHO_TIMEOUT_US) {
        fprintf(stderr, "Error: echo timeout waiting for falling edge.\n");
        return ECHO_TIMEOUT_ERROR;
    }

    /* Measure pulse width: 50 µs = 50,000 us */
    int pulse_us = gpioTick() - (int)(timeout * 1000);
    if (pulse_us < 0) {
        fprintf(stderr, "Error: gpioTick() returned negative value.\n");
        return ECHO_TIMEOUT_ERROR;
    }

    /* Convert pulse width to distance in cm */
    float distance = (float)pulse_us * 0.0343f;

    return distance;
}

static int log_distance(float distance)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[80];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(log_file, "%s, %.2f\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error: failed to write to log file.\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void)
{
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        float distance = read_distance();

        if (distance >= 0.0f) {
            if (log_distance(distance) != 0) {
                fprintf(stderr, "Warning: failed to log distance.\n");
            }
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error: failed to read distance.\n");
        }

        /* Sleep for 1 second, but wake early on signal */
        for (int i = 0; i < 10 && running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

