/*
 * VL53L1X Time-of-Flight Distance Sensor Reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   VL53L1X VCC  -> 3.3 V (Pin 1)
 *   VL53L1X GND  -> GND  (Pin 6)
 *   VL53L1X SDA  -> GPIO2 / I2C1 SDA (Pin 3)
 *   VL53L1X SCL  -> GPIO3 / I2C1 SCL (Pin 5)
 *   Relay IN     -> GPIO18 (Pin 11)
 *
 * Build:  gcc -O2 -Wall -o vl53l1x_relay vl53l1x_relay.c -lrt
 * Run:    sudo ./vl53l1x_relay
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define VL53L1X_ADDR   0x29
#define RELAY_PIN      18
#define DISTANCE_THRESHOLD_CM 50.0f
#define POLL_DELAY_US   100000   /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_write_byte(int fd, uint8_t byte)
{
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C short read: got %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* VL53L1X driver                                                      */
/* ------------------------------------------------------------------ */

static int vl53l1x_init(int fd)
{
    /*
     * VL53L1X default address is 0x29 on I2C bus 1.
     * The sensor responds at 0x29 on the default address.
     */
    if (i2c_write_byte(fd, VL53L1X_ADDR) < 0)
        return -1;

    /*
     * Poll the sensor to ensure it is ready.
     * The VL53L1X responds with a 16-bit status register that
     * increments every ~1 ms.  We wait for the first register
     * to be non-zero.
     */
    uint8_t status = 0;
    if (i2c_read_bytes(fd, &status, 1) < 0)
        return -1;

    if (status == 0) {
        fprintf(stderr, "VL53L1X not ready at 0x%02X\n", VL53L1X_ADDR);
        return -1;
    }

    /*
     * The sensor responds with a 16-bit distance register.
     * The first byte is the status byte (0x00), the second byte
     * is the distance register (0x00).
     */
    uint16_t distance = 0;
    if (i2c_read_bytes(fd, &distance, 2) < 0)
        return -1;

    return 0;
}

/*
 * Returns the distance in cm, or -1.0f on error.
 */
static float vl53l1x_distance_cm(int fd)
{
    uint16_t raw = (uint16_t)((distance_high << 8) | distance_low);
    if (raw == 0x0000) {
        fprintf(stderr, "VL53L1X distance register read 0x0000\n");
        return -1.0f;
    }
    return (float)raw / 1023.0f;
}

/* ------------------------------------------------------------------ */
/* Relay control                                                       */
/* ------------------------------------------------------------------ */

static void relay_set(int pin, bool state)
{
    if (ioctl(pin, FIONBIO, NULL) < 0) {
        fprintf(stderr, "ioctl(FIONBIO) failed: %s\n", strerror(errno));
        return;
    }
    if (state)
        write(pin, &state, sizeof(state));
    else
        write(pin, &state, sizeof(state));
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* Signal handling for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the I2C bus for the VL53L1X */
    if (ioctl(i2c_fd, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        fprintf(stderr, "Cannot acquire I2C bus access to 0x%02X: %s\n",
                VL53L1X_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Initialize the VL53L1X sensor */
    if (vl53l1x_init(i2c_fd) < 0) {
        fprintf(stderr, "VL53L1X initialization failed.\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Configure relay pin as output, initially LOW */
    if (ioctl(RELAY_PIN, PI_SET_OUTPUT, 0) < 0) {
        fprintf(stderr, "Cannot set relay pin %d as output: %s\n",
                RELAY_PIN, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    relay_set(RELAY_PIN, false);

    printf("VL53L1X distance sensor reader started.\n");
    printf("  Bus: %s, Addr: 0x%02X, Threshold: %.1f cm\n",
           I2C_BUS, VL53L1X_ADDR, DISTANCE_THRESHOLD_CM);
    printf("  Relay: GPIO%d (BCM)\n", RELAY_PIN);
    printf("Press Ctrl+C to exit.\n\n");

    /* Main polling loop */
    while (g_running) {
        float distance = vl53l1x_distance_cm(i2c_fd);

        if (distance < 0.0f) {
            fprintf(stderr, "Sensor read error; continuing.\n");
        } else {
            printf("Distance: %.2f cm\n", distance);
            if (distance < DISTANCE_THRESHOLD_CM)
                relay_set(RELAY_PIN, true);
            else
                relay_set(RELAY_PIN, false);
        }

        usleep(POLL_DELAY_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    relay_set(RELAY_PIN, false);
    close(i2c_fd);
    printf("Resources released.\n");
    return EXIT_SUCCESS;
}

