/*
 * MPU-6050 Gyroscope reader for Raspberry Pi 3 Model B+
 * Uses the standard I2C bus (/dev/i2c-1) and the documented device address.
 * Reads the x, y, and z rotation rates and logs them to stdout.
 *
 * Build: gcc -O2 -Wall -o mpu6050_gyro mpu6050_gyro.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6050_ADDR   0x68

/* MPU-6050 register addresses */
#define MPU6050_PWR_MGMT_1   0x6B
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_ACCEL_XOUT_L 0x5B
#define MPU6050_GYRO_XOUT_H  0x43
#define MPU6050_GYRO_XOUT_L  0x5D

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg 0x%02X, val 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpu6050_init(int fd)
{
    /* Power down the device */
    if (i2c_write_reg8(fd, MPU6050_PWR_MGMT_1, 0x00) < 0)
        return -1;
    usleep(10000); /* 10 ms power-down delay */

    /* Set the device to normal mode */
    if (i2c_write_reg8(fd, MPU6050_PWR_MGMT_1, 0x01) < 0)
        return -1;

    /* Allow the device to stabilize after power-up */
    usleep(50000);

    return 0;
}

static int read_gyro_data(int fd, float *x, float *y, float *z)
{
    uint8_t buf[6];

    if (i2c_read_reg8(fd, MPU6050_ACCEL_XOUT_H, buf) < 0)
        return -1;

    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    *x = (float)raw_x / 16384.0f;
    *y = (float)raw_y / 16384.0f;
    *z = (float)raw_z / 16384.0f;

    return 0;
}

int main(void)
{
    int fd = -1;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the MPU-6050 device address */
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus access to 0x%02X: %s\n",
                MPU6050_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Initialize the MPU-6050 */
    if (mpu6050_init(fd) < 0) {
        fprintf(stderr, "Failed to initialize MPU-6050\n");
        goto cleanup;
    }

    printf("MPU-6050 initialized. Reading gyroscope data...\n");

    while (g_running) {
        float x, y, z;

        if (read_gyro_data(fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Error reading gyroscope data. Retrying...\n");
            usleep(100000);
            continue;
        }

        printf("x=%.2f  y=%.2f  z=%.2f\n", x, y, z);
        fflush(stdout);

        usleep(10000); /* 10 ms delay between readings */
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    printf("\nExiting cleanly.\n");
    return ret;
}

