/*
 * Automated Plant Watering System for Raspberry Pi 4 Model B
 * Uses the gpiochip4 GPIO controller on a Raspberry Pi 4.
 *
 * Wiring:
 *   Relay module 1 -> GPIO17 (BCM 11)
 *   Relay module 2 -> GPIO18 (BCM 12)
 *   Relay module 3 -> GPIO27 (BCM 13)
 *   Relay module 4 -> GPIO22 (BCM 15)
 *
 * Relay modules are active-low: HIGH = water ON.
 *
 * Build: gcc -o watering watering.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define POLL_INTERVAL_SEC 60
#define LOG_FILE "watering_log.txt"

/* BCM pin numbers for the relay modules */
static const unsigned int relay_pins[NUM_RELAYS] = {17, 18, 27, 22};

/*
 * Full cycle: activate each relay for 5 seconds, then sleep 86 400 seconds.
 * Returns 0 on success, -1 on error.
 */
static int water_cycle(struct gpiod_chip *chip)
{
    int rc = 0;
    int i;

    for (i = 0; i < NUM_RELAYS; i++) {
        if (gpiod_line_set_value(relay_pins[i], 1) < 0) {
            fprintf(stderr, "Error: failed to set relay %u HIGH: %s\n",
                    relay_pins[i], strerror(errno));
            rc = -1;
            break;
        }
        if (gpiod_line_set_value(relay_pins[i], 0) < 0) {
            fprintf(stderr, "Error: failed to set relay %u LOW: %s\n",
                    relay_pins[i], strerror(errno));
            rc = -1;
            break;
        }
        usleep(5000); /* 5 seconds */
    }

    if (rc == 0) {
        rc = gpiod_line_set_value(relay_pins[i], 0);
        if (rc < 0) {
            fprintf(stderr, "Warning: failed to set relay %u LOW at end: %s\n",
                    relay_pins[i], strerror(errno));
        }
    }

    /* Sleep 86 400 seconds (24 hours) */
    struct timespec sleep_ts = {
        .tv_sec = 86400,
        .tv_nsec = 0
    };
    nanosleep(&sleep_ts, NULL);

    return rc;
}

/*
 * Log the start of a watering cycle to the log file.
 * Returns 0 on success, -1 on error.
 */
static int log_cycle(struct gpiod_chip *chip)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char timestamp[32];

    if (t) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    } else {
        snprintf(timestamp, sizeof(timestamp), "1970-01-01 00:00:00");
    }

    fprintf(fp, "%s\n", timestamp);
    fclose(fp);
    return 0;
}

/*
 * Signal handler for graceful shutdown.
 */
static void signal_handler(int sig)
{
    (void)sig;
    fprintf(stderr, "\nCaught signal, cleaning up...\n");
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpiod_line_set_value(relay_pins[i], 0) < 0) {
            fprintf(stderr, "Warning: failed to set relay %u LOW on signal: %s\n",
                    relay_pins[i], strerror(errno));
        }
    }
    gpiod_chip_close(chip);
    exit(0);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    int rc = 1;

    /* Open the gpiochip4 GPIO controller */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Error: cannot open gpiochip4: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request all four relay lines as outputs */
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpiod_line_request_output(chip, relay_pins[i], "watering-system", 0) < 0) {
            fprintf(stderr, "Error: cannot request GPIO %u as output: %s\n",
                    relay_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: failed to install SIGTERM handler: %s\n",
                strerror(errno));
    }

    /* Main watering cycle loop */
    while (rc == 1) {
        if (water_cycle(chip) == 0) {
            if (log_cycle(chip) == 0) {
                printf("Watering cycle complete. Logged to %s\n", LOG_FILE);
            } else {
                fprintf(stderr, "Warning: failed to log watering cycle\n");
            }
        } else {
            fprintf(stderr, "Warning: watering cycle failed, retrying in %d seconds\n",
                    POLL_INTERVAL_SEC);
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL_SEC && rc == 1; i++) {
            sleep(1);
        }
    }

    rc = 0;

cleanup:
    /* Release all GPIO lines */
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpiod_line_set_value(relay_pins[i], 1) < 0) {
            fprintf(stderr, "Warning: failed to release relay %u: %s\n",
                    relay_pins[i], strerror(errno));
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return rc;
}

