#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_RELAY_MODULES 4
#define LOG_FILE "smart_lighting.log"
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define PWM_STEP 1
#define PWM_DUTY_MIN 0
#define PWM_DUTY_MAX PWM_RANGE
#define TIME_PERIOD_SEC 30
#define LOG_FILE_SIZE 1024

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *message) {
    if (!log_file) return -1;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
    return 0;
}

static int setup_gpio(int pin) {
    if (gpioSetMode(pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", pin);
        return -1;
    }
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Error: Failed to write GPIO %d to LOW\n", pin);
        return -1;
    }
    return 0;
}

static int set_pwm_duty(int pin, int duty) {
    if (duty < 0 || duty > PWM_RANGE) {
        fprintf(stderr, "Error: Duty cycle %d out of range (0-%d)\n", duty, PWM_RANGE);
        return -1;
    }
    if (gpioPWM(pin, duty) != 0) {
        fprintf(stderr, "Error: Failed to set PWM on GPIO %d to %d\n", pin, duty);
        return -1;
    }
    return 0;
}

static int init_pwm(void) {
    for (int i = 0; i < NUM_RELAY_MODULES; i++) {
        if (gpioSetPWMfrequency(i, PWM_FREQUENCY) != 0) {
            fprintf(stderr, "Error: Failed to set PWM frequency on GPIO %d\n", i);
            return -1;
        }
        if (set_pwm_duty(i, PWM_DUTY_MIN) != 0) return -1;
    }
    return 0;
}

static int init_gpio(void) {
    for (int i = 0; i < NUM_RELAY_MODULES; i++) {
        if (setup_gpio(i) != 0) return -1;
    }
    return 0;
}

static void cleanup(void) {
    for (int i = 0; i < NUM_RELAY_MODULES; i++) {
        if (gpioPWM(i, 0) != 0) {
            fprintf(stderr, "Warning: Failed to stop PWM on GPIO %d\n", i);
        }
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        fprintf(stderr, "Error: GPIO initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_pwm() != 0) {
        fprintf(stderr, "Error: PWM initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Smart lighting sunrise started. Press Ctrl+C to exit.\n");

    while (running) {
        for (int i = 0; i < NUM_RELAY_MODULES; i++) {
            if (set_pwm_duty(i, PWM_DUTY_MIN + (i * PWM_STEP)) != 0) {
                fprintf(stderr, "Error: Failed to set PWM duty cycle for GPIO %d\n", i);
                break;
            }
        }
        if (log_event("Sunrise started") != 0) {
            fprintf(stderr, "Error: Failed to log sunrise event\n");
            break;
        }
        sleep(TIME_PERIOD_SEC);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

