static void buffer_print(void);

/* ----------------------------- Signal handler ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- SPI init ---------------------------------- */

static int init_spi(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

/* ----------------------------- GPIO init -------------------------------- */

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise: %s\n", strerror(errno));
        return -1;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d): %s\n", LED_GPIO, strerror(errno));
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(LED_GPIO, 0) < 0) {
        fprintf(stderr, "gpioWrite(%d, 0): %s\n", LED_GPIO, strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* ----------------------------- MPU-6050 read ----------------------------- */

static int read_mpu6050(int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t reg = MPU6050_REG_ACCEL_XOUT_H;
    uint8_t data[6];

    /*
     * Read 6 bytes starting at the specified register.
     * The MPU-6050 sends X,Y,Z in little-endian order.
     */
    if (spiXfer(g_spi_fd, (char *)&reg, (char *)data, 6) != 6) {
        fprintf(stderr, "spiXfer: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((data[0] << 8) | data[1]);
    *y = (int16_t)((data[2] << 8) | data[3]);
    *z = (int16_t)((data[4] << 8) | data[5]);

    return 0;
}

/* ----------------------------- Circular buffer ----------------------------- */

static void buffer_add(int16_t x, int16_t y, int16_t z)
{
    g_buffer[g_buffer_head] = x;
    g_buffer[g_buffer_head + 1] = y;
    g_buffer[g_buffer_head + 2] = z;
    g_buffer_head = (g_buffer_head + 3) % BUFFER_SIZE;
    if (g_buffer_count < BUFFER_SIZE)
        g_buffer_count++;
}

static void buffer_print(void)
{
    printf("Timestamp,X,Y,Z\n");
    for (int i = 0; i < g_buffer_count; i++) {
        int idx = (g_buffer_head + i) % BUFFER_SIZE;
        int x = g_buffer[idx];
        int y = g_buffer[idx + 1];
        int z = g_buffer[idx + 2];
        printf("%d, %d, %d, %d\n", idx, x, y, z);
    }
    fflush(stdout);
}

/* ----------------------------- Main ------------------------------------- */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (init_spi() < 0)
        return EXIT_FAILURE;

    if (init_gpio() < 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
        return EXIT_FAILURE;
    }

    printf("MPU-6050 monitoring started. Press Ctrl-C to exit.\n");

    while (g_running) {
        int16_t x, y, z;
        if (read_mpu6050(&x, &y, &z) < 0) {
            fprintf(stderr, "SPI read error; retrying in 1 s...\n");
            gpioDelay(1000000);
            continue;
        }

        buffer_add(x, y, z);

        if (fabsf(x) > THRESHOLD_DEG_S ||
            fabsf(y) > THRESHOLD_DEG_S ||
            fabsf(z) > THRESHOLD_DEG_S) {
            printf("X: %6.2f, Y: %6.2f, Z: %6.2f  -> threshold exceeded\n",
                   x, y, z);
            if (gpioWrite(LED_GPIO, 1) < 0)
                fprintf(stderr, "LED on: %s\n", strerror(errno));
            gpioDelay(BLINK_MS * 1000);
            if (gpioWrite(LED_GPIO, 0) < 0)
                fprintf(stderr, "LED off: %s\n", strerror(errno));
        }

        buffer_print();

        gpioDelay(10000); /* 10 ms */
    }

    /* ----------------------------- Graceful shutdown ----------------------------- */
    printf("\nShutting down...\n");
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

