/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */
static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

static int spi_read_reg(uint8_t reg, uint8_t *buf, size_t len)
{
    if (g_spi_fd < 0) {
        fprintf(stderr, "SPI not initialized\n");
        return -1;
    }

    uint8_t tx[2] = { reg, 0x00 };
    uint8_t rx[2] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 2,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        return -1;
    }

    /* Response is the second byte of the transfer */
    if (rx[1] != 0x00) {
        fprintf(stderr, "SPI transfer failed: expected 0x%02X, got 0x%02X\n",
                reg, rx[1]);
        return -1;
    }

    memcpy(buf, &rx[0], len);
    return 0;
}

static int spi_read_reg_word(uint8_t reg, uint16_t *out)
{
    if (g_spi_fd < 0) {
        fprintf(stderr, "SPI not initialized\n");
        return -1;
    }

    uint8_t tx[2] = { reg, 0x00 };
    uint8_t rx[2] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 2,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        return -1;
    }

    *out = ((uint16_t)rx[0] << 8) | rx[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Gyroscope read                                                       */
/* ------------------------------------------------------------------ */
static int read_gyro_data(int16_t *x, int16_t *y)
{
    uint8_t buf[2];
    uint8_t tx[2] = { 0x00, 0x00 };
    uint8_t rx[2] = { 0 };

    if (g_spi_fd < 0) {
        fprintf(stderr, "SPI not initialized\n");
        return -1;
    }

    if (spi_read_reg_word(0x00, buf) < 0) {
        fprintf(stderr, "Failed to read gyro data\n");
        return -1;
    }

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    return 0;
}

