    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s,%d,%d\n", timestamp, x, y) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        perror("fflush");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(g_log_fp, "# timestamp,raw_x,raw_y\n");
    fflush(g_log_fp);

    int retries = 0;
    int consecutive_failures = 0;

    while (g_running) {
        int16_t x, y;

        if (read_gyro_data(&x, &y) < 0) {
            consecutive_failures++;
            if (consecutive_failures >= MAX_RETRIES) {
                fprintf(stderr, "Max retries reached, exiting\n");
                break;
            }
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        if (log_data(x, y) < 0) {
            fprintf(stderr, "Logging failed, continuing\n");
        }

        usleep(SAMPLE_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

