/*
 * ADXRS290 dual-axis gyroscope reader for Raspberry Pi Zero W.
 *
 * Wiring (BCM numbering):
 *   SPI0 SCLK  -> GPIO11 (BCM)
 *   SPI0 MOSI  -> GPIO10 (BCM)
 *   SPI0 MISO  -> GPIO9  (BCM)
 *   SPI0 CE0  -> GPIO8  (BCM)  (chip-enable)
 *   LED        -> GPIO17 (BCM)
 *
 * Build:  gcc -O2 -Wall -Wextra -o gyro_reader gyro_reader.c -lrt -lpthread
 * Run:    sudo ./gyro_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pthread.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0
#define SPI_CPOL        0
#define SPI_CPHA        0
#define SPI_FLAGS       0

#define GPIO_LED        17
#define THRESHOLD_DEG_S 20.0f
#define BUFFER_SIZE     100
#define SAMPLE_PERIOD_NS (1000000000ULL / THRESHOLD_DEG_S)

#define ADXRS290_REG_X_MSB  0x00
#define ADXRS290_REG_X_LSB  0x01
#define ADXRS290_REG_Y_MSB  0x02
#define ADXRS290_REG_Y_LSB  0x03
#define ADXRS290_REG_Z_MSB  0x04
#define ADXRS290_REG_Z_LSB  0x05

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static pthread_mutex_t g_buffer_mutex = PTHREAD_MUTEX_INITIALIZER;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single 16-bit register from the ADXRS290.
 * Returns 0 on success, -1 on error.
 */
static int adxrs290_read_reg(int fd, uint8_t reg_msb, uint8_t reg_lsb,
                              int16_t *out)
{
    uint8_t tx[3] = { reg_msb, reg_lsb, 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
        .tx_nbits      = 0,
        .rx_nbits      = 0,
        .pad           = 0
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    *out = (int16_t)(((uint16_t)rx[0] << 8) | rx[1]);
    return 0;
}

static int adxrs290_init(int fd)
{
    /*
     * Write MSB of register address to 1 to read.
     * ADXRS290: 0x00 -> 0x01.
     */
    if (ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        return -1;
    }
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        return -1;
    }
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        return -1;
    }
    if (ioctl(fd, SPI_IOC_WR_CS_CHANGE, &0) < 0) {
        fprintf(stderr, "SPI_IOC_WR_CS_CHANGE failed: %s\n", strerror(errno));
        return -1;
    }
    if (ioctl(fd, SPI_IOC_WR_CS_SET_TO_IDLE, &0) < 0) {
        fprintf(stderr, "SPI_IOC_WR_CS_SET_TO_IDLE failed: %s\n", strerror(errno));
        return -1;
    }

    /*
     * Read the device ID to confirm the chip is an ADXRS290.
     */
    uint8_t id_buf[2] = { 0x00, 0x00 };
    if (ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        return -1;
    }
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        return -1;
    }
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        return -1;
    }
    if (ioctl(fd, SPI_IOC_WR_CS_CHANGE, &0) < 0) {
        fprintf(stderr, "SPI_IOC_WR_CS_CHANGE failed: %s\n", strerror(errno));
        return -1;
    }
    if (ioctl(fd, SPI_IOC_WR_CS_SET_TO_IDLE, &0) < 0) {
        fprintf(stderr, "SPI_IOC_WR_CS_SET_TO_IDLE failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    int16_t raw_x, raw_y, raw_z;

    if (adxrs290_read_reg(fd, ADXRS290_REG_X_MSB, ADXRS290_REG_X_LSB, &raw_x) < 0)
        return -1;
    if (adxrs290_read_reg(fd, ADXRS290_REG_Y_MSB, ADXRS290_REG_Y_LSB, &raw_y) < 0)
        return -1;
    if (adxrs290_read_reg(fd, ADXRS290_REG_Z_MSB, ADXRS290_REG_Z_LSB, &raw_z) < 0)
        return -1;

    *x = (int16_t)((raw_x << 8) | raw_x >> 8);
    *y = (int16_t)((raw_y << 8) | raw_y >> 8);
    *z = (int16_t)((raw_z << 8) | raw_z >> 8);

    return 0;
}

static void buffer_add(pthread_mutex_t *mutex, int16_t *data, int count)
{
    pthread_mutex_lock(mutex);
    for (int i = 0; i < count; i++) {
        data[i] = data[i + BUFFER_SIZE - count];
    }
    pthread_mutex_unlock(mutex);
}

static void buffer_print(pthread_mutex_t *mutex, int16_t *data, int count)
{
    pthread_mutex_lock(mutex);
    printf("Buffer: ");
    for (int i = 0; i < count; i++) {
        printf("%d ", data[i]);
    }
    printf("\n");
    pthread_mutex_unlock(mutex);
}

static void buffer_print_threshold(pthread_mutex_t *mutex, int16_t *data, int count,
                                   int16_t threshold)
{
    pthread_mutex_lock(mutex);
    printf("Threshold exceeded: ");
    for (int i = 0; i < count; i++) {
        if (data[i] > threshold) {
            printf("%d ", data[i]);
        }
    }
    printf("\n");
    pthread_mutex_unlock(mutex);
}

static void signal_handler_thread(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler_thread;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open SPI device */
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Configure SPI mode */
    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Configure bits per word */
    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Configure speed */
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Configure CS */
    uint8_t cs_change = 0;
    if (ioctl(g_spi_fd, SPI_IOC_WR_CS_CHANGE, &cs_change) < 0) {
        fprintf(stderr, "SPI_IOC_WR_CS_CHANGE failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Initialize ADXRS290 */
    if (adxrs290_init(g_spi_fd) < 0) {
        fprintf(stderr, "ADXRS290 initialization failed.\n");
        goto cleanup;
    }

    /* Create circular buffer */
    pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
    buffer_init(&buffer_mutex, BUFFER_SIZE);

    /* Initialize GPIO LED */
    if (gpio_led_init(GPIO_LED) < 0) {
        fprintf(stderr, "GPIO LED initialization failed.\n");
        goto cleanup;
    }
    gpio_led_set(GPIO_LED, 0);

    /* Main loop */
    while (g_running) {
        int16_t x, y, z;
        if (read_gyro_data(g_spi_fd, &x, &y, &z) == 0) {
            buffer_add(&buffer_mutex, &x, BUFFER_SIZE);
            buffer_print(&buffer_mutex, BUFFER_SIZE, BUFFER_SIZE);
            buffer_print_threshold(&buffer_mutex, BUFFER_SIZE, BUFFER_SIZE, THRESHOLD_DEG_S);
        } else {
            fprintf(stderr, "Failed to read gyro data.\n");
        }
        usleep(SAMPLE_PERIOD_NS);
    }

    /* Cleanup */
    gpio_led_set(GPIO_LED, 0);
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    pthread_mutex_destroy(&buffer_mutex);
    pthread_mutex_destroy(&g_buffer_mutex);
    return EXIT_SUCCESS;

cleanup:
    /* Ensure LED is off */
    gpio_led_set(GPIO_LED, 0);
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    return EXIT_FAILURE;
}

