/*
 * Smart Sunset Simulator for Raspberry Pi Zero W
 * Three relay-controlled lamps (BCM GPIO17, GPIO18, GPIO27)
 * Fades sequentially from full brightness to off over a user-defined
 * duration (1–3600 seconds).  Uses hardware PWM at 100 Hz on BCM17,
 * BCM18, BCM27.  No software PWM is used; the duty cycle is
 * directly controlled by the hardware PWM hardware.
 *
 * Build:  gcc -O2 -Wall -Wextra -o sunset_sim sunset_sim.c -lpigpio -lrt
 * Run:    sudo ./sunset_sim [duration_seconds]
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define NUM_LAMPS 3
#define GPIO_LAMPS {17, 18, 27}
#define PWM_FREQUENCY 100
#define PWM_RANGE     255
#define DIM_DELAY_US  10000   /* 10 ms between dimming steps */
#define DIM_STEP_US   1000    /* 1 ms per step */
#define DIM_MAX_US    (PWM_RANGE * DIM_STEP_US)
#define DIM_MIN_US    (0)
#define DIM_MAX_US    (PWM_RANGE)
#define DIM_STEP_US   (DIM_MAX_US - DIM_MIN_US)
#define DIM_DURATION_US (DIM_MAX_US * (duration_seconds / 3600.0))
#define MAX_DIM_US     (DIM_MAX_US)
#define MAX_DIM_STEP_US (DIM_MAX_US / NUM_LAMPS)

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Fade a single lamp from full brightness to off over the given duration.
 * Returns 0 on success, -1 on error.
 */
static int fade_lamp(int gpio, int duration_seconds)
{
    int step = (int)((duration_seconds / DIM_DURATION_US) * DIM_STEP_US);
    int dim_us = DIM_MIN_US + step;

    if (dim_us > MAX_DIM_US)
        dim_us = MAX_DIM_US;

    if (dim_us < DIM_MIN_US)
        dim_us = DIM_MIN_US;

    if (dim_us > DIM_MAX_US)
        dim_us = DIM_MAX_US;

    if (dim_us == 0) {
        gpioPWM(gpio, 0);
        return 0;
    }

    if (gpioPWM(gpio, dim_us) != 0) {
        fprintf(stderr, "Error: gpioPWM(%d, %d) failed\n", gpio, dim_us);
        return -1;
    }

    printf("Lamp %d fading from %d to %d over %d seconds\n",
           gpio, dim_us, dim_us + 1, duration_seconds);
    fflush(stdout);

    return 0;
}

int main(int argc, char *argv[])
{
    int duration_seconds = 0;
    int rc = EXIT_FAILURE;

    if (argc > 1) {
        duration_seconds = atoi(argv[1]);
        if (duration_seconds <= 0 || duration_seconds > 3600) {
            fprintf(stderr, "Error: duration must be 1–3600 s\n");
            return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_LAMPS; i++) {
        if (gpioSetMode(GPIO_LAMPS[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode(%d) failed\n", GPIO_LAMPS[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(GPIO_LAMPS[i], PWM_FREQUENCY) != 0) {
            fprintf(stderr, "Error: gpioSetPWMfrequency(%d, %d) failed\n",
                    GPIO_LAMPS[i], PWM_FREQUENCY);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(GPIO_LAMPS[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Error: gpioSetPWMrange(%d, %d) failed\n",
                    GPIO_LAMPS[i], PWM_RANGE);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Smart Sunset Simulator started.  Lamps: GPIO%d, GPIO%d, GPIO%d\n",
           GPIO_LAMPS[0], GPIO_LAMPS[1], GPIO_LAMPS[2]);
    fflush(stdout);

    int lamp_index = 0;
    int dim_step = DIM_MIN_US;

    while (g_running) {
        if (fade_lamp(GPIO_LAMPS[lamp_index], duration_seconds) != 0) {
            fprintf(stderr, "Error: lamp %d failed to fade\n", lamp_index + 1);
            break;
        }

        lamp_index = (lamp_index + 1) % NUM_LAMPS;
        if (lamp_index == 0)
            dim_step = DIM_MAX_US;

        if (dim_step > DIM_MAX_US)
            dim_step = DIM_MAX_US;

        if (gpioDelay(DIM_DELAY_US) != 0) {
            fprintf(stderr, "Error: gpioDelay failed\n");
            break;
        }
    }

    printf("\nShutting down...\n");
    fflush(stdout);

    for (int i = 0; i < NUM_LAMPS; i++) {
        if (gpioPWM(GPIO_LAMPS[i], 0) != 0) {
            fprintf(stderr, "Warning: gpioPWM(%d, 0) failed after shutdown\n",
                    GPIO_LAMPS[i]);
        }
    }

    gpioTerminate();
    rc = EXIT_SUCCESS;
    return rc;
}

