#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RED_PIN 17
#define YELLOW_PIN 22
#define GREEN_PIN 23
#define BLUE_PIN 24

#define RED_ON_TIME_SEC 10
#define RED_ON_SEC 2
#define RED_OFF_SEC 10
#define RED_OFF_SEC 3
#define YELLOW_ON_SEC 10
#define YELLOW_ON_SEC 2
#define YELLOW_OFF_SEC 3
#define YELLOW_OFF_SEC 4

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    for (int i = 0; i < 4; i++) {
        gpioWrite(RED_PIN, 0);
        gpioWrite(YELLOW_PIN, 0);
        gpioWrite(GREEN_PIN, 0);
        gpioWrite(BLUE_PIN, 0);
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install signal handler.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0 ||
            gpioSetMode(YELLOW_PIN, PI_OUTPUT) != 0 ||
            gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
            gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d mode.\n", i);
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpioWrite(RED_PIN, 0) != 0 ||
            gpioWrite(YELLOW_PIN, 0) != 0 ||
            gpioWrite(GREEN_PIN, 0) != 0 ||
            gpioWrite(BLUE_PIN, 0) != 0) {
            fprintf(stderr, "Error: failed to initialize GPIO %d to LOW.\n", i);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    printf("Traffic light simulation started. Press Ctrl+C to exit.\n");

    while (running) {
        if (gpioWrite(RED_PIN, 1) != 0) {
            fprintf(stderr, "Error: failed to energize RED.\n");
            break;
        }
        printf("Red ON\n");
        fflush(stdout);

        if (gpioWrite(RED_PIN, 0) != 0) {
            fprintf(stderr, "Error: failed to de-energize RED.\n");
            break;
        }
        printf("Red OFF\n");
        fflush(stdout);

        if (gpioWrite(YELLOW_PIN, 1) != 0) {
            fprintf(stderr, "Error: failed to energize YELLOW.\n");
            break;
        }
        printf("Yellow ON\n");
        fflush(stdout);

        if (gpioWrite(YELLOW_PIN, 0) != 0) {
            fprintf(stderr, "Error: failed to de-energize YELLOW.\n");
            break;
        }
        printf("Yellow OFF\n");
        fflush(stdout);

        if (gpioWrite(GREEN_PIN, 1) != 0) {
            fprintf(stderr, "Error: failed to energize GREEN.\n");
            break;
        }
        printf("Green ON\n");
        fflush(stdout);

        if (gpioWrite(GREEN_PIN, 0) != 0) {
            fprintf(stderr, "Error: failed to de-energize GREEN.\n");
            break;
        }
        printf("Green OFF\n");
        fflush(stdout);

        if (gpioWrite(BLUE_PIN, 1) != 0) {
            fprintf(stderr, "Error: failed to energize BLUE.\n");
            break;
        }
        printf("Blue ON\n");
        fflush(stdout);

        if (gpioWrite(BLUE_PIN, 0) != 0) {
            fprintf(stderr, "Error: failed to de-energize BLUE.\n");
            break;
        }
        printf("Blue OFF\n");
        fflush(stdout);

        if (running) {
            sleep(RED_ON_SEC);
            if (!running) break;
            if (gpioWrite(RED_PIN, 1) != 0) {
                fprintf(stderr, "Error: failed to de-energize RED.\n");
                break;
            }
            printf("Red ON\n");
            fflush(stdout);
            if (gpioWrite(RED_PIN, 0) != 0) {
                fprintf(stderr, "Error: failed to de-energize RED.\n");
                break;
            }
            printf("Red OFF\n");
            fflush(stdout);
            if (gpioWrite(YELLOW_PIN, 1) != 0) {
                fprintf(stderr, "Error: failed to energize YELLOW.\n");
                break;
            }
            printf("Yellow ON\n");
            fflush(stdout);
            if (gpioWrite(YELLOW_PIN, 0) != 0) {
                fprintf(stderr, "Error: failed to de-energize YELLOW.\n");
                break;
            }
            printf("Yellow OFF\n");
            fflush(stdout);
            if (gpioWrite(GREEN_PIN, 1) != 0) {
                fprintf(stderr, "Error: failed to energize GREEN.\n");
                break;
            }
            printf("Green ON\n");
            fflush(stdout);
            if (gpioWrite(GREEN_PIN, 0) != 0) {
                fprintf(stderr, "Error: failed to de-energize GREEN.\n");
                break;
            }
            printf("Green OFF\n");
            fflush(stdout);
            if (gpioWrite(BLUE_PIN, 1) != 0) {
                fprintf(stderr, "Error: failed to energize BLUE.\n");
                break;
            }
            printf("Blue ON\n");
            fflush(stdout);
            if (gpioWrite(BLUE_PIN, 0) != 0) {
                fprintf(stderr, "Error: failed to de-energize BLUE.\n");
                break;
            }
            printf("Blue OFF\n");
            fflush(stdout);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

