#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18
#define LED_PIN 23
#define LOG_FILE "flame_log.txt"
#define SAMPLE_INTERVAL_US 50000  /* 50 ms */
#define CONSECUTIVE_LOW_COUNT 3

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_flame_event(void) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[64];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Flame Detected\n", timestamp);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file not open.\n");
    }
}

static void activate_buzzer(void) {
    if (gpioWrite(BUZZER_PIN, 1) != 0) {
        fprintf(stderr, "Error: Failed to activate buzzer.\n");
        return;
    }
    gpioDelay(100000);  /* 100 ms */
    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Error: Failed to deactivate buzzer.\n");
    }
}

static void activate_led(void) {
    if (gpioWrite(LED_PIN, 1) != 0) {
        fprintf(stderr, "Error: Failed to activate LED.\n");
        return;
    }
    gpioDelay(100000);  /* 100 ms */
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: Failed to deactivate LED.\n");
    }
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set flame sensor pin mode.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set buzzer pin mode.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set LED pin mode.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Error: Failed to initialise buzzer state.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: Failed to initialise LED state.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    int consecutive_low_count = 0;
    int last_state = gpioRead(FLAME_SENSOR_PIN);

    while (running) {
        int sensor_value = gpioRead(FLAME_SENSOR_PIN);
        if (sensor_value < 0) {
            fprintf(stderr, "Error: Failed to read flame sensor.\n");
            break;
        }

        if (sensor_value == 0) {
            consecutive_low_count++;
            if (consecutive_low_count >= CONSECUTIVE_LOW_COUNT) {
                consecutive_low_count = 0;
                last_state = sensor_value;

                if (last_state == 0) {
                    log_flame_event();
                    activate_buzzer();
                    activate_led();
                    printf("Flame detected! Activating buzzer and LED.\n");
                }
            }
        } else {
            consecutive_low_count = 0;
            last_state = 0;
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    printf("Exiting gracefully.\n");
    return EXIT_SUCCESS;
}

