}

static int log_dispose(int solenoid_pin, int duration_ms) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, S1: %d, S2: %d, Duration: %d ms\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                solenoid_pin, solenoid_pin, duration_ms);
    } else {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
    }
    fclose(fp);
    return 0;
}

