    if (gpioWrite(pin, 1) < 0) {
        fprintf(stderr, "Error activating solenoid %d: %s\n", pin, strerror(errno));
        return -1;
    }
    return 0;
}

static int deactivate_solenoid(int pin) {
    if (gpioWrite(pin, 0) < 0) {
        fprintf(stderr, "Error deactivating solenoid %d: %s\n", pin, strerror(errno));
        return -1;
    }
    return 0;
}

