#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_MS 50
#define POLL_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int setup_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: failed to set pull-down on GPIO %d.\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", RELAY_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize relay state on GPIO %d.\n", RELAY_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_touch_sensor(void) {
    int value = gpioRead(TOUCH_SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Error: gpioRead failed on GPIO %d.\n", TOUCH_SENSOR_PIN);
        return -1;
    }
    return value;
}

static int toggle_relay(void) {
    int relay_state = gpioRead(RELAY_PIN);
    if (relay_state < 0) {
        fprintf(stderr, "Error: gpioRead failed on GPIO %d.\n", RELAY_PIN);
        return -1;
    }

    if (gpioWrite(RELAY_PIN, relay_state) != 0) {
        fprintf(stderr, "Error: gpioWrite failed on GPIO %d.\n", RELAY_PIN);
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int touch_detected = read_touch_sensor();
        if (touch_detected < 0) {
            fprintf(stderr, "Error: failed to read touch sensor.\n");
            break;
        }

        if (touch_detected == 1) {
            if (toggle_relay() != 0) {
                fprintf(stderr, "Error: failed to toggle relay.\n");
                break;
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    /* Graceful cleanup */
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

