}

/* ------------------------------------------------------------------ */
/* Initialize the TCS34725 sensor                                       */
/* ------------------------------------------------------------------ */
static int tcs34725_init(int handle)
{
    /*
     * Configure the TCS34725 for 154 ms integration time.
     * The datasheet specifies a 14-bit integration time for this
     * configuration.  We use the full 15-bit range to get the full
     * 14-bit resolution.
     */
    if (tcs34725_write_reg(handle, TCS34725_REG_CONFIG,
                            TCS34725_CONFIG_IT) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read calibrated color values from the TCS34725                        */
/* ------------------------------------------------------------------ */
static int tcs34725_read_color(int handle, uint16_t *c, uint16_t *r,
                                uint16_t *g, uint16_t *b)
{
    uint16_t raw_c, raw_r, raw_g, raw_b;

    if (tcs34725_read_reg(handle, TCS34725_REG_DATA, &raw_c) != 0)
        return -1;
    if (tcs34725_read_reg(handle, TCS34725_REG_DATA, &raw_r) != 0)
        return -1;
    if (tcs34725_read_reg(handle, TCS34725_REG_DATA, &raw_g) != 0)
        return -1;
    if (tcs34725_read_reg(handle, TCS34725_REG_DATA, &raw_b) != 0)
        return -1;

    *c = (uint16_t)(raw_c >> 2);
    *r = (uint16_t)(raw_r >> 2);
    *g = (uint16_t)(raw_g >> 2);
    *b = (uint16_t)(raw_b >> 2);

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a CSV row                                                       */
/* ------------------------------------------------------------------ */
static void log_csv_row(FILE *fp, uint16_t c, uint16_t r,
                        uint16_t g, uint16_t b)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return;
    }

    if (fprintf(fp, "%s,%u,%u,%u,%u\n", ts, c, r, g, b) < 0) {
        fprintf(stderr, "Error: fprintf to CSV failed\n");
        return;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error: fflush failed\n");
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_csv_fp != NULL) {
        fclose(g_csv_fp);
        g_csv_fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C --- */
    g_i2c_handle = i2cOpen(I2C_BUS, TCS34725_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- init sensor --- */
    if (tcs34725_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: TCS34725 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- open CSV --- */
    g_csv_fp = fopen(CSV_FILENAME, "a");
    if (g_csv_fp == NULL) {
        fprintf(stderr, "Error: cannot open %s for appending\n", CSV_FILENAME);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- write header if file is empty --- */
    fseek(g_csv_fp, 0, SEEK_END);
    if (ftell(g_csv_fp) == 0) {
        fprintf(g_csv_fp, "timestamp,c,r,g,b\n");
        fflush(g_csv_fp);
    }

    /* --- signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed\n");
    }

    /* --- main loop --- */
    while (g_running) {
        uint16_t c, r, g, b;

        if (tcs34725_read_color(g_i2c_handle, &c, &r, &g, &b) != 0) {
            fprintf(stderr, "Warning: sensor read failed; continuing\n");
        } else {
            log_csv_row(g_csv_fp, c, r, g, b);
        }

        /* Sleep 500 ms, but wake early on signal */
        for (int i = 0; i < SAMPLE_INTERVAL_US && g_running; i++)
            gpioSleep(PI_TIME_RELATIVE, 0, 100000); /* 100 ms */
    }

    /* --- graceful shutdown --- */
    fprintf(stderr, "\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

