/*
 * KY-033 IR Obstacle Avoidance Sensor Monitor for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   KY-033 VCC  -> 3.3 V (Pin 1)
 *   KY-033 GND  -> GND  (Pin 6)
 *   KY-033 OUT  -> GPIO17 (Pin 11)
 *
 * The KY-033 is active-low: a LOW level indicates motion.
 *
 * Build:  gcc -O2 -Wall -Wextra -o ky033_monitor ky033_monitor.c
 * Run:    sudo ./ky033_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>

#define GPIO_PIN          17
#define DEBOUNCE_MS       200
#define VIDEO_CAPTURE_DIR "/home/pi/videos"
#define LOG_FILE          "/home/pi/logs/motion_log.txt"

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int initialize_gpio(void)
{
    if (gpio_init() < 0) {
        fprintf(stderr, "gpio_init() failed\n");
        return -1;
    }
    return 0;
}

static int read_gpio(int pin)
{
    int level = gpio_read(pin);
    if (level < 0) {
        fprintf(stderr, "gpio_read(%d) failed\n", pin);
        return -1;
    }
    return level;
}

static int trigger_motion(void)
{
    int level = read_gpio(GPIO_PIN);
    if (level < 0)
        return -1;

    if (level == 0) {
        /* KY-033 is active-low: LOW indicates motion */
        return 0;
    }

    /* KY-033 is active-high: HIGH indicates motion */
    return 1;
}

static int capture_video(const char *output_path)
{
    int status = system(
        "raspivid -o " VIDEO_CAPTURE_DIR "/%Y%m%d_%H%M%S.h264 "
        "--width 640 --height 480 --fps 30 "
        "--min-fast-threshold 0 "
        "--no-bayer "
        "--timeout 0 "
        "--output-prefix " VIDEO_CAPTURE_DIR "/%Y%m%d_%H%M%S "
        "--timestamp-prefix " VIDEO_CAPTURE_DIR "/%Y%m%d_%H%M%S "
        "--timestamp-suffix "" "
        "--max-file-size 0 "
        "--time-limit 0 "
        "--quiet "
        "--overwrite
    );

    if (status != 0) {
        fprintf(stderr, "raspivid failed with status %d\n", status);
        return -1;
    }
    return 0;
}

static int log_motion_event(const char *filename)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("localtime_r()");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s Motion event detected!\n", timestamp) < 0) {
        perror("fprintf()");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose()");
        return -1;
    }

    return 0;
}

int main(void)
{
    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    if (initialize_gpio() != 0)
        return EXIT_FAILURE;

    printf("KY-033 obstacle avoidance monitor started.\n");
    printf("GPIO%d: active-low, debounce %d ms, capture %s\n",
           GPIO_PIN, DEBOUNCE_MS, VIDEO_CAPTURE_DIR);
    printf("Log file: %s\n", LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        if (trigger_motion()) {
            if (capture_video(VIDEO_CAPTURE_DIR) != 0) {
                fprintf(stderr, "Video capture failed; continuing.\n");
            }
            if (log_motion_event(VIDEO_CAPTURE_DIR) != 0) {
                fprintf(stderr, "Motion event logging failed; continuing.\n");
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < 100 && g_running; i++)
            usleep(100000);
    }

    printf("\nShutting down...\n");
    gpio_close();
    return EXIT_SUCCESS;
}

