/*
 * MPU-6050 Gyroscope Data Logger for Raspberry Pi 4 Model B
 * Uses pigpio for I2C communication.
 *
 * Wiring:
 *   MPU-6050 VCC -> 3.3V (Pin 1)
 *   MPU-6050 GND -> GND (Pin 6)
 *   MPU-6050 SDA -> GPIO2 (Pin 3)
 *   MPU-6050 SCL -> GPIO3 (Pin 5)
 *   MPU-6050 AD0 -> GND (Pin 6)
 *
 * Build: gcc -o gyro_logger gyro_logger.c -lpigpio -lrt
 * Run:   sudo ./gyro_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x68
#define LOG_FILE "gyro_log.csv"
#define MAX_RETRIES 3
#define SAMPLE_INTERVAL_US 10000  /* 10 ms */
#define MAX_RETRIES_REINIT 3

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* MPU-6050 register addresses */
#define MPU6050_REG_PWR_MGMT_1 0x6B
#define MPU6050_REG_ACCEL_XOUT_H 0x3B
#define MPU6050_REG_ACCEL_YOUT_H 0x3C
#define MPU6050_REG_ACCEL_ZOUT_H 0x3D
#define MPU6050_REG_GYRO_XOUT_H  0x43
#define MPU6050_REG_GYRO_YOUT_H  0x44
#define MPU6050_REG_GYRO_ZOUT_H  0x45

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int initialize_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    int retries = 0;

    while (retries < MAX_RETRIES_REINIT) {
        int bytes = i2cReadI2CBlockData(i2c_handle, MPU6050_REG_ACCEL_XOUT_H, buf, 6);
        if (bytes == 6) {
            *x = (int16_t)((buf[1] << 8) | buf[0]);
            *y = (int16_t)((buf[3] << 8) | buf[2]);
            *z = (int16_t)((buf[5] << 8) | buf[4]);
            return 0;
        }
        fprintf(stderr, "I2C read error (attempt %d/%d): %d\n", retries + 1, MAX_RETRIES_REINIT, bytes);
        retries++;
        gpioDelay(10000); /* 10 ms backoff */
    }
    return -1;
}

static int log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (initialize_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X_degps,Y_degps,Z_degps\n");
        fflush(log_file);
    }

    printf("Logging gyroscope data to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (!terminate) {
        int16_t x, y, z;
        if (read_gyro_data(&x, &y, &z) == 0) {
            if (log_data(log_file, x, y, z) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading gyroscope data\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

