#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY_1_PIN 4
#define RELAY_2_PIN 17
#define RELAY_3_PIN 27
#define RELAY_4_PIN 22
#define LOG_FILE "irrigation_log.txt"
#define POLL_INTERVAL_US 5000000  /* 5 seconds */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

/*
 * Returns a random moisture reading between 0 and 100, seeded with the
 * current time.  The relays are driven active-low (LOW = ON).
 */
static int simulate_moisture_reading(void) {
    time_t rawtime;
    struct tm timeinfo;
    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    int moisture = (int)((timeinfo.tm_year - 1980) * 100 +
                         (timeinfo.tm_mon + 1) * 10 +
                         timeinfo.tm_mday * 100 +
                         timeinfo.tm_hour * 100 +
                         timeinfo.tm_min * 10 +
                         timeinfo.tm_sec * 100);
    return moisture;
}

/*
 * Drive the relay: active-low (LOW = ON).
 */
static void drive_relay(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Error: gpioWrite(%d, %d) failed\n", pin, state);
    }
}

/*
 * Append a line to the log file.
 */
static void log_data(int moisture, int relay_state1, int relay_state2,
                     int relay_state3, int relay_state4) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t rawtime;
    struct tm timeinfo;
    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(fp, "%s, Moisture: %d, Relay1: %s, Relay2: %s, Relay3: %s, Relay4: %s\n",
            timestamp, moisture,
            relay_state1 ? "ON" : "OFF",
            relay_state2 ? "ON" : "OFF",
            relay_state3 ? "ON" : "OFF",
            relay_state4 ? "ON" : "OFF");

    fclose(fp);
}

int main(void) {
    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure relay pins as outputs */
    if (gpioSetMode(RELAY_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n",
                RELAY_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(RELAY_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n",
                RELAY_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(RELAY_3_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n",
                RELAY_3_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(RELAY_4_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n",
                RELAY_4_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure all relays start OFF */
    drive_relay(RELAY_1_PIN, 0);
    drive_relay(RELAY_2_PIN, 0);
    drive_relay(RELAY_3_PIN, 0);
    drive_relay(RELAY_4_PIN, 0);

    printf("Smart greenhouse irrigation system started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (program_running) {
        int moisture = simulate_moisture_reading();
        int relay_state1 = (moisture < 30) ? 1 : 0;
        int relay_state2 = (moisture < 30) ? 1 : 0;
        int relay_state3 = (moisture < 30) ? 1 : 0;
        int relay_state4 = (moisture < 30) ? 1 : 0;

        drive_relay(RELAY_1_PIN, relay_state1);
        drive_relay(RELAY_2_PIN, relay_state2);
        drive_relay(RELAY_3_PIN, relay_state3);
        drive_relay(RELAY_4_PIN, relay_state4);

        log_data(moisture, relay_state1, relay_state2,
                 relay_state3, relay_state4);

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < 50 && program_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    /* Clean shutdown: ensure all relays are OFF */
    drive_relay(RELAY_1_PIN, 0);
    drive_relay(RELAY_2_PIN, 0);
    drive_relay(RELAY_3_PIN, 0);
    drive_relay(RELAY_4_PIN, 0);

    /* Close log file */
    if (fclose(fopen(LOG_FILE, "r")) == EOF) {
        perror("Error closing log file");
    }

    gpioTerminate();
    printf("Smart greenhouse irrigation system stopped.\n");
    return EXIT_SUCCESS;
}

