    }
    if (init_log() != 0) {
        gpioTerminate();
        return 1;
    }

    pthread_t echo_thread;
    if (pthread_create(&echo_thread, NULL, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: cannot create echo thread\n");
        cleanup();
        return 1;
    }

    struct timespec ts = {0, 200000000}; /* 200 ms */
    while (running) {
        if (gpioWrite(TRIG_PIN, 1) != 0) {
            fprintf(stderr, "Error: cannot trigger TRIG\n");
            break;
        }
        gpioDelay(TRIG_PULSE_US);
        if (!running) break;
        if (gpioWrite(TRIG_PIN, 0) != 0) {
            fprintf(stderr, "Error: cannot trigger TRIG again\n");
            break;
        }
        struct timespec timeout;
        timeout.tv_sec = 0;
        timeout.tv_nsec = 200000000;
        while (running && !gpioRead(ECHO_PIN)) {
            if (!running) break;
            if (nanosleep(&timeout, NULL) == -1) {
                if (errno == EINTR) continue;
                fprintf(stderr, "Error: nanosleep timeout\n");
                break;
            }
        }
        if (!running) break;
        if (nanosleep(&ts, NULL) == -1) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Error: nanosleep timeout\n");
            break;
        }
        if (running) {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            long long pulse_ns = (now.tv_sec - ts.tv_sec) * 1000000000LL +
                                 (now.tv_nsec - ts.tv_nsec);
            if (pulse_ns > MAX_TIMEOUT_ERROR_NS) {
                fprintf(stderr, "Warning: echo pulse exceeds timeout (%.2f ns)\n", pulse_ns);
            }
        }
    }

    pthread_join(echo_thread, NULL);
    cleanup();
    return 0;
}

