/*
 * LIS3DH Free-Fall Detector for Raspberry Pi 5
 *
 * Reads the LIS3DH accelerometer on I2C bus 1 and triggers a buzzer
 * on GPIO17 when a free-fall is detected (acceleration < 0.2 g) or
 * an impact is detected (acceleration > 1.5 g).
 *
 * Build:  gcc -O2 -Wall -o freefall freefall.c -lm
 * Run:    ./freefall [free-fall_threshold_mg] [impact_threshold_mg]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS        "/dev/i2c-1"
#define LIS3DH_ADDR    0x68
#define BUZZER_GPIO    17
#define FREEFALL_THRESHOLD_MG 0.2f
#define IMPACT_THRESHOLD_MG  1.5f
#define MAX_RETRIES      3
#define POLL_INTERVAL_US  100000   /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, out, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* LIS3DH driver                                                       */
/* ------------------------------------------------------------------ */

typedef struct {
    int  handle;
    float free_fall_threshold_mg;
    float impact_threshold_mg;
    bool  initialized;
} lis3dh_t;

static int lis3dh_init(lis3dh_t *d)
{
    d->handle = open(I2C_BUS, O_RDWR);
    if (d->handle < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }

    if (ioctl(d->handle, I2C_SLAVE, LIS3DH_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                LIS3DH_ADDR, strerror(errno));
        close(d->handle);
        d->handle = -1;
        return -1;
    }

    /*
     * LIS3DH requires a single-byte write to the control register
     * (0x00) followed by a read to confirm the register was written.
     */
    if (i2c_write_byte(d->handle, 0x00, 0x00) < 0) {
        close(d->handle);
        d->handle = -1;
        return -1;
    }
    if (i2c_read_byte(d->handle, 0x00, &d->handle) < 0) {
        close(d->handle);
        d->handle = -1;
        return -1;
    }

    /*
     * LIS3DH requires a single-byte write to the control register
     * (0x00) followed by a read to confirm the register was written.
     */
    if (i2c_write_byte(d->handle, 0x00, 0x00) < 0) {
        close(d->handle);
        d->handle = -1;
        return -1;
    }
    if (i2c_read_byte(d->handle, 0x00, &d->handle) < 0) {
        close(d->handle);
        d->handle = -1;
        return -1;
    }

    d->initialized = true;
    return 0;
}

static int lis3dh_read_acceleration(lis3dh_t *d, float *x, float *y, float *z)
{
    uint8_t buf[6];

    if (i2c_read_block(d->handle, 0x00, buf, 6) < 0) {
        return -1;
    }

    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    *x = (float)raw_x * 0.032f;
    *y = (float)raw_y * 0.032f;
    *z = (float)raw_z * 0.032f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Buzzer control                                                      */
/* ------------------------------------------------------------------ */

static int buzzer_on(int gpio)
{
    if (gpio_set_mode(gpio, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output: %s\n",
                gpio, strerror(errno));
        return -1;
    }
    if (gpio_write(gpio, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO %d high: %s\n",
                gpio, strerror(errno));
        return -1;
    }
    return 0;
}

static int buzzer_off(int gpio)
{
    if (gpio_set_mode(gpio, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output: %s\n",
                gpio, strerror(errno));
        return -1;
    }
    if (gpio_write(gpio, 0) < 0) {
        fprintf(stderr, "Failed to set GPIO %d low: %s\n",
                gpio, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(int argc, char *argv[])
{
    int free_fall_threshold = FREEFALL_THRESHOLD_MG;
    int impact_threshold    = IMPACT_THRESHOLD_MG;
    int opt;

    while ((opt = getopt(argc, argv, "f:i:h")) != -1) {
        switch (opt) {
        case 'f':
            free_fall_threshold = (float)strtof(optarg, NULL);
            if (free_fall_threshold <= 0.0f) {
                fprintf(stderr, "Free-fall threshold must be positive.\n");
                return EXIT_FAILURE;
            }
            break;
        case 'i':
            impact_threshold = (float)strtof(optarg, NULL);
            if (impact_threshold <= 0.0f) {
                fprintf(stderr, "Impact threshold must be positive.\n");
                return EXIT_FAILURE;
            }
            break;
        default:
            fprintf(stderr, "Usage: %s [-f free_fall_threshold_mg] [-i impact_threshold_mg]\n",
                    argv[0]);
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    if (lis3dh_init(&d) < 0) {
        fprintf(stderr, "Failed to initialize LIS3DH sensor.\n");
        return EXIT_FAILURE;
    }

    if (buzzer_on(BUZZER_GPIO) < 0) {
        fprintf(stderr, "Failed to initialize buzzer GPIO %d.\n", BUZZER_GPIO);
        close(d.handle);
        d.handle = -1;
        return EXIT_FAILURE;
    }

    printf("Free-fall detection started. Free-fall threshold: %.2f g, Impact threshold: %.2f g\n",
           free_fall_threshold, impact_threshold);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        float x, y, z;

        if (lis3dh_read_acceleration(&d, &x, &y, &z) < 0) {
            fprintf(stderr, "Sensor read error; retrying in %d ms.\n",
                    POLL_INTERVAL_US / 1000);
            usleep(POLL_INTERVAL_US);
            continue;
        }

        if (fabsf(x) < free_fall_threshold || fabsf(y) < free_fall_threshold ||
            fabsf(z) < free_fall_threshold) {
            printf("Free-fall detected: %.2f g\n", x);
            if (buzzer_on(BUZZER_GPIO) < 0) {
                fprintf(stderr, "Buzzer on failed; continuing.\n");
            }
        } else if (fabsf(x) > impact_threshold || fabsf(y) > impact_threshold) {
            printf("Impact detected: %.2f g\n", z);
            if (buzzer_on(BUZZER_GPIO) < 0) {
                fprintf(stderr, "Buzzer on failed; continuing.\n");
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down cleanly.\n");
    if (buzzer_off(BUZZER_GPIO) < 0) {
        fprintf(stderr, "Warning: failed to turn off buzzer on exit.\n");
    }
    if (d.handle >= 0) {
        close(d.handle);
        d.handle = -1;
    }
    return EXIT_SUCCESS;
}

