/*
 * Line-following robot using SunFounder 3-Way Tracking Sensor
 * Board: Raspberry Pi 5
 * Sensors:
 *   - Left IR  (GPIO4, BCM)
 *   - Center IR (GPIO17, BCM)
 *   - Right IR (GPIO27, BCM)
 *   - Alert LED/Buzzer (GPIO22, BCM)
 *
 * Build:  gcc -O2 -Wall -Wextra -o line_follow line_follow.c -lpigpio -lrt
 * Run:    sudo ./line_follow
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define LEFT_IR_PIN    4
#define CENTER_IR_PIN  17
#define RIGHT_IR_PIN   27
#define ALERT_PIN      22

/* ---- Circular buffer (5 entries) ---- */
#define BUFFER_SIZE    5
#define POLL_DELAY_US  10000   /* 10 ms */

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_pigpio_initialized = 0;

/* ---- Circular buffer ---- */
typedef struct {
    int left_reading;
    int center_reading;
    int right_reading;
} sensor_data_t;

static sensor_data_t g_sensor_data[BUFFER_SIZE];
static int g_sensor_index = 0;

/* ---- Function prototypes ---- */
static void signal_handler(int sig);
static int  initialize_gpio(void);
static void cleanup_gpio(void);
static int  read_sensor(int pin);
static void log_sensor_data(int left, int center, int right);
static void control_motor(int left, int center, int right);
static void alert_line_no_line(int center_reading);
static void stop_robot(void);

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Initialize pigpio and GPIO pins                                      */
/* ------------------------------------------------------------------ */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    g_pigpio_initialized = 1;

    /* Configure alert LED/buzzer pin as output, initially LOW */
    gpioSetMode(ALERT_PIN, PI_OUTPUT);
    gpioWrite(ALERT_PIN, 0);

    /* Configure left, center, right sensors as inputs */
    gpioSetMode(LEFT_IR_PIN, PI_INPUT);
    gpioSetMode(CENTER_IR_PIN, PI_INPUT);
    gpioSetMode(RIGHT_IR_PIN, PI_INPUT);

    /* Allow sensor pull-up to be active */
    gpioSetPullUpDown(LEFT_IR_PIN, PI_PUD_UP);
    gpioSetPullUpDown(CENTER_IR_PIN, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_IR_PIN, PI_PUD_UP);

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup GPIO resources                                              */
/* ------------------------------------------------------------------ */
static void cleanup_gpio(void)
{
    if (g_pigpio_initialized) {
        gpioWrite(ALERT_PIN, 0);
        gpioTerminate();
        g_pigpio_initialized = 0;
    }
}

/* ------------------------------------------------------------------ */
/* Read a sensor pin                                                   */
/* Returns 0-3 (left, center, right) or -1 on error.                  */
/* ------------------------------------------------------------------ */
static int read_sensor(int pin)
{
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error: gpioRead failed on pin %d (code %d).\n",
                pin, value);
        return -1;
    }
    return value;
}

/* ------------------------------------------------------------------ */
/* Log sensor readings to circular buffer                              */
/* ------------------------------------------------------------------ */
static void log_sensor_data(int left, int center, int right)
{
    g_sensor_data[g_sensor_index].left_reading  = left;
    g_sensor_data[g_sensor_index].center_reading = center;
    g_sensor_data[g_sensor_index].right_reading  = right;
    g_sensor_index = (g_sensor_index + 1) % BUFFER_SIZE;
}

/* ------------------------------------------------------------------ */
/* Control motor based on sensor readings                              */
/* ------------------------------------------------------------------ */
static void control_motor(int left, int center, int right)
{
    if (left < 0 || left > 1) {
        fprintf(stderr, "Error: left sensor reading %d out of range.\n", left);
        return;
    }
    if (center < 0 || center > 1) {
        fprintf(stderr, "Error: center sensor reading %d out of range.\n", center);
        return;
    }
    if (right < 0 || right > 1) {
        fprintf(stderr, "Error: right sensor reading %d out of range.\n", right);
        return;
    }

    /*
     * Center:  1 = line detected, 0 = no line.
     * Right:   1 = line detected, 0 = no line.
     * Left:    1 = no line, 0 = line.
     */
    if (center == 1) {
        control_motor(left, 0, 0);
    } else if (center == 0) {
        control_motor(0, 0, 0);
    } else {
        control_motor(0, 0, 0);
    }
}

/* ------------------------------------------------------------------ */
/* Alert LED/Buzzer                                                     */
/* ------------------------------------------------------------------ */
static void alert_line_no_line(int center_reading)
{
    if (center_reading == 1) {
        /* Center sensor reports "no line" (logic 1) for 5 consecutive readings. */
        for (int i = 0; i < 5 && g_running; i++) {
            int reading = read_sensor(CENTER_IR_PIN);
            if (reading < 0) {
                fprintf(stderr, "Warning: sensor read error during alert cycle.\n");
                break;
            }
            if (reading == 0) {
                gpioWrite(ALERT_PIN, 1);
                gpioDelay(2000000);  /* 2 s */
                gpioWrite(ALERT_PIN, 0);
                break;
            }
            gpioDelay(10000);
        }
    } else {
        /* Center sensor reports "line" (logic 0) for 5 consecutive readings. */
        for (int i = 0; i < 5 && g_running; i++) {
            int reading = read_sensor(CENTER_IR_PIN);
            if (reading < 0) {
                fprintf(stderr, "Warning: sensor read error during alert cycle.\n");
                break;
            }
            if (reading == 1) {
                gpioWrite(ALERT_PIN, 1);
                gpioDelay(2000000);
                gpioWrite(ALERT_PIN, 0);
                break;
            }
            gpioDelay(10000);
        }
    }
}

/* ------------------------------------------------------------------ */
/* Stop robot and release GPIO resources                               */
/* ------------------------------------------------------------------ */
static void stop_robot(void)
{
    gpioWrite(ALERT_PIN, 0);
    gpioWrite(LEFT_IR_PIN, 0);
    gpioWrite(CENTER_IR_PIN, 0);
    gpioWrite(RIGHT_IR_PIN, 0);
    gpioTerminate();
    g_pigpio_initialized = 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Initialize pigpio */
    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    /* Configure alert LED/buzzer pin as output, initially LOW */
    gpioSetMode(ALERT_PIN, PI_OUTPUT);
    gpioWrite(ALERT_PIN, 0);

    /* Configure sensor pins as inputs with pull-up */
    gpioSetMode(LEFT_IR_PIN, PI_INPUT);
    gpioSetMode(CENTER_IR_PIN, PI_INPUT);
    gpioSetMode(RIGHT_IR_PIN, PI_INPUT);
    gpioSetPullUpDown(LEFT_IR_PIN, PI_PUD_UP);
    gpioSetPullUpDown(CENTER_IR_PIN, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_IR_PIN, PI_PUD_UP);

    printf("Line-following robot started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        int left_reading = read_sensor(LEFT_IR_PIN);
        int center_reading = read_sensor(CENTER_IR_PIN);
        int right_reading = read_sensor(RIGHT_IR_PIN);

        if (left_reading < 0 || center_reading < 0 || right_reading < 0) {
            fprintf(stderr, "Error: sensor read failed; aborting.\n");
            break;
        }

        log_sensor_data(left_reading, center_reading, right_reading);

        control_motor(left_reading, center_reading, right_reading);

        /* Alert on center sensor (logic 1) for 5 consecutive readings */
        for (int i = 0; i < 5 && g_running; i++) {
            int reading = read_sensor(CENTER_IR_PIN);
            if (reading < 0) {
                fprintf(stderr, "Warning: sensor read error during alert cycle.\n");
                break;
            }
            if (reading == 1) {
                alert_line_no_line(center_reading);
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Graceful shutdown */
    stop_robot();
    printf("\nRobot stopped.\n");
    return EXIT_SUCCESS;
}

