#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define RELAY_GPIO 18
#define PORT 5000
#define LOG_FILE "relay_log.txt"
#define BUF_SIZE 256

static volatile sig_atomic_t running = 1;
static int relay_on = 0;
static int relay_off = 0;
static int relay_state = 0;
static int relay_sock = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event) {
    if (!log_fp) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(log_fp, "%04d-%02d-%02d %02d:%02d:%02d: %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, event);
        fflush(log_fp);
    }
}

static void relay_on_command(void) {
    if (relay_state) return;
    relay_state = 1;
    relay_on = 1;
    log_event("Relay ON");
    if (gpioWrite(RELAY_GPIO, 1) != 0) {
        log_event("Error: failed to turn relay ON");
        return;
    }
    log_event("Relay ON");
}

static void relay_off_command(void) {
    if (!relay_state) return;
    relay_state = 0;
    relay_off = 1;
    log_event("Relay OFF");
    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        log_event("Error: failed to turn relay OFF");
        return;
    }
    log_event("Relay OFF");
}

static int relay_api_call(void) {
    char cmd[BUF_SIZE];
    int rc;

    if (relay_on) {
        snprintf(cmd, sizeof(cmd), "ON");
        rc = relay_on_command();
    } else if (relay_off) {
        snprintf(cmd, sizeof(cmd), "OFF");
        rc = relay_off_command();
    } else {
        snprintf(cmd, sizeof(cmd), "ON");
        rc = relay_on_command();
    }

    if (rc != 0) {
        log_event("Error: relay API call failed");
        return -1;
    }
    return 0;
}

static int relay_init(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise relay state to 0\n");
        gpioTerminate();
        return -1;
    }
    relay_state = 0;
    relay_off = 0;
    relay_on = 0;
    relay_sock = -1;
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Error: cannot open log file %s\n", LOG_FILE);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static void relay_cleanup(void) {
    if (relay_sock != -1) {
        close(relay_sock);
        relay_sock = -1;
    }
    if (relay_sock != -1) {
        close(relay_sock);
        relay_sock = -1;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (relay_init() != 0) {
        return EXIT_FAILURE;
