static void log_event(const char *event) {
    if (!log_fp) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(log_fp, "%04d-%02d-%02d %02d:%02d:%02d: %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, event);
        fflush(log_fp);
    }
}

static void relay_on_command(void) {
    if (relay_state) return;
    relay_state = 1;
    relay_on = 1;
