/*
 * Raspberry Pi Zero W – dual SLF3S-1300F liquid-flow monitor
 *
 * Wiring:
 *   Sensor 1  -> I2C bus 1, SDA -> GPIO2, SCL -> GPIO3
 *   Sensor 2  -> I2C bus 1, SDA -> GPIO5, SCL -> GPIO7
 *   Relay     -> GPIO18 (BCM)
 *
 * Build:  gcc -Wall -Wextra -O2 -o flow_monitor flow_monitor.c -lgpiod
 * Run:    sudo ./flow_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define SENSOR_1_ADDR  0x40
#define SENSOR_2_ADDR  0x41
#define RELAY_PIN      18
#define FLOW_THRESHOLD 5.0f
#define LOG_FILE       "flow_log.txt"
#define POLL_DELAY_US  100000   /* 100 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion: poly 0x31, init 0xFF, no final XOR)                */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int i2c_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write(0x%02X) failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C short read: got %zd of %zu\n", n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor 1                                                            */
/* ------------------------------------------------------------------ */
static int sensor1_init(int fd)
{
    if (i2c_write_cmd(fd, 0x01) < 0)
        return -1;   /* start measurement */
    usleep(2000);   /* 2 ms settle */
    return 0;
}

static int sensor1_read(int fd, float *flow)
{
    uint8_t buf[3];
    if (i2c_read_bytes(fd, buf, sizeof(buf)) < 0)
        return -1;

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on sensor 1\n");
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow = (float)raw / 1000.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor 2                                                            */
/* ------------------------------------------------------------------ */
static int sensor2_init(int fd)
{
    if (i2c_write_cmd(fd, 0x02) < 0)
        return -1;   /* start measurement */
    usleep(2000);   /* 2 ms settle */
    return 0;
}

static int sensor2_read(int fd, float *flow)
{
    uint8_t buf[3];
    if (i2c_read_bytes(fd, buf, sizeof(buf)) < 0)
        return -1;

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on sensor 2\n");
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow = (float)raw / 1000.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Relay control                                                       */
/* ------------------------------------------------------------------ */
static int relay_set(struct gpiod_line *line, int state)
{
    if (gpiod_line_set_value(line, state) < 0) {
        fprintf(stderr, "gpiod_line_set_value failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    /* Ensure relay is off before releasing resources */
    if (g_running) {
        relay_set(NULL, 0);
    }
    if (i2c_close(SENSOR_1_ADDR) < 0)
        fprintf(stderr, "I2C close failed for sensor 1\n");
    if (i2c_close(SENSOR_2_ADDR) < 0)
        fprintf(stderr, "I2C close failed for sensor 2\n");
    if (g_running) {
        relay_set(NULL, 0);
    }
    if (g_running) {
        gpiod_line_release(RELAY_PIN);
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 for both sensors */
    int fd1 = i2c_open(I2C_BUS, SENSOR_1_ADDR);
    int fd2 = i2c_open(I2C_BUS, SENSOR_2_ADDR);
    if (fd1 < 0 || fd2 < 0) {
        fprintf(stderr, "Failed to open I2C devices; exiting.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Sensor 1: start measurement */
    if (sensor1_init(fd1) < 0) {
        fprintf(stderr, "Sensor 1 initialization failed; exiting.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Sensor 2: start measurement */
    if (sensor2_init(fd2) < 0) {
        fprintf(stderr, "Sensor 2 initialization failed; exiting.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure relay pin as output, initially low */
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    struct gpiod_line *relay = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                RELAY_PIN, strerror(errno));
        gpiod_chip_close(chip);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(relay, "flow_monitor", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output failed: %s\n",
                strerror(errno));
        gpiod_chip_close(chip);
        cleanup();
        return EXIT_FAILURE;
    }

    float flow1 = 0.0f, flow2 = 0.0f;
    int relay_state = 0;   /* 0 = off, 1 = on */

    printf("Flow monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        if (sensor1_read(fd1, &flow1) < 0) {
            fprintf(stderr, "Sensor 1 read failed; retrying next cycle.\n");
            usleep(POLL_DELAY_US);
            continue;
        }
        if (sensor2_read(fd2, &flow2) < 0) {
            fprintf(stderr, "Sensor 2 read failed; retrying next cycle.\n");
            usleep(POLL_DELAY_US);
            continue;
        }

        if (flow1 < FLOW_THRESHOLD || flow2 < FLOW_THRESHOLD) {
            relay_state = !relay_state;
            if (relay_set(relay, relay_state) < 0) {
                fprintf(stderr, "Relay write failed; continuing.\n");
            }
        }

        time_t now = time(NULL);
        struct tm tm_buf;
        struct tm *t = localtime_r(&now, &tm_buf);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
        printf("%s  Sensor 1: %.2f ml/min  Sensor 2: %.2f ml/min  Relay: %s\n",
               ts, flow1, flow2, relay_state ? "ON" : "OFF");
        fflush(stdout);

        usleep(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

