    if (sensor2_init(fd2) < 0) {
        fprintf(stderr, "Sensor 2 initialization failed; exiting.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure relay pin as output, initially low */
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    struct gpiod_line *relay = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                RELAY_PIN, strerror(errno));
        gpiod_chip_close(chip);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(relay, "flow_monitor", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output failed: %s\n",
                strerror(errno));
        gpiod_chip_close(chip);
        cleanup();
        return EXIT_FAILURE;
    }

    float flow1 = 0.0f, flow2 = 0.0f;
    int relay_state = 0;   /* 0 = off, 1 = on */

    printf("Flow monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        if (sensor1_read(fd1, &flow1) < 0) {
            fprintf(stderr, "Sensor 1 read failed; retrying next cycle.\n");
            usleep(POLL_DELAY_US);
            continue;
        }
        if (sensor2_read(fd2, &flow2) < 0) {
            fprintf(stderr, "Sensor 2 read failed; retrying next cycle.\n");
            usleep(POLL_DELAY_US);
            continue;
        }

        if (flow1 < FLOW_THRESHOLD || flow2 < FLOW_THRESHOLD) {
            relay_state = !relay_state;
            if (relay_set(relay, relay_state) < 0) {
                fprintf(stderr, "Relay write failed; continuing.\n");
            }
        }

        time_t now = time(NULL);
        struct tm tm_buf;
        struct tm *t = localtime_r(&now, &tm_buf);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
        printf("%s  Sensor 1: %.2f ml/min  Sensor 2: %.2f ml/min  Relay: %s\n",
               ts, flow1, flow2, relay_state ? "ON" : "OFF");
        fflush(stdout);

        usleep(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

