/*
 * rain_window.c — Raspberry Pi 5
 *
 * Monitors the Seeed Studio Rain Sensor v1.0 digital output on GPIO 17
 * (BCM) and drives a DC motor window actuator through an L298N driver.
 *
 * Build:  gcc -O2 -Wall -Wextra -o rain_window rain_window.c -lpigpio -lrt
 * Run:    sudo ./rain_window
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN  17
#define MOTOR_PIN        22
#define ENA_PIN          23
#define IN1_PIN          24

#define MOTOR_ON_MS      5000   /* 5 s motor-on duration */
#define POLL_INTERVAL_US 200000 /* 200 ms polling interval */
#define DRY_THRESHOLD_US 600000 /* 600 ms dry-to-wet threshold */
#define MAX_TRIGGERS     3

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_message(int priority, const char *message)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        snprintf(ts, sizeof(ts), "UNKNOWN");
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    }

    syslog(priority, "%s: %s", ts, message);
}

/* ------------------------------------------------------------------ */
/* Motor control                                                       */
/* ------------------------------------------------------------------ */
static void motor_stop(void)
{
    gpioWrite(MOTOR_PIN, 0);
    gpioWrite(ENA_PIN, 0);
    gpioWrite(IN1_PIN, 0);
    gpioWrite(IN2_PIN, 0);
}

static void motor_start(void)
{
    gpioWrite(MOTOR_PIN, 1);
    gpioWrite(ENA_PIN, 1);
    gpioWrite(IN1_PIN, 1);
    gpioWrite(IN2_PIN, 0);
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int gpio_init(void)
{
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) != 0) {
        log_message(LOG_ERR, "Failed to set rain sensor pin mode");
        return -1;
    }

    if (gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP) != 0) {
        log_message(LOG_ERR, "Failed to set rain sensor pull-up");
        return -1;
    }

    if (gpioSetMode(MOTOR_PIN, PI_OUTPUT) != 0) {
        log_message(LOG_ERR, "Failed to set motor pin mode");
        return -1;
    }

    if (gpioSetMode(ENA_PIN, PI_OUTPUT) != 0) {
        log_message(LOG_ERR, "Failed to set ENA pin mode");
        return -1;
    }

    if (gpioSetMode(IN1_PIN, PI_OUTPUT) != 0) {
        log_message(LOG_ERR, "Failed to set IN1 pin mode");
        return -1;
    }

    if (gpioSetMode(IN2_PIN, PI_OUTPUT) != 0) {
        log_message(LOG_ERR, "Failed to set IN2 pin mode");
        return -1;
    }

    return 0;
}

static int gpio_cleanup(void)
{
    motor_stop();
    gpioWrite(ENA_PIN, 0);
    gpioWrite(IN1_PIN, 0);
    gpioWrite(IN2_PIN, 0);
    gpioTerminate();
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor monitoring                                                   */
/* ------------------------------------------------------------------ */
static int read_rain_sensor(void)
{
    int val = gpioRead(RAIN_SENSOR_PIN);
    if (val < 0) {
        log_message(LOG_ERR, "Failed to read rain sensor");
        return -1;
    }
    return val;
}

static int trigger_motor_start(void)
{
    if (gpioWrite(ENA_PIN, 1) != 0) {
        log_message(LOG_ERR, "Failed to set ENA high");
        return -1;
    }
    if (gpioWrite(IN1_PIN, 1) != 0) {
        log_message(LOG_ERR, "Failed to set IN1 high");
        return -1;
    }
    if (gpioWrite(IN2_PIN, 0) != 0) {
        log_message(LOG_ERR, "Failed to set IN2 low");
        return -1;
    }
    return 0;
}

static int trigger_motor_stop(void)
{
    if (gpioWrite(ENA_PIN, 0) != 0) {
        log_message(LOG_ERR, "Failed to set ENA low");
        return -1;
    }
    if (gpioWrite(IN1_PIN, 0) != 0) {
        log_message(LOG_ERR, "Failed to set IN1 low");
        return -1;
    }
    if (gpioWrite(IN2_PIN, 0) != 0) {
        log_message(LOG_ERR, "Failed to set IN2 low");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sequencing                                                          */
/* ------------------------------------------------------------------ */
static int sequence_start(void)
{
    if (trigger_motor_start() != 0) {
        return -1;
    }
    return 0;
}

static int sequence_stop(void)
{
    if (trigger_motor_stop() != 0) {
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpio_init() != 0) {
        return EXIT_FAILURE;
    }

    log_message(LOG_INFO, "Rain sensor monitoring started");

    int last_dry_count = 0;
    int dry_triggered = 0;

    while (g_running) {
        int rain_val = read_rain_sensor();
        if (rain_val < 0) {
            log_message(LOG_ERR, "Sensor read error — continuing");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (rain_val == 0) {
            /* Dry-to-wet transition — start motor sequence */
            if (dry_triggered == 0) {
                if (sequence_start() != 0) {
                    log_message(LOG_ERR, "Sequence start failed");
                    break;
                }
                dry_triggered = 1;
                last_dry_count = 0;
            } else {
                /* Dry-to-wet transition — stop motor sequence */
                if (dry_triggered == 1) {
                    if (sequence_stop() != 0) {
                        log_message(LOG_ERR, "Sequence stop failed");
                        break;
                    }
                    dry_triggered = 0;
                }
            }
        } else {
            /* Dry sensor — wait for next transition */
            if (last_dry_count < DRY_THRESHOLD_US) {
                log_message(LOG_INFO, "Dry sensor — waiting for next transition");
                gpioDelay(POLL_INTERVAL_US);
                continue;
            }
            last_dry_count = 0;
            dry_triggered = 0;
        }

        /* Wait for the next dry-to-wet transition (600 ms) */
        gpioDelay(POLL_INTERVAL_US);
    }

    /* Graceful shutdown */
    log_message(LOG_INFO, "Shutting down motor and GPIO");
    motor_stop();
    gpio_cleanup();
    log_message(LOG_INFO, "Rain sensor monitoring stopped");

    return EXIT_SUCCESS;
}

