/*
 * Door-lock actuator using two momentary push-buttons and a servo.
 * Board:  Raspberry Pi (GPIO 18, 21, 22)
 * Library: pigpio (gpio.h)
 *
 * Build:  gcc -O2 -Wall -o door_lock door_lock.c -lpigpio -lrt
 * Run:    sudo ./door_lock
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN      18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

#define DEBOUNCE_DELAY_US   500   /* 500 µs */
#define API_CALL_DELAY_US   2000  /* 2 ms  */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * pigpio API call() returns 0 on success, -1 on error.
 * Returns 0 on success, -1 on failure.
 */
static int lock_servo(void)
{
    if (gpioWrite(LOCK_BUTTON_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set lock button high\n");
        return -1;
    }
    gpioDelay(API_CALL_DELAY_US);

    if (gpioWrite(LOCK_BUTTON_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set lock button low\n");
        return -1;
    }
    gpioDelay(API_CALL_DELAY_US);

    return 0;
}

static int unlock_servo(void)
{
    if (gpioWrite(UNLOCK_BUTTON_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set unlock button high\n");
        return -1;
    }
    gpioDelay(API_CALL_DELAY_US);

    if (gpioWrite(UNLOCK_BUTTON_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set unlock button low\n");
        return -1;
    }
    gpioDelay(API_CALL_DELAY_US);

    return 0;
}

int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set SERVO_PIN %d as output\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set LOCK_BUTTON_PIN %d as input\n", LOCK_BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set UNLOCK_BUTTON_PIN %d as input\n", UNLOCK_BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Enable internal pull-up resistors on the buttons */
    if (gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: failed to set pull-up on LOCK_BUTTON_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: failed to set pull-up on UNLOCK_BUTTON_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Main loop --- */
    while (g_running) {
        int lock_state = gpioRead(LOCK_BUTTON_PIN);
        int unlock_state = gpioRead(UNLOCK_BUTTON_PIN);

        if (lock_state < 0) {
            fprintf(stderr, "Error: gpioRead failed on LOCK_BUTTON_PIN\n");
            break;
        }
        if (unlock_state < 0) {
            fprintf(stderr, "Error: gpioRead failed on UNLOCK_BUTTON_PIN\n");
            break;
        }

        /*
         * Detect a single press of the lock button (release + release).
         * Debounce: wait for release, then re-read.
         */
        if (lock_state == 0 && unlock_state == 1) {
            gpioDelay(DEBOUNCE_DELAY_US);
            if (gpioRead(LOCK_BUTTON_PIN) < 0) {
                fprintf(stderr, "Error: gpioRead failed on LOCK_BUTTON_PIN during debounce\n");
                break;
            }
            if (unlock_state == 0) {
                lock_servo();
                printf("Locked\n");
            }
        }

        if (lock_state == 1 && unlock_state == 0) {
            gpioDelay(DEBOUNCE_DELAY_US);
            if (gpioRead(UNLOCK_BUTTON_PIN) < 0) {
                fprintf(stderr, "Error: gpioRead failed on UNLOCK_BUTTON_PIN during debounce\n");
                break;
            }
            if (lock_state == 0) {
                unlock_servo();
                printf("Unlocked\n");
            }
        }

        gpioDelay(10000); /* 10 ms poll interval */
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    gpioWrite(SERVO_PIN, 0);
    gpioWrite(LOCK_BUTTON_PIN, 0);
    gpioWrite(UNLOCK_BUTTON_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

