#define PIR_PIN 4
#define LED_PIN 17
#define LOG_FILE "security_log.txt"
#define POLL_INTERVAL_US 100000  /* 100 ms */
#define LED_ON_DURATION_S 60
#define MAX_EVENT_LEN 256

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *event_type, const char *event_data) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file not open.\n");
        return -1;
    }
    if (fprintf(log_file, "%s: %s\n", event_type, event_data) < 0) {
        fprintf(stderr, "Error: Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file);
    return 0;
}

static int activate_floodlight(void) {
    if (gpioWrite(LED_PIN, 1) < 0) {
        fprintf(stderr, "Error: Failed to turn on floodlight (GPIO %d).\n", LED_PIN);
        return -1;
    }
    printf("Floodlight turned on.\n");
    return 0;
}

static int deactivate_floodlight(void) {
    if (gpioWrite(LED_PIN, 0) < 0) {
        fprintf(stderr, "Error: Failed to turn off floodlight (GPIO %d).\n", LED_PIN);
        return -1;
    }
    printf("Floodlight turned off.\n");
    return 0;
}

static int log_event_with_duration(const char *event_type, const char *event_data, long duration_sec) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file not open.\n");
        return -1;
    }
    if (fprintf(log_file, "%s: %s (Duration: %ld s)\n", event_type, event_data, duration_sec) < 0) {
        fprintf(stderr, "Error: Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: Failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: Failed to install SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    /* Configure PIR pin as input with pull-up */
    if (gpioSetMode(PIR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: Failed to set PIR pin mode.\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(PIR_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: Failed to set pull-up on PIR pin.\n");
        gpioTerminate();
        return 1;
    }

    /* Configure LED pin as output and ensure it is off */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set LED pin mode.\n");
        gpioTerminate();
        return 1;
    }
    if (gpioWrite(LED_PIN, 0) < 0) {
        fprintf(stderr, "Error: Failed to initialise LED pin state.\n");
        gpioTerminate();
        return 1;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return 1;
    }

    printf("Monitoring PIR sensor on GPIO %d. Press Ctrl+C to exit.\n", PIR_PIN);

    /* Main polling loop */
    while (running) {
        int pir_value = gpioRead(PIR_PIN);
        if (pir_value < 0) {
            fprintf(stderr, "Error: Failed to read PIR pin.\n");
            break;
        }

        if (pir_value == 1) {
            printf("Motion detected! Activating floodlight for %d seconds.\n", LED_ON_DURATION_S);
            if (activate_floodlight() < 0) {
                fprintf(stderr, "Error: Floodlight activation failed.\n");
            }
            if (log_event_with_duration("Floodlight Activation", "Motion detected", LED_ON_DURATION_S) < 0) {
                fprintf(stderr, "Error: Failed to log floodlight activation event.\n");
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    deactivate_floodlight();
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
    return 0;
}

