/*
 * BH1750 ambient light sensor reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   BH1750 SDA  -> GPIO2  (I2C1 SDA)
 *   BH1750 SCL  -> GPIO3  (I2C1 SCL)
 *   BH1750 VCC  -> 3.3 V
 *   BH1750 GND  -> GND
 *   Relay IN    -> GPIO23 (BCM)
 *   Relay OUT   -> GND (or +5 V via a suitable resistor)
 *
 * Build:  gcc -O2 -Wall -Wextra -o bh1750_relay bh1750_relay.c -lgpiod
 * Run:    sudo ./bh1750_relay
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
