#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR    0x23
#define BH1750_REG_ID   0x0F
#define BH1750_REG_LUX  0x0E

#define BH1750_RELAY_PIN 23
#define RELAY_THRESHOLD 150
#define SAMPLE_INTERVAL_S 2
#define I2C_RETRY_DELAY_MS 100

