static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_relay_line = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int bh1750_init(int fd)
{
    uint8_t id = 0;
    if (i2c_read_reg8(fd, BH1750_REG_ID, &id) < 0) {
        fprintf(stderr, "BH1750 not responding on I2C bus %s\n", I2C_BUS);
        return -1;
    }
    if (id != 0x27) {
        fprintf(stderr, "Unexpected BH1750 ID 0x%02X (expected 0x27)\n", id);
        return -1;
    }
    printf("BH1750 detected (ID=0x27)\n");

    if (i2c_write_byte(fd, 0x00) < 0) {
        fprintf(stderr, "Failed to write to BH1750 register 0x00\n");
        return -1;
