/*
 * weight_monitor.c — Raspberry Pi 3 Model B+
 *
 * TAL220B load cell + HX711 amplifier + solenoid lock controller.
 *
 * Build:  gcc -O2 -Wall -Wextra -o weight_monitor weight_monitor.c -lgpiod
 * Run:    ./weight_monitor [--threshold <grams>] [--scale <factor>]
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME   "gpiochip0"
#define SOLENOID_PIN     25
#define DOUT_PIN         23
#define SCK_PIN          24

#define DEFAULT_THRESHOLD 1000
#define DEFAULT_SCALE     1.0
#define DEFAULT_DURATION  500

#define MAX_RETRIES      3
#define READ_TIMEOUT_MS  1000

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a 24-bit two’s-complement value from the HX711.
 * Returns 0 on success, -1 on timeout/error.
 */
static int hx711_read_weight(struct gpiod_line *dout, struct gpiod_line *sck,
                              struct gpiod_line *sck_p,
                              struct gpiod_line *sck_n,
                              int *out_value)
{
    int retries = 0;
    int val = 0;

    while (retries < MAX_RETRIES) {
        /* Wait for DOUT to go LOW (data ready) */
        int timeout = READ_TIMEOUT_MS;
        while (gpiod_line_get_value(dout) == 1) {
            if (timeout-- <= 0) {
                syslog(LOG_ERR, "HX711 DOUT timeout (retry %d)", retries + 1);
                retries++;
                usleep(1000);
                continue;
            }
            usleep(100);
        }

        /* Read 24 bits MSB-first */
        for (int i = 0; i < 24; i++) {
            if (gpiod_line_set_value(sck, 1) < 0) {
                syslog(LOG_ERR, "Failed to set SCK HIGH");
                retries++;
                usleep(1000);
                continue;
            }
            usleep(1);

            int bit = gpiod_line_get_value(dout);
            if (bit < 0) {
                syslog(LOG_ERR, "Failed to read DOUT (retry %d)", retries + 1);
                retries++;
                usleep(1000);
                continue;
            }

            if (bit & 1) {
                val |= (1 << i);
            }

            if (gpiod_line_set_value(sck, 0) < 0) {
                syslog(LOG_ERR, "Failed to set SCK LOW");
                retries++;
                usleep(1000);
                continue;
            }
            usleep(1);
        }

        /* Select Channel A gain 128 */
        if (gpiod_line_set_value(sck_p, 1) < 0) {
            syslog(LOG_ERR, "Failed to set SCK_P HIGH");
            retries++;
            usleep(1000);
            continue;
        }
        usleep(1);

        if (gpiod_line_set_value(sck_p, 0) < 0) {
            syslog(LOG_ERR, "Failed to set SCK_P LOW");
            retries++;
            usleep(1000);
            continue;
        }
        usleep(1);

        /* Read one extra clock pulse to select Channel A gain 128 */
        if (gpiod_line_set_value(sck_n, 1) < 0) {
            syslog(LOG_ERR, "Failed to set SCK_N HIGH");
            retries++;
            usleep(1000);
            continue;
        }
        usleep(1);

        if (gpiod_line_set_value(sck_n, 0) < 0) {
            syslog(LOG_ERR, "Failed to set SCK_N LOW");
            retries++;
            usleep(1000);
            continue;
        }
        usleep(1);

        /* Convert 24-bit two’s complement to signed integer */
        if (val & 0x800000) {
            val |= 0xFF000000;
        }

        *out_value = val;
        return 0;
    }

    syslog(LOG_ERR, "HX711 read failed after %d retries", MAX_RETRIES);
    return -1;
}

static double hx711_scale(int value)
{
    if (value < 0) return 0.0;
    return (double)value / 128.0;
}

static int hx711_tare(struct gpiod_line *dout, struct gpiod_line *sck,
                       struct gpiod_line *sck_p,
                       struct gpiod_line *sck_n,
                       int *out_value)
{
    int val = 0;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (gpiod_line_set_value(sck, 1) < 0) {
            syslog(LOG_ERR, "Failed to set SCK HIGH");
            retries++;
            usleep(1000);
            continue;
        }
        usleep(1);

        int timeout = READ_TIMEOUT_MS;
        while (gpiod_line_get_value(dout) == 1) {
            if (timeout-- <= 0) {
                syslog(LOG_ERR, "HX711 DOUT timeout (retry %d)", retries + 1);
                retries++;
                usleep(1000);
                continue;
            }
            usleep(1);
        }

        if (gpiod_line_set_value(sck, 0) < 0) {
            syslog(LOG_ERR, "Failed to set SCK LOW");
            retries++;
            usleep(1000);
            continue;
        }
        usleep(1);

        if (gpiod_line_set_value(sck_p, 1) < 0) {
            syslog(LOG_ERR, "Failed to set SCK_P HIGH");
            retries++;
            usleep(1000);
            continue;
        }
        usleep(1);

        if (gpiod_line_set_value(sck_p, 0) < 0) {
            syslog(LOG_ERR, "Failed to set SCK_P LOW");
            retries++;
            usleep(1000);
            continue;
        }
        usleep(1);

        if (gpiod_line_set_value(sck_n, 1) < 0) {
            syslog(LOG_ERR, "Failed to set SCK_N HIGH");
            retries++;
            usleep(1000);
            continue;
        }
        usleep(1);

        if (gpiod_line_set_value(sck_n, 0) < 0) {
            syslog(LOG_ERR, "Failed to set SCK_N LOW");
            retries++;
            usleep(1000);
            continue;
        }
        usleep(1);

        /* Tare: read 10 times, average, then select Channel A gain 128 */
        for (int i = 0; i < 10; i++) {
            if (gpiod_line_set_value(sck, 1) < 0) {
                syslog(LOG_ERR, "Failed to set SCK HIGH");
                retries++;
                usleep(1000);
                continue;
            }
            usleep(1);

            int val = 0;
            int timeout = READ_TIMEOUT_MS;
            while (gpiod_line_get_value(dout) == 1) {
                if (timeout-- <= 0) {
                    syslog(LOG_ERR, "HX711 DOUT timeout (retry %d)", retries + 1);
                    retries++;
                    usleep(1000);
                    continue;
                }
                usleep(1);
            }

            if (gpiod_line_set_value(sck, 0) < 0) {
                syslog(LOG_ERR, "Failed to set SCK LOW");
                retries++;
                usleep(1000);
                continue;
            }
            usleep(1);

            if (gpiod_line_set_value(sck_p, 1) < 0) {
                syslog(LOG_ERR, "Failed to set SCK_P HIGH");
                retries++;
                usleep(1000);
                continue;
            }
            usleep(1);

            if (gpiod_line_set_value(sck_p, 0) < 0) {
                syslog(LOG_ERR, "Failed to set SCK_P LOW");
                retries++;
                usleep(1000);
                continue;
            }
            usleep(1);

            if (gpiod_line_set_value(sck_n, 1) < 0) {
                syslog(LOG_ERR, "Failed to set SCK_N HIGH");
                retries++;
                usleep(1000);
                continue;
            }
            usleep(1);

            if (gpiod_line_set_value(sck_n, 0) < 0) {
                syslog(LOG_ERR, "Failed to set SCK_N LOW");
                retries++;
                usleep(1000);
                continue;
            }
            usleep(1);

            /* Tare: read one sample */
            if (gpiod_line_set_value(sck, 1) < 0) {
                syslog(LOG_ERR, "Failed to set SCK HIGH");
                retries++;
                usleep(1000);
                continue;
            }
            usleep(1);

            val = 0;
            timeout = READ_TIMEOUT_MS;
            while (gpiod_line_get_value(dout) == 1) {
                if (timeout-- <= 0) {
                    syslog(LOG_ERR, "HX711 DOUT timeout (retry %d)", retries + 1);
                    retries++;
                    usleep(1000);
                    continue;
                }
                usleep(1);
            }

            if (gpiod_line_set_value(sck, 0) < 0) {
                syslog(LOG_ERR, "Failed to set SCK LOW");
                retries++;
                usleep(1000);
                continue;
            }
            usleep(1);

            if (gpiod_line_set_value(sck_p, 1) < 0) {
                syslog(LOG_ERR, "Failed to set SCK_P HIGH");
                retries++;
                usleep(1000);
                continue;
            }
            usleep(1);

            if (gpiod_line_set_value(sck_p, 0) < 0) {
                syslog(LOG_ERR, "Failed to set SCK_P LOW");
                retries++;
                usleep(1000);
                continue;
            }
            usleep(1);

            if (gpiod_line_set_value(sck_n, 1) < 0) {
                syslog(LOG_ERR, "Failed to set SCK_N HIGH");
                retries++;
                usleep(1000);
