static int hx711_read_weight(struct gpiod_line *dout, struct gpiod_line *sck,
                              struct gpiod_line *sck_p,
                              struct gpiod_line *sck_n,
                              int *out_value)
{
    int retries = 0;
    int val = 0;

    while (retries < MAX_RETRIES) {
        /* Wait for DOUT to go LOW (data ready) */
        int timeout = READ_TIMEOUT_MS;
        while (gpiod_line_get_value(dout) == 1) {
            if (timeout-- <= 0) {
                syslog(LOG_ERR, "HX711 DOUT timeout (retry %d)", retries + 1);
                retries++;
                usleep(1000);
                continue;
            }
            usleep(100);
        }

        /* Read 24 bits MSB-first */
        for (int i = 0; i < 24; i++) {
            if (gpiod_line_set_value(sck, 1) < 0) {
                syslog(LOG_ERR, "Failed to set SCK HIGH");
                retries++;
                usleep(1000);
                continue;
