 *
 * Controls a relay module on GPIO17 (BCM 17) via MQTT.
 *
 * Subscription: home/lights/control
 * Publish: home/lights/control/ON
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o relay_controller relay_controller.c -lrt -lpthread
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <errno.h>
#include <pthread.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC "home/lights/control"
#define MQTT_QOS 0
#define KEEP_ALIVE_INTERVAL 60
#define RECONNECT_DELAY_SEC 5
#define MAX_PAYLOAD_LEN 1024

static volatile sig_atomic_t g_running = 1;
static pthread_mutex_t g_log_mutex = PTHREAD_MUTEX_INITIALIZER;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_message(int priority, const char *message) {
    syslog(priority, "%s", message);
}

static void log_error(const char *message) {
    syslog(LOG_ERR, "%s", message);
}

static void cleanup_gpio(void) {
    gpioWrite(GPIO_PIN, 0);
    gpioSetMode(GPIO_PIN, PI_INPUT);
}

static void cleanup_mqtt(void) {
    if (gpioInitialise() >= 0) {
        gpioWrite(GPIO_PIN, 0);
        gpioTerminate();
    }
}

static void cleanup_syslog(void) {
    closelog();
}

static int connect_mqtt(void) {
    int rc;
    rc = mqtt_connect(MQTT_BROKER, MQTT_PORT, MQTT_CLIENT_ID, MQTT_QOS);
    if (rc < 0) {
        log_error("MQTT connect failed");
        return -1;
    }
    return 0;
}

static int subscribe_to_mqtt(void) {
    int rc;
    rc = mqtt_subscribe(MQTT_BROKER, MQTT_PORT, MQTT_CLIENT_ID, MQTT_TOPIC);
    if (rc < 0) {
        log_error("MQTT subscribe failed");
        return -1;
    }
    return 0;
}

static int control_relay(int on) {
    int rc;
    char payload[MAX_PAYLOAD_LEN];
    int len = snprintf(payload, sizeof(payload), "%s", on ? "ON" : "OFF");
    if (len < 0 || (size_t)len >= sizeof(payload)) {
        log_error("Payload too long");
        return -1;
    }

    rc = mqtt_publish(MQTT_BROKER, MQTT_PORT, MQTT_CLIENT_ID, MQTT_TOPIC, payload);
    if (rc < 0) {
        log_error("MQTT publish failed");
        return -1;
    }

    log_message(LOG_INFO, "Relay state set to %s", on ? "ON" : "OFF");
    return 0;
}

static void *mqtt_loop(void *arg) {
    (void)arg;
    while (g_running) {
        int rc;
        rc = mqtt_loop();
        if (rc < 0) {
            log_error("MQTT loop error");
            break;
        }
    }
    return NULL;
}

int main(void) {
    int rc;

    openlog("relay_controller", LOG_PID | LOG_CONS, LOG_USER);

    rc = signal(SIGINT, signal_handler);
    if (rc < 0) {
        log_error("Failed to register SIGINT handler");
        closelog();
        return EXIT_FAILURE;
    }
    rc = signal(SIGTERM, signal_handler);
    if (rc < 0) {
        log_error("Failed to register SIGTERM handler");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0);

    rc = connect_mqtt();
    if (rc < 0) {
        log_error("Failed to connect to MQTT broker");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    rc = subscribe_to_mqtt();
    if (rc < 0) {
        log_error("Failed to subscribe to MQTT topic");
        cleanup_mqtt();
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    pthread_t mqtt_thread;
    rc = pthread_create(&mqtt_thread, NULL, mqtt_loop, NULL);
    if (rc < 0) {
        log_error("Failed to create MQTT thread");
        cleanup_mqtt();
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    log_message(LOG_INFO, "Relay controller started");

    while (g_running) {
        sleep(KEEP_ALIVE_INTERVAL);
    }

    log_message(LOG_INFO, "Relay controller shutting down");
    cleanup_gpio();
    cleanup_mqtt();
    cleanup_syslog();

    return EXIT_SUCCESS;
}

