/*
 * DC motor control for a miniature vehicle using DRV8833 H-bridge.
 *
 * Hardware:
 *   - Raspberry Pi 3 Model B+
 *   - DRV8833 H-bridge on GPIO 17 (Motor A PWM), GPIO 18 (Motor A dir),
 *     GPIO 22 (Motor B PWM), GPIO 23 (Motor B dir), GPIO 12 (Encoder A phase A),
 *     GPIO 5 (Encoder A phase B), GPIO 6 (Encoder B phase A), GPIO 4 (Encoder B phase B).
 *   - DRV8833 VCC/GND on 3.3 V, IN1/IN2/IN3/IN4 on GPIO 17/18/22/23,
 *     OUT1/OUT2/OUT3/OUT4 on GPIO 12/5/6/4.
 *
 * Build:  gcc -O2 -Wall -o motor_control motor_control.c -lpigpio -lrt
 * Run:    sudo ./motor_control
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
