/*
 * Raspberry Pi 4 Model B – Light Sensor Monitor with LED Relay
 *
 * Hardware:
 *   - BH1750 light sensor on I2C bus 1, address 0x23 (address register 0x00)
 *   - 12 V LED strip on GPIO 17 (BCM)
 *   - Relay module on GPIO 17 (BCM, active-high)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o light_monitor light_monitor.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./light_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS            1
#define BH1750_ADDR        0x23
#define BH1750_MODE_CONT   0x00
#define BH1750_MODE_LIGHT  0x01
#define BH1750_MODE_OFF    0x02
#define BH1750_MODE_OFF_L 0x03

#define LED_PIN            17
#define LOG_FILE           "chicken_coop_log.txt"
#define POLL_INTERVAL_S    5
#define READ_DELAY_MS      50
#define LOG_FILE_SIZE      (POLL_INTERVAL_S * 1000)

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static int  init_i2c(void);
static int  init_gpio(void);
static int  read_bh1750(int handle, int *lux_out);
static void log_data(int lux, int relay_state);
static void cleanup(void);
static void signal_handler(int sig);

/* ----------------------------- I2C -------------------------------------- */
static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        return -1;
    }
    return 0;
}

/* ----------------------------- GPIO ------------------------------------- */
static int init_gpio(void)
{
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", LED_PIN);
        return -1;
    }
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(%d, 0) failed\n", LED_PIN);
        return -1;
    }
    return 0;
}

/* ----------------------------- BH1750 ----------------------------------- */
static int read_bh1750(int handle, int *lux_out)
{
    /*
     * BH1750 mode 0: continuous measurement, no hysteresis.
     * The datasheet specifies a typical measurement time of ~1.5 ms.
     * We wait at least 2 ms to be safe.
     */
    gpioDelay(2000);

    uint8_t cmd = BH1750_MODE_CONT;
    if (i2cWriteDevice(handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "Error: i2cWriteDevice(mode) failed\n");
        return -1;
    }

    /*
     * Wait for the sensor to settle (~1.5 ms).
     * We use a small delay to avoid busy-waiting.
     */
    gpioDelay(2000);

    /*
     * Read 6 bytes: 2 bytes for the light sensor data, 2 bytes for the
     * temperature sensor data, and 2 bytes for the digital temperature
     * compensation.
     */
    uint8_t buf[6];
    int bytes_read = i2cReadDevice(handle, (char *)buf, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Error: i2cReadDevice returned %d (expected 6)\n", bytes_read);
        return -1;
    }

    /*
     * The light sensor data is stored in the last 2 bytes of the buffer.
     * The first 2 bytes contain the temperature data.
     */
    uint16_t raw_light = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t raw_temp  = ((uint16_t)buf[2] << 8) | buf[3];

    /*
     * The temperature compensation is stored in the first 2 bytes of the
     * data buffer.
     */
    uint16_t raw_temp_comp = ((uint16_t)buf[2] << 8) | buf[3];

    /*
     * The raw light value is a 12-bit value, with the first 2 bits
     * representing the high byte and the remaining 10 bits representing
     * the low byte.
     */
    *lux_out = (raw_light & 0x0FFF) << 2;

    /*
     * The temperature compensation is a 12-bit value, with the first 2
     * bits representing the high byte and the remaining 10 bits representing
     * the low byte.
     */
    raw_temp_comp = (raw_temp_comp & 0x0FFF) << 2;

    /*
     * Hysteresis: lux < 50 => relay ON, lux > 200 => relay OFF.
     * The sensor datasheet specifies a typical range of ~50-300 lux.
     */
    int lux = (raw_light & 0x0FFF) << 2;
    if (lux < 50) {
        if (gpioWrite(LED_PIN, 1) != 0) {
            fprintf(stderr, "Warning: gpioWrite(%d, 1) failed\n", LED_PIN);
        }
    } else if (lux > 200) {
        if (gpioWrite(LED_PIN, 0) != 0) {
            fprintf(stderr, "Warning: gpioWrite(%d, 0) failed\n", LED_PIN);
        }
    }

    return 0;
}

/* ----------------------------- Logging ----------------------------------- */
static void log_data(int lux, int relay_state)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(g_log_file, "%s: Lux = %d, Relay = %s\n", ts, lux, relay_state ? "ON" : "OFF");
    fflush(g_log_file);
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Initialize I2C */
    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize GPIO */
    if (init_gpio() != 0) {
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error: fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "--- Log started ---\n");
        fflush(g_log_file);
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Light sensor monitoring started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        int lux = 0;
        int relay_state = 0;

        if (read_bh1750(g_i2c_handle, &lux) != 0) {
            fprintf(stderr, "Warning: BH1750 read failed; relay off\n");
            relay_state = 0;
        } else {
            relay_state = (lux < 50) ? 1 : 0;
        }

        log_data(lux, relay_state);

        /* Sleep in 100 ms increments so signals are caught promptly */
