#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_MS 50
#define LOOP_DELAY_MS 10
#define POLL_DELAY_MS 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *state) {
    FILE *fp = fopen("relay_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, state);
    } else {
        fprintf(fp, "UNKNOWN TIME\n");
    }
    fclose(fp);
    return 0;
}

static int read_touch_sensor(int gpio) {
    int val = gpioRead(gpio);
    if (val < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", gpio, strerror(errno));
        return -1;
    }
    return val;
}

static int toggle_relay(int gpio) {
    int ret = gpioWrite(gpio, 1);
    if (ret < 0) {
        fprintf(stderr, "Error writing to GPIO %d: %s\n", gpio, strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) < 0) {
        fprintf(stderr, "Error initialising relay state to OFF\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        gpioWrite(RELAY_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch-toggled relay control started. Touch sensor on GPIO %d, relay on GPIO %d.\n",
           TOUCH_SENSOR_PIN, RELAY_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int touch = read_touch_sensor(TOUCH_SENSOR_PIN);
        if (touch < 0) {
            gpioDelay(POLL_DELAY_MS * 1000);
            continue;
        }

        if (touch == 1) {
            printf("Touch detected!\n");
            if (toggle_relay(RELAY_PIN) < 0) {
                fprintf(stderr, "Error toggling relay\n");
            }
            if (log_event("ON") < 0) {
                fprintf(stderr, "Error logging event\n");
            }
        } else {
            printf("No touch detected.\n");
            if (log_event("OFF") < 0) {
                fprintf(stderr, "Error logging event\n");
            }
        }

        gpioDelay(LOOP_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

