/*
 * water_flow_monitor.c
 *
 * Raspberry Pi 5 – YF-S201 water flow sensor on GPIO 17 (BCM),
 * solenoid valve on GPIO 27 (BCM), and shared pulse-count log file.
 *
 * Build:  gcc -O2 -Wall -Wextra -o water_flow_monitor water_flow_monitor.c \
 *   -lgpiod -lpthread -lrt
 *
 * Run:    sudo ./water_flow_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <errno.h>
#include <unistd.h>

#include <gpiod.h>

#define FLOW_SENSOR_PIN      17
#define SOLENOID_PIN         27
#define LOG_FILE             "water_flow.log"
#define FLOW_THRESHOLD_LPM   5.0f
#define FLOW_HYSTERESIS_LPM  4.5f
#define DEBOUNCE_TIMEOUT_US  1000000   /* 1 second */
#define SAMPLE_INTERVAL_S    1

/* Global state for the shared pulse-count counter */
static volatile uint32_t pulse_count = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;

/* Global state for the solenoid valve */
static volatile int solenoid_open = 0;

/* Global state for the program */
static volatile sig_atomic_t program_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(const char *message)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[unknown time] %s\n", message);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int gpio_init(void)
{
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "Error: cannot open GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    struct gpiod_line *flow_line = gpiod_chip_get_line(chip, FLOW_SENSOR_PIN);
    struct gpiod_line *solenoid_line = gpiod_chip_get_line(chip, SOLENOID_PIN);
    if (!flow_line || !solenoid_line) {
        fprintf(stderr, "Error: cannot get GPIO lines: %s\n", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_input_flags(flow_line, "water-flow",
                                        GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Error: cannot request flow sensor line as input: %s\n",
                strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(solenoid_line, "solenoid", 0) < 0) {
        fprintf(stderr, "Error: cannot request solenoid line as output: %s\n",
                strerror(errno));
        return -1;
    }

    return 0;
}

static void gpio_cleanup(void)
{
    /* Ensure solenoid is off before releasing lines */
    if (solenoid_open) {
        (void)gpiod_line_set_value(solenoid_line, 0);
        solenoid_open = 0;
    }

    if (flow_line) {
        gpiod_line_release(flow_line);
        flow_line = NULL;
    }
    if (solenoid_line) {
        gpiod_line_release(solenoid_line);
        solenoid_line = NULL;
    }

    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* Pulse-count counting                                                 */
/* ------------------------------------------------------------------ */
static void pulse_count_callback(struct gpiod_line *line,
                                 unsigned int level,
                                 void *userdata)
{
    (void)userdata;

    pthread_mutex_lock(&pulse_mutex);

    if (level == 1) {
        pulse_count++;
    } else if (level == 0) {
        pulse_count--;
    }

    /* Debounce: only update if the count has changed since the last
     * interrupt (1 second ago). */
    if (pulse_count != pulse_count_prev) {
        pulse_count_prev = pulse_count;
    }

    pthread_mutex_unlock(&pulse_mutex);
}

/* ------------------------------------------------------------------ */
/* Solenoid control                                                    */
/* ------------------------------------------------------------------ */
static void solenoid_control(void)
{
    if (solenoid_open) {
        (void)gpiod_line_set_value(solenoid_line, 0);
        solenoid_open = 0;
    } else {
        (void)gpiod_line_set_value(solenoid_line, 1);
        solenoid_open = 1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize GPIO */
    if (gpio_init() < 0) {
        return EXIT_FAILURE;
    }

    /* Initialize pulse-count counter */
    if (pthread_mutex_init(&pulse_mutex, NULL) != 0) {
        fprintf(stderr, "Error: mutex initialization failed: %s\n",
                strerror(errno));
        gpio_cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize solenoid valve */
    solenoid_open = 0;

    /* Register ISR callback for flow sensor */
    if (gpiod_line_request_event_source(flow_line, "water-flow",
                                          pulse_count_callback, NULL) < 0) {
        fprintf(stderr, "Error: cannot request flow sensor event source: %s\n",
                strerror(errno));
        pthread_mutex_destroy(&pulse_mutex);
        gpio_cleanup();
        return EXIT_FAILURE;
    }

    log_event("Water flow monitoring started");

    /* Main sampling loop */
    while (program_running) {
        /* Wait for the next 1-second interrupt */
        struct timespec ts = {
            .tv_sec = SAMPLE_INTERVAL_S,
            .tv_nsec = 0
        };
        while (nanosleep(&ts, &ts) == -1 && errno == EINTR && program_running) {
            /* Retry if interrupted by a signal */
        }

        if (!program_running) {
            break;
        }

        /* Read pulse count */
        uint32_t pulse_count_val = pulse_count;

        /* Log the reading */
        char log_msg[128];
        snprintf(log_msg, sizeof(log_msg),
                 "Flow: %u LPM (count=%u)",
                 (unsigned)pulse_count_val, pulse_count_val);
        log_event(log_msg);

        /* Control solenoid valve */
        solenoid_control();

        /* Debounce: wait for the next 1-second interrupt */
        ts.tv_sec = 0;
        ts.tv_nsec = DEBOUNCE_TIMEOUT_US;
        while (nanosleep(&ts, &ts) == -1 && errno == EINTR && program_running) {
            /* Retry if interrupted by a signal */
        }
    }

    /* Cleanup */
    log_event("Water flow monitoring stopped");
    solenoid_control();
    pthread_mutex_destroy(&pulse_mutex);
    gpio_cleanup();

    return EXIT_SUCCESS;
}

