#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_MS 50
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int debounce_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)tick;
    (void)userdata;
    if (level == 1) {
        return 1;
    }
    return 0;
}

static int read_touch_sensor(void) {
    int value = gpioRead(TOUCH_SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", TOUCH_SENSOR_PIN, strerror(errno));
        return -1;
    }
    return value;
}

static int toggle_relay(void) {
    int relay_state = gpioRead(RELAY_PIN);
    if (relay_state < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", RELAY_PIN, strerror(errno));
        return -1;
    }
    if (gpioWrite(RELAY_PIN, relay_state) != 0) {
        fprintf(stderr, "Error writing GPIO %d: %s\n", RELAY_PIN, strerror(errno));
        return -1;
    }
    return 0;
}

static void log_relay_state(int relay_state) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return;
    }

    printf("[%s] Relay: %s\n", timestamp, relay_state ? "ON" : "OFF");
    fflush(stdout);
}

int main(int argc, char *argv[]) {
    int debounce_ms = DEBOUNCE_MS;
    if (argc > 1) {
        if (sscanf(argv[1], "%d", &debounce_ms) != 1) {
            fprintf(stderr, "Invalid debounce argument: %s\n", argv[1]);
            return EXIT_FAILURE;
        }
    }

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error initialising relay state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(TOUCH_SENSOR_PIN, debounce_callback, NULL) != 0) {
        fprintf(stderr, "Error setting alert function for GPIO %d\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started on GPIO %d. Debounce: %d ms. Relay on GPIO %d.\n",
           TOUCH_SENSOR_PIN, debounce_ms, RELAY_PIN);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (running) {
        int touch_state = read_touch_sensor();
        if (touch_state < 0) {
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (touch_state == 1) {
            if (toggle_relay() != 0) {
                fprintf(stderr, "Error toggling relay\n");
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

