#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define PWM_FREQ 50
#define PWM_PERIOD_US 20000
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define KEY_DECREMENT 10
#define KEY_INCREMENT 10

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_servo_angle(int angle) {
    if (angle < MIN_ANGLE) angle = MIN_ANGLE;
    if (angle > MAX_ANGLE) angle = MAX_ANGLE;
    int pulse_width = (int)((float)angle * PWM_PERIOD_US / 180.0f);
    if (pulse_width < MIN_PULSE_WIDTH) pulse_width = MIN_PULSE_WIDTH;
    if (pulse_width > MAX_PULSE_WIDTH) pulse_width = MAX_PULSE_WIDTH;
    int rc = gpioPWM(SERVO_PIN, pulse_width);
    if (rc < 0) {
        fprintf(stderr, "gpioPWM failed: %s\n", pigpio_error(rc));
        return -1;
    }
    return 0;
}

static int read_keyboard_input(int *angle) {
    int ch;
    while (running) {
        ch = getchar();
        if (ch == '\n') break;
        if (ch == 'q' || ch == 'Q') break;
        if (ch == '+' || ch == '-' || ch == '=') {
            *angle += KEY_DECREMENT;
            if (*angle < MIN_ANGLE) *angle = MIN_ANGLE;
            if (*angle > MAX_ANGLE) *angle = MAX_ANGLE;
            if (read_keyboard_input(angle) != 0) return -1;
            return 0;
        }
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO%d\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(SERVO_PIN, PWM_FREQ) != 0) {
        fprintf(stderr, "gpioSetPWMfrequency failed for GPIO%d\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(SERVO_PIN, PWM_PERIOD_US) != 0) {
        fprintf(stderr, "gpioSetPWMrange failed for GPIO%d\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int angle = 90;
    int last_angle = 90;

    while (running) {
        if (read_keyboard_input(&angle) == 0) {
            int new_angle = angle + KEY_INCREMENT;
            if (new_angle < MIN_ANGLE) new_angle = MIN_ANGLE;
            if (new_angle > MAX_ANGLE) new_angle = MAX_ANGLE;
            if (set_servo_angle(new_angle) != 0) {
                fprintf(stderr, "Failed to set servo angle\n");
                break;
            }
            printf("Angle: %d°\n", new_angle);
            last_angle = new_angle;
        } else {
            break;
        }
        usleep(10000);
    }

    gpioPWM(SERVO_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

