static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_touch_sensor(int pin) {
    int level = gpioRead(pin);
    if (level < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", pin, pigpio_error(level));
        return -1;
    }
    return level;
}

static int toggle_relay(int pin) {
    int current = gpioRead(pin);
    if (current < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", pin, pigpio_error(current));
        return -1;
    }
    if (current == RELAY_HIGH) {
        if (gpioWrite(pin, RELAY_OFF) < 0) {
            fprintf(stderr, "Error toggling GPIO %d: %s\n", pin, pigpio_error(gpioWrite(pin, RELAY_OFF)));
            return -1;
        }
        return 0;
    }
    if (current == RELAY_OFF) {
        if (gpioWrite(pin, RELAY_ON) < 0) {
            fprintf(stderr, "Error toggling GPIO %d: %s\n", pin, pigpio_error(gpioWrite(pin, RELAY_ON)));
            return -1;
        }
        return 0;
    }
    if (current == RELAY_HIGH) {
        if (gpioWrite(pin, RELAY_HIGH) < 0) {
            fprintf(stderr, "Error toggling GPIO %d: %s\n", pin, pigpio_error(gpioWrite(pin, RELAY_HIGH)));
            return -1;
        }
        return 0;
    }
    if (current == RELAY_OFF) {
        if (gpioWrite(pin, RELAY_OFF) < 0) {
            fprintf(stderr, "Error toggling GPIO %d: %s\n", pin, pigpio_error(gpioWrite(pin, RELAY_OFF)));
            return -1;
        }
        return 0;
    }
    return -1;
}

static int force_relay_off(int pin) {
    if (gpioWrite(pin, RELAY_OFF) < 0) {
        fprintf(stderr, "Error toggling GPIO %d: %s\n", pin, pigpio_error(gpioWrite(pin, RELAY_OFF)));
        return -1;
    }
    return 0;
}

static int check_relay_state(int pin) {
