 * using ASCO RedHat 8210 series valve and YF-S201 flow sensor.
 *
 * Hardware:
 *   - ASCO RedHat 8210 valve on GPIO 18 (BCM, hardware PWM 0)
 *   - YF-S201 flow sensor on GPIO 24 (BCM) with interrupt on each rising edge
 *   - YF-S201 flow sensor output is a digital signal; the flow rate is
 *     proportional to the number of edges per second.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o flow_control flow_control.c -lrt
 *
 * Run:
 *   ./flow_control -t <target_flow_rate_lpm>
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <linux/gpiochip.h>

#define GPIO_VALVE_PIN      18
#define GPIO_ENABLE_PIN     23
#define GPIO_FLOW_SENSOR_PIN 24
#define PWM_FREQUENCY      1000   /* Hz */
#define PWM_RANGE          255
#define PWM_DUTY_CYCLE     (PWM_RANGE / 2)
#define LOG_FILE           "flow_log.csv"
#define SAMPLE_INTERVAL_US 100000 /* 100 ms */
#define Kp                 1.0
#define TARGET_FLOW_RATE   0.0    /* L/min */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* ISR: flow sensor interrupt (rising edge)                             */
/* ------------------------------------------------------------------ */
static void flow_isr(int gpio, int level, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        /* Rising edge: count edges per second and compute flow rate */
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        long elapsed_us = (long)(ts.tv_sec * 1000000L + ts.tv_nsec / 1000L);
        long flow_rate = (elapsed_us * 1000L) / SAMPLE_INTERVAL_US;
        /* YF-S201 output is a digital signal; the flow rate is proportional
         * to the number of edges per second. */
        printf("Flow rate: %ld L/min\n", flow_rate);
    }
}

/* ------------------------------------------------------------------ */
/* Signal handler                                                       */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* GPIO setup helpers                                                   */
/* ------------------------------------------------------------------ */
static int setup_gpio(void)
{
    struct gpiochip *chip = gpiochip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return -1;
    }

    int pin = GPIO_VALVE_PIN;
    if (gpio_is_output(pin)) {
        if (gpio_set_direction(pin, GPIO_DIR_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pin);
            return -1;
        }
    } else {
        fprintf(stderr, "Invalid GPIO pin %d (must be output)\n", pin);
        return -1;
    }

    if (gpio_set_mode(pin, GPIO_MODE_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", pin);
        return -1;
    }

    /* Enable valve enable line (active-high) */
    if (gpio_set_direction(GPIO_ENABLE_PIN, GPIO_DIR_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_ENABLE_PIN);
        return -1;
    }
    if (gpio_write(GPIO_ENABLE_PIN, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO %d HIGH\n", GPIO_ENABLE_PIN);
        return -1;
    }

    /* YF-S201 flow sensor output is a digital signal; we read it as an
     * edge-triggered interrupt. */
    if (gpio_is_input(GPIO_FLOW_SENSOR_PIN) < 0) {
        fprintf(stderr, "Invalid GPIO %d (must be input)\n", GPIO_FLOW_SENSOR_PIN);
        return -1;
    }

    /* Register ISR for rising edge on flow sensor */
    if (gpio_set_interrupt_line_flags(GPIO_FLOW_SENSOR_PIN,
                                     GPIO_INT_EDGE_RISING,
                                     0) < 0) {
        fprintf(stderr, "Failed to set interrupt on GPIO %d\n", GPIO_FLOW_SENSOR_PIN);
        return -1;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                              */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Ensure PWM is off and GPIO is low */
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (gpio_set_direction(GPIO_VALVE_PIN, GPIO_DIR_OUTPUT) < 0)
        fprintf(stderr, "Warning: failed to reset GPIO %d\n", GPIO_VALVE_PIN);
    if (gpio_set_direction(GPIO_ENABLE_PIN, GPIO_DIR_OUTPUT) < 0)
        fprintf(stderr, "Warning: failed to reset GPIO %d\n", GPIO_ENABLE_PIN);
    if (gpio_write(GPIO_VALVE_PIN, 0) < 0)
        fprintf(stderr, "Warning: failed to reset GPIO %d\n", GPIO_VALVE_PIN);
    if (gpio_set_interrupt_line_flags(GPIO_FLOW_SENSOR_PIN,
                                     GPIO_INT_EDGE_RISING,
                                     0) < 0)
        fprintf(stderr, "Warning: failed to reset GPIO %d\n", GPIO_FLOW_SENSOR_PIN);

    /* Turn off PWM on all GPIOs */
    if (gpio_set_direction(GPIO_VALVE_PIN, GPIO_DIR_OUTPUT) < 0)
        fprintf(stderr, "Warning: failed to reset GPIO %d\n", GPIO_VALVE_PIN);
    if (gpio_set_direction(GPIO_ENABLE_PIN, GPIO_DIR_OUTPUT) < 0)
