/*
 * MPR121 Capacitive Touch Sensor Monitor for Raspberry Pi Zero W
 * Uses I2C bus 1 (SDA=GPIO2, SCL=GPIO3) and the pigpio library.
 *
 * Wiring:
 *   MPR121 VDD  -> 3.3V (Pin 1)
 *   MPR121 GND  -> GND  (Pin 6)
 *   MPR121 SDA  -> GPIO2 (Pin 3)
 *   MPR121 SCL  -> GPIO3 (Pin 5)
 *   Relay IN    -> GPIO17 (Pin 11)
 *
 * Build: gcc -Wall -o mpr121_monitor mpr121_monitor.c -lpigpio -lrt
 * Run:   sudo ./mpr121_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- MPR121 Configuration ---- */
#define I2C_BUS        1
#define MPR121_ADDR    0x5A

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS_L  0x00
#define MPR121_TOUCHSTATUS_H  0x01
#define MPR121_ELECTRODE_DATA 0x2B
#define MPR121_CONFIG        0x5E
#define MPR121_FILTER        0x5F
#define MPR121_CHARGE_TIME   0x5C
#define MPR121_ELECTRODE_CURRENT_L 0x5D
#define MPR121_ELECTRODE_CURRENT_H 0x5E

/* ---- Relay GPIO ---- */
#define RELAY_GPIO 17

/* ---- Global state ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- Function prototypes ---- */
static int  mpr121_write_byte(int handle, uint8_t reg, uint8_t value);
static int  mpr121_read_byte(int handle, uint8_t reg);
static int  mpr121_init(int handle);
static int  mpr121_configure(int handle);
static int  mpr121_start_run(int handle);
static int  mpr121_stop(int handle);
static int  mpr121_read_touch_status(int handle);
static int  mpr121_set_electrode_current(int handle, uint8_t electrode, uint16_t current);
static int  mpr121_set_touch_threshold(int handle, uint8_t electrode, uint16_t touch_threshold);
static int  mpr121_set_release_threshold(int handle, uint8_t electrode, uint16_t release_threshold);
static int  mpr121_set_filter(int handle, uint8_t filter);
static int  mpr121_set_charge_time(int handle, uint8_t charge_time);
static int  mpr121_start(int handle);
static void cleanup(int handle);
static void signal_handler(int sig);

/*
 * Write a single byte to an MPR121 register.
 * Returns 0 on success, -1 on failure.
 */
static int mpr121_write_byte(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error: I2C write to reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

/*
 * Read a single byte from an MPR121 register.
 * Returns 0 on success, -1 on failure.
 */
static int mpr121_read_byte(int handle, uint8_t reg) {
    char buf[1] = { (char)reg };
    if (i2cWriteDevice(handle, buf, 1) != 1) {
        fprintf(stderr, "Error: I2C write (reg select 0x%02X) failed\n", reg);
        return -1;
    }
    char val;
    if (i2cReadDevice(handle, &val, 1) != 1) {
        fprintf(stderr, "Error: I2C read from reg 0x%02X failed\n", reg);
        return -1;
    }
    return (int)val;
}

/*
 * Initialize the MPR121 sensor.
 * Returns 0 on success, -1 on failure.
 */
static int mpr121_init(int handle) {
    /* Stop the sensor */
    if (mpr121_write_byte(handle, MPR121_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to stop MPR121\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle */

    /* Configure touch and release thresholds for all twelve electrodes */
    for (int i = 0; i < 12; i++) {
        if (mpr121_write_byte(handle, MPR121_ELECTRODE_DATA + (i * 2), 0x00) != 0) {
            fprintf(stderr, "Error: Failed to set touch threshold for electrode %d\n", i);
            return -1;
        }
        if (mpr121_write_byte(handle, MPR121_ELECTRODE_DATA + (i * 2) + 1, 0x00) != 0) {
            fprintf(stderr, "Error: Failed to set release threshold for electrode %d\n", i);
            return -1;
        }
    }

    /* Set filter to 1 (default) */
    if (mpr121_write_byte(handle, MPR121_FILTER, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to set filter\n");
        return -1;
    }

    /* Set charge time to 100 ms (default) */
    if (mpr121_write_byte(handle, MPR121_CHARGE_TIME, 0x0C) != 0) {
        fprintf(stderr, "Error: Failed to set charge time\n");
        return -1;
    }

    /* Set electrode current limits */
    for (int i = 0; i < 12; i++) {
        if (mpr121_write_byte(handle, MPR121_ELECTRODE_CURRENT_L + (i * 2), 0x00) != 0) {
            fprintf(stderr, "Error: Failed to set electrode current limit for electrode %d\n", i);
            return -1;
        }
        if (mpr121_write_byte(handle, MPR121_ELECTRODE_CURRENT_H + (i * 2), 0x00) != 0) {
            fprintf(stderr, "Error: Failed to set electrode current limit for electrode %d\n", i);
            return -1;
        }
    }

    /* Start the MPR121 in run mode */
    if (mpr121_write_byte(handle, MPR121_CONFIG, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to start MPR121\n");
        return -1;
    }

    return 0;
}

/*
 * Configure the MPR121.
 * Returns 0 on success, -1 on failure.
 */
static int mpr121_configure(int handle) {
    /* Stop the sensor */
    if (mpr121_write_byte(handle, MPR121_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to stop MPR121\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle */

    /* Configure touch and release thresholds for all twelve electrodes */
    for (int i = 0; i < 12; i++) {
        if (mpr121_write_byte(handle, MPR121_ELECTRODE_DATA + (i * 2), 0x00) != 0) {
            fprintf(stderr, "Error: Failed to set touch threshold for electrode %d\n", i);
            return -1;
        }
        if (mpr121_write_byte(handle, MPR121_ELECTRODE_DATA + (i * 2) + 1, 0x00) != 0) {
            fprintf(stderr, "Error: Failed to set release threshold for electrode %d\n", i);
            return -1;
        }
    }

    /* Set filter to 1 (default) */
    if (mpr121_write_byte(handle, MPR121_FILTER, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to set filter\n");
        return -1;
    }

    /* Set charge time to 100 ms (default) */
    if (mpr121_write_byte(handle, MPR121_CHARGE_TIME, 0x0C) != 0) {
        fprintf(stderr, "Error: Failed to set charge time\n");
        return -1;
    }

    /* Set electrode current limits */
    for (int i = 0; i < 12; i++) {
        if (mpr121_write_byte(handle, MPR121_ELECTRODE_CURRENT_L + (i * 2), 0x00) != 0) {
            fprintf(stderr, "Error: Failed to set electrode current limit for electrode %d\n", i);
            return -1;
        }
        if (mpr121_write_byte(handle, MPR121_ELECTRODE_CURRENT_H + (i * 2), 0x00) != 0) {
            fprintf(stderr, "Error: Failed to set electrode current limit for electrode %d\n", i);
            return -1;
        }
    }

    /* Start the MPR121 in run mode */
    if (mpr121_write_byte(handle, MPR121_CONFIG, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to start MPR121\n");
        return -1;
    }

    return 0;
}

/*
 * Start the MPR121 in run mode.
 * Returns 0 on success, -1 on failure.
 */
static int mpr121_start(int handle) {
    if (mpr121_write_byte(handle, MPR121_CONFIG, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to start MPR121\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle */
    return 0;
}

/*
 * Stop the MPR121.
 * Returns 0 on success, -1 on failure.
 */
static int mpr121_stop(int handle) {
    if (mpr121_write_byte(handle, MPR121_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to stop MPR121\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle */
    return 0;
}

/*
 * Read the current touch status from all twelve electrodes.
 * Returns the number of touch events (0 or 1), or -1 on failure.
 */
static int mpr121_read_touch_status(int handle) {
    int status = 0;
    for (int i = 0; i < 12; i++) {
        int val = mpr121_read_byte(handle, MPR121_TOUCHSTATUS_L + (i * 2));
        if (val < 0) {
            fprintf(stderr, "Error: Failed to read touch status for electrode %d\n", i);
            return -1;
        }
        status |= (1 << i);
    }
    return status;
}

/*
 * Set the electrode current for a given electrode number.
 * Returns 0 on success, -1 on failure.
 */
static int mpr121_set_electrode_current(int handle, uint8_t electrode, uint16_t current) {
    if (mpr121_write_byte(handle, MPR121_ELECTRODE_CURRENT_L + (electrode * 2), (uint8_t)current) != 0) {
        fprintf(stderr, "Error: Failed to set electrode current for electrode %d\n", electrode);
        return -1;
    }
    return 0;
}

/*
 * Set the touch threshold for a given electrode number.
 * Returns 0 on success, -1 on failure.
 */
static int mpr121_set_touch_threshold(int handle, uint8_t electrode, uint16_t touch_threshold) {
    if (mpr121_write_byte(handle, MPR121_TOUCHSTATUS_L + (electrode * 2), (uint8_t)touch_threshold) != 0) {
        fprintf(stderr, "Error: Failed to set touch threshold for electrode %d\n", electrode);
        return -1;
    }
    return 0;
}

/*
 * Set the release threshold for a given electrode number.
 * Returns 0 on success, -1 on failure.
 */
static int mpr121_set_release_threshold(int handle, uint8_t electrode, uint16_t release_threshold) {
    if (mpr121_write_byte(handle, MPR121_RELEASE_THRESHOLD_L + (electrode * 2), (uint8_t)release_threshold) != 0) {
        fprintf(stderr, "Error: Failed to set release threshold for electrode %d\n", electrode);
        return -1;
    }
    return 0;
}

/*
 * Set the filter for the MPR121.
 * Returns 0 on success, -1 on failure.
 */
static int mpr121_set_filter(int handle, uint8_t filter) {
    if (mpr121_write_byte(handle, MPR121_FILTER, filter) != 0) {
        fprintf(stderr, "Error: Failed to set filter\n");
        return -1;
    }
    return 0;
}

/*
 * Set the charge time for the MPR121.
 * Returns 0 on success, -1 on failure.
 */
static int mpr121_set_charge_time(int handle, uint8_t charge_time) {
    if (mpr121_write_byte(handle, MPR121_CHARGE_TIME, charge_time) != 0) {
        fprintf(stderr, "Error: Failed to set charge time\n");
        return -1;
    }
    return 0;
}

/*
 * Start the MPR121.
 * Returns 0 on success, -1 on failure.
 */
static int mpr121_start(int handle) {
    if (mpr121_write_byte(handle, MPR121_CONFIG, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to start MPR121\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle */
    return 0;
}

/*
 * Cleanup the MPR121 sensor.
 * Closes the I2C connection and releases the GPIO.
 */
static void cleanup(int handle) {
    if (handle >= 0) {
        /* Stop the MPR121 */
        if (mpr121_stop(handle) != 0) {
            fprintf(stderr, "Warning: Failed to stop MPR121 during cleanup\n");
        }
        /* Close the I2C connection */
        i2cClose(handle);
    }
    gpioTerminate();
}

/*
 * Signal handler for graceful shutdown.
 */
static void signal_handler(int sig) {
    (void)sig;
    fprintf(stderr, "\nReceived signal, shutting down...\n");

