            return -1;
        }
    }

    /* Set filter to 1 (default) */
    if (mpr121_write_byte(handle, MPR121_FILTER, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to set filter\n");
        return -1;
    }

    /* Set charge time to 100 ms (default) */
    if (mpr121_write_byte(handle, MPR121_CHARGE_TIME, 0x0C) != 0) {
        fprintf(stderr, "Error: Failed to set charge time\n");
        return -1;
    }

    /* Set electrode current limits */
    for (int i = 0; i < 12; i++) {
        if (mpr121_write_byte(handle, MPR121_ELECTRODE_CURRENT_L + (i * 2), 0x00) != 0) {
            fprintf(stderr, "Error: Failed to set electrode current limit for electrode %d\n", i);
            return -1;
        }
        if (mpr121_write_byte(handle, MPR121_ELECTRODE_CURRENT_H + (i * 2), 0x00) != 0) {
            fprintf(stderr, "Error: Failed to set electrode current limit for electrode %d\n", i);
            return -1;
        }
    }

    /* Start the MPR121 in run mode */
    if (mpr121_write_byte(handle, MPR121_CONFIG, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to start MPR121\n");
        return -1;
