#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define PWM_RANGE 255
#define PWM_FREQUENCY 1000
#define MIN_DUTY_CYCLE 0
#define MAX_DUTY_CYCLE PWM_RANGE
#define MIN_DURATION_MS 50
#define MAX_DURATION_MS 200
#define STEPS_PER_PATTERN 5
#define MAX_PATTERN_STEPS 15

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int set_motor_pwm(int pin, int duty_cycle) {
    if (gpioPWM(pin, duty_cycle) != 0) {
        fprintf(stderr, "Error: gpioPWM failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

static int play_pattern(int pattern[], int pattern_length) {
    for (int i = 0; i < pattern_length && g_running; i++) {
        if (set_motor_pwm(MOTOR1_PIN, pattern[i]) != 0) {
            fprintf(stderr, "Error: failed to set motor 1 PWM\n");
            return -1;
        }
        if (set_motor_pwm(MOTOR2_PIN, pattern[i]) != 0) {
            fprintf(stderr, "Error: failed to set motor 2 PWM\n");
            return -1;
        }
        gpioDelay(MIN_DURATION_MS * 1000);
        if (set_motor_pwm(MOTOR1_PIN, 0) != 0) {
            fprintf(stderr, "Error: failed to reset motor 1\n");
            return -1;
        }
        if (set_motor_pwm(MOTOR2_PIN, 0) != 0) {
            fprintf(stderr, "Error: failed to reset motor 2\n");
            return -1;
        }
    }
    return 0;
}

static int generate_random_pattern(int *pattern, int *pattern_length) {
    *pattern = malloc(STEPS_PER_PATTERN * sizeof(int));
    if (*pattern == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for pattern\n");
        return -1;
    }
    *pattern_length = 0;
    while (*pattern_length < STEPS_PER_PATTERN) {
        int step = rand() % STEPS_PER_PATTERN;
        if (step < STEPS_PER_PATTERN / 2) {
            *pattern[*pattern_length] = step;
            *pattern_length++;
        } else {
            *pattern[*pattern_length] = STEPS_PER_PATTERN - step - 1;
            *pattern_length++;
        }
        if (g_running) {
            gpioDelay(MIN_DURATION_MS * 1000);
        }
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", MOTOR1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", MOTOR2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(MOTOR1_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(MOTOR2_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(MOTOR1_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(MOTOR2_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: failed to register signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int pattern[MAX_PATTERN_STEPS];
    int pattern_length = 0;

    while (g_running) {
        if (generate_random_pattern(pattern, &pattern_length) != 0) {
            fprintf(stderr, "Error: failed to generate random pattern\n");
            break;
        }

        if (play_pattern(pattern, pattern_length) != 0) {
            fprintf(stderr, "Error: failed to play pattern\n");
            break;
        }
    }

    if (g_running) {
        set_motor_pwm(MOTOR1_PIN, 0);
        set_motor_pwm(MOTOR2_PIN, 0);
    }

    free(pattern);
    gpioTerminate();
    return EXIT_SUCCESS;
}

