/*
 * Raspberry Pi 4 Model B – Rain Window Control
 *
 * Sensor: Seeed Studio Grove Rain Sensor (BCM GPIO4)
 * Motor: L298N motor driver (BCM GPIO17 IN1, GPIO18 IN2, GPIO27 PWM)
 *
 * Build: gcc -O2 -Wall -o window_control window_control.c -lrt
 * Run:   sudo ./window_control
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <errno.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27

#define DEBOUNCE_DELAY_US 50000   /* 50 ms between readings */
#define MOTOR_DURATION_US   5000000 /* 5 seconds */
#define LOG_FILE "/var/log/window_control.log"
#define SAMPLE_INTERVAL_S  60
#define MOTOR_ON_DURATION_S 5

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_message(const char *level, const char *msg)
{
    if (!g_log_file)
        return;

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "UNKNOWN");

    char level_str[16];
    if (level)
        strncpy(level_str, level, sizeof(level_str) - 1);
    else
        snprintf(level_str, sizeof(level_str), "UNKNOWN");

    fprintf(g_log_file, "[%s] %s: %s\n", ts, level_str, msg);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Motor control                                                       */
/* ------------------------------------------------------------------ */
static void motor_stop(void)
{
    if (gpioWrite(MOTOR_IN1_PIN, 0) < 0)
        syslog(LOG_ERR, "Failed to set IN1 low on motor stop");
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0)
        syslog(LOG_ERR, "Failed to set IN2 low on motor stop");
    if (gpioPWM(MOTOR_PWM_PIN, 0) < 0)
        syslog(LOG_ERR, "Failed to set PWM low on motor stop");
}

static void motor_on(void)
{
    if (gpioWrite(MOTOR_IN1_PIN, 1) < 0)
        syslog(LOG_ERR, "Failed to set IN1 high on motor on");
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0)
        syslog(LOG_ERR, "Failed to set IN2 low on motor on");
    if (gpioPWM(MOTOR_PWM_PIN, 150) < 0)
        syslog(LOG_ERR, "Failed to set PWM high on motor on");
}

static void motor_off(void)
{
    if (gpioWrite(MOTOR_IN1_PIN, 0) < 0)
        syslog(LOG_ERR, "Failed to set IN1 low on motor off");
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0)
        syslog(LOG_ERR, "Failed to set IN2 low on motor off");
    if (gpioPWM(MOTOR_PWM_PIN, 0) < 0)
        syslog(LOG_ERR, "Failed to set PWM low on motor off");
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
static int read_rain_sensor(void)
{
    int val = gpioRead(RAIN_SENSOR_PIN);
    if (val < 0)
        syslog(LOG_ERR, "Failed to read rain sensor (GPIO%d)", RAIN_SENSOR_PIN);
    return val;
}

/* ------------------------------------------------------------------ */
/* Debounce                                                            */
/* ------------------------------------------------------------------ */
static int debounce(int sensor_val, int expected_val)
{
    if (sensor_val == expected_val)
        return 1;
    if (sensor_val < expected_val)
        return 0;
    return -1; /* invalid read */
}

/* ------------------------------------------------------------------ */
/* Motor control                                                       */
/* ------------------------------------------------------------------ */
static void motor_run(void)
{
    if (gpioWrite(MOTOR_IN1_PIN, 1) < 0)
        syslog(LOG_ERR, "Failed to set IN1 high on motor run");
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0)
        syslog(LOG_ERR, "Failed to set IN2 low on motor run");
    if (gpioPWM(MOTOR_PWM_PIN, 150) < 0)
        syslog(LOG_ERR, "Failed to set PWM high on motor run");
}

static void motor_stop(void)
{
    motor_stop();
    gpioDelay(MOTOR_ON_DURATION_S * 1000000);
    motor_off();
}

/* ------------------------------------------------------------------ */
