#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define DT_PIN 23
#define SCK_PIN 24
#define SOLENOID_PIN 17
#define WEIGHT_THRESHOLD 100
#define SOLENOID_DURATION_SEC 5
#define LOG_FILE "stock_events.txt"
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int *raw_value) {
    int retries = 0;
    int count = 0;
    int last_state = 0;
    int state = 0;
    int data = 0;
    int timeout = 0;

    while (retries < MAX_RETRIES) {
        state = gpioRead(DT_PIN);
        if (state < 0) {
            fprintf(stderr, "Error reading DT pin: %s\n", strerror(errno));
            retries++;
            gpioDelay(10000);
            continue;
        }

        if (state == 1) {
            data |= 1 << count;
            count++;
            if (count >= 7) {
                data &= 0x7F;
                count = 0;
            }
        } else if (state == 0) {
            data &= ~(1 << count);
            count = 0;
        }

        gpioDelay(1000);
        retries++;
        timeout++;
        if (timeout > 100) {
            fprintf(stderr, "Timeout waiting for HX711 data\n");
            return -1;
        }
    }

    if (data == 0) {
        fprintf(stderr, "HX711 data read error: invalid state\n");
        return -1;
    }

    *raw_value = data;
    return 0;
}

static int activate_solenoid(int duration_sec) {
    if (gpioWrite(SOLENOID_PIN, 1) != 0) {
        fprintf(stderr, "Error activating solenoid: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(duration_sec * 1000000);
    if (gpioWrite(SOLENOID_PIN, 0) != 0) {
        fprintf(stderr, "Error deactivating solenoid: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

