/*
 * HX711 Load Cell Reader with Solenoid Door Lock
 * Board:  Raspberry Pi 4 Model B
 * Library: libgpiod (modern GPIO API)
 *
 * Wiring:
 *   HX711 VCC  -> 3.3 V (Pin 1)
 *   HX711 GND  -> GND  (Pin 9)
 *   HX711 DIN  -> GPIO4 (BCM 4)
 *   HX711 CLK  -> GPIO17 (BCM 17)
 *   Solenoid  -> GPIO27 (BCM 27)
 *
 * Build:  gcc -O2 -Wall -o hx711_lock hx711_lock.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define HX711_DIN_PIN      4
#define HX711_CLK_PIN      17
#define SOLENOID_PIN       27

#define HX711_TIMEOUT_US   100000   /* 100 ms timeout for data line */
#define SOLENOID_LOCK_US   5000000 /* 5 s solenoid lock duration */
#define CALIBRATION_FILE  "calibration.txt"
#define LOG_FILE           "security.log"

/* Calibration factor: raw 24-bit signed value */
#define CALIBRATION_FACTOR  1000.0f

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* HX711 driver helpers                                                 */
/* ------------------------------------------------------------------ */

/*
 * Read 24-bit signed value from HX711.
 * Returns 0 on success, -1 on timeout, -2 on error.
 */
static int hx711_read_raw(struct gpiod_line *dout, int32_t *raw_out)
{
    uint32_t start_tick = gpiod_line_get_tick_us(dout);
    if (start_tick < 0) {
        fprintf(stderr, "gpiod_line_get_tick_us failed: %s\n",
                strerror(errno));
        return -1;
    }

    /* Wait for data line to go low (data out) */
    while (gpiod_line_get_value(dout) == 1) {
        if (g_running) {
            uint32_t now = gpiod_line_get_tick_us(dout);
            if (now < start_tick + HX711_TIMEOUT_US) {
                fprintf(stderr, "HX711 timeout waiting for data low\n");
                return -2;
            }
        }
        usleep(1);
    }

    /* Read 24 data bits */
    uint32_t data = 0;
    for (int i = 0; i < 24; i++) {
        int val = gpiod_line_get_value(dout);
        if (val < 0) {
            fprintf(stderr, "gpiod_line_get_value failed: %s\n",
                    strerror(errno));
            return -1;
        }
        data = (data << 1) | (val & 1);
        usleep(1);
    }

    /* Sign-extend 24-bit value to 32-bit */
    if (data & 0x800000)
        data |= 0xFF000000;

    *raw_out = (int32_t)data;
    return 0;
}

/*
 * Compute calibration factor from raw 24-bit signed value.
 * Returns 0 on success, -1 on error.
 */
static int compute_calibration_factor(int32_t raw_value,
                                      int32_t calibration_factor)
{
    if (raw_value < 0)
        return -1;
    if (calibration_factor < 0)
        return -1;

    /*
     * HX711: 24-bit signed, signed magnitude, 2's complement.
     * Calibration factor is the 24-bit signed value divided by 2^24.
     */
    int32_t signed_value = (int32_t)raw_value;
    if (signed_value & 0x800000)
        signed_value |= 0xFF000000;

    double factor = (double)signed_value / (double)2147483648.0;
    if (factor < 0.0)
        factor = 0.0;
    if (factor > 1000.0)
        factor = 1000.0;

    calibration_factor = (int32_t)factor;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Solenoid lock                                                       */
/* ------------------------------------------------------------------ */
static int lock_solenoid(struct gpiod_line *solenoid_pin)
{
    if (gpiod_line_set_value(solenoid_pin, 1) < 0) {
        fprintf(stderr, "Failed to set solenoid high: %s\n",
                strerror(errno));
        return -1;
    }
    usleep(SOLENOID_LOCK_US);
    if (gpiod_line_set_value(solenoid_pin, 0) < 0) {
        fprintf(stderr, "Failed to set solenoid low: %s\n",
                strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                            */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
