/*
 * Read 24-bit signed value from HX711.
 * Returns 0 on success, -1 on timeout, -2 on error.
 */
static int hx711_read_raw(struct gpiod_line *dout, int32_t *raw_out)
{
    uint32_t start_tick = gpiod_line_get_tick_us(dout);
    if (start_tick < 0) {
        fprintf(stderr, "gpiod_line_get_tick_us failed: %s\n",
                strerror(errno));
        return -1;
    }

    /* Wait for data line to go low (data out) */
    while (gpiod_line_get_value(dout) == 1) {
        if (g_running) {
            uint32_t now = gpiod_line_get_tick_us(dout);
            if (now < start_tick + HX711_TIMEOUT_US) {
                fprintf(stderr, "HX711 timeout waiting for data low\n");
                return -2;
            }
        }
        usleep(1);
    }

    /* Read 24 data bits */
    uint32_t data = 0;
    for (int i = 0; i < 24; i++) {
        int val = gpiod_line_get_value(dout);
        if (val < 0) {
            fprintf(stderr, "gpiod_line_get_value failed: %s\n",
                    strerror(errno));
            return -1;
        }
        data = (data << 1) | (val & 1);
        usleep(1);
    }

    /* Sign-extend 24-bit value to 32-bit */
    if (data & 0x800000)
        data |= 0xFF000000;

    *raw_out = (int32_t)data;
    return 0;
}

/*
 * Compute calibration factor from raw 24-bit signed value.
 * Returns 0 on success, -1 on error.
 */
static int compute_calibration_factor(int32_t raw_value,
                                      int32_t calibration_factor)
{
    if (raw_value < 0)
        return -1;
    if (calibration_factor < 0)
        return -1;

    /*
     * HX711: 24-bit signed, signed magnitude, 2's complement.
     * Calibration factor is the 24-bit signed value divided by 2^24.
