    int32_t signed_value = (int32_t)raw_value;
    if (signed_value & 0x800000)
        signed_value |= 0xFF000000;

    double factor = (double)signed_value / (double)2147483648.0;
    if (factor < 0.0)
        factor = 0.0;
    if (factor > 1000.0)
        factor = 1000.0;

    calibration_factor = (int32_t)factor;
    return 0;
}

