/*
 * Raspberry Pi 3 Model B+ – IR obstacle avoidance sensor + relay control
 *
 * Wiring:
 *   KY-022 VCC  -> 3.3 V (Pin 1)
 *   KY-022 GND  -> GND  (Pin 9)
 *   KY-022 OUT  -> GPIO16 (BCM 16)
 *   Songle SRD-05VDC-SL VCC -> 3.3 V (Pin 1)
 *   Songle SRD-05VDC-SL GND -> GND  (Pin 9)
 *   Songle SRD-05VDC-SL OUT -> GPIO20 (BCM 20)
 *
 * The KY-022 is active-low: a LOW reading indicates an obstacle.
 * The relay module is active-high: a LOW reading on the relay input
 * indicates the relay should switch to the opposite state.
 *
 * Build:  gcc -O2 -Wall -Wextra -o obstacle_relay obstacle_relay.c -lpigpio -lrt
 * Run:    sudo ./obstacle_relay
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_GPIO      16
#define RELAY_GPIO       20
#define LOG_FILE         "relay_events.log"
#define POLL_DELAY_US    100000   /* 100 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(const char *event)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S%z", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return;
    }

    fprintf(fp, "%s: %s\n", ts, event);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                         */
/* ------------------------------------------------------------------ */
static int gpio_init(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_GPIO);
        return -1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY_GPIO);
        return -1;
    }

    /* Ensure relay starts OFF */
    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialise relay state\n");
        return -1;
    }

    return 0;
}

static int gpio_read_sensor(int gpio)
{
    int v = gpioRead(gpio);
    if (v < 0) {
        fprintf(stderr, "gpioRead failed on GPIO%d\n", gpio);
        return -1;
    }
    return v;
}

static void gpio_write_relay(int gpio, int state)
{
    if (gpioWrite(gpio, state) != 0) {
        fprintf(stderr, "gpioWrite failed on GPIO%d\n", gpio);
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpio_init() != 0) {
        return EXIT_FAILURE;
    }

    printf("Monitoring obstacle sensor on GPIO%d and relay on GPIO%d.\n",
           SENSOR_GPIO, RELAY_GPIO);
    printf("Logging to %s. Press Ctrl+C to exit.\n", LOG_FILE);

    int relay_state = 0;   /* OFF */
    int sensor_state = 0;  /* LOW = obstacle */

    while (g_running) {
        int sensor_val = gpio_read_sensor(SENSOR_GPIO);
        if (sensor_val < 0) {
            /* Sensor read error – log and continue */
            log_event("Sensor read error");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* KY-022 is active-low: LOW = obstacle */
        if (sensor_val == 0) {
            relay_state = !relay_state;
            if (gpio_write_relay(RELAY_GPIO, relay_state) != 0) {
                log_event("Relay write failed");
            }
            log_event(relay_state ? "Relay ON" : "Relay OFF");
        }

        sensor_state = sensor_val;
        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown */
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

