#include <pigpio.h>

#define PIR_SENSOR_PIN 17
#define BUZZER_PIN 18
#define LOG_FILE "motion_log.txt"
#define BUZZER_DURATION_US 2000000  /* 2 seconds in microseconds */
#define POLL_INTERVAL_US 100000     /* 100 ms */

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int log_motion(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s - Motion detected\n", timestamp) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int activate_buzzer(void)
{
    if (gpioWrite(BUZZER_PIN, 1) != 0) {
        fprintf(stderr, "Failed to turn on buzzer: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void deactivate_buzzer(void)
{
    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Failed to turn off buzzer: %s\n", strerror(errno));
    }
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return -1;
    }

    if (gpioSetMode(PIR_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set PIR sensor pin mode: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set buzzer pin mode: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise buzzer state: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup(void)
{
    deactivate_buzzer();
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int pir_value = gpioRead(PIR_SENSOR_PIN);
        if (pir_value < 0) {
            fprintf(stderr, "Failed to read PIR sensor: %s\n", strerror(errno));
            break;
        }

        if (pir_value == 1) {
            printf("Motion detected!\n");
            if (log_motion() != 0) {
                fprintf(stderr, "Failed to log motion event.\n");
            }
            if (activate_buzzer() != 0) {
                fprintf(stderr, "Failed to activate buzzer.\n");
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    cleanup();
    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

