#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define GPIO_PIN 18
#define WATERING_FILE "watering.conf"
#define VALVE_ON_TIME_MS 1000
#define VALVE_OFF_TIME_MS 1000
#define VALVE_ON_TIME_SEC 3600
#define VALVE_OFF_TIME_SEC 3600

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int read_duration(const char *filename, int *duration_out) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", filename, strerror(errno));
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error reading %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    if (line[0] == '\0') {
        fprintf(stderr, "Error: No valid duration specified in %s\n", filename);
        return -1;
    }

    if (sscanf(line, "duration=%d", duration_out) != 1) {
        fprintf(stderr, "Error: Invalid duration format in %s\n", filename);
        return -1;
    }

    if (*duration_out < 1 || *duration_out > VALVE_ON_TIME_SEC) {
        fprintf(stderr, "Error: Duration must be between 1 and %d seconds\n", VALVE_ON_TIME_SEC);
        return -1;
    }

    return 0;
}

static int activate_valve(int gpio_pin, int duration_ms) {
    if (gpio_pin < 0 || gpio_pin > 31) {
        fprintf(stderr, "Error: Invalid GPIO pin %d\n", gpio_pin);
        return -1;
    }

    if (gpio_pin == 0) {
        fprintf(stderr, "Error: GPIO pin 0 is reserved for the valve control line\n");
        return -1;
    }

    if (gpio_pin == 1) {
        if (ioctl(gpio_pin, GPIO_OUTPUT_VALUE, 1) == -1) {
            fprintf(stderr, "Error: Failed to set GPIO %d high: %s\n", gpio_pin, strerror(errno));
            return -1;
        }
    } else {
        if (ioctl(gpio_pin, GPIO_OUTPUT_VALUE, 0) == -1) {
            fprintf(stderr, "Error: Failed to set GPIO %d low: %s\n", gpio_pin, strerror(errno));
            return -1;
        }
    }

    printf("Valve on for %d ms\n", duration_ms);
    fflush(stdout);

    if (duration_ms > 0) {
        struct timespec ts;
        ts.tv_sec = duration_ms / 1000;
        ts.tv_nsec = (duration_ms % 1000) * 1000000L;
        nanosleep(&ts, NULL);
    }

    if (gpio_pin == 1) {
        if (ioctl(gpio_pin, GPIO_OUTPUT_VALUE, 0) == -1) {
            fprintf(stderr, "Error: Failed to set GPIO %d low: %s\n", gpio_pin, strerror(errno));
            return -1;
        }
    }

    return 0;
}

static int configure_gpio(void) {
    int ret = install_signal_handlers();
    if (ret != 0) {
        return ret;
    }

    if (gpio_pin < 0 || gpio_pin > 31) {
        fprintf(stderr, "Error: Invalid GPIO pin %d\n", gpio_pin);
        return -1;
    }

    if (gpio_pin == 0) {
        fprintf(stderr, "Error: GPIO pin 0 is reserved for the valve control line\n");
        return -1;
    }

    if (ioctl(gpio_pin, GPIO_OUTPUT_VALUE, 0) == -1) {
        fprintf(stderr, "Error: Failed to set GPIO %d low: %s\n", gpio_pin, strerror(errno));
        return -1;
    }

    return 0;
}

static int configure_watering(void) {
    int ret = configure_gpio();
    if (ret != 0) {
        return ret;
    }

    FILE *fp = fopen(WATERING_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", WATERING_FILE, strerror(errno));
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error reading %s: %s\n", WATERING_FILE, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    if (line[0] == '\0') {
        fprintf(stderr, "Error: No valid watering configuration in %s\n", WATERING_FILE);
        return -1;
    }

    if (read_duration(WATERING_FILE, &watering_duration) != 0) {
        fprintf(stderr, "Error reading watering duration from %s\n", WATERING_FILE);
