/*
 * Door Lock Control using Servo API (libgpiod)
 * Board: Raspberry Pi (GPIO18=Servo, GPIO21=Lock, GPIO22=Unlock)
 *
 * Build: gcc -O2 -Wall -o door_lock door_lock.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define SERVO_PIN      18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

#define SERVO_MIN_US   500   /* 500 µs = 0°  */
#define SERVO_MAX_US   2500  /* 2500 µs = 180° */
#define DEBOUNCE_MS    100

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void print_status(const char *msg)
{
    printf("[%s] %s\n", msg, msg ? "OK" : "ERROR");
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lock_line = NULL;
    struct gpiod_line *unlock_line = NULL;
    int ret = EXIT_FAILURE;

    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the servo line (BCM 18) */
    lock_line = gpiod_chip_get_line(chip, SERVO_PIN);
    if (!lock_line) {
        perror("gpiod_chip_get_line (lock)");
        goto cleanup;
    }

    /* Get the unlock line (BCM 22) */
    unlock_line = gpiod_chip_get_line(chip, UNLOCK_BUTTON_PIN);
    if (!unlock_line) {
        perror("gpiod_chip_get_line (unlock)");
        goto cleanup;
    }

    /* Request lock line as output, initial LOW */
    if (gpiod_line_request_output(lock_line, "door_lock", 0) < 0) {
        perror("gpiod_line_request_output (lock)");
        goto cleanup;
    }

    /* Request unlock line as output, initial HIGH */
    if (gpiod_line_request_output(unlock_line, "door_lock", 1) < 0) {
        perror("gpiod_line_request_output (unlock)");
        goto cleanup;
    }

    /* Request both lines as input with pull-up */
    if (gpiod_line_request_input_flags(lock_line, "door_lock",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("gpiod_line_request_input_flags (lock)");
        goto cleanup;
    }

    if (gpiod_line_request_input_flags(unlock_line, "door_lock",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("gpiod_line_request_input_flags (unlock)");
        goto cleanup;
    }

    printf("Door lock control started. Press Ctrl+C to exit.\n");

    while (running) {
        int lock_val = gpiod_line_get_value(lock_line);
        if (lock_val < 0) {
            perror("gpiod_line_get_value (lock)");
            break;
        }

        /* Active-low: 0 = pressed, 1 = released */
        if (lock_val == 0) {
            /* Lock button pressed: set servo to 0° */
            if (gpiod_line_set_value(lock_line, 0) < 0) {
                perror("gpiod_line_set_value (lock)");
                break;
            }
            print_status("Lock button pressed (servo 0°)");

            /* Debounce: wait DEBOUNCE_MS, then check again */
            usleep(DEBOUNCE_MS * 1000);
            lock_val = gpiod_line_get_value(lock_line);
            if (lock_val < 0) {
                perror("gpiod_line_get_value (lock)");
                break;
            }
            if (lock_val == 0) {
                /* Lock button released: set servo to 180° */
                if (gpiod_line_set_value(lock_line, 1) < 0) {
                    perror("gpiod_line_set_value (lock)");
                    break;
                }
                print_status("Lock button released (servo 180°)");
            }
        }

        int unlock_val = gpiod_line_get_value(unlock_line);
        if (unlock_val < 0) {
            perror("gpiod_line_get_value (unlock)");
            break;
        }

        if (unlock_val == 0) {
            /* Unlock button pressed: set servo to 2000° */
            if (gpiod_line_set_value(unlock_line, 1) < 0) {
                perror("gpiod_line_set_value (unlock)");
                break;
            }
            print_status("Unlock button pressed (servo 2000°)");

            /* Debounce: wait DEBOUNCE_MS, then check again */
            usleep(DEBOUNCE_MS * 1000);
            unlock_val = gpiod_line_get_value(unlock_line);
            if (unlock_val < 0) {
                perror("gpiod_line_get_value (unlock)");
                break;
            }
            if (unlock_val == 0) {
                /* Unlock button released: set servo to 0° */
                if (gpiod_line_set_value(unlock_line, 0) < 0) {
                    perror("gpiod_line_set_value (unlock)");
                    break;
                }
                print_status("Unlock button released (servo 0°)");
            }
        }

        usleep(10000); /* 10 ms poll interval */
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure servo is in safe position before releasing */
    if (lock_line) {
        gpiod_line_set_value(lock_line, 1);
        gpiod_line_release(lock_line);
    }
    if (unlock_line) {
        gpiod_line_set_value(unlock_line, 1);
        gpiod_line_release(unlock_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Door lock control stopped.\n");
    return ret;
}

