    if (gpioSetMode(MOTOR2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", MOTOR2_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(MOTOR1_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO %d\n", MOTOR1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(MOTOR2_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO %d\n", MOTOR2_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(MOTOR1_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise GPIO %d low\n", MOTOR1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(MOTOR2_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise GPIO %d low\n", MOTOR2_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void stop_motor(int pin) {
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Warning: failed to stop GPIO %d\n", pin);
    }
}

static void pulse_motor(int pin, int duration_ms) {
    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Warning: failed to set GPIO %d high\n", pin);
        return;
    }
    gpioDelay(duration_ms * 1000);
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Warning: failed to set GPIO %d low\n", pin);
    }
}

static void cleanup(void) {
    stop_motor(MOTOR1_PIN);
    stop_motor(MOTOR2_PIN);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Haptic feedback system started. Press Ctrl+C to exit.\n");

    while (running) {
        pulse_motor(MOTOR1_PIN, PULSE_DURATION_MS);
        gpioDelay(LOOP_DELAY_MS * 1000);

        pulse_motor(MOTOR2_PIN, PULSE_DURATION_MS);
        gpioDelay(LOOP_DELAY_MS * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

