/*
 * sound_alarm.c — sound-triggered alarm for Raspberry Pi 5
 *
 * Build:  gcc -O2 -Wall -Wextra -o sound_alarm sound_alarm.c -lrt -lpthread
 * Run:    ./sound_alarm [sound_sensor|alarm_node]
 *
 * Sound-triggered alarm on GPIO17 (BCM) with ZeroMQ alert publishing.
 *
 * Wiring:
 *   LM393  digital output  -> GPIO17 (BCM)
 *   LED    anode           -> GPIO27 (BCM)
 *   GND    -> GND
 *   VCC    -> 3.3 V (or 5 V)
 *
 * The sound sensor mode polls the LM393 every 10 ms and treats a
 * logic 0 as a sound event.  The alarm_node mode subscribes to
 * tcp://localhost:5555 and lights the LED for 1 s upon receiving
 * a message on the topic SOUND_ALERTS.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>
#include <pthread.h>
#include <pthread.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/select.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <linux/gpio.h>

#define SOUND_SENSOR_PIN  17
#define ALARM_LED_PIN     27
#define ZMQ_PORT          5555
#define ZMQ_HOST          "localhost"
#define ZMQ_TOPIC         "SOUND_ALERTS"
#define POLL_TIMEOUT_MS   10

/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */

/*
 * Read the LM393 digital output.
 * Returns 0 on a sound event (logic 0), -1 on error.
 */
static int read_sound_sensor(void)
{
    int val = gpio_get_value(SOUND_SENSOR_PIN);
    if (val < 0) {
        fprintf(stderr, "gpio_get_value(%d) failed: %s\n",
                SOUND_SENSOR_PIN, strerror(errno));
        return -1;
    }
    return (val == 0) ? 0 : -1;
}

/* ------------------------------------------------------------------ */

/*
 * Publish a ZeroMQ message on the topic.
 * Returns 0 on success, -1 on error.
 */
static int publish_message(const char *topic, const char *message)
{
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        perror("socket");
        return -1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port   = htons(ZMQ_PORT);
    if (inet_pton(AF_INET, ZMQ_HOST, &addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid address %s\n", ZMQ_HOST);
        close(sock);
        return -1;
    }

    char buf[1024];
    size_t len = snprintf(buf, sizeof(buf), "%s:%s", topic, message);
    if (len < 0 || (size_t)len >= sizeof(buf)) {
        fprintf(stderr, "Message too long\n");
        close(sock);
        return -1;
    }

    ssize_t n = sendto(sock, buf, (size_t)len, 0,
                       (struct sockaddr *)&addr, sizeof(addr));
    if (n < 0) {
        perror("sendto");
        close(sock);
        return -1;
    }

    if (close(sock) < 0) {
        perror("close");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */

static void *sound_sensor_thread(void *arg)
{
    (void)arg;
    int sound_event = -1;

    while (g_running) {
        int val = read_sound_sensor();
        if (val < 0) {
            fprintf(stderr, "read_sound_sensor failed; continuing\n");
            usleep(POLL_TIMEOUT_MS * 1000);
            continue;
        }

        if (val == 0) {
            sound_event = 1;
            break;
        }

        usleep(POLL_TIMEOUT_MS * 1000);
    }

    if (sound_event == 0)
        fprintf(stderr, "No sound event detected; exiting.\n");
    return NULL;
}

/* ------------------------------------------------------------------ */

static void alarm_node_thread(void *arg)
{
    (void)arg;
    int alarm_active = 0;

    while (g_running) {
        int val = read_sound_sensor();
        if (val < 0) {
            fprintf(stderr, "read_sound_sensor failed; continuing\n");
            usleep(POLL_TIMEOUT_MS * 1000);
            continue;
        }

        if (val == 0) {
            alarm_active = 1;
            break;
        }

        usleep(POLL_TIMEOUT_MS * 1000);
    }

    if (alarm_active) {
        printf("Alarm activated.\n");
        fflush(stdout);

        if (gpio_set_mode(ALARM_LED_PIN, OUTPUT) < 0) {
            perror("gpio_set_mode(ALARM_LED)");
            return;
        }
        if (gpio_write(ALARM_LED_PIN, 1) < 0) {
            perror("gpio_write(ALARM_LED)");
            return;
        }
        usleep(1000000);
        if (gpio_write(ALARM_LED_PIN, 0) < 0) {
            perror("gpio_write(ALARM_LED)");
            return;
        }
        printf("Alarm deactivated.\n");
        fflush(stdout);
    }
    return;
}

/* ------------------------------------------------------------------ */

int main(int argc, char *argv[])
{
    if (argc != 2) {
        fprintf(stderr, "Usage: %s [sound_sensor|alarm_node]\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *mode = argv[1];

    install_signal_handlers();

    /* --- GPIO setup --- */
    struct gpio_chip *chip = gpiochip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiochip_open");
        return EXIT_FAILURE;
    }

    int led_pin = gpio_request_output(ALARM_LED_PIN, "alarm_led", 0);
    if (led_pin < 0) {
        perror("gpio_request_output(ALARM_LED)");
        gpiochip_close(chip);
        return EXIT_FAILURE;
    }

    int sound_pin = gpio_request_input(SOUND_SENSOR_PIN, "sound_sensor", 0);
    if (sound_pin < 0) {
        perror("gpio_request_input(SOUND_SENSOR)");
        gpiochip_close(chip);
        return EXIT_FAILURE;
    }

    /* --- ZeroMQ setup --- */
    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port   = htons(ZMQ_PORT);

    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        perror("socket");
        gpiochip_close(chip);
        return EXIT_FAILURE;
    }

    if (setsockopt(sock, SOL_SOCKET, SO_REUSEADDR, &server_addr,
                   sizeof(server_addr)) < 0) {
        perror("setsockopt(SO_REUSEADDR)");
        close(sock);
        gpiochip_close(chip);
        return EXIT_FAILURE;
    }

    if (bind(sock, (struct sockaddr *)&server_addr,
             sizeof(server_addr)) < 0) {
        perror("bind");
        close(sock);
        gpiochip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Listening for sound events on GPIO%d (BCM)...\n", SOUND_SENSOR_PIN);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* --- Sound sensor thread --- */
    pthread_t sound_thread;
    if (pthread_create(&sound_thread, NULL, sound_sensor_thread, NULL) != 0) {
        perror("pthread_create(sound_sensor)");
        close(sock);
        gpiochip_close(chip);
        return EXIT_FAILURE;
    }

    /* --- Alarm node thread --- */
    pthread_t alarm_thread;
    if (pthread_create(&alarm_thread, NULL, alarm_node_thread, NULL) != 0) {
        perror("pthread_create(alarm_node)");
        pthread_join(sound_thread, NULL);
        close(sock);
        gpiochip_close(chip);
        return EXIT_FAILURE;
    }

    /* --- Main loop --- */
    while (g_running) {
        int val = read_sound_sensor();
        if (val < 0) {
            fprintf(stderr, "read_sound_sensor failed; exiting.\n");
            break;
        }

        if (val == 0) {
            printf("Sound detected! Activating alarm.\n");
            fflush(stdout);

            if (gpio_set_mode(ALARM_LED_PIN, OUTPUT) < 0) {
                perror("gpio_set_mode(ALARM_LED)");
                break;
            }
            if (gpio_write(ALARM_LED_PIN, 1) < 0) {
                perror("gpio_write(ALARM_LED)");
                break;
            }
            usleep(1000000);
            if (gpio_write(ALARM_LED_PIN, 0) < 0) {
                perror("gpio_write(ALARM_LED)");
                break;
            }
            printf("Alarm deactivated.\n");
            fflush(stdout);
        }

        usleep(POLL_TIMEOUT_MS * 1000);
    }

    /* --- Cleanup --- */
    pthread_join(sound_thread, NULL);
    pthread_join(alarm_thread, NULL);

    gpio_set_mode(ALARM_LED_PIN, INPUT);
    gpio_set_mode(SOUND_SENSOR_PIN, INPUT);
    gpiochip_close(chip);

    printf("Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

