/*
 * BH1750FVI ambient-light sensor reader for Raspberry Pi 3 Model B+
 * Uses /dev/i2c-1 single-device mode (no external driver needed).
 * Broadcasts a UDP multicast packet containing sensor IDs and lux values.
 *
 * Build:  gcc -O2 -Wall -Wextra -o bh1750_multicast bh1750_multicast.c
 * Run:    sudo ./bh1750_multicast
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR    0x23
#define NUM_SENSORS    4
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define SAMPLE_DELAY_US 180000   /* 180 ms between sensor starts */
#define LOOP_DELAY_US   1000000  /* 1 s between acquisitions */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Open a single I2C device descriptor.
 * Returns file descriptor 0–2 on success, -1 on failure.
 */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * Send a 16-bit command to the BH1750.
 * Returns 0 on success, -1 on failure.
 */
static int bh1750_write_cmd(int fd, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "bh1750_write_cmd: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit result from the BH1750.
 * Returns 0 on success, -1 on failure.
 */
static int bh1750_read_result(int fd, uint16_t *out)
{
    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
