/*
 * Raspberry Pi Zero W – Honeywell AWM7300V mass airflow sensor logger
 *
 * Wiring:
 *   AWM7300V VCC  -> 3.3 V (pin 1)
 *   AWM7300V GND  -> GND  (pin 9)
 *   AWM7300V SCL  -> GPIO2 / I2C1 SCL (pin 5)
 *   AWM7300V SDA  -> GPIO3 / I2C1 SDA (pin 3)
 *
 * Build:  gcc -O2 -Wall -Wextra -o airflow_logger airflow_logger.c
 * Run:    sudo ./airflow_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SENSOR_ADDR    0x00
#define LOG_FILE       "airflow_log.txt"
#define RETRY_COUNT    3
#define RETRY_DELAY_MS 100
#define SAMPLE_PERIOD_S 1

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Write a zero-length I2C command to the sensor.
 * Returns 0 on success, -1 on failure.
 */
static int sensor_write_zero(int fd)
{
    uint8_t cmd[1] = {0x00};
    ssize_t ret = write(fd, cmd, 1);
    if (ret != 1) {
        fprintf(stderr, "write(0x%02X): %s\n", SENSOR_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read two bytes from the sensor.
 * Returns 0 on success, -1 on failure.
 */
static int sensor_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t ret = read(fd, buf, len);
    if (ret != (ssize_t)len) {
        fprintf(stderr, "read: expected %zu bytes, got %zd: %s\n",
                len, ret, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Convert 14-bit flow value (MSB first) to SLPM.
 * Flow value is masked to the range 0–999, then scaled to SLPM.
 */
static float convert_flow_to_slpm(uint16_t raw)
{
    uint16_t mask = 0x3FFF;
    uint16_t flow = (raw & mask) << 2;
    return (float)flow / 1000.0f;
}

/*
 * Log a timestamped entry to the log file.
 * Returns 0 on success, -1 on failure.
 */
static int log_entry(const char *filename, float flow_slpm)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time(): %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, %.2f SLPM\n", ts, flow_slpm) < 0) {
        fprintf(stderr, "fprintf: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the sensor address */
    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                SENSOR_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("AWM7300V logger started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD_S);
    printf("Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        uint8_t buf[2];
        if (sensor_write_zero(i2c_fd) != 0) {
            fprintf(stderr, "Sensor write failed; retrying...\n");
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        if (sensor_read_bytes(i2c_fd, buf, 2) != 0) {
            fprintf(stderr, "Sensor read failed; retrying...\n");
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        uint16_t raw = (buf[0] << 8) | buf[1];
        float slpm = convert_flow_to_slpm(raw);

        if (log_entry(LOG_FILE, slpm) != 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        printf("Flow: %.2f SLPM\n", slpm);
        fflush(stdout);

        /* Sleep SAMPLE_PERIOD_S seconds, but wake early on signal */
        for (int i = 0; i < SAMPLE_PERIOD_S && g_running; i++) {
            sleep(1);
        }
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    close(i2c_fd);
    return EXIT_SUCCESS;
}

