 *
 * Wiring:
 *   AS7341 SDA -> GPIO2 (I2C1 SDA, pin 3)
 *   AS7341 SCL -> GPIO3 (I2C1 SCL, pin 5)
 *   AS7341 VDD -> 3.3 V
 *   AS7341 GND -> GND
 *
 * Build:  gcc -O2 -Wall -o as7341 as7341.c -lm
 * Run:    ./as7341   (requires i2c-1 access)
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define LOG_FILE       "spectral_log.csv"
#define SAMPLE_PERIOD  5
#define MAX_CHANNELS   10
#define CFG6_REG       0x0E
#define ENABLE_REG     0x0F
#define PON_REG        0x10
#define SMUX_REG       0x11
#define CFG6_VAL       0x01
#define PON_ON         0x01

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, out, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int sensor_init(void)
{
    /* Verify sensor identity register */
    uint8_t id = 0;
    if (i2c_read_byte(g_i2c_fd, CFG6_REG, &id) < 0)
        return -1;
    if (id != 0x00) {
        fprintf(stderr, "AS7341 not detected (ID=0x%02X, expected 0x00)\n", id);
        return -1;
    }

    /* Enable power (PON = 1) */
    if (i2c_write_byte(g_i2c_fd, ENABLE_REG, PON_ON) < 0)
        return -1;

    /* Configure spectral multiplexing (SMUX) */
    if (i2c_write_byte(g_i2c_fd, CFG6_REG, CFG6_VAL) < 0)
        return -1;

    /* Enable spectral measurement (clear and NIR channels) */
    if (i2c_write_byte(g_i2c_fd, ENABLE_REG, PON_ON | 0x03) < 0)
        return -1;

    /* Allow sensor to stabilize */
    usleep(100000);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read spectral data                                                   */
/* ------------------------------------------------------------------ */
static int read_spectral_data(uint16_t *f1, uint16_t *f2,
                              uint16_t *f3, uint16_t *f4,
                              uint16_t *f5, uint16_t *f6,
                              uint16_t *f7, uint16_t *f8,
                              uint16_t *clear, uint16_t *nir)
{
    uint8_t buf[8];
    if (i2c_read_word(g_i2c_fd, CFG6_REG, buf) < 0)
        return -1;

    *f1 = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    *f2 = (uint16_t)buf[2] | ((uint16_t)buf[3] << 8);
    *f3 = (uint16_t)buf[4] | ((uint16_t)buf[5] << 8);
    *f4 = (uint16_t)buf[6] | ((uint16_t)buf[7] << 8);

    *clear = (uint16_t)buf[8] | ((uint16_t)buf[9] << 8);
    *nir  = (uint16_t)buf[10] | ((uint16_t)buf[11] << 8);

    return 0;
}

/* ------------------------------------------------------------------ */
/* Lux approximation                                                     */
/* ------------------------------------------------------------------ */
static double lux_from_spectral(uint16_t f1, uint16_t f2,
                                uint16_t f3, uint16_t f4,
                                uint16_t f5, uint16_t f6,
                                uint16_t f7, uint16_t f8,
                                uint16_t clear, uint16_t nir)
{
    double sum = 0.0;
    for (int i = 0; i < MAX_CHANNELS; i++) {
        double val = (double)f1 + (double)f2 + (double)f3 +
                     (double)f4 + (double)f5 + (double)f6 +
                     (double)f7 + (double)f8 +
                     (double)clear + (double)nir;
        sum += val;
    }
    return sum / (double)MAX_CHANNELS;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, uint16_t f1, uint16_t f2,
                    uint16_t f3, uint16_t f4,
                    uint16_t f5, uint16_t f6,
                    uint16_t f7, uint16_t f8,
                    uint16_t clear, uint16_t nir,
                    double lux)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,F1=%u,F2=%u,F3=%u,F4=%u,F5=%u,F6=%u,F7=%u,F8=%u,Clear=%u,NIR=%u,Lux=%f\n",
                ts, f1, f2, f3, f4, f5, f6, f7, f8, clear, nir, lux) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, 0x1F) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x1F failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (sensor_init() < 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(g_log_fp, "# AS7341 10-Channel Light/Color Sensor Log\n");
    fprintf(g_log_fp, "# Timestamp,F1,F2,F3,F4,F5,F6,F7,F8,Clear,NIR,Lux\n");
    fflush(g_log_fp);

    printf("AS7341 sensor initialized. Logging to %s every %d s. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_PERIOD);

    while (g_running) {
        uint16_t f1, f2, f3, f4, f5, f6, f7, f8, clear, nir;
        if (read_spectral_data(&f1, &f2, &f3, &f4, &f5, &f6, &f7, &f8,
                               &clear, &nir) < 0) {
            fprintf(stderr, "Sensor read error; continuing.\n");
        } else {
            double lux = lux_from_spectral(f1, f2, f3, f4, f5, f6, f7, f8,
                                            clear, nir);
            if (log_data(g_log_fp, f1, f2, f3, f4, f5, f6, f7, f8,
                         clear, nir, lux) < 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        }
        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

