                              uint16_t *f3, uint16_t *f4,
                              uint16_t *f5, uint16_t *f6,
                              uint16_t *f7, uint16_t *f8,
                              uint16_t *clear, uint16_t *nir)
{
    uint8_t buf[8];
    if (i2c_read_word(g_i2c_fd, CFG6_REG, buf) < 0)
        return -1;

    *f1 = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    *f2 = (uint16_t)buf[2] | ((uint16_t)buf[3] << 8);
    *f3 = (uint16_t)buf[4] | ((uint16_t)buf[5] << 8);
    *f4 = (uint16_t)buf[6] | ((uint16_t)buf[7] << 8);

    *clear = (uint16_t)buf[8] | ((uint16_t)buf[9] << 8);
    *nir  = (uint16_t)buf[10] | ((uint16_t)buf[11] << 8);

