/*
 * seismic_logger.c
 *
 * Reads tri-axial acceleration data from an Omron D7S seismic sensor
 * over I2C (/dev/i2c-1) and logs timestamped X, Y, Z values to
 * seismic_data.csv.  Optionally writes error messages to
 * seismic_error.log.
 *
 * Build:  gcc -O2 -Wall -Wextra -o seismic_logger seismic_logger.c
 * Run:    ./seismic_logger [-a <address>] [-i <interval_s>] [-f <filename>]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define I2C_ADDR       0x10
#define CSV_FILE       "seismic_data.csv"
#define ERROR_FILE     "seismic_error.log"
#define MAX_RETRIES    3
#define RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_S 1

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a timestamped message to the error log. */
static void log_error(const char *msg)
{
    FILE *fp = fopen(ERROR_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open %s: %s\n", ERROR_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d: %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    } else {
        fprintf(fp, "timestamp error: %s\n", msg);
    }
    fclose(fp);
}

/*
 * Read a 16-bit big-endian value from the D7S.
 * Returns 0 on success, -1 on error.
 */
static int d7s_read_accel(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        log_error("I2C read failed");
        return -1;
    }
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

/*
 * Write a CSV record to the CSV file.
 * Returns 0 on success, -1 on error.
 */
static int write_csv(const char *filename, int16_t x, int16_t y, int16_t z)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        log_error("Cannot open CSV file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%d,%d,%d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    } else {
        fprintf(fp, "%s,%d,%d,%d\n",
                gmtime_r(&t, &tm), x, y, z);
    }
    fclose(fp);
    return 0;
}

int main(int argc, char *argv[])
{
    int addr = I2C_ADDR;
    int i_interval = SAMPLE_INTERVAL_S;
    int f_filename = CSV_FILE;
    int opt;

    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                addr = (int)strtol(optarg, NULL, 0);
                break;
            case 'i':
                i_interval = (int)strtol(optarg, NULL, 0);
                break;
            case 'f':
                f_filename = (int)strtol(optarg, NULL, 0);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a <address>] [-i <interval_s>] [-f <filename>]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    /* Signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        log_error("Cannot open I2C bus");
        return EXIT_FAILURE;
    }

    /* Acquire the I2C slave address */
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        log_error("Cannot set I2C slave address");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Seismic logger started.  I2C addr 0x%02X, interval %d s, output %s\n",
           addr, i_interval, f_filename);

    /* Main loop */
    while (g_running) {
        int16_t x, y, z;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (d7s_read_accel(fd, &x, &y, &z) == 0) {
                ok = 1;
                break;
            }
            log_error("Sensor read failed, attempt %d");
            if (attempt < MAX_RETRIES - 1) {
                usleep(RETRY_DELAY_MS * 1000);
            }
        }

        if (!ok) {
            fprintf(stderr, "Sensor read failed after %d attempts.\n", MAX_RETRIES);
            /* Sleep briefly before retrying */
            usleep(SAMPLE_INTERVAL_S * 1000);
            continue;
        }

        if (write_csv(f_filename, x, y, z) != 0) {
            fprintf(stderr, "Failed to write CSV data.\n");
        }

        /* Sleep for the configured interval, checking g_running every 100 ms */
        for (int i = 0; i < 100 && g_running; i++) {
            usleep(100000);
        }
    }

    /* Cleanup */
    close(fd);
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

