#include <netinet/in.h>
#include <arpa/inet.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR    0x23
#define BH1750_REG_ID   0x00
#define BH1750_REG_LUX  0x02
#define BH1750_REG_CTRL 0x0F

#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define MULTICAST_TTL   1

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(int fd, unsigned char reg, unsigned char val)
{
    unsigned char buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, unsigned char reg, unsigned char *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_bh1750(int fd, float *lux_out)
{
    unsigned char id = 0;
    if (i2c_read_reg(fd, BH1750_REG_ID, &id) < 0)
        return -1;
    if (id != 0x4B) {
        fprintf(stderr, "BH1750 ID mismatch: got 0x%02X, expected 0x4B\n", id);
        return -1;
    }

    unsigned char ctrl = 0;
    if (i2c_write_reg(fd, BH1750_REG_CTRL, ctrl) < 0)
        return -1;

    usleep(10000);

    unsigned char raw[2];
    if (i2c_read_reg(fd, BH1750_REG_LUX, raw) < 0)
        return -1;

    unsigned int raw_u = (raw[0] << 8) | raw[1];
    *lux_out = (float)raw_u / 65535.0f;
    return 0;
}

static int send_udp(const char *msg)
{
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        perror("socket");
        return -1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(MULTICAST_PORT);
    if (inet_pton(AF_INET, MULTICAST_ADDR, &addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid multicast address: %s\n", MULTICAST_ADDR);
        close(sock);
        return -1;
    }

    if (sendto(sock, msg, strlen(msg), 0,
               (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("sendto");
        close(sock);
        return -1;
    }

    close(sock);
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return EXIT_FAILURE;
    }

    float lux = 0.0f;
    while (g_running) {
        if (read_bh1750(fd, &lux) < 0) {
            fprintf(stderr, "Sensor read error; retrying in 1 s...\n");
            sleep(1);
            continue;
        }
        if (send_udp(fprintf("%.2f", lux)) < 0)
            fprintf(stderr, "UDP send error\n");
        sleep(1);
    }

    close(fd);
    return EXIT_SUCCESS;
}

