/*
 * AWR1642 mmWave radar data logger for Raspberry Pi 3 Model B+
 *
 * UART: /dev/ttyS0  921600 baud, 8-bit, no parity, 1-byte EOF
 * CSV:   radar_data.csv
 *
 * Reads 8-byte magic word, validates TLV payloads, extracts range/velocity
 * and writes rows to radar_data.csv.  Handles partial reads, buffer
 * overflow, and signal-driven cleanup.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/serial.h>
#include <linux/serial_reg.h>

#define UART_DEVICE      "/dev/ttyS0"
#define BAUD_RATE        921600
#define CSV_FILENAME     "radar_data.csv"
#define MAGIC_WORD_LEN   8
#define MAX_FRAME_LEN    (MAGIC_WORD_LEN + 8)
#define MAX_BUFFER_LEN   (MAX_FRAME_LEN * 10)

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                            */
/* ------------------------------------------------------------------ */

static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);
}

static int uart_init(const char *device, speed_t baud)
{
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", device, strerror(errno));
        return -1;
    }

    struct serial_port port;
    memset(&port, 0, sizeof(port));
    port.flags = 0;
    port.c_cflag = (CS8 | CLOCAL | CREAD);
    port.h_cflag = (CS8 | CLOCAL | CREAD);
    port.l_cflag = (CS8 | CLOCAL | CREAD);
    port.ispeed = baud;
    port.ospeed = baud;

    if (ioctl(fd, TIOCMGET, &port) < 0) {
        fprintf(stderr, "TIOCMGET: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (port.c_cflag & CRTSCTS) {
        port.c_cflag &= ~(CS8 | CRTSCTS);
    }

    if (port.c_cflag & PARENB) {
        port.c_cflag &= ~PARENB;
    }
    if (port.c_cflag & PARODD) {
        port.c_cflag &= ~PARODD;
    }
    if (port.c_cflag & CSTOPB) {
        port.c_cflag &= ~CSTOPB;
    }
    if (port.c_cflag & CRTSCTS) {
        port.c_cflag |= CRTSCTS;
    }

    if (ioctl(fd, TIOCMGET, &port) < 0) {
        fprintf(stderr, "TIOCMGET: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (port.ispeed != baud) {
        fprintf(stderr, "baud rate mismatch: %d vs %d\n", port.ispeed, baud);
        close(fd);
        return -1;
    }

    if (port.c_cflag & CREAD) {
        if (ioctl(fd, TIOCMGET, &port) < 0) {
            fprintf(stderr, "TIOCMGET: %s\n", strerror(errno));
            close(fd);
            return -1;
        }
        if (port.ispeed != baud) {
            fprintf(stderr, "baud rate mismatch: %d vs %d\n", port.ispeed, baud);
            close(fd);
            return -1;
        }
    }

    return fd;
}

static int uart_open(const char *device, speed_t baud)
{
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", device, strerror(errno));
        return -1;
    }

    struct serial_port port;
    memset(&port, 0, sizeof(port));
    port.flags = 0;
    port.c_cflag = (CS8 | CLOCAL | CREAD);
    port.h_cflag = (CS8 | CLOCAL | CREAD);
    port.l_cflag = (CS8 | CLOCAL | CREAD);
    port.ispeed = baud;
    port.ospeed = baud;

    if (ioctl(fd, TIOCMGET, &port) < 0) {
        fprintf(stderr, "TIOCMGET: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (port.c_cflag & CRTSCTS) {
        port.c_cflag &= ~(CS8 | CRTSCTS);
    }

    if (port.c_cflag & PARENB) {
        port.c_cflag &= ~PARENB;
    }
    if (port.c_cflag & PARODD) {
        port.c_cflag &= ~PARODD;
    }
    if (port.c_cflag & CSTOPB) {
        port.c_cflag &= ~CSTOPB;
    }
    if (port.c_cflag & CRTSCTS) {
        port.c_cflag |= CRTSCTS;
    }

    if (ioctl(fd, TIOCMGET, &port) < 0) {
        fprintf(stderr, "TIOCMGET: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (port.ispeed != baud) {
        fprintf(stderr, "baud rate mismatch: %d vs %d\n", port.ispeed, baud);
        close(fd);
        return -1;
    }

    return fd;
}

static int uart_read_frame(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            return 0;
        }
        fprintf(stderr, "read: %s\n", strerror(errno));
        return -1;
    }
    if (n == 0) {
        return 0;
    }
    return (int)n;
}

static int uart_parse_magic_word(const uint8_t *buf, size_t len,
                                 uint32_t *out_range, uint32_t *out_velocity)
{
    if (len < MAGIC_WORD_LEN) {
        return -1;
    }

    /*
     * The 8-byte magic word is little-endian.
     * The first 4 bytes are the magic word itself,
     * the next 4 bytes are padding, and the last byte is
     * the length of the payload.
     */
    uint32_t magic_word = 0;
    memcpy(&magic_word, buf, MAGIC_WORD_LEN);
    if (magic_word != 0x12345678) {
        return -1;
    }

    /*
     * The next 4 bytes are padding.
     */
    if (len < MAGIC_WORD_LEN + 4) {
        return -1;
    }

    /*
     * The last byte is the length of the payload.
     */
    uint32_t payload_len = buf[MAGIC_WORD_LEN];
    if (len < MAGIC_WORD_LEN + 4 + payload_len) {
        return -1;
    }

    /*
     * The payload is little-endian.
     */
    uint8_t *payload = buf + MAGIC_WORD_LEN;
    *out_range = payload_len;

    if (payload_len > 0) {
        *out_velocity = (uint32_t)payload[MAGIC_WORD_LEN];
    }

    return 0;
}

static int parse_frame(const uint8_t *buf, size_t len,
                       float *range, float *velocity)
{
    if (len < MAX_FRAME_LEN) {
        return -1;
    }

    /*
     * The 8-byte magic word is little-endian.
     * The first 4 bytes are the magic word itself,
     * the next 4 bytes are padding, and the last byte is
     * the length of the payload.
     */
    uint32_t magic_word = 0;
    memcpy(&magic_word, buf, MAGIC_WORD_LEN);
    if (magic_word != 0x12345678) {
        return -1;
    }

    /*
     * The next 4 bytes are padding.
     */
    if (len < MAGIC_WORD_LEN + 4) {
        return -1;
    }

