        return -1;
    }

    struct serial_port port;
    memset(&port, 0, sizeof(port));
    port.flags = 0;
    port.c_cflag = (CS8 | CLOCAL | CREAD);
    port.h_cflag = (CS8 | CLOCAL | CREAD);
    port.l_cflag = (CS8 | CLOCAL | CREAD);
    port.ispeed = baud;
    port.ospeed = baud;

