#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/select.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/ioctl.h>
#include <linux/serial.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define BUFFER_SIZE 1024
#define TIMEOUT_MS 2000
#define READ_INTERVAL_MS 500
#define MAX_DETECTIONS 100
#define MAX_LINE_LEN 256

static volatile sig_atomic_t g_running = 1;
static int g_uart_fd = -1;
static int g_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int setup_uart(const char *device, speed_t baud) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting UART attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud);
    cfsetispeed(&tty, baud);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);

    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ECHONL | ISIG);

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 0;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting UART attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_uart(int fd, char *buf, size_t len) {
    fd_set fds;
    struct timeval timeout;
    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    timeout.tv_sec = 0;
    timeout.tv_usec = TIMEOUT_MS * 1000;

    int ret = select(fd + 1, &fds, NULL, NULL, &timeout);
    if (ret < 0) {
        if (errno == EINTR) return -1;
        fprintf(stderr, "select error: %s\n", strerror(errno));
        return -1;
    }
    if (ret == 0) return -1;

    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        if (errno == EINTR) return -1;
        fprintf(stderr, "read error: %s\n", strerror(errno));
        return -1;
    }
    if (n == 0) return -1;

    return 0;
}

static int parse_line(const char *line, float *range_meters) {
    char *endptr;
    *range_meters = strtof(line, &endptr);
    if (*endptr != '\0') {
        fprintf(stderr, "Invalid range format: %s\n", line);
        return -1;
    }
    return 0;
}

static int log_data(const char *timestamp, float range_meters) {
    FILE *fp = fopen("data.log", "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", timestamp, range_meters) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    g_uart_fd = setup_uart(UART_DEVICE, BAUD_RATE);
    if (g_uart_fd < 0) {
        return 1;
    }

    printf("Radar data acquisition started. Press Ctrl+C to exit.\n");

    while (g_running) {
        char line[MAX_LINE_LEN];
        char timestamp[32];
        float range_meters;

        if (read_uart(g_uart_fd, line, sizeof(line)) == 0) {
            if (parse_line(line, &range_meters) == 0) {
                if (log_data(timestamp, range_meters) != 0) {
                    fprintf(stderr, "Error logging data.\n");
                } else {
                    printf("%s, Range: %.2f meters\n", timestamp, range_meters);
                }
            } else {
                fprintf(stderr, "Invalid range data format.\n");
            }
        } else {
            fprintf(stderr, "UART read error. Retrying...\n");
        }

        struct timespec ts;
        ts.tv_sec = READ_INTERVAL_MS / 1000;
        ts.tv_nsec = (READ_INTERVAL_MS % 1000) * 1000000L;

        struct pollfd pfd;
        pfd.fd = g_uart_fd;
        pfd.events = POLLIN;
        pfd.revents = 0;

        int ret = poll(&pfd, 1, &ts);
        if (ret < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "poll error: %s\n", strerror(errno));
            break;
        }
        if (ret == 0) continue;

        if (pfd.revents & POLLIN) {
            char line[MAX_LINE_LEN];
            char timestamp[32];
            float range_meters;

            if (read_uart(g_uart_fd, line, sizeof(line)) == 0) {
                if (parse_line(line, &range_meters) == 0) {
                    if (log_data(timestamp, range_meters) != 0) {
                        fprintf(stderr, "Error logging data.\n");
                    } else {
                        printf("%s, Range: %.2f meters\n", timestamp, range_meters);
                    }
                } else {
                    fprintf(stderr, "Invalid range data format.\n");
                }
            } else {
                fprintf(stderr, "UART read error. Retrying...\n");
            }
        }
    }

    if (g_uart_fd != -1) {
        close(g_uart_fd);
        g_uart_fd = -1;
    }
    printf("Radar data acquisition stopped.\n");
    return 0;
}

