#include <linux/serial.h>

#define SENSOR_LEFT_PIN 4
#define SENSOR_MIDDLE_PIN 17
#define SENSOR_RIGHT_PIN 27
#define UART_DEVICE "/dev/ttyAMA0"
#define BAUD_RATE B115200
#define POLL_INTERVAL_MS 100
#define API_CALL_TIMEOUT_MS 1000

static volatile sig_atomic_t program_running = 1;
static int uart_fd = -1;
static struct termios tty_options;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int init_uart(void) {
    int fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        fprintf(stderr, "Error opening UART device %s: %s\n", UART_DEVICE, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting UART attributes: %s\n", strerror(errno));
        close(fd);
