    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_lflag = 0;
    tty.c_iflag = 0;
    tty.c_oflag = 0;
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 0;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting UART attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int init_gpio(void) {
    int fd = open("/dev/gpiochip4", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    struct gpio_chip *chip = gpiochip_open(fd);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    struct gpio_line *left = gpio_chip_get_line(chip, SENSOR_LEFT_PIN);
    struct gpio_line *middle = gpio_chip_get_line(chip, SENSOR_MIDDLE_PIN);
    struct gpio_line *right = gpio_chip_get_line(chip, SENSOR_RIGHT_PIN);
    if (!left || !middle || !right) {
        fprintf(stderr, "Error getting GPIO lines: %s\n", strerror(errno));
        gpio_chip_close(chip);
        close(fd);
        return -1;
    }

    if (gpio_line_request_input(left, "ky033_left") < 0) {
        fprintf(stderr, "Error requesting left sensor line as input: %s\n", strerror(errno));
        gpio_chip_close(chip);
        close(fd);
        return -1;
    }

    if (gpio_line_request_input(middle, "ky033_middle") < 0) {
        fprintf(stderr, "Error requesting middle sensor line as input: %s\n", strerror(errno));
        gpio_line_release(left);
        gpio_chip_close(chip);
        close(fd);
        return -1;
    }

    if (gpio_line_request_input(right, "ky033_right") < 0) {
        fprintf(stderr, "Error requesting right sensor line as input: %s\n", strerror(errno));
        gpio_line_release(left);
        gpio_line_release(middle);
        gpio_chip_close(chip);
        close(fd);
        return -1;
    }

    return 0;
}

static int read_sensor(int pin) {
    int level = gpio_line_get_value(pin);
    if (level < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", pin, strerror(errno));
        return -1;
    }
    return level;
}

static void log_sensor_data(int left, int middle, int right) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Left: %d, Middle: %d, Right: %d\n", timestamp, left, middle, right);
    fflush(stdout);
}

static int send_data_to_uart(int data) {
    if (data < 0) {
        fprintf(stderr, "Error sending data to UART: %s\n", strerror(errno));
        return -1;
    }

    ssize_t bytes_written = write(uart_fd, &data, sizeof(data));
    if (bytes_written < 0) {
        fprintf(stderr, "Error writing to UART: %s\n", strerror(errno));
        return -1;
    }
    if (bytes_written == 0) {
        fprintf(stderr, "Warning: UART write returned 0 bytes\n");
    }
    return 0;
}

static void cleanup(void) {
    if (uart_fd >= 0) {
        close(uart_fd);
        uart_fd = -1;
    }
    gpio_line_release(left);
    gpio_line_release(middle);
    gpio_line_release(right);
    gpio_chip_close(NULL);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_uart() != 0) {
        return 1;
    }

    if (init_gpio() != 0) {
        close(uart_fd);
        return 1;
    }

    printf("KY-033 Tracking Sensor Monitoring System\n");
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (program_running) {
        int left = read_sensor(SENSOR_LEFT_PIN);
        int middle = read_sensor(SENSOR_MIDDLE_PIN);
        int right = read_sensor(SENSOR_RIGHT_PIN);

        if (left < 0 || middle < 0 || right < 0) {
            fprintf(stderr, "Error reading sensor data, skipping cycle.\n");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        log_sensor_data(left, middle, right);

        if (left == 0 && middle == 0 && right == 0) {
            if (send_data_to_uart(1) != 0) {
                fprintf(stderr, "Error sending data to UART.\n");
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

